window.ExtraBibleBooks=window.ExtraBibleBooks||{};window.ExtraBibleBooks["EXO"]={"book":"EXO","editions":{"hbo-source":[[1,1,"וְ⁠אֵ֗לֶּה שְׁמוֹת֙ בְּנֵ֣י יִשְׂרָאֵ֔ל הַ⁠בָּאִ֖ים מִצְרָ֑יְמָ⁠ה אֵ֣ת יַעֲקֹ֔ב אִ֥ישׁ וּ⁠בֵית֖⁠וֹ בָּֽאוּ׃","wĕ⁠ʼé֗lėh şĕ̌mwòţ֙ bĕ̇né֣y yişĕ̂ráʼé֔l ha⁠bá̇ʼi֖ym miẕĕrá֑yĕmá⁠h ʼé֣ţ yaʻàqò֔b ʼi֥yş̌ ẇ⁠béyţ֖⁠wò báֽ̇ʼẇ׃"],[1,2,"רְאוּבֵ֣ן שִׁמְע֔וֹן לֵוִ֖י וִ⁠יהוּדָֽה׃","rĕʼẇbé֣n şǐmĕʻ֔wòn léwi֖y wi⁠yhẇdáֽh׃"],[1,3,"יִשָּׂשכָ֥ר זְבוּלֻ֖ן וּ⁠בְנְיָמִֽן׃","yişá̇̂şká֥r zĕbẇlu֖n ẇ⁠bĕnĕyámiֽn׃"],[1,4,"דָּ֥ן וְ⁠נַפְתָּלִ֖י גָּ֥ד וְ⁠אָשֵֽׁר׃","dá֥̇n wĕ⁠napĕţá̇li֖y gá֥̇d wĕ⁠ʼáşéֽ̌r׃"],[1,5,"וַֽ⁠יְהִ֗י כָּל־נֶ֛פֶשׁ יֹצְאֵ֥י יֶֽרֶךְ־יַעֲקֹ֖ב שִׁבְעִ֣ים נָ֑פֶשׁ וְ⁠יוֹסֵ֖ף הָיָ֥ה בְ⁠מִצְרָֽיִם׃","wֽa⁠yĕhi֗y ká̇l-ne֛peş̌ yòẕĕʼé֥y yeֽrekĕ-yaʻàqò֖b şǐbĕʻi֣ym ná֑peş̌ wĕ⁠ywòsé֖p háyá֥h bĕ⁠miẕĕráֽyim׃"],[1,6,"וַ⁠יָּ֤מָת יוֹסֵף֙ וְ⁠כָל־אֶחָ֔י⁠ו וְ⁠כֹ֖ל הַ⁠דּ֥וֹר הַ⁠הֽוּא׃","wa⁠yá֤̇máţ ywòsép֙ wĕ⁠kál-ʼeẖá֔y⁠w wĕ⁠kò֖l ha⁠ḋ֥wòr ha⁠hֽẇʼ׃"],[1,7,"וּ⁠בְנֵ֣י יִשְׂרָאֵ֗ל פָּר֧וּ וַֽ⁠יִּשְׁרְצ֛וּ וַ⁠יִּרְבּ֥וּ וַ⁠יַּֽעַצְמ֖וּ בִּ⁠מְאֹ֣ד מְאֹ֑ד וַ⁠תִּמָּלֵ֥א הָ⁠אָ֖רֶץ אֹתָֽ⁠ם׃פ","ẇ⁠bĕné֣y yişĕ̂ráʼé֗l pá̇r֧ẇ waֽ⁠yi̇şĕ̌rĕẕ֛ẇ wa⁠yi̇rĕḃ֥ẇ wa⁠yȧֽʻaẕĕm֖ẇ bi̇⁠mĕʼò֣d mĕʼò֑d wa⁠ţi̇má̇lé֥ʼ há⁠ʼá֖reẕ ʼòţáֽ⁠m׃p"],[1,8,"וַ⁠יָּ֥קָם מֶֽלֶךְ־חָדָ֖שׁ עַל־מִצְרָ֑יִם אֲשֶׁ֥ר לֹֽא־יָדַ֖ע אֶת־יוֹסֵֽף׃","wa⁠yá֥̇qám meֽlekĕ-ẖádá֖ş̌ ʻal-miẕĕrá֑yim ʼàşě֥r lòֽʼ-yáda֖ʻ ʼeţ-ywòséֽp׃"],[1,9,"וַ⁠יֹּ֖אמֶר אֶל־עַמּ֑⁠וֹ הִנֵּ֗ה עַ֚ם בְּנֵ֣י יִשְׂרָאֵ֔ל רַ֥ב וְ⁠עָצ֖וּם מִמֶּֽ⁠נּוּ׃","wa⁠yò֖̇ʼmer ʼel-ʻaṁ֑⁠wò hiné̇֗h ʻa֚m bĕ̇né֣y yişĕ̂ráʼé֔l ra֥b wĕ⁠ʻáẕ֖ẇm mimėֽ⁠ṅẇ׃"],[1,10,"הָ֥בָ⁠ה נִֽתְחַכְּמָ֖ה ל֑⁠וֹ פֶּן־יִרְבֶּ֗ה וְ⁠הָיָ֞ה כִּֽי־תִקְרֶ֤אנָה מִלְחָמָה֙ וְ⁠נוֹסַ֤ף גַּם־הוּא֙ עַל־שֹׂ֣נְאֵ֔י⁠נוּ וְ⁠נִלְחַם־בָּ֖⁠נוּ וְ⁠עָלָ֥ה מִן־הָ⁠אָֽרֶץ׃","há֥bá⁠h niֽţĕẖakĕ̇má֖h l֑⁠wò pėn-yirĕbė֗h wĕ⁠háyá֞h kiֽ̇y-ţiqĕre֤ʼnáh milĕẖámáh֙ wĕ⁠nwòsa֤p gȧm-hẇʼ֙ ʻal-şò֣̂nĕʼé֔y⁠nẇ wĕ⁠nilĕẖam-bá֖̇⁠nẇ wĕ⁠ʻálá֥h min-há⁠ʼáֽreẕ׃"],[1,11,"וַ⁠יָּשִׂ֤ימוּ עָלָי⁠ו֙ שָׂרֵ֣י מִסִּ֔ים לְמַ֥עַן עַנֹּת֖⁠וֹ בְּ⁠סִבְלֹתָ֑⁠ם וַ⁠יִּ֜בֶן עָרֵ֤י מִסְכְּנוֹת֙ לְ⁠פַרְעֹ֔ה אֶת־פִּתֹ֖ם וְ⁠אֶת־רַעַמְסֵֽס׃","wa⁠yá̇şî֤ymẇ ʻáláy⁠w֙ şá̂ré֣y misi̇֔ym lĕma֥ʻan ʻanò̇ţ֖⁠wò bĕ̇⁠sibĕlòţá֑⁠m wa⁠yi̇֜ben ʻáré֤y misĕkĕ̇nwòţ֙ lĕ⁠parĕʻò֔h ʼeţ-pi̇ţò֖m wĕ⁠ʼeţ-raʻamĕséֽs׃"],[1,12,"וְ⁠כַ⁠אֲשֶׁר֙ יְעַנּ֣וּ אֹת֔⁠וֹ כֵּ֥ן יִרְבֶּ֖ה וְ⁠כֵ֣ן יִפְרֹ֑ץ וַ⁠יָּקֻ֕צוּ מִ⁠פְּנֵ֖י בְּנֵ֥י יִשְׂרָאֵֽל׃","wĕ⁠ka⁠ʼàşěr֙ yĕʻaṅ֣ẇ ʼòţ֔⁠wò ké֥̇n yirĕbė֖h wĕ⁠ké֣n yipĕrò֑ẕ wa⁠yá̇qu֕ẕẇ mi⁠pĕ̇né֖y bĕ̇né֥y yişĕ̂ráʼéֽl׃"],[1,13,"וַ⁠יַּעֲבִ֧דוּ מִצְרַ֛יִם אֶת־בְּנֵ֥י יִשְׂרָאֵ֖ל בְּ⁠פָֽרֶךְ׃","wa⁠yȧʻàbi֧dẇ miẕĕra֛yim ʼeţ-bĕ̇né֥y yişĕ̂ráʼé֖l bĕ̇⁠páֽrekĕ׃"],[1,14,"וַ⁠יְמָרְר֨וּ אֶת־חַיֵּי⁠הֶ֜ם בַּ⁠עֲבֹדָ֣ה קָשָׁ֗ה בְּ⁠חֹ֨מֶר֙ וּ⁠בִ⁠לְבֵנִ֔ים וּ⁠בְ⁠כָל־עֲבֹדָ֖ה בַּ⁠שָּׂדֶ֑ה אֵ֚ת כָּל־עֲבֹ֣דָתָ֔⁠ם אֲשֶׁר־עָבְד֥וּ בָ⁠הֶ֖ם בְּ⁠פָֽרֶךְ׃","wa⁠yĕmárĕr֨ẇ ʼeţ-ẖayé̇y⁠he֜m bȧ⁠ʻàbòdá֣h qáşá̌֗h bĕ̇⁠ẖò֨mer֙ ẇ⁠bi⁠lĕbéni֔ym ẇ⁠bĕ⁠kál-ʻàbòdá֖h bȧ⁠şá̇̂de֑h ʼé֚ţ ká̇l-ʻàbò֣dáţá֔⁠m ʼàşěr-ʻábĕd֥ẇ bá⁠he֖m bĕ̇⁠páֽrekĕ׃"],[1,15,"וַ⁠יֹּ֨אמֶר֙ מֶ֣לֶךְ מִצְרַ֔יִם לַֽ⁠מְיַלְּדֹ֖ת הָֽ⁠עִבְרִיֹּ֑ת אֲשֶׁ֨ר שֵׁ֤ם הָֽ⁠אַחַת֙ שִׁפְרָ֔ה וְ⁠שֵׁ֥ם הַ⁠שֵּׁנִ֖ית פּוּעָֽה׃","wa⁠yò̇֨ʼmer֙ me֣lekĕ miẕĕra֔yim laֽ⁠mĕyalĕ̇dò֖ţ háֽ⁠ʻibĕriyò֑̇ţ ʼàşě֨r şé֤̌m háֽ⁠ʼaẖaţ֙ şǐpĕrá֔h wĕ⁠şé֥̌m ha⁠şé̇̌ni֖yţ ṗẇʻáֽh׃"],[1,16,"וַ⁠יֹּ֗אמֶר בְּ⁠יַלֶּדְ⁠כֶן֙ אֶת־הָֽ⁠עִבְרִיּ֔וֹת וּ⁠רְאִיתֶ֖ן עַל־הָ⁠אָבְנָ֑יִם אִם־בֵּ֥ן הוּא֙ וַ⁠הֲמִתֶּ֣ן אֹת֔⁠וֹ וְ⁠אִם־בַּ֥ת הִ֖יא וָ⁠חָֽיָה׃","wa⁠yò̇֗ʼmer bĕ̇⁠yalėdĕ⁠ken֙ ʼeţ-háֽ⁠ʻibĕriẏ֔wòţ ẇ⁠rĕʼiyţe֖n ʻal-há⁠ʼábĕná֑yim ʼim-bé֥̇n hẇʼ֙ wa⁠hàmiţė֣n ʼòţ֔⁠wò wĕ⁠ʼim-bȧ֥ţ hi֖yʼ wá⁠ẖáֽyáh׃"],[1,17,"וַ⁠תִּירֶ֤אןָ הַֽ⁠מְיַלְּדֹת֙ אֶת־הָ֣⁠אֱלֹהִ֔ים וְ⁠לֹ֣א עָשׂ֔וּ כַּ⁠אֲשֶׁ֛ר דִּבֶּ֥ר אֲלֵי⁠הֶ֖ן מֶ֣לֶךְ מִצְרָ֑יִם וַ⁠תְּחַיֶּ֖יןָ אֶת־הַ⁠יְלָדִֽים׃","wa⁠ţi̇yre֤ʼná haֽ⁠mĕyalĕ̇dòţ֙ ʼeţ-há֣⁠ʼèlòhi֔ym wĕ⁠lò֣ʼ ʻáş̂֔ẇ kȧ⁠ʼàşě֛r di̇bė֥r ʼàléy⁠he֖n me֣lekĕ miẕĕrá֑yim wa⁠ţĕ̇ẖayė֖yná ʼeţ-ha⁠yĕládiֽym׃"],[1,18,"וַ⁠יִּקְרָ֤א מֶֽלֶךְ־מִצְרַ֨יִם֙ לַֽ⁠מְיַלְּדֹ֔ת וַ⁠יֹּ֣אמֶר לָ⁠הֶ֔ן מַדּ֥וּעַ עֲשִׂיתֶ֖ן הַ⁠דָּבָ֣ר הַ⁠זֶּ֑ה וַ⁠תְּחַיֶּ֖יןָ אֶת־הַ⁠יְלָדִֽים׃","wa⁠yi̇qĕrá֤ʼ meֽlekĕ-miẕĕra֨yim֙ laֽ⁠mĕyalĕ̇dò֔ţ wa⁠yò֣̇ʼmer lá⁠he֔n maḋ֥ẇʻa ʻàşîyţe֖n ha⁠dá̇bá֣r ha⁠zė֑h wa⁠ţĕ̇ẖayė֖yná ʼeţ-ha⁠yĕládiֽym׃"],[1,19,"וַ⁠תֹּאמַ֤רְןָ הַֽ⁠מְיַלְּדֹת֙ אֶל־פַּרְעֹ֔ה כִּ֣י לֹ֧א כַ⁠נָּשִׁ֛ים הַ⁠מִּצְרִיֹּ֖ת הָֽ⁠עִבְרִיֹּ֑ת כִּֽי־חָי֣וֹת הֵ֔נָּה בְּ⁠טֶ֨רֶם תָּב֧וֹא אֲלֵ⁠הֶ֛ן הַ⁠מְיַלֶּ֖דֶת וְ⁠יָלָֽדוּ׃","wa⁠ţò̇ʼma֤rĕná haֽ⁠mĕyalĕ̇dòţ֙ ʼel-pȧrĕʻò֔h ki֣̇y lò֧ʼ ka⁠ná̇şǐ֛ym ha⁠mi̇ẕĕriyò֖̇ţ háֽ⁠ʻibĕriyò֑̇ţ kiֽ̇y-ẖáy֣wòţ hé֔ná̇h bĕ̇⁠te֨rem ţá̇b֧wòʼ ʼàlé⁠he֛n ha⁠mĕyalė֖deţ wĕ⁠yáláֽdẇ׃"],[1,20,"וַ⁠יֵּ֥יטֶב אֱלֹהִ֖ים לַֽ⁠מְיַלְּדֹ֑ת וַ⁠יִּ֧רֶב הָ⁠עָ֛ם וַ⁠יַּֽעַצְמ֖וּ מְאֹֽד׃","wa⁠yé֥̇yteb ʼèlòhi֖ym laֽ⁠mĕyalĕ̇dò֑ţ wa⁠yi֧̇reb há⁠ʻá֛m wa⁠yȧֽʻaẕĕm֖ẇ mĕʼòֽd׃"],[1,21,"וַ⁠יְהִ֕י כִּֽי־יָֽרְא֥וּ הַֽ⁠מְיַלְּדֹ֖ת אֶת־הָ⁠אֱלֹהִ֑ים וַ⁠יַּ֥עַשׂ לָ⁠הֶ֖ם בָּתִּֽים׃","wa⁠yĕhi֕y kiֽ̇y-yáֽrĕʼ֥ẇ haֽ⁠mĕyalĕ̇dò֖ţ ʼeţ-há⁠ʼèlòhi֑ym wa⁠yȧ֥ʻaş̂ lá⁠he֖m bá̇ţiֽ̇ym׃"],[1,22,"וַ⁠יְצַ֣ו פַּרְעֹ֔ה לְ⁠כָל־עַמּ֖⁠וֹ לֵ⁠אמֹ֑ר כָּל־הַ⁠בֵּ֣ן הַ⁠יִּלּ֗וֹד הַ⁠יְאֹ֨רָ⁠ה֙ תַּשְׁלִיכֻ֔⁠הוּ וְ⁠כָל־הַ⁠בַּ֖ת תְּחַיּֽוּ⁠ן׃ס","wa⁠yĕẕa֣w pȧrĕʻò֔h lĕ⁠kál-ʻaṁ֖⁠wò lé⁠ʼmò֑r ká̇l-ha⁠bé֣̇n ha⁠yi̇l̇֗wòd ha⁠yĕʼò֨rá⁠h֙ ţȧşĕ̌liyku֔⁠hẇ wĕ⁠kál-ha⁠bȧ֖ţ ţĕ̇ẖaẏֽẇ⁠n׃s"],[2,1,"וַ⁠יֵּ֥לֶךְ אִ֖ישׁ מִ⁠בֵּ֣ית לֵוִ֑י וַ⁠יִּקַּ֖ח אֶת־בַּת־לֵוִֽי׃","wa⁠yé֥̇lekĕ ʼi֖yş̌ mi⁠bé֣̇yţ léwi֑y wa⁠yi̇qȧ֖ẖ ʼeţ-bȧţ-léwiֽy׃"],[2,2,"וַ⁠תַּ֥הַר הָ⁠אִשָּׁ֖ה וַ⁠תֵּ֣לֶד בֵּ֑ן וַ⁠תֵּ֤רֶא אֹת⁠וֹ֙ כִּי־ט֣וֹב ה֔וּא וַֽ⁠תִּצְפְּנֵ֖⁠הוּ שְׁלֹשָׁ֥ה יְרָחִֽים׃","wa⁠ţȧ֥har há⁠ʼişá֖̇̌h wa⁠ţé֣̇led bé֑̇n wa⁠ţé֤̇reʼ ʼòţ⁠wò֙ ki̇y-t֣wòb h֔ẇʼ waֽ⁠ţi̇ẕĕpĕ̇né֖⁠hẇ şĕ̌lòşá֥̌h yĕráẖiֽym׃"],[2,3,"וְ⁠לֹא־יָכְלָ֣ה עוֹד֮ הַצְּפִינ⁠וֹ֒ וַ⁠תִּֽקַּֽח־ל⁠וֹ֙ תֵּ֣בַת גֹּ֔מֶא וַ⁠תַּחְמְרָ֥⁠ה בַ⁠חֵמָ֖ר וּ⁠בַ⁠זָּ֑פֶת וַ⁠תָּ֤שֶׂם בָּ⁠הּ֙ אֶת־הַ⁠יֶּ֔לֶד וַ⁠תָּ֥שֶׂם בַּ⁠סּ֖וּף עַל־שְׂפַ֥ת הַ⁠יְאֹֽר׃","wĕ⁠lòʼ-yákĕlá֣h ʻwòd֮ haẕĕ̇piyn⁠wò֒ wa⁠ţiֽ̇qȧֽẖ-l⁠wò֙ ţé֣̇baţ gò̇֔meʼ wa⁠ţȧẖĕmĕrá֥⁠h ba⁠ẖémá֖r ẇ⁠ba⁠zá֑̇peţ wa⁠ţá֤̇şêm bá̇⁠ḣ֙ ʼeţ-ha⁠yė֔led wa⁠ţá֥̇şêm bȧ⁠ṡ֖ẇp ʻal-şĕ̂pa֥ţ ha⁠yĕʼòֽr׃"],[2,4,"וַ⁠תֵּתַצַּ֥ב אֲחֹת֖⁠וֹ מֵ⁠רָחֹ֑ק לְ⁠דֵעָ֕ה מַה־יֵּעָשֶׂ֖ה לֽ⁠וֹ׃","wa⁠ţé̇ţaẕȧ֥b ʼàẖòţ֖⁠wò mé⁠ráẖò֑q lĕ⁠déʻá֕h mah-yé̇ʻáşê֖h lֽ⁠wò׃"],[2,5,"וַ⁠תֵּ֤רֶד בַּת־פַּרְעֹה֙ לִ⁠רְחֹ֣ץ עַל־הַ⁠יְאֹ֔ר וְ⁠נַעֲרֹתֶ֥י⁠הָ הֹלְכֹ֖ת עַל־יַ֣ד הַ⁠יְאֹ֑ר וַ⁠תֵּ֤רֶא אֶת־הַ⁠תֵּבָה֙ בְּ⁠ת֣וֹךְ הַ⁠סּ֔וּף וַ⁠תִּשְׁלַ֥ח אֶת־אֲמָתָ֖⁠הּ וַ⁠תִּקָּחֶֽ⁠הָ","wa⁠ţé֤̇red bȧţ-pȧrĕʻòh֙ li⁠rĕẖò֣ẕ ʻal-ha⁠yĕʼò֔r wĕ⁠naʻàròţe֥y⁠há hòlĕkò֖ţ ʻal-ya֣d ha⁠yĕʼò֑r wa⁠ţé֤̇reʼ ʼeţ-ha⁠ţé̇báh֙ bĕ̇⁠ţ֣wòkĕ ha⁠ṡ֔ẇp wa⁠ţi̇şĕ̌la֥ẖ ʼeţ-ʼàmáţá֖⁠ḣ wa⁠ţi̇qá̇ẖeֽ⁠há"],[2,6,"וַ⁠תִּפְתַּח֙ וַ⁠תִּרְאֵ֣⁠הוּ אֶת־הַ⁠יֶּ֔לֶד וְ⁠הִנֵּה־נַ֖עַר בֹּכֶ֑ה וַ⁠תַּחְמֹ֣ל עָלָ֔י⁠ו וַ⁠תֹּ֕אמֶר מִ⁠יַּלְדֵ֥י הָֽ⁠עִבְרִ֖ים זֶֽה׃","wa⁠ţi̇pĕţȧẖ֙ wa⁠ţi̇rĕʼé֣⁠hẇ ʼeţ-ha⁠yė֔led wĕ⁠hiné̇h-na֖ʻar bò̇ke֑h wa⁠ţȧẖĕmò֣l ʻálá֔y⁠w wa⁠ţò̇֕ʼmer mi⁠yȧlĕdé֥y háֽ⁠ʻibĕri֖ym zeֽh׃"],[2,7,"וַ⁠תֹּ֣אמֶר אֲחֹת⁠וֹ֮ אֶל־בַּת־פַּרְעֹה֒ הַ⁠אֵלֵ֗ךְ וְ⁠קָרָ֤אתִי לָ⁠ךְ֙ אִשָּׁ֣ה מֵינֶ֔קֶת מִ֖ן הָ⁠עִבְרִיֹּ֑ת וְ⁠תֵינִ֥ק לָ֖⁠ךְ אֶת־הַ⁠יָּֽלֶד׃","wa⁠ţò֣̇ʼmer ʼàẖòţ⁠wò֮ ʼel-bȧţ-pȧrĕʻòh֒ ha⁠ʼélé֗kĕ wĕ⁠qárá֤ʼţiy lá⁠kĕ֙ ʼişá֣̇̌h méyne֔qeţ mi֖n há⁠ʻibĕriyò֑̇ţ wĕ⁠ţéyni֥q lá֖⁠kĕ ʼeţ-ha⁠yáֽ̇led׃"],[2,8,"וַ⁠תֹּֽאמֶר־לָ֥⁠הּ בַּת־פַּרְעֹ֖ה לֵ֑כִי וַ⁠תֵּ֨לֶךְ֙ הָֽ⁠עַלְמָ֔ה וַ⁠תִּקְרָ֖א אֶת־אֵ֥ם הַ⁠יָּֽלֶד׃","wa⁠ţòֽ̇ʼmer-lá֥⁠ḣ bȧţ-pȧrĕʻò֖h lé֑kiy wa⁠ţé̇֨lekĕ֙ háֽ⁠ʻalĕmá֔h wa⁠ţi̇qĕrá֖ʼ ʼeţ-ʼé֥m ha⁠yáֽ̇led׃"],[2,9,"וַ⁠תֹּ֧אמֶר לָ֣⁠הּ בַּת־פַּרְעֹ֗ה הֵילִ֜יכִי אֶת־הַ⁠יֶּ֤לֶד הַ⁠זֶּה֙ וְ⁠הֵינִקִ֣⁠הוּ לִ֔⁠י וַ⁠אֲנִ֖י אֶתֵּ֣ן אֶת־שְׂכָרֵ֑⁠ךְ וַ⁠תִּקַּ֧ח הָ⁠אִשָּׁ֛ה הַ⁠יֶּ֖לֶד וַ⁠תְּנִיקֵֽ⁠הוּ׃","wa⁠ţò֧̇ʼmer lá֣⁠ḣ bȧţ-pȧrĕʻò֗h héyli֜ykiy ʼeţ-ha⁠yė֤led ha⁠zėh֙ wĕ⁠héyniqi֣⁠hẇ li֔⁠y wa⁠ʼàni֖y ʼeţé֣̇n ʼeţ-şĕ̂káré֑⁠kĕ wa⁠ţi̇qȧ֧ẖ há⁠ʼişá֛̇̌h ha⁠yė֖led wa⁠ţĕ̇niyqéֽ⁠hẇ׃"],[2,10,"וַ⁠יִגְדַּ֣ל הַ⁠יֶּ֗לֶד וַ⁠תְּבִאֵ֨⁠הוּ֙ לְ⁠בַת־פַּרְעֹ֔ה וַֽ⁠יְהִי־לָ֖⁠הּ לְ⁠בֵ֑ן וַ⁠תִּקְרָ֤א שְׁמ⁠וֹ֙ מֹשֶׁ֔ה וַ⁠תֹּ֕אמֶר כִּ֥י מִן־הַ⁠מַּ֖יִם מְשִׁיתִֽ⁠הוּ׃","wa⁠yigĕdȧ֣l ha⁠yė֗led wa⁠ţĕ̇biʼé֨⁠hẇ֙ lĕ⁠baţ-pȧrĕʻò֔h wֽa⁠yĕhiy-lá֖⁠ḣ lĕ⁠bé֑n wa⁠ţi̇qĕrá֤ʼ şĕ̌m⁠wò֙ mòşě֔h wa⁠ţò̇֕ʼmer ki֥̇y min-ha⁠mȧ֖yim mĕşǐyţiֽ⁠hẇ׃"],[2,11,"וַ⁠יְהִ֣י ׀ בַּ⁠יָּמִ֣ים הָ⁠הֵ֗ם וַ⁠יִּגְדַּ֤ל מֹשֶׁה֙ וַ⁠יֵּצֵ֣א אֶל־אֶחָ֔י⁠ו וַ⁠יַּ֖רְא בְּ⁠סִבְלֹתָ֑⁠ם וַ⁠יַּרְא֙ אִ֣ישׁ מִצְרִ֔י מַכֶּ֥ה אִישׁ־עִבְרִ֖י מֵ⁠אֶחָֽי⁠ו׃","wa⁠yĕhi֣y ׀ bȧ⁠yá̇mi֣ym há⁠hé֗m wa⁠yi̇gĕdȧ֤l mòşěh֙ wa⁠yé̇ẕé֣ʼ ʼel-ʼeẖá֔y⁠w wa⁠yȧ֖rĕʼ bĕ̇⁠sibĕlòţá֑⁠m wa⁠yȧrĕʼ֙ ʼi֣yş̌ miẕĕri֔y makė֥h ʼiyş̌-ʻibĕri֖y mé⁠ʼeẖáֽy⁠w׃"],[2,12,"וַ⁠יִּ֤פֶן כֹּה֙ וָ⁠כֹ֔ה וַ⁠יַּ֖רְא כִּ֣י אֵ֣ין אִ֑ישׁ וַ⁠יַּךְ֙ אֶת־הַ⁠מִּצְרִ֔י וַֽ⁠יִּטְמְנֵ֖⁠הוּ בַּ⁠חֽוֹל׃","wa⁠yi֤̇pen kò̇h֙ wá⁠kò֔h wa⁠yȧ֖rĕʼ ki֣̇y ʼé֣yn ʼi֑yş̌ wa⁠yȧkĕ֙ ʼeţ-ha⁠mi̇ẕĕri֔y waֽ⁠yi̇tĕmĕné֖⁠hẇ bȧ⁠ẖֽwòl׃"],[2,13,"וַ⁠יֵּצֵא֙ בַּ⁠יּ֣וֹם הַ⁠שֵּׁנִ֔י וְ⁠הִנֵּ֛ה שְׁנֵֽי־אֲנָשִׁ֥ים עִבְרִ֖ים נִצִּ֑ים וַ⁠יֹּ֨אמֶר֙ לָֽ⁠רָשָׁ֔ע לָ֥⁠מָּה תַכֶּ֖ה רֵעֶֽ⁠ךָ׃","wa⁠yé̇ẕéʼ֙ bȧ⁠ẏ֣wòm ha⁠şé̇̌ni֔y wĕ⁠hiné֛̇h şĕ̌néֽy-ʼànáşǐ֥ym ʻibĕri֖ym niẕi֑̇ym wa⁠yò̇֨ʼmer֙ láֽ⁠ráşá̌֔ʻ lá֥⁠má̇h ţakė֖h réʻeֽ⁠ká׃"],[2,14,"וַ֠⁠יֹּאמֶר מִ֣י שָֽׂמְ⁠ךָ֞ לְ⁠אִ֨ישׁ שַׂ֤ר וְ⁠שֹׁפֵט֙ עָלֵ֔י⁠נוּ הַ⁠לְ⁠הָרְגֵ֨⁠נִי֙ אַתָּ֣ה אֹמֵ֔ר כַּ⁠אֲשֶׁ֥ר הָרַ֖גְתָּ אֶת־הַ⁠מִּצְרִ֑י וַ⁠יִּירָ֤א מֹשֶׁה֙ וַ⁠יֹּאמַ֔ר אָכֵ֖ן נוֹדַ֥ע הַ⁠דָּבָֽר׃","wa֠⁠yò̇ʼmer mi֣y şáֽ̂mĕ⁠ká֞ lĕ⁠ʼi֨yş̌ şâ֤r wĕ⁠şò̌pét֙ ʻálé֔y⁠nẇ ha⁠lĕ⁠hárĕgé֨⁠niy֙ ʼaţá֣̇h ʼòmé֔r kȧ⁠ʼàşě֥r hára֖gĕţá̇ ʼeţ-ha⁠mi̇ẕĕri֑y wa⁠yi̇yrá֤ʼ mòşěh֙ wa⁠yò̇ʼma֔r ʼáké֖n nwòda֥ʻ ha⁠dá̇báֽr׃"],[2,15,"וַ⁠יִּשְׁמַ֤ע פַּרְעֹה֙ אֶת־הַ⁠דָּבָ֣ר הַ⁠זֶּ֔ה וַ⁠יְבַקֵּ֖שׁ לַ⁠הֲרֹ֣ג אֶת־מֹשֶׁ֑ה וַ⁠יִּבְרַ֤ח מֹשֶׁה֙ מִ⁠פְּנֵ֣י פַרְעֹ֔ה וַ⁠יֵּ֥שֶׁב בְּ⁠אֶֽרֶץ־מִדְיָ֖ן וַ⁠יֵּ֥שֶׁב עַֽל־הַ⁠בְּאֵֽר׃","wa⁠yi̇şĕ̌ma֤ʻ pȧrĕʻòh֙ ʼeţ-ha⁠dá̇bá֣r ha⁠zė֔h wa⁠yĕbaqé֖̇ş̌ la⁠hàrò֣g ʼeţ-mòşě֑h wa⁠yi̇bĕra֤ẖ mòşěh֙ mi⁠pĕ̇né֣y parĕʻò֔h wa⁠yé֥̇şěb bĕ̇⁠ʼeֽreẕ-midĕyá֖n wa⁠yé֥̇şěb ʻaֽl-ha⁠bĕ̇ʼéֽr׃"],[2,16,"וּ⁠לְ⁠כֹהֵ֥ן מִדְיָ֖ן שֶׁ֣בַע בָּנ֑וֹת וַ⁠תָּבֹ֣אנָה וַ⁠תִּדְלֶ֗נָה וַ⁠תְּמַלֶּ֨אנָה֙ אֶת־הָ֣⁠רְהָטִ֔ים לְ⁠הַשְׁק֖וֹת צֹ֥אן אֲבִי⁠הֶֽן׃","ẇ⁠lĕ⁠kòhé֥n midĕyá֖n şě֣baʻ bá̇n֑wòţ wa⁠ţá̇bò֣ʼnáh wa⁠ţi̇dĕle֗náh wa⁠ţĕ̇malė֨ʼnáh֙ ʼeţ-há֣⁠rĕháti֔ym lĕ⁠haşĕ̌q֖wòţ ẕò֥ʼn ʼàbiy⁠heֽn׃"],[2,17,"וַ⁠יָּבֹ֥אוּ הָ⁠רֹעִ֖ים וַ⁠יְגָרְשׁ֑וּ⁠ם וַ⁠יָּ֤קָם מֹשֶׁה֙ וַ⁠יּ֣וֹשִׁעָ֔⁠ן וַ⁠יַּ֖שְׁקְ אֶת־צֹאנָֽ⁠ם׃","wa⁠yá̇bò֥ʼẇ há⁠ròʻi֖ym wa⁠yĕgárĕş֑̌ẇ⁠m wa⁠yá֤̇qám mòşěh֙ wa⁠ẏ֣wòşǐʻá֔⁠n wa⁠yȧ֖şĕ̌qĕ ʼeţ-ẕòʼnáֽ⁠m׃"],[2,18,"וַ⁠תָּבֹ֕אנָה אֶל־רְעוּאֵ֖ל אֲבִי⁠הֶ֑ן וַ⁠יֹּ֕אמֶר מַדּ֛וּעַ מִהַרְתֶּ֥ן בֹּ֖א הַ⁠יּֽוֹם׃","wa⁠ţá̇bò֕ʼnáh ʼel-rĕʻẇʼé֖l ʼàbiy⁠he֑n wa⁠yò̇֕ʼmer maḋ֛ẇʻa miharĕţė֥n bò֖̇ʼ ha⁠ẏֽwòm׃"],[2,19,"וַ⁠תֹּאמַ֕רְןָ אִ֣ישׁ מִצְרִ֔י הִצִּילָ֖⁠נוּ מִ⁠יַּ֣ד הָ⁠רֹעִ֑ים וְ⁠גַם־דָּלֹ֤ה דָלָה֙ לָ֔⁠נוּ וַ⁠יַּ֖שְׁקְ אֶת־הַ⁠צֹּֽאן׃","wa⁠ţò̇ʼma֕rĕná ʼi֣yş̌ miẕĕri֔y hiẕi̇ylá֖⁠nẇ mi⁠yȧ֣d há⁠ròʻi֑ym wĕ⁠gam-dá̇lò֤h dáláh֙ lá֔⁠nẇ wa⁠yȧ֖şĕ̌qĕ ʼeţ-ha⁠ẕòֽ̇ʼn׃"],[2,20,"וַ⁠יֹּ֥אמֶר אֶל־בְּנֹתָ֖י⁠ו וְ⁠אַיּ֑⁠וֹ לָ֤⁠מָּה זֶּה֙ עֲזַבְתֶּ֣ן אֶת־הָ⁠אִ֔ישׁ קִרְאֶ֥ן ל֖⁠וֹ וְ⁠יֹ֥אכַל לָֽחֶם׃","wa⁠yò֥̇ʼmer ʼel-bĕ̇nòţá֖y⁠w wĕ⁠ʼaẏ֑⁠wò lá֤⁠má̇h zėh֙ ʻàzabĕţė֣n ʼeţ-há⁠ʼi֔yş̌ qirĕʼe֥n l֖⁠wò wĕ⁠yò֥ʼkal láֽẖem׃"],[2,21,"וַ⁠יּ֥וֹאֶל מֹשֶׁ֖ה לָ⁠שֶׁ֣בֶת אֶת־הָ⁠אִ֑ישׁ וַ⁠יִּתֵּ֛ן אֶת־צִפֹּרָ֥ה בִתּ֖⁠וֹ לְ⁠מֹשֶֽׁה׃","wa⁠ẏ֥wòʼel mòşě֖h lá⁠şě֣beţ ʼeţ-há⁠ʼi֑yş̌ wa⁠yi̇ţé֛̇n ʼeţ-ẕipò̇rá֥h biţ֖̇⁠wò lĕ⁠mòşěֽh׃"],[2,22,"וַ⁠תֵּ֣לֶד בֵּ֔ן וַ⁠יִּקְרָ֥א אֶת־שְׁמ֖⁠וֹ גֵּרְשֹׁ֑ם כִּ֣י אָמַ֔ר גֵּ֣ר הָיִ֔יתִי בְּ⁠אֶ֖רֶץ נָכְרִיָּֽה׃פ","wa⁠ţé֣̇led bé̇֔n wa⁠yi̇qĕrá֥ʼ ʼeţ-şĕ̌m֖⁠wò gé̇rĕşò֑̌m ki֣̇y ʼáma֔r gé֣̇r háyi֔yţiy bĕ̇⁠ʼe֖reẕ nákĕriyáֽ̇h׃p"],[2,23,"וַ⁠יְהִי֩ בַ⁠יָּמִ֨ים הָֽ⁠רַבִּ֜ים הָ⁠הֵ֗ם וַ⁠יָּ֨מָת֙ מֶ֣לֶךְ מִצְרַ֔יִם וַ⁠יֵּאָנְח֧וּ בְנֵֽי־יִשְׂרָאֵ֛ל מִן־הָ⁠עֲבֹדָ֖ה וַ⁠יִּזְעָ֑קוּ וַ⁠תַּ֧עַל שַׁוְעָתָ֛⁠ם אֶל־הָ⁠אֱלֹהִ֖ים מִן־הָ⁠עֲבֹדָֽה׃","wa⁠yĕhiy֩ ba⁠yá̇mi֨ym hֽá⁠rabi̇֜ym há⁠hé֗m wa⁠yá̇֨máţ֙ me֣lekĕ miẕĕra֔yim wa⁠yé̇ʼánĕẖ֧ẇ bĕnéֽy-yişĕ̂ráʼé֛l min-há⁠ʻàbòdá֖h wa⁠yi̇zĕʻá֑qẇ wa⁠ţȧ֧ʻal şǎwĕʻáţá֛⁠m ʼel-há⁠ʼèlòhi֖ym min-há⁠ʻàbòdáֽh׃"],[2,24,"וַ⁠יִּשְׁמַ֥ע אֱלֹהִ֖ים אֶת־נַאֲקָתָ֑⁠ם וַ⁠יִּזְכֹּ֤ר אֱלֹהִים֙ אֶת־בְּרִית֔⁠וֹ אֶת־אַבְרָהָ֖ם אֶת־יִצְחָ֥ק וְ⁠אֶֽת־יַעֲקֹֽב׃","wa⁠yi̇şĕ̌ma֥ʻ ʼèlòhi֖ym ʼeţ-naʼàqáţá֑⁠m wa⁠yi̇zĕkò֤̇r ʼèlòhiym֙ ʼeţ-bĕ̇riyţ֔⁠wò ʼeţ-ʼabĕráhá֖m ʼeţ-yiẕĕẖá֥q wĕ⁠ʼeֽţ-yaʻàqòֽb׃"],[2,25,"וַ⁠יַּ֥רְא אֱלֹהִ֖ים אֶת־בְּנֵ֣י יִשְׂרָאֵ֑ל וַ⁠יֵּ֖דַע אֱלֹהִֽים׃ס","wa⁠yȧ֥rĕʼ ʼèlòhi֖ym ʼeţ-bĕ̇né֣y yişĕ̂ráʼé֑l wa⁠yé֖̇daʻ ʼèlòhiֽym׃s"],[3,1,"וּ⁠מֹשֶׁ֗ה הָיָ֥ה רֹעֶ֛ה אֶת־צֹ֛אן יִתְר֥וֹ חֹתְנ֖⁠וֹ כֹּהֵ֣ן מִדְיָ֑ן וַ⁠יִּנְהַ֤ג אֶת־הַ⁠צֹּאן֙ אַחַ֣ר הַ⁠מִּדְבָּ֔ר וַ⁠יָּבֹ֛א אֶל־הַ֥ר הָ⁠אֱלֹהִ֖ים חֹרֵֽבָ⁠ה׃","ẇ⁠mòşě֗h háyá֥h ròʻe֛h ʼeţ-ẕò֛ʼn yiţĕr֥wò ẖòţĕn֖⁠wò kò̇hé֣n midĕyá֑n wa⁠yi̇nĕha֤g ʼeţ-ha⁠ẕò̇ʼn֙ ʼaẖa֣r ha⁠mi̇dĕbá̇֔r wa⁠yá̇bò֛ʼ ʼel-ha֥r há⁠ʼèlòhi֖ym ẖòréֽbá⁠h׃"],[3,2,"וַ֠⁠יֵּרָא מַלְאַ֨ךְ יְהֹוָ֥ה אֵלָ֛י⁠ו בְּ⁠לַבַּת־אֵ֖שׁ מִ⁠תּ֣וֹךְ הַ⁠סְּנֶ֑ה וַ⁠יַּ֗רְא וְ⁠הִנֵּ֤ה הַ⁠סְּנֶה֙ בֹּעֵ֣ר בָּ⁠אֵ֔שׁ וְ⁠הַ⁠סְּנֶ֖ה אֵינֶ֥⁠נּוּ אֻכָּֽל׃","wa֠⁠yé̇ráʼ malĕʼa֨kĕ yĕhòwá֥h ʼélá֛y⁠w bĕ̇⁠labȧţ-ʼé֖ş̌ mi⁠ţ֣̇wòkĕ ha⁠sĕ̇ne֑h wa⁠yȧ֗rĕʼ wĕ⁠hiné֤̇h ha⁠sĕ̇neh֙ bò̇ʻé֣r bá̇⁠ʼé֔ş̌ wĕ⁠ha⁠sĕ̇ne֖h ʼéyne֥⁠ṅẇ ʼukáֽ̇l׃"],[3,3,"וַ⁠יֹּ֣אמֶר מֹשֶׁ֔ה אָסֻֽרָה־נָּ֣א וְ⁠אֶרְאֶ֔ה אֶת־הַ⁠מַּרְאֶ֥ה הַ⁠גָּדֹ֖ל הַ⁠זֶּ֑ה מַדּ֖וּעַ לֹא־יִבְעַ֥ר הַ⁠סְּנֶֽה׃","wa⁠yò֣̇ʼmer mòşě֔h ʼásuֽráh-ná֣̇ʼ wĕ⁠ʼerĕʼe֔h ʼeţ-ha⁠mȧrĕʼe֥h ha⁠gá̇dò֖l ha⁠zė֑h maḋ֖ẇʻa lòʼ-yibĕʻa֥r ha⁠sĕ̇neֽh׃"],[3,4,"וַ⁠יַּ֥רְא יְהוָ֖ה כִּ֣י סָ֣ר לִ⁠רְא֑וֹת וַ⁠יִּקְרָא֩ אֵלָ֨י⁠ו אֱלֹהִ֜ים מִ⁠תּ֣וֹךְ הַ⁠סְּנֶ֗ה וַ⁠יֹּ֛אמֶר מֹשֶׁ֥ה מֹשֶׁ֖ה וַ⁠יֹּ֥אמֶר הִנֵּֽ⁠נִי׃","wa⁠yȧ֥rĕʼ yĕhwá֖h ki֣̇y sá֣r li⁠rĕʼ֑wòţ wa⁠yi̇qĕráʼ֩ ʼélá֨y⁠w ʼèlòhi֜ym mi⁠ţ֣̇wòkĕ ha⁠sĕ̇ne֗h wa⁠yò֛̇ʼmer mòşě֥h mòşě֖h wa⁠yò֥̇ʼmer hinéֽ̇⁠niy׃"],[3,5,"וַ⁠יֹּ֖אמֶר אַל־תִּקְרַ֣ב הֲלֹ֑ם שַׁל־נְעָלֶ֨י⁠ךָ֙ מֵ⁠עַ֣ל רַגְלֶ֔י⁠ךָ כִּ֣י הַ⁠מָּק֗וֹם אֲשֶׁ֤ר אַתָּה֙ עוֹמֵ֣ד עָלָ֔י⁠ו אַדְמַת־קֹ֖דֶשׁ הֽוּא׃","wa⁠yò֖̇ʼmer ʼal-ţi̇qĕra֣b hàlò֑m şǎl-nĕʻále֨y⁠ká֙ mé⁠ʻa֣l ragĕle֔y⁠ká ki֣̇y ha⁠má̇q֗wòm ʼàşě֤r ʼaţá̇h֙ ʻwòmé֣d ʻálá֔y⁠w ʼadĕmaţ-qò֖deş̌ hֽẇʼ׃"],[3,6,"וַ⁠יֹּ֗אמֶר אָנֹכִי֙ אֱלֹהֵ֣י אָבִ֔י⁠ךָ אֱלֹהֵ֧י אַבְרָהָ֛ם אֱלֹהֵ֥י יִצְחָ֖ק וֵ⁠אלֹהֵ֣י יַעֲקֹ֑ב וַ⁠יַּסְתֵּ֤ר מֹשֶׁה֙ פָּנָ֔י⁠ו כִּ֣י יָרֵ֔א מֵ⁠הַבִּ֖יט אֶל־הָ⁠אֱלֹהִֽים׃","wa⁠yò̇֗ʼmer ʼánòkiy֙ ʼèlòhé֣y ʼábi֔y⁠ká ʼèlòhé֧y ʼabĕráhá֛m ʼèlòhé֥y yiẕĕẖá֖q wé⁠ʼlòhé֣y yaʻàqò֑b wa⁠yȧsĕţé֤̇r mòşěh֙ pá̇ná֔y⁠w ki֣̇y yáré֔ʼ mé⁠habi֖̇yt ʼel-há⁠ʼèlòhiֽym׃"],[3,7,"וַ⁠יֹּ֣אמֶר יְהוָ֔ה רָאֹ֥ה רָאִ֛יתִי אֶת־עֳנִ֥י עַמִּ֖⁠י אֲשֶׁ֣ר בְּ⁠מִצְרָ֑יִם וְ⁠אֶת־צַעֲקָתָ֤⁠ם שָׁמַ֨עְתִּי֙ מִ⁠פְּנֵ֣י נֹֽגְשָׂ֔י⁠ו כִּ֥י יָדַ֖עְתִּי אֶת־מַכְאֹבָֽי⁠ו׃","wa⁠yò֣̇ʼmer yĕhwá֔h ráʼò֥h ráʼi֛yţiy ʼeţ-ʻoni֥y ʻami֖̇⁠y ʼàşě֣r bĕ̇⁠miẕĕrá֑yim wĕ⁠ʼeţ-ẕaʻàqáţá֤⁠m şá̌ma֨ʻĕţi̇y֙ mi⁠pĕ̇né֣y nòֽgĕşá̂֔y⁠w ki֥̇y yáda֖ʻĕţi̇y ʼeţ-makĕʼòbáֽy⁠w׃"],[3,8,"וָ⁠אֵרֵ֞ד לְ⁠הַצִּיל֣⁠וֹ ׀ מִ⁠יַּ֣ד מִצְרַ֗יִם וּֽ⁠לְ⁠הַעֲלֹת⁠וֹ֮ מִן־הָ⁠אָ֣רֶץ הַ⁠הִוא֒ אֶל־אֶ֤רֶץ טוֹבָה֙ וּ⁠רְחָבָ֔ה אֶל־אֶ֛רֶץ זָבַ֥ת חָלָ֖ב וּ⁠דְבָ֑שׁ אֶל־מְק֤וֹם הַֽ⁠כְּנַעֲנִי֙ וְ⁠הַ֣⁠חִתִּ֔י וְ⁠הָֽ⁠אֱמֹרִי֙ וְ⁠הַ⁠פְּרִזִּ֔י וְ⁠הַ⁠חִוִּ֖י וְ⁠הַ⁠יְבוּסִֽי׃","wá⁠ʼéré֞d lĕ⁠haẕi̇yl֣⁠wò ׀ mi⁠yȧ֣d miẕĕra֗yim ẇֽ⁠lĕ⁠haʻàlòţ⁠wò֮ min-há⁠ʼá֣reẕ ha⁠hiwʼ֒ ʼel-ʼe֤reẕ twòbáh֙ ẇ⁠rĕẖábá֔h ʼel-ʼe֛reẕ zába֥ţ ẖálá֖b ẇ⁠dĕbá֑ş̌ ʼel-mĕq֤wòm haֽ⁠kĕ̇naʻàniy֙ wĕ⁠ha֣⁠ẖiţi̇֔y wĕ⁠háֽ⁠ʼèmòriy֙ wĕ⁠ha⁠pĕ̇rizi̇֔y wĕ⁠ha⁠ẖiwi֖̇y wĕ⁠ha⁠yĕbẇsiֽy׃"],[3,9,"וְ⁠עַתָּ֕ה הִנֵּ֛ה צַעֲקַ֥ת בְּנֵי־יִשְׂרָאֵ֖ל בָּ֣אָה אֵלָ֑⁠י וְ⁠גַם־רָאִ֨יתִי֙ אֶת־הַ⁠לַּ֔חַץ אֲשֶׁ֥ר מִצְרַ֖יִם לֹחֲצִ֥ים אֹתָֽ⁠ם׃","wĕ⁠ʻaţá̇֕h hiné֛̇h ẕaʻàqa֥ţ bĕ̇néy-yişĕ̂ráʼé֖l bá֣̇ʼáh ʼélá֑⁠y wĕ⁠gam-ráʼi֨yţiy֙ ʼeţ-ha⁠lȧ֔ẖaẕ ʼàşě֥r miẕĕra֖yim lòẖàẕi֥ym ʼòţáֽ⁠m׃"],[3,10,"וְ⁠עַתָּ֣ה לְכָ֔⁠ה וְ⁠אֶֽשְׁלָחֲ⁠ךָ֖ אֶל־פַּרְעֹ֑ה וְ⁠הוֹצֵ֛א אֶת־עַמִּ֥⁠י בְנֵֽי־יִשְׂרָאֵ֖ל מִ⁠מִּצְרָֽיִם׃","wĕ⁠ʻaţá֣̇h lĕká֔⁠h wĕ⁠ʼeֽşĕ̌láẖà⁠ká֖ ʼel-pȧrĕʻò֑h wĕ⁠hwòẕé֛ʼ ʼeţ-ʻami֥̇⁠y bĕnéֽy-yişĕ̂ráʼé֖l mi⁠mi̇ẕĕráֽyim׃"],[3,11,"וַ⁠יֹּ֤אמֶר מֹשֶׁה֙ אֶל־הָ֣⁠אֱלֹהִ֔ים מִ֣י אָנֹ֔כִי כִּ֥י אֵלֵ֖ךְ אֶל־פַּרְעֹ֑ה וְ⁠כִ֥י אוֹצִ֛יא אֶת־בְּנֵ֥י יִשְׂרָאֵ֖ל מִ⁠מִּצְרָֽיִם׃","wa⁠yò֤̇ʼmer mòşěh֙ ʼel-há֣⁠ʼèlòhi֔ym mi֣y ʼánò֔kiy ki֥̇y ʼélé֖kĕ ʼel-pȧrĕʻò֑h wĕ⁠ki֥y ʼwòẕi֛yʼ ʼeţ-bĕ̇né֥y yişĕ̂ráʼé֖l mi⁠mi̇ẕĕráֽyim׃"],[3,12,"וַ⁠יֹּ֨אמֶר֙ כִּֽי־אֶֽהְיֶ֣ה עִמָּ֔⁠ךְ וְ⁠זֶה־לְּ⁠ךָ֣ הָ⁠א֔וֹת כִּ֥י אָנֹכִ֖י שְׁלַחְתִּ֑י⁠ךָ בְּ⁠הוֹצִֽיאֲ⁠ךָ֤ אֶת־הָ⁠עָם֙ מִ⁠מִּצְרַ֔יִם תַּֽעַבְדוּ⁠ן֙ אֶת־הָ֣⁠אֱלֹהִ֔ים עַ֖ל הָ⁠הָ֥ר הַ⁠זֶּֽה׃","wa⁠yò̇֨ʼmer֙ kiֽ̇y-ʼeֽhĕye֣h ʻimá̇֔⁠kĕ wĕ⁠zeh-lĕ̇⁠ká֣ há⁠ʼ֔wòţ ki֥̇y ʼánòki֖y şĕ̌laẖĕţi֑̇y⁠ká bĕ̇⁠hwòẕiֽyʼà⁠ká֤ ʼeţ-há⁠ʻám֙ mi⁠mi̇ẕĕra֔yim ţȧֽʻabĕdẇ⁠n֙ ʼeţ-há֣⁠ʼèlòhi֔ym ʻa֖l há⁠há֥r ha⁠zėֽh׃"],[3,13,"וַ⁠יֹּ֨אמֶר מֹשֶׁ֜ה אֶל־הָֽ⁠אֱלֹהִ֗ים הִנֵּ֨ה אָנֹכִ֣י בָא֮ אֶל־בְּנֵ֣י יִשְׂרָאֵל֒ וְ⁠אָמַרְתִּ֣י לָ⁠הֶ֔ם אֱלֹהֵ֥י אֲבוֹתֵי⁠כֶ֖ם שְׁלָחַ֣⁠נִי אֲלֵי⁠כֶ֑ם וְ⁠אָֽמְרוּ־לִ֣⁠י מַה־שְּׁמ֔⁠וֹ מָ֥ה אֹמַ֖ר אֲלֵ⁠הֶֽם׃","wa⁠yò̇֨ʼmer mòşě֜h ʼel-háֽ⁠ʼèlòhi֗ym hiné̇֨h ʼánòki֣y báʼ֮ ʼel-bĕ̇né֣y yişĕ̂ráʼél֒ wĕ⁠ʼámarĕţi֣̇y lá⁠he֔m ʼèlòhé֥y ʼàbwòţéy⁠ke֖m şĕ̌láẖa֣⁠niy ʼàléy⁠ke֑m wĕ⁠ʼáֽmĕrẇ-li֣⁠y mah-şĕ̇̌m֔⁠wò má֥h ʼòma֖r ʼàlé⁠heֽm׃"],[3,14,"וַ⁠יֹּ֤אמֶר אֱלֹהִים֙ אֶל־מֹשֶׁ֔ה אֶֽהְיֶ֖ה אֲשֶׁ֣ר אֶֽהְיֶ֑ה וַ⁠יֹּ֗אמֶר כֹּ֤ה תֹאמַר֙ לִ⁠בְנֵ֣י יִשְׂרָאֵ֔ל אֶֽהְיֶ֖ה שְׁלָחַ֥⁠נִי אֲלֵי⁠כֶֽם׃","wa⁠yò֤̇ʼmer ʼèlòhiym֙ ʼel-mòşě֔h ʼeֽhĕye֖h ʼàşě֣r ʼeֽhĕye֑h wa⁠yò̇֗ʼmer kò֤̇h ţòʼmar֙ li⁠bĕné֣y yişĕ̂ráʼé֔l ʼeֽhĕye֖h şĕ̌láẖa֥⁠niy ʼàléy⁠keֽm׃"],[3,15,"וַ⁠יֹּאמֶר֩ ע֨וֹד אֱלֹהִ֜ים אֶל־מֹשֶׁ֗ה כֹּֽה־תֹאמַר֮ אֶל־בְּנֵ֣י יִשְׂרָאֵל֒ יְהוָ֞ה אֱלֹהֵ֣י אֲבֹתֵי⁠כֶ֗ם אֱלֹהֵ֨י אַבְרָהָ֜ם אֱלֹהֵ֥י יִצְחָ֛ק וֵ⁠אלֹהֵ֥י יַעֲקֹ֖ב שְׁלָחַ֣⁠נִי אֲלֵי⁠כֶ֑ם זֶה־שְּׁמִ֣⁠י לְ⁠עֹלָ֔ם וְ⁠זֶ֥ה זִכְרִ֖⁠י לְ⁠דֹ֥ר דֹּֽר׃","wa⁠yò̇ʼmer֩ ʻ֨wòd ʼèlòhi֜ym ʼel-mòşě֗h kòֽ̇h-ţòʼmar֮ ʼel-bĕ̇né֣y yişĕ̂ráʼél֒ yĕhwá֞h ʼèlòhé֣y ʼàbòţéy⁠ke֗m ʼèlòhé֨y ʼabĕráhá֜m ʼèlòhé֥y yiẕĕẖá֛q wé⁠ʼlòhé֥y yaʻàqò֖b şĕ̌láẖa֣⁠niy ʼàléy⁠ke֑m zeh-şĕ̇̌mi֣⁠y lĕ⁠ʻòlá֔m wĕ⁠ze֥h zikĕri֖⁠y lĕ⁠dò֥r dòֽ̇r׃"],[3,16,"לֵ֣ךְ וְ⁠אָֽסַפְתָּ֞ אֶת־זִקְנֵ֣י יִשְׂרָאֵ֗ל וְ⁠אָמַרְתָּ֤ אֲלֵ⁠הֶם֙ יְהוָ֞ה אֱלֹהֵ֤י אֲבֹֽתֵי⁠כֶם֙ נִרְאָ֣ה אֵלַ֔⁠י אֱלֹהֵ֧י אַבְרָהָ֛ם יִצְחָ֥ק וְ⁠יַעֲקֹ֖ב לֵ⁠אמֹ֑ר פָּקֹ֤ד פָּקַ֨דְתִּי֙ אֶתְ⁠כֶ֔ם וְ⁠אֶת־הֶ⁠עָשׂ֥וּי לָ⁠כֶ֖ם בְּ⁠מִצְרָֽיִם׃","lé֣kĕ wĕ⁠ʼáֽsapĕţá̇֞ ʼeţ-ziqĕné֣y yişĕ̂ráʼé֗l wĕ⁠ʼámarĕţá֤̇ ʼàlé⁠hem֙ yĕhwá֞h ʼèlòhé֤y ʼàbòֽţéy⁠kem֙ nirĕʼá֣h ʼéla֔⁠y ʼèlòhé֧y ʼabĕráhá֛m yiẕĕẖá֥q wĕ⁠yaʻàqò֖b lé⁠ʼmò֑r pá̇qò֤d pá̇qa֨dĕţi̇y֙ ʼeţĕ⁠ke֔m wĕ⁠ʼeţ-he⁠ʻáş֥̂ẇy lá⁠ke֖m bĕ̇⁠miẕĕráֽyim׃"],[3,17,"וָ⁠אֹמַ֗ר אַעֲלֶ֣ה אֶתְ⁠כֶם֮ מֵ⁠עֳנִ֣י מִצְרַיִם֒ אֶל־אֶ֤רֶץ הַֽ⁠כְּנַעֲנִי֙ וְ⁠הַ֣⁠חִתִּ֔י וְ⁠הָֽ⁠אֱמֹרִי֙ וְ⁠הַ⁠פְּרִזִּ֔י וְ⁠הַ⁠חִוִּ֖י וְ⁠הַ⁠יְבוּסִ֑י אֶל־אֶ֛רֶץ זָבַ֥ת חָלָ֖ב וּ⁠דְבָֽשׁ׃","wá⁠ʼòma֗r ʼaʻàle֣h ʼeţĕ⁠kem֮ mé⁠ʻoni֣y miẕĕrayim֒ ʼel-ʼe֤reẕ haֽ⁠kĕ̇naʻàniy֙ wĕ⁠ha֣⁠ẖiţi̇֔y wĕ⁠háֽ⁠ʼèmòriy֙ wĕ⁠ha⁠pĕ̇rizi̇֔y wĕ⁠ha⁠ẖiwi֖̇y wĕ⁠ha⁠yĕbẇsi֑y ʼel-ʼe֛reẕ zába֥ţ ẖálá֖b ẇ⁠dĕbáֽş̌׃"],[3,18,"וְ⁠שָׁמְע֖וּ לְ⁠קֹלֶ֑⁠ךָ וּ⁠בָאתָ֡ אַתָּה֩ וְ⁠זִקְנֵ֨י יִשְׂרָאֵ֜ל אֶל־מֶ֣לֶךְ מִצְרַ֗יִם וַ⁠אֲמַרְתֶּ֤ם אֵלָי⁠ו֙ יְהוָ֞ה אֱלֹהֵ֤י הָֽ⁠עִבְרִיִּים֙ נִקְרָ֣ה עָלֵ֔י⁠נוּ וְ⁠עַתָּ֗ה נֵֽלֲכָה־נָּ֞א דֶּ֣רֶךְ שְׁלֹ֤שֶׁת יָמִים֙ בַּ⁠מִּדְבָּ֔ר וְ⁠נִזְבְּחָ֖ה לַֽ⁠יהוָ֥ה אֱלֹהֵֽי⁠נוּ׃","wĕ⁠şá̌mĕʻ֖ẇ lĕ⁠qòle֑⁠ká ẇ⁠báʼţá֡ ʼaţá̇h֩ wĕ⁠ziqĕné֨y yişĕ̂ráʼé֜l ʼel-me֣lekĕ miẕĕra֗yim wa⁠ʼàmarĕţė֤m ʼéláy⁠w֙ yĕhwá֞h ʼèlòhé֤y háֽ⁠ʻibĕriyi̇ym֙ niqĕrá֣h ʻálé֔y⁠nẇ wĕ⁠ʻaţá̇֗h néֽlàkáh-ná̇֞ʼ dė֣rekĕ şĕ̌lò֤şěţ yámiym֙ bȧ⁠mi̇dĕbá̇֔r wĕ⁠nizĕbĕ̇ẖá֖h laֽ⁠yhwá֥h ʼèlòhéֽy⁠nẇ׃"],[3,19,"וַ⁠אֲנִ֣י יָדַ֔עְתִּי כִּ֠י לֹֽא־יִתֵּ֥ן אֶתְ⁠כֶ֛ם מֶ֥לֶךְ מִצְרַ֖יִם לַ⁠הֲלֹ֑ךְ וְ⁠לֹ֖א בְּ⁠יָ֥ד חֲזָקָֽה׃","wa⁠ʼàni֣y yáda֔ʻĕţi̇y ki̇֠y lòֽʼ-yiţé֥̇n ʼeţĕ⁠ke֛m me֥lekĕ miẕĕra֖yim la⁠hàlò֑kĕ wĕ⁠lò֖ʼ bĕ̇⁠yá֥d ẖàzáqáֽh׃"],[3,20,"וְ⁠שָׁלַחְתִּ֤י אֶת־יָדִ⁠י֙ וְ⁠הִכֵּיתִ֣י אֶת־מִצְרַ֔יִם בְּ⁠כֹל֙ נִפְלְאֹתַ֔⁠י אֲשֶׁ֥ר אֶֽעֱשֶׂ֖ה בְּ⁠קִרְבּ֑⁠וֹ וְ⁠אַחֲרֵי־כֵ֖ן יְשַׁלַּ֥ח אֶתְ⁠כֶֽם׃","wĕ⁠şá̌laẖĕţi֤̇y ʼeţ-yádi⁠y֙ wĕ⁠hiké̇yţi֣y ʼeţ-miẕĕra֔yim bĕ̇⁠kòl֙ nipĕlĕʼòţa֔⁠y ʼàşě֥r ʼֽeʻèşê֖h bĕ̇⁠qirĕḃ֑⁠wò wĕ⁠ʼaẖàréy-ké֖n yĕşǎlȧ֥ẖ ʼeţĕ⁠keֽm׃"],[3,21,"וְ⁠נָתַתִּ֛י אֶת־חֵ֥ן הָֽ⁠עָם־הַ⁠זֶּ֖ה בְּ⁠עֵינֵ֣י מִצְרָ֑יִם וְ⁠הָיָה֙ כִּ֣י תֵֽלֵכ֔וּ⁠ן לֹ֥א תֵלְכ֖וּ רֵיקָֽם׃","wĕ⁠náţaţi֛̇y ʼeţ-ẖé֥n háֽ⁠ʻám-ha⁠zė֖h bĕ̇⁠ʻéyné֣y miẕĕrá֑yim wĕ⁠háyáh֙ ki֣̇y ţéֽlék֔ẇ⁠n lò֥ʼ ţélĕk֖ẇ réyqáֽm׃"],[3,22,"וְ⁠שָׁאֲלָ֨ה אִשָּׁ֤ה מִ⁠שְּׁכֶנְתָּ⁠הּ֙ וּ⁠מִ⁠גָּרַ֣ת בֵּיתָ֔⁠הּ כְּלֵי־כֶ֛סֶף וּ⁠כְלֵ֥י זָהָ֖ב וּ⁠שְׂמָלֹ֑ת וְ⁠שַׂמְתֶּ֗ם עַל־בְּנֵי⁠כֶם֙ וְ⁠עַל־בְּנֹ֣תֵי⁠כֶ֔ם וְ⁠נִצַּלְתֶּ֖ם אֶת־מִצְרָֽיִם׃","wĕ⁠şá̌ʼàlá֨h ʼişá֤̇̌h mi⁠şĕ̇̌kenĕţá̇⁠ḣ֙ ẇ⁠mi⁠gá̇ra֣ţ bé̇yţá֔⁠ḣ kĕ̇léy-ke֛sep ẇ⁠kĕlé֥y záhá֖b ẇ⁠şĕ̂málò֑ţ wĕ⁠şâmĕţė֗m ʻal-bĕ̇néy⁠kem֙ wĕ⁠ʻal-bĕ̇nò֣ţéy⁠ke֔m wĕ⁠niẕȧlĕţė֖m ʼeţ-miẕĕráֽyim׃"],[4,1,"וַ⁠יַּ֤עַן מֹשֶׁה֙ וַ⁠יֹּ֔אמֶר וְ⁠הֵן֙ לֹֽא־יַאֲמִ֣ינוּ לִ֔⁠י וְ⁠לֹ֥א יִשְׁמְע֖וּ בְּ⁠קֹלִ֑⁠י כִּ֣י יֹֽאמְר֔וּ לֹֽא־נִרְאָ֥ה אֵלֶ֖י⁠ךָ יְהוָֽה׃","wa⁠yȧ֤ʻan mòşěh֙ wa⁠yò̇֔ʼmer wĕ⁠hén֙ lòֽʼ-yaʼàmi֣ynẇ li֔⁠y wĕ⁠lò֥ʼ yişĕ̌mĕʻ֖ẇ bĕ̇⁠qòli֑⁠y ki֣̇y yòֽʼmĕr֔ẇ lòֽʼ-nirĕʼá֥h ʼéle֖y⁠ká yĕhwáֽh׃"],[4,2,"וַ⁠יֹּ֧אמֶר אֵלָ֛י⁠ו יְהוָ֖ה מ⁠זה בְ⁠יָדֶ֑⁠ךָ וַ⁠יֹּ֖אמֶר מַטֶּֽה׃","wa⁠yò֧̇ʼmer ʼélá֛y⁠w yĕhwá֖h m⁠zh bĕ⁠yáde֑⁠ká wa⁠yò֖̇ʼmer matėֽh׃"],[4,3,"וַ⁠יֹּ֨אמֶר֙ הַשְׁלִיכֵ֣⁠הוּ אַ֔רְצָ⁠ה וַ⁠יַּשְׁלִיכֵ֥⁠הוּ אַ֖רְצָ⁠ה וַ⁠יְהִ֣י לְ⁠נָחָ֑שׁ וַ⁠יָּ֥נָס מֹשֶׁ֖ה מִ⁠פָּנָֽי⁠ו׃","wa⁠yò̇֨ʼmer֙ haşĕ̌liyké֣⁠hẇ ʼa֔rĕẕá⁠h wa⁠yȧşĕ̌liyké֥⁠hẇ ʼa֖rĕẕá⁠h wa⁠yĕhi֣y lĕ⁠náẖá֑ş̌ wa⁠yá֥̇nás mòşě֖h mi⁠pá̇náֽy⁠w׃"],[4,4,"וַ⁠יֹּ֤אמֶר יְהוָה֙ אֶל־מֹשֶׁ֔ה שְׁלַח֙ יָֽדְ⁠ךָ֔ וֶ⁠אֱחֹ֖ז בִּ⁠זְנָב֑⁠וֹ וַ⁠יִּשְׁלַ֤ח יָד⁠וֹ֙ וַ⁠יַּ֣חֲזֶק בּ֔⁠וֹ וַ⁠יְהִ֥י לְ⁠מַטֶּ֖ה בְּ⁠כַפּֽ⁠וֹ׃","wa⁠yò֤̇ʼmer yĕhwáh֙ ʼel-mòşě֔h şĕ̌laẖ֙ yáֽdĕ⁠ká֔ we⁠ʼèẖò֖z bi̇⁠zĕnáb֑⁠wò wa⁠yi̇şĕ̌la֤ẖ yád⁠wò֙ wa⁠yȧ֣ẖàzeq ḃ֔⁠wò wa⁠yĕhi֥y lĕ⁠matė֖h bĕ̇⁠kaṗֽ⁠wò׃"],[4,5,"לְמַ֣עַן יַאֲמִ֔ינוּ כִּֽי־נִרְאָ֥ה אֵלֶ֛י⁠ךָ יְהוָ֖ה אֱלֹהֵ֣י אֲבֹתָ֑⁠ם אֱלֹהֵ֧י אַבְרָהָ֛ם אֱלֹהֵ֥י יִצְחָ֖ק וֵ⁠אלֹהֵ֥י יַעֲקֹֽב׃","lĕma֣ʻan yaʼàmi֔ynẇ kiֽ̇y-nirĕʼá֥h ʼéle֛y⁠ká yĕhwá֖h ʼèlòhé֣y ʼàbòţá֑⁠m ʼèlòhé֧y ʼabĕráhá֛m ʼèlòhé֥y yiẕĕẖá֖q wé⁠ʼlòhé֥y yaʻàqòֽb׃"],[4,6,"וַ⁠יֹּאמֶר֩ יְהוָ֨ה ל֜⁠וֹ ע֗וֹד הָֽבֵא־נָ֤א יָֽדְ⁠ךָ֙ בְּ⁠חֵיקֶ֔⁠ךָ וַ⁠יָּבֵ֥א יָד֖⁠וֹ בְּ⁠חֵיק֑⁠וֹ וַ⁠יּ֣וֹצִאָ֔⁠הּ וְ⁠הִנֵּ֥ה יָד֖⁠וֹ מְצֹרַ֥עַת כַּ⁠שָּֽׁלֶג׃","wa⁠yò̇ʼmer֩ yĕhwá֨h l֜⁠wò ʻ֗wòd háֽbéʼ-ná֤ʼ yáֽdĕ⁠ká֙ bĕ̇⁠ẖéyqe֔⁠ká wa⁠yá̇bé֥ʼ yád֖⁠wò bĕ̇⁠ẖéyq֑⁠wò wa⁠ẏ֣wòẕiʼá֔⁠ḣ wĕ⁠hiné֥̇h yád֖⁠wò mĕẕòra֥ʻaţ kȧ⁠şáֽ̇̌leg׃"],[4,7,"וַ⁠יֹּ֗אמֶר הָשֵׁ֤ב יָֽדְ⁠ךָ֙ אֶל־חֵיקֶ֔⁠ךָ וַ⁠יָּ֥שֶׁב יָד֖⁠וֹ אֶל־חֵיק֑⁠וֹ וַ⁠יּֽוֹצִאָ⁠הּ֙ מֵֽ⁠חֵיק֔⁠וֹ וְ⁠הִנֵּה־שָׁ֖בָה כִּ⁠בְשָׂרֽ⁠וֹ׃","wa⁠yò̇֗ʼmer háşé֤̌b yáֽdĕ⁠ká֙ ʼel-ẖéyqe֔⁠ká wa⁠yá֥̇şěb yád֖⁠wò ʼel-ẖéyq֑⁠wò wa⁠ẏֽwòẕiʼá⁠ḣ֙ méֽ⁠ẖéyq֔⁠wò wĕ⁠hiné̇h-şá֖̌báh ki̇⁠bĕşá̂rֽ⁠wò׃"],[4,8,"וְ⁠הָיָה֙ אִם־לֹ֣א יַאֲמִ֣ינוּ לָ֔⁠ךְ וְ⁠לֹ֣א יִשְׁמְע֔וּ לְ⁠קֹ֖ל הָ⁠אֹ֣ת הָ⁠רִאשׁ֑וֹן וְ⁠הֶֽאֱמִ֔ינוּ לְ⁠קֹ֖ל הָ⁠אֹ֥ת הָ⁠אַחֲרֽוֹן׃","wĕ⁠háyáh֙ ʼim-lò֣ʼ yaʼàmi֣ynẇ lá֔⁠kĕ wĕ⁠lò֣ʼ yişĕ̌mĕʻ֔ẇ lĕ⁠qò֖l há⁠ʼò֣ţ há⁠riʼş֑̌wòn wĕ⁠heֽʼèmi֔ynẇ lĕ⁠qò֖l há⁠ʼò֥ţ há⁠ʼaẖàrֽwòn׃"],[4,9,"וְ⁠הָיָ֡ה אִם־לֹ֣א יַאֲמִ֡ינוּ גַּם֩ לִ⁠שְׁנֵ֨י הָ⁠אֹת֜וֹת הָ⁠אֵ֗לֶּה וְ⁠לֹ֤א יִשְׁמְעוּ⁠ן֙ לְ⁠קֹלֶ֔⁠ךָ וְ⁠לָקַחְתָּ֙ מִ⁠מֵּימֵ֣י הַ⁠יְאֹ֔ר וְ⁠שָׁפַכְתָּ֖ הַ⁠יַּבָּשָׁ֑ה וְ⁠הָי֤וּ הַ⁠מַּ֨יִם֙ אֲשֶׁ֣ר תִּקַּ֣ח מִן־הַ⁠יְאֹ֔ר וְ⁠הָי֥וּ לְ⁠דָ֖ם בַּ⁠יַּבָּֽשֶׁת׃","wĕ⁠háyá֡h ʼim-lò֣ʼ yaʼàmi֡ynẇ gȧm֩ li⁠şĕ̌né֨y há⁠ʼòţ֜wòţ há⁠ʼé֗lėh wĕ⁠lò֤ʼ yişĕ̌mĕʻẇ⁠n֙ lĕ⁠qòle֔⁠ká wĕ⁠láqaẖĕţá̇֙ mi⁠mé̇ymé֣y ha⁠yĕʼò֔r wĕ⁠şá̌pakĕţá֖̇ ha⁠yȧbá̇şá֑̌h wĕ⁠háy֤ẇ ha⁠mȧ֨yim֙ ʼàşě֣r ţi̇qȧ֣ẖ min-ha⁠yĕʼò֔r wĕ⁠háy֥ẇ lĕ⁠dá֖m bȧ⁠yȧbáֽ̇şěţ׃"],[4,10,"וַ⁠יֹּ֨אמֶר מֹשֶׁ֣ה אֶל־יְהוָה֮ בִּ֣י אֲדֹנָ⁠י֒ לֹא֩ אִ֨ישׁ דְּבָרִ֜ים אָנֹ֗כִי גַּ֤ם מִ⁠תְּמוֹל֙ גַּ֣ם מִ⁠שִּׁלְשֹׁ֔ם גַּ֛ם מֵ⁠אָ֥ז דַּבֶּרְ⁠ךָ אֶל־עַבְדֶּ֑⁠ךָ כִּ֧י כְבַד־פֶּ֛ה וּ⁠כְבַ֥ד לָשׁ֖וֹן אָנֹֽכִי׃","wa⁠yò̇֨ʼmer mòşě֣h ʼel-yĕhwáh֮ bi֣̇y ʼàdòná⁠y֒ lòʼ֩ ʼi֨yş̌ dĕ̇bári֜ym ʼánò֗kiy gȧ֤m mi⁠ţĕ̇mwòl֙ gȧ֣m mi⁠şi̇̌lĕşò̌֔m gȧ֛m mé⁠ʼá֥z dȧbėrĕ⁠ká ʼel-ʻabĕdė֑⁠ká ki֧̇y kĕbad-pė֛h ẇ⁠kĕba֥d láş֖̌wòn ʼánòֽkiy׃"],[4,11,"וַ⁠יֹּ֨אמֶר יְהוָ֜ה אֵלָ֗י⁠ו מִ֣י שָׂ֣ם פֶּה֮ לָֽ⁠אָדָם֒ א֚וֹ מִֽי־יָשׂ֣וּם אִלֵּ֔ם א֣וֹ חֵרֵ֔שׁ א֥וֹ פִקֵּ֖חַ א֣וֹ עִוֵּ֑ר הֲ⁠לֹ֥א אָנֹכִ֖י יְהוָֽה׃","wa⁠yò̇֨ʼmer yĕhwá֜h ʼélá֗y⁠w mi֣y şá֣̂m pėh֮ láֽ⁠ʼádám֒ ʼ֚wò miֽy-yáş֣̂ẇm ʼilé̇֔m ʼ֣wò ẖéré֔ş̌ ʼ֥wò piqé֖̇ẖa ʼ֣wò ʻiwé֑̇r hà⁠lò֥ʼ ʼánòki֖y yĕhwáֽh׃"],[4,12,"וְ⁠עַתָּ֖ה לֵ֑ךְ וְ⁠אָנֹכִי֙ אֶֽהְיֶ֣ה עִם־פִּ֔י⁠ךָ וְ⁠הוֹרֵיתִ֖י⁠ךָ אֲשֶׁ֥ר תְּדַבֵּֽר׃","wĕ⁠ʻaţá֖̇h lé֑kĕ wĕ⁠ʼánòkiy֙ ʼeֽhĕye֣h ʻim-pi̇֔y⁠ká wĕ⁠hwòréyţi֖y⁠ká ʼàşě֥r ţĕ̇dabéֽ̇r׃"],[4,13,"וַ⁠יֹּ֖אמֶר בִּ֣י אֲדֹנָ֑⁠י שְֽׁלַֽח־נָ֖א בְּ⁠יַד־תִּשְׁלָֽח׃","wa⁠yò֖̇ʼmer bi֣̇y ʼàdòná֑⁠y şĕֽ̌laֽẖ-ná֖ʼ bĕ̇⁠yad-ţi̇şĕ̌láֽẖ׃"],[4,14,"וַ⁠יִּֽחַר־אַ֨ף יְהוָ֜ה בְּ⁠מֹשֶׁ֗ה וַ⁠יֹּ֨אמֶר֙ הֲ⁠לֹ֨א אַהֲרֹ֤ן אָחִ֨י⁠ךָ֙ הַ⁠לֵּוִ֔י יָדַ֕עְתִּי כִּֽי־דַבֵּ֥ר יְדַבֵּ֖ר ה֑וּא וְ⁠גַ֤ם הִנֵּה־הוּא֙ יֹצֵ֣א לִ⁠קְרָאתֶ֔⁠ךָ וְ⁠רָאֲ⁠ךָ֖ וְ⁠שָׂמַ֥ח בְּ⁠לִבּֽ⁠וֹ׃","wa⁠yiֽ̇ẖar-ʼa֨p yĕhwá֜h bĕ̇⁠mòşě֗h wa⁠yò̇֨ʼmer֙ hà⁠lò֨ʼ ʼahàrò֤n ʼáẖi֨y⁠ká֙ ha⁠lé̇wi֔y yáda֕ʻĕţi̇y kiֽ̇y-dabé֥̇r yĕdabé֖̇r h֑ẇʼ wĕ⁠ga֤m hiné̇h-hẇʼ֙ yòẕé֣ʼ li⁠qĕráʼţe֔⁠ká wĕ⁠ráʼà⁠ká֖ wĕ⁠şá̂ma֥ẖ bĕ̇⁠liḃֽ⁠wò׃"],[4,15,"וְ⁠דִבַּרְתָּ֣ אֵלָ֔י⁠ו וְ⁠שַׂמְתָּ֥ אֶת־הַ⁠דְּבָרִ֖ים בְּ⁠פִ֑י⁠ו וְ⁠אָנֹכִ֗י אֶֽהְיֶ֤ה עִם־פִּ֨י⁠ךָ֙ וְ⁠עִם־פִּ֔י⁠הוּ וְ⁠הוֹרֵיתִ֣י אֶתְ⁠כֶ֔ם אֵ֖ת אֲשֶׁ֥ר תַּעֲשֽׂוּ⁠ן׃","wĕ⁠dibȧrĕţá֣̇ ʼélá֔y⁠w wĕ⁠şâmĕţá֥̇ ʼeţ-ha⁠dĕ̇bári֖ym bĕ̇⁠pi֑y⁠w wĕ⁠ʼánòki֗y ʼeֽhĕye֤h ʻim-pi̇֨y⁠ká֙ wĕ⁠ʻim-pi̇֔y⁠hẇ wĕ⁠hwòréyţi֣y ʼeţĕ⁠ke֔m ʼé֖ţ ʼàşě֥r ţȧʻàşֽ̂ẇ⁠n׃"],[4,16,"וְ⁠דִבֶּר־ה֥וּא לְ⁠ךָ֖ אֶל־הָ⁠עָ֑ם וְ⁠הָ֤יָה הוּא֙ יִֽהְיֶה־לְּ⁠ךָ֣ לְ⁠פֶ֔ה וְ⁠אַתָּ֖ה תִּֽהְיֶה־לּ֥⁠וֹ לֵֽ⁠אלֹהִֽים׃","wĕ⁠dibėr-h֥ẇʼ lĕ⁠ká֖ ʼel-há⁠ʻá֑m wĕ⁠há֤yáh hẇʼ֙ yiֽhĕyeh-lĕ̇⁠ká֣ lĕ⁠pe֔h wĕ⁠ʼaţá֖̇h ţiֽ̇hĕyeh-l֥̇⁠wò léֽ⁠ʼlòhiֽym׃"],[4,17,"וְ⁠אֶת־הַ⁠מַּטֶּ֥ה הַ⁠זֶּ֖ה תִּקַּ֣ח בְּ⁠יָדֶ֑⁠ךָ אֲשֶׁ֥ר תַּעֲשֶׂה־בּ֖⁠וֹ אֶת־הָ⁠אֹתֹֽת׃פ","wĕ⁠ʼeţ-ha⁠mȧtė֥h ha⁠zė֖h ţi̇qȧ֣ẖ bĕ̇⁠yáde֑⁠ká ʼàşě֥r ţȧʻàşêh-ḃ֖⁠wò ʼeţ-há⁠ʼòţòֽţ׃p"],[4,18,"וַ⁠יֵּ֨לֶךְ מֹשֶׁ֜ה וַ⁠יָּ֣שָׁב ׀ אֶל־יֶ֣תֶר חֹֽתְנ֗⁠וֹ וַ⁠יֹּ֤אמֶר ל⁠וֹ֙ אֵ֣לֲכָה נָּ֗א וְ⁠אָשׁ֨וּבָה֙ אֶל־אַחַ֣⁠י אֲשֶׁר־בְּ⁠מִצְרַ֔יִם וְ⁠אֶרְאֶ֖ה הַ⁠עוֹדָ֣⁠ם חַיִּ֑ים וַ⁠יֹּ֧אמֶר יִתְר֛וֹ לְ⁠מֹשֶׁ֖ה לֵ֥ךְ לְ⁠שָׁלֽוֹם׃","wa⁠yé̇֨lekĕ mòşě֜h wa⁠yá֣̇şá̌b ׀ ʼel-ye֣ţer ẖòֽţĕn֗⁠wò wa⁠yò֤̇ʼmer l⁠wò֙ ʼé֣làkáh ná̇֗ʼ wĕ⁠ʼáş̌֨ẇbáh֙ ʼel-ʼaẖa֣⁠y ʼàşěr-bĕ̇⁠miẕĕra֔yim wĕ⁠ʼerĕʼe֖h ha⁠ʻwòdá֣⁠m ẖayi֑̇ym wa⁠yò֧̇ʼmer yiţĕr֛wò lĕ⁠mòşě֖h lé֥kĕ lĕ⁠şá̌lֽwòm׃"],[4,19,"וַ⁠יֹּ֨אמֶר יְהוָ֤ה אֶל־מֹשֶׁה֙ בְּ⁠מִדְיָ֔ן לֵ֖ךְ שֻׁ֣ב מִצְרָ֑יִם כִּי־מֵ֨תוּ֙ כָּל־הָ֣⁠אֲנָשִׁ֔ים הַֽ⁠מְבַקְשִׁ֖ים אֶת־נַפְשֶֽׁ⁠ךָ׃","wa⁠yò̇֨ʼmer yĕhwá֤h ʼel-mòşěh֙ bĕ̇⁠midĕyá֔n lé֖kĕ şǔ֣b miẕĕrá֑yim ki̇y-mé֨ţẇ֙ ká̇l-há֣⁠ʼànáşǐ֔ym haֽ⁠mĕbaqĕşǐ֖ym ʼeţ-napĕşěֽ⁠ká׃"],[4,20,"וַ⁠יִּקַּ֨ח מֹשֶׁ֜ה אֶת־אִשְׁתּ֣⁠וֹ וְ⁠אֶת־בָּנָ֗י⁠ו וַ⁠יַּרְכִּבֵ⁠ם֙ עַֽל־הַ⁠חֲמֹ֔ר וַ⁠יָּ֖שָׁב אַ֣רְצָ⁠ה מִצְרָ֑יִם וַ⁠יִּקַּ֥ח מֹשֶׁ֛ה אֶת־מַטֵּ֥ה הָ⁠אֱלֹהִ֖ים בְּ⁠יָדֽ⁠וֹ׃","wa⁠yi̇qȧ֨ẖ mòşě֜h ʼeţ-ʼişĕ̌ţ֣̇⁠wò wĕ⁠ʼeţ-bá̇ná֗y⁠w wa⁠yȧrĕki̇bé⁠m֙ ʻaֽl-ha⁠ẖàmò֔r wa⁠yá֖̇şá̌b ʼa֣rĕẕá⁠h miẕĕrá֑yim wa⁠yi̇qȧ֥ẖ mòşě֛h ʼeţ-maté֥̇h há⁠ʼèlòhi֖ym bĕ̇⁠yádֽ⁠wò׃"],[4,21,"וַ⁠יֹּ֣אמֶר יְהוָה֮ אֶל־מֹשֶׁה֒ בְּ⁠לֶכְתְּ⁠ךָ֙ לָ⁠שׁ֣וּב מִצְרַ֔יְמָ⁠ה רְאֵ֗ה כָּל־הַ⁠מֹּֽפְתִים֙ אֲשֶׁר־שַׂ֣מְתִּי בְ⁠יָדֶ֔⁠ךָ וַ⁠עֲשִׂיתָ֖⁠ם לִ⁠פְנֵ֣י פַרְעֹ֑ה וַ⁠אֲנִי֙ אֲחַזֵּ֣ק אֶת־לִבּ֔⁠וֹ וְ⁠לֹ֥א יְשַׁלַּ֖ח אֶת־הָ⁠עָֽם׃","wa⁠yò֣̇ʼmer yĕhwáh֮ ʼel-mòşěh֒ bĕ̇⁠lekĕţĕ̇⁠ká֙ lá⁠ş֣̌ẇb miẕĕra֔yĕmá⁠h rĕʼé֗h ká̇l-ha⁠mòֽ̇pĕţiym֙ ʼàşěr-şâ֣mĕţi̇y bĕ⁠yáde֔⁠ká wa⁠ʻàşîyţá֖⁠m li⁠pĕné֣y parĕʻò֑h wa⁠ʼàniy֙ ʼàẖazé֣̇q ʼeţ-liḃ֔⁠wò wĕ⁠lò֥ʼ yĕşǎlȧ֖ẖ ʼeţ-há⁠ʻáֽm׃"],[4,22,"וְ⁠אָמַרְתָּ֖ אֶל־פַּרְעֹ֑ה כֹּ֚ה אָמַ֣ר יְהוָ֔ה בְּנִ֥⁠י בְכֹרִ֖⁠י יִשְׂרָאֵֽל׃","wĕ⁠ʼámarĕţá֖̇ ʼel-pȧrĕʻò֑h kò֚̇h ʼáma֣r yĕhwá֔h bĕ̇ni֥⁠y bĕkòri֖⁠y yişĕ̂ráʼéֽl׃"],[4,23,"וָ⁠אֹמַ֣ר אֵלֶ֗י⁠ךָ שַׁלַּ֤ח אֶת־בְּנִ⁠י֙ וְ⁠יַֽעַבְדֵ֔⁠נִי וַ⁠תְּמָאֵ֖ן לְ⁠שַׁלְּח֑⁠וֹ הִנֵּה֙ אָנֹכִ֣י הֹרֵ֔ג אֶת־בִּנְ⁠ךָ֖ בְּכֹרֶֽ⁠ךָ׃","wá⁠ʼòma֣r ʼéle֗y⁠ká şǎlȧ֤ẖ ʼeţ-bĕ̇ni⁠y֙ wĕ⁠yaֽʻabĕdé֔⁠niy wa⁠ţĕ̇máʼé֖n lĕ⁠şǎlĕ̇ẖ֑⁠wò hiné̇h֙ ʼánòki֣y hòré֔g ʼeţ-bi̇nĕ⁠ká֖ bĕ̇kòreֽ⁠ká׃"],[4,24,"וַ⁠יְהִ֥י בַ⁠דֶּ֖רֶךְ בַּ⁠מָּל֑וֹן וַ⁠יִּפְגְּשֵׁ֣⁠הוּ יְהוָ֔ה וַ⁠יְבַקֵּ֖שׁ הֲמִיתֽ⁠וֹ׃","wa⁠yĕhi֥y ba⁠dė֖rekĕ bȧ⁠má̇l֑wòn wa⁠yi̇pĕgĕ̇şé֣̌⁠hẇ yĕhwá֔h wa⁠yĕbaqé֖̇ş̌ hàmiyţֽ⁠wò׃"],[4,25,"וַ⁠תִּקַּ֨ח צִפֹּרָ֜ה צֹ֗ר וַ⁠תִּכְרֹת֙ אֶת־עָרְלַ֣ת בְּנָ֔⁠הּ וַ⁠תַּגַּ֖ע לְ⁠רַגְלָ֑י⁠ו וַ⁠תֹּ֕אמֶר כִּ֧י חֲתַן־דָּמִ֛ים אַתָּ֖ה לִֽ⁠י׃","wa⁠ţi̇qȧ֨ẖ ẕipò̇rá֜h ẕò֗r wa⁠ţi̇kĕròţ֙ ʼeţ-ʻárĕla֣ţ bĕ̇ná֔⁠ḣ wa⁠ţȧgȧ֖ʻ lĕ⁠ragĕlá֑y⁠w wa⁠ţò̇֕ʼmer ki֧̇y ẖàţan-dá̇mi֛ym ʼaţá֖̇h liֽ⁠y׃"],[4,26,"וַ⁠יִּ֖רֶף מִמֶּ֑⁠נּוּ אָ֚ז אָֽמְרָ֔ה חֲתַ֥ן דָּמִ֖ים לַ⁠מּוּלֹֽת׃פ","wa⁠yi֖̇rep mimė֑⁠ṅẇ ʼá֚z ʼáֽmĕrá֔h ẖàţa֥n dá̇mi֖ym la⁠ṁẇlòֽţ׃p"],[4,27,"וַ⁠יֹּ֤אמֶר יְהוָה֙ אֶֽל־אַהֲרֹ֔ן לֵ֛ךְ לִ⁠קְרַ֥את מֹשֶׁ֖ה הַ⁠מִּדְבָּ֑רָ⁠ה וַ⁠יֵּ֗לֶךְ וַֽ⁠יִּפְגְּשֵׁ֛⁠הוּ בְּ⁠הַ֥ר הָ⁠אֱלֹהִ֖ים וַ⁠יִּשַּׁק־לֽ⁠וֹ׃","wa⁠yò֤̇ʼmer yĕhwáh֙ ʼeֽl-ʼahàrò֔n lé֛kĕ li⁠qĕra֥ʼţ mòşě֖h ha⁠mi̇dĕbá֑̇rá⁠h wa⁠yé̇֗lekĕ waֽ⁠yi̇pĕgĕ̇şé֛̌⁠hẇ bĕ̇⁠ha֥r há⁠ʼèlòhi֖ym wa⁠yi̇şȧ̌q-lֽ⁠wò׃"],[4,28,"וַ⁠יַּגֵּ֤ד מֹשֶׁה֙ לְ⁠אַֽהֲרֹ֔ן אֵ֛ת כָּל־דִּבְרֵ֥י יְהוָ֖ה אֲשֶׁ֣ר שְׁלָח֑⁠וֹ וְ⁠אֵ֥ת כָּל־הָ⁠אֹתֹ֖ת אֲשֶׁ֥ר צִוָּֽ⁠הוּ׃","wa⁠yȧgé֤̇d mòşěh֙ lĕ⁠ʼaֽhàrò֔n ʼé֛ţ ká̇l-di̇bĕré֥y yĕhwá֖h ʼàşě֣r şĕ̌láẖ֑⁠wò wĕ⁠ʼé֥ţ ká̇l-há⁠ʼòţò֖ţ ʼàşě֥r ẕiwáֽ̇⁠hẇ׃"],[4,29,"וַ⁠יֵּ֥לֶךְ מֹשֶׁ֖ה וְ⁠אַהֲרֹ֑ן וַ⁠יַּ֣אַסְפ֔וּ אֶת־כָּל־זִקְנֵ֖י בְּנֵ֥י יִשְׂרָאֵֽל׃","wa⁠yé֥̇lekĕ mòşě֖h wĕ⁠ʼahàrò֑n wa⁠yȧ֣ʼasĕp֔ẇ ʼeţ-ká̇l-ziqĕné֖y bĕ̇né֥y yişĕ̂ráʼéֽl׃"],[4,30,"וַ⁠יְדַבֵּ֣ר אַהֲרֹ֔ן אֵ֚ת כָּל־הַ⁠דְּבָרִ֔ים אֲשֶׁר־דִּבֶּ֥ר יְהוָ֖ה אֶל־מֹשֶׁ֑ה וַ⁠יַּ֥עַשׂ הָ⁠אֹתֹ֖ת לְ⁠עֵינֵ֥י הָ⁠עָֽם׃","wa⁠yĕdabé֣̇r ʼahàrò֔n ʼé֚ţ ká̇l-ha⁠dĕ̇bári֔ym ʼàşěr-di̇bė֥r yĕhwá֖h ʼel-mòşě֑h wa⁠yȧ֥ʻaş̂ há⁠ʼòţò֖ţ lĕ⁠ʻéyné֥y há⁠ʻáֽm׃"],[4,31,"וַֽ⁠יַּאֲמֵ֖ן הָ⁠עָ֑ם וַֽ⁠יִּשְׁמְע֡וּ כִּֽי־פָקַ֨ד יְהוָ֜ה אֶת־בְּנֵ֣י יִשְׂרָאֵ֗ל וְ⁠כִ֤י רָאָה֙ אֶת־עָנְיָ֔⁠ם וַֽ⁠יִּקְּד֖וּ וַ⁠יִּֽשְׁתַּחֲוּֽוּ׃","waֽ⁠yȧʼàmé֖n há⁠ʻá֑m waֽ⁠yi̇şĕ̌mĕʻ֡ẇ kiֽ̇y-páqa֨d yĕhwá֜h ʼeţ-bĕ̇né֣y yişĕ̂ráʼé֗l wĕ⁠ki֤y ráʼáh֙ ʼeţ-ʻánĕyá֔⁠m waֽ⁠yi̇qĕ̇d֖ẇ wa⁠yiֽ̇şĕ̌ţȧẖàẇֽẇ׃"],[5,1,"וְ⁠אַחַ֗ר בָּ֚אוּ מֹשֶׁ֣ה וְ⁠אַהֲרֹ֔ן וַ⁠יֹּאמְר֖וּ אֶל־פַּרְעֹ֑ה כֹּֽה־אָמַ֤ר יְהוָה֙ אֱלֹהֵ֣י יִשְׂרָאֵ֔ל שַׁלַּח֙ אֶת־עַמִּ֔⁠י וְ⁠יָחֹ֥גּוּ לִ֖⁠י בַּ⁠מִּדְבָּֽר׃","wĕ⁠ʼaẖa֗r bá֚̇ʼẇ mòşě֣h wĕ⁠ʼahàrò֔n wa⁠yò̇ʼmĕr֖ẇ ʼel-pȧrĕʻò֑h kòֽ̇h-ʼáma֤r yĕhwáh֙ ʼèlòhé֣y yişĕ̂ráʼé֔l şǎlȧẖ֙ ʼeţ-ʻami̇֔⁠y wĕ⁠yáẖò֥ġẇ li֖⁠y bȧ⁠mi̇dĕbáֽ̇r׃"],[5,2,"וַ⁠יֹּ֣אמֶר פַּרְעֹ֔ה מִ֤י יְהוָה֙ אֲשֶׁ֣ר אֶשְׁמַ֣ע בְּ⁠קֹל֔⁠וֹ לְ⁠שַׁלַּ֖ח אֶת־יִשְׂרָאֵ֑ל לֹ֤א יָדַ֨עְתִּי֙ אֶת־יְהוָ֔ה וְ⁠גַ֥ם אֶת־יִשְׂרָאֵ֖ל לֹ֥א אֲשַׁלֵּֽחַ׃","wa⁠yò֣̇ʼmer pȧrĕʻò֔h mi֤y yĕhwáh֙ ʼàşě֣r ʼeşĕ̌ma֣ʻ bĕ̇⁠qòl֔⁠wò lĕ⁠şǎlȧ֖ẖ ʼeţ-yişĕ̂ráʼé֑l lò֤ʼ yáda֨ʻĕţi̇y֙ ʼeţ-yĕhwá֔h wĕ⁠ga֥m ʼeţ-yişĕ̂ráʼé֖l lò֥ʼ ʼàşǎléֽ̇ẖa׃"],[5,3,"וַ⁠יֹּ֣אמְר֔וּ אֱלֹהֵ֥י הָ⁠עִבְרִ֖ים נִקְרָ֣א עָלֵ֑י⁠נוּ נֵ֣לֲכָה נָּ֡א דֶּרֶךְ֩ שְׁלֹ֨שֶׁת יָמִ֜ים בַּ⁠מִּדְבָּ֗ר וְ⁠נִזְבְּחָה֙ לַֽ⁠יהוָ֣ה אֱלֹהֵ֔י⁠נוּ פֶּ֨ן־יִפְגָּעֵ֔⁠נוּ בַּ⁠דֶּ֖בֶר א֥וֹ בֶ⁠חָֽרֶב׃","wa⁠yò֣̇ʼmĕr֔ẇ ʼèlòhé֥y há⁠ʻibĕri֖ym niqĕrá֣ʼ ʻálé֑y⁠nẇ né֣làkáh ná̇֡ʼ dėrekĕ֩ şĕ̌lò֨şěţ yámi֜ym bȧ⁠mi̇dĕbá̇֗r wĕ⁠nizĕbĕ̇ẖáh֙ laֽ⁠yhwá֣h ʼèlòhé֔y⁠nẇ pė֨n-yipĕgá̇ʻé֔⁠nẇ bȧ⁠dė֖ber ʼ֥wò be⁠ẖáֽreb׃"],[5,4,"וַ⁠יֹּ֤אמֶר אֲלֵ⁠הֶם֙ מֶ֣לֶךְ מִצְרַ֔יִם לָ֚⁠מָּה מֹשֶׁ֣ה וְ⁠אַהֲרֹ֔ן תַּפְרִ֥יעוּ אֶת־הָ⁠עָ֖ם מִ⁠מַּֽעֲשָׂ֑י⁠ו לְכ֖וּ לְ⁠סִבְלֹתֵי⁠כֶֽם׃","wa⁠yò֤̇ʼmer ʼàlé⁠hem֙ me֣lekĕ miẕĕra֔yim lá֚⁠má̇h mòşě֣h wĕ⁠ʼahàrò֔n ţȧpĕri֥yʻẇ ʼeţ-há⁠ʻá֖m mi⁠mȧֽʻàşá֑̂y⁠w lĕk֖ẇ lĕ⁠sibĕlòţéy⁠keֽm׃"],[5,5,"וַ⁠יֹּ֣אמֶר פַּרְעֹ֔ה הֵן־רַבִּ֥ים עַתָּ֖ה עַ֣ם הָ⁠אָ֑רֶץ וְ⁠הִשְׁבַּתֶּ֥ם אֹתָ֖⁠ם מִ⁠סִּבְלֹתָֽ⁠ם׃","wa⁠yò֣̇ʼmer pȧrĕʻò֔h hén-rabi֥̇ym ʻaţá֖̇h ʻa֣m há⁠ʼá֑reẕ wĕ⁠hişĕ̌bȧţė֥m ʼòţá֖⁠m mi⁠si̇bĕlòţáֽ⁠m׃"],[5,6,"וַ⁠יְצַ֥ו פַּרְעֹ֖ה בַּ⁠יּ֣וֹם הַ⁠ה֑וּא אֶת־הַ⁠נֹּגְשִׂ֣ים בָּ⁠עָ֔ם וְ⁠אֶת־שֹׁטְרָ֖י⁠ו לֵ⁠אמֹֽר׃","wa⁠yĕẕa֥w pȧrĕʻò֖h bȧ⁠ẏ֣wòm ha⁠h֑ẇʼ ʼeţ-ha⁠nò̇gĕşî֣ym bá̇⁠ʻá֔m wĕ⁠ʼeţ-şò̌tĕrá֖y⁠w lé⁠ʼmòֽr׃"],[5,7,"לֹ֣א תֹאסִפ֞וּ⁠ן לָ⁠תֵ֨ת תֶּ֧בֶן לָ⁠עָ֛ם לִ⁠לְבֹּ֥ן הַ⁠לְּבֵנִ֖ים כִּ⁠תְמ֣וֹל שִׁלְשֹׁ֑ם הֵ֚ם יֵֽלְכ֔וּ וְ⁠קֹשְׁשׁ֥וּ לָ⁠הֶ֖ם תֶּֽבֶן׃","lò֣ʼ ţòʼsip֞ẇ⁠n lá⁠ţé֨ţ ţė֧ben lá⁠ʻá֛m li⁠lĕbò֥̇n ha⁠lĕ̇béni֖ym ki̇⁠ţĕm֣wòl şǐlĕşò֑̌m hé֚m yéֽlĕk֔ẇ wĕ⁠qòşĕ̌ş֥̌ẇ lá⁠he֖m ţėֽben׃"],[5,8,"וְ⁠אֶת־מַתְכֹּ֨נֶת הַ⁠לְּבֵנִ֜ים אֲשֶׁ֣ר הֵם֩ עֹשִׂ֨ים תְּמ֤וֹל שִׁלְשֹׁם֙ תָּשִׂ֣ימוּ עֲלֵי⁠הֶ֔ם לֹ֥א תִגְרְע֖וּ מִמֶּ֑⁠נּוּ כִּֽי־נִרְפִּ֣ים הֵ֔ם עַל־כֵּ֗ן הֵ֤ם צֹֽעֲקִים֙ לֵ⁠אמֹ֔ר נֵלְכָ֖ה נִזְבְּחָ֥ה לֵ⁠אלֹהֵֽי⁠נוּ׃","wĕ⁠ʼeţ-maţĕkò̇֨neţ ha⁠lĕ̇béni֜ym ʼàşě֣r hém֩ ʻòşî֨ym ţĕ̇m֤wòl şǐlĕşò̌m֙ ţá̇şî֣ymẇ ʻàléy⁠he֔m lò֥ʼ ţigĕrĕʻ֖ẇ mimė֑⁠ṅẇ kiֽ̇y-nirĕpi֣̇ym hé֔m ʻal-ké̇֗n hé֤m ẕòֽʻàqiym֙ lé⁠ʼmò֔r nélĕká֖h nizĕbĕ̇ẖá֥h lé⁠ʼlòhéֽy⁠nẇ׃"],[5,9,"תִּכְבַּ֧ד הָ⁠עֲבֹדָ֛ה עַל־הָ⁠אֲנָשִׁ֖ים וְ⁠יַעֲשׂוּ־בָ֑⁠הּ וְ⁠אַל־יִשְׁע֖וּ בְּ⁠דִבְרֵי־שָֽׁקֶר׃","ţi̇kĕbȧ֧d há⁠ʻàbòdá֛h ʻal-há⁠ʼànáşǐ֖ym wĕ⁠yaʻàş̂ẇ-bá֑⁠ḣ wĕ⁠ʼal-yişĕ̌ʻ֖ẇ bĕ̇⁠dibĕréy-şáֽ̌qer׃"],[5,10,"וַ⁠יֵּ֨צְא֜וּ נֹגְשֵׂ֤י הָ⁠עָם֙ וְ⁠שֹׁ֣טְרָ֔י⁠ו וַ⁠יֹּאמְר֥וּ אֶל־הָ⁠עָ֖ם לֵ⁠אמֹ֑ר כֹּ֚ה אָמַ֣ר פַּרְעֹ֔ה אֵינֶ֛⁠נִּי נֹתֵ֥ן לָ⁠כֶ֖ם תֶּֽבֶן׃","wa⁠yé̇֨ẕĕʼ֜ẇ nògĕşé֤̂y há⁠ʻám֙ wĕ⁠şò֣̌tĕrá֔y⁠w wa⁠yò̇ʼmĕr֥ẇ ʼel-há⁠ʻá֖m lé⁠ʼmò֑r kò֚̇h ʼáma֣r pȧrĕʻò֔h ʼéyne֛⁠ni̇y nòţé֥n lá⁠ke֖m ţėֽben׃"],[5,11,"אַתֶּ֗ם לְכ֨וּ קְח֤וּ לָ⁠כֶם֙ תֶּ֔בֶן מֵ⁠אֲשֶׁ֖ר תִּמְצָ֑אוּ כִּ֣י אֵ֥ין נִגְרָ֛ע מֵ⁠עֲבֹדַתְ⁠כֶ֖ם דָּבָֽר׃","ʼaţė֗m lĕk֨ẇ qĕẖ֤ẇ lá⁠kem֙ ţė֔ben mé⁠ʼàşě֖r ţi̇mĕẕá֑ʼẇ ki֣̇y ʼé֥yn nigĕrá֛ʻ mé⁠ʻàbòdaţĕ⁠ke֖m dá̇báֽr׃"],[5,12,"וַ⁠יָּ֥פֶץ הָ⁠עָ֖ם בְּ⁠כָל־אֶ֣רֶץ מִצְרָ֑יִם לְ⁠קֹשֵׁ֥שׁ קַ֖שׁ לַ⁠תֶּֽבֶן׃","wa⁠yá֥̇peẕ há⁠ʻá֖m bĕ̇⁠kál-ʼe֣reẕ miẕĕrá֑yim lĕ⁠qòşé֥̌ş̌ qa֖ş̌ la⁠ţėֽben׃"],[5,13,"וְ⁠הַ⁠נֹּגְשִׂ֖ים אָצִ֣ים לֵ⁠אמֹ֑ר כַּלּ֤וּ מַעֲשֵׂי⁠כֶם֙ דְּבַר־י֣וֹם בְּ⁠יוֹמ֔⁠וֹ כַּ⁠אֲשֶׁ֖ר בִּ⁠הְי֥וֹת הַ⁠תֶּֽבֶן׃","wĕ⁠ha⁠nò̇gĕşî֖ym ʼáẕi֣ym lé⁠ʼmò֑r kȧl֤̇ẇ maʻàşé̂y⁠kem֙ dĕ̇bar-y֣wòm bĕ̇⁠ywòm֔⁠wò kȧ⁠ʼàşě֖r bi̇⁠hĕy֥wòţ ha⁠ţėֽben׃"],[5,14,"וַ⁠יֻּכּ֗וּ שֹֽׁטְרֵי֙ בְּנֵ֣י יִשְׂרָאֵ֔ל אֲשֶׁר־שָׂ֣מוּ עֲלֵ⁠הֶ֔ם נֹגְשֵׂ֥י פַרְעֹ֖ה לֵ⁠אמֹ֑ר מַדּ֡וּעַ לֹא֩ כִלִּיתֶ֨ם חָקְ⁠כֶ֤ם לִ⁠לְבֹּן֙ כִּ⁠תְמ֣וֹל שִׁלְשֹׁ֔ם גַּם־תְּמ֖וֹל גַּם־הַ⁠יּֽוֹם׃","wa⁠yu̇k̇֗ẇ şòֽ̌tĕréy֙ bĕ̇né֣y yişĕ̂ráʼé֔l ʼàşěr-şá֣̂mẇ ʻàlé⁠he֔m nògĕşé֥̂y parĕʻò֖h lé⁠ʼmò֑r maḋ֡ẇʻa lòʼ֩ kili̇yţe֨m ẖáqĕ⁠ke֤m li⁠lĕbò̇n֙ ki̇⁠ţĕm֣wòl şǐlĕşò̌֔m gȧm-ţĕ̇m֖wòl gȧm-ha⁠ẏֽwòm׃"],[5,15,"וַ⁠יָּבֹ֗אוּ שֹֽׁטְרֵי֙ בְּנֵ֣י יִשְׂרָאֵ֔ל וַ⁠יִּצְעֲק֥וּ אֶל־פַּרְעֹ֖ה לֵ⁠אמֹ֑ר לָ֧⁠מָּה תַעֲשֶׂ֦ה כֹ֖ה לַ⁠עֲבָדֶֽי⁠ךָ׃","wa⁠yá̇bò֗ʼẇ şòֽ̌tĕréy֙ bĕ̇né֣y yişĕ̂ráʼé֔l wa⁠yi̇ẕĕʻàq֥ẇ ʼel-pȧrĕʻò֖h lé⁠ʼmò֑r lá֧⁠má̇h ţaʻàşê֦h kò֖h la⁠ʻàbádeֽy⁠ká׃"],[5,16,"תֶּ֗בֶן אֵ֤ין נִתָּן֙ לַ⁠עֲבָדֶ֔י⁠ךָ וּ⁠לְבֵנִ֛ים אֹמְרִ֥ים לָ֖⁠נוּ עֲשׂ֑וּ וְ⁠הִנֵּ֧ה עֲבָדֶ֛י⁠ךָ מֻכִּ֖ים וְ⁠חָטָ֥את עַמֶּֽ⁠ךָ׃","ţė֗ben ʼé֤yn niţá̇n֙ la⁠ʻàbáde֔y⁠ká ẇ⁠lĕbéni֛ym ʼòmĕri֥ym lá֖⁠nẇ ʻàş֑̂ẇ wĕ⁠hiné֧̇h ʻàbáde֛y⁠ká muki֖̇ym wĕ⁠ẖátá֥ʼţ ʻamėֽ⁠ká׃"],[5,17,"וַ⁠יֹּ֛אמֶר נִרְפִּ֥ים אַתֶּ֖ם נִרְפִּ֑ים עַל־כֵּן֙ אַתֶּ֣ם אֹֽמְרִ֔ים נֵלְכָ֖ה נִזְבְּחָ֥ה לַֽ⁠יהוָֽה׃","wa⁠yò֛̇ʼmer nirĕpi֥̇ym ʼaţė֖m nirĕpi֑̇ym ʻal-ké̇n֙ ʼaţė֣m ʼòֽmĕri֔ym nélĕká֖h nizĕbĕ̇ẖá֥h laֽ⁠yhwáֽh׃"],[5,18,"וְ⁠עַתָּה֙ לְכ֣וּ עִבְד֔וּ וְ⁠תֶ֖בֶן לֹא־יִנָּתֵ֣ן לָ⁠כֶ֑ם וְ⁠תֹ֥כֶן לְבֵנִ֖ים תִּתֵּֽנּוּ׃","wĕ⁠ʻaţá̇h֙ lĕk֣ẇ ʻibĕd֔ẇ wĕ⁠ţe֖ben lòʼ-yiná̇ţé֣n lá⁠ke֑m wĕ⁠ţò֥ken lĕbéni֖ym ţi̇ţéֽ̇ṅẇ׃"],[5,19,"וַ⁠יִּרְא֞וּ שֹֽׁטְרֵ֧י בְנֵֽי־יִשְׂרָאֵ֛ל אֹתָ֖⁠ם בְּ⁠רָ֣ע לֵ⁠אמֹ֑ר לֹא־תִגְרְע֥וּ מִ⁠לִּבְנֵי⁠כֶ֖ם דְּבַר־י֥וֹם בְּ⁠יוֹמֽ⁠וֹ׃","wa⁠yi̇rĕʼ֞ẇ şòֽ̌tĕré֧y bĕnéֽy-yişĕ̂ráʼé֛l ʼòţá֖⁠m bĕ̇⁠rá֣ʻ lé⁠ʼmò֑r lòʼ-ţigĕrĕʻ֥ẇ mi⁠li̇bĕnéy⁠ke֖m dĕ̇bar-y֥wòm bĕ̇⁠ywòmֽ⁠wò׃"],[5,20,"וַֽ⁠יִּפְגְּעוּ֙ אֶת־מֹשֶׁ֣ה וְ⁠אֶֽת־אַהֲרֹ֔ן נִצָּבִ֖ים לִ⁠קְרָאתָ֑⁠ם בְּ⁠צֵאתָ֖⁠ם מֵ⁠אֵ֥ת פַּרְעֹֽה׃","waֽ⁠yi̇pĕgĕ̇ʻẇ֙ ʼeţ-mòşě֣h wĕ⁠ʼeֽţ-ʼahàrò֔n niẕá̇bi֖ym li⁠qĕráʼţá֑⁠m bĕ̇⁠ẕéʼţá֖⁠m mé⁠ʼé֥ţ pȧrĕʻòֽh׃"],[5,21,"וַ⁠יֹּאמְר֣וּ אֲלֵ⁠הֶ֔ם יֵ֧רֶא יְהוָ֛ה עֲלֵי⁠כֶ֖ם וְ⁠יִשְׁפֹּ֑ט אֲשֶׁ֧ר הִבְאַשְׁתֶּ֣ם אֶת־רֵיחֵ֗⁠נוּ בְּ⁠עֵינֵ֤י פַרְעֹה֙ וּ⁠בְ⁠עֵינֵ֣י עֲבָדָ֔י⁠ו לָֽ⁠תֶת־חֶ֥רֶב בְּ⁠יָדָ֖⁠ם לְ⁠הָרְגֵֽ⁠נוּ׃","wa⁠yò̇ʼmĕr֣ẇ ʼàlé⁠he֔m yé֧reʼ yĕhwá֛h ʻàléy⁠ke֖m wĕ⁠yişĕ̌pò֑̇t ʼàşě֧r hibĕʼaşĕ̌ţė֣m ʼeţ-réyẖé֗⁠nẇ bĕ̇⁠ʻéyné֤y parĕʻòh֙ ẇ⁠bĕ⁠ʻéyné֣y ʻàbádá֔y⁠w láֽ⁠ţeţ-ẖe֥reb bĕ̇⁠yádá֖⁠m lĕ⁠hárĕgéֽ⁠nẇ׃"],[5,22,"וַ⁠יָּ֧שָׁב מֹשֶׁ֛ה אֶל־יְהוָ֖ה וַ⁠יֹּאמַ֑ר אֲדֹנָ֗⁠י לָ⁠מָ֤ה הֲרֵעֹ֨תָה֙ לָ⁠עָ֣ם הַ⁠זֶּ֔ה לָ֥⁠מָּה זֶּ֖ה שְׁלַחְתָּֽ⁠נִי׃","wa⁠yá֧̇şá̌b mòşě֛h ʼel-yĕhwá֖h wa⁠yò̇ʼma֑r ʼàdòná֗⁠y lá⁠má֤h hàréʻò֨ţáh֙ lá⁠ʻá֣m ha⁠zė֔h lá֥⁠má̇h zė֖h şĕ̌laẖĕţáֽ̇⁠niy׃"],[5,23,"וּ⁠מֵ⁠אָ֞ז בָּ֤אתִי אֶל־פַּרְעֹה֙ לְ⁠דַבֵּ֣ר בִּ⁠שְׁמֶ֔⁠ךָ הֵרַ֖ע לָ⁠עָ֣ם הַ⁠זֶּ֑ה וְ⁠הַצֵּ֥ל לֹא־הִצַּ֖לְתָּ אֶת־עַמֶּֽ⁠ךָ׃","ẇ⁠mé⁠ʼá֞z bá֤̇ʼţiy ʼel-pȧrĕʻòh֙ lĕ⁠dabé֣̇r bi̇⁠şĕ̌me֔⁠ká héra֖ʻ lá⁠ʻá֣m ha⁠zė֑h wĕ⁠haẕé֥̇l lòʼ-hiẕȧ֖lĕţá̇ ʼeţ-ʻamėֽ⁠ká׃"],[6,1,"וַ⁠יֹּ֤אמֶר יְהוָה֙ אֶל־מֹשֶׁ֔ה עַתָּ֣ה תִרְאֶ֔ה אֲשֶׁ֥ר אֶֽעֱשֶׂ֖ה לְ⁠פַרְעֹ֑ה כִּ֣י בְ⁠יָ֤ד חֲזָקָה֙ יְשַׁלְּחֵ֔⁠ם וּ⁠בְ⁠יָ֣ד חֲזָקָ֔ה יְגָרְשֵׁ֖⁠ם מֵ⁠אַרְצֽ⁠וֹ׃ס","wa⁠yò֤̇ʼmer yĕhwáh֙ ʼel-mòşě֔h ʻaţá֣̇h ţirĕʼe֔h ʼàşě֥r ʼֽeʻèşê֖h lĕ⁠parĕʻò֑h ki֣̇y bĕ⁠yá֤d ẖàzáqáh֙ yĕşǎlĕ̇ẖé֔⁠m ẇ⁠bĕ⁠yá֣d ẖàzáqá֔h yĕgárĕşé֖̌⁠m mé⁠ʼarĕẕֽ⁠wò׃s"],[6,2,"וַ⁠יְדַבֵּ֥ר אֱלֹהִ֖ים אֶל־מֹשֶׁ֑ה וַ⁠יֹּ֥אמֶר אֵלָ֖י⁠ו אֲנִ֥י יְהוָֽה׃","wa⁠yĕdabé֥̇r ʼèlòhi֖ym ʼel-mòşě֑h wa⁠yò֥̇ʼmer ʼélá֖y⁠w ʼàni֥y yĕhwáֽh׃"],[6,3,"וָ⁠אֵרָ֗א אֶל־אַבְרָהָ֛ם אֶל־יִצְחָ֥ק וְ⁠אֶֽל־יַעֲקֹ֖ב בְּ⁠אֵ֣ל שַׁדָּ֑י וּ⁠שְׁמִ֣⁠י יְהוָ֔ה לֹ֥א נוֹדַ֖עְתִּי לָ⁠הֶֽם׃","wá⁠ʼérá֗ʼ ʼel-ʼabĕráhá֛m ʼel-yiẕĕẖá֥q wĕ⁠ʼeֽl-yaʻàqò֖b bĕ̇⁠ʼé֣l şǎdá֑̇y ẇ⁠şĕ̌mi֣⁠y yĕhwá֔h lò֥ʼ nwòda֖ʻĕţi̇y lá⁠heֽm׃"],[6,4,"וְ⁠גַ֨ם הֲקִמֹ֤תִי אֶת־בְּרִיתִ⁠י֙ אִתָּ֔⁠ם לָ⁠תֵ֥ת לָ⁠הֶ֖ם אֶת־אֶ֣רֶץ כְּנָ֑עַן אֵ֛ת אֶ֥רֶץ מְגֻרֵי⁠הֶ֖ם אֲשֶׁר־גָּ֥רוּ בָֽ⁠הּ׃","wĕ⁠ga֨m hàqimò֤ţiy ʼeţ-bĕ̇riyţi⁠y֙ ʼiţá̇֔⁠m lá⁠ţé֥ţ lá⁠he֖m ʼeţ-ʼe֣reẕ kĕ̇ná֑ʻan ʼé֛ţ ʼe֥reẕ mĕguréy⁠he֖m ʼàşěr-gá֥̇rẇ báֽ⁠ḣ׃"],[6,5,"וְ⁠גַ֣ם ׀ אֲנִ֣י שָׁמַ֗עְתִּי אֶֽת־נַאֲקַת֙ בְּנֵ֣י יִשְׂרָאֵ֔ל אֲשֶׁ֥ר מִצְרַ֖יִם מַעֲבִדִ֣ים אֹתָ֑⁠ם וָ⁠אֶזְכֹּ֖ר אֶת־בְּרִיתִֽ⁠י׃","wĕ⁠ga֣m ׀ ʼàni֣y şá̌ma֗ʻĕţi̇y ʼeֽţ-naʼàqaţ֙ bĕ̇né֣y yişĕ̂ráʼé֔l ʼàşě֥r miẕĕra֖yim maʻàbidi֣ym ʼòţá֑⁠m wá⁠ʼezĕkò֖̇r ʼeţ-bĕ̇riyţiֽ⁠y׃"],[6,6,"לָ⁠כֵ֞ן אֱמֹ֥ר לִ⁠בְנֵֽי־יִשְׂרָאֵ֘ל אֲנִ֣י יְהוָה֒ וְ⁠הוֹצֵאתִ֣י אֶתְ⁠כֶ֗ם מִ⁠תַּ֨חַת֙ סִבְלֹ֣ת מִצְרַ֔יִם וְ⁠הִצַּלְתִּ֥י אֶתְ⁠כֶ֖ם מֵ⁠עֲבֹדָתָ֑⁠ם וְ⁠גָאַלְתִּ֤י אֶתְ⁠כֶם֙ בִּ⁠זְר֣וֹעַ נְטוּיָ֔ה וּ⁠בִ⁠שְׁפָטִ֖ים גְּדֹלִֽים׃","lá⁠ké֞n ʼèmò֥r li⁠bĕnéֽy-yişĕ̂ráʼé֘l ʼàni֣y yĕhwáh֒ wĕ⁠hwòẕéʼţi֣y ʼeţĕ⁠ke֗m mi⁠ţȧ֨ẖaţ֙ sibĕlò֣ţ miẕĕra֔yim wĕ⁠hiẕȧlĕţi֥̇y ʼeţĕ⁠ke֖m mé⁠ʻàbòdáţá֑⁠m wĕ⁠gáʼalĕţi֤̇y ʼeţĕ⁠kem֙ bi̇⁠zĕr֣wòʻa nĕtẇyá֔h ẇ⁠bi⁠şĕ̌páti֖ym gĕ̇dòliֽym׃"],[6,7,"וְ⁠לָקַחְתִּ֨י אֶתְ⁠כֶ֥ם לִ⁠י֙ לְ⁠עָ֔ם וְ⁠הָיִ֥יתִי לָ⁠כֶ֖ם לֵֽ⁠אלֹהִ֑ים וִֽ⁠ידַעְתֶּ֗ם כִּ֣י אֲנִ֤י יְהוָה֙ אֱלֹ֣הֵי⁠כֶ֔ם הַ⁠מּוֹצִ֣יא אֶתְ⁠כֶ֔ם מִ⁠תַּ֖חַת סִבְל֥וֹת מִצְרָֽיִם׃","wĕ⁠láqaẖĕţi̇֨y ʼeţĕ⁠ke֥m li⁠y֙ lĕ⁠ʻá֔m wĕ⁠háyi֥yţiy lá⁠ke֖m léֽ⁠ʼlòhi֑ym wiֽ⁠ydaʻĕţė֗m ki֣̇y ʼàni֤y yĕhwáh֙ ʼèlò֣héy⁠ke֔m ha⁠ṁwòẕi֣yʼ ʼeţĕ⁠ke֔m mi⁠ţȧ֖ẖaţ sibĕl֥wòţ miẕĕráֽyim׃"],[6,8,"וְ⁠הֵבֵאתִ֤י אֶתְ⁠כֶם֙ אֶל־הָ⁠אָ֔רֶץ אֲשֶׁ֤ר נָשָׂ֨אתִי֙ אֶת־יָדִ֔⁠י לָ⁠תֵ֣ת אֹתָ֔⁠הּ לְ⁠אַבְרָהָ֥ם לְ⁠יִצְחָ֖ק וּֽ⁠לְ⁠יַעֲקֹ֑ב וְ⁠נָתַתִּ֨י אֹתָ֥⁠הּ לָ⁠כֶ֛ם מוֹרָשָׁ֖ה אֲנִ֥י יְהוָֽה׃","wĕ⁠hébéʼţi֤y ʼeţĕ⁠kem֙ ʼel-há⁠ʼá֔reẕ ʼàşě֤r náşá̂֨ʼţiy֙ ʼeţ-yádi֔⁠y lá⁠ţé֣ţ ʼòţá֔⁠ḣ lĕ⁠ʼabĕráhá֥m lĕ⁠yiẕĕẖá֖q ẇֽ⁠lĕ⁠yaʻàqò֑b wĕ⁠náţaţi̇֨y ʼòţá֥⁠ḣ lá⁠ke֛m mwòráşá֖̌h ʼàni֥y yĕhwáֽh׃"],[6,9,"וַ⁠יְדַבֵּ֥ר מֹשֶׁ֛ה כֵּ֖ן אֶל־בְּנֵ֣י יִשְׂרָאֵ֑ל וְ⁠לֹ֤א שָֽׁמְעוּ֙ אֶל־מֹשֶׁ֔ה מִ⁠קֹּ֣צֶר ר֔וּחַ וּ⁠מֵ⁠עֲבֹדָ֖ה קָשָֽׁה׃פ","wa⁠yĕdabé֥̇r mòşě֛h ké֖̇n ʼel-bĕ̇né֣y yişĕ̂ráʼé֑l wĕ⁠lò֤ʼ şáֽ̌mĕʻẇ֙ ʼel-mòşě֔h mi⁠qò֣̇ẕer r֔ẇẖa ẇ⁠mé⁠ʻàbòdá֖h qáşáֽ̌h׃p"],[6,10,"וַ⁠יְדַבֵּ֥ר יְהוָ֖ה אֶל־מֹשֶׁ֥ה לֵּ⁠אמֹֽר׃","wa⁠yĕdabé֥̇r yĕhwá֖h ʼel-mòşě֥h lé̇⁠ʼmòֽr׃"],[6,11,"בֹּ֣א דַבֵּ֔ר אֶל־פַּרְעֹ֖ה מֶ֣לֶךְ מִצְרָ֑יִם וִֽ⁠ישַׁלַּ֥ח אֶת־בְּנֵֽי־יִשְׂרָאֵ֖ל מֵ⁠אַרְצֽ⁠וֹ׃","bò֣̇ʼ dabé̇֔r ʼel-pȧrĕʻò֖h me֣lekĕ miẕĕrá֑yim wiֽ⁠yşǎlȧ֥ẖ ʼeţ-bĕ̇néֽy-yişĕ̂ráʼé֖l mé⁠ʼarĕẕֽ⁠wò׃"],[6,12,"וַ⁠יְדַבֵּ֣ר מֹשֶׁ֔ה לִ⁠פְנֵ֥י יְהוָ֖ה לֵ⁠אמֹ֑ר הֵ֤ן בְּנֵֽי־יִשְׂרָאֵל֙ לֹֽא־שָׁמְע֣וּ אֵלַ֔⁠י וְ⁠אֵיךְ֙ יִשְׁמָעֵ֣⁠נִי פַרְעֹ֔ה וַ⁠אֲנִ֖י עֲרַ֥ל שְׂפָתָֽיִם׃פ","wa⁠yĕdabé֣̇r mòşě֔h li⁠pĕné֥y yĕhwá֖h lé⁠ʼmò֑r hé֤n bĕ̇néֽy-yişĕ̂ráʼél֙ lòֽʼ-şá̌mĕʻ֣ẇ ʼéla֔⁠y wĕ⁠ʼéykĕ֙ yişĕ̌máʻé֣⁠niy parĕʻò֔h wa⁠ʼàni֖y ʻàra֥l şĕ̂páţáֽyim׃p"],[6,13,"וַ⁠יְדַבֵּ֣ר יְהוָה֮ אֶל־מֹשֶׁ֣ה וְ⁠אֶֽל־אַהֲרֹן֒ וַ⁠יְצַוֵּ⁠ם֙ אֶל־בְּנֵ֣י יִשְׂרָאֵ֔ל וְ⁠אֶל־פַּרְעֹ֖ה מֶ֣לֶךְ מִצְרָ֑יִם לְ⁠הוֹצִ֥יא אֶת־בְּנֵֽי־יִשְׂרָאֵ֖ל מֵ⁠אֶ֥רֶץ מִצְרָֽיִם׃ס","wa⁠yĕdabé֣̇r yĕhwáh֮ ʼel-mòşě֣h wĕ⁠ʼeֽl-ʼahàròn֒ wa⁠yĕẕawé̇⁠m֙ ʼel-bĕ̇né֣y yişĕ̂ráʼé֔l wĕ⁠ʼel-pȧrĕʻò֖h me֣lekĕ miẕĕrá֑yim lĕ⁠hwòẕi֥yʼ ʼeţ-bĕ̇néֽy-yişĕ̂ráʼé֖l mé⁠ʼe֥reẕ miẕĕráֽyim׃s"],[6,14,"אֵ֖לֶּה רָאשֵׁ֣י בֵית־אֲבֹתָ֑⁠ם בְּנֵ֨י רְאוּבֵ֜ן בְּכֹ֣ר יִשְׂרָאֵ֗ל חֲנ֤וֹךְ וּ⁠פַלּוּא֙ חֶצְר֣וֹן וְ⁠כַרְמִ֔י אֵ֖לֶּה מִשְׁפְּחֹ֥ת רְאוּבֵֽן׃","ʼé֖lėh ráʼşé֣̌y béyţ-ʼàbòţá֑⁠m bĕ̇né֨y rĕʼẇbé֜n bĕ̇kò֣r yişĕ̂ráʼé֗l ẖàn֤wòkĕ ẇ⁠pal̇ẇʼ֙ ẖeẕĕr֣wòn wĕ⁠karĕmi֔y ʼé֖lėh mişĕ̌pĕ̇ẖò֥ţ rĕʼẇbéֽn׃"],[6,15,"וּ⁠בְנֵ֣י שִׁמְע֗וֹן יְמוּאֵ֨ל וְ⁠יָמִ֤ין וְ⁠אֹ֨הַד֙ וְ⁠יָכִ֣ין וְ⁠צֹ֔חַר וְ⁠שָׁא֖וּל בֶּן־הַֽ⁠כְּנַעֲנִ֑ית אֵ֖לֶּה מִשְׁפְּחֹ֥ת שִׁמְעֽוֹן׃","ẇ⁠bĕné֣y şǐmĕʻ֗wòn yĕmẇʼé֨l wĕ⁠yámi֤yn wĕ⁠ʼò֨had֙ wĕ⁠yáki֣yn wĕ⁠ẕò֔ẖar wĕ⁠şá̌ʼ֖ẇl bėn-haֽ⁠kĕ̇naʻàni֑yţ ʼé֖lėh mişĕ̌pĕ̇ẖò֥ţ şǐmĕʻֽwòn׃"],[6,16,"וְ⁠אֵ֨לֶּה שְׁמ֤וֹת בְּנֵֽי־לֵוִי֙ לְ⁠תֹ֣לְדֹתָ֔⁠ם גֵּרְשׁ֕וֹן וּ⁠קְהָ֖ת וּ⁠מְרָרִ֑י וּ⁠שְׁנֵי֙ חַיֵּ֣י לֵוִ֔י שֶׁ֧בַע וּ⁠שְׁלֹשִׁ֛ים וּ⁠מְאַ֖ת שָׁנָֽה׃","wĕ⁠ʼé֨lėh şĕ̌m֤wòţ bĕ̇néֽy-léwiy֙ lĕ⁠ţò֣lĕdòţá֔⁠m gé̇rĕş̌֕wòn ẇ⁠qĕhá֖ţ ẇ⁠mĕrári֑y ẇ⁠şĕ̌néy֙ ẖayé֣̇y léwi֔y şě֧baʻ ẇ⁠şĕ̌lòşǐ֛ym ẇ⁠mĕʼa֖ţ şá̌náֽh׃"],[6,17,"בְּנֵ֥י גֵרְשׁ֛וֹן לִבְנִ֥י וְ⁠שִׁמְעִ֖י לְ⁠מִשְׁפְּחֹתָֽ⁠ם׃","bĕ̇né֥y gérĕş֛̌wòn libĕni֥y wĕ⁠şǐmĕʻi֖y lĕ⁠mişĕ̌pĕ̇ẖòţáֽ⁠m׃"],[6,18,"וּ⁠בְנֵ֣י קְהָ֔ת עַמְרָ֣ם וְ⁠יִצְהָ֔ר וְ⁠חֶבְר֖וֹן וְ⁠עֻזִּיאֵ֑ל וּ⁠שְׁנֵי֙ חַיֵּ֣י קְהָ֔ת שָׁלֹ֧שׁ וּ⁠שְׁלֹשִׁ֛ים וּ⁠מְאַ֖ת שָׁנָֽה׃","ẇ⁠bĕné֣y qĕhá֔ţ ʻamĕrá֣m wĕ⁠yiẕĕhá֔r wĕ⁠ẖebĕr֖wòn wĕ⁠ʻuzi̇yʼé֑l ẇ⁠şĕ̌néy֙ ẖayé֣̇y qĕhá֔ţ şá̌lò֧ş̌ ẇ⁠şĕ̌lòşǐ֛ym ẇ⁠mĕʼa֖ţ şá̌náֽh׃"],[6,19,"וּ⁠בְנֵ֥י מְרָרִ֖י מַחְלִ֣י וּ⁠מוּשִׁ֑י אֵ֛לֶּה מִשְׁפְּחֹ֥ת הַ⁠לֵּוִ֖י לְ⁠תֹלְדֹתָֽ⁠ם׃","ẇ⁠bĕné֥y mĕrári֖y maẖĕli֣y ẇ⁠mẇşǐ֑y ʼé֛lėh mişĕ̌pĕ̇ẖò֥ţ ha⁠lé̇wi֖y lĕ⁠ţòlĕdòţáֽ⁠m׃"],[6,20,"וַ⁠יִּקַּ֨ח עַמְרָ֜ם אֶת־יוֹכֶ֤בֶד דֹּֽדָת⁠וֹ֙ ל֣⁠וֹ לְ⁠אִשָּׁ֔ה וַ⁠תֵּ֣לֶד ל֔⁠וֹ אֶֽת־אַהֲרֹ֖ן וְ⁠אֶת־מֹשֶׁ֑ה וּ⁠שְׁנֵי֙ חַיֵּ֣י עַמְרָ֔ם שֶׁ֧בַע וּ⁠שְׁלֹשִׁ֛ים וּ⁠מְאַ֖ת שָׁנָֽה׃","wa⁠yi̇qȧ֨ẖ ʻamĕrá֜m ʼeţ-ywòke֤bed dòֽ̇dáţ⁠wò֙ l֣⁠wò lĕ⁠ʼişá̇̌֔h wa⁠ţé֣̇led l֔⁠wò ʼeֽţ-ʼahàrò֖n wĕ⁠ʼeţ-mòşě֑h ẇ⁠şĕ̌néy֙ ẖayé֣̇y ʻamĕrá֔m şě֧baʻ ẇ⁠şĕ̌lòşǐ֛ym ẇ⁠mĕʼa֖ţ şá̌náֽh׃"],[6,21,"וּ⁠בְנֵ֖י יִצְהָ֑ר קֹ֥רַח וָ⁠נֶ֖פֶג וְ⁠זִכְרִֽי׃","ẇ⁠bĕné֖y yiẕĕhá֑r qò֥raẖ wá⁠ne֖peg wĕ⁠zikĕriֽy׃"],[6,22,"וּ⁠בְנֵ֖י עֻזִּיאֵ֑ל מִֽישָׁאֵ֥ל וְ⁠אֶלְצָפָ֖ן וְ⁠סִתְרִֽי׃","ẇ⁠bĕné֖y ʻuzi̇yʼé֑l miֽyşá̌ʼé֥l wĕ⁠ʼelĕẕápá֖n wĕ⁠siţĕriֽy׃"],[6,23,"וַ⁠יִּקַּ֨ח אַהֲרֹ֜ן אֶת־אֱלִישֶׁ֧בַע בַּת־עַמִּינָדָ֛ב אֲח֥וֹת נַחְשׁ֖וֹן ל֣⁠וֹ לְ⁠אִשָּׁ֑ה וַ⁠תֵּ֣לֶד ל֗⁠וֹ אֶת־נָדָב֙ וְ⁠אֶת־אֲבִיה֔וּא אֶת־אֶלְעָזָ֖ר וְ⁠אֶת־אִֽיתָמָֽר׃","wa⁠yi̇qȧ֨ẖ ʼahàrò֜n ʼeţ-ʼèliyşě֧baʻ bȧţ-ʻami̇ynádá֛b ʼàẖ֥wòţ naẖĕş֖̌wòn l֣⁠wò lĕ⁠ʼişá֑̇̌h wa⁠ţé֣̇led l֗⁠wò ʼeţ-nádáb֙ wĕ⁠ʼeţ-ʼàbiyh֔ẇʼ ʼeţ-ʼelĕʻázá֖r wĕ⁠ʼeţ-ʼiֽyţámáֽr׃"],[6,24,"וּ⁠בְנֵ֣י קֹ֔רַח אַסִּ֥יר וְ⁠אֶלְקָנָ֖ה וַ⁠אֲבִיאָסָ֑ף אֵ֖לֶּה מִשְׁפְּחֹ֥ת הַ⁠קָּרְחִֽי׃","ẇ⁠bĕné֣y qò֔raẖ ʼasi֥̇yr wĕ⁠ʼelĕqáná֖h wa⁠ʼàbiyʼásá֑p ʼé֖lėh mişĕ̌pĕ̇ẖò֥ţ ha⁠qá̇rĕẖiֽy׃"],[6,25,"וְ⁠אֶלְעָזָ֨ר בֶּֽן־אַהֲרֹ֜ן לָקַֽח־ל֨⁠וֹ מִ⁠בְּנ֤וֹת פּֽוּטִיאֵל֙ ל֣⁠וֹ לְ⁠אִשָּׁ֔ה וַ⁠תֵּ֥לֶד ל֖⁠וֹ אֶת־פִּֽינְחָ֑ס אֵ֗לֶּה רָאשֵׁ֛י אֲב֥וֹת הַ⁠לְוִיִּ֖ם לְ⁠מִשְׁפְּחֹתָֽ⁠ם׃","wĕ⁠ʼelĕʻázá֨r bėֽn-ʼahàrò֜n láqaֽẖ-l֨⁠wò mi⁠bĕ̇n֤wòţ ṗֽẇtiyʼél֙ l֣⁠wò lĕ⁠ʼişá̇̌֔h wa⁠ţé֥̇led l֖⁠wò ʼeţ-piֽ̇ynĕẖá֑s ʼé֗lėh ráʼşé֛̌y ʼàb֥wòţ ha⁠lĕwiyi֖̇m lĕ⁠mişĕ̌pĕ̇ẖòţáֽ⁠m׃"],[6,26,"ה֥וּא אַהֲרֹ֖ן וּ⁠מֹשֶׁ֑ה אֲשֶׁ֨ר אָמַ֤ר יְהוָה֙ לָ⁠הֶ֔ם הוֹצִ֜יאוּ אֶת־בְּנֵ֧י יִשְׂרָאֵ֛ל מֵ⁠אֶ֥רֶץ מִצְרַ֖יִם עַל־צִבְאֹתָֽ⁠ם׃","h֥ẇʼ ʼahàrò֖n ẇ⁠mòşě֑h ʼàşě֨r ʼáma֤r yĕhwáh֙ lá⁠he֔m hwòẕi֜yʼẇ ʼeţ-bĕ̇né֧y yişĕ̂ráʼé֛l mé⁠ʼe֥reẕ miẕĕra֖yim ʻal-ẕibĕʼòţáֽ⁠m׃"],[6,27,"הֵ֗ם הַֽ⁠מְדַבְּרִים֙ אֶל־פַּרְעֹ֣ה מֶֽלֶךְ־מִצְרַ֔יִם לְ⁠הוֹצִ֥יא אֶת־בְּנֵֽי־יִשְׂרָאֵ֖ל מִ⁠מִּצְרָ֑יִם ה֥וּא מֹשֶׁ֖ה וְ⁠אַהֲרֹֽן׃","hé֗m haֽ⁠mĕdabĕ̇riym֙ ʼel-pȧrĕʻò֣h meֽlekĕ-miẕĕra֔yim lĕ⁠hwòẕi֥yʼ ʼeţ-bĕ̇néֽy-yişĕ̂ráʼé֖l mi⁠mi̇ẕĕrá֑yim h֥ẇʼ mòşě֖h wĕ⁠ʼahàròֽn׃"],[6,28,"וַ⁠יְהִ֗י בְּ⁠י֨וֹם דִּבֶּ֧ר יְהוָ֛ה אֶל־מֹשֶׁ֖ה בְּ⁠אֶ֥רֶץ מִצְרָֽיִם׃פ","wa⁠yĕhi֗y bĕ̇⁠y֨wòm di̇bė֧r yĕhwá֛h ʼel-mòşě֖h bĕ̇⁠ʼe֥reẕ miẕĕráֽyim׃p"],[6,29,"וַ⁠יְדַבֵּ֧ר יְהוָ֛ה אֶל־מֹשֶׁ֥ה לֵּ⁠אמֹ֖ר אֲנִ֣י יְהוָ֑ה דַּבֵּ֗ר אֶל־פַּרְעֹה֙ מֶ֣לֶךְ מִצְרַ֔יִם אֵ֛ת כָּל־אֲשֶׁ֥ר אֲנִ֖י דֹּבֵ֥ר אֵלֶֽי⁠ךָ׃","wa⁠yĕdabé֧̇r yĕhwá֛h ʼel-mòşě֥h lé̇⁠ʼmò֖r ʼàni֣y yĕhwá֑h dȧbé̇֗r ʼel-pȧrĕʻòh֙ me֣lekĕ miẕĕra֔yim ʼé֛ţ ká̇l-ʼàşě֥r ʼàni֖y dò̇bé֥r ʼéleֽy⁠ká׃"],[6,30,"וַ⁠יֹּ֥אמֶר מֹשֶׁ֖ה לִ⁠פְנֵ֣י יְהוָ֑ה הֵ֤ן אֲנִי֙ עֲרַ֣ל שְׂפָתַ֔יִם וְ⁠אֵ֕יךְ יִשְׁמַ֥ע אֵלַ֖⁠י פַּרְעֹֽה׃פ","wa⁠yò֥̇ʼmer mòşě֖h li⁠pĕné֣y yĕhwá֑h hé֤n ʼàniy֙ ʻàra֣l şĕ̂páţa֔yim wĕ⁠ʼé֕ykĕ yişĕ̌ma֥ʻ ʼéla֖⁠y pȧrĕʻòֽh׃p"],[7,1,"וַ⁠יֹּ֤אמֶר יְהוָה֙ אֶל־מֹשֶׁ֔ה רְאֵ֛ה נְתַתִּ֥י⁠ךָ אֱלֹהִ֖ים לְ⁠פַרְעֹ֑ה וְ⁠אַהֲרֹ֥ן אָחִ֖י⁠ךָ יִהְיֶ֥ה נְבִיאֶֽ⁠ךָ׃","wa⁠yò֤̇ʼmer yĕhwáh֙ ʼel-mòşě֔h rĕʼé֛h nĕţaţi֥̇y⁠ká ʼèlòhi֖ym lĕ⁠parĕʻò֑h wĕ⁠ʼahàrò֥n ʼáẖi֖y⁠ká yihĕye֥h nĕbiyʼeֽ⁠ká׃"],[7,2,"אַתָּ֣ה תְדַבֵּ֔ר אֵ֖ת כָּל־אֲשֶׁ֣ר אֲצַוֶּ֑⁠ךָּ וְ⁠אַהֲרֹ֤ן אָחִ֨י⁠ךָ֙ יְדַבֵּ֣ר אֶל־פַּרְעֹ֔ה וְ⁠שִׁלַּ֥ח אֶת־בְּנֵֽי־יִשְׂרָאֵ֖ל מֵ⁠אַרְצֽ⁠וֹ׃","ʼaţá֣̇h ţĕdabé̇֔r ʼé֖ţ ká̇l-ʼàşě֣r ʼàẕawė֑⁠ká̇ wĕ⁠ʼahàrò֤n ʼáẖi֨y⁠ká֙ yĕdabé֣̇r ʼel-pȧrĕʻò֔h wĕ⁠şǐlȧ֥ẖ ʼeţ-bĕ̇néֽy-yişĕ̂ráʼé֖l mé⁠ʼarĕẕֽ⁠wò׃"],[7,3,"וַ⁠אֲנִ֥י אַקְשֶׁ֖ה אֶת־לֵ֣ב פַּרְעֹ֑ה וְ⁠הִרְבֵּיתִ֧י אֶת־אֹתֹתַ֛⁠י וְ⁠אֶת־מוֹפְתַ֖⁠י בְּ⁠אֶ֥רֶץ מִצְרָֽיִם׃","wa⁠ʼàni֥y ʼaqĕşě֖h ʼeţ-lé֣b pȧrĕʻò֑h wĕ⁠hirĕbé̇yţi֧y ʼeţ-ʼòţòţa֛⁠y wĕ⁠ʼeţ-mwòpĕţa֖⁠y bĕ̇⁠ʼe֥reẕ miẕĕráֽyim׃"],[7,4,"וְ⁠לֹֽא־יִשְׁמַ֤ע אֲלֵ⁠כֶם֙ פַּרְעֹ֔ה וְ⁠נָתַתִּ֥י אֶת־יָדִ֖⁠י בְּ⁠מִצְרָ֑יִם וְ⁠הוֹצֵאתִ֨י אֶת־צִבְאֹתַ֜⁠י אֶת־עַמִּ֤⁠י בְנֵֽי־יִשְׂרָאֵל֙ מֵ⁠אֶ֣רֶץ מִצְרַ֔יִם בִּ⁠שְׁפָטִ֖ים גְּדֹלִֽים׃","wĕ⁠lòֽʼ-yişĕ̌ma֤ʻ ʼàlé⁠kem֙ pȧrĕʻò֔h wĕ⁠náţaţi֥̇y ʼeţ-yádi֖⁠y bĕ̇⁠miẕĕrá֑yim wĕ⁠hwòẕéʼţi֨y ʼeţ-ẕibĕʼòţa֜⁠y ʼeţ-ʻami֤̇⁠y bĕnéֽy-yişĕ̂ráʼél֙ mé⁠ʼe֣reẕ miẕĕra֔yim bi̇⁠şĕ̌páti֖ym gĕ̇dòliֽym׃"],[7,5,"וְ⁠יָדְע֤וּ מִצְרַ֨יִם֙ כִּֽי־אֲנִ֣י יְהוָ֔ה בִּ⁠נְטֹתִ֥⁠י אֶת־יָדִ֖⁠י עַל־מִצְרָ֑יִם וְ⁠הוֹצֵאתִ֥י אֶת־בְּנֵֽי־יִשְׂרָאֵ֖ל מִ⁠תּוֹכָֽ⁠ם׃","wĕ⁠yádĕʻ֤ẇ miẕĕra֨yim֙ kiֽ̇y-ʼàni֣y yĕhwá֔h bi̇⁠nĕtòţi֥⁠y ʼeţ-yádi֖⁠y ʻal-miẕĕrá֑yim wĕ⁠hwòẕéʼţi֥y ʼeţ-bĕ̇néֽy-yişĕ̂ráʼé֖l mi⁠ţ̇wòkáֽ⁠m׃"],[7,6,"וַ⁠יַּ֥עַשׂ מֹשֶׁ֖ה וְ⁠אַהֲרֹ֑ן כַּ⁠אֲשֶׁ֨ר צִוָּ֧ה יְהוָ֛ה אֹתָ֖⁠ם כֵּ֥ן עָשֽׂוּ׃","wa⁠yȧ֥ʻaş̂ mòşě֖h wĕ⁠ʼahàrò֑n kȧ⁠ʼàşě֨r ẕiwá֧̇h yĕhwá֛h ʼòţá֖⁠m ké֥̇n ʻáşֽ̂ẇ׃"],[7,7,"וּ⁠מֹשֶׁה֙ בֶּן־שְׁמֹנִ֣ים שָׁנָ֔ה וְ⁠אַֽהֲרֹ֔ן בֶּן־שָׁלֹ֥שׁ וּ⁠שְׁמֹנִ֖ים שָׁנָ֑ה בְּ⁠דַבְּרָ֖⁠ם אֶל־פַּרְעֹֽה׃פ","ẇ⁠mòşěh֙ bėn-şĕ̌mòni֣ym şá̌ná֔h wĕ⁠ʼֽahàrò֔n bėn-şá̌lò֥ş̌ ẇ⁠şĕ̌mòni֖ym şá̌ná֑h bĕ̇⁠dabĕ̇rá֖⁠m ʼel-pȧrĕʻòֽh׃p"],[7,8,"וַ⁠יֹּ֣אמֶר יְהוָ֔ה אֶל־מֹשֶׁ֥ה וְ⁠אֶֽל־אַהֲרֹ֖ן לֵ⁠אמֹֽר׃","wa⁠yò֣̇ʼmer yĕhwá֔h ʼel-mòşě֥h wĕ⁠ʼeֽl-ʼahàrò֖n lé⁠ʼmòֽr׃"],[7,9,"כִּי֩ יְדַבֵּ֨ר אֲלֵ⁠כֶ֤ם פַּרְעֹה֙ לֵ⁠אמֹ֔ר תְּנ֥וּ לָ⁠כֶ֖ם מוֹפֵ֑ת וְ⁠אָמַרְתָּ֣ אֶֽל־אַהֲרֹ֗ן קַ֧ח אֶֽת־מַטְּ⁠ךָ֛ וְ⁠הַשְׁלֵ֥ךְ לִ⁠פְנֵֽי־פַרְעֹ֖ה יְהִ֥י לְ⁠תַנִּֽין׃","ki̇y֩ yĕdabé̇֨r ʼàlé⁠ke֤m pȧrĕʻòh֙ lé⁠ʼmò֔r ţĕ̇n֥ẇ lá⁠ke֖m mwòpé֑ţ wĕ⁠ʼámarĕţá֣̇ ʼeֽl-ʼahàrò֗n qa֧ẖ ʼeֽţ-matĕ̇⁠ká֛ wĕ⁠haşĕ̌lé֥kĕ li⁠pĕnéֽy-parĕʻò֖h yĕhi֥y lĕ⁠ţaniֽ̇yn׃"],[7,10,"וַ⁠יָּבֹ֨א מֹשֶׁ֤ה וְ⁠אַהֲרֹן֙ אֶל־פַּרְעֹ֔ה וַ⁠יַּ֣עַשׂוּ כֵ֔ן כַּ⁠אֲשֶׁ֖ר צִוָּ֣ה יְהוָ֑ה וַ⁠יַּשְׁלֵ֨ךְ אַהֲרֹ֜ן אֶת־מַטֵּ֗⁠הוּ לִ⁠פְנֵ֥י פַרְעֹ֛ה וְ⁠לִ⁠פְנֵ֥י עֲבָדָ֖י⁠ו וַ⁠יְהִ֥י לְ⁠תַנִּֽין׃","wa⁠yá̇bò֨ʼ mòşě֤h wĕ⁠ʼahàròn֙ ʼel-pȧrĕʻò֔h wa⁠yȧ֣ʻaş̂ẇ ké֔n kȧ⁠ʼàşě֖r ẕiwá֣̇h yĕhwá֑h wa⁠yȧşĕ̌lé֨kĕ ʼahàrò֜n ʼeţ-maté̇֗⁠hẇ li⁠pĕné֥y parĕʻò֛h wĕ⁠li⁠pĕné֥y ʻàbádá֖y⁠w wa⁠yĕhi֥y lĕ⁠ţaniֽ̇yn׃"],[7,11,"וַ⁠יִּקְרָא֙ גַּם־פַּרְעֹ֔ה לַֽ⁠חֲכָמִ֖ים וְ⁠לַֽ⁠מְכַשְּׁפִ֑ים וַ⁠יַּֽעֲשׂ֨וּ גַם־הֵ֜ם חַרְטֻמֵּ֥י מִצְרַ֛יִם בְּ⁠לַהֲטֵי⁠הֶ֖ם כֵּֽן׃","wa⁠yi̇qĕráʼ֙ gȧm-pȧrĕʻò֔h lֽa⁠ẖàkámi֖ym wĕ⁠laֽ⁠mĕkaşĕ̇̌pi֑ym wa⁠yȧֽʻàş̂֨ẇ gam-hé֜m ẖarĕtumé֥̇y miẕĕra֛yim bĕ̇⁠lahàtéy⁠he֖m kéֽ̇n׃"],[7,12,"וַ⁠יַּשְׁלִ֨יכוּ֙ אִ֣ישׁ מַטֵּ֔⁠הוּ וַ⁠יִּהְי֖וּ לְ⁠תַנִּינִ֑ם וַ⁠יִּבְלַ֥ע מַטֵּֽה־אַהֲרֹ֖ן אֶת־מַטֹּתָֽ⁠ם׃","wa⁠yȧşĕ̌li֨ykẇ֙ ʼi֣yş̌ maté̇֔⁠hẇ wa⁠yi̇hĕy֖ẇ lĕ⁠ţani̇yni֑m wa⁠yi̇bĕla֥ʻ matéֽ̇h-ʼahàrò֖n ʼeţ-matò̇ţáֽ⁠m׃"],[7,13,"וַ⁠יֶּחֱזַק֙ לֵ֣ב פַּרְעֹ֔ה וְ⁠לֹ֥א שָׁמַ֖ע אֲלֵ⁠הֶ֑ם כַּ⁠אֲשֶׁ֖ר דִּבֶּ֥ר יְהוָֽה׃פ","wa⁠yėẖèzaq֙ lé֣b pȧrĕʻò֔h wĕ⁠lò֥ʼ şá̌ma֖ʻ ʼàlé⁠he֑m kȧ⁠ʼàşě֖r di̇bė֥r yĕhwáֽh׃p"],[7,14,"וַ⁠יֹּ֤אמֶר יְהוָה֙ אֶל־מֹשֶׁ֔ה כָּבֵ֖ד לֵ֣ב פַּרְעֹ֑ה מֵאֵ֖ן לְ⁠שַׁלַּ֥ח הָ⁠עָֽם׃","wa⁠yò֤̇ʼmer yĕhwáh֙ ʼel-mòşě֔h ká̇bé֖d lé֣b pȧrĕʻò֑h méʼé֖n lĕ⁠şǎlȧ֥ẖ há⁠ʻáֽm׃"],[7,15,"לֵ֣ךְ אֶל־פַּרְעֹ֞ה בַּ⁠בֹּ֗קֶר הִנֵּה֙ יֹצֵ֣א הַ⁠מַּ֔יְמָ⁠ה וְ⁠נִצַּבְתָּ֥ לִ⁠קְרָאת֖⁠וֹ עַל־שְׂפַ֣ת הַ⁠יְאֹ֑ר וְ⁠הַ⁠מַּטֶּ֛ה אֲשֶׁר־נֶהְפַּ֥ךְ לְ⁠נָחָ֖שׁ תִּקַּ֥ח בְּ⁠יָדֶֽ⁠ךָ׃","lé֣kĕ ʼel-pȧrĕʻò֞h bȧ⁠bò̇֗qer hiné̇h֙ yòẕé֣ʼ ha⁠mȧ֔yĕmá⁠h wĕ⁠niẕȧbĕţá֥̇ li⁠qĕráʼţ֖⁠wò ʻal-şĕ̂pa֣ţ ha⁠yĕʼò֑r wĕ⁠ha⁠mȧtė֛h ʼàşěr-nehĕpȧ֥kĕ lĕ⁠náẖá֖ş̌ ţi̇qȧ֥ẖ bĕ̇⁠yádeֽ⁠ká׃"],[7,16,"וְ⁠אָמַרְתָּ֣ אֵלָ֗י⁠ו יְהוָ֞ה אֱלֹהֵ֤י הָ⁠עִבְרִים֙ שְׁלָחַ֤⁠נִי אֵלֶ֨י⁠ךָ֙ לֵ⁠אמֹ֔ר שַׁלַּח֙ אֶת־עַמִּ֔⁠י וְ⁠יַֽעַבְדֻ֖⁠נִי בַּ⁠מִּדְבָּ֑ר וְ⁠הִנֵּ֥ה לֹא־שָׁמַ֖עְתָּ עַד־כֹּֽה׃","wĕ⁠ʼámarĕţá֣̇ ʼélá֗y⁠w yĕhwá֞h ʼèlòhé֤y há⁠ʻibĕriym֙ şĕ̌láẖa֤⁠niy ʼéle֨y⁠ká֙ lé⁠ʼmò֔r şǎlȧẖ֙ ʼeţ-ʻami̇֔⁠y wĕ⁠yaֽʻabĕdu֖⁠niy bȧ⁠mi̇dĕbá֑̇r wĕ⁠hiné֥̇h lòʼ-şá̌ma֖ʻĕţá̇ ʻad-kòֽ̇h׃"],[7,17,"כֹּ֚ה אָמַ֣ר יְהוָ֔ה בְּ⁠זֹ֣את תֵּדַ֔ע כִּ֖י אֲנִ֣י יְהוָ֑ה הִנֵּ֨ה אָנֹכִ֜י מַכֶּ֣ה ׀ בַּ⁠מַּטֶּ֣ה אֲשֶׁר־בְּ⁠יָדִ֗⁠י עַל־הַ⁠מַּ֛יִם אֲשֶׁ֥ר בַּ⁠יְאֹ֖ר וְ⁠נֶהֶפְכ֥וּ לְ⁠דָֽם׃","kò֚̇h ʼáma֣r yĕhwá֔h bĕ̇⁠zò֣ʼţ ţé̇da֔ʻ ki֖̇y ʼàni֣y yĕhwá֑h hiné̇֨h ʼánòki֜y makė֣h ׀ bȧ⁠mȧtė֣h ʼàşěr-bĕ̇⁠yádi֗⁠y ʻal-ha⁠mȧ֛yim ʼàşě֥r bȧ⁠yĕʼò֖r wĕ⁠nehepĕk֥ẇ lĕ⁠dáֽm׃"],[7,18,"וְ⁠הַ⁠דָּגָ֧ה אֲשֶׁר־בַּ⁠יְאֹ֛ר תָּמ֖וּת וּ⁠בָאַ֣שׁ הַ⁠יְאֹ֑ר וְ⁠נִלְא֣וּ מִצְרַ֔יִם לִ⁠שְׁתּ֥וֹת מַ֖יִם מִן־הַ⁠יְאֹֽר׃ס","wĕ⁠ha⁠dá̇gá֧h ʼàşěr-bȧ⁠yĕʼò֛r ţá̇m֖ẇţ ẇ⁠báʼa֣ş̌ ha⁠yĕʼò֑r wĕ⁠nilĕʼ֣ẇ miẕĕra֔yim li⁠şĕ̌ţ֥̇wòţ ma֖yim min-ha⁠yĕʼòֽr׃s"],[7,19,"וַ⁠יֹּ֨אמֶר יְהוָ֜ה אֶל־מֹשֶׁ֗ה אֱמֹ֣ר אֶֽל־אַהֲרֹ֡ן קַ֣ח מַטְּ⁠ךָ֣ וּ⁠נְטֵֽה־יָדְ⁠ךָ֩ עַל־מֵימֵ֨י מִצְרַ֜יִם עַֽל־נַהֲרֹתָ֣⁠ם ׀ עַל־יְאֹרֵי⁠הֶ֣ם וְ⁠עַל־אַגְמֵי⁠הֶ֗ם וְ⁠עַ֛ל כָּל־מִקְוֵ֥ה מֵימֵי⁠הֶ֖ם וְ⁠יִֽהְיוּ־דָ֑ם וְ⁠הָ֤יָה דָם֙ בְּ⁠כָל־אֶ֣רֶץ מִצְרַ֔יִם וּ⁠בָ⁠עֵצִ֖ים וּ⁠בָ⁠אֲבָנִֽים׃","wa⁠yò̇֨ʼmer yĕhwá֜h ʼel-mòşě֗h ʼèmò֣r ʼeֽl-ʼahàrò֡n qa֣ẖ matĕ̇⁠ká֣ ẇ⁠nĕtéֽh-yádĕ⁠ká֩ ʻal-méymé֨y miẕĕra֜yim ʻaֽl-nahàròţá֣⁠m ׀ ʻal-yĕʼòréy⁠he֣m wĕ⁠ʻal-ʼagĕméy⁠he֗m wĕ⁠ʻa֛l ká̇l-miqĕwé֥h méyméy⁠he֖m wĕ⁠yiֽhĕyẇ-dá֑m wĕ⁠há֤yáh dám֙ bĕ̇⁠kál-ʼe֣reẕ miẕĕra֔yim ẇ⁠bá⁠ʻéẕi֖ym ẇ⁠bá⁠ʼàbániֽym׃"],[7,20,"וַ⁠יַּֽעֲשׂוּ־כֵן֩ מֹשֶׁ֨ה וְ⁠אַהֲרֹ֜ן כַּ⁠אֲשֶׁ֣ר ׀ צִוָּ֣ה יְהוָ֗ה וַ⁠יָּ֤רֶם בַּ⁠מַּטֶּה֙ וַ⁠יַּ֤ךְ אֶת־הַ⁠מַּ֨יִם֙ אֲשֶׁ֣ר בַּ⁠יְאֹ֔ר לְ⁠עֵינֵ֣י פַרְעֹ֔ה וּ⁠לְ⁠עֵינֵ֖י עֲבָדָ֑י⁠ו וַ⁠יֵּהָֽפְכ֛וּ כָּל־הַ⁠מַּ֥יִם אֲשֶׁר־בַּ⁠יְאֹ֖ר לְ⁠דָֽם׃","wa⁠yȧֽʻàş̂ẇ-kén֩ mòşě֨h wĕ⁠ʼahàrò֜n kȧ⁠ʼàşě֣r ׀ ẕiwá֣̇h yĕhwá֗h wa⁠yá֤̇rem bȧ⁠mȧtėh֙ wa⁠yȧ֤kĕ ʼeţ-ha⁠mȧ֨yim֙ ʼàşě֣r bȧ⁠yĕʼò֔r lĕ⁠ʻéyné֣y parĕʻò֔h ẇ⁠lĕ⁠ʻéyné֖y ʻàbádá֑y⁠w wa⁠yé̇háֽpĕk֛ẇ ká̇l-ha⁠mȧ֥yim ʼàşěr-bȧ⁠yĕʼò֖r lĕ⁠dáֽm׃"],[7,21,"וְ⁠הַ⁠דָּגָ֨ה אֲשֶׁר־בַּ⁠יְאֹ֥ר מֵ֨תָה֙ וַ⁠יִּבְאַ֣שׁ הַ⁠יְאֹ֔ר וְ⁠לֹא־יָכְל֣וּ מִצְרַ֔יִם לִ⁠שְׁתּ֥וֹת מַ֖יִם מִן־הַ⁠יְאֹ֑ר וַ⁠יְהִ֥י הַ⁠דָּ֖ם בְּ⁠כָל־אֶ֥רֶץ מִצְרָֽיִם׃","wĕ⁠ha⁠dá̇gá֨h ʼàşěr-bȧ⁠yĕʼò֥r mé֨ţáh֙ wa⁠yi̇bĕʼa֣ş̌ ha⁠yĕʼò֔r wĕ⁠lòʼ-yákĕl֣ẇ miẕĕra֔yim li⁠şĕ̌ţ֥̇wòţ ma֖yim min-ha⁠yĕʼò֑r wa⁠yĕhi֥y ha⁠dá֖̇m bĕ̇⁠kál-ʼe֥reẕ miẕĕráֽyim׃"],[7,22,"וַ⁠יַּֽעֲשׂוּ־כֵ֛ן חַרְטֻמֵּ֥י מִצְרַ֖יִם בְּ⁠לָטֵי⁠הֶ֑ם וַ⁠יֶּחֱזַ֤ק לֵב־פַּרְעֹה֙ וְ⁠לֹא־שָׁמַ֣ע אֲלֵ⁠הֶ֔ם כַּ⁠אֲשֶׁ֖ר דִּבֶּ֥ר יְהוָֽה׃","wa⁠yȧֽʻàş̂ẇ-ké֛n ẖarĕtumé֥̇y miẕĕra֖yim bĕ̇⁠látéy⁠he֑m wa⁠yėẖèza֤q léb-pȧrĕʻòh֙ wĕ⁠lòʼ-şá̌ma֣ʻ ʼàlé⁠he֔m kȧ⁠ʼàşě֖r di̇bė֥r yĕhwáֽh׃"],[7,23,"וַ⁠יִּ֣פֶן פַּרְעֹ֔ה וַ⁠יָּבֹ֖א אֶל־בֵּית֑⁠וֹ וְ⁠לֹא־שָׁ֥ת לִבּ֖⁠וֹ גַּם־לָ⁠זֹֽאת׃","wa⁠yi֣̇pen pȧrĕʻò֔h wa⁠yá̇bò֖ʼ ʼel-bé̇yţ֑⁠wò wĕ⁠lòʼ-şá֥̌ţ liḃ֖⁠wò gȧm-lá⁠zòֽʼţ׃"],[7,24,"וַ⁠יַּחְפְּר֧וּ כָל־מִצְרַ֛יִם סְבִיבֹ֥ת הַ⁠יְאֹ֖ר מַ֣יִם לִ⁠שְׁתּ֑וֹת כִּ֣י לֹ֤א יָֽכְלוּ֙ לִ⁠שְׁתֹּ֔ת מִ⁠מֵּימֵ֖י הַ⁠יְאֹֽר׃","wa⁠yȧẖĕpĕ̇r֧ẇ kál-miẕĕra֛yim sĕbiybò֥ţ ha⁠yĕʼò֖r ma֣yim li⁠şĕ̌ţ֑̇wòţ ki֣̇y lò֤ʼ yáֽkĕlẇ֙ li⁠şĕ̌ţò̇֔ţ mi⁠mé̇ymé֖y ha⁠yĕʼòֽr׃"],[7,25,"וַ⁠יִּמָּלֵ֖א שִׁבְעַ֣ת יָמִ֑ים אַחֲרֵ֥י הַכּוֹת־יְהוָ֖ה אֶת־הַ⁠יְאֹֽר׃פ","wa⁠yi̇má̇lé֖ʼ şǐbĕʻa֣ţ yámi֑ym ʼaẖàré֥y hak̇wòţ-yĕhwá֖h ʼeţ-ha⁠yĕʼòֽr׃p"],[8,1,"וַ⁠יֹּ֤אמֶר יְהוָה֙ אֶל־מֹשֶׁ֔ה בֹּ֖א אֶל־פַּרְעֹ֑ה וְ⁠אָמַרְתָּ֣ אֵלָ֗י⁠ו כֹּ֚ה אָמַ֣ר יְהוָ֔ה שַׁלַּ֥ח אֶת־עַמִּ֖⁠י וְ⁠יַֽעַבְדֻֽ⁠נִי׃","wa⁠yò֤̇ʼmer yĕhwáh֙ ʼel-mòşě֔h bò֖̇ʼ ʼel-pȧrĕʻò֑h wĕ⁠ʼámarĕţá֣̇ ʼélá֗y⁠w kò֚̇h ʼáma֣r yĕhwá֔h şǎlȧ֥ẖ ʼeţ-ʻami֖̇⁠y wĕ⁠yaֽʻabĕduֽ⁠niy׃"],[8,2,"וְ⁠אִם־מָאֵ֥ן אַתָּ֖ה לְ⁠שַׁלֵּ֑חַ הִנֵּ֣ה אָנֹכִ֗י נֹגֵ֛ף אֶת־כָּל־גְּבוּלְ⁠ךָ֖ בַּֽ⁠צְפַרְדְּעִֽים׃","wĕ⁠ʼim-máʼé֥n ʼaţá֖̇h lĕ⁠şǎlé֑̇ẖa hiné֣̇h ʼánòki֗y nògé֛p ʼeţ-ká̇l-gĕ̇bẇlĕ⁠ká֖ bȧֽ⁠ẕĕparĕdĕ̇ʻiֽym׃"],[8,3,"וְ⁠שָׁרַ֣ץ הַ⁠יְאֹר֮ צְפַרְדְּעִים֒ וְ⁠עָלוּ֙ וּ⁠בָ֣אוּ בְּ⁠בֵיתֶ֔⁠ךָ וּ⁠בַ⁠חֲדַ֥ר מִשְׁכָּבְ⁠ךָ֖ וְ⁠עַל־מִטָּתֶ֑⁠ךָ וּ⁠בְ⁠בֵ֤ית עֲבָדֶ֨י⁠ךָ֙ וּ⁠בְ⁠עַמֶּ֔⁠ךָ וּ⁠בְ⁠תַנּוּרֶ֖י⁠ךָ וּ⁠בְ⁠מִשְׁאֲרוֹתֶֽי⁠ךָ׃","wĕ⁠şá̌ra֣ẕ ha⁠yĕʼòr֮ ẕĕparĕdĕ̇ʻiym֒ wĕ⁠ʻálẇ֙ ẇ⁠bá֣ʼẇ bĕ̇⁠béyţe֔⁠ká ẇ⁠ba⁠ẖàda֥r mişĕ̌ká̇bĕ⁠ká֖ wĕ⁠ʻal-mitá̇ţe֑⁠ká ẇ⁠bĕ⁠bé֤yţ ʻàbáde֨y⁠ká֙ ẇ⁠bĕ⁠ʻamė֔⁠ká ẇ⁠bĕ⁠ţaṅẇre֖y⁠ká ẇ⁠bĕ⁠mişĕ̌ʼàrwòţeֽy⁠ká׃"],[8,4,"וּ⁠בְ⁠כָ֥ה וּֽ⁠בְ⁠עַמְּ⁠ךָ֖ וּ⁠בְ⁠כָל־עֲבָדֶ֑י⁠ךָ יַעֲל֖וּ הַֽ⁠צְפַרְדְּעִֽים׃","ẇ⁠bĕ⁠ká֥h ẇֽ⁠bĕ⁠ʻamĕ̇⁠ká֖ ẇ⁠bĕ⁠kál-ʻàbáde֑y⁠ká yaʻàl֖ẇ haֽ⁠ẕĕparĕdĕ̇ʻiֽym׃"],[8,5,"וַ⁠יֹּ֣אמֶר יְהוָה֮ אֶל־מֹשֶׁה֒ אֱמֹ֣ר אֶֽל־אַהֲרֹ֗ן נְטֵ֤ה אֶת־יָדְ⁠ךָ֙ בְּ⁠מַטֶּ֔⁠ךָ עַל־הַ֨⁠נְּהָרֹ֔ת עַל־הַ⁠יְאֹרִ֖ים וְ⁠עַל־הָ⁠אֲגַמִּ֑ים וְ⁠הַ֥עַל אֶת־הַֽ⁠צְפַרְדְּעִ֖ים עַל־אֶ֥רֶץ מִצְרָֽיִם׃","wa⁠yò֣̇ʼmer yĕhwáh֮ ʼel-mòşěh֒ ʼèmò֣r ʼeֽl-ʼahàrò֗n nĕté֤h ʼeţ-yádĕ⁠ká֙ bĕ̇⁠matė֔⁠ká ʻal-ha֨⁠nĕ̇hárò֔ţ ʻal-ha⁠yĕʼòri֖ym wĕ⁠ʻal-há⁠ʼàgami֑̇ym wĕ⁠ha֥ʻal ʼeţ-haֽ⁠ẕĕparĕdĕ̇ʻi֖ym ʻal-ʼe֥reẕ miẕĕráֽyim׃"],[8,6,"וַ⁠יֵּ֤ט אַהֲרֹן֙ אֶת־יָד֔⁠וֹ עַ֖ל מֵימֵ֣י מִצְרָ֑יִם וַ⁠תַּ֨עַל֙ הַ⁠צְּפַרְדֵּ֔עַ וַ⁠תְּכַ֖ס אֶת־אֶ֥רֶץ מִצְרָֽיִם׃","wa⁠yé֤̇t ʼahàròn֙ ʼeţ-yád֔⁠wò ʻa֖l méymé֣y miẕĕrá֑yim wa⁠ţȧ֨ʻal֙ ha⁠ẕĕ̇parĕdé̇֔ʻa wa⁠ţĕ̇ka֖s ʼeţ-ʼe֥reẕ miẕĕráֽyim׃"],[8,7,"וַ⁠יַּֽעֲשׂוּ־כֵ֥ן הַֽ⁠חֲרְטֻמִּ֖ים בְּ⁠לָטֵי⁠הֶ֑ם וַ⁠יַּעֲל֥וּ אֶת־הַֽ⁠צְפַרְדְּעִ֖ים עַל־אֶ֥רֶץ מִצְרָֽיִם׃","wa⁠yȧֽʻàş̂ẇ-ké֥n hֽa⁠ẖàrĕtumi֖̇ym bĕ̇⁠látéy⁠he֑m wa⁠yȧʻàl֥ẇ ʼeţ-haֽ⁠ẕĕparĕdĕ̇ʻi֖ym ʻal-ʼe֥reẕ miẕĕráֽyim׃"],[8,8,"וַ⁠יִּקְרָ֨א פַרְעֹ֜ה לְ⁠מֹשֶׁ֣ה וּֽ⁠לְ⁠אַהֲרֹ֗ן וַ⁠יֹּ֨אמֶר֙ הַעְתִּ֣ירוּ אֶל־יְהוָ֔ה וְ⁠יָסֵר֙ הַֽ⁠צְפַרְדְּעִ֔ים מִמֶּ֖⁠נִּי וּ⁠מֵֽ⁠עַמִּ֑⁠י וַ⁠אֲשַׁלְּחָה֙ אֶת־הָ⁠עָ֔ם וְ⁠יִזְבְּח֖וּ לַ⁠יהוָֽה׃","wa⁠yi̇qĕrá֨ʼ parĕʻò֜h lĕ⁠mòşě֣h ẇֽ⁠lĕ⁠ʼahàrò֗n wa⁠yò̇֨ʼmer֙ haʻĕţi֣̇yrẇ ʼel-yĕhwá֔h wĕ⁠yásér֙ haֽ⁠ẕĕparĕdĕ̇ʻi֔ym mimė֖⁠ni̇y ẇ⁠méֽ⁠ʻami֑̇⁠y wa⁠ʼàşǎlĕ̇ẖáh֙ ʼeţ-há⁠ʻá֔m wĕ⁠yizĕbĕ̇ẖ֖ẇ la⁠yhwáֽh׃"],[8,9,"וַ⁠יֹּ֣אמֶר מֹשֶׁ֣ה לְ⁠פַרְעֹה֮ הִתְפָּאֵ֣ר עָלַ⁠י֒ לְ⁠מָתַ֣י ׀ אַעְתִּ֣יר לְ⁠ךָ֗ וְ⁠לַ⁠עֲבָדֶ֨י⁠ךָ֙ וּֽ⁠לְ⁠עַמְּ⁠ךָ֔ לְ⁠הַכְרִית֙ הַֽ⁠צֲפַרְדְּעִ֔ים מִמְּ⁠ךָ֖ וּ⁠מִ⁠בָּתֶּ֑י⁠ךָ רַ֥ק בַּ⁠יְאֹ֖ר תִּשָּׁאַֽרְנָה׃","wa⁠yò֣̇ʼmer mòşě֣h lĕ⁠parĕʻòh֮ hiţĕpá̇ʼé֣r ʻála⁠y֒ lĕ⁠máţa֣y ׀ ʼaʻĕţi֣̇yr lĕ⁠ká֗ wĕ⁠la⁠ʻàbáde֨y⁠ká֙ ẇֽ⁠lĕ⁠ʻamĕ̇⁠ká֔ lĕ⁠hakĕriyţ֙ haֽ⁠ẕàparĕdĕ̇ʻi֔ym mimĕ̇⁠ká֖ ẇ⁠mi⁠bá̇ţė֑y⁠ká ra֥q bȧ⁠yĕʼò֖r ţi̇şá̇̌ʼaֽrĕnáh׃"],[8,10,"וַ⁠יֹּ֖אמֶר לְ⁠מָחָ֑ר וַ⁠יֹּ֨אמֶר֙ כִּ⁠דְבָ֣רְ⁠ךָ֔ לְמַ֣עַן תֵּדַ֔ע כִּי־אֵ֖ין כַּ⁠יהוָ֥ה אֱלֹהֵֽי⁠נוּ׃","wa⁠yò֖̇ʼmer lĕ⁠máẖá֑r wa⁠yò̇֨ʼmer֙ ki̇⁠dĕbá֣rĕ⁠ká֔ lĕma֣ʻan ţé̇da֔ʻ ki̇y-ʼé֖yn kȧ⁠yhwá֥h ʼèlòhéֽy⁠nẇ׃"],[8,11,"וְ⁠סָר֣וּ הַֽ⁠צְפַרְדְּעִ֗ים מִמְּ⁠ךָ֙ וּ⁠מִ⁠בָּ֣תֶּ֔י⁠ךָ וּ⁠מֵ⁠עֲבָדֶ֖י⁠ךָ וּ⁠מֵ⁠עַמֶּ֑⁠ךָ רַ֥ק בַּ⁠יְאֹ֖ר תִּשָּׁאַֽרְנָה׃","wĕ⁠sár֣ẇ haֽ⁠ẕĕparĕdĕ̇ʻi֗ym mimĕ̇⁠ká֙ ẇ⁠mi⁠bá֣̇ţė֔y⁠ká ẇ⁠mé⁠ʻàbáde֖y⁠ká ẇ⁠mé⁠ʻamė֑⁠ká ra֥q bȧ⁠yĕʼò֖r ţi̇şá̇̌ʼaֽrĕnáh׃"],[8,12,"וַ⁠יֵּצֵ֥א מֹשֶׁ֛ה וְ⁠אַהֲרֹ֖ן מֵ⁠עִ֣ם פַּרְעֹ֑ה וַ⁠יִּצְעַ֤ק מֹשֶׁה֙ אֶל־יְהוָ֔ה עַל־דְּבַ֥ר הַֽ⁠צְפַרְדְּעִ֖ים אֲשֶׁר־שָׂ֥ם לְ⁠פַרְעֹֽה׃","wa⁠yé̇ẕé֥ʼ mòşě֛h wĕ⁠ʼahàrò֖n mé⁠ʻi֣m pȧrĕʻò֑h wa⁠yi̇ẕĕʻa֤q mòşěh֙ ʼel-yĕhwá֔h ʻal-dĕ̇ba֥r haֽ⁠ẕĕparĕdĕ̇ʻi֖ym ʼàşěr-şá֥̂m lĕ⁠parĕʻòֽh׃"],[8,13,"וַ⁠יַּ֥עַשׂ יְהוָ֖ה כִּ⁠דְבַ֣ר מֹשֶׁ֑ה וַ⁠יָּמֻ֨תוּ֙ הַֽ⁠צְפַרְדְּעִ֔ים מִן־הַ⁠בָּתִּ֥ים מִן־הַ⁠חֲצֵרֹ֖ת וּ⁠מִן־הַ⁠שָּׂדֹֽת׃","wa⁠yȧ֥ʻaş̂ yĕhwá֖h ki̇⁠dĕba֣r mòşě֑h wa⁠yá̇mu֨ţẇ֙ haֽ⁠ẕĕparĕdĕ̇ʻi֔ym min-ha⁠bá̇ţi֥̇ym min-ha⁠ẖàẕérò֖ţ ẇ⁠min-ha⁠şá̇̂dòֽţ׃"],[8,14,"וַ⁠יִּצְבְּר֥וּ אֹתָ֖⁠ם חֳמָרִ֣ם חֳמָרִ֑ם וַ⁠תִּבְאַ֖שׁ הָ⁠אָֽרֶץ׃","wa⁠yi̇ẕĕbĕ̇r֥ẇ ʼòţá֖⁠m ẖomári֣m ẖomári֑m wa⁠ţi̇bĕʼa֖ş̌ há⁠ʼáֽreẕ׃"],[8,15,"וַ⁠יַּ֣רְא פַּרְעֹ֗ה כִּ֤י הָֽיְתָה֙ הָֽ⁠רְוָחָ֔ה וְ⁠הַכְבֵּד֙ אֶת־לִבּ֔⁠וֹ וְ⁠לֹ֥א שָׁמַ֖ע אֲלֵ⁠הֶ֑ם כַּ⁠אֲשֶׁ֖ר דִּבֶּ֥ר יְהוָֽה׃ס","wa⁠yȧ֣rĕʼ pȧrĕʻò֗h ki֤̇y háֽyĕţáh֙ háֽ⁠rĕwáẖá֔h wĕ⁠hakĕbé̇d֙ ʼeţ-liḃ֔⁠wò wĕ⁠lò֥ʼ şá̌ma֖ʻ ʼàlé⁠he֑m kȧ⁠ʼàşě֖r di̇bė֥r yĕhwáֽh׃s"],[8,16,"וַ⁠יֹּ֣אמֶר יְהוָה֮ אֶל־מֹשֶׁה֒ אֱמֹר֙ אֶֽל־אַהֲרֹ֔ן נְטֵ֣ה אֶֽת־מַטְּ⁠ךָ֔ וְ⁠הַ֖ךְ אֶת־עֲפַ֣ר הָ⁠אָ֑רֶץ וְ⁠הָיָ֥ה לְ⁠כִנִּ֖ם בְּ⁠כָל־אֶ֥רֶץ מִצְרָֽיִם׃","wa⁠yò֣̇ʼmer yĕhwáh֮ ʼel-mòşěh֒ ʼèmòr֙ ʼeֽl-ʼahàrò֔n nĕté֣h ʼeֽţ-matĕ̇⁠ká֔ wĕ⁠ha֖kĕ ʼeţ-ʻàpa֣r há⁠ʼá֑reẕ wĕ⁠háyá֥h lĕ⁠kini֖̇m bĕ̇⁠kál-ʼe֥reẕ miẕĕráֽyim׃"],[8,17,"וַ⁠יַּֽעֲשׂוּ־כֵ֗ן וַ⁠יֵּט֩ אַהֲרֹ֨ן אֶת־יָד֤⁠וֹ בְ⁠מַטֵּ֨⁠הוּ֙ וַ⁠יַּךְ֙ אֶת־עֲפַ֣ר הָ⁠אָ֔רֶץ וַ⁠תְּהִי֙ הַ⁠כִּנָּ֔ם בָּ⁠אָדָ֖ם וּ⁠בַ⁠בְּהֵמָ֑ה כָּל־עֲפַ֥ר הָ⁠אָ֛רֶץ הָיָ֥ה כִנִּ֖ים בְּ⁠כָל־אֶ֥רֶץ מִצְרָֽיִם׃","wa⁠yȧֽʻàş̂ẇ-ké֗n wa⁠yé̇t֩ ʼahàrò֨n ʼeţ-yád֤⁠wò bĕ⁠maté̇֨⁠hẇ֙ wa⁠yȧkĕ֙ ʼeţ-ʻàpa֣r há⁠ʼá֔reẕ wa⁠ţĕ̇hiy֙ ha⁠ki̇ná̇֔m bá̇⁠ʼádá֖m ẇ⁠ba⁠bĕ̇hémá֑h ká̇l-ʻàpa֥r há⁠ʼá֛reẕ háyá֥h kini֖̇ym bĕ̇⁠kál-ʼe֥reẕ miẕĕráֽyim׃"],[8,18,"וַ⁠יַּעֲשׂוּ־כֵ֨ן הַ⁠חַרְטֻמִּ֧ים בְּ⁠לָטֵי⁠הֶ֛ם לְ⁠הוֹצִ֥יא אֶת־הַ⁠כִּנִּ֖ים וְ⁠לֹ֣א יָכֹ֑לוּ וַ⁠תְּהִי֙ הַ⁠כִּנָּ֔ם בָּ⁠אָדָ֖ם וּ⁠בַ⁠בְּהֵמָֽה׃","wa⁠yȧʻàş̂ẇ-ké֨n ha⁠ẖarĕtumi֧̇ym bĕ̇⁠látéy⁠he֛m lĕ⁠hwòẕi֥yʼ ʼeţ-ha⁠ki̇ni֖̇ym wĕ⁠lò֣ʼ yákò֑lẇ wa⁠ţĕ̇hiy֙ ha⁠ki̇ná̇֔m bá̇⁠ʼádá֖m ẇ⁠ba⁠bĕ̇hémáֽh׃"],[8,19,"וַ⁠יֹּאמְר֤וּ הַֽ⁠חַרְטֻמִּים֙ אֶל־פַּרְעֹ֔ה אֶצְבַּ֥ע אֱלֹהִ֖ים הִ֑וא וַ⁠יֶּחֱזַ֤ק לֵב־פַּרְעֹה֙ וְ⁠לֹֽא־שָׁמַ֣ע אֲלֵ⁠הֶ֔ם כַּ⁠אֲשֶׁ֖ר דִּבֶּ֥ר יְהוָֽה׃ס","wa⁠yò̇ʼmĕr֤ẇ haֽ⁠ẖarĕtumi̇ym֙ ʼel-pȧrĕʻò֔h ʼeẕĕbȧ֥ʻ ʼèlòhi֖ym hi֑wʼ wa⁠yėẖèza֤q léb-pȧrĕʻòh֙ wĕ⁠lòֽʼ-şá̌ma֣ʻ ʼàlé⁠he֔m kȧ⁠ʼàşě֖r di̇bė֥r yĕhwáֽh׃s"],[8,20,"וַ⁠יֹּ֨אמֶר יְהוָ֜ה אֶל־מֹשֶׁ֗ה הַשְׁכֵּ֤ם בַּ⁠בֹּ֨קֶר֙ וְ⁠הִתְיַצֵּב֙ לִ⁠פְנֵ֣י פַרְעֹ֔ה הִנֵּ֖ה יוֹצֵ֣א הַ⁠מָּ֑יְמָ⁠ה וְ⁠אָמַרְתָּ֣ אֵלָ֗י⁠ו כֹּ֚ה אָמַ֣ר יְהוָ֔ה שַׁלַּ֥ח עַמִּ֖⁠י וְ⁠יַֽעַבְדֻֽ⁠נִי׃","wa⁠yò̇֨ʼmer yĕhwá֜h ʼel-mòşě֗h haşĕ̌ké֤̇m bȧ⁠bò̇֨qer֙ wĕ⁠hiţĕyaẕé̇b֙ li⁠pĕné֣y parĕʻò֔h hiné֖̇h ywòẕé֣ʼ ha⁠má֑̇yĕmá⁠h wĕ⁠ʼámarĕţá֣̇ ʼélá֗y⁠w kò֚̇h ʼáma֣r yĕhwá֔h şǎlȧ֥ẖ ʻami֖̇⁠y wĕ⁠yaֽʻabĕduֽ⁠niy׃"],[8,21,"כִּ֣י אִם־אֵינְ⁠ךָ֮ מְשַׁלֵּ֣חַ אֶת־עַמִּ⁠י֒ הִנְ⁠נִי֩ מַשְׁלִ֨יחַ בְּ⁠ךָ֜ וּ⁠בַ⁠עֲבָדֶ֧י⁠ךָ וּֽ⁠בְ⁠עַמְּ⁠ךָ֛ וּ⁠בְ⁠בָתֶּ֖י⁠ךָ אֶת־הֶ⁠עָרֹ֑ב וּ⁠מָ֨לְא֜וּ בָּתֵּ֤י מִצְרַ֨יִם֙ אֶת־הֶ֣⁠עָרֹ֔ב וְ⁠גַ֥ם הָ⁠אֲדָמָ֖ה אֲשֶׁר־הֵ֥ם עָלֶֽי⁠הָ׃","ki֣̇y ʼim-ʼéynĕ⁠ká֮ mĕşǎlé֣̇ẖa ʼeţ-ʻami̇⁠y֒ hinĕ⁠niy֩ maşĕ̌li֨yẖa bĕ̇⁠ká֜ ẇ⁠ba⁠ʻàbáde֧y⁠ká ẇֽ⁠bĕ⁠ʻamĕ̇⁠ká֛ ẇ⁠bĕ⁠báţė֖y⁠ká ʼeţ-he⁠ʻárò֑b ẇ⁠má֨lĕʼ֜ẇ bá̇ţé֤̇y miẕĕra֨yim֙ ʼeţ-he֣⁠ʻárò֔b wĕ⁠ga֥m há⁠ʼàdámá֖h ʼàşěr-hé֥m ʻáleֽy⁠há׃"],[8,22,"וְ⁠הִפְלֵיתִי֩ בַ⁠יּ֨וֹם הַ⁠ה֜וּא אֶת־אֶ֣רֶץ גֹּ֗שֶׁן אֲשֶׁ֤ר עַמִּ⁠י֙ עֹמֵ֣ד עָלֶ֔י⁠הָ לְ⁠בִלְתִּ֥י הֱיֽוֹת־שָׁ֖ם עָרֹ֑ב לְמַ֣עַן תֵּדַ֔ע כִּ֛י אֲנִ֥י יְהוָ֖ה בְּ⁠קֶ֥רֶב הָ⁠אָֽרֶץ׃","wĕ⁠hipĕléyţiy֩ ba⁠ẏ֨wòm ha⁠h֜ẇʼ ʼeţ-ʼe֣reẕ gò̇֗şěn ʼàşě֤r ʻami̇⁠y֙ ʻòmé֣d ʻále֔y⁠há lĕ⁠bilĕţi֥̇y hèyֽwòţ-şá֖̌m ʻárò֑b lĕma֣ʻan ţé̇da֔ʻ ki֛̇y ʼàni֥y yĕhwá֖h bĕ̇⁠qe֥reb há⁠ʼáֽreẕ׃"],[8,23,"וְ⁠שַׂמְתִּ֣י פְדֻ֔ת בֵּ֥ין עַמִּ֖⁠י וּ⁠בֵ֣ין עַמֶּ֑⁠ךָ לְ⁠מָחָ֥ר יִהְיֶ֖ה הָ⁠אֹ֥ת הַ⁠זֶּֽה׃","wĕ⁠şâmĕţi֣̇y pĕdu֔ţ bé֥̇yn ʻami֖̇⁠y ẇ⁠bé֣yn ʻamė֑⁠ká lĕ⁠máẖá֥r yihĕye֖h há⁠ʼò֥ţ ha⁠zėֽh׃"],[8,24,"וַ⁠יַּ֤עַשׂ יְהוָה֙ כֵּ֔ן וַ⁠יָּבֹא֙ עָרֹ֣ב כָּבֵ֔ד בֵּ֥יתָ⁠ה פַרְעֹ֖ה וּ⁠בֵ֣ית עֲבָדָ֑י⁠ו וּ⁠בְ⁠כָל־אֶ֧רֶץ מִצְרַ֛יִם תִּשָּׁחֵ֥ת הָ⁠אָ֖רֶץ מִ⁠פְּנֵ֥י הֶ⁠עָרֹֽב׃","wa⁠yȧ֤ʻaş̂ yĕhwáh֙ ké̇֔n wa⁠yá̇bòʼ֙ ʻárò֣b ká̇bé֔d bé֥̇yţá⁠h parĕʻò֖h ẇ⁠bé֣yţ ʻàbádá֑y⁠w ẇ⁠bĕ⁠kál-ʼe֧reẕ miẕĕra֛yim ţi̇şá̇̌ẖé֥ţ há⁠ʼá֖reẕ mi⁠pĕ̇né֥y he⁠ʻáròֽb׃"],[8,25,"וַ⁠יִּקְרָ֣א פַרְעֹ֔ה אֶל־מֹשֶׁ֖ה וּֽ⁠לְ⁠אַהֲרֹ֑ן וַ⁠יֹּ֗אמֶר לְכ֛וּ זִבְח֥וּ לֵֽ⁠אלֹהֵי⁠כֶ֖ם בָּ⁠אָֽרֶץ׃","wa⁠yi̇qĕrá֣ʼ parĕʻò֔h ʼel-mòşě֖h ẇֽ⁠lĕ⁠ʼahàrò֑n wa⁠yò̇֗ʼmer lĕk֛ẇ zibĕẖ֥ẇ lֽé⁠ʼlòhéy⁠ke֖m bá̇⁠ʼáֽreẕ׃"],[8,26,"וַ⁠יֹּ֣אמֶר מֹשֶׁ֗ה לֹ֤א נָכוֹן֙ לַ⁠עֲשׂ֣וֹת כֵּ֔ן כִּ֚י תּוֹעֲבַ֣ת מִצְרַ֔יִם נִזְבַּ֖ח לַ⁠יהוָ֣ה אֱלֹהֵ֑י⁠נוּ הֵ֣ן נִזְבַּ֞ח אֶת־תּוֹעֲבַ֥ת מִצְרַ֛יִם לְ⁠עֵינֵי⁠הֶ֖ם וְ⁠לֹ֥א יִסְקְלֻֽ⁠נוּ׃","wa⁠yò֣̇ʼmer mòşě֗h lò֤ʼ nákwòn֙ la⁠ʻàş֣̂wòţ ké̇֔n ki֚̇y ţ̇wòʻàba֣ţ miẕĕra֔yim nizĕbȧ֖ẖ la⁠yhwá֣h ʼèlòhé֑y⁠nẇ hé֣n nizĕbȧ֞ẖ ʼeţ-ţ̇wòʻàba֥ţ miẕĕra֛yim lĕ⁠ʻéynéy⁠he֖m wĕ⁠lò֥ʼ yisĕqĕluֽ⁠nẇ׃"],[8,27,"דֶּ֚רֶךְ שְׁלֹ֣שֶׁת יָמִ֔ים נֵלֵ֖ךְ בַּ⁠מִּדְבָּ֑ר וְ⁠זָבַ֨חְנוּ֙ לַֽ⁠יהוָ֣ה אֱלֹהֵ֔י⁠נוּ כַּ⁠אֲשֶׁ֖ר יֹאמַ֥ר אֵלֵֽי⁠נוּ׃","dė֚rekĕ şĕ̌lò֣şěţ yámi֔ym nélé֖kĕ bȧ⁠mi̇dĕbá֑̇r wĕ⁠zába֨ẖĕnẇ֙ laֽ⁠yhwá֣h ʼèlòhé֔y⁠nẇ kȧ⁠ʼàşě֖r yòʼma֥r ʼéléֽy⁠nẇ׃"],[8,28,"וַ⁠יֹּ֣אמֶר פַּרְעֹ֗ה אָנֹכִ֞י אֲשַׁלַּ֤ח אֶתְ⁠כֶם֙ וּ⁠זְבַחְתֶּ֞ם לַ⁠יהוָ֤ה אֱלֹֽהֵי⁠כֶם֙ בַּ⁠מִּדְבָּ֔ר רַ֛ק הַרְחֵ֥ק לֹא־תַרְחִ֖יקוּ לָ⁠לֶ֑כֶת הַעְתִּ֖ירוּ בַּעֲדִֽ⁠י׃","wa⁠yò֣̇ʼmer pȧrĕʻò֗h ʼánòki֞y ʼàşǎlȧ֤ẖ ʼeţĕ⁠kem֙ ẇ⁠zĕbaẖĕţė֞m la⁠yhwá֤h ʼèlòֽhéy⁠kem֙ bȧ⁠mi̇dĕbá̇֔r ra֛q harĕẖé֥q lòʼ-ţarĕẖi֖yqẇ lá⁠le֑keţ haʻĕţi֖̇yrẇ bȧʻàdiֽ⁠y׃"],[8,29,"וַ⁠יֹּ֣אמֶר מֹשֶׁ֗ה הִנֵּ֨ה אָנֹכִ֜י יוֹצֵ֤א מֵֽ⁠עִמָּ⁠ךְ֙ וְ⁠הַעְתַּרְתִּ֣י אֶל־יְהוָ֔ה וְ⁠סָ֣ר הֶ⁠עָרֹ֗ב מִ⁠פַּרְעֹ֛ה מֵ⁠עֲבָדָ֥י⁠ו וּ⁠מֵ⁠עַמּ֖⁠וֹ מָחָ֑ר רַ֗ק אַל־יֹסֵ֤ף פַּרְעֹה֙ הָתֵ֔ל לְ⁠בִלְתִּי֙ שַׁלַּ֣ח אֶת־הָ⁠עָ֔ם לִ⁠זְבֹּ֖חַ לַֽ⁠יהוָֽה׃","wa⁠yò֣̇ʼmer mòşě֗h hiné̇֨h ʼánòki֜y ywòẕé֤ʼ méֽ⁠ʻimá̇⁠kĕ֙ wĕ⁠haʻĕţȧrĕţi֣̇y ʼel-yĕhwá֔h wĕ⁠sá֣r he⁠ʻárò֗b mi⁠pȧrĕʻò֛h mé⁠ʻàbádá֥y⁠w ẇ⁠mé⁠ʻaṁ֖⁠wò máẖá֑r ra֗q ʼal-yòsé֤p pȧrĕʻòh֙ háţé֔l lĕ⁠bilĕţi̇y֙ şǎlȧ֣ẖ ʼeţ-há⁠ʻá֔m li⁠zĕbò֖̇ẖa laֽ⁠yhwáֽh׃"],[8,30,"וַ⁠יֵּצֵ֥א מֹשֶׁ֖ה מֵ⁠עִ֣ם פַּרְעֹ֑ה וַ⁠יֶּעְתַּ֖ר אֶל־יְהוָֽה׃","wa⁠yé̇ẕé֥ʼ mòşě֖h mé⁠ʻi֣m pȧrĕʻò֑h wa⁠yėʻĕţȧ֖r ʼel-yĕhwáֽh׃"],[8,31,"וַ⁠יַּ֤עַשׂ יְהוָה֙ כִּ⁠דְבַ֣ר מֹשֶׁ֔ה וַ⁠יָּ֨סַר֙ הֶ⁠עָרֹ֔ב מִ⁠פַּרְעֹ֖ה מֵ⁠עֲבָדָ֣י⁠ו וּ⁠מֵ⁠עַמּ֑⁠וֹ לֹ֥א נִשְׁאַ֖ר אֶחָֽד׃","wa⁠yȧ֤ʻaş̂ yĕhwáh֙ ki̇⁠dĕba֣r mòşě֔h wa⁠yá̇֨sar֙ he⁠ʻárò֔b mi⁠pȧrĕʻò֖h mé⁠ʻàbádá֣y⁠w ẇ⁠mé⁠ʻaṁ֑⁠wò lò֥ʼ nişĕ̌ʼa֖r ʼeẖáֽd׃"],[8,32,"וַ⁠יַּכְבֵּ֤ד פַּרְעֹה֙ אֶת־לִבּ֔⁠וֹ גַּ֖ם בַּ⁠פַּ֣עַם הַ⁠זֹּ֑את וְ⁠לֹ֥א שִׁלַּ֖ח אֶת־הָ⁠עָֽם׃פ","wa⁠yȧkĕbé֤̇d pȧrĕʻòh֙ ʼeţ-liḃ֔⁠wò gȧ֖m bȧ⁠pȧ֣ʻam ha⁠zò֑̇ʼţ wĕ⁠lò֥ʼ şǐlȧ֖ẖ ʼeţ-há⁠ʻáֽm׃p"],[9,1,"וַ⁠יֹּ֤אמֶר יְהוָה֙ אֶל־מֹשֶׁ֔ה בֹּ֖א אֶל־פַּרְעֹ֑ה וְ⁠דִבַּרְתָּ֣ אֵלָ֗י⁠ו כֹּֽה־אָמַ֤ר יְהוָה֙ אֱלֹהֵ֣י הָֽ⁠עִבְרִ֔ים שַׁלַּ֥ח אֶת־עַמִּ֖⁠י וְ⁠יַֽעַבְדֻֽ⁠נִי׃","wa⁠yò֤̇ʼmer yĕhwáh֙ ʼel-mòşě֔h bò֖̇ʼ ʼel-pȧrĕʻò֑h wĕ⁠dibȧrĕţá֣̇ ʼélá֗y⁠w kòֽ̇h-ʼáma֤r yĕhwáh֙ ʼèlòhé֣y háֽ⁠ʻibĕri֔ym şǎlȧ֥ẖ ʼeţ-ʻami֖̇⁠y wĕ⁠yaֽʻabĕduֽ⁠niy׃"],[9,2,"כִּ֛י אִם־מָאֵ֥ן אַתָּ֖ה לְ⁠שַׁלֵּ֑חַ וְ⁠עוֹדְ⁠ךָ֖ מַחֲזִ֥יק בָּֽ⁠ם׃","ki֛̇y ʼim-máʼé֥n ʼaţá֖̇h lĕ⁠şǎlé֑̇ẖa wĕ⁠ʻwòdĕ⁠ká֖ maẖàzi֥yq báֽ̇⁠m׃"],[9,3,"הִנֵּ֨ה יַד־יְהוָ֜ה הוֹיָ֗ה בְּ⁠מִקְנְ⁠ךָ֙ אֲשֶׁ֣ר בַּ⁠שָּׂדֶ֔ה בַּ⁠סּוּסִ֤ים בַּֽ⁠חֲמֹרִים֙ בַּ⁠גְּמַלִּ֔ים בַּ⁠בָּקָ֖ר וּ⁠בַ⁠צֹּ֑אן דֶּ֖בֶר כָּבֵ֥ד מְאֹֽד׃","hiné̇֨h yad-yĕhwá֜h hwòyá֗h bĕ̇⁠miqĕnĕ⁠ká֙ ʼàşě֣r bȧ⁠şá̇̂de֔h bȧ⁠ṡẇsi֤ym bȧֽ⁠ẖàmòriym֙ bȧ⁠gĕ̇mali̇֔ym bȧ⁠bá̇qá֖r ẇ⁠ba⁠ẕò֑̇ʼn dė֖ber ká̇bé֥d mĕʼòֽd׃"],[9,4,"וְ⁠הִפְלָ֣ה יְהוָ֔ה בֵּ֚ין מִקְנֵ֣ה יִשְׂרָאֵ֔ל וּ⁠בֵ֖ין מִקְנֵ֣ה מִצְרָ֑יִם וְ⁠לֹ֥א יָמ֛וּת מִ⁠כָּל־לִ⁠בְנֵ֥י יִשְׂרָאֵ֖ל דָּבָֽר׃","wĕ⁠hipĕlá֣h yĕhwá֔h bé֚̇yn miqĕné֣h yişĕ̂ráʼé֔l ẇ⁠bé֖yn miqĕné֣h miẕĕrá֑yim wĕ⁠lò֥ʼ yám֛ẇţ mi⁠ká̇l-li⁠bĕné֥y yişĕ̂ráʼé֖l dá̇báֽr׃"],[9,5,"וַ⁠יָּ֥שֶׂם יְהוָ֖ה מוֹעֵ֣ד לֵ⁠אמֹ֑ר מָחָ֗ר יַעֲשֶׂ֧ה יְהוָ֛ה הַ⁠דָּבָ֥ר הַ⁠זֶּ֖ה בָּ⁠אָֽרֶץ׃","wa⁠yá֥̇şêm yĕhwá֖h mwòʻé֣d lé⁠ʼmò֑r máẖá֗r yaʻàşê֧h yĕhwá֛h ha⁠dá̇bá֥r ha⁠zė֖h bá̇⁠ʼáֽreẕ׃"],[9,6,"וַ⁠יַּ֨עַשׂ יְהוָ֜ה אֶת־הַ⁠דָּבָ֤ר הַ⁠זֶּה֙ מִֽ⁠מָּחֳרָ֔ת וַ⁠יָּ֕מָת כֹּ֖ל מִקְנֵ֣ה מִצְרָ֑יִם וּ⁠מִ⁠מִּקְנֵ֥ה בְנֵֽי־יִשְׂרָאֵ֖ל לֹא־מֵ֥ת אֶחָֽד׃","wa⁠yȧ֨ʻaş̂ yĕhwá֜h ʼeţ-ha⁠dá̇bá֤r ha⁠zėh֙ miֽ⁠má̇ẖorá֔ţ wa⁠yá̇֕máţ kò֖̇l miqĕné֣h miẕĕrá֑yim ẇ⁠mi⁠mi̇qĕné֥h bĕnéֽy-yişĕ̂ráʼé֖l lòʼ-mé֥ţ ʼeẖáֽd׃"],[9,7,"וַ⁠יִּשְׁלַ֣ח פַּרְעֹ֔ה וְ⁠הִנֵּ֗ה לֹא־מֵ֛ת מִ⁠מִּקְנֵ֥ה יִשְׂרָאֵ֖ל עַד־אֶחָ֑ד וַ⁠יִּכְבַּד֙ לֵ֣ב פַּרְעֹ֔ה וְ⁠לֹ֥א שִׁלַּ֖ח אֶת־הָ⁠עָֽם׃פ","wa⁠yi̇şĕ̌la֣ẖ pȧrĕʻò֔h wĕ⁠hiné̇֗h lòʼ-mé֛ţ mi⁠mi̇qĕné֥h yişĕ̂ráʼé֖l ʻad-ʼeẖá֑d wa⁠yi̇kĕbȧd֙ lé֣b pȧrĕʻò֔h wĕ⁠lò֥ʼ şǐlȧ֖ẖ ʼeţ-há⁠ʻáֽm׃p"],[9,8,"וַ⁠יֹּ֣אמֶר יְהוָה֮ אֶל־מֹשֶׁ֣ה וְ⁠אֶֽל־אַהֲרֹן֒ קְח֤וּ לָ⁠כֶם֙ מְלֹ֣א חָפְנֵי⁠כֶ֔ם פִּ֖יחַ כִּבְשָׁ֑ן וּ⁠זְרָק֥⁠וֹ מֹשֶׁ֛ה הַ⁠שָּׁמַ֖יְמָ⁠ה לְ⁠עֵינֵ֥י פַרְעֹֽה׃","wa⁠yò֣̇ʼmer yĕhwáh֮ ʼel-mòşě֣h wĕ⁠ʼeֽl-ʼahàròn֒ qĕẖ֤ẇ lá⁠kem֙ mĕlò֣ʼ ẖápĕnéy⁠ke֔m pi֖̇yẖa ki̇bĕşá֑̌n ẇ⁠zĕráq֥⁠wò mòşě֛h ha⁠şá̇̌ma֖yĕmá⁠h lĕ⁠ʻéyné֥y parĕʻòֽh׃"],[9,9,"וְ⁠הָיָ֣ה לְ⁠אָבָ֔ק עַ֖ל כָּל־אֶ֣רֶץ מִצְרָ֑יִם וְ⁠הָיָ֨ה עַל־הָ⁠אָדָ֜ם וְ⁠עַל־הַ⁠בְּהֵמָ֗ה לִ⁠שְׁחִ֥ין פֹּרֵ֛חַ אֲבַעְבֻּעֹ֖ת בְּ⁠כָל־אֶ֥רֶץ מִצְרָֽיִם׃","wĕ⁠háyá֣h lĕ⁠ʼábá֔q ʻa֖l ká̇l-ʼe֣reẕ miẕĕrá֑yim wĕ⁠háyá֨h ʻal-há⁠ʼádá֜m wĕ⁠ʻal-ha⁠bĕ̇hémá֗h li⁠şĕ̌ẖi֥yn pò̇ré֛ẖa ʼàbaʻĕbu̇ʻò֖ţ bĕ̇⁠kál-ʼe֥reẕ miẕĕráֽyim׃"],[9,10,"וַ⁠יִּקְח֞וּ אֶת־פִּ֣יחַ הַ⁠כִּבְשָׁ֗ן וַ⁠יַּֽעַמְדוּ֙ לִ⁠פְנֵ֣י פַרְעֹ֔ה וַ⁠יִּזְרֹ֥ק אֹת֛⁠וֹ מֹשֶׁ֖ה הַ⁠שָּׁמָ֑יְמָ⁠ה וַ⁠יְהִ֗י שְׁחִין֙ אֲבַעְבֻּעֹ֔ת פֹּרֵ֕חַ בָּ⁠אָדָ֖ם וּ⁠בַ⁠בְּהֵמָֽה׃","wa⁠yi̇qĕẖ֞ẇ ʼeţ-pi֣̇yẖa ha⁠ki̇bĕşá̌֗n wa⁠yȧֽʻamĕdẇ֙ li⁠pĕné֣y parĕʻò֔h wa⁠yi̇zĕrò֥q ʼòţ֛⁠wò mòşě֖h ha⁠şá̇̌má֑yĕmá⁠h wa⁠yĕhi֗y şĕ̌ẖiyn֙ ʼàbaʻĕbu̇ʻò֔ţ pò̇ré֕ẖa bá̇⁠ʼádá֖m ẇ⁠ba⁠bĕ̇hémáֽh׃"],[9,11,"וְ⁠לֹֽא־יָכְל֣וּ הַֽ⁠חַרְטֻמִּ֗ים לַ⁠עֲמֹ֛ד לִ⁠פְנֵ֥י מֹשֶׁ֖ה מִ⁠פְּנֵ֣י הַ⁠שְּׁחִ֑ין כִּֽי־הָיָ֣ה הַ⁠שְּׁחִ֔ין בַּֽ⁠חֲרְטֻמִּ֖ם וּ⁠בְ⁠כָל־מִצְרָֽיִם׃","wĕ⁠lòֽʼ-yákĕl֣ẇ hֽa⁠ẖarĕtumi̇֗ym la⁠ʻàmò֛d li⁠pĕné֥y mòşě֖h mi⁠pĕ̇né֣y ha⁠şĕ̇̌ẖi֑yn kiֽ̇y-háyá֣h ha⁠şĕ̇̌ẖi֔yn ḃֽa⁠ẖàrĕtumi֖̇m ẇ⁠bĕ⁠kál-miẕĕráֽyim׃"],[9,12,"וַ⁠יְחַזֵּ֤ק יְהוָה֙ אֶת־לֵ֣ב פַּרְעֹ֔ה וְ⁠לֹ֥א שָׁמַ֖ע אֲלֵ⁠הֶ֑ם כַּ⁠אֲשֶׁ֛ר דִּבֶּ֥ר יְהוָ֖ה אֶל־מֹשֶֽׁה׃ס","wa⁠yĕẖazé֤̇q yĕhwáh֙ ʼeţ-lé֣b pȧrĕʻò֔h wĕ⁠lò֥ʼ şá̌ma֖ʻ ʼàlé⁠he֑m kȧ⁠ʼàşě֛r di̇bė֥r yĕhwá֖h ʼel-mòşěֽh׃s"],[9,13,"וַ⁠יֹּ֤אמֶר יְהוָה֙ אֶל־מֹשֶׁ֔ה הַשְׁכֵּ֣ם בַּ⁠בֹּ֔קֶר וְ⁠הִתְיַצֵּ֖ב לִ⁠פְנֵ֣י פַרְעֹ֑ה וְ⁠אָמַרְתָּ֣ אֵלָ֗י⁠ו כֹּֽה־אָמַ֤ר יְהוָה֙ אֱלֹהֵ֣י הָֽ⁠עִבְרִ֔ים שַׁלַּ֥ח אֶת־עַמִּ֖⁠י וְ⁠יַֽעַבְדֻֽ⁠נִי׃","wa⁠yò֤̇ʼmer yĕhwáh֙ ʼel-mòşě֔h haşĕ̌ké֣̇m bȧ⁠bò̇֔qer wĕ⁠hiţĕyaẕé֖̇b li⁠pĕné֣y parĕʻò֑h wĕ⁠ʼámarĕţá֣̇ ʼélá֗y⁠w kòֽ̇h-ʼáma֤r yĕhwáh֙ ʼèlòhé֣y háֽ⁠ʻibĕri֔ym şǎlȧ֥ẖ ʼeţ-ʻami֖̇⁠y wĕ⁠yaֽʻabĕduֽ⁠niy׃"],[9,14,"כִּ֣י ׀ בַּ⁠פַּ֣עַם הַ⁠זֹּ֗את אֲנִ֨י שֹׁלֵ֜חַ אֶת־כָּל־מַגֵּפֹתַ⁠י֙ אֶֽל־לִבְּ⁠ךָ֔ וּ⁠בַ⁠עֲבָדֶ֖י⁠ךָ וּ⁠בְ⁠עַמֶּ֑⁠ךָ בַּ⁠עֲב֣וּר תֵּדַ֔ע כִּ֛י אֵ֥ין כָּמֹ֖⁠נִי בְּ⁠כָל־הָ⁠אָֽרֶץ׃","ki֣̇y ׀ bȧ⁠pȧ֣ʻam ha⁠zò̇֗ʼţ ʼàni֨y şò̌lé֜ẖa ʼeţ-ká̇l-magé̇pòţa⁠y֙ ʼeֽl-libĕ̇⁠ká֔ ẇ⁠ba⁠ʻàbáde֖y⁠ká ẇ⁠bĕ⁠ʻamė֑⁠ká bȧ⁠ʻàb֣ẇr ţé̇da֔ʻ ki֛̇y ʼé֥yn ká̇mò֖⁠niy bĕ̇⁠kál-há⁠ʼáֽreẕ׃"],[9,15,"כִּ֤י עַתָּה֙ שָׁלַ֣חְתִּי אֶת־יָדִ֔⁠י וָ⁠אַ֥ךְ אוֹתְ⁠ךָ֛ וְ⁠אֶֽת־עַמְּ⁠ךָ֖ בַּ⁠דָּ֑בֶר וַ⁠תִּכָּחֵ֖ד מִן־הָ⁠אָֽרֶץ׃","ki֤̇y ʻaţá̇h֙ şá̌la֣ẖĕţi̇y ʼeţ-yádi֔⁠y wá⁠ʼa֥kĕ ʼwòţĕ⁠ká֛ wĕ⁠ʼeֽţ-ʻamĕ̇⁠ká֖ bȧ⁠dá֑̇ber wa⁠ţi̇ká̇ẖé֖d min-há⁠ʼáֽreẕ׃"],[9,16,"וְ⁠אוּלָ֗ם בַּ⁠עֲב֥וּר זֹאת֙ הֶעֱמַדְתִּ֔י⁠ךָ בַּ⁠עֲב֖וּר הַרְאֹתְ⁠ךָ֣ אֶת־כֹּחִ֑⁠י וּ⁠לְמַ֛עַן סַפֵּ֥ר שְׁמִ֖⁠י בְּ⁠כָל־הָ⁠אָֽרֶץ׃","wĕ⁠ʼẇlá֗m bȧ⁠ʻàb֥ẇr zòʼţ֙ heʻèmadĕţi̇֔y⁠ká bȧ⁠ʻàb֖ẇr harĕʼòţĕ⁠ká֣ ʼeţ-kò̇ẖi֑⁠y ẇ⁠lĕma֛ʻan sapé֥̇r şĕ̌mi֖⁠y bĕ̇⁠kál-há⁠ʼáֽreẕ׃"],[9,17,"עוֹדְ⁠ךָ֖ מִסְתּוֹלֵ֣ל בְּ⁠עַמִּ֑⁠י לְ⁠בִלְתִּ֖י שַׁלְּחָֽ⁠ם׃","ʻwòdĕ⁠ká֖ misĕţ̇wòlé֣l bĕ̇⁠ʻami֑̇⁠y lĕ⁠bilĕţi֖̇y şǎlĕ̇ẖáֽ⁠m׃"],[9,18,"הִנְ⁠נִ֤י מַמְטִיר֙ כָּ⁠עֵ֣ת מָחָ֔ר בָּרָ֖ד כָּבֵ֣ד מְאֹ֑ד אֲשֶׁ֨ר לֹא־הָיָ֤ה כָמֹ֨⁠הוּ֙ בְּ⁠מִצְרַ֔יִם לְ⁠מִן־הַ⁠יּ֥וֹם הִוָּסְדָ֖⁠ה וְ⁠עַד־עָֽתָּה׃","hinĕ⁠ni֤y mamĕtiyr֙ ká̇⁠ʻé֣ţ máẖá֔r bá̇rá֖d ká̇bé֣d mĕʼò֑d ʼàşě֨r lòʼ-háyá֤h kámò֨⁠hẇ֙ bĕ̇⁠miẕĕra֔yim lĕ⁠min-ha⁠ẏ֥wòm hiwá̇sĕdá֖⁠h wĕ⁠ʻad-ʻáֽţá̇h׃"],[9,19,"וְ⁠עַתָּ֗ה שְׁלַ֤ח הָעֵז֙ אֶֽת־מִקְנְ⁠ךָ֔ וְ⁠אֵ֛ת כָּל־אֲשֶׁ֥ר לְ⁠ךָ֖ בַּ⁠שָּׂדֶ֑ה כָּל־הָ⁠אָדָ֨ם וְ⁠הַ⁠בְּהֵמָ֜ה אֲשֶֽׁר־יִמָּצֵ֣א בַ⁠שָּׂדֶ֗ה וְ⁠לֹ֤א יֵֽאָסֵף֙ הַ⁠בַּ֔יְתָ⁠ה וְ⁠יָרַ֧ד עֲלֵ⁠הֶ֛ם הַ⁠בָּרָ֖ד וָ⁠מֵֽתוּ׃","wĕ⁠ʻaţá̇֗h şĕ̌la֤ẖ háʻéz֙ ʼeֽţ-miqĕnĕ⁠ká֔ wĕ⁠ʼé֛ţ ká̇l-ʼàşě֥r lĕ⁠ká֖ bȧ⁠şá̇̂de֑h ká̇l-há⁠ʼádá֨m wĕ⁠ha⁠bĕ̇hémá֜h ʼàşěֽr-yimá̇ẕé֣ʼ ba⁠şá̇̂de֗h wĕ⁠lò֤ʼ yéֽʼásép֙ ha⁠bȧ֔yĕţá⁠h wĕ⁠yára֧d ʻàlé⁠he֛m ha⁠bá̇rá֖d wá⁠méֽţẇ׃"],[9,20,"הַ⁠יָּרֵא֙ אֶת־דְּבַ֣ר יְהוָ֔ה מֵֽ⁠עַבְדֵ֖י פַּרְעֹ֑ה הֵנִ֛יס אֶת־עֲבָדָ֥י⁠ו וְ⁠אֶת־מִקְנֵ֖⁠הוּ אֶל־הַ⁠בָּתִּֽים׃","ha⁠yá̇réʼ֙ ʼeţ-dĕ̇ba֣r yĕhwá֔h méֽ⁠ʻabĕdé֖y pȧrĕʻò֑h héni֛ys ʼeţ-ʻàbádá֥y⁠w wĕ⁠ʼeţ-miqĕné֖⁠hẇ ʼel-ha⁠bá̇ţiֽ̇ym׃"],[9,21,"וַ⁠אֲשֶׁ֥ר לֹא־שָׂ֛ם לִבּ֖⁠וֹ אֶל־דְּבַ֣ר יְהוָ֑ה וַֽ⁠יַּעֲזֹ֛ב אֶת־עֲבָדָ֥י⁠ו וְ⁠אֶת־מִקְנֵ֖⁠הוּ בַּ⁠שָּׂדֶֽה׃פ","wa⁠ʼàşě֥r lòʼ-şá֛̂m liḃ֖⁠wò ʼel-dĕ̇ba֣r yĕhwá֑h waֽ⁠yȧʻàzò֛b ʼeţ-ʻàbádá֥y⁠w wĕ⁠ʼeţ-miqĕné֖⁠hẇ bȧ⁠şá̇̂deֽh׃p"],[9,22,"וַ⁠יֹּ֨אמֶר יְהוָ֜ה אֶל־מֹשֶׁה נְטֵ֤ה אֶת־יָֽדְ⁠ךָ֙ עַל־הַ⁠שָּׁמַ֔יִם וִ⁠יהִ֥י בָרָ֖ד בְּ⁠כָל־אֶ֣רֶץ מִצְרָ֑יִם עַל־הָ⁠אָדָ֣ם וְ⁠עַל־הַ⁠בְּהֵמָ֗ה וְ⁠עַ֛ל כָּל־עֵ֥שֶׂב הַ⁠שָּׂדֶ֖ה בְּ⁠אֶ֥רֶץ מִצְרָֽיִם׃","wa⁠yò̇֨ʼmer yĕhwá֜h ʼel-mòşěh nĕté֤h ʼeţ-yáֽdĕ⁠ká֙ ʻal-ha⁠şá̇̌ma֔yim wi⁠yhi֥y bárá֖d bĕ̇⁠kál-ʼe֣reẕ miẕĕrá֑yim ʻal-há⁠ʼádá֣m wĕ⁠ʻal-ha⁠bĕ̇hémá֗h wĕ⁠ʻa֛l ká̇l-ʻé֥şêb ha⁠şá̇̂de֖h bĕ̇⁠ʼe֥reẕ miẕĕráֽyim׃"],[9,23,"וַ⁠יֵּ֨ט מֹשֶׁ֣ה אֶת־מַטֵּ⁠הוּ֮ עַל־הַ⁠שָּׁמַיִם֒ וַֽ⁠יהוָ֗ה נָתַ֤ן קֹלֹת֙ וּ⁠בָרָ֔ד וַ⁠תִּ֥הֲלַךְ אֵ֖שׁ אָ֑רְצָ⁠ה וַ⁠יַּמְטֵ֧ר יְהוָ֛ה בָּרָ֖ד עַל־אֶ֥רֶץ מִצְרָֽיִם׃","wa⁠yé̇֨t mòşě֣h ʼeţ-maté̇⁠hẇ֮ ʻal-ha⁠şá̇̌mayim֒ waֽ⁠yhwá֗h náţa֤n qòlòţ֙ ẇ⁠bárá֔d wa⁠ţi֥̇hàlakĕ ʼé֖ş̌ ʼá֑rĕẕá⁠h wa⁠yȧmĕté֧r yĕhwá֛h bá̇rá֖d ʻal-ʼe֥reẕ miẕĕráֽyim׃"],[9,24,"וַ⁠יְהִ֣י בָרָ֔ד וְ⁠אֵ֕שׁ מִתְלַקַּ֖חַת בְּ⁠ת֣וֹךְ הַ⁠בָּרָ֑ד כָּבֵ֣ד מְאֹ֔ד אֲ֠שֶׁר לֹֽא־הָיָ֤ה כָמֹ֨⁠הוּ֙ בְּ⁠כָל־אֶ֣רֶץ מִצְרַ֔יִם מֵ⁠אָ֖ז הָיְתָ֥ה לְ⁠גֽוֹי׃","wa⁠yĕhi֣y bárá֔d wĕ⁠ʼé֕ş̌ miţĕlaqȧ֖ẖaţ bĕ̇⁠ţ֣wòkĕ ha⁠bá̇rá֑d ká̇bé֣d mĕʼò֔d ʼà֠şěr lòֽʼ-háyá֤h kámò֨⁠hẇ֙ bĕ̇⁠kál-ʼe֣reẕ miẕĕra֔yim mé⁠ʼá֖z háyĕţá֥h lĕ⁠gֽwòy׃"],[9,25,"וַ⁠יַּ֨ךְ הַ⁠בָּרָ֜ד בְּ⁠כָל־אֶ֣רֶץ מִצְרַ֗יִם אֵ֚ת כָּל־אֲשֶׁ֣ר בַּ⁠שָּׂדֶ֔ה מֵ⁠אָדָ֖ם וְ⁠עַד־בְּהֵמָ֑ה וְ⁠אֵ֨ת כָּל־עֵ֤שֶׂב הַ⁠שָּׂדֶה֙ הִכָּ֣ה הַ⁠בָּרָ֔ד וְ⁠אֶת־כָּל־עֵ֥ץ הַ⁠שָּׂדֶ֖ה שִׁבֵּֽר׃","wa⁠yȧ֨kĕ ha⁠bá̇rá֜d bĕ̇⁠kál-ʼe֣reẕ miẕĕra֗yim ʼé֚ţ ká̇l-ʼàşě֣r bȧ⁠şá̇̂de֔h mé⁠ʼádá֖m wĕ⁠ʻad-bĕ̇hémá֑h wĕ⁠ʼé֨ţ ká̇l-ʻé֤şêb ha⁠şá̇̂deh֙ hiká֣̇h ha⁠bá̇rá֔d wĕ⁠ʼeţ-ká̇l-ʻé֥ẕ ha⁠şá̇̂de֖h şǐbéֽ̇r׃"],[9,26,"רַ֚ק בְּ⁠אֶ֣רֶץ גֹּ֔שֶׁן אֲשֶׁר־שָׁ֖ם בְּנֵ֣י יִשְׂרָאֵ֑ל לֹ֥א הָיָ֖ה בָּרָֽד׃","ra֚q bĕ̇⁠ʼe֣reẕ gò̇֔şěn ʼàşěr-şá֖̌m bĕ̇né֣y yişĕ̂ráʼé֑l lò֥ʼ háyá֖h bá̇ráֽd׃"],[9,27,"וַ⁠יִּשְׁלַ֣ח פַּרְעֹ֗ה וַ⁠יִּקְרָא֙ לְ⁠מֹשֶׁ֣ה וּֽ⁠לְ⁠אַהֲרֹ֔ן וַ⁠יֹּ֥אמֶר אֲלֵ⁠הֶ֖ם חָטָ֣אתִי הַ⁠פָּ֑עַם יְהוָה֙ הַ⁠צַּדִּ֔יק וַ⁠אֲנִ֥י וְ⁠עַמִּ֖⁠י הָ⁠רְשָׁעִֽים׃","wa⁠yi̇şĕ̌la֣ẖ pȧrĕʻò֗h wa⁠yi̇qĕráʼ֙ lĕ⁠mòşě֣h ẇֽ⁠lĕ⁠ʼahàrò֔n wa⁠yò֥̇ʼmer ʼàlé⁠he֖m ẖátá֣ʼţiy ha⁠pá֑̇ʻam yĕhwáh֙ ha⁠ẕȧdi̇֔yq wa⁠ʼàni֥y wĕ⁠ʻami֖̇⁠y há⁠rĕşá̌ʻiֽym׃"],[9,28,"הַעְתִּ֨ירוּ֙ אֶל־יְהוָ֔ה וְ⁠רַ֕ב מִֽ⁠הְיֹ֛ת קֹלֹ֥ת אֱלֹהִ֖ים וּ⁠בָרָ֑ד וַ⁠אֲשַׁלְּחָ֣ה אֶתְ⁠כֶ֔ם וְ⁠לֹ֥א תֹסִפ֖וּ⁠ן לַ⁠עֲמֹֽד׃","haʻĕţi̇֨yrẇ֙ ʼel-yĕhwá֔h wĕ⁠ra֕b miֽ⁠hĕyò֛ţ qòlò֥ţ ʼèlòhi֖ym ẇ⁠bárá֑d wa⁠ʼàşǎlĕ̇ẖá֣h ʼeţĕ⁠ke֔m wĕ⁠lò֥ʼ ţòsip֖ẇ⁠n la⁠ʻàmòֽd׃"],[9,29,"וַ⁠יֹּ֤אמֶר אֵלָי⁠ו֙ מֹשֶׁ֔ה כְּ⁠צֵאתִ⁠י֙ אֶת־הָ⁠עִ֔יר אֶפְרֹ֥שׂ אֶת־כַּפַּ֖⁠י אֶל־יְהוָ֑ה הַ⁠קֹּל֣וֹת יֶחְדָּל֗וּ⁠ן וְ⁠הַ⁠בָּרָד֙ לֹ֣א יִֽהְיֶה־ע֔וֹד לְמַ֣עַן תֵּדַ֔ע כִּ֥י לַ⁠יהוָ֖ה הָ⁠אָֽרֶץ׃","wa⁠yò֤̇ʼmer ʼéláy⁠w֙ mòşě֔h kĕ̇⁠ẕéʼţi⁠y֙ ʼeţ-há⁠ʻi֔yr ʼepĕrò֥ş̂ ʼeţ-kȧpȧ֖⁠y ʼel-yĕhwá֑h ha⁠qò̇l֣wòţ yeẖĕdá̇l֗ẇ⁠n wĕ⁠ha⁠bá̇rád֙ lò֣ʼ yiֽhĕyeh-ʻ֔wòd lĕma֣ʻan ţé̇da֔ʻ ki֥̇y la⁠yhwá֖h há⁠ʼáֽreẕ׃"],[9,30,"וְ⁠אַתָּ֖ה וַ⁠עֲבָדֶ֑י⁠ךָ יָדַ֕עְתִּי כִּ֚י טֶ֣רֶם תִּֽירְא֔וּ⁠ן מִ⁠פְּנֵ֖י יְהוָ֥ה אֱלֹהִֽים׃","wĕ⁠ʼaţá֖̇h wa⁠ʻàbáde֑y⁠ká yáda֕ʻĕţi̇y ki֚̇y te֣rem ţiֽ̇yrĕʼ֔ẇ⁠n mi⁠pĕ̇né֖y yĕhwá֥h ʼèlòhiֽym׃"],[9,31,"וְ⁠הַ⁠פִּשְׁתָּ֥ה וְ⁠הַ⁠שְּׂעֹרָ֖ה נֻכָּ֑תָה כִּ֤י הַ⁠שְּׂעֹרָה֙ אָבִ֔יב וְ⁠הַ⁠פִּשְׁתָּ֖ה גִּבְעֹֽל׃","wĕ⁠ha⁠pi̇şĕ̌ţá֥̇h wĕ⁠ha⁠şĕ̇̂ʻòrá֖h nuká֑̇ţáh ki֤̇y ha⁠şĕ̇̂ʻòráh֙ ʼábi֔yb wĕ⁠ha⁠pi̇şĕ̌ţá֖̇h gi̇bĕʻòֽl׃"],[9,32,"וְ⁠הַ⁠חִטָּ֥ה וְ⁠הַ⁠כֻּסֶּ֖מֶת לֹ֣א נֻכּ֑וּ כִּ֥י אֲפִילֹ֖ת הֵֽנָּה׃","wĕ⁠ha⁠ẖitá֥̇h wĕ⁠ha⁠ku̇sė֖meţ lò֣ʼ nuk֑̇ẇ ki֥̇y ʼàpiylò֖ţ héֽná̇h׃"],[9,33,"וַ⁠יֵּצֵ֨א מֹשֶׁ֜ה מֵ⁠עִ֤ם פַּרְעֹה֙ אֶת־הָ⁠עִ֔יר וַ⁠יִּפְרֹ֥שׂ כַּפָּ֖י⁠ו אֶל־יְהוָ֑ה וַֽ⁠יַּחְדְּל֤וּ הַ⁠קֹּלוֹת֙ וְ⁠הַ⁠בָּרָ֔ד וּ⁠מָטָ֖ר לֹא־נִתַּ֥ךְ אָֽרְצָ⁠ה׃","wa⁠yé̇ẕé֨ʼ mòşě֜h mé⁠ʻi֤m pȧrĕʻòh֙ ʼeţ-há⁠ʻi֔yr wa⁠yi̇pĕrò֥ş̂ kȧpá֖̇y⁠w ʼel-yĕhwá֑h waֽ⁠yȧẖĕdĕ̇l֤ẇ ha⁠qò̇lwòţ֙ wĕ⁠ha⁠bá̇rá֔d ẇ⁠mátá֖r lòʼ-niţȧ֥kĕ ʼáֽrĕẕá⁠h׃"],[9,34,"וַ⁠יַּ֣רְא פַּרְעֹ֗ה כִּֽי־חָדַ֨ל הַ⁠מָּטָ֧ר וְ⁠הַ⁠בָּרָ֛ד וְ⁠הַ⁠קֹּלֹ֖ת וַ⁠יֹּ֣סֶף לַ⁠חֲטֹ֑א וַ⁠יַּכְבֵּ֥ד לִבּ֖⁠וֹ ה֥וּא וַ⁠עֲבָדָֽי⁠ו׃","wa⁠yȧ֣rĕʼ pȧrĕʻò֗h kiֽ̇y-ẖáda֨l ha⁠má̇tá֧r wĕ⁠ha⁠bá̇rá֛d wĕ⁠ha⁠qò̇lò֖ţ wa⁠yò֣̇sep la⁠ẖàtò֑ʼ wa⁠yȧkĕbé֥̇d liḃ֖⁠wò h֥ẇʼ wa⁠ʻàbádáֽy⁠w׃"],[9,35,"וַֽ⁠יֶּחֱזַק֙ לֵ֣ב פַּרְעֹ֔ה וְ⁠לֹ֥א שִׁלַּ֖ח אֶת־בְּנֵ֣י יִשְׂרָאֵ֑ל כַּ⁠אֲשֶׁ֛ר דִּבֶּ֥ר יְהוָ֖ה בְּ⁠יַד־מֹשֶֽׁה׃פ","waֽ⁠yėẖèzaq֙ lé֣b pȧrĕʻò֔h wĕ⁠lò֥ʼ şǐlȧ֖ẖ ʼeţ-bĕ̇né֣y yişĕ̂ráʼé֑l kȧ⁠ʼàşě֛r di̇bė֥r yĕhwá֖h bĕ̇⁠yad-mòşěֽh׃p"],[10,1,"וַ⁠יֹּ֤אמֶר יְהוָה֙ אֶל־מֹשֶׁ֔ה בֹּ֖א אֶל־פַּרְעֹ֑ה כִּֽי־אֲנִ֞י הִכְבַּ֤דְתִּי אֶת־לִבּ⁠וֹ֙ וְ⁠אֶת־לֵ֣ב עֲבָדָ֔י⁠ו לְמַ֗עַן שִׁתִ֛⁠י אֹתֹתַ֥⁠י אֵ֖לֶּה בְּ⁠קִרְבּֽ⁠וֹ׃","wa⁠yò֤̇ʼmer yĕhwáh֙ ʼel-mòşě֔h bò֖̇ʼ ʼel-pȧrĕʻò֑h kiֽ̇y-ʼàni֞y hikĕbȧ֤dĕţi̇y ʼeţ-liḃ⁠wò֙ wĕ⁠ʼeţ-lé֣b ʻàbádá֔y⁠w lĕma֗ʻan şǐţi֛⁠y ʼòţòţa֥⁠y ʼé֖lėh bĕ̇⁠qirĕḃֽ⁠wò׃"],[10,2,"וּ⁠לְמַ֡עַן תְּסַפֵּר֩ בְּ⁠אָזְנֵ֨י בִנְ⁠ךָ֜ וּ⁠בֶן־בִּנְ⁠ךָ֗ אֵ֣ת אֲשֶׁ֤ר הִתְעַלַּ֨לְתִּי֙ בְּ⁠מִצְרַ֔יִם וְ⁠אֶת־אֹתֹתַ֖⁠י אֲשֶׁר־שַׂ֣מְתִּי בָ֑⁠ם וִֽ⁠ידַעְתֶּ֖ם כִּי־אֲנִ֥י יְהוָֽה׃","ẇ⁠lĕma֡ʻan ţĕ̇sapé̇r֩ bĕ̇⁠ʼázĕné֨y binĕ⁠ká֜ ẇ⁠ben-bi̇nĕ⁠ká֗ ʼé֣ţ ʼàşě֤r hiţĕʻalȧ֨lĕţi̇y֙ bĕ̇⁠miẕĕra֔yim wĕ⁠ʼeţ-ʼòţòţa֖⁠y ʼàşěr-şâ֣mĕţi̇y bá֑⁠m wiֽ⁠ydaʻĕţė֖m ki̇y-ʼàni֥y yĕhwáֽh׃"],[10,3,"וַ⁠יָּבֹ֨א מֹשֶׁ֣ה וְ⁠אַהֲרֹן֮ אֶל־פַּרְעֹה֒ וַ⁠יֹּאמְר֣וּ אֵלָ֗י⁠ו כֹּֽה־אָמַ֤ר יְהוָה֙ אֱלֹהֵ֣י הָֽ⁠עִבְרִ֔ים עַד־מָתַ֣י מֵאַ֔נְתָּ לֵ⁠עָנֹ֖ת מִ⁠פָּנָ֑⁠י שַׁלַּ֥ח עַמִּ֖⁠י וְ⁠יַֽעַבְדֻֽ⁠נִי׃","wa⁠yá̇bò֨ʼ mòşě֣h wĕ⁠ʼahàròn֮ ʼel-pȧrĕʻòh֒ wa⁠yò̇ʼmĕr֣ẇ ʼélá֗y⁠w kòֽ̇h-ʼáma֤r yĕhwáh֙ ʼèlòhé֣y háֽ⁠ʻibĕri֔ym ʻad-máţa֣y méʼa֔nĕţá̇ lé⁠ʻánò֖ţ mi⁠pá̇ná֑⁠y şǎlȧ֥ẖ ʻami֖̇⁠y wĕ⁠yaֽʻabĕduֽ⁠niy׃"],[10,4,"כִּ֛י אִם־מָאֵ֥ן אַתָּ֖ה לְ⁠שַׁלֵּ֣חַ אֶת־עַמִּ֑⁠י הִנְ⁠נִ֨י מֵבִ֥יא מָחָ֛ר אַרְבֶּ֖ה בִּ⁠גְבֻלֶֽ⁠ךָ׃","ki֛̇y ʼim-máʼé֥n ʼaţá֖̇h lĕ⁠şǎlé֣̇ẖa ʼeţ-ʻami֑̇⁠y hinĕ⁠ni֨y mébi֥yʼ máẖá֛r ʼarĕbė֖h bi̇⁠gĕbuleֽ⁠ká׃"],[10,5,"וְ⁠כִסָּה֙ אֶת־עֵ֣ין הָ⁠אָ֔רֶץ וְ⁠לֹ֥א יוּכַ֖ל לִ⁠רְאֹ֣ת אֶת־הָ⁠אָ֑רֶץ וְ⁠אָכַ֣ל ׀ אֶת־יֶ֣תֶר הַ⁠פְּלֵטָ֗ה הַ⁠נִּשְׁאֶ֤רֶת לָ⁠כֶם֙ מִן־הַ⁠בָּרָ֔ד וְ⁠אָכַל֙ אֶת־כָּל־הָ⁠עֵ֔ץ הַ⁠צֹּמֵ֥חַ לָ⁠כֶ֖ם מִן־הַ⁠שָּׂדֶֽה׃","wĕ⁠kisá̇h֙ ʼeţ-ʻé֣yn há⁠ʼá֔reẕ wĕ⁠lò֥ʼ yẇka֖l li⁠rĕʼò֣ţ ʼeţ-há⁠ʼá֑reẕ wĕ⁠ʼáka֣l ׀ ʼeţ-ye֣ţer ha⁠pĕ̇létá֗h ha⁠ni̇şĕ̌ʼe֤reţ lá⁠kem֙ min-ha⁠bá̇rá֔d wĕ⁠ʼákal֙ ʼeţ-ká̇l-há⁠ʻé֔ẕ ha⁠ẕò̇mé֥ẖa lá⁠ke֖m min-ha⁠şá̇̂deֽh׃"],[10,6,"וּ⁠מָלְא֨וּ בָתֶּ֜י⁠ךָ וּ⁠בָתֵּ֣י כָל־עֲבָדֶי⁠ךָ֮ וּ⁠בָתֵּ֣י כָל־מִצְרַיִם֒ אֲשֶׁ֨ר לֹֽא־רָא֤וּ אֲבֹתֶ֨י⁠ךָ֙ וַ⁠אֲב֣וֹת אֲבֹתֶ֔י⁠ךָ מִ⁠יּ֗וֹם הֱיוֹתָ⁠ם֙ עַל־הָ֣⁠אֲדָמָ֔ה עַ֖ד הַ⁠יּ֣וֹם הַ⁠זֶּ֑ה וַ⁠יִּ֥פֶן וַ⁠יֵּצֵ֖א מֵ⁠עִ֥ם פַּרְעֹֽה׃","ẇ⁠málĕʼ֨ẇ báţė֜y⁠ká ẇ⁠báţé֣̇y kál-ʻàbádey⁠ká֮ ẇ⁠báţé֣̇y kál-miẕĕrayim֒ ʼàşě֨r lòֽʼ-ráʼ֤ẇ ʼàbòţe֨y⁠ká֙ wa⁠ʼàb֣wòţ ʼàbòţe֔y⁠ká mi⁠ẏ֗wòm hèywòţá⁠m֙ ʻal-há֣⁠ʼàdámá֔h ʻa֖d ha⁠ẏ֣wòm ha⁠zė֑h wa⁠yi֥̇pen wa⁠yé̇ẕé֖ʼ mé⁠ʻi֥m pȧrĕʻòֽh׃"],[10,7,"וַ⁠יֹּאמְרוּ֩ עַבְדֵ֨י פַרְעֹ֜ה אֵלָ֗י⁠ו עַד־מָתַי֙ יִהְיֶ֨ה זֶ֥ה לָ֨⁠נוּ֙ לְ⁠מוֹקֵ֔שׁ שַׁלַּח֙ אֶת־הָ֣⁠אֲנָשִׁ֔ים וְ⁠יַֽעַבְד֖וּ אֶת־יְהוָ֣ה אֱלֹהֵי⁠הֶ֑ם הֲ⁠טֶ֣רֶם תֵּדַ֔ע כִּ֥י אָבְדָ֖ה מִצְרָֽיִם׃","wa⁠yò̇ʼmĕrẇ֩ ʻabĕdé֨y parĕʻò֜h ʼélá֗y⁠w ʻad-máţay֙ yihĕye֨h ze֥h lá֨⁠nẇ֙ lĕ⁠mwòqé֔ş̌ şǎlȧẖ֙ ʼeţ-há֣⁠ʼànáşǐ֔ym wĕ⁠yaֽʻabĕd֖ẇ ʼeţ-yĕhwá֣h ʼèlòhéy⁠he֑m hà⁠te֣rem ţé̇da֔ʻ ki֥̇y ʼábĕdá֖h miẕĕráֽyim׃"],[10,8,"וַ⁠יּוּשַׁ֞ב אֶת־מֹשֶׁ֤ה וְ⁠אֶֽת־אַהֲרֹן֙ אֶל־פַּרְעֹ֔ה וַ⁠יֹּ֣אמֶר אֲלֵ⁠הֶ֔ם לְכ֥וּ עִבְד֖וּ אֶת־יְהוָ֣ה אֱלֹהֵי⁠כֶ֑ם מִ֥י וָ⁠מִ֖י הַ⁠הֹלְכִֽים׃","wa⁠ẏẇşǎ֞b ʼeţ-mòşě֤h wĕ⁠ʼeֽţ-ʼahàròn֙ ʼel-pȧrĕʻò֔h wa⁠yò֣̇ʼmer ʼàlé⁠he֔m lĕk֥ẇ ʻibĕd֖ẇ ʼeţ-yĕhwá֣h ʼèlòhéy⁠ke֑m mi֥y wá⁠mi֖y ha⁠hòlĕkiֽym׃"],[10,9,"וַ⁠יֹּ֣אמֶר מֹשֶׁ֔ה בִּ⁠נְעָרֵ֥י⁠נוּ וּ⁠בִ⁠זְקֵנֵ֖י⁠נוּ נֵלֵ֑ךְ בְּ⁠בָנֵ֨י⁠נוּ וּ⁠בִ⁠בְנוֹתֵ֜⁠נוּ בְּ⁠צֹאנֵ֤⁠נוּ וּ⁠בִ⁠בְקָרֵ֨⁠נוּ֙ נֵלֵ֔ךְ כִּ֥י חַג־יְהוָ֖ה לָֽ⁠נוּ׃","wa⁠yò֣̇ʼmer mòşě֔h bi̇⁠nĕʻáré֥y⁠nẇ ẇ⁠bi⁠zĕqéné֖y⁠nẇ nélé֑kĕ bĕ̇⁠báné֨y⁠nẇ ẇ⁠bi⁠bĕnwòţé֜⁠nẇ bĕ̇⁠ẕòʼné֤⁠nẇ ẇ⁠bi⁠bĕqáré֨⁠nẇ֙ nélé֔kĕ ki֥̇y ẖag-yĕhwá֖h láֽ⁠nẇ׃"],[10,10,"וַ⁠יֹּ֣אמֶר אֲלֵ⁠הֶ֗ם יְהִ֨י כֵ֤ן יְהוָה֙ עִמָּ⁠כֶ֔ם כַּ⁠אֲשֶׁ֛ר אֲשַׁלַּ֥ח אֶתְ⁠כֶ֖ם וְ⁠אֶֽת־טַפְּ⁠כֶ֑ם רְא֕וּ כִּ֥י רָעָ֖ה נֶ֥גֶד פְּנֵי⁠כֶֽם׃","wa⁠yò֣̇ʼmer ʼàlé⁠he֗m yĕhi֨y ké֤n yĕhwáh֙ ʻimá̇⁠ke֔m kȧ⁠ʼàşě֛r ʼàşǎlȧ֥ẖ ʼeţĕ⁠ke֖m wĕ⁠ʼeֽţ-tapĕ̇⁠ke֑m rĕʼ֕ẇ ki֥̇y ráʻá֖h ne֥ged pĕ̇néy⁠keֽm׃"],[10,11,"לֹ֣א כֵ֗ן לְכֽוּ־נָ֤א הַ⁠גְּבָרִים֙ וְ⁠עִבְד֣וּ אֶת־יְהוָ֔ה כִּ֥י אֹתָ֖⁠הּ אַתֶּ֣ם מְבַקְשִׁ֑ים וַ⁠יְגָ֣רֶשׁ אֹתָ֔⁠ם מֵ⁠אֵ֖ת פְּנֵ֥י פַרְעֹֽה׃פ","lò֣ʼ ké֗n lĕkֽẇ-ná֤ʼ ha⁠gĕ̇báriym֙ wĕ⁠ʻibĕd֣ẇ ʼeţ-yĕhwá֔h ki֥̇y ʼòţá֖⁠ḣ ʼaţė֣m mĕbaqĕşǐ֑ym wa⁠yĕgá֣reş̌ ʼòţá֔⁠m mé⁠ʼé֖ţ pĕ̇né֥y parĕʻòֽh׃p"],[10,12,"וַ⁠יֹּ֨אמֶר יְהוָ֜ה אֶל־מֹשֶׁ֗ה נְטֵ֨ה יָדְ⁠ךָ֜ עַל־אֶ֤רֶץ מִצְרַ֨יִם֙ בָּֽ⁠אַרְבֶּ֔ה וְ⁠יַ֖עַל עַל־אֶ֣רֶץ מִצְרָ֑יִם וְ⁠יֹאכַל֙ אֶת־כָּל־עֵ֣שֶׂב הָ⁠אָ֔רֶץ אֵ֛ת כָּל־אֲשֶׁ֥ר הִשְׁאִ֖יר הַ⁠בָּרָֽד׃","wa⁠yò̇֨ʼmer yĕhwá֜h ʼel-mòşě֗h nĕté֨h yádĕ⁠ká֜ ʻal-ʼe֤reẕ miẕĕra֨yim֙ báֽ̇⁠ʼarĕbė֔h wĕ⁠ya֖ʻal ʻal-ʼe֣reẕ miẕĕrá֑yim wĕ⁠yòʼkal֙ ʼeţ-ká̇l-ʻé֣şêb há⁠ʼá֔reẕ ʼé֛ţ ká̇l-ʼàşě֥r hişĕ̌ʼi֖yr ha⁠bá̇ráֽd׃"],[10,13,"וַ⁠יֵּ֨ט מֹשֶׁ֣ה אֶת־מַטֵּ⁠הוּ֮ עַל־אֶ֣רֶץ מִצְרַיִם֒ וַֽ⁠יהוָ֗ה נִהַ֤ג ר֥וּחַ קָדִים֙ בָּ⁠אָ֔רֶץ כָּל־הַ⁠יּ֥וֹם הַ⁠ה֖וּא וְ⁠כָל־הַ⁠לָּ֑יְלָה הַ⁠בֹּ֣קֶר הָיָ֔ה וְ⁠ר֨וּחַ֙ הַ⁠קָּדִ֔ים נָשָׂ֖א אֶת־הָ⁠אַרְבֶּֽה׃","wa⁠yé̇֨t mòşě֣h ʼeţ-maté̇⁠hẇ֮ ʻal-ʼe֣reẕ miẕĕrayim֒ wֽa⁠yhwá֗h niha֤g r֥ẇẖa qádiym֙ bá̇⁠ʼá֔reẕ ká̇l-ha⁠ẏ֥wòm ha⁠h֖ẇʼ wĕ⁠kál-ha⁠lá֑̇yĕláh ha⁠bò֣̇qer háyá֔h wĕ⁠r֨ẇẖa֙ ha⁠qá̇di֔ym náşá֖̂ʼ ʼeţ-há⁠ʼarĕbėֽh׃"],[10,14,"וַ⁠יַּ֣עַל הָֽ⁠אַרְבֶּ֗ה עַ֚ל כָּל־אֶ֣רֶץ מִצְרַ֔יִם וַ⁠יָּ֕נַח בְּ⁠כֹ֖ל גְּב֣וּל מִצְרָ֑יִם כָּבֵ֣ד מְאֹ֔ד לְ֠⁠פָנָי⁠ו לֹא־הָ֨יָה כֵ֤ן אַרְבֶּה֙ כָּמֹ֔⁠הוּ וְ⁠אַחֲרָ֖י⁠ו לֹ֥א יִֽהְיֶה־כֵּֽן׃","wa⁠yȧ֣ʻal háֽ⁠ʼarĕbė֗h ʻa֚l ká̇l-ʼe֣reẕ miẕĕra֔yim wa⁠yá̇֕naẖ bĕ̇⁠kò֖l gĕ̇b֣ẇl miẕĕrá֑yim ká̇bé֣d mĕʼò֔d lĕ֠⁠pánáy⁠w lòʼ-há֨yáh ké֤n ʼarĕbėh֙ ká̇mò֔⁠hẇ wĕ⁠ʼaẖàrá֖y⁠w lò֥ʼ yiֽhĕyeh-kéֽ̇n׃"],[10,15,"וַ⁠יְכַ֞ס אֶת־עֵ֣ין כָּל־הָ⁠אָרֶץ֮ וַ⁠תֶּחְשַׁ֣ךְ הָ⁠אָרֶץ֒ וַ⁠יֹּ֜אכַל אֶת־כָּל־עֵ֣שֶׂב הָ⁠אָ֗רֶץ וְ⁠אֵת֙ כָּל־פְּרִ֣י הָ⁠עֵ֔ץ אֲשֶׁ֥ר הוֹתִ֖יר הַ⁠בָּרָ֑ד וְ⁠לֹא־נוֹתַ֨ר כָּל־יֶ֧רֶק בָּ⁠עֵ֛ץ וּ⁠בְ⁠עֵ֥שֶׂב הַ⁠שָּׂדֶ֖ה בְּ⁠כָל־אֶ֥רֶץ מִצְרָֽיִם׃","wa⁠yĕka֞s ʼeţ-ʻé֣yn ká̇l-há⁠ʼáreẕ֮ wa⁠ţėẖĕşǎ֣kĕ há⁠ʼáreẕ֒ wa⁠yò̇֜ʼkal ʼeţ-ká̇l-ʻé֣şêb há⁠ʼá֗reẕ wĕ⁠ʼéţ֙ ká̇l-pĕ̇ri֣y há⁠ʻé֔ẕ ʼàşě֥r hwòţi֖yr ha⁠bá̇rá֑d wĕ⁠lòʼ-nwòţa֨r ká̇l-ye֧req bá̇⁠ʻé֛ẕ ẇ⁠bĕ⁠ʻé֥şêb ha⁠şá̇̂de֖h bĕ̇⁠kál-ʼe֥reẕ miẕĕráֽyim׃"],[10,16,"וַ⁠יְמַהֵ֣ר פַּרְעֹ֔ה לִ⁠קְרֹ֖א לְ⁠מֹשֶׁ֣ה וּֽ⁠לְ⁠אַהֲרֹ֑ן וַ⁠יֹּ֗אמֶר חָטָ֛אתִי לַ⁠יהוָ֥ה אֱלֹֽהֵי⁠כֶ֖ם וְ⁠לָ⁠כֶֽם׃","wa⁠yĕmahé֣r pȧrĕʻò֔h li⁠qĕrò֖ʼ lĕ⁠mòşě֣h ẇֽ⁠lĕ⁠ʼahàrò֑n wa⁠yò̇֗ʼmer ẖátá֛ʼţiy la⁠yhwá֥h ʼèlòֽhéy⁠ke֖m wĕ⁠lá⁠keֽm׃"],[10,17,"וְ⁠עַתָּ֗ה שָׂ֣א נָ֤א חַטָּאתִ⁠י֙ אַ֣ךְ הַ⁠פַּ֔עַם וְ⁠הַעְתִּ֖ירוּ לַ⁠יהוָ֣ה אֱלֹהֵי⁠כֶ֑ם וְ⁠יָסֵר֙ מֵֽ⁠עָלַ֔⁠י רַ֖ק אֶת־הַ⁠מָּ֥וֶת הַ⁠זֶּֽה׃","wĕ⁠ʻaţá̇֗h şá֣̂ʼ ná֤ʼ ẖatá̇ʼţi⁠y֙ ʼa֣kĕ ha⁠pȧ֔ʻam wĕ⁠haʻĕţi֖̇yrẇ la⁠yhwá֣h ʼèlòhéy⁠ke֑m wĕ⁠yásér֙ méֽ⁠ʻála֔⁠y ra֖q ʼeţ-ha⁠má֥̇weţ ha⁠zėֽh׃"],[10,18,"וַ⁠יֵּצֵ֖א מֵ⁠עִ֣ם פַּרְעֹ֑ה וַ⁠יֶּעְתַּ֖ר אֶל־יְהוָֽה׃","wa⁠yé̇ẕé֖ʼ mé⁠ʻi֣m pȧrĕʻò֑h wa⁠yėʻĕţȧ֖r ʼel-yĕhwáֽh׃"],[10,19,"וַ⁠יַּהֲפֹ֨ךְ יְהוָ֤ה רֽוּחַ־יָם֙ חָזָ֣ק מְאֹ֔ד וַ⁠יִּשָּׂא֙ אֶת־הָ֣⁠אַרְבֶּ֔ה וַ⁠יִּתְקָעֵ֖⁠הוּ יָ֣מָּ⁠ה סּ֑וּף לֹ֤א נִשְׁאַר֙ אַרְבֶּ֣ה אֶחָ֔ד בְּ⁠כֹ֖ל גְּב֥וּל מִצְרָֽיִם׃","wa⁠yȧhàpò֨kĕ yĕhwá֤h rֽẇẖa-yám֙ ẖázá֣q mĕʼò֔d wa⁠yi̇şá̇̂ʼ֙ ʼeţ-há֣⁠ʼarĕbė֔h wa⁠yi̇ţĕqáʻé֖⁠hẇ yá֣má̇⁠h ṡ֑ẇp lò֤ʼ nişĕ̌ʼar֙ ʼarĕbė֣h ʼeẖá֔d bĕ̇⁠kò֖l gĕ̇b֥ẇl miẕĕráֽyim׃"],[10,20,"וַ⁠יְחַזֵּ֥ק יְהוָ֖ה אֶת־לֵ֣ב פַּרְעֹ֑ה וְ⁠לֹ֥א שִׁלַּ֖ח אֶת־בְּנֵ֥י יִשְׂרָאֵֽל׃פ","wa⁠yĕẖazé֥̇q yĕhwá֖h ʼeţ-lé֣b pȧrĕʻò֑h wĕ⁠lò֥ʼ şǐlȧ֖ẖ ʼeţ-bĕ̇né֥y yişĕ̂ráʼéֽl׃p"],[10,21,"וַ⁠יֹּ֨אמֶר יְהוָ֜ה אֶל־מֹשֶׁ֗ה נְטֵ֤ה יָֽדְ⁠ךָ֙ עַל־הַ⁠שָּׁמַ֔יִם וִ֥⁠יהִי חֹ֖שֶׁךְ עַל־אֶ֣רֶץ מִצְרָ֑יִם וְ⁠יָמֵ֖שׁ חֹֽשֶׁךְ׃","wa⁠yò̇֨ʼmer yĕhwá֜h ʼel-mòşě֗h nĕté֤h yáֽdĕ⁠ká֙ ʻal-ha⁠şá̇̌ma֔yim wi֥⁠yhiy ẖò֖şěkĕ ʻal-ʼe֣reẕ miẕĕrá֑yim wĕ⁠yámé֖ş̌ ẖòֽşěkĕ׃"],[10,22,"וַ⁠יֵּ֥ט מֹשֶׁ֛ה אֶת־יָד֖⁠וֹ עַל־הַ⁠שָּׁמָ֑יִם וַ⁠יְהִ֧י חֹֽשֶׁךְ־אֲפֵלָ֛ה בְּ⁠כָל־אֶ֥רֶץ מִצְרַ֖יִם שְׁלֹ֥שֶׁת יָמִֽים׃","wa⁠yé֥̇t mòşě֛h ʼeţ-yád֖⁠wò ʻal-ha⁠şá̇̌má֑yim wa⁠yĕhi֧y ẖòֽşěkĕ-ʼàpélá֛h bĕ̇⁠kál-ʼe֥reẕ miẕĕra֖yim şĕ̌lò֥şěţ yámiֽym׃"],[10,23,"לֹֽא־רָא֞וּ אִ֣ישׁ אֶת־אָחִ֗י⁠ו וְ⁠לֹא־קָ֛מוּ אִ֥ישׁ מִ⁠תַּחְתָּ֖י⁠ו שְׁלֹ֣שֶׁת יָמִ֑ים וּֽ⁠לְ⁠כָל־בְּנֵ֧י יִשְׂרָאֵ֛ל הָ֥יָה א֖וֹר בְּ⁠מוֹשְׁבֹתָֽ⁠ם׃","lòֽʼ-ráʼ֞ẇ ʼi֣yş̌ ʼeţ-ʼáẖi֗y⁠w wĕ⁠lòʼ-qá֛mẇ ʼi֥yş̌ mi⁠ţȧẖĕţá֖̇y⁠w şĕ̌lò֣şěţ yámi֑ym ẇֽ⁠lĕ⁠kál-bĕ̇né֧y yişĕ̂ráʼé֛l há֥yáh ʼ֖wòr bĕ̇⁠mwòşĕ̌bòţáֽ⁠m׃"],[10,24,"וַ⁠יִּקְרָ֨א פַרְעֹ֜ה אֶל־מֹשֶׁ֗ה וַ⁠יֹּ֨אמֶר֙ לְכוּ֙ עִבְד֣וּ אֶת־יְהוָ֔ה רַ֛ק צֹאנְ⁠כֶ֥ם וּ⁠בְקַרְ⁠כֶ֖ם יֻצָּ֑ג גַּֽם־טַפְּ⁠כֶ֖ם יֵלֵ֥ךְ עִמָּ⁠כֶֽם׃","wa⁠yi̇qĕrá֨ʼ parĕʻò֜h ʼel-mòşě֗h wa⁠yò̇֨ʼmer֙ lĕkẇ֙ ʻibĕd֣ẇ ʼeţ-yĕhwá֔h ra֛q ẕòʼnĕ⁠ke֥m ẇ⁠bĕqarĕ⁠ke֖m yuẕá֑̇g gȧֽm-tapĕ̇⁠ke֖m yélé֥kĕ ʻimá̇⁠keֽm׃"],[10,25,"וַ⁠יֹּ֣אמֶר מֹשֶׁ֔ה גַּם־אַתָּ֛ה תִּתֵּ֥ן בְּ⁠יָדֵ֖⁠נוּ זְבָחִ֣ים וְ⁠עֹל֑וֹת וְ⁠עָשִׂ֖ינוּ לַ⁠יהוָ֥ה אֱלֹהֵֽי⁠נוּ׃","wa⁠yò֣̇ʼmer mòşě֔h gȧm-ʼaţá֛̇h ţi̇ţé֥̇n bĕ̇⁠yádé֖⁠nẇ zĕbáẖi֣ym wĕ⁠ʻòl֑wòţ wĕ⁠ʻáşî֖ynẇ la⁠yhwá֥h ʼèlòhéֽy⁠nẇ׃"],[10,26,"וְ⁠גַם־מִקְנֵ֜⁠נוּ יֵלֵ֣ךְ עִמָּ֗⁠נוּ לֹ֤א תִשָּׁאֵר֙ פַּרְסָ֔ה כִּ֚י מִמֶּ֣⁠נּוּ נִקַּ֔ח לַ⁠עֲבֹ֖ד אֶת־יְהוָ֣ה אֱלֹהֵ֑י⁠נוּ וַ⁠אֲנַ֣חְנוּ לֹֽא־נֵדַ֗ע מַֽה־נַּעֲבֹד֙ אֶת־יְהוָ֔ה עַד־בֹּאֵ֖⁠נוּ שָֽׁמָּ⁠ה׃","wĕ⁠gam-miqĕné֜⁠nẇ yélé֣kĕ ʻimá̇֗⁠nẇ lò֤ʼ ţişá̇̌ʼér֙ pȧrĕsá֔h ki֚̇y mimė֣⁠ṅẇ niqȧ֔ẖ la⁠ʻàbò֖d ʼeţ-yĕhwá֣h ʼèlòhé֑y⁠nẇ wa⁠ʼàna֣ẖĕnẇ lòֽʼ-néda֗ʻ maֽh-nȧʻàbòd֙ ʼeţ-yĕhwá֔h ʻad-bò̇ʼé֖⁠nẇ şáֽ̌má̇⁠h׃"],[10,27,"וַ⁠יְחַזֵּ֥ק יְהוָ֖ה אֶת־לֵ֣ב פַּרְעֹ֑ה וְ⁠לֹ֥א אָבָ֖ה לְ⁠שַׁלְּחָֽ⁠ם׃","wa⁠yĕẖazé֥̇q yĕhwá֖h ʼeţ-lé֣b pȧrĕʻò֑h wĕ⁠lò֥ʼ ʼábá֖h lĕ⁠şǎlĕ̇ẖáֽ⁠m׃"],[10,28,"וַ⁠יֹּֽאמֶר־ל֥⁠וֹ פַרְעֹ֖ה לֵ֣ךְ מֵ⁠עָלָ֑⁠י הִשָּׁ֣מֶר לְ⁠ךָ֗ אֶל־תֹּ֨סֶף֙ רְא֣וֹת פָּנַ֔⁠י כִּ֗י בְּ⁠י֛וֹם רְאֹתְ⁠ךָ֥ פָנַ֖⁠י תָּמֽוּת׃","wa⁠yòֽ̇ʼmer-l֥⁠wò parĕʻò֖h lé֣kĕ mé⁠ʻálá֑⁠y hişá֣̇̌mer lĕ⁠ká֗ ʼel-ţò̇֨sep֙ rĕʼ֣wòţ pá̇na֔⁠y ki̇֗y bĕ̇⁠y֛wòm rĕʼòţĕ⁠ká֥ pána֖⁠y ţá̇mֽẇţ׃"],[10,29,"וַ⁠יֹּ֥אמֶר מֹשֶׁ֖ה כֵּ֣ן דִּבַּ֑רְתָּ לֹא־אֹסִ֥ף ע֖וֹד רְא֥וֹת פָּנֶֽי⁠ךָ׃פ","wa⁠yò֥̇ʼmer mòşě֖h ké֣̇n di̇bȧ֑rĕţá̇ lòʼ-ʼòsi֥p ʻ֖wòd rĕʼ֥wòţ pá̇neֽy⁠ká׃p"],[11,1,"וַ⁠יֹּ֨אמֶר יְהוָ֜ה אֶל־מֹשֶׁ֗ה ע֣וֹד נֶ֤גַע אֶחָד֙ אָבִ֤יא עַל־פַּרְעֹה֙ וְ⁠עַל־מִצְרַ֔יִם אַֽחֲרֵי־כֵ֕ן יְשַׁלַּ֥ח אֶתְ⁠כֶ֖ם מִ⁠זֶּ֑ה כְּ⁠שַׁ֨לְּח֔⁠וֹ כָּלָ֕ה גָּרֵ֛שׁ יְגָרֵ֥שׁ אֶתְ⁠כֶ֖ם מִ⁠זֶּֽה׃","wa⁠yò̇֨ʼmer yĕhwá֜h ʼel-mòşě֗h ʻ֣wòd ne֤gaʻ ʼeẖád֙ ʼábi֤yʼ ʻal-pȧrĕʻòh֙ wĕ⁠ʻal-miẕĕra֔yim ʼֽaẖàréy-ké֕n yĕşǎlȧ֥ẖ ʼeţĕ⁠ke֖m mi⁠zė֑h kĕ̇⁠şǎ֨lĕ̇ẖ֔⁠wò ká̇lá֕h gá̇ré֛ş̌ yĕgáré֥ş̌ ʼeţĕ⁠ke֖m mi⁠zėֽh׃"],[11,2,"דַּבֶּר־נָ֖א בְּ⁠אָזְנֵ֣י הָ⁠עָ֑ם וְ⁠יִשְׁאֲל֞וּ אִ֣ישׁ ׀ מֵ⁠אֵ֣ת רֵעֵ֗⁠הוּ וְ⁠אִשָּׁה֙ מֵ⁠אֵ֣ת רְעוּתָ֔⁠הּ כְּלֵי־כֶ֖סֶף וּ⁠כְלֵ֥י זָהָֽב׃","dȧbėr-ná֖ʼ bĕ̇⁠ʼázĕné֣y há⁠ʻá֑m wĕ⁠yişĕ̌ʼàl֞ẇ ʼi֣yş̌ ׀ mé⁠ʼé֣ţ réʻé֗⁠hẇ wĕ⁠ʼişá̇̌h֙ mé⁠ʼé֣ţ rĕʻẇţá֔⁠ḣ kĕ̇léy-ke֖sep ẇ⁠kĕlé֥y záháֽb׃"],[11,3,"וַ⁠יִּתֵּ֧ן יְהוָ֛ה אֶת־חֵ֥ן הָ⁠עָ֖ם בְּ⁠עֵינֵ֣י מִצְרָ֑יִם גַּ֣ם ׀ הָ⁠אִ֣ישׁ מֹשֶׁ֗ה גָּד֤וֹל מְאֹד֙ בְּ⁠אֶ֣רֶץ מִצְרַ֔יִם בְּ⁠עֵינֵ֥י עַבְדֵֽי־פַרְעֹ֖ה וּ⁠בְ⁠עֵינֵ֥י הָ⁠עָֽם׃ס","wa⁠yi̇ţé֧̇n yĕhwá֛h ʼeţ-ẖé֥n há⁠ʻá֖m bĕ̇⁠ʻéyné֣y miẕĕrá֑yim gȧ֣m ׀ há⁠ʼi֣yş̌ mòşě֗h gá̇d֤wòl mĕʼòd֙ bĕ̇⁠ʼe֣reẕ miẕĕra֔yim bĕ̇⁠ʻéyné֥y ʻabĕdéֽy-parĕʻò֖h ẇ⁠bĕ⁠ʻéyné֥y há⁠ʻáֽm׃s"],[11,4,"וַ⁠יֹּ֣אמֶר מֹשֶׁ֔ה כֹּ֖ה אָמַ֣ר יְהוָ֑ה כַּ⁠חֲצֹ֣ת הַ⁠לַּ֔יְלָה אֲנִ֥י יוֹצֵ֖א בְּ⁠ת֥וֹךְ מִצְרָֽיִם׃","wa⁠yò֣̇ʼmer mòşě֔h kò֖̇h ʼáma֣r yĕhwá֑h kȧ⁠ẖàẕò֣ţ ha⁠lȧ֔yĕláh ʼàni֥y ywòẕé֖ʼ bĕ̇⁠ţ֥wòkĕ miẕĕráֽyim׃"],[11,5,"וּ⁠מֵ֣ת כָּל־בְּכוֹר֮ בְּ⁠אֶ֣רֶץ מִצְרַיִם֒ מִ⁠בְּכ֤וֹר פַּרְעֹה֙ הַ⁠יֹּשֵׁ֣ב עַל־כִּסְא֔⁠וֹ עַ֚ד בְּכ֣וֹר הַ⁠שִּׁפְחָ֔ה אֲשֶׁ֖ר אַחַ֣ר הָ⁠רֵחָ֑יִם וְ⁠כֹ֖ל בְּכ֥וֹר בְּהֵמָֽה׃","ẇ⁠mé֣ţ ká̇l-bĕ̇kwòr֮ bĕ̇⁠ʼe֣reẕ miẕĕrayim֒ mi⁠bĕ̇k֤wòr pȧrĕʻòh֙ ha⁠yò̇şé֣̌b ʻal-ki̇sĕʼ֔⁠wò ʻa֚d bĕ̇k֣wòr ha⁠şi̇̌pĕẖá֔h ʼàşě֖r ʼaẖa֣r há⁠réẖá֑yim wĕ⁠kò֖l bĕ̇k֥wòr bĕ̇hémáֽh׃"],[11,6,"וְ⁠הָֽיְתָ֛ה צְעָקָ֥ה גְדֹלָ֖ה בְּ⁠כָל־אֶ֣רֶץ מִצְרָ֑יִם אֲשֶׁ֤ר כָּמֹ֨⁠הוּ֙ לֹ֣א נִהְיָ֔תָה וְ⁠כָמֹ֖⁠הוּ לֹ֥א תֹסִֽף׃","wĕ⁠háֽyĕţá֛h ẕĕʻáqá֥h gĕdòlá֖h bĕ̇⁠kál-ʼe֣reẕ miẕĕrá֑yim ʼàşě֤r ká̇mò֨⁠hẇ֙ lò֣ʼ nihĕyá֔ţáh wĕ⁠kámò֖⁠hẇ lò֥ʼ ţòsiֽp׃"],[11,7,"וּ⁠לְ⁠כֹ֣ל ׀ בְּנֵ֣י יִשְׂרָאֵ֗ל לֹ֤א יֶֽחֱרַץ־כֶּ֨לֶב֙ לְשֹׁנ֔⁠וֹ לְ⁠מֵ⁠אִ֖ישׁ וְ⁠עַד־בְּהֵמָ֑ה לְמַ֨עַן֙ תֵּֽדְע֔וּ⁠ן אֲשֶׁר֙ יַפְלֶ֣ה יְהוָ֔ה בֵּ֥ין מִצְרַ֖יִם וּ⁠בֵ֥ין יִשְׂרָאֵֽל׃","ẇ⁠lĕ⁠kò֣l ׀ bĕ̇né֣y yişĕ̂ráʼé֗l lò֤ʼ yeֽẖèraẕ-kė֨leb֙ lĕşò̌n֔⁠wò lĕ⁠mé⁠ʼi֖yş̌ wĕ⁠ʻad-bĕ̇hémá֑h lĕma֨ʻan֙ ţéֽ̇dĕʻ֔ẇ⁠n ʼàşěr֙ yapĕle֣h yĕhwá֔h bé֥̇yn miẕĕra֖yim ẇ⁠bé֥yn yişĕ̂ráʼéֽl׃"],[11,8,"וְ⁠יָרְד֣וּ כָל־עֲבָדֶי⁠ךָ֩ אֵ֨לֶּה אֵלַ֜⁠י וְ⁠הִשְׁתַּֽחֲוּוּ־לִ֣⁠י לֵ⁠אמֹ֗ר צֵ֤א אַתָּה֙ וְ⁠כָל־הָ⁠עָ֣ם אֲשֶׁר־בְּ⁠רַגְלֶ֔י⁠ךָ וְ⁠אַחֲרֵי־כֵ֖ן אֵצֵ֑א וַ⁠יֵּצֵ֥א מֵֽ⁠עִם־פַּרְעֹ֖ה בָּ⁠חֳרִי־אָֽף׃ס","wĕ⁠yárĕd֣ẇ kál-ʻàbádey⁠ká֩ ʼé֨lėh ʼéla֜⁠y wĕ⁠hişĕ̌ţȧֽẖàẇẇ-li֣⁠y lé⁠ʼmò֗r ẕé֤ʼ ʼaţá̇h֙ wĕ⁠kál-há⁠ʻá֣m ʼàşěr-bĕ̇⁠ragĕle֔y⁠ká wĕ⁠ʼaẖàréy-ké֖n ʼéẕé֑ʼ wa⁠yé̇ẕé֥ʼ méֽ⁠ʻim-pȧrĕʻò֖h bá̇⁠ẖoriy-ʼáֽp׃s"],[11,9,"וַ⁠יֹּ֤אמֶר יְהוָה֙ אֶל־מֹשֶׁ֔ה לֹא־יִשְׁמַ֥ע אֲלֵי⁠כֶ֖ם פַּרְעֹ֑ה לְמַ֛עַן רְב֥וֹת מוֹפְתַ֖⁠י בְּ⁠אֶ֥רֶץ מִצְרָֽיִם׃","wa⁠yò֤̇ʼmer yĕhwáh֙ ʼel-mòşě֔h lòʼ-yişĕ̌ma֥ʻ ʼàléy⁠ke֖m pȧrĕʻò֑h lĕma֛ʻan rĕb֥wòţ mwòpĕţa֖⁠y bĕ̇⁠ʼe֥reẕ miẕĕráֽyim׃"],[11,10,"וּ⁠מֹשֶׁ֣ה וְ⁠אַהֲרֹ֗ן עָשׂ֛וּ אֶת־כָּל־הַ⁠מֹּפְתִ֥ים הָ⁠אֵ֖לֶּה לִ⁠פְנֵ֣י פַרְעֹ֑ה וַ⁠יְחַזֵּ֤ק יְהוָה֙ אֶת־לֵ֣ב פַּרְעֹ֔ה וְ⁠לֹֽא־שִׁלַּ֥ח אֶת־בְּנֵֽי־יִשְׂרָאֵ֖ל מֵ⁠אַרְצֽ⁠וֹ׃פ","ẇ⁠mòşě֣h wĕ⁠ʼahàrò֗n ʻáş֛̂ẇ ʼeţ-ká̇l-ha⁠mò̇pĕţi֥ym há⁠ʼé֖lėh li⁠pĕné֣y parĕʻò֑h wa⁠yĕẖazé֤̇q yĕhwáh֙ ʼeţ-lé֣b pȧrĕʻò֔h wĕ⁠lòֽʼ-şǐlȧ֥ẖ ʼeţ-bĕ̇néֽy-yişĕ̂ráʼé֖l mé⁠ʼarĕẕֽ⁠wò׃p"],[12,1,"וַ⁠יֹּ֤אמֶר יְהוָה֙ אֶל־מֹשֶׁ֣ה וְ⁠אֶֽל־אַהֲרֹ֔ן בְּ⁠אֶ֥רֶץ מִצְרַ֖יִם לֵ⁠אמֹֽר׃","wa⁠yò֤̇ʼmer yĕhwáh֙ ʼel-mòşě֣h wĕ⁠ʼeֽl-ʼahàrò֔n bĕ̇⁠ʼe֥reẕ miẕĕra֖yim lé⁠ʼmòֽr׃"],[12,2,"הַ⁠חֹ֧דֶשׁ הַ⁠זֶּ֛ה לָ⁠כֶ֖ם רֹ֣אשׁ חֳדָשִׁ֑ים רִאשׁ֥וֹן הוּא֙ לָ⁠כֶ֔ם לְ⁠חָדְשֵׁ֖י הַ⁠שָּׁנָֽה׃","ha⁠ẖò֧deş̌ ha⁠zė֛h lá⁠ke֖m rò֣ʼş̌ ẖodáşǐ֑ym riʼş֥̌wòn hẇʼ֙ lá⁠ke֔m lĕ⁠ẖádĕşé֖̌y ha⁠şá̇̌náֽh׃"],[12,3,"דַּבְּר֗וּ אֶֽל־כָּל־עֲדַ֤ת יִשְׂרָאֵל֙ לֵ⁠אמֹ֔ר בֶּ⁠עָשֹׂ֖ר לַ⁠חֹ֣דֶשׁ הַ⁠זֶּ֑ה וְ⁠יִקְח֣וּ לָ⁠הֶ֗ם אִ֛ישׁ שֶׂ֥ה לְ⁠בֵית־אָבֹ֖ת שֶׂ֥ה לַ⁠בָּֽיִת׃","dȧbĕ̇r֗ẇ ʼeֽl-ká̇l-ʻàda֤ţ yişĕ̂ráʼél֙ lé⁠ʼmò֔r bė⁠ʻáşò֖̂r la⁠ẖò֣deş̌ ha⁠zė֑h wĕ⁠yiqĕẖ֣ẇ lá⁠he֗m ʼi֛yş̌ şê֥h lĕ⁠béyţ-ʼábò֖ţ şê֥h la⁠báֽ̇yiţ׃"],[12,4,"וְ⁠אִם־יִמְעַ֣ט הַ⁠בַּיִת֮ מִ⁠הְיֹ֣ת מִ⁠שֶּׂה֒ וְ⁠לָקַ֣ח ה֗וּא וּ⁠שְׁכֵנ֛⁠וֹ הַ⁠קָּרֹ֥ב אֶל־בֵּית֖⁠וֹ בְּ⁠מִכְסַ֣ת נְפָשֹׁ֑ת אִ֚ישׁ לְ⁠פִ֣י אָכְל֔⁠וֹ תָּכֹ֖סּוּ עַל־הַ⁠שֶּֽׂה׃","wĕ⁠ʼim-yimĕʻa֣t ha⁠bȧyiţ֮ mi⁠hĕyò֣ţ mi⁠şė̂h֒ wĕ⁠láqa֣ẖ h֗ẇʼ ẇ⁠şĕ̌kén֛⁠wò ha⁠qá̇rò֥b ʼel-bé̇yţ֖⁠wò bĕ̇⁠mikĕsa֣ţ nĕpáşò֑̌ţ ʼi֚yş̌ lĕ⁠pi֣y ʼákĕl֔⁠wò ţá̇kò֖ṡẇ ʻal-ha⁠şėֽ̂h׃"],[12,5,"שֶׂ֥ה תָמִ֛ים זָכָ֥ר בֶּן־שָׁנָ֖ה יִהְיֶ֣ה לָ⁠כֶ֑ם מִן־הַ⁠כְּבָשִׂ֥ים וּ⁠מִן־הָ⁠עִזִּ֖ים תִּקָּֽחוּ׃","şê֥h ţámi֛ym záká֥r bėn-şá̌ná֖h yihĕye֣h lá⁠ke֑m min-ha⁠kĕ̇báşî֥ym ẇ⁠min-há⁠ʻizi֖̇ym ţi̇qáֽ̇ẖẇ׃"],[12,6,"וְ⁠הָיָ֤ה לָ⁠כֶם֙ לְ⁠מִשְׁמֶ֔רֶת עַ֣ד אַרְבָּעָ֥ה עָשָׂ֛ר י֖וֹם לַ⁠חֹ֣דֶשׁ הַ⁠זֶּ֑ה וְ⁠שָׁחֲט֣וּ אֹת֗⁠וֹ כֹּ֛ל קְהַ֥ל עֲדַֽת־יִשְׂרָאֵ֖ל בֵּ֥ין הָ⁠עַרְבָּֽיִם׃","wĕ⁠háyá֤h lá⁠kem֙ lĕ⁠mişĕ̌me֔reţ ʻa֣d ʼarĕbá̇ʻá֥h ʻáşá֛̂r y֖wòm la⁠ẖò֣deş̌ ha⁠zė֑h wĕ⁠şá̌ẖàt֣ẇ ʼòţ֗⁠wò kò֛̇l qĕha֥l ʻàdaֽţ-yişĕ̂ráʼé֖l bé֥̇yn há⁠ʻarĕbáֽ̇yim׃"],[12,7,"וְ⁠לָֽקְחוּ֙ מִן־הַ⁠דָּ֔ם וְ⁠נָֽתְנ֛וּ עַל־שְׁתֵּ֥י הַ⁠מְּזוּזֹ֖ת וְ⁠עַל־הַ⁠מַּשְׁק֑וֹף עַ֚ל הַ⁠בָּ֣תִּ֔ים אֲשֶׁר־יֹאכְל֥וּ אֹת֖⁠וֹ בָּ⁠הֶֽם׃","wĕ⁠láֽqĕẖẇ֙ min-ha⁠dá̇֔m wĕ⁠náֽţĕn֛ẇ ʻal-şĕ̌ţé֥̇y ha⁠mĕ̇zẇzò֖ţ wĕ⁠ʻal-ha⁠mȧşĕ̌q֑wòp ʻa֚l ha⁠bá֣̇ţi̇֔ym ʼàşěr-yòʼkĕl֥ẇ ʼòţ֖⁠wò bá̇⁠heֽm׃"],[12,8,"וְ⁠אָכְל֥וּ אֶת־הַ⁠בָּשָׂ֖ר בַּ⁠לַּ֣יְלָה הַ⁠זֶּ֑ה צְלִי־אֵ֣שׁ וּ⁠מַצּ֔וֹת עַל־מְרֹרִ֖ים יֹאכְלֻֽ⁠הוּ׃","wĕ⁠ʼákĕl֥ẇ ʼeţ-ha⁠bá̇şá֖̂r bȧ⁠lȧ֣yĕláh ha⁠zė֑h ẕĕliy-ʼé֣ş̌ ẇ⁠maẕ̇֔wòţ ʻal-mĕròri֖ym yòʼkĕluֽ⁠hẇ׃"],[12,9,"אַל־תֹּאכְל֤וּ מִמֶּ֨⁠נּוּ֙ נָ֔א וּ⁠בָשֵׁ֥ל מְבֻשָּׁ֖ל בַּ⁠מָּ֑יִם כִּ֣י אִם־צְלִי־אֵ֔שׁ רֹאשׁ֥⁠וֹ עַל־כְּרָעָ֖י⁠ו וְ⁠עַל־קִרְבּֽ⁠וֹ׃","ʼal-ţò̇ʼkĕl֤ẇ mimė֨⁠ṅẇ֙ ná֔ʼ ẇ⁠báşé֥̌l mĕbuşá֖̇̌l bȧ⁠má֑̇yim ki֣̇y ʼim-ẕĕliy-ʼé֔ş̌ ròʼş֥̌⁠wò ʻal-kĕ̇ráʻá֖y⁠w wĕ⁠ʻal-qirĕḃֽ⁠wò׃"],[12,10,"וְ⁠לֹא־תוֹתִ֥ירוּ מִמֶּ֖⁠נּוּ עַד־בֹּ֑קֶר וְ⁠הַ⁠נֹּתָ֥ר מִמֶּ֛⁠נּוּ עַד־בֹּ֖קֶר בָּ⁠אֵ֥שׁ תִּשְׂרֹֽפוּ׃","wĕ⁠lòʼ-ţwòţi֥yrẇ mimė֖⁠ṅẇ ʻad-bò֑̇qer wĕ⁠ha⁠nò̇ţá֥r mimė֛⁠ṅẇ ʻad-bò֖̇qer bá̇⁠ʼé֥ş̌ ţi̇şĕ̂ròֽpẇ׃"],[12,11,"וְ⁠כָכָה֮ תֹּאכְל֣וּ אֹת⁠וֹ֒ מָתְנֵי⁠כֶ֣ם חֲגֻרִ֔ים נַֽעֲלֵי⁠כֶם֙ בְּ⁠רַגְלֵי⁠כֶ֔ם וּ⁠מַקֶּלְ⁠כֶ֖ם בְּ⁠יֶדְ⁠כֶ֑ם וַ⁠אֲכַלְתֶּ֤ם אֹת⁠וֹ֙ בְּ⁠חִפָּז֔וֹן פֶּ֥סַח ה֖וּא לַ⁠יהוָֽה׃","wĕ⁠kákáh֮ ţò̇ʼkĕl֣ẇ ʼòţ⁠wò֒ máţĕnéy⁠ke֣m ẖàguri֔ym nֽaʻàléy⁠kem֙ bĕ̇⁠ragĕléy⁠ke֔m ẇ⁠maqėlĕ⁠ke֖m bĕ̇⁠yedĕ⁠ke֑m wa⁠ʼàkalĕţė֤m ʼòţ⁠wò֙ bĕ̇⁠ẖipá̇z֔wòn pė֥saẖ h֖ẇʼ la⁠yhwáֽh׃"],[12,12,"וְ⁠עָבַרְתִּ֣י בְ⁠אֶֽרֶץ־מִצְרַיִם֮ בַּ⁠לַּ֣יְלָה הַ⁠זֶּה֒ וְ⁠הִכֵּיתִ֤י כָל־בְּכוֹר֙ בְּ⁠אֶ֣רֶץ מִצְרַ֔יִם מֵ⁠אָדָ֖ם וְ⁠עַד־בְּהֵמָ֑ה וּ⁠בְ⁠כָל־אֱלֹהֵ֥י מִצְרַ֛יִם אֶֽעֱשֶׂ֥ה שְׁפָטִ֖ים אֲנִ֥י יְהוָֽה׃","wĕ⁠ʻábarĕţi֣̇y bĕ⁠ʼeֽreẕ-miẕĕrayim֮ bȧ⁠lȧ֣yĕláh ha⁠zėh֒ wĕ⁠hiké̇yţi֤y kál-bĕ̇kwòr֙ bĕ̇⁠ʼe֣reẕ miẕĕra֔yim mé⁠ʼádá֖m wĕ⁠ʻad-bĕ̇hémá֑h ẇ⁠bĕ⁠kál-ʼèlòhé֥y miẕĕra֛yim ʼeֽʻèşê֥h şĕ̌páti֖ym ʼàni֥y yĕhwáֽh׃"],[12,13,"וְ⁠הָיָה֩ הַ⁠דָּ֨ם לָ⁠כֶ֜ם לְ⁠אֹ֗ת עַ֤ל הַ⁠בָּתִּים֙ אֲשֶׁ֣ר אַתֶּ֣ם שָׁ֔ם וְ⁠רָאִ֨יתִי֙ אֶת־הַ⁠דָּ֔ם וּ⁠פָסַחְתִּ֖י עֲלֵ⁠כֶ֑ם וְ⁠לֹֽא־יִֽהְיֶ֨ה בָ⁠כֶ֥ם נֶ֨גֶף֙ לְ⁠מַשְׁחִ֔ית בְּ⁠הַכֹּתִ֖⁠י בְּ⁠אֶ֥רֶץ מִצְרָֽיִם׃","wĕ⁠háyáh֩ ha⁠dá̇֨m lá⁠ke֜m lĕ⁠ʼò֗ţ ʻa֤l ha⁠bá̇ţi̇ym֙ ʼàşě֣r ʼaţė֣m şá̌֔m wĕ⁠ráʼi֨yţiy֙ ʼeţ-ha⁠dá̇֔m ẇ⁠pásaẖĕţi֖̇y ʻàlé⁠ke֑m wĕ⁠lòֽʼ-yiֽhĕye֨h bá⁠ke֥m ne֨gep֙ lĕ⁠maşĕ̌ẖi֔yţ bĕ̇⁠hakò̇ţi֖⁠y bĕ̇⁠ʼe֥reẕ miẕĕráֽyim׃"],[12,14,"וְ⁠הָיָה֩ הַ⁠יּ֨וֹם הַ⁠זֶּ֤ה לָ⁠כֶם֙ לְ⁠זִכָּר֔וֹן וְ⁠חַגֹּתֶ֥ם אֹת֖⁠וֹ חַ֣ג לַֽ⁠יהוָ֑ה לְ⁠דֹרֹ֣תֵי⁠כֶ֔ם חֻקַּ֥ת עוֹלָ֖ם תְּחָגֻּֽ⁠הוּ׃","wĕ⁠háyáh֩ ha⁠ẏ֨wòm ha⁠zė֤h lá⁠kem֙ lĕ⁠ziká̇r֔wòn wĕ⁠ẖagò̇ţe֥m ʼòţ֖⁠wò ẖa֣g laֽ⁠yhwá֑h lĕ⁠dòrò֣ţéy⁠ke֔m ẖuqȧ֥ţ ʻwòlá֖m ţĕ̇ẖáguֽ̇⁠hẇ׃"],[12,15,"שִׁבְעַ֤ת יָמִים֙ מַצּ֣וֹת תֹּאכֵ֔לוּ אַ֚ךְ בַּ⁠יּ֣וֹם הָ⁠רִאשׁ֔וֹן תַּשְׁבִּ֥יתוּ שְּׂאֹ֖ר מִ⁠בָּתֵּי⁠כֶ֑ם כִּ֣י ׀ כָּל־אֹכֵ֣ל חָמֵ֗ץ וְ⁠נִכְרְתָ֞ה הַ⁠נֶּ֤פֶשׁ הַ⁠הִוא֙ מִ⁠יִּשְׂרָאֵ֔ל מִ⁠יּ֥וֹם הָ⁠רִאשֹׁ֖ן עַד־י֥וֹם הַ⁠שְּׁבִעִֽי׃","şǐbĕʻa֤ţ yámiym֙ maẕ֣̇wòţ ţò̇ʼké֔lẇ ʼa֚kĕ bȧ⁠ẏ֣wòm há⁠riʼş̌֔wòn ţȧşĕ̌bi֥̇yţẇ şĕ̇̂ʼò֖r mi⁠bá̇ţé̇y⁠ke֑m ki֣̇y ׀ ká̇l-ʼòké֣l ẖámé֗ẕ wĕ⁠nikĕrĕţá֞h ha⁠nė֤peş̌ ha⁠hiwʼ֙ mi⁠yi̇şĕ̂ráʼé֔l mi⁠ẏ֥wòm há⁠riʼşò֖̌n ʻad-y֥wòm ha⁠şĕ̇̌biʻiֽy׃"],[12,16,"וּ⁠בַ⁠יּ֤וֹם הָ⁠רִאשׁוֹן֙ מִקְרָא־קֹ֔דֶשׁ וּ⁠בַ⁠יּוֹם֙ הַ⁠שְּׁבִיעִ֔י מִקְרָא־קֹ֖דֶשׁ יִהְיֶ֣ה לָ⁠כֶ֑ם כָּל־מְלָאכָה֙ לֹא־יֵעָשֶׂ֣ה בָ⁠הֶ֔ם אַ֚ךְ אֲשֶׁ֣ר יֵאָכֵ֣ל לְ⁠כָל־נֶ֔פֶשׁ ה֥וּא לְ⁠בַדּ֖⁠וֹ יֵעָשֶׂ֥ה לָ⁠כֶֽם׃","ẇ⁠ba⁠ẏ֤wòm há⁠riʼş̌wòn֙ miqĕráʼ-qò֔deş̌ ẇ⁠ba⁠ẏwòm֙ ha⁠şĕ̇̌biyʻi֔y miqĕráʼ-qò֖deş̌ yihĕye֣h lá⁠ke֑m ká̇l-mĕláʼkáh֙ lòʼ-yéʻáşê֣h bá⁠he֔m ʼa֚kĕ ʼàşě֣r yéʼáké֣l lĕ⁠kál-ne֔peş̌ h֥ẇʼ lĕ⁠baḋ֖⁠wò yéʻáşê֥h lá⁠keֽm׃"],[12,17,"וּ⁠שְׁמַרְתֶּם֮ אֶת־הַ⁠מַּצּוֹת֒ כִּ֗י בְּ⁠עֶ֨צֶם֙ הַ⁠יּ֣וֹם הַ⁠זֶּ֔ה הוֹצֵ֥אתִי אֶת־צִבְאוֹתֵי⁠כֶ֖ם מֵ⁠אֶ֣רֶץ מִצְרָ֑יִם וּ⁠שְׁמַרְתֶּ֞ם אֶת־הַ⁠יּ֥וֹם הַ⁠זֶּ֛ה לְ⁠דֹרֹתֵי⁠כֶ֖ם חֻקַּ֥ת עוֹלָֽם׃","ẇ⁠şĕ̌marĕţėm֮ ʼeţ-ha⁠mȧẕ̇wòţ֒ ki̇֗y bĕ̇⁠ʻe֨ẕem֙ ha⁠ẏ֣wòm ha⁠zė֔h hwòẕé֥ʼţiy ʼeţ-ẕibĕʼwòţéy⁠ke֖m mé⁠ʼe֣reẕ miẕĕrá֑yim ẇ⁠şĕ̌marĕţė֞m ʼeţ-ha⁠ẏ֥wòm ha⁠zė֛h lĕ⁠dòròţéy⁠ke֖m ẖuqȧ֥ţ ʻwòláֽm׃"],[12,18,"בָּ⁠רִאשֹׁ֡ן בְּ⁠אַרְבָּעָה֩ עָשָׂ֨ר י֤וֹם לַ⁠חֹ֨דֶשׁ֙ בָּ⁠עֶ֔רֶב תֹּאכְל֖וּ מַצֹּ֑ת עַ֠ד י֣וֹם הָ⁠אֶחָ֧ד וְ⁠עֶשְׂרִ֛ים לַ⁠חֹ֖דֶשׁ בָּ⁠עָֽרֶב׃","bá̇⁠riʼşò̌֡n bĕ̇⁠ʼarĕbá̇ʻáh֩ ʻáşá̂֨r y֤wòm la⁠ẖò֨deş̌֙ bá̇⁠ʻe֔reb ţò̇ʼkĕl֖ẇ maẕò֑̇ţ ʻa֠d y֣wòm há⁠ʼeẖá֧d wĕ⁠ʻeşĕ̂ri֛ym la⁠ẖò֖deş̌ bá̇⁠ʻáֽreb׃"],[12,19,"שִׁבְעַ֣ת יָמִ֔ים שְׂאֹ֕ר לֹ֥א יִמָּצֵ֖א בְּ⁠בָתֵּי⁠כֶ֑ם כִּ֣י ׀ כָּל־אֹכֵ֣ל מַחְמֶ֗צֶת וְ⁠נִכְרְתָ֞ה הַ⁠נֶּ֤פֶשׁ הַ⁠הִוא֙ מֵ⁠עֲדַ֣ת יִשְׂרָאֵ֔ל בַּ⁠גֵּ֖ר וּ⁠בְ⁠אֶזְרַ֥ח הָ⁠אָֽרֶץ׃","şǐbĕʻa֣ţ yámi֔ym şĕ̂ʼò֕r lò֥ʼ yimá̇ẕé֖ʼ bĕ̇⁠báţé̇y⁠ke֑m ki֣̇y ׀ ká̇l-ʼòké֣l maẖĕme֗ẕeţ wĕ⁠nikĕrĕţá֞h ha⁠nė֤peş̌ ha⁠hiwʼ֙ mé⁠ʻàda֣ţ yişĕ̂ráʼé֔l bȧ⁠gé֖̇r ẇ⁠bĕ⁠ʼezĕra֥ẖ há⁠ʼáֽreẕ׃"],[12,20,"כָּל־מַחְמֶ֖צֶת לֹ֣א תֹאכֵ֑לוּ בְּ⁠כֹל֙ מוֹשְׁבֹ֣תֵי⁠כֶ֔ם תֹּאכְל֖וּ מַצּֽוֹת׃פ","ká̇l-maẖĕme֖ẕeţ lò֣ʼ ţòʼké֑lẇ bĕ̇⁠kòl֙ mwòşĕ̌bò֣ţéy⁠ke֔m ţò̇ʼkĕl֖ẇ maẕֽ̇wòţ׃p"],[12,21,"וַ⁠יִּקְרָ֥א מֹשֶׁ֛ה לְ⁠כָל־זִקְנֵ֥י יִשְׂרָאֵ֖ל וַ⁠יֹּ֣אמֶר אֲלֵ⁠הֶ֑ם מִֽשְׁכ֗וּ וּ⁠קְח֨וּ לָ⁠כֶ֥ם צֹ֛אן לְ⁠מִשְׁפְּחֹתֵי⁠כֶ֖ם וְ⁠שַׁחֲט֥וּ הַ⁠פָּֽסַח׃","wa⁠yi̇qĕrá֥ʼ mòşě֛h lĕ⁠kál-ziqĕné֥y yişĕ̂ráʼé֖l wa⁠yò֣̇ʼmer ʼàlé⁠he֑m miֽşĕ̌k֗ẇ ẇ⁠qĕẖ֨ẇ lá⁠ke֥m ẕò֛ʼn lĕ⁠mişĕ̌pĕ̇ẖòţéy⁠ke֖m wĕ⁠şǎẖàt֥ẇ ha⁠páֽ̇saẖ׃"],[12,22,"וּ⁠לְקַחְתֶּ֞ם אֲגֻדַּ֣ת אֵז֗וֹב וּ⁠טְבַלְתֶּם֮ בַּ⁠דָּ֣ם אֲשֶׁר־בַּ⁠סַּף֒ וְ⁠הִגַּעְתֶּ֤ם אֶל־הַ⁠מַּשְׁקוֹף֙ וְ⁠אֶל־שְׁתֵּ֣י הַ⁠מְּזוּזֹ֔ת מִן־הַ⁠דָּ֖ם אֲשֶׁ֣ר בַּ⁠סָּ֑ף וְ⁠אַתֶּ֗ם לֹ֥א תֵצְא֛וּ אִ֥ישׁ מִ⁠פֶּֽתַח־בֵּית֖⁠וֹ עַד־בֹּֽקֶר׃","ẇ⁠lĕqaẖĕţė֞m ʼàgudȧ֣ţ ʼéz֗wòb ẇ⁠tĕbalĕţėm֮ bȧ⁠dá֣̇m ʼàşěr-bȧ⁠sȧp֒ wĕ⁠higȧʻĕţė֤m ʼel-ha⁠mȧşĕ̌qwòp֙ wĕ⁠ʼel-şĕ̌ţé֣̇y ha⁠mĕ̇zẇzò֔ţ min-ha⁠dá֖̇m ʼàşě֣r bȧ⁠sá֑̇p wĕ⁠ʼaţė֗m lò֥ʼ ţéẕĕʼ֛ẇ ʼi֥yş̌ mi⁠pėֽţaẖ-bé̇yţ֖⁠wò ʻad-bòֽ̇qer׃"],[12,23,"וְ⁠עָבַ֣ר יְהוָה֮ לִ⁠נְגֹּ֣ף אֶת־מִצְרַיִם֒ וְ⁠רָאָ֤ה אֶת־הַ⁠דָּם֙ עַל־הַ⁠מַּשְׁק֔וֹף וְ⁠עַ֖ל שְׁתֵּ֣י הַ⁠מְּזוּזֹ֑ת וּ⁠פָסַ֤ח יְהוָה֙ עַל־הַ⁠פֶּ֔תַח וְ⁠לֹ֤א יִתֵּן֙ הַ⁠מַּשְׁחִ֔ית לָ⁠בֹ֥א אֶל־בָּתֵּי⁠כֶ֖ם לִ⁠נְגֹּֽף׃","wĕ⁠ʻába֣r yĕhwáh֮ li⁠nĕgò֣̇p ʼeţ-miẕĕrayim֒ wĕ⁠ráʼá֤h ʼeţ-ha⁠dá̇m֙ ʻal-ha⁠mȧşĕ̌q֔wòp wĕ⁠ʻa֖l şĕ̌ţé֣̇y ha⁠mĕ̇zẇzò֑ţ ẇ⁠pása֤ẖ yĕhwáh֙ ʻal-ha⁠pė֔ţaẖ wĕ⁠lò֤ʼ yiţé̇n֙ ha⁠mȧşĕ̌ẖi֔yţ lá⁠bò֥ʼ ʼel-bá̇ţé̇y⁠ke֖m li⁠nĕgòֽ̇p׃"],[12,24,"וּ⁠שְׁמַרְתֶּ֖ם אֶת־הַ⁠דָּבָ֣ר הַ⁠זֶּ֑ה לְ⁠חָק־לְ⁠ךָ֥ וּ⁠לְ⁠בָנֶ֖י⁠ךָ עַד־עוֹלָֽם׃","ẇ⁠şĕ̌marĕţė֖m ʼeţ-ha⁠dá̇bá֣r ha⁠zė֑h lĕ⁠ẖáq-lĕ⁠ká֥ ẇ⁠lĕ⁠báne֖y⁠ká ʻad-ʻwòláֽm׃"],[12,25,"וְ⁠הָיָ֞ה כִּֽי־תָבֹ֣אוּ אֶל־הָ⁠אָ֗רֶץ אֲשֶׁ֨ר יִתֵּ֧ן יְהוָ֛ה לָ⁠כֶ֖ם כַּ⁠אֲשֶׁ֣ר דִּבֵּ֑ר וּ⁠שְׁמַרְתֶּ֖ם אֶת־הָ⁠עֲבֹדָ֥ה הַ⁠זֹּֽאת׃","wĕ⁠háyá֞h kiֽ̇y-ţábò֣ʼẇ ʼel-há⁠ʼá֗reẕ ʼàşě֨r yiţé֧̇n yĕhwá֛h lá⁠ke֖m kȧ⁠ʼàşě֣r di̇bé֑̇r ẇ⁠şĕ̌marĕţė֖m ʼeţ-há⁠ʻàbòdá֥h ha⁠zòֽ̇ʼţ׃"],[12,26,"וְ⁠הָיָ֕ה כִּֽי־יֹאמְר֥וּ אֲלֵי⁠כֶ֖ם בְּנֵי⁠כֶ֑ם מָ֛ה הָ⁠עֲבֹדָ֥ה הַ⁠זֹּ֖את לָ⁠כֶֽם׃","wĕ⁠háyá֕h kiֽ̇y-yòʼmĕr֥ẇ ʼàléy⁠ke֖m bĕ̇néy⁠ke֑m má֛h há⁠ʻàbòdá֥h ha⁠zò֖̇ʼţ lá⁠keֽm׃"],[12,27,"וַ⁠אֲמַרְתֶּ֡ם זֶֽבַח־פֶּ֨סַח ה֜וּא לַֽ⁠יהוָ֗ה אֲשֶׁ֣ר פָּ֠סַח עַל־בָּתֵּ֤י בְנֵֽי־יִשְׂרָאֵל֙ בְּ⁠מִצְרַ֔יִם בְּ⁠נָגְפּ֥⁠וֹ אֶת־מִצְרַ֖יִם וְ⁠אֶת־בָּתֵּ֣י⁠נוּ הִצִּ֑יל וַ⁠יִּקֹּ֥ד הָ⁠עָ֖ם וַ⁠יִּֽשְׁתַּחֲוּֽוּ׃","wa⁠ʼàmarĕţė֡m zeֽbaẖ-pė֨saẖ h֜ẇʼ laֽ⁠yhwá֗h ʼàşě֣r pá̇֠saẖ ʻal-bá̇ţé֤̇y bĕnéֽy-yişĕ̂ráʼél֙ bĕ̇⁠miẕĕra֔yim bĕ̇⁠nágĕṗ֥⁠wò ʼeţ-miẕĕra֖yim wĕ⁠ʼeţ-bá̇ţé֣̇y⁠nẇ hiẕi֑̇yl wa⁠yi̇qò֥̇d há⁠ʻá֖m wa⁠yiֽ̇şĕ̌ţȧẖàẇֽẇ׃"],[12,28,"וַ⁠יֵּלְכ֥וּ וַ⁠יַּֽעֲשׂ֖וּ בְּנֵ֣י יִשְׂרָאֵ֑ל כַּ⁠אֲשֶׁ֨ר צִוָּ֧ה יְהוָ֛ה אֶת־מֹשֶׁ֥ה וְ⁠אַהֲרֹ֖ן כֵּ֥ן עָשֽׂוּ׃ס","wa⁠yé̇lĕk֥ẇ wa⁠ẏֽaʻàş֖̂ẇ bĕ̇né֣y yişĕ̂ráʼé֑l kȧ⁠ʼàşě֨r ẕiwá֧̇h yĕhwá֛h ʼeţ-mòşě֥h wĕ⁠ʼahàrò֖n ké֥̇n ʻáşֽ̂ẇ׃s"],[12,29,"וַ⁠יְהִ֣י ׀ בַּ⁠חֲצִ֣י הַ⁠לַּ֗יְלָה וַֽ⁠יהוָה֮ הִכָּ֣ה כָל־בְּכוֹר֮ בְּ⁠אֶ֣רֶץ מִצְרַיִם֒ מִ⁠בְּכֹ֤ר פַּרְעֹה֙ הַ⁠יֹּשֵׁ֣ב עַל־כִּסְא֔⁠וֹ עַ֚ד בְּכ֣וֹר הַ⁠שְּׁבִ֔י אֲשֶׁ֖ר בְּ⁠בֵ֣ית הַ⁠בּ֑וֹר וְ⁠כֹ֖ל בְּכ֥וֹר בְּהֵמָֽה׃","wa⁠yĕhi֣y ׀ bȧ⁠ẖàẕi֣y ha⁠lȧ֗yĕláh waֽ⁠yhwáh֮ hiká֣̇h kál-bĕ̇kwòr֮ bĕ̇⁠ʼe֣reẕ miẕĕrayim֒ mi⁠bĕ̇kò֤r pȧrĕʻòh֙ ha⁠yò̇şé֣̌b ʻal-ki̇sĕʼ֔⁠wò ʻa֚d bĕ̇k֣wòr ha⁠şĕ̇̌bi֔y ʼàşě֖r bĕ̇⁠bé֣yţ ha⁠ḃ֑wòr wĕ⁠kò֖l bĕ̇k֥wòr bĕ̇hémáֽh׃"],[12,30,"וַ⁠יָּ֨קָם פַּרְעֹ֜ה לַ֗יְלָה ה֤וּא וְ⁠כָל־עֲבָדָי⁠ו֙ וְ⁠כָל־מִצְרַ֔יִם וַ⁠תְּהִ֛י צְעָקָ֥ה גְדֹלָ֖ה בְּ⁠מִצְרָ֑יִם כִּֽי־אֵ֣ין בַּ֔יִת אֲשֶׁ֥ר אֵֽין־שָׁ֖ם מֵֽת׃","wa⁠yá̇֨qám pȧrĕʻò֜h la֗yĕláh h֤ẇʼ wĕ⁠kál-ʻàbádáy⁠w֙ wĕ⁠kál-miẕĕra֔yim wa⁠ţĕ̇hi֛y ẕĕʻáqá֥h gĕdòlá֖h bĕ̇⁠miẕĕrá֑yim kiֽ̇y-ʼé֣yn bȧ֔yiţ ʼàşě֥r ʼéֽyn-şá֖̌m méֽţ׃"],[12,31,"וַ⁠יִּקְרָא֩ לְ⁠מֹשֶׁ֨ה וּֽ⁠לְ⁠אַהֲרֹ֜ן לַ֗יְלָה וַ⁠יֹּ֨אמֶר֙ ק֤וּמוּ צְּאוּ֙ מִ⁠תּ֣וֹךְ עַמִּ֔⁠י גַּם־אַתֶּ֖ם גַּם־בְּנֵ֣י יִשְׂרָאֵ֑ל וּ⁠לְכ֛וּ עִבְד֥וּ אֶת־יְהוָ֖ה כְּ⁠דַבֶּרְ⁠כֶֽם׃","wa⁠yi̇qĕráʼ֩ lĕ⁠mòşě֨h ẇֽ⁠lĕ⁠ʼahàrò֜n la֗yĕláh wa⁠yò̇֨ʼmer֙ q֤ẇmẇ ẕĕ̇ʼẇ֙ mi⁠ţ֣̇wòkĕ ʻami̇֔⁠y gȧm-ʼaţė֖m gȧm-bĕ̇né֣y yişĕ̂ráʼé֑l ẇ⁠lĕk֛ẇ ʻibĕd֥ẇ ʼeţ-yĕhwá֖h kĕ̇⁠dabėrĕ⁠keֽm׃"],[12,32,"גַּם־צֹאנְ⁠כֶ֨ם גַּם־בְּקַרְ⁠כֶ֥ם קְח֛וּ כַּ⁠אֲשֶׁ֥ר דִּבַּרְתֶּ֖ם וָ⁠לֵ֑כוּ וּ⁠בֵֽרַכְתֶּ֖ם גַּם־אֹתִֽ⁠י׃","gȧm-ẕòʼnĕ⁠ke֨m gȧm-bĕ̇qarĕ⁠ke֥m qĕẖ֛ẇ kȧ⁠ʼàşě֥r di̇bȧrĕţė֖m wá⁠lé֑kẇ ẇ⁠béֽrakĕţė֖m gȧm-ʼòţiֽ⁠y׃"],[12,33,"וַ⁠תֶּחֱזַ֤ק מִצְרַ֨יִם֙ עַל־הָ⁠עָ֔ם לְ⁠מַהֵ֖ר לְ⁠שַׁלְּחָ֣⁠ם מִן־הָ⁠אָ֑רֶץ כִּ֥י אָמְר֖וּ כֻּלָּ֥⁠נוּ מֵתִֽים׃","wa⁠ţėẖèza֤q miẕĕra֨yim֙ ʻal-há⁠ʻá֔m lĕ⁠mahé֖r lĕ⁠şǎlĕ̇ẖá֣⁠m min-há⁠ʼá֑reẕ ki֥̇y ʼámĕr֖ẇ ku̇lá֥̇⁠nẇ méţiֽym׃"],[12,34,"וַ⁠יִּשָּׂ֥א הָ⁠עָ֛ם אֶת־בְּצֵק֖⁠וֹ טֶ֣רֶם יֶחְמָ֑ץ מִשְׁאֲרֹתָ֛⁠ם צְרֻרֹ֥ת בְּ⁠שִׂמְלֹתָ֖⁠ם עַל־שִׁכְמָֽ⁠ם׃","wa⁠yi̇şá֥̇̂ʼ há⁠ʻá֛m ʼeţ-bĕ̇ẕéq֖⁠wò te֣rem yeẖĕmá֑ẕ mişĕ̌ʼàròţá֛⁠m ẕĕrurò֥ţ bĕ̇⁠şîmĕlòţá֖⁠m ʻal-şǐkĕmáֽ⁠m׃"],[12,35,"וּ⁠בְנֵי־יִשְׂרָאֵ֥ל עָשׂ֖וּ כִּ⁠דְבַ֣ר מֹשֶׁ֑ה וַֽ⁠יִּשְׁאֲלוּ֙ מִ⁠מִּצְרַ֔יִם כְּלֵי־כֶ֛סֶף וּ⁠כְלֵ֥י זָהָ֖ב וּ⁠שְׂמָלֹֽת׃","ẇ⁠bĕnéy-yişĕ̂ráʼé֥l ʻáş֖̂ẇ ki̇⁠dĕba֣r mòşě֑h waֽ⁠yi̇şĕ̌ʼàlẇ֙ mi⁠mi̇ẕĕra֔yim kĕ̇léy-ke֛sep ẇ⁠kĕlé֥y záhá֖b ẇ⁠şĕ̂málòֽţ׃"],[12,36,"וַֽ⁠יהוָ֞ה נָתַ֨ן אֶת־חֵ֥ן הָ⁠עָ֛ם בְּ⁠עֵינֵ֥י מִצְרַ֖יִם וַ⁠יַּשְׁאִל֑וּ⁠ם וַֽ⁠יְנַצְּל֖וּ אֶת־מִצְרָֽיִם׃פ","waֽ⁠yhwá֞h náţa֨n ʼeţ-ẖé֥n há⁠ʻá֛m bĕ̇⁠ʻéyné֥y miẕĕra֖yim wa⁠yȧşĕ̌ʼil֑ẇ⁠m waֽ⁠yĕnaẕĕ̇l֖ẇ ʼeţ-miẕĕráֽyim׃p"],[12,37,"וַ⁠יִּסְע֧וּ בְנֵֽי־יִשְׂרָאֵ֛ל מֵ⁠רַעְמְסֵ֖ס סֻכֹּ֑תָ⁠ה כְּ⁠שֵׁשׁ־מֵא֨וֹת אֶ֧לֶף רַגְלִ֛י הַ⁠גְּבָרִ֖ים לְ⁠בַ֥ד מִ⁠טָּֽף׃","wa⁠yi̇sĕʻ֧ẇ bĕnéֽy-yişĕ̂ráʼé֛l mé⁠raʻĕmĕsé֖s sukò֑̇ţá⁠h kĕ̇⁠şé̌ş̌-méʼ֨wòţ ʼe֧lep ragĕli֛y ha⁠gĕ̇bári֖ym lĕ⁠ba֥d mi⁠táֽ̇p׃"],[12,38,"וְ⁠גַם־עֵ֥רֶב רַ֖ב עָלָ֣ה אִתָּ֑⁠ם וְ⁠צֹ֣אן וּ⁠בָקָ֔ר מִקְנֶ֖ה כָּבֵ֥ד מְאֹֽד׃","wĕ⁠gam-ʻé֥reb ra֖b ʻálá֣h ʼiţá֑̇⁠m wĕ⁠ẕò֣ʼn ẇ⁠báqá֔r miqĕne֖h ká̇bé֥d mĕʼòֽd׃"],[12,39,"וַ⁠יֹּאפ֨וּ אֶת־הַ⁠בָּצֵ֜ק אֲשֶׁ֨ר הוֹצִ֧יאוּ מִ⁠מִּצְרַ֛יִם עֻגֹ֥ת מַצּ֖וֹת כִּ֣י לֹ֣א חָמֵ֑ץ כִּֽי־גֹרְשׁ֣וּ מִ⁠מִּצְרַ֗יִם וְ⁠לֹ֤א יָֽכְלוּ֙ לְ⁠הִתְמַהְמֵ֔הַּ וְ⁠גַם־צֵדָ֖ה לֹא־עָשׂ֥וּ לָ⁠הֶֽם׃","wa⁠yò̇ʼp֨ẇ ʼeţ-ha⁠bá̇ẕé֜q ʼàşě֨r hwòẕi֧yʼẇ mi⁠mi̇ẕĕra֛yim ʻugò֥ţ maẕ֖̇wòţ ki֣̇y lò֣ʼ ẖámé֑ẕ kiֽ̇y-gòrĕş֣̌ẇ mi⁠mi̇ẕĕra֗yim wĕ⁠lò֤ʼ yáֽkĕlẇ֙ lĕ⁠hiţĕmahĕmé֔hȧ wĕ⁠gam-ẕédá֖h lòʼ-ʻáş֥̂ẇ lá⁠heֽm׃"],[12,40,"וּ⁠מוֹשַׁב֙ בְּנֵ֣י יִשְׂרָאֵ֔ל אֲשֶׁ֥ר יָשְׁב֖וּ בְּ⁠מִצְרָ֑יִם שְׁלֹשִׁ֣ים שָׁנָ֔ה וְ⁠אַרְבַּ֥ע מֵא֖וֹת שָׁנָֽה׃","ẇ⁠mwòşǎb֙ bĕ̇né֣y yişĕ̂ráʼé֔l ʼàşě֥r yáşĕ̌b֖ẇ bĕ̇⁠miẕĕrá֑yim şĕ̌lòşǐ֣ym şá̌ná֔h wĕ⁠ʼarĕbȧ֥ʻ méʼ֖wòţ şá̌náֽh׃"],[12,41,"וַ⁠יְהִ֗י מִ⁠קֵּץ֙ שְׁלֹשִׁ֣ים שָׁנָ֔ה וְ⁠אַרְבַּ֥ע מֵא֖וֹת שָׁנָ֑ה וַ⁠יְהִ֗י בְּ⁠עֶ֨צֶם֙ הַ⁠יּ֣וֹם הַ⁠זֶּ֔ה יָֽצְא֛וּ כָּל־צִבְא֥וֹת יְהוָ֖ה מֵ⁠אֶ֥רֶץ מִצְרָֽיִם׃","wa⁠yĕhi֗y mi⁠qé̇ẕ֙ şĕ̌lòşǐ֣ym şá̌ná֔h wĕ⁠ʼarĕbȧ֥ʻ méʼ֖wòţ şá̌ná֑h wa⁠yĕhi֗y bĕ̇⁠ʻe֨ẕem֙ ha⁠ẏ֣wòm ha⁠zė֔h yáֽẕĕʼ֛ẇ ká̇l-ẕibĕʼ֥wòţ yĕhwá֖h mé⁠ʼe֥reẕ miẕĕráֽyim׃"],[12,42,"לֵ֣יל שִׁמֻּרִ֥ים הוּא֙ לַֽ⁠יהוָ֔ה לְ⁠הוֹצִיאָ֖⁠ם מֵ⁠אֶ֣רֶץ מִצְרָ֑יִם הֽוּא־הַ⁠לַּ֤יְלָה הַ⁠זֶּה֙ לַֽ⁠יהוָ֔ה שִׁמֻּרִ֛ים לְ⁠כָל־בְּנֵ֥י יִשְׂרָאֵ֖ל לְ⁠דֹרֹתָֽ⁠ם׃פ","lé֣yl şǐmu̇ri֥ym hẇʼ֙ laֽ⁠yhwá֔h lĕ⁠hwòẕiyʼá֖⁠m mé⁠ʼe֣reẕ miẕĕrá֑yim hֽẇʼ-ha⁠lȧ֤yĕláh ha⁠zėh֙ laֽ⁠yhwá֔h şǐmu̇ri֛ym lĕ⁠kál-bĕ̇né֥y yişĕ̂ráʼé֖l lĕ⁠dòròţáֽ⁠m׃p"],[12,43,"וַ⁠יֹּ֤אמֶר יְהוָה֙ אֶל־מֹשֶׁ֣ה וְ⁠אַהֲרֹ֔ן זֹ֖את חֻקַּ֣ת הַ⁠פָּ֑סַח כָּל־בֶּן־נֵכָ֖ר לֹא־יֹ֥אכַל בּֽ⁠וֹ׃","wa⁠yò֤̇ʼmer yĕhwáh֙ ʼel-mòşě֣h wĕ⁠ʼahàrò֔n zò֖ʼţ ẖuqȧ֣ţ ha⁠pá֑̇saẖ ká̇l-bėn-néká֖r lòʼ-yò֥ʼkal ḃֽ⁠wò׃"],[12,44,"וְ⁠כָל־עֶ֥בֶד אִ֖ישׁ מִקְנַת־כָּ֑סֶף וּ⁠מַלְתָּ֣ה אֹת֔⁠וֹ אָ֖ז יֹ֥אכַל בּֽ⁠וֹ׃","wĕ⁠kál-ʻe֥bed ʼi֖yş̌ miqĕnaţ-ká֑̇sep ẇ⁠malĕţá֣̇h ʼòţ֔⁠wò ʼá֖z yò֥ʼkal ḃֽ⁠wò׃"],[12,45,"תּוֹשָׁ֥ב וְ⁠שָׂכִ֖יר לֹא־יֹ֥אכַל־בּֽ⁠וֹ׃","ţ̇wòşá֥̌b wĕ⁠şá̂ki֖yr lòʼ-yò֥ʼkal-ḃֽ⁠wò׃"],[12,46,"בְּ⁠בַ֤יִת אֶחָד֙ יֵאָכֵ֔ל לֹא־תוֹצִ֧יא מִן־הַ⁠בַּ֛יִת מִן־הַ⁠בָּשָׂ֖ר ח֑וּצָ⁠ה וְ⁠עֶ֖צֶם לֹ֥א תִשְׁבְּרוּ־בֽ⁠וֹ׃","bĕ̇⁠ba֤yiţ ʼeẖád֙ yéʼáké֔l lòʼ-ţwòẕi֧yʼ min-ha⁠bȧ֛yiţ min-ha⁠bá̇şá֖̂r ẖ֑ẇẕá⁠h wĕ⁠ʻe֖ẕem lò֥ʼ ţişĕ̌bĕ̇rẇ-bֽ⁠wò׃"],[12,47,"כָּל־עֲדַ֥ת יִשְׂרָאֵ֖ל יַעֲשׂ֥וּ אֹתֽ⁠וֹ׃","ká̇l-ʻàda֥ţ yişĕ̂ráʼé֖l yaʻàş֥̂ẇ ʼòţֽ⁠wò׃"],[12,48,"וְ⁠כִֽי־יָג֨וּר אִתְּ⁠ךָ֜ גֵּ֗ר וְ⁠עָ֣שָׂה פֶסַח֮ לַ⁠יהוָה֒ הִמּ֧וֹל ל֣⁠וֹ כָל־זָכָ֗ר וְ⁠אָז֙ יִקְרַ֣ב לַ⁠עֲשֹׂת֔⁠וֹ וְ⁠הָיָ֖ה כְּ⁠אֶזְרַ֣ח הָ⁠אָ֑רֶץ וְ⁠כָל־עָרֵ֖ל לֹֽא־יֹ֥אכַל בּֽ⁠וֹ׃","wĕ⁠kiֽy-yág֨ẇr ʼiţĕ̇⁠ká֜ gé̇֗r wĕ⁠ʻá֣şá̂h pesaẖ֮ la⁠yhwáh֒ hiṁ֧wòl l֣⁠wò kál-záká֗r wĕ⁠ʼáz֙ yiqĕra֣b la⁠ʻàşò̂ţ֔⁠wò wĕ⁠háyá֖h kĕ̇⁠ʼezĕra֣ẖ há⁠ʼá֑reẕ wĕ⁠kál-ʻáré֖l lòֽʼ-yò֥ʼkal ḃֽ⁠wò׃"],[12,49,"תּוֹרָ֣ה אַחַ֔ת יִהְיֶ֖ה לָֽ⁠אֶזְרָ֑ח וְ⁠לַ⁠גֵּ֖ר הַ⁠גָּ֥ר בְּ⁠תוֹכְ⁠כֶֽם׃","ţ̇wòrá֣h ʼaẖa֔ţ yihĕye֖h láֽ⁠ʼezĕrá֑ẖ wĕ⁠la⁠gé֖̇r ha⁠gá֥̇r bĕ̇⁠ţwòkĕ⁠keֽm׃"],[12,50,"וַ⁠יַּֽעֲשׂ֖וּ כָּל־בְּנֵ֣י יִשְׂרָאֵ֑ל כַּ⁠אֲשֶׁ֨ר צִוָּ֧ה יְהוָ֛ה אֶת־מֹשֶׁ֥ה וְ⁠אֶֽת־אַהֲרֹ֖ן כֵּ֥ן עָשֽׂוּ׃ס","wa⁠ẏֽaʻàş֖̂ẇ ká̇l-bĕ̇né֣y yişĕ̂ráʼé֑l kȧ⁠ʼàşě֨r ẕiwá֧̇h yĕhwá֛h ʼeţ-mòşě֥h wĕ⁠ʼeֽţ-ʼahàrò֖n ké֥̇n ʻáşֽ̂ẇ׃s"],[12,51,"וַ⁠יְהִ֕י בְּ⁠עֶ֖צֶם הַ⁠יּ֣וֹם הַ⁠זֶּ֑ה הוֹצִ֨יא יְהוָ֜ה אֶת־בְּנֵ֧י יִשְׂרָאֵ֛ל מֵ⁠אֶ֥רֶץ מִצְרַ֖יִם עַל־צִבְאֹתָֽ⁠ם׃פ","wa⁠yĕhi֕y bĕ̇⁠ʻe֖ẕem ha⁠ẏ֣wòm ha⁠zė֑h hwòẕi֨yʼ yĕhwá֜h ʼeţ-bĕ̇né֧y yişĕ̂ráʼé֛l mé⁠ʼe֥reẕ miẕĕra֖yim ʻal-ẕibĕʼòţáֽ⁠m׃p"],[13,1,"וַ⁠יְדַבֵּ֥ר יְהוָ֖ה אֶל־מֹשֶׁ֥ה לֵּ⁠אמֹֽר׃","wa⁠yĕdabé֥̇r yĕhwá֖h ʼel-mòşě֥h lé̇⁠ʼmòֽr׃"],[13,2,"קַדֶּשׁ־לִ֨⁠י כָל־בְּכ֜וֹר פֶּ֤טֶר כָּל־רֶ֨חֶם֙ בִּ⁠בְנֵ֣י יִשְׂרָאֵ֔ל בָּ⁠אָדָ֖ם וּ⁠בַ⁠בְּהֵמָ֑ה לִ֖⁠י הֽוּא׃","qadėş̌-li֨⁠y kál-bĕ̇k֜wòr pė֤ter ká̇l-re֨ẖem֙ bi̇⁠bĕné֣y yişĕ̂ráʼé֔l bá̇⁠ʼádá֖m ẇ⁠ba⁠bĕ̇hémá֑h li֖⁠y hֽẇʼ׃"],[13,3,"וַ⁠יֹּ֨אמֶר מֹשֶׁ֜ה אֶל־הָ⁠עָ֗ם זָכ֞וֹר אֶת־הַ⁠יּ֤וֹם הַ⁠זֶּה֙ אֲשֶׁ֨ר יְצָאתֶ֤ם מִ⁠מִּצְרַ֨יִם֙ מִ⁠בֵּ֣ית עֲבָדִ֔ים כִּ֚י בְּ⁠חֹ֣זֶק יָ֔ד הוֹצִ֧יא יְהֹוָ֛ה אֶתְ⁠כֶ֖ם מִ⁠זֶּ֑ה וְ⁠לֹ֥א יֵאָכֵ֖ל חָמֵֽץ׃","wa⁠yò̇֨ʼmer mòşě֜h ʼel-há⁠ʻá֗m zák֞wòr ʼeţ-ha⁠ẏ֤wòm ha⁠zėh֙ ʼàşě֨r yĕẕáʼţe֤m mi⁠mi̇ẕĕra֨yim֙ mi⁠bé֣̇yţ ʻàbádi֔ym ki֚̇y bĕ̇⁠ẖò֣zeq yá֔d hwòẕi֧yʼ yĕhòwá֛h ʼeţĕ⁠ke֖m mi⁠zė֑h wĕ⁠lò֥ʼ yéʼáké֖l ẖáméֽẕ׃"],[13,4,"הַ⁠יּ֖וֹם אַתֶּ֣ם יֹצְאִ֑ים בְּ⁠חֹ֖דֶשׁ הָ⁠אָבִֽיב׃","ha⁠ẏ֖wòm ʼaţė֣m yòẕĕʼi֑ym bĕ̇⁠ẖò֖deş̌ há⁠ʼábiֽyb׃"],[13,5,"וְ⁠הָיָ֣ה כִֽי־יְבִֽיאֲ⁠ךָ֣ יְהוָ֡ה אֶל־אֶ֣רֶץ הַֽ֠⁠כְּנַעֲנִי וְ⁠הַ⁠חִתִּ֨י וְ⁠הָ⁠אֱמֹרִ֜י וְ⁠הַ⁠חִוִּ֣י וְ⁠הַ⁠יְבוּסִ֗י אֲשֶׁ֨ר נִשְׁבַּ֤ע לַ⁠אֲבֹתֶ֨י⁠ךָ֙ לָ֣⁠תֶת לָ֔⁠ךְ אֶ֛רֶץ זָבַ֥ת חָלָ֖ב וּ⁠דְבָ֑שׁ וְ⁠עָבַדְתָּ֛ אֶת־הָ⁠עֲבֹדָ֥ה הַ⁠זֹּ֖את בַּ⁠חֹ֥דֶשׁ הַ⁠זֶּֽה׃","wĕ⁠háyá֣h kiֽy-yĕbiֽyʼà⁠ká֣ yĕhwá֡h ʼel-ʼe֣reẕ haֽ֠⁠kĕ̇naʻàniy wĕ⁠ha⁠ẖiţi̇֨y wĕ⁠há⁠ʼèmòri֜y wĕ⁠ha⁠ẖiwi֣̇y wĕ⁠ha⁠yĕbẇsi֗y ʼàşě֨r nişĕ̌bȧ֤ʻ la⁠ʼàbòţe֨y⁠ká֙ lá֣⁠ţeţ lá֔⁠kĕ ʼe֛reẕ zába֥ţ ẖálá֖b ẇ⁠dĕbá֑ş̌ wĕ⁠ʻábadĕţá֛̇ ʼeţ-há⁠ʻàbòdá֥h ha⁠zò֖̇ʼţ bȧ⁠ẖò֥deş̌ ha⁠zėֽh׃"],[13,6,"שִׁבְעַ֥ת יָמִ֖ים תֹּאכַ֣ל מַצֹּ֑ת וּ⁠בַ⁠יּוֹם֙ הַ⁠שְּׁבִיעִ֔י חַ֖ג לַ⁠יהוָֽה׃","şǐbĕʻa֥ţ yámi֖ym ţò̇ʼka֣l maẕò֑̇ţ ẇ⁠ba⁠ẏwòm֙ ha⁠şĕ̇̌biyʻi֔y ẖa֖g la⁠yhwáֽh׃"],[13,7,"מַצּוֹת֙ יֵֽאָכֵ֔ל אֵ֖ת שִׁבְעַ֣ת הַ⁠יָּמִ֑ים וְ⁠לֹֽא־יֵרָאֶ֨ה לְ⁠ךָ֜ חָמֵ֗ץ וְ⁠לֹֽא־יֵרָאֶ֥ה לְ⁠ךָ֛ שְׂאֹ֖ר בְּ⁠כָל־גְּבֻלֶֽ⁠ךָ׃","maẕ̇wòţ֙ yéֽʼáké֔l ʼé֖ţ şǐbĕʻa֣ţ ha⁠yá̇mi֑ym wĕ⁠lòֽʼ-yéráʼe֨h lĕ⁠ká֜ ẖámé֗ẕ wĕ⁠lòֽʼ-yéráʼe֥h lĕ⁠ká֛ şĕ̂ʼò֖r bĕ̇⁠kál-gĕ̇buleֽ⁠ká׃"],[13,8,"וְ⁠הִגַּדְתָּ֣ לְ⁠בִנְ⁠ךָ֔ בַּ⁠יּ֥וֹם הַ⁠ה֖וּא לֵ⁠אמֹ֑ר בַּ⁠עֲב֣וּר זֶ֗ה עָשָׂ֤ה יְהוָה֙ לִ֔⁠י בְּ⁠צֵאתִ֖⁠י מִ⁠מִּצְרָֽיִם׃","wĕ⁠higȧdĕţá֣̇ lĕ⁠binĕ⁠ká֔ bȧ⁠ẏ֥wòm ha⁠h֖ẇʼ lé⁠ʼmò֑r bȧ⁠ʻàb֣ẇr ze֗h ʻáşá֤̂h yĕhwáh֙ li֔⁠y bĕ̇⁠ẕéʼţi֖⁠y mi⁠mi̇ẕĕráֽyim׃"],[13,9,"וְ⁠הָיָה֩ לְ⁠ךָ֨ לְ⁠א֜וֹת עַל־יָדְ⁠ךָ֗ וּ⁠לְ⁠זִכָּרוֹן֙ בֵּ֣ין עֵינֶ֔י⁠ךָ לְמַ֗עַן תִּהְיֶ֛ה תּוֹרַ֥ת יְהוָ֖ה בְּ⁠פִ֑י⁠ךָ כִּ֚י בְּ⁠יָ֣ד חֲזָקָ֔ה הוֹצִֽאֲ⁠ךָ֥ יְהֹוָ֖ה מִ⁠מִּצְרָֽיִם׃","wĕ⁠háyáh֩ lĕ⁠ká֨ lĕ⁠ʼ֜wòţ ʻal-yádĕ⁠ká֗ ẇ⁠lĕ⁠ziká̇rwòn֙ bé֣̇yn ʻéyne֔y⁠ká lĕma֗ʻan ţi̇hĕye֛h ţ̇wòra֥ţ yĕhwá֖h bĕ̇⁠pi֑y⁠ká ki֚̇y bĕ̇⁠yá֣d ẖàzáqá֔h hwòẕiֽʼà⁠ká֥ yĕhòwá֖h mi⁠mi̇ẕĕráֽyim׃"],[13,10,"וְ⁠שָׁמַרְתָּ֛ אֶת־הַ⁠חֻקָּ֥ה הַ⁠זֹּ֖את לְ⁠מוֹעֲדָ֑⁠הּ מִ⁠יָּמִ֖ים יָמִֽימָ⁠ה׃ס","wĕ⁠şá̌marĕţá֛̇ ʼeţ-ha⁠ẖuqá֥̇h ha⁠zò֖̇ʼţ lĕ⁠mwòʻàdá֑⁠ḣ mi⁠yá̇mi֖ym yámiֽymá⁠h׃s"],[13,11,"וְ⁠הָיָ֞ה כִּֽי־יְבִֽאֲ⁠ךָ֤ יְהוָה֙ אֶל־אֶ֣רֶץ הַֽ⁠כְּנַעֲנִ֔י כַּ⁠אֲשֶׁ֛ר נִשְׁבַּ֥ע לְ⁠ךָ֖ וְ⁠לַֽ⁠אֲבֹתֶ֑י⁠ךָ וּ⁠נְתָנָ֖⁠הּ לָֽ⁠ךְ׃","wĕ⁠háyá֞h kiֽ̇y-yĕbiֽʼà⁠ká֤ yĕhwáh֙ ʼel-ʼe֣reẕ haֽ⁠kĕ̇naʻàni֔y kȧ⁠ʼàşě֛r nişĕ̌bȧ֥ʻ lĕ⁠ká֖ wĕ⁠laֽ⁠ʼàbòţe֑y⁠ká ẇ⁠nĕţáná֖⁠ḣ láֽ⁠kĕ׃"],[13,12,"וְ⁠הַעֲבַרְתָּ֥ כָל־פֶּֽטֶר־רֶ֖חֶם לַֽ⁠יהֹוָ֑ה וְ⁠כָל־פֶּ֣טֶר ׀ שֶׁ֣גֶר בְּהֵמָ֗ה אֲשֶׁ֨ר יִהְיֶ֥ה לְ⁠ךָ֛ הַ⁠זְּכָרִ֖ים לַ⁠יהוָֽה׃","wĕ⁠haʻàbarĕţá֥̇ kál-pėֽter-re֖ẖem laֽ⁠yhòwá֑h wĕ⁠kál-pė֣ter ׀ şě֣ger bĕ̇hémá֗h ʼàşě֨r yihĕye֥h lĕ⁠ká֛ ha⁠zĕ̇kári֖ym la⁠yhwáֽh׃"],[13,13,"וְ⁠כָל־פֶּ֤טֶר חֲמֹר֙ תִּפְדֶּ֣ה בְ⁠שֶׂ֔ה וְ⁠אִם־לֹ֥א תִפְדֶּ֖ה וַ⁠עֲרַפְתּ֑⁠וֹ וְ⁠כֹ֨ל בְּכ֥וֹר אָדָ֛ם בְּ⁠בָנֶ֖י⁠ךָ תִּפְדֶּֽה׃","wĕ⁠kál-pė֤ter ẖàmòr֙ ţi̇pĕdė֣h bĕ⁠şê֔h wĕ⁠ʼim-lò֥ʼ ţipĕdė֖h wa⁠ʻàrapĕţ֑̇⁠wò wĕ⁠kò֨l bĕ̇k֥wòr ʼádá֛m bĕ̇⁠báne֖y⁠ká ţi̇pĕdėֽh׃"],[13,14,"וְ⁠הָיָ֞ה כִּֽי־יִשְׁאָלְ⁠ךָ֥ בִנְ⁠ךָ֛ מָחָ֖ר לֵ⁠אמֹ֣ר מַה־זֹּ֑את וְ⁠אָמַרְתָּ֣ אֵלָ֔י⁠ו בְּ⁠חֹ֣זֶק יָ֗ד הוֹצִיאָ֧⁠נוּ יְהוָ֛ה מִ⁠מִּצְרַ֖יִם מִ⁠בֵּ֥ית עֲבָדִֽים׃","wĕ⁠háyá֞h kiֽ̇y-yişĕ̌ʼálĕ⁠ká֥ binĕ⁠ká֛ máẖá֖r lé⁠ʼmò֣r mah-zò֑̇ʼţ wĕ⁠ʼámarĕţá֣̇ ʼélá֔y⁠w bĕ̇⁠ẖò֣zeq yá֗d hwòẕiyʼá֧⁠nẇ yĕhwá֛h mi⁠mi̇ẕĕra֖yim mi⁠bé֥̇yţ ʻàbádiֽym׃"],[13,15,"וַ⁠יְהִ֗י כִּֽי־הִקְשָׁ֣ה פַרְעֹה֮ לְ⁠שַׁלְּחֵ⁠נוּ֒ וַ⁠יַּהֲרֹ֨ג יְהֹוָ֤ה כָּל־בְּכוֹר֙ בְּ⁠אֶ֣רֶץ מִצְרַ֔יִם מִ⁠בְּכֹ֥ר אָדָ֖ם וְ⁠עַד־בְּכ֣וֹר בְּהֵמָ֑ה עַל־כֵּן֩ אֲנִ֨י זֹבֵ֜חַ לַֽ⁠יהוָ֗ה כָּל־פֶּ֤טֶר רֶ֨חֶם֙ הַ⁠זְּכָרִ֔ים וְ⁠כָל־בְּכ֥וֹר בָּנַ֖⁠י אֶפְדֶּֽה׃","wa⁠yĕhi֗y kiֽ̇y-hiqĕşá֣̌h parĕʻòh֮ lĕ⁠şǎlĕ̇ẖé⁠nẇ֒ wa⁠yȧhàrò֨g yĕhòwá֤h ká̇l-bĕ̇kwòr֙ bĕ̇⁠ʼe֣reẕ miẕĕra֔yim mi⁠bĕ̇kò֥r ʼádá֖m wĕ⁠ʻad-bĕ̇k֣wòr bĕ̇hémá֑h ʻal-ké̇n֩ ʼàni֨y zòbé֜ẖa laֽ⁠yhwá֗h ká̇l-pė֤ter re֨ẖem֙ ha⁠zĕ̇kári֔ym wĕ⁠kál-bĕ̇k֥wòr bá̇na֖⁠y ʼepĕdėֽh׃"],[13,16,"וְ⁠הָיָ֤ה לְ⁠אוֹת֙ עַל־יָ֣דְ⁠כָ֔ה וּ⁠לְ⁠טוֹטָפֹ֖ת בֵּ֣ין עֵינֶ֑י⁠ךָ כִּ֚י בְּ⁠חֹ֣זֶק יָ֔ד הוֹצִיאָ֥⁠נוּ יְהוָ֖ה מִ⁠מִּצְרָֽיִם׃ס","wĕ⁠háyá֤h lĕ⁠ʼwòţ֙ ʻal-yá֣dĕ⁠ká֔h ẇ⁠lĕ⁠twòtápò֖ţ bé֣̇yn ʻéyne֑y⁠ká ki֚̇y bĕ̇⁠ẖò֣zeq yá֔d hwòẕiyʼá֥⁠nẇ yĕhwá֖h mi⁠mi̇ẕĕráֽyim׃s"],[13,17,"וַ⁠יְהִ֗י בְּ⁠שַׁלַּ֣ח פַּרְעֹה֮ אֶת־הָ⁠עָם֒ וְ⁠לֹא־נָחָ֣⁠ם אֱלֹהִ֗ים דֶּ֚רֶךְ אֶ֣רֶץ פְּלִשְׁתִּ֔ים כִּ֥י קָר֖וֹב ה֑וּא כִּ֣י ׀ אָמַ֣ר אֱלֹהִ֗ים פֶּֽן־יִנָּחֵ֥ם הָ⁠עָ֛ם בִּ⁠רְאֹתָ֥⁠ם מִלְחָמָ֖ה וְ⁠שָׁ֥בוּ מִצְרָֽיְמָ⁠ה׃","wa⁠yĕhi֗y bĕ̇⁠şǎlȧ֣ẖ pȧrĕʻòh֮ ʼeţ-há⁠ʻám֒ wĕ⁠lòʼ-náẖá֣⁠m ʼèlòhi֗ym dė֚rekĕ ʼe֣reẕ pĕ̇lişĕ̌ţi̇֔ym ki֥̇y qár֖wòb h֑ẇʼ ki֣̇y ׀ ʼáma֣r ʼèlòhi֗ym pėֽn-yiná̇ẖé֥m há⁠ʻá֛m bi̇⁠rĕʼòţá֥⁠m milĕẖámá֖h wĕ⁠şá֥̌bẇ miẕĕráֽyĕmá⁠h׃"],[13,18,"וַ⁠יַּסֵּ֨ב אֱלֹהִ֧ים ׀ אֶת־הָ⁠עָ֛ם דֶּ֥רֶךְ הַ⁠מִּדְבָּ֖ר יַם־ס֑וּף וַ⁠חֲמֻשִׁ֛ים עָל֥וּ בְנֵי־יִשְׂרָאֵ֖ל מֵ⁠אֶ֥רֶץ מִצְרָֽיִם׃","wa⁠yȧsé̇֨b ʼèlòhi֧ym ׀ ʼeţ-há⁠ʻá֛m dė֥rekĕ ha⁠mi̇dĕbá֖̇r yam-s֑ẇp wa⁠ẖàmuşǐ֛ym ʻál֥ẇ bĕnéy-yişĕ̂ráʼé֖l mé⁠ʼe֥reẕ miẕĕráֽyim׃"],[13,19,"וַ⁠יִּקַּ֥ח מֹשֶׁ֛ה אֶת־עַצְמ֥וֹת יוֹסֵ֖ף עִמּ֑⁠וֹ כִּי֩ הַשְׁבֵּ֨עַ הִשְׁבִּ֜יעַ אֶת־בְּנֵ֤י יִשְׂרָאֵל֙ לֵ⁠אמֹ֔ר פָּקֹ֨ד יִפְקֹ֤ד אֱלֹהִים֙ אֶתְ⁠כֶ֔ם וְ⁠הַעֲלִיתֶ֧ם אֶת־עַצְמֹתַ֛⁠י מִ⁠זֶּ֖ה אִתְּ⁠כֶֽם׃","wa⁠yi̇qȧ֥ẖ mòşě֛h ʼeţ-ʻaẕĕm֥wòţ ywòsé֖p ʻiṁ֑⁠wò ki̇y֩ haşĕ̌bé̇֨ʻa hişĕ̌bi̇֜yʻa ʼeţ-bĕ̇né֤y yişĕ̂ráʼél֙ lé⁠ʼmò֔r pá̇qò֨d yipĕqò֤d ʼèlòhiym֙ ʼeţĕ⁠ke֔m wĕ⁠haʻàliyţe֧m ʼeţ-ʻaẕĕmòţa֛⁠y mi⁠zė֖h ʼiţĕ̇⁠keֽm׃"],[13,20,"וַ⁠יִּסְע֖וּ מִ⁠סֻּכֹּ֑ת וַ⁠יַּחֲנ֣וּ בְ⁠אֵתָ֔ם בִּ⁠קְצֵ֖ה הַ⁠מִּדְבָּֽר׃","wa⁠yi̇sĕʻ֖ẇ mi⁠su̇kò֑̇ţ wa⁠yȧẖàn֣ẇ bĕ⁠ʼéţá֔m bi̇⁠qĕẕé֖h ha⁠mi̇dĕbáֽ̇r׃"],[13,21,"וַֽ⁠יהוָ֡ה הֹלֵךְ֩ לִ⁠פְנֵי⁠הֶ֨ם יוֹמָ֜ם בְּ⁠עַמּ֤וּד עָנָן֙ לַ⁠נְחֹתָ֣⁠ם הַ⁠דֶּ֔רֶךְ וְ⁠לַ֛יְלָה בְּ⁠עַמּ֥וּד אֵ֖שׁ לְ⁠הָאִ֣יר לָ⁠הֶ֑ם לָ⁠לֶ֖כֶת יוֹמָ֥ם וָ⁠לָֽיְלָה׃","waֽ⁠yhwá֡h hòlékĕ֩ li⁠pĕnéy⁠he֨m ywòmá֜m bĕ̇⁠ʻaṁ֤ẇd ʻánán֙ la⁠nĕẖòţá֣⁠m ha⁠dė֔rekĕ wĕ⁠la֛yĕláh bĕ̇⁠ʻaṁ֥ẇd ʼé֖ş̌ lĕ⁠háʼi֣yr lá⁠he֑m lá⁠le֖keţ ywòmá֥m wá⁠láֽyĕláh׃"],[13,22,"לֹֽא־יָמִ֞ישׁ עַמּ֤וּד הֶֽ⁠עָנָן֙ יוֹמָ֔ם וְ⁠עַמּ֥וּד הָ⁠אֵ֖שׁ לָ֑יְלָה לִ⁠פְנֵ֖י הָ⁠עָֽם׃פ","lòֽʼ-yámi֞yş̌ ʻaṁ֤ẇd heֽ⁠ʻánán֙ ywòmá֔m wĕ⁠ʻaṁ֥ẇd há⁠ʼé֖ş̌ lá֑yĕláh li⁠pĕné֖y há⁠ʻáֽm׃p"],[14,1,"וַ⁠יְדַבֵּ֥ר יְהֹוָ֖ה אֶל־מֹשֶׁ֥ה לֵּ⁠אמֹֽר׃","wa⁠yĕdabé֥̇r yĕhòwá֖h ʼel-mòşě֥h lé̇⁠ʼmòֽr׃"],[14,2,"דַּבֵּר֮ אֶל־בְּנֵ֣י יִשְׂרָאֵל֒ וְ⁠יָשֻׁ֗בוּ וְ⁠יַחֲנוּ֙ לִ⁠פְנֵי֙ פִּ֣י הַחִירֹ֔ת בֵּ֥ין מִגְדֹּ֖ל וּ⁠בֵ֣ין הַ⁠יָּ֑ם לִ⁠פְנֵי֙ בַּ֣עַל צְפֹ֔ן נִכְח֥⁠וֹ תַחֲנ֖וּ עַל־הַ⁠יָּֽם׃","dȧbé̇r֮ ʼel-bĕ̇né֣y yişĕ̂ráʼél֒ wĕ⁠yáşǔ֗bẇ wĕ⁠yaẖànẇ֙ li⁠pĕnéy֙ pi֣̇y haẖiyrò֔ţ bé֥̇yn migĕdò֖̇l ẇ⁠bé֣yn ha⁠yá֑̇m li⁠pĕnéy֙ bȧ֣ʻal ẕĕpò֔n nikĕẖ֥⁠wò ţaẖàn֖ẇ ʻal-ha⁠yáֽ̇m׃"],[14,3,"וְ⁠אָמַ֤ר פַּרְעֹה֙ לִ⁠בְנֵ֣י יִשְׂרָאֵ֔ל נְבֻכִ֥ים הֵ֖ם בָּ⁠אָ֑רֶץ סָגַ֥ר עֲלֵי⁠הֶ֖ם הַ⁠מִּדְבָּֽר׃","wĕ⁠ʼáma֤r pȧrĕʻòh֙ li⁠bĕné֣y yişĕ̂ráʼé֔l nĕbuki֥ym hé֖m bá̇⁠ʼá֑reẕ sága֥r ʻàléy⁠he֖m ha⁠mi̇dĕbáֽ̇r׃"],[14,4,"וְ⁠חִזַּקְתִּ֣י אֶת־לֵב־פַּרְעֹה֮ וְ⁠רָדַ֣ף אַחֲרֵי⁠הֶם֒ וְ⁠אִכָּבְדָ֤ה בְּ⁠פַרְעֹה֙ וּ⁠בְ⁠כָל־חֵיל֔⁠וֹ וְ⁠יָדְע֥וּ מִצְרַ֖יִם כִּֽי־אֲנִ֣י יְהוָ֑ה וַ⁠יַּֽעֲשׂוּ־כֵֽן׃","wĕ⁠ẖizȧqĕţi֣̇y ʼeţ-léb-pȧrĕʻòh֮ wĕ⁠ráda֣p ʼaẖàréy⁠hem֒ wĕ⁠ʼiká̇bĕdá֤h bĕ̇⁠parĕʻòh֙ ẇ⁠bĕ⁠kál-ẖéyl֔⁠wò wĕ⁠yádĕʻ֥ẇ miẕĕra֖yim kiֽ̇y-ʼàni֣y yĕhwá֑h wa⁠ẏֽaʻàş̂ẇ-kéֽn׃"],[14,5,"וַ⁠יֻּגַּד֙ לְ⁠מֶ֣לֶךְ מִצְרַ֔יִם כִּ֥י בָרַ֖ח הָ⁠עָ֑ם וַ֠⁠יֵּהָפֵךְ לְבַ֨ב פַּרְעֹ֤ה וַ⁠עֲבָדָי⁠ו֙ אֶל־הָ⁠עָ֔ם וַ⁠יֹּֽאמרוּ֙ מַה־זֹּ֣את עָשִׂ֔ינוּ כִּֽי־שִׁלַּ֥חְנוּ אֶת־יִשְׂרָאֵ֖ל מֵ⁠עָבְדֵֽ⁠נוּ׃","wa⁠yu̇gȧd֙ lĕ⁠me֣lekĕ miẕĕra֔yim ki֥̇y bára֖ẖ há⁠ʻá֑m wa֠⁠yé̇hápékĕ lĕba֨b pȧrĕʻò֤h wa⁠ʻàbádáy⁠w֙ ʼel-há⁠ʻá֔m wa⁠yòֽ̇ʼmrẇ֙ mah-zò֣̇ʼţ ʻáşî֔ynẇ kiֽ̇y-şǐlȧ֥ẖĕnẇ ʼeţ-yişĕ̂ráʼé֖l mé⁠ʻábĕdéֽ⁠nẇ׃"],[14,6,"וַ⁠יֶּאְסֹ֖ר אֶת־רִכְבּ֑⁠וֹ וְ⁠אֶת־עַמּ֖⁠וֹ לָקַ֥ח עִמּֽ⁠וֹ׃","wa⁠yėʼĕsò֖r ʼeţ-rikĕḃ֑⁠wò wĕ⁠ʼeţ-ʻaṁ֖⁠wò láqa֥ẖ ʻiṁֽ⁠wò׃"],[14,7,"וַ⁠יִּקַּ֗ח שֵׁשׁ־מֵא֥וֹת רֶ֨כֶב֙ בָּח֔וּר וְ⁠כֹ֖ל רֶ֣כֶב מִצְרָ֑יִם וְ⁠שָׁלִשִׁ֖ם עַל־כֻּלּֽ⁠וֹ׃","wa⁠yi̇qȧ֗ẖ şé̌ş̌-méʼ֥wòţ re֨keb֙ bá̇ẖ֔ẇr wĕ⁠kò֖l re֣keb miẕĕrá֑yim wĕ⁠şá̌lişǐ֖m ʻal-ku̇lֽ̇⁠wò׃"],[14,8,"וַ⁠יְחַזֵּ֣ק יְהֹוָ֗ה אֶת־לֵ֤ב פַּרְעֹה֙ מֶ֣לֶךְ מִצְרַ֔יִם וַ⁠יִּרְדֹּ֕ף אַחֲרֵ֖י בְּנֵ֣י יִשְׂרָאֵ֑ל וּ⁠בְנֵ֣י יִשְׂרָאֵ֔ל יֹצְאִ֖ים בְּ⁠יָ֥ד רָמָֽה׃","wa⁠yĕẖazé֣̇q yĕhòwá֗h ʼeţ-lé֤b pȧrĕʻòh֙ me֣lekĕ miẕĕra֔yim wa⁠yi̇rĕdò̇֕p ʼaẖàré֖y bĕ̇né֣y yişĕ̂ráʼé֑l ẇ⁠bĕné֣y yişĕ̂ráʼé֔l yòẕĕʼi֖ym bĕ̇⁠yá֥d rámáֽh׃"],[14,9,"וַ⁠יִּרְדְּפ֨וּ מִצְרַ֜יִם אַחֲרֵי⁠הֶ֗ם וַ⁠יַּשִּׂ֤יגוּ אוֹתָ⁠ם֙ חֹנִ֣ים עַל־הַ⁠יָּ֔ם כָּל־סוּס֙ רֶ֣כֶב פַּרְעֹ֔ה וּ⁠פָרָשָׁ֖י⁠ו וְ⁠חֵיל֑⁠וֹ עַל־פִּי֙ הַֽחִירֹ֔ת לִ⁠פְנֵ֖י בַּ֥עַל צְפֹֽן׃","wa⁠yi̇rĕdĕ̇p֨ẇ miẕĕra֜yim ʼaẖàréy⁠he֗m wa⁠yȧşi֤̇̂ygẇ ʼwòţá⁠m֙ ẖòni֣ym ʻal-ha⁠yá̇֔m ká̇l-sẇs֙ re֣keb pȧrĕʻò֔h ẇ⁠páráşá֖̌y⁠w wĕ⁠ẖéyl֑⁠wò ʻal-pi̇y֙ haֽẖiyrò֔ţ li⁠pĕné֖y bȧ֥ʻal ẕĕpòֽn׃"],[14,10,"וּ⁠פַרְעֹ֖ה הִקְרִ֑יב וַ⁠יִּשְׂאוּ֩ בְנֵֽי־יִשְׂרָאֵ֨ל אֶת־עֵינֵי⁠הֶ֜ם וְ⁠הִנֵּ֥ה מִצְרַ֣יִם ׀ נֹסֵ֣עַ אַחֲרֵי⁠הֶ֗ם וַ⁠יִּֽירְאוּ֙ מְאֹ֔ד וַ⁠יִּצְעֲק֥וּ בְנֵֽי־יִשְׂרָאֵ֖ל אֶל־יְהוָֽה׃","ẇ⁠parĕʻò֖h hiqĕri֑yb wa⁠yi̇şĕ̂ʼẇ֩ bĕnéֽy-yişĕ̂ráʼé֨l ʼeţ-ʻéynéy⁠he֜m wĕ⁠hiné֥̇h miẕĕra֣yim ׀ nòsé֣ʻa ʼaẖàréy⁠he֗m wa⁠yiֽ̇yrĕʼẇ֙ mĕʼò֔d wa⁠yi̇ẕĕʻàq֥ẇ bĕnéֽy-yişĕ̂ráʼé֖l ʼel-yĕhwáֽh׃"],[14,11,"וַ⁠יֹּאמְרוּ֮ אֶל־מֹשֶׁה֒ הַֽ⁠מִ⁠בְּלִ֤י אֵין־קְבָרִים֙ בְּ⁠מִצְרַ֔יִם לְקַחְתָּ֖⁠נוּ לָ⁠מ֣וּת בַּ⁠מִּדְבָּ֑ר מַה־זֹּאת֙ עָשִׂ֣יתָ לָּ֔⁠נוּ לְ⁠הוֹצִיאָ֖⁠נוּ מִ⁠מִּצְרָֽיִם׃","wa⁠yò̇ʼmĕrẇ֮ ʼel-mòşěh֒ haֽ⁠mi⁠bĕ̇li֤y ʼéyn-qĕbáriym֙ bĕ̇⁠miẕĕra֔yim lĕqaẖĕţá֖̇⁠nẇ lá⁠m֣ẇţ bȧ⁠mi̇dĕbá֑̇r mah-zò̇ʼţ֙ ʻáşî֣yţá lá̇֔⁠nẇ lĕ⁠hwòẕiyʼá֖⁠nẇ mi⁠mi̇ẕĕráֽyim׃"],[14,12,"הֲ⁠לֹא־זֶ֣ה הַ⁠דָּבָ֗ר אֲשֶׁר֩ דִּבַּ֨רְנוּ אֵלֶ֤י⁠ךָ בְ⁠מִצְרַ֨יִם֙ לֵ⁠אמֹ֔ר חֲדַ֥ל מִמֶּ֖⁠נּוּ וְ⁠נַֽעַבְדָ֣ה אֶת־מִצְרָ֑יִם כִּ֣י ט֥וֹב לָ֨⁠נוּ֙ עֲבֹ֣ד אֶת־מִצְרַ֔יִם מִ⁠מֻּתֵ֖⁠נוּ בַּ⁠מִּדְבָּֽר׃","hà⁠lòʼ-ze֣h ha⁠dá̇bá֗r ʼàşěr֩ di̇bȧ֨rĕnẇ ʼéle֤y⁠ká bĕ⁠miẕĕra֨yim֙ lé⁠ʼmò֔r ẖàda֥l mimė֖⁠ṅẇ wĕ⁠naֽʻabĕdá֣h ʼeţ-miẕĕrá֑yim ki֣̇y t֥wòb lá֨⁠nẇ֙ ʻàbò֣d ʼeţ-miẕĕra֔yim mi⁠mu̇ţé֖⁠nẇ bȧ⁠mi̇dĕbáֽ̇r׃"],[14,13,"וַ⁠יֹּ֨אמֶר מֹשֶׁ֣ה אֶל־הָ⁠עָם֮ אַל־תִּירָאוּ֒ הִֽתְיַצְב֗וּ וּ⁠רְאוּ֙ אֶת־יְשׁוּעַ֣ת יְהוָ֔ה אֲשֶׁר־יַעֲשֶׂ֥ה לָ⁠כֶ֖ם הַ⁠יּ֑וֹם כִּ֗י אֲשֶׁ֨ר רְאִיתֶ֤ם אֶת־מִצְרַ֨יִם֙ הַ⁠יּ֔וֹם לֹ֥א תֹסִ֛יפוּ לִ⁠רְאֹתָ֥⁠ם ע֖וֹד עַד־עוֹלָֽם׃","wa⁠yò̇֨ʼmer mòşě֣h ʼel-há⁠ʻám֮ ʼal-ţi̇yráʼẇ֒ hiֽţĕyaẕĕb֗ẇ ẇ⁠rĕʼẇ֙ ʼeţ-yĕş̌ẇʻa֣ţ yĕhwá֔h ʼàşěr-yaʻàşê֥h lá⁠ke֖m ha⁠ẏ֑wòm ki̇֗y ʼàşě֨r rĕʼiyţe֤m ʼeţ-miẕĕra֨yim֙ ha⁠ẏ֔wòm lò֥ʼ ţòsi֛ypẇ li⁠rĕʼòţá֥⁠m ʻ֖wòd ʻad-ʻwòláֽm׃"],[14,14,"יְהוָ֖ה יִלָּחֵ֣ם לָ⁠כֶ֑ם וְ⁠אַתֶּ֖ם תַּחֲרִישֽׁוּ⁠ן׃פ","yĕhwá֖h yilá̇ẖé֣m lá⁠ke֑m wĕ⁠ʼaţė֖m ţȧẖàriyşֽ̌ẇ⁠n׃p"],[14,15,"וַ⁠יֹּ֤אמֶר יְהוָה֙ אֶל־מֹשֶׁ֔ה מַה־תִּצְעַ֖ק אֵלָ֑⁠י דַּבֵּ֥ר אֶל־בְּנֵי־יִשְׂרָאֵ֖ל וְ⁠יִסָּֽעוּ׃","wa⁠yò֤̇ʼmer yĕhwáh֙ ʼel-mòşě֔h mah-ţi̇ẕĕʻa֖q ʼélá֑⁠y dȧbé֥̇r ʼel-bĕ̇néy-yişĕ̂ráʼé֖l wĕ⁠yisáֽ̇ʻẇ׃"],[14,16,"וְ⁠אַתָּ֞ה הָרֵ֣ם אֶֽת־מַטְּ⁠ךָ֗ וּ⁠נְטֵ֧ה אֶת־יָדְ⁠ךָ֛ עַל־הַ⁠יָּ֖ם וּ⁠בְקָעֵ֑⁠הוּ וְ⁠יָבֹ֧אוּ בְנֵֽי־יִשְׂרָאֵ֛ל בְּ⁠ת֥וֹךְ הַ⁠יָּ֖ם בַּ⁠יַּבָּשָֽׁה׃","wĕ⁠ʼaţá̇֞h háré֣m ʼeֽţ-matĕ̇⁠ká֗ ẇ⁠nĕté֧h ʼeţ-yádĕ⁠ká֛ ʻal-ha⁠yá֖̇m ẇ⁠bĕqáʻé֑⁠hẇ wĕ⁠yábò֧ʼẇ bĕnéֽy-yişĕ̂ráʼé֛l bĕ̇⁠ţ֥wòkĕ ha⁠yá֖̇m bȧ⁠yȧbá̇şáֽ̌h׃"],[14,17,"וַ⁠אֲנִ֗י הִנְ⁠נִ֤י מְחַזֵּק֙ אֶת־לֵ֣ב מִצְרַ֔יִם וְ⁠יָבֹ֖אוּ אַחֲרֵי⁠הֶ֑ם וְ⁠אִכָּבְדָ֤ה בְּ⁠פַרְעֹה֙ וּ⁠בְ⁠כָל־חֵיל֔⁠וֹ בְּ⁠רִכְבּ֖⁠וֹ וּ⁠בְ⁠פָרָשָֽׁי⁠ו׃","wa⁠ʼàni֗y hinĕ⁠ni֤y mĕẖazé̇q֙ ʼeţ-lé֣b miẕĕra֔yim wĕ⁠yábò֖ʼẇ ʼaẖàréy⁠he֑m wĕ⁠ʼiká̇bĕdá֤h bĕ̇⁠parĕʻòh֙ ẇ⁠bĕ⁠kál-ẖéyl֔⁠wò bĕ̇⁠rikĕḃ֖⁠wò ẇ⁠bĕ⁠páráşáֽ̌y⁠w׃"],[14,18,"וְ⁠יָדְע֥וּ מִצְרַ֖יִם כִּי־אֲנִ֣י יְהוָ֑ה בְּ⁠הִכָּבְדִ֣⁠י בְּ⁠פַרְעֹ֔ה בְּ⁠רִכְבּ֖⁠וֹ וּ⁠בְ⁠פָרָשָֽׁי⁠ו׃","wĕ⁠yádĕʻ֥ẇ miẕĕra֖yim ki̇y-ʼàni֣y yĕhwá֑h bĕ̇⁠hiká̇bĕdi֣⁠y bĕ̇⁠parĕʻò֔h bĕ̇⁠rikĕḃ֖⁠wò ẇ⁠bĕ⁠páráşáֽ̌y⁠w׃"],[14,19,"וַ⁠יִּסַּ֞ע מַלְאַ֣ךְ הָ⁠אֱלֹהִ֗ים הַ⁠הֹלֵךְ֙ לִ⁠פְנֵי֙ מַחֲנֵ֣ה יִשְׂרָאֵ֔ל וַ⁠יֵּ֖לֶךְ מֵ⁠אַחֲרֵי⁠הֶ֑ם וַ⁠יִּסַּ֞ע עַמּ֤וּד הֶֽ⁠עָנָן֙ מִ⁠פְּנֵי⁠הֶ֔ם וַ⁠יַּֽעֲמֹ֖ד מֵ⁠אַחֲרֵי⁠הֶֽם׃","wa⁠yi̇sȧ֞ʻ malĕʼa֣kĕ há⁠ʼèlòhi֗ym ha⁠hòlékĕ֙ li⁠pĕnéy֙ maẖàné֣h yişĕ̂ráʼé֔l wa⁠yé֖̇lekĕ mé⁠ʼaẖàréy⁠he֑m wa⁠yi̇sȧ֞ʻ ʻaṁ֤ẇd heֽ⁠ʻánán֙ mi⁠pĕ̇néy⁠he֔m wa⁠ẏֽaʻàmò֖d mé⁠ʼaẖàréy⁠heֽm׃"],[14,20,"וַ⁠יָּבֹ֞א בֵּ֣ין ׀ מַחֲנֵ֣ה מִצְרַ֗יִם וּ⁠בֵין֙ מַחֲנֵ֣ה יִשְׂרָאֵ֔ל וַ⁠יְהִ֤י הֶֽ⁠עָנָן֙ וְ⁠הַ⁠חֹ֔שֶׁךְ וַ⁠יָּ֖אֶר אֶת־הַ⁠לָּ֑יְלָה וְ⁠לֹא־קָרַ֥ב זֶ֛ה אֶל־זֶ֖ה כָּל־הַ⁠לָּֽיְלָה׃","wa⁠yá̇bò֞ʼ bé֣̇yn ׀ maẖàné֣h miẕĕra֗yim ẇ⁠béyn֙ maẖàné֣h yişĕ̂ráʼé֔l wa⁠yĕhi֤y heֽ⁠ʻánán֙ wĕ⁠ha⁠ẖò֔şěkĕ wa⁠yá֖̇ʼer ʼeţ-ha⁠lá֑̇yĕláh wĕ⁠lòʼ-qára֥b ze֛h ʼel-ze֖h ká̇l-ha⁠láֽ̇yĕláh׃"],[14,21,"וַ⁠יֵּ֨ט מֹשֶׁ֣ה אֶת־יָד⁠וֹ֮ עַל־הַ⁠יָּם֒ וַ⁠יּ֣וֹלֶךְ יְהוָ֣ה ׀ אֶת־הַ֠⁠יָּם בְּ⁠ר֨וּחַ קָדִ֤ים עַזָּה֙ כָּל־הַ⁠לַּ֔יְלָה וַ⁠יָּ֥שֶׂם אֶת־הַ⁠יָּ֖ם לֶ⁠חָרָבָ֑ה וַ⁠יִּבָּקְע֖וּ הַ⁠מָּֽיִם׃","wa⁠yé̇֨t mòşě֣h ʼeţ-yád⁠wò֮ ʻal-ha⁠yá̇m֒ wa⁠ẏ֣wòlekĕ yĕhwá֣h ׀ ʼeţ-ha֠⁠yá̇m bĕ̇⁠r֨ẇẖa qádi֤ym ʻazá̇h֙ ká̇l-ha⁠lȧ֔yĕláh wa⁠yá֥̇şêm ʼeţ-ha⁠yá֖̇m le⁠ẖárábá֑h wa⁠yi̇bá̇qĕʻ֖ẇ ha⁠máֽ̇yim׃"],[14,22,"וַ⁠יָּבֹ֧אוּ בְנֵֽי־יִשְׂרָאֵ֛ל בְּ⁠ת֥וֹךְ הַ⁠יָּ֖ם בַּ⁠יַּבָּשָׁ֑ה וְ⁠הַ⁠מַּ֤יִם לָ⁠הֶם֙ חֹמָ֔ה מִֽ⁠ימִינָ֖⁠ם וּ⁠מִ⁠שְּׂמֹאלָֽ⁠ם׃","wa⁠yá̇bò֧ʼẇ bĕnéֽy-yişĕ̂ráʼé֛l bĕ̇⁠ţ֥wòkĕ ha⁠yá֖̇m bȧ⁠yȧbá̇şá֑̌h wĕ⁠ha⁠mȧ֤yim lá⁠hem֙ ẖòmá֔h miֽ⁠ymiyná֖⁠m ẇ⁠mi⁠şĕ̇̂mòʼláֽ⁠m׃"],[14,23,"וַ⁠יִּרְדְּפ֤וּ מִצְרַ֨יִם֙ וַ⁠יָּבֹ֣אוּ אַחֲרֵי⁠הֶ֔ם כֹּ֚ל ס֣וּס פַּרְעֹ֔ה רִכְבּ֖⁠וֹ וּ⁠פָרָשָׁ֑י⁠ו אֶל־תּ֖וֹךְ הַ⁠יָּֽם׃","wa⁠yi̇rĕdĕ̇p֤ẇ miẕĕra֨yim֙ wa⁠yá̇bò֣ʼẇ ʼaẖàréy⁠he֔m kò֚̇l s֣ẇs pȧrĕʻò֔h rikĕḃ֖⁠wò ẇ⁠páráşá֑̌y⁠w ʼel-ţ֖̇wòkĕ ha⁠yáֽ̇m׃"],[14,24,"וַֽ⁠יְהִי֙ בְּ⁠אַשְׁמֹ֣רֶת הַ⁠בֹּ֔קֶר וַ⁠יַּשְׁקֵ֤ף יְהוָה֙ אֶל־מַחֲנֵ֣ה מִצְרַ֔יִם בְּ⁠עַמּ֥וּד אֵ֖שׁ וְ⁠עָנָ֑ן וַ⁠יָּ֕הָם אֵ֖ת מַחֲנֵ֥ה מִצְרָֽיִם׃","waֽ⁠yĕhiy֙ bĕ̇⁠ʼaşĕ̌mò֣reţ ha⁠bò̇֔qer wa⁠yȧşĕ̌qé֤p yĕhwáh֙ ʼel-maẖàné֣h miẕĕra֔yim bĕ̇⁠ʻaṁ֥ẇd ʼé֖ş̌ wĕ⁠ʻáná֑n wa⁠yá̇֕hám ʼé֖ţ maẖàné֥h miẕĕráֽyim׃"],[14,25,"וַ⁠יָּ֗סַר אֵ֚ת אֹפַ֣ן מַרְכְּבֹתָ֔י⁠ו וַֽ⁠יְנַהֲגֵ֖⁠הוּ בִּ⁠כְבֵדֻ֑ת וַ⁠יֹּ֣אמֶר מִצְרַ֗יִם אָנ֨וּסָה֙ מִ⁠פְּנֵ֣י יִשְׂרָאֵ֔ל כִּ֣י יְהוָ֔ה נִלְחָ֥ם לָ⁠הֶ֖ם בְּ⁠מִצְרָֽיִם פ","wa⁠yá̇֗sar ʼé֚ţ ʼòpa֣n marĕkĕ̇bòţá֔y⁠w waֽ⁠yĕnahàgé֖⁠hẇ bi̇⁠kĕbédu֑ţ wa⁠yò֣̇ʼmer miẕĕra֗yim ʼán֨ẇsáh֙ mi⁠pĕ̇né֣y yişĕ̂ráʼé֔l ki֣̇y yĕhwá֔h nilĕẖá֥m lá⁠he֖m bĕ̇⁠miẕĕráֽyim p"],[14,26,"וַ⁠יֹּ֤אמֶר יְהוָה֙ אֶל־מֹשֶׁ֔ה נְטֵ֥ה אֶת־יָדְ⁠ךָ֖ עַל־הַ⁠יָּ֑ם וְ⁠יָשֻׁ֤בוּ הַ⁠מַּ֨יִם֙ עַל־מִצְרַ֔יִם עַל־רִכְבּ֖⁠וֹ וְ⁠עַל־פָּרָשָֽׁי⁠ו׃","wa⁠yò֤̇ʼmer yĕhwáh֙ ʼel-mòşě֔h nĕté֥h ʼeţ-yádĕ⁠ká֖ ʻal-ha⁠yá֑̇m wĕ⁠yáşǔ֤bẇ ha⁠mȧ֨yim֙ ʻal-miẕĕra֔yim ʻal-rikĕḃ֖⁠wò wĕ⁠ʻal-pá̇ráşáֽ̌y⁠w׃"],[14,27,"וַ⁠יֵּט֩ מֹשֶׁ֨ה אֶת־יָד֜⁠וֹ עַל־הַ⁠יָּ֗ם וַ⁠יָּ֨שָׁב הַ⁠יָּ֜ם לִ⁠פְנ֥וֹת בֹּ֨קֶר֙ לְ⁠אֵ֣יתָנ֔⁠וֹ וּ⁠מִצְרַ֖יִם נָסִ֣ים לִ⁠קְרָאת֑⁠וֹ וַ⁠יְנַעֵ֧ר יְהוָ֛ה אֶת־מִצְרַ֖יִם בְּ⁠ת֥וֹךְ הַ⁠יָּֽם׃","wa⁠yé̇t֩ mòşě֨h ʼeţ-yád֜⁠wò ʻal-ha⁠yá̇֗m wa⁠yá̇֨şá̌b ha⁠yá̇֜m li⁠pĕn֥wòţ bò̇֨qer֙ lĕ⁠ʼé֣yţán֔⁠wò ẇ⁠miẕĕra֖yim nási֣ym li⁠qĕráʼţ֑⁠wò wa⁠yĕnaʻé֧r yĕhwá֛h ʼeţ-miẕĕra֖yim bĕ̇⁠ţ֥wòkĕ ha⁠yáֽ̇m׃"],[14,28,"וַ⁠יָּשֻׁ֣בוּ הַ⁠מַּ֗יִם וַ⁠יְכַסּ֤וּ אֶת־הָ⁠רֶ֨כֶב֙ וְ⁠אֶת־הַ⁠פָּ֣רָשִׁ֔ים לְ⁠כֹל֙ חֵ֣יל פַּרְעֹ֔ה הַ⁠בָּאִ֥ים אַחֲרֵי⁠הֶ֖ם בַּ⁠יָּ֑ם לֹֽא־נִשְׁאַ֥ר בָּ⁠הֶ֖ם עַד־אֶחָֽד׃","wa⁠yá̇şǔ֣bẇ ha⁠mȧ֗yim wa⁠yĕkaṡ֤ẇ ʼeţ-há⁠re֨keb֙ wĕ⁠ʼeţ-ha⁠pá֣̇ráşǐ֔ym lĕ⁠kòl֙ ẖé֣yl pȧrĕʻò֔h ha⁠bá̇ʼi֥ym ʼaẖàréy⁠he֖m bȧ⁠yá֑̇m lòֽʼ-nişĕ̌ʼa֥r bá̇⁠he֖m ʻad-ʼeẖáֽd׃"],[14,29,"וּ⁠בְנֵ֧י יִשְׂרָאֵ֛ל הָלְכ֥וּ בַ⁠יַּבָּשָׁ֖ה בְּ⁠ת֣וֹךְ הַ⁠יָּ֑ם וְ⁠הַ⁠מַּ֤יִם לָ⁠הֶם֙ חֹמָ֔ה מִֽ⁠ימִינָ֖⁠ם וּ⁠מִ⁠שְּׂמֹאלָֽ⁠ם","ẇ⁠bĕné֧y yişĕ̂ráʼé֛l hálĕk֥ẇ ba⁠yȧbá̇şá֖̌h bĕ̇⁠ţ֣wòkĕ ha⁠yá֑̇m wĕ⁠ha⁠mȧ֤yim lá⁠hem֙ ẖòmá֔h miֽ⁠ymiyná֖⁠m ẇ⁠mi⁠şĕ̇̂mòʼláֽ⁠m"],[14,30,"וַ⁠יּ֨וֹשַׁע יְהוָ֜ה בַּ⁠יּ֥וֹם הַ⁠ה֛וּא אֶת־יִשְׂרָאֵ֖ל מִ⁠יַּ֣ד מִצְרָ֑יִם וַ⁠יַּ֤רְא יִשְׂרָאֵל֙ אֶת־מִצְרַ֔יִם מֵ֖ת עַל־שְׂפַ֥ת הַ⁠יָּֽם׃","wa⁠ẏ֨wòşǎʻ yĕhwá֜h bȧ⁠ẏ֥wòm ha⁠h֛ẇʼ ʼeţ-yişĕ̂ráʼé֖l mi⁠yȧ֣d miẕĕrá֑yim wa⁠yȧ֤rĕʼ yişĕ̂ráʼél֙ ʼeţ-miẕĕra֔yim mé֖ţ ʻal-şĕ̂pa֥ţ ha⁠yáֽ̇m׃"],[14,31,"וַ⁠יַּ֨רְא יִשְׂרָאֵ֜ל אֶת־הַ⁠יָּ֣ד הַ⁠גְּדֹלָ֗ה אֲשֶׁ֨ר עָשָׂ֤ה יְהוָה֙ בְּ⁠מִצְרַ֔יִם וַ⁠יִּֽירְא֥וּ הָ⁠עָ֖ם אֶת־יְהוָ֑ה וַ⁠יַּֽאֲמִ֨ינוּ֙ בַּֽ⁠יהוָ֔ה וּ⁠בְ⁠מֹשֶׁ֖ה עַבְדּֽ⁠וֹ׃פ","wa⁠yȧ֨rĕʼ yişĕ̂ráʼé֜l ʼeţ-ha⁠yá֣̇d ha⁠gĕ̇dòlá֗h ʼàşě֨r ʻáşá֤̂h yĕhwáh֙ bĕ̇⁠miẕĕra֔yim wa⁠yiֽ̇yrĕʼ֥ẇ há⁠ʻá֖m ʼeţ-yĕhwá֑h wa⁠ẏֽaʼàmi֨ynẇ֙ bȧֽ⁠yhwá֔h ẇ⁠bĕ⁠mòşě֖h ʻabĕḋֽ⁠wò׃p"],[15,1,"אָ֣ז יָשִֽׁיר־מֹשֶׁה֩ וּ⁠בְנֵ֨י יִשְׂרָאֵ֜ל אֶת־הַ⁠שִּׁירָ֤ה הַ⁠זֹּאת֙ לַֽ⁠יהוָ֔ה וַ⁠יֹּאמְר֖וּ לֵ⁠אמֹ֑ר אָשִׁ֤ירָה לַֽ⁠יהוָה֙ כִּֽי־גָאֹ֣ה גָּאָ֔ה ס֥וּס וְ⁠רֹכְב֖⁠וֹ רָמָ֥ה בַ⁠יָּֽם׃","ʼá֣z yáşǐֽyr-mòşěh֩ ẇ⁠bĕné֨y yişĕ̂ráʼé֜l ʼeţ-ha⁠şi̇̌yrá֤h ha⁠zò̇ʼţ֙ laֽ⁠yhwá֔h wa⁠yò̇ʼmĕr֖ẇ lé⁠ʼmò֑r ʼáşǐ֤yráh lֽa⁠yhwáh֙ kiֽ̇y-gáʼò֣h gá̇ʼá֔h s֥ẇs wĕ⁠ròkĕb֖⁠wò rámá֥h ba⁠yáֽ̇m׃"],[15,2,"עָזִּ֤⁠י וְ⁠זִמְרָת֙ יָ֔הּ וַֽ⁠יְהִי־לִ֖⁠י לִֽ⁠ישׁוּעָ֑ה זֶ֤ה אֵלִ⁠י֙ וְ⁠אַנְוֵ֔⁠הוּ אֱלֹהֵ֥י אָבִ֖⁠י וַ⁠אֲרֹמְמֶֽ⁠נְהוּ׃","ʻázi֤̇⁠y wĕ⁠zimĕráţ֙ yá֔ḣ waֽ⁠yĕhiy-li֖⁠y liֽ⁠yş̌ẇʻá֑h ze֤h ʼéli⁠y֙ wĕ⁠ʼanĕwé֔⁠hẇ ʼèlòhé֥y ʼábi֖⁠y wa⁠ʼàròmĕmeֽ⁠nĕhẇ׃"],[15,3,"יְהוָ֖ה אִ֣ישׁ מִלְחָמָ֑ה יְהוָ֖ה שְׁמֽ⁠וֹ׃","yĕhwá֖h ʼi֣yş̌ milĕẖámá֑h yĕhwá֖h şĕ̌mֽ⁠wò׃"],[15,4,"מַרְכְּבֹ֥ת פַּרְעֹ֛ה וְ⁠חֵיל֖⁠וֹ יָרָ֣ה בַ⁠יָּ֑ם וּ⁠מִבְחַ֥ר שָֽׁלִשָׁ֖י⁠ו טֻבְּע֥וּ בְ⁠יַם־סֽוּף׃","marĕkĕ̇bò֥ţ pȧrĕʻò֛h wĕ⁠ẖéyl֖⁠wò yárá֣h ba⁠yá֑̇m ẇ⁠mibĕẖa֥r şáֽ̌lişá֖̌y⁠w tubĕ̇ʻ֥ẇ bĕ⁠yam-sֽẇp׃"],[15,5,"תְּהֹמֹ֖ת יְכַסְיֻ֑⁠מוּ יָרְד֥וּ בִ⁠מְצוֹלֹ֖ת כְּמוֹ־אָֽבֶן׃","ţĕ̇hòmò֖ţ yĕkasĕyu֑⁠mẇ yárĕd֥ẇ bi⁠mĕẕwòlò֖ţ kĕ̇mwò-ʼáֽben׃"],[15,6,"יְמִֽינְ⁠ךָ֣ יְהוָ֔ה נֶאְדָּרִ֖י בַּ⁠כֹּ֑חַ יְמִֽינְ⁠ךָ֥ יְהוָ֖ה תִּרְעַ֥ץ אוֹיֵֽב׃","yĕmiֽynĕ⁠ká֣ yĕhwá֔h neʼĕdá̇ri֖y bȧ⁠kò֑̇ẖa yĕmiֽynĕ⁠ká֥ yĕhwá֖h ţi̇rĕʻa֥ẕ ʼwòyéֽb׃"],[15,7,"וּ⁠בְ⁠רֹ֥ב גְּאוֹנְ⁠ךָ֖ תַּהֲרֹ֣ס קָמֶ֑י⁠ךָ תְּשַׁלַּח֙ חֲרֹ֣נְ⁠ךָ֔ יֹאכְלֵ֖⁠מוֹ כַּ⁠קַּֽשׁ׃","ẇ⁠bĕ⁠rò֥b gĕ̇ʼwònĕ⁠ká֖ ţȧhàrò֣s qáme֑y⁠ká ţĕ̇şǎlȧẖ֙ ẖàrò֣nĕ⁠ká֔ yòʼkĕlé֖⁠mwò kȧ⁠qȧֽş̌׃"],[15,8,"וּ⁠בְ⁠ר֤וּחַ אַפֶּ֨י⁠ךָ֙ נֶ֣עֶרְמוּ מַ֔יִם נִצְּב֥וּ כְמוֹ־נֵ֖ד נֹזְלִ֑ים קָֽפְא֥וּ תְהֹמֹ֖ת בְּ⁠לֶב־יָֽם׃","ẇ⁠bĕ⁠r֤ẇẖa ʼapė֨y⁠ká֙ ne֣ʻerĕmẇ ma֔yim niẕĕ̇b֥ẇ kĕmwò-né֖d nòzĕli֑ym qáֽpĕʼ֥ẇ ţĕhòmò֖ţ bĕ̇⁠leb-yáֽm׃"],[15,9,"אָמַ֥ר אוֹיֵ֛ב אֶרְדֹּ֥ף אַשִּׂ֖יג אֲחַלֵּ֣ק שָׁלָ֑ל תִּמְלָאֵ֣⁠מוֹ נַפְשִׁ֔⁠י אָרִ֣יק חַרְבִּ֔⁠י תּוֹרִישֵׁ֖⁠מוֹ יָדִֽ⁠י׃","ʼáma֥r ʼwòyé֛b ʼerĕdò֥̇p ʼaşi֖̇̂yg ʼàẖalé֣̇q şá̌lá֑l ţi̇mĕláʼé֣⁠mwò napĕşǐ֔⁠y ʼári֣yq ẖarĕbi̇֔⁠y ţ̇wòriyşé֖̌⁠mwò yádiֽ⁠y׃"],[15,10,"נָשַׁ֥פְתָּ בְ⁠רוּחֲ⁠ךָ֖ כִּסָּ֣⁠מוֹ יָ֑ם צָֽלֲלוּ֙ כַּֽ⁠עוֹפֶ֔רֶת בְּ⁠מַ֖יִם אַדִּירִֽים׃","náşǎ֥pĕţá̇ bĕ⁠rẇẖà⁠ká֖ ki̇sá֣̇⁠mwò yá֑m ẕáֽlàlẇ֙ kȧֽ⁠ʻwòpe֔reţ bĕ̇⁠ma֖yim ʼadi̇yriֽym׃"],[15,11,"מִֽי־כָמֹ֤⁠כָה בָּֽ⁠אֵלִם֙ יְהוָ֔ה מִ֥י כָּמֹ֖⁠כָה נֶאְדָּ֣ר בַּ⁠קֹּ֑דֶשׁ נוֹרָ֥א תְהִלֹּ֖ת עֹ֥שֵׂה פֶֽלֶא׃","miֽy-kámò֤⁠káh báֽ̇⁠ʼélim֙ yĕhwá֔h mi֥y ká̇mò֖⁠káh neʼĕdá֣̇r bȧ⁠qò֑̇deş̌ nwòrá֥ʼ ţĕhilò֖̇ţ ʻò֥şé̂h peֽleʼ׃"],[15,12,"נָטִ֨יתָ֙ יְמִ֣ינְ⁠ךָ֔ תִּבְלָעֵ֖⁠מוֹ אָֽרֶץ׃","náti֨yţá֙ yĕmi֣ynĕ⁠ká֔ ţi̇bĕláʻé֖⁠mwò ʼáֽreẕ׃"],[15,13,"נָחִ֥יתָ בְ⁠חַסְדְּ⁠ךָ֖ עַם־ז֣וּ גָּאָ֑לְתָּ נֵהַ֥לְתָּ בְ⁠עָזְּ⁠ךָ֖ אֶל־נְוֵ֥ה קָדְשֶֽׁ⁠ךָ׃","náẖi֥yţá bĕ⁠ẖasĕdĕ̇⁠ká֖ ʻam-z֣ẇ gá̇ʼá֑lĕţá̇ néha֥lĕţá̇ bĕ⁠ʻázĕ̇⁠ká֖ ʼel-nĕwé֥h qádĕşěֽ⁠ká׃"],[15,14,"שָֽׁמְע֥וּ עַמִּ֖ים יִרְגָּז֑וּ⁠ן חִ֣יל אָחַ֔ז יֹשְׁבֵ֖י פְּלָֽשֶׁת׃","şáֽ̌mĕʻ֥ẇ ʻami֖̇ym yirĕgá̇z֑ẇ⁠n ẖi֣yl ʼáẖa֔z yòşĕ̌bé֖y pĕ̇láֽşěţ׃"],[15,15,"אָ֤ז נִבְהֲלוּ֙ אַלּוּפֵ֣י אֱד֔וֹם אֵילֵ֣י מוֹאָ֔ב יֹֽאחֲזֵ֖⁠מוֹ רָ֑עַד נָמֹ֕גוּ כֹּ֖ל יֹשְׁבֵ֥י כְנָֽעַן׃","ʼá֤z nibĕhàlẇ֙ ʼal̇ẇpé֣y ʼèd֔wòm ʼéylé֣y mwòʼá֔b yòֽʼẖàzé֖⁠mwò rá֑ʻad námò֕gẇ kò֖̇l yòşĕ̌bé֥y kĕnáֽʻan׃"],[15,16,"תִּפֹּ֨ל עֲלֵי⁠הֶ֤ם אֵימָ֨תָ⁠ה֙ וָ⁠פַ֔חַד בִּ⁠גְדֹ֥ל זְרוֹעֲ⁠ךָ֖ יִדְּמ֣וּ כָּ⁠אָ֑בֶן עַד־יַעֲבֹ֤ר עַמְּ⁠ךָ֙ יְהוָ֔ה עַֽד־יַעֲבֹ֖ר עַם־ז֥וּ קָנִֽיתָ׃","ţi̇pò̇֨l ʻàléy⁠he֤m ʼéymá֨ţá⁠h֙ wá⁠pa֔ẖad bi̇⁠gĕdò֥l zĕrwòʻà⁠ká֖ yidĕ̇m֣ẇ ká̇⁠ʼá֑ben ʻad-yaʻàbò֤r ʻamĕ̇⁠ká֙ yĕhwá֔h ʻaֽd-yaʻàbò֖r ʻam-z֥ẇ qániֽyţá׃"],[15,17,"תְּבִאֵ֗⁠מוֹ וְ⁠תִטָּעֵ֨⁠מוֹ֙ בְּ⁠הַ֣ר נַחֲלָֽתְ⁠ךָ֔ מָכ֧וֹן לְ⁠שִׁבְתְּ⁠ךָ֛ פָּעַ֖לְתָּ יְהוָ֑ה מִקְּדָ֕שׁ אֲדֹנָ֖⁠י כּוֹנְנ֥וּ יָדֶֽי⁠ךָ׃","ţĕ̇biʼé֗⁠mwò wĕ⁠ţitá̇ʻé֨⁠mwò֙ bĕ̇⁠ha֣r naẖàláֽţĕ⁠ká֔ mák֧wòn lĕ⁠şǐbĕţĕ̇⁠ká֛ pá̇ʻa֖lĕţá̇ yĕhwá֑h miqĕ̇dá֕ş̌ ʼàdòná֖⁠y k̇wònĕn֥ẇ yádeֽy⁠ká׃"],[15,18,"יְהוָ֥ה ׀ יִמְלֹ֖ךְ לְ⁠עֹלָ֥ם וָ⁠עֶֽד׃","yĕhwá֥h ׀ yimĕlò֖kĕ lĕ⁠ʻòlá֥m wá⁠ʻeֽd׃"],[15,19,"כִּ֣י בָא֩ ס֨וּס פַּרְעֹ֜ה בְּ⁠רִכְבּ֤⁠וֹ וּ⁠בְ⁠פָרָשָׁי⁠ו֙ בַּ⁠יָּ֔ם וַ⁠יָּ֧שֶׁב יְהוָ֛ה עֲלֵ⁠הֶ֖ם אֶת־מֵ֣י הַ⁠יָּ֑ם וּ⁠בְנֵ֧י יִשְׂרָאֵ֛ל הָלְכ֥וּ בַ⁠יַּבָּשָׁ֖ה בְּ⁠ת֥וֹךְ הַ⁠יָּֽם׃פ","ki֣̇y báʼ֩ s֨ẇs pȧrĕʻò֜h bĕ̇⁠rikĕḃ֤⁠wò ẇ⁠bĕ⁠páráşá̌y⁠w֙ bȧ⁠yá̇֔m wa⁠yá֧̇şěb yĕhwá֛h ʻàlé⁠he֖m ʼeţ-mé֣y ha⁠yá֑̇m ẇ⁠bĕné֧y yişĕ̂ráʼé֛l hálĕk֥ẇ ba⁠yȧbá̇şá֖̌h bĕ̇⁠ţ֥wòkĕ ha⁠yáֽ̇m׃p"],[15,20,"וַ⁠תִּקַּח֩ מִרְיָ֨ם הַ⁠נְּבִיאָ֜ה אֲח֧וֹת אַהֲרֹ֛ן אֶת־הַ⁠תֹּ֖ף בְּ⁠יָדָ֑⁠הּ וַ⁠תֵּצֶ֤אןָ כָֽל־הַ⁠נָּשִׁים֙ אַחֲרֶ֔י⁠הָ בְּ⁠תֻפִּ֖ים וּ⁠בִ⁠מְחֹלֹֽת׃","wa⁠ţi̇qȧẖ֩ mirĕyá֨m ha⁠nĕ̇biyʼá֜h ʼàẖ֧wòţ ʼahàrò֛n ʼeţ-ha⁠ţò֖̇p bĕ̇⁠yádá֑⁠ḣ wa⁠ţé̇ẕe֤ʼná káֽl-ha⁠ná̇şǐym֙ ʼaẖàre֔y⁠há bĕ̇⁠ţupi֖̇ym ẇ⁠bi⁠mĕẖòlòֽţ׃"],[15,21,"וַ⁠תַּ֥עַן לָ⁠הֶ֖ם מִרְיָ֑ם שִׁ֤ירוּ לַֽ⁠יהוָה֙ כִּֽי־גָאֹ֣ה גָּאָ֔ה ס֥וּס וְ⁠רֹכְב֖⁠וֹ רָמָ֥ה בַ⁠יָּֽם׃ס","wa⁠ţȧ֥ʻan lá⁠he֖m mirĕyá֑m şǐ֤yrẇ laֽ⁠yhwáh֙ kiֽ̇y-gáʼò֣h gá̇ʼá֔h s֥ẇs wĕ⁠ròkĕb֖⁠wò rámá֥h ba⁠yáֽ̇m׃s"],[15,22,"וַ⁠יַּסַּ֨ע מֹשֶׁ֤ה אֶת־יִשְׂרָאֵל֙ מִ⁠יַּם־ס֔וּף וַ⁠יֵּצְא֖וּ אֶל־מִדְבַּר־שׁ֑וּר וַ⁠יֵּלְכ֧וּ שְׁלֹֽשֶׁת־יָמִ֛ים בַּ⁠מִּדְבָּ֖ר וְ⁠לֹא־מָ֥צְאוּ מָֽיִם׃","wa⁠yȧsȧ֨ʻ mòşě֤h ʼeţ-yişĕ̂ráʼél֙ mi⁠yȧm-s֔ẇp wa⁠yé̇ẕĕʼ֖ẇ ʼel-midĕbȧr-ş֑̌ẇr wa⁠yé̇lĕk֧ẇ şĕ̌lòֽşěţ-yámi֛ym bȧ⁠mi̇dĕbá֖̇r wĕ⁠lòʼ-má֥ẕĕʼẇ máֽyim׃"],[15,23,"וַ⁠יָּבֹ֣אוּ מָרָ֔תָ⁠ה וְ⁠לֹ֣א יָֽכְל֗וּ לִ⁠שְׁתֹּ֥ת מַ֨יִם֙ מִ⁠מָּרָ֔ה כִּ֥י מָרִ֖ים הֵ֑ם עַל־כֵּ֥ן קָרָֽא־שְׁמָ֖⁠הּ מָרָֽה׃","wa⁠yá̇bò֣ʼẇ márá֔ţá⁠h wĕ⁠lò֣ʼ yáֽkĕl֗ẇ li⁠şĕ̌ţò֥̇ţ ma֨yim֙ mi⁠má̇rá֔h ki֥̇y mári֖ym hé֑m ʻal-ké֥̇n qáráֽʼ-şĕ̌má֖⁠ḣ máráֽh׃"],[15,24,"וַ⁠יִּלֹּ֧נוּ הָ⁠עָ֛ם עַל־מֹשֶׁ֥ה לֵּ⁠אמֹ֖ר מַה־נִּשְׁתֶּֽה׃","wa⁠yi̇lò֧̇nẇ há⁠ʻá֛m ʻal-mòşě֥h lé̇⁠ʼmò֖r mah-ni̇şĕ̌ţėֽh׃"],[15,25,"וַ⁠יִּצְעַ֣ק אֶל־יְהוָ֗ה וַ⁠יּוֹרֵ֤⁠הוּ יְהוָה֙ עֵ֔ץ וַ⁠יַּשְׁלֵךְ֙ אֶל־הַ⁠מַּ֔יִם וַֽ⁠יִּמְתְּק֖וּ הַ⁠מָּ֑יִם שָׁ֣ם שָׂ֥ם ל֛⁠וֹ חֹ֥ק וּ⁠מִשְׁפָּ֖ט וְ⁠שָׁ֥ם נִסָּֽ⁠הוּ׃","wa⁠yi̇ẕĕʻa֣q ʼel-yĕhwá֗h wa⁠ẏwòré֤⁠hẇ yĕhwáh֙ ʻé֔ẕ wa⁠yȧşĕ̌lékĕ֙ ʼel-ha⁠mȧ֔yim waֽ⁠yi̇mĕţĕ̇q֖ẇ ha⁠má֑̇yim şá֣̌m şá֥̂m l֛⁠wò ẖò֥q ẇ⁠mişĕ̌pá֖̇t wĕ⁠şá֥̌m nisáֽ̇⁠hẇ׃"],[15,26,"וַ⁠יֹּאמֶר֩ אִם־שָׁמ֨וֹעַ תִּשְׁמַ֜ע לְ⁠ק֣וֹל ׀ יְהוָ֣ה אֱלֹהֶ֗י⁠ךָ וְ⁠הַ⁠יָּשָׁ֤ר בְּ⁠עֵינָי⁠ו֙ תַּעֲשֶׂ֔ה וְ⁠הַֽאֲזַנְתָּ֙ לְ⁠מִצְוֺתָ֔י⁠ו וְ⁠שָׁמַרְתָּ֖ כָּל־חֻקָּ֑י⁠ו כָּֽל־הַ⁠מַּֽחֲלָ֞ה אֲשֶׁר־שַׂ֤מְתִּי בְ⁠מִצְרַ֨יִם֙ לֹא־אָשִׂ֣ים עָלֶ֔י⁠ךָ כִּ֛י אֲנִ֥י יְהוָ֖ה רֹפְאֶֽ⁠ךָ׃ס","wa⁠yò̇ʼmer֩ ʼim-şá̌m֨wòʻa ţi̇şĕ̌ma֜ʻ lĕ⁠q֣wòl ׀ yĕhwá֣h ʼèlòhe֗y⁠ká wĕ⁠ha⁠yá̇şá֤̌r bĕ̇⁠ʻéynáy⁠w֙ ţȧʻàşê֔h wĕ⁠hֽaʼàzanĕţá̇֙ lĕ⁠miẕĕwֺţá֔y⁠w wĕ⁠şá̌marĕţá֖̇ ká̇l-ẖuqá֑̇y⁠w káֽ̇l-ha⁠ṁֽaẖàlá֞h ʼàşěr-şâ֤mĕţi̇y bĕ⁠miẕĕra֨yim֙ lòʼ-ʼáşî֣ym ʻále֔y⁠ká ki֛̇y ʼàni֥y yĕhwá֖h ròpĕʼeֽ⁠ká׃s"],[15,27,"וַ⁠יָּבֹ֣אוּ אֵילִ֔מָ⁠ה וְ⁠שָׁ֗ם שְׁתֵּ֥ים עֶשְׂרֵ֛ה עֵינֹ֥ת מַ֖יִם וְ⁠שִׁבְעִ֣ים תְּמָרִ֑ים וַ⁠יַּחֲנוּ־שָׁ֖ם עַל־הַ⁠מָּֽיִם׃","wa⁠yá̇bò֣ʼẇ ʼéyli֔má⁠h wĕ⁠şá̌֗m şĕ̌ţé֥̇ym ʻeşĕ̂ré֛h ʻéynò֥ţ ma֖yim wĕ⁠şǐbĕʻi֣ym ţĕ̇mári֑ym wa⁠yȧẖànẇ-şá֖̌m ʻal-ha⁠máֽ̇yim׃"],[16,1,"וַ⁠יִּסְעוּ֙ מֵֽ⁠אֵילִ֔ם וַ⁠יָּבֹ֜אוּ כָּל־עֲדַ֤ת בְּנֵֽי־יִשְׂרָאֵל֙ אֶל־מִדְבַּר־סִ֔ין אֲשֶׁ֥ר בֵּין־אֵילִ֖ם וּ⁠בֵ֣ין סִינָ֑י בַּ⁠חֲמִשָּׁ֨ה עָשָׂ֥ר יוֹם֙ לַ⁠חֹ֣דֶשׁ הַ⁠שֵּׁנִ֔י לְ⁠צֵאתָ֖⁠ם מֵ⁠אֶ֥רֶץ מִצְרָֽיִם׃","wa⁠yi̇sĕʻẇ֙ méֽ⁠ʼéyli֔m wa⁠yá̇bò֜ʼẇ ká̇l-ʻàda֤ţ bĕ̇néֽy-yişĕ̂ráʼél֙ ʼel-midĕbȧr-si֔yn ʼàşě֥r bé̇yn-ʼéyli֖m ẇ⁠bé֣yn siyná֑y bȧ⁠ẖàmişá̇̌֨h ʻáşá֥̂r ywòm֙ la⁠ẖò֣deş̌ ha⁠şé̇̌ni֔y lĕ⁠ẕéʼţá֖⁠m mé⁠ʼe֥reẕ miẕĕráֽyim׃"],[16,2,"ו⁠ילינו כָּל־עֲדַ֧ת בְּנֵי־יִשְׂרָאֵ֛ל עַל־מֹשֶׁ֥ה וְ⁠עַֽל־אַהֲרֹ֖ן בַּ⁠מִּדְבָּֽר׃","w⁠ylynw ká̇l-ʻàda֧ţ bĕ̇néy-yişĕ̂ráʼé֛l ʻal-mòşě֥h wĕ⁠ʻaֽl-ʼahàrò֖n bȧ⁠mi̇dĕbáֽ̇r׃"],[16,3,"וַ⁠יֹּאמְר֨וּ אֲלֵ⁠הֶ֜ם בְּנֵ֣י יִשְׂרָאֵ֗ל מִֽי־יִתֵּ֨ן מוּתֵ֤⁠נוּ בְ⁠יַד־יְהוָה֙ בְּ⁠אֶ֣רֶץ מִצְרַ֔יִם בְּ⁠שִׁבְתֵּ֨⁠נוּ֙ עַל־סִ֣יר הַ⁠בָּשָׂ֔ר בְּ⁠אָכְלֵ֥⁠נוּ לֶ֖חֶם לָ⁠שֹׂ֑בַע כִּֽי־הוֹצֵאתֶ֤ם אֹתָ֨⁠נוּ֙ אֶל־הַ⁠מִּדְבָּ֣ר הַ⁠זֶּ֔ה לְ⁠הָמִ֛ית אֶת־כָּל־הַ⁠קָּהָ֥ל הַ⁠זֶּ֖ה בָּ⁠רָעָֽב׃ס","wa⁠yò̇ʼmĕr֨ẇ ʼàlé⁠he֜m bĕ̇né֣y yişĕ̂ráʼé֗l miֽy-yiţé̇֨n mẇţé֤⁠nẇ bĕ⁠yad-yĕhwáh֙ bĕ̇⁠ʼe֣reẕ miẕĕra֔yim bĕ̇⁠şǐbĕţé̇֨⁠nẇ֙ ʻal-si֣yr ha⁠bá̇şá̂֔r bĕ̇⁠ʼákĕlé֥⁠nẇ le֖ẖem lá⁠şò֑̂baʻ kiֽ̇y-hwòẕéʼţe֤m ʼòţá֨⁠nẇ֙ ʼel-ha⁠mi̇dĕbá֣̇r ha⁠zė֔h lĕ⁠hámi֛yţ ʼeţ-ká̇l-ha⁠qá̇há֥l ha⁠zė֖h bá̇⁠ráʻáֽb׃s"],[16,4,"וַ⁠יֹּ֤אמֶר יְהוָה֙ אֶל־מֹשֶׁ֔ה הִנְ⁠נִ֨י מַמְטִ֥יר לָ⁠כֶ֛ם לֶ֖חֶם מִן־הַ⁠שָּׁמָ֑יִם וְ⁠יָצָ֨א הָ⁠עָ֤ם וְ⁠לָֽקְטוּ֙ דְּבַר־י֣וֹם בְּ⁠יוֹמ֔⁠וֹ לְמַ֧עַן אֲנַסֶּ֛⁠נּוּ הֲ⁠יֵלֵ֥ךְ בְּ⁠תוֹרָתִ֖⁠י אִם־לֹֽא׃","wa⁠yò֤̇ʼmer yĕhwáh֙ ʼel-mòşě֔h hinĕ⁠ni֨y mamĕti֥yr lá⁠ke֛m le֖ẖem min-ha⁠şá̇̌má֑yim wĕ⁠yáẕá֨ʼ há⁠ʻá֤m wĕ⁠láֽqĕtẇ֙ dĕ̇bar-y֣wòm bĕ̇⁠ywòm֔⁠wò lĕma֧ʻan ʼànasė֛⁠ṅẇ hà⁠yélé֥kĕ bĕ̇⁠ţwòráţi֖⁠y ʼim-lòֽʼ׃"],[16,5,"וְ⁠הָיָה֙ בַּ⁠יּ֣וֹם הַ⁠שִּׁשִּׁ֔י וְ⁠הֵכִ֖ינוּ אֵ֣ת אֲשֶׁר־יָבִ֑יאוּ וְ⁠הָיָ֣ה מִשְׁנֶ֔ה עַ֥ל אֲשֶֽׁר־יִלְקְט֖וּ י֥וֹם ׀ יֽוֹם׃ס","wĕ⁠háyáh֙ bȧ⁠ẏ֣wòm ha⁠şi̇̌şi̇̌֔y wĕ⁠héki֖ynẇ ʼé֣ţ ʼàşěr-yábi֑yʼẇ wĕ⁠háyá֣h mişĕ̌ne֔h ʻa֥l ʼàşěֽr-yilĕqĕt֖ẇ y֥wòm ׀ yֽwòm׃s"],[16,6,"וַ⁠יֹּ֤אמֶר מֹשֶׁה֙ וְ⁠אַהֲרֹ֔ן אֶֽל־כָּל־בְּנֵ֖י יִשְׂרָאֵ֑ל עֶ֕רֶב וִֽ⁠ידַעְתֶּ֕ם כִּ֧י יְהוָ֛ה הוֹצִ֥יא אֶתְ⁠כֶ֖ם מֵ⁠אֶ֥רֶץ מִצְרָֽיִם׃","wa⁠yò֤̇ʼmer mòşěh֙ wĕ⁠ʼahàrò֔n ʼeֽl-ká̇l-bĕ̇né֖y yişĕ̂ráʼé֑l ʻe֕reb wiֽ⁠ydaʻĕţė֕m ki֧̇y yĕhwá֛h hwòẕi֥yʼ ʼeţĕ⁠ke֖m mé⁠ʼe֥reẕ miẕĕráֽyim׃"],[16,7,"וּ⁠בֹ֗קֶר וּ⁠רְאִיתֶם֙ אֶת־כְּב֣וֹד יְהוָ֔ה בְּ⁠שָׁמְע֥⁠וֹ אֶת־תְּלֻנֹּתֵי⁠כֶ֖ם עַל־יְהוָ֑ה וְ⁠נַ֣חְנוּ מָ֔ה כִּ֥י תלונו עָלֵֽי⁠נוּ׃","ẇ⁠bò֗qer ẇ⁠rĕʼiyţem֙ ʼeţ-kĕ̇b֣wòd yĕhwá֔h bĕ̇⁠şá̌mĕʻ֥⁠wò ʼeţ-ţĕ̇lunò̇ţéy⁠ke֖m ʻal-yĕhwá֑h wĕ⁠na֣ẖĕnẇ má֔h ki֥̇y ţlwnw ʻáléֽy⁠nẇ׃"],[16,8,"וַ⁠יֹּ֣אמֶר מֹשֶׁ֗ה בְּ⁠תֵ֣ת יְהוָה֩ לָ⁠כֶ֨ם בָּ⁠עֶ֜רֶב בָּשָׂ֣ר לֶ⁠אֱכֹ֗ל וְ⁠לֶ֤חֶם בַּ⁠בֹּ֨קֶר֙ לִ⁠שְׂבֹּ֔עַ בִּ⁠שְׁמֹ֤עַ יְהוָה֙ אֶת־תְּלֻנֹּ֣תֵי⁠כֶ֔ם אֲשֶׁר־אַתֶּ֥ם מַלִּינִ֖ם עָלָ֑י⁠ו וְ⁠נַ֣חְנוּ מָ֔ה לֹא־עָלֵ֥י⁠נוּ תְלֻנֹּתֵי⁠כֶ֖ם כִּ֥י עַל־יְהוָֽה׃","wa⁠yò֣̇ʼmer mòşě֗h bĕ̇⁠ţé֣ţ yĕhwáh֩ lá⁠ke֨m bá̇⁠ʻe֜reb bá̇şá֣̂r le⁠ʼèkò֗l wĕ⁠le֤ẖem bȧ⁠bò̇֨qer֙ li⁠şĕ̂bò̇֔ʻa bi̇⁠şĕ̌mò֤ʻa yĕhwáh֙ ʼeţ-ţĕ̇lunò֣̇ţéy⁠ke֔m ʼàşěr-ʼaţė֥m mali̇yni֖m ʻálá֑y⁠w wĕ⁠na֣ẖĕnẇ má֔h lòʼ-ʻálé֥y⁠nẇ ţĕlunò̇ţéy⁠ke֖m ki֥̇y ʻal-yĕhwáֽh׃"],[16,9,"וַ⁠יֹּ֤אמֶר מֹשֶׁה֙ אֶֽל־אַהֲרֹ֔ן אֱמֹ֗ר אֶֽל־כָּל־עֲדַת֙ בְּנֵ֣י יִשְׂרָאֵ֔ל קִרְב֖וּ לִ⁠פְנֵ֣י יְהוָ֑ה כִּ֣י שָׁמַ֔ע אֵ֖ת תְּלֻנֹּתֵי⁠כֶֽם׃","wa⁠yò֤̇ʼmer mòşěh֙ ʼeֽl-ʼahàrò֔n ʼèmò֗r ʼeֽl-ká̇l-ʻàdaţ֙ bĕ̇né֣y yişĕ̂ráʼé֔l qirĕb֖ẇ li⁠pĕné֣y yĕhwá֑h ki֣̇y şá̌ma֔ʻ ʼé֖ţ ţĕ̇lunò̇ţéy⁠keֽm׃"],[16,10,"וַ⁠יְהִ֗י כְּ⁠דַבֵּ֤ר אַהֲרֹן֙ אֶל־כָּל־עֲדַ֣ת בְּנֵֽי־יִשְׂרָאֵ֔ל וַ⁠יִּפְנ֖וּ אֶל־הַ⁠מִּדְבָּ֑ר וְ⁠הִנֵּה֙ כְּב֣וֹד יְהוָ֔ה נִרְאָ֖ה בֶּ⁠עָנָֽן׃פ","wa⁠yĕhi֗y kĕ̇⁠dabé֤̇r ʼahàròn֙ ʼel-ká̇l-ʻàda֣ţ bĕ̇néֽy-yişĕ̂ráʼé֔l wa⁠yi̇pĕn֖ẇ ʼel-ha⁠mi̇dĕbá֑̇r wĕ⁠hiné̇h֙ kĕ̇b֣wòd yĕhwá֔h nirĕʼá֖h bė⁠ʻánáֽn׃p"],[16,11,"וַ⁠יְדַבֵּ֥ר יְהוָ֖ה אֶל־מֹשֶׁ֥ה לֵּ⁠אמֹֽר׃","wa⁠yĕdabé֥̇r yĕhwá֖h ʼel-mòşě֥h lé̇⁠ʼmòֽr׃"],[16,12,"שָׁמַ֗עְתִּי אֶת־תְּלוּנֹּת֮ בְּנֵ֣י יִשְׂרָאֵל֒ דַּבֵּ֨ר אֲלֵ⁠הֶ֜ם לֵ⁠אמֹ֗ר בֵּ֤ין הָֽ⁠עַרְבַּ֨יִם֙ תֹּאכְל֣וּ בָשָׂ֔ר וּ⁠בַ⁠בֹּ֖קֶר תִּשְׂבְּעוּ־לָ֑חֶם וִֽ⁠ידַעְתֶּ֕ם כִּ֛י אֲנִ֥י יְהוָ֖ה אֱלֹהֵי⁠כֶֽם׃","şá̌ma֗ʻĕţi̇y ʼeţ-ţĕ̇lẇnò̇ţ֮ bĕ̇né֣y yişĕ̂ráʼél֒ dȧbé̇֨r ʼàlé⁠he֜m lé⁠ʼmò֗r bé֤̇yn háֽ⁠ʻarĕbȧ֨yim֙ ţò̇ʼkĕl֣ẇ báşá̂֔r ẇ⁠ba⁠bò֖̇qer ţi̇şĕ̂bĕ̇ʻẇ-lá֑ẖem wiֽ⁠ydaʻĕţė֕m ki֛̇y ʼàni֥y yĕhwá֖h ʼèlòhéy⁠keֽm׃"],[16,13,"וַ⁠יְהִ֣י בָ⁠עֶ֔רֶב וַ⁠תַּ֣עַל הַ⁠שְּׂלָ֔ו וַ⁠תְּכַ֖ס אֶת־הַֽ⁠מַּחֲנֶ֑ה וּ⁠בַ⁠בֹּ֗קֶר הָֽיְתָה֙ שִׁכְבַ֣ת הַ⁠טַּ֔ל סָבִ֖יב לַֽ⁠מַּחֲנֶֽה׃","wa⁠yĕhi֣y bá⁠ʻe֔reb wa⁠ţȧ֣ʻal ha⁠şĕ̇̂lá֔w wa⁠ţĕ̇ka֖s ʼeţ-haֽ⁠mȧẖàne֑h ẇ⁠ba⁠bò̇֗qer háֽyĕţáh֙ şǐkĕba֣ţ ha⁠tȧ֔l sábi֖yb laֽ⁠mȧẖàneֽh׃"],[16,14,"וַ⁠תַּ֖עַל שִׁכְבַ֣ת הַ⁠טָּ֑ל וְ⁠הִנֵּ֞ה עַל־פְּנֵ֤י הַ⁠מִּדְבָּר֙ דַּ֣ק מְחֻסְפָּ֔ס דַּ֥ק כַּ⁠כְּפֹ֖ר עַל־הָ⁠אָֽרֶץ׃","wa⁠ţȧ֖ʻal şǐkĕba֣ţ ha⁠tá֑̇l wĕ⁠hiné̇֞h ʻal-pĕ̇né֤y ha⁠mi̇dĕbá̇r֙ dȧ֣q mĕẖusĕpá̇֔s dȧ֥q kȧ⁠kĕ̇pò֖r ʻal-há⁠ʼáֽreẕ׃"],[16,15,"וַ⁠יִּרְא֣וּ בְנֵֽי־יִשְׂרָאֵ֗ל וַ⁠יֹּ֨אמְר֜וּ אִ֤ישׁ אֶל־אָחִי⁠ו֙ מָ֣ן ה֔וּא כִּ֛י לֹ֥א יָדְע֖וּ מַה־ה֑וּא וַ⁠יֹּ֤אמֶר מֹשֶׁה֙ אֲלֵ⁠הֶ֔ם ה֣וּא הַ⁠לֶּ֔חֶם אֲשֶׁ֨ר נָתַ֧ן יְהוָ֛ה לָ⁠כֶ֖ם לְ⁠אָכְלָֽה׃","wa⁠yi̇rĕʼ֣ẇ bĕnéֽy-yişĕ̂ráʼé֗l wa⁠yò̇֨ʼmĕr֜ẇ ʼi֤yş̌ ʼel-ʼáẖiy⁠w֙ má֣n h֔ẇʼ ki֛̇y lò֥ʼ yádĕʻ֖ẇ mah-h֑ẇʼ wa⁠yò֤̇ʼmer mòşěh֙ ʼàlé⁠he֔m h֣ẇʼ ha⁠lė֔ẖem ʼàşě֨r náţa֧n yĕhwá֛h lá⁠ke֖m lĕ⁠ʼákĕláֽh׃"],[16,16,"זֶ֤ה הַ⁠דָּבָר֙ אֲשֶׁ֣ר צִוָּ֣ה יְהוָ֔ה לִקְט֣וּ מִמֶּ֔⁠נּוּ אִ֖ישׁ לְ⁠פִ֣י אָכְל֑⁠וֹ עֹ֣מֶר לַ⁠גֻּלְגֹּ֗לֶת מִסְפַּר֙ נַפְשֹׁ֣תֵי⁠כֶ֔ם אִ֛ישׁ לַ⁠אֲשֶׁ֥ר בְּ⁠אָהֳל֖⁠וֹ תִּקָּֽחוּ׃","ze֤h ha⁠dá̇bár֙ ʼàşě֣r ẕiwá֣̇h yĕhwá֔h liqĕt֣ẇ mimė֔⁠ṅẇ ʼi֖yş̌ lĕ⁠pi֣y ʼákĕl֑⁠wò ʻò֣mer la⁠gu̇lĕgò̇֗leţ misĕpȧr֙ napĕşò֣̌ţéy⁠ke֔m ʼi֛yş̌ la⁠ʼàşě֥r bĕ̇⁠ʼáhol֖⁠wò ţi̇qáֽ̇ẖẇ׃"],[16,17,"וַ⁠יַּעֲשׂוּ־כֵ֖ן בְּנֵ֣י יִשְׂרָאֵ֑ל וַֽ⁠יִּלְקְט֔וּ הַ⁠מַּרְבֶּ֖ה וְ⁠הַ⁠מַּמְעִֽיט׃","wa⁠yȧʻàş̂ẇ-ké֖n bĕ̇né֣y yişĕ̂ráʼé֑l waֽ⁠yi̇lĕqĕt֔ẇ ha⁠mȧrĕbė֖h wĕ⁠ha⁠mȧmĕʻiֽyt׃"],[16,18,"וַ⁠יָּמֹ֣דּוּ בָ⁠עֹ֔מֶר וְ⁠לֹ֤א הֶעְדִּיף֙ הַ⁠מַּרְבֶּ֔ה וְ⁠הַ⁠מַּמְעִ֖יט לֹ֣א הֶחְסִ֑יר אִ֥ישׁ לְ⁠פִֽי־אָכְל֖⁠וֹ לָקָֽטוּ׃","wa⁠yá̇mò֣ḋẇ bá⁠ʻò֔mer wĕ⁠lò֤ʼ heʻĕdi̇yp֙ ha⁠mȧrĕbė֔h wĕ⁠ha⁠mȧmĕʻi֖yt lò֣ʼ heẖĕsi֑yr ʼi֥yş̌ lĕ⁠piֽy-ʼákĕl֖⁠wò láqáֽtẇ׃"],[16,19,"וַ⁠יֹּ֥אמֶר מֹשֶׁ֖ה אֲלֵ⁠הֶ֑ם אִ֕ישׁ אַל־יוֹתֵ֥ר מִמֶּ֖⁠נּוּ עַד־בֹּֽקֶר׃","wa⁠yò֥̇ʼmer mòşě֖h ʼàlé⁠he֑m ʼi֕yş̌ ʼal-ywòţé֥r mimė֖⁠ṅẇ ʻad-bòֽ̇qer׃"],[16,20,"וְ⁠לֹא־שָׁמְע֣וּ אֶל־מֹשֶׁ֗ה וַ⁠יּוֹתִ֨רוּ אֲנָשִׁ֤ים מִמֶּ֨⁠נּוּ֙ עַד־בֹּ֔קֶר וַ⁠יָּ֥רֻם תּוֹלָעִ֖ים וַ⁠יִּבְאַ֑שׁ וַ⁠יִּקְצֹ֥ף עֲלֵ⁠הֶ֖ם מֹשֶֽׁה׃","wĕ⁠lòʼ-şá̌mĕʻ֣ẇ ʼel-mòşě֗h wa⁠ẏwòţi֨rẇ ʼànáşǐ֤ym mimė֨⁠ṅẇ֙ ʻad-bò̇֔qer wa⁠yá֥̇rum ţ̇wòláʻi֖ym wa⁠yi̇bĕʼa֑ş̌ wa⁠yi̇qĕẕò֥p ʻàlé⁠he֖m mòşěֽh׃"],[16,21,"וַ⁠יִּלְקְט֤וּ אֹת⁠וֹ֙ בַּ⁠בֹּ֣קֶר בַּ⁠בֹּ֔קֶר אִ֖ישׁ כְּ⁠פִ֣י אָכְל֑⁠וֹ וְ⁠חַ֥ם הַ⁠שֶּׁ֖מֶשׁ וְ⁠נָמָֽס׃","wa⁠yi̇lĕqĕt֤ẇ ʼòţ⁠wò֙ bȧ⁠bò֣̇qer bȧ⁠bò̇֔qer ʼi֖yş̌ kĕ̇⁠pi֣y ʼákĕl֑⁠wò wĕ⁠ẖa֥m ha⁠şė֖̌meş̌ wĕ⁠námáֽs׃"],[16,22,"וַ⁠יְהִ֣י ׀ בַּ⁠יּ֣וֹם הַ⁠שִּׁשִּׁ֗י לָֽקְט֥וּ לֶ֨חֶם֙ מִשְׁנֶ֔ה שְׁנֵ֥י הָ⁠עֹ֖מֶר לָ⁠אֶחָ֑ד וַ⁠יָּבֹ֨אוּ֙ כָּל־נְשִׂיאֵ֣י הָֽ⁠עֵדָ֔ה וַ⁠יַּגִּ֖ידוּ לְ⁠מֹשֶֽׁה׃","wa⁠yĕhi֣y ׀ bȧ⁠ẏ֣wòm ha⁠şi̇̌şi̇̌֗y láֽqĕt֥ẇ le֨ẖem֙ mişĕ̌ne֔h şĕ̌né֥y há⁠ʻò֖mer lá⁠ʼeẖá֑d wa⁠yá̇bò֨ʼẇ֙ ká̇l-nĕşîyʼé֣y háֽ⁠ʻédá֔h wa⁠yȧgi֖̇ydẇ lĕ⁠mòşěֽh׃"],[16,23,"וַ⁠יֹּ֣אמֶר אֲלֵ⁠הֶ֗ם ה֚וּא אֲשֶׁ֣ר דִּבֶּ֣ר יְהוָ֔ה שַׁבָּת֧וֹן שַׁבַּת־קֹ֛דֶשׁ לַֽ⁠יהוָ֖ה מָחָ֑ר אֵ֣ת אֲשֶׁר־תֹּאפ֞וּ אֵפ֗וּ וְ⁠אֵ֤ת אֲשֶֽׁר־תְּבַשְּׁלוּ֙ בַּשֵּׁ֔לוּ וְ⁠אֵת֙ כָּל־הָ֣⁠עֹדֵ֔ף הַנִּ֧יחוּ לָ⁠כֶ֛ם לְ⁠מִשְׁמֶ֖רֶת עַד־הַ⁠בֹּֽקֶר׃","wa⁠yò֣̇ʼmer ʼàlé⁠he֗m h֚ẇʼ ʼàşě֣r di̇bė֣r yĕhwá֔h şǎbá̇ţ֧wòn şǎbȧţ-qò֛deş̌ laֽ⁠yhwá֖h máẖá֑r ʼé֣ţ ʼàşěr-ţò̇ʼp֞ẇ ʼép֗ẇ wĕ⁠ʼé֤ţ ʼàşěֽr-ţĕ̇başĕ̇̌lẇ֙ bȧşé̇̌֔lẇ wĕ⁠ʼéţ֙ ká̇l-há֣⁠ʻòdé֔p hani֧̇yẖẇ lá⁠ke֛m lĕ⁠mişĕ̌me֖reţ ʻad-ha⁠bòֽ̇qer׃"],[16,24,"וַ⁠יַּנִּ֤יחוּ אֹת⁠וֹ֙ עַד־הַ⁠בֹּ֔קֶר כַּ⁠אֲשֶׁ֖ר צִוָּ֣ה מֹשֶׁ֑ה וְ⁠לֹ֣א הִבְאִ֔ישׁ וְ⁠רִמָּ֖ה לֹא־הָ֥יְתָה בּֽ⁠וֹ׃","wa⁠yȧni֤̇yẖẇ ʼòţ⁠wò֙ ʻad-ha⁠bò̇֔qer kȧ⁠ʼàşě֖r ẕiwá֣̇h mòşě֑h wĕ⁠lò֣ʼ hibĕʼi֔yş̌ wĕ⁠rimá֖̇h lòʼ-há֥yĕţáh ḃֽ⁠wò׃"],[16,25,"וַ⁠יֹּ֤אמֶר מֹשֶׁה֙ אִכְלֻ֣⁠הוּ הַ⁠יּ֔וֹם כִּֽי־שַׁבָּ֥ת הַ⁠יּ֖וֹם לַ⁠יהוָ֑ה הַ⁠יּ֕וֹם לֹ֥א תִמְצָאֻ֖⁠הוּ בַּ⁠שָּׂדֶֽה׃","wa⁠yò֤̇ʼmer mòşěh֙ ʼikĕlu֣⁠hẇ ha⁠ẏ֔wòm kiֽ̇y-şǎbá֥̇ţ ha⁠ẏ֖wòm la⁠yhwá֑h ha⁠ẏ֕wòm lò֥ʼ ţimĕẕáʼu֖⁠hẇ bȧ⁠şá̇̂deֽh׃"],[16,26,"שֵׁ֥שֶׁת יָמִ֖ים תִּלְקְטֻ֑⁠הוּ וּ⁠בַ⁠יּ֧וֹם הַ⁠שְּׁבִיעִ֛י שַׁבָּ֖ת לֹ֥א יִֽהְיֶה־בּֽ⁠וֹ׃","şé֥̌şěţ yámi֖ym ţi̇lĕqĕtu֑⁠hẇ ẇ⁠ba⁠ẏ֧wòm ha⁠şĕ̇̌biyʻi֛y şǎbá֖̇ţ lò֥ʼ yiֽhĕyeh-ḃֽ⁠wò׃"],[16,27,"וַֽ⁠יְהִי֙ בַּ⁠יּ֣וֹם הַ⁠שְּׁבִיעִ֔י יָצְא֥וּ מִן־הָ⁠עָ֖ם לִ⁠לְקֹ֑ט וְ⁠לֹ֖א מָצָֽאוּ׃ס","wֽa⁠yĕhiy֙ bȧ⁠ẏ֣wòm ha⁠şĕ̇̌biyʻi֔y yáẕĕʼ֥ẇ min-há⁠ʻá֖m li⁠lĕqò֑t wĕ⁠lò֖ʼ máẕáֽʼẇ׃s"],[16,28,"וַ⁠יֹּ֥אמֶר יְהוָ֖ה אֶל־מֹשֶׁ֑ה עַד־אָ֨נָה֙ מֵֽאַנְתֶּ֔ם לִ⁠שְׁמֹ֥ר מִצְוֺתַ֖⁠י וְ⁠תוֹרֹתָֽ⁠י׃","wa⁠yò֥̇ʼmer yĕhwá֖h ʼel-mòşě֑h ʻad-ʼá֨náh֙ méֽʼanĕţė֔m li⁠şĕ̌mò֥r miẕĕwֺţa֖⁠y wĕ⁠ţwòròţáֽ⁠y׃"],[16,29,"רְא֗וּ כִּֽי־יְהוָה֮ נָתַ֣ן לָ⁠כֶ֣ם הַ⁠שַּׁבָּת֒ עַל־כֵּ֠ן ה֣וּא נֹתֵ֥ן לָ⁠כֶ֛ם בַּ⁠יּ֥וֹם הַ⁠שִּׁשִּׁ֖י לֶ֣חֶם יוֹמָ֑יִם שְׁב֣וּ ׀ אִ֣ישׁ תַּחְתָּ֗י⁠ו אַל־יֵ֥צֵא אִ֛ישׁ מִ⁠מְּקֹמ֖⁠וֹ בַּ⁠יּ֥וֹם הַ⁠שְּׁבִיעִֽי׃","rĕʼ֗ẇ kiֽ̇y-yĕhwáh֮ náţa֣n lá⁠ke֣m ha⁠şȧ̌bá̇ţ֒ ʻal-ké̇֠n h֣ẇʼ nòţé֥n lá⁠ke֛m bȧ⁠ẏ֥wòm ha⁠şi̇̌şi֖̇̌y le֣ẖem ywòmá֑yim şĕ̌b֣ẇ ׀ ʼi֣yş̌ ţȧẖĕţá̇֗y⁠w ʼal-yé֥ẕéʼ ʼi֛yş̌ mi⁠mĕ̇qòm֖⁠wò bȧ⁠ẏ֥wòm ha⁠şĕ̇̌biyʻiֽy׃"],[16,30,"וַ⁠יִּשְׁבְּת֥וּ הָ⁠עָ֖ם בַּ⁠יּ֥וֹם הַ⁠שְּׁבִעִֽי׃","wa⁠yi̇şĕ̌bĕ̇ţ֥ẇ há⁠ʻá֖m bȧ⁠ẏ֥wòm ha⁠şĕ̇̌biʻiֽy׃"],[16,31,"וַ⁠יִּקְרְא֧וּ בֵֽית־יִשְׂרָאֵ֛ל אֶת־שְׁמ֖⁠וֹ מָ֑ן וְ⁠ה֗וּא כְּ⁠זֶ֤רַע גַּד֙ לָבָ֔ן וְ⁠טַעְמ֖⁠וֹ כְּ⁠צַפִּיחִ֥ת בִּ⁠דְבָֽשׁ׃","wa⁠yi̇qĕrĕʼ֧ẇ béֽyţ-yişĕ̂ráʼé֛l ʼeţ-şĕ̌m֖⁠wò má֑n wĕ⁠h֗ẇʼ kĕ̇⁠ze֤raʻ gȧd֙ lábá֔n wĕ⁠taʻĕm֖⁠wò kĕ̇⁠ẕapi̇yẖi֥ţ bi̇⁠dĕbáֽş̌׃"],[16,32,"וַ⁠יֹּ֣אמֶר מֹשֶׁ֗ה זֶ֤ה הַ⁠דָּבָר֙ אֲשֶׁ֣ר צִוָּ֣ה יְהוָ֔ה מְלֹ֤א הָ⁠עֹ֨מֶר֙ מִמֶּ֔⁠נּוּ לְ⁠מִשְׁמֶ֖רֶת לְ⁠דֹרֹתֵי⁠כֶ֑ם לְמַ֣עַן ׀ יִרְא֣וּ אֶת־הַ⁠לֶּ֗חֶם אֲשֶׁ֨ר הֶאֱכַ֤לְתִּי אֶתְ⁠כֶם֙ בַּ⁠מִּדְבָּ֔ר בְּ⁠הוֹצִיאִ֥⁠י אֶתְ⁠כֶ֖ם מֵ⁠אֶ֥רֶץ מִצְרָֽיִם׃","wa⁠yò֣̇ʼmer mòşě֗h ze֤h ha⁠dá̇bár֙ ʼàşě֣r ẕiwá֣̇h yĕhwá֔h mĕlò֤ʼ há⁠ʻò֨mer֙ mimė֔⁠ṅẇ lĕ⁠mişĕ̌me֖reţ lĕ⁠dòròţéy⁠ke֑m lĕma֣ʻan ׀ yirĕʼ֣ẇ ʼeţ-ha⁠lė֗ẖem ʼàşě֨r heʼèka֤lĕţi̇y ʼeţĕ⁠kem֙ bȧ⁠mi̇dĕbá̇֔r bĕ̇⁠hwòẕiyʼi֥⁠y ʼeţĕ⁠ke֖m mé⁠ʼe֥reẕ miẕĕráֽyim׃"],[16,33,"וַ⁠יֹּ֨אמֶר מֹשֶׁ֜ה אֶֽל־אַהֲרֹ֗ן קַ֚ח צִנְצֶ֣נֶת אַחַ֔ת וְ⁠תֶן־שָׁ֥מָּ⁠ה מְלֹֽא־הָ⁠עֹ֖מֶר מָ֑ן וְ⁠הַנַּ֤ח אֹת⁠וֹ֙ לִ⁠פְנֵ֣י יְהוָ֔ה לְ⁠מִשְׁמֶ֖רֶת לְ⁠דֹרֹתֵי⁠כֶֽם׃","wa⁠yò̇֨ʼmer mòşě֜h ʼeֽl-ʼahàrò֗n qa֚ẖ ẕinĕẕe֣neţ ʼaẖa֔ţ wĕ⁠ţen-şá֥̌má̇⁠h mĕlòֽʼ-há⁠ʻò֖mer má֑n wĕ⁠hanȧ֤ẖ ʼòţ⁠wò֙ li⁠pĕné֣y yĕhwá֔h lĕ⁠mişĕ̌me֖reţ lĕ⁠dòròţéy⁠keֽm׃"],[16,34,"כַּ⁠אֲשֶׁ֛ר צִוָּ֥ה יְהוָ֖ה אֶל־מֹשֶׁ֑ה וַ⁠יַּנִּיחֵ֧⁠הוּ אַהֲרֹ֛ן לִ⁠פְנֵ֥י הָ⁠עֵדֻ֖ת לְ⁠מִשְׁמָֽרֶת׃","kȧ⁠ʼàşě֛r ẕiwá֥̇h yĕhwá֖h ʼel-mòşě֑h wa⁠yȧni̇yẖé֧⁠hẇ ʼahàrò֛n li⁠pĕné֥y há⁠ʻédu֖ţ lĕ⁠mişĕ̌máֽreţ׃"],[16,35,"וּ⁠בְנֵ֣י יִשְׂרָאֵ֗ל אָֽכְל֤וּ אֶת־הַ⁠מָּן֙ אַרְבָּעִ֣ים שָׁנָ֔ה עַד־בֹּאָ֖⁠ם אֶל־אֶ֣רֶץ נוֹשָׁ֑בֶת אֶת־הַ⁠מָּן֙ אָֽכְל֔וּ עַד־בֹּאָ֕⁠ם אֶל־קְצֵ֖ה אֶ֥רֶץ כְּנָֽעַן׃","ẇ⁠bĕné֣y yişĕ̂ráʼé֗l ʼֽákĕl֤ẇ ʼeţ-ha⁠má̇n֙ ʼarĕbá̇ʻi֣ym şá̌ná֔h ʻad-bò̇ʼá֖⁠m ʼel-ʼe֣reẕ nwòşá֑̌beţ ʼeţ-ha⁠má̇n֙ ʼáֽkĕl֔ẇ ʻad-bò̇ʼá֕⁠m ʼel-qĕẕé֖h ʼe֥reẕ kĕ̇náֽʻan׃"],[16,36,"וְ⁠הָ⁠עֹ֕מֶר עֲשִׂרִ֥ית הָ⁠אֵיפָ֖ה הֽוּא׃פ","wĕ⁠há⁠ʻò֕mer ʻàşîri֥yţ há⁠ʼéypá֖h hֽẇʼ׃p"],[17,1,"וַ֠⁠יִּסְעוּ כָּל־עֲדַ֨ת בְּנֵֽי־יִשְׂרָאֵ֧ל מִ⁠מִּדְבַּר־סִ֛ין לְ⁠מַסְעֵי⁠הֶ֖ם עַל־פִּ֣י יְהוָ֑ה וַֽ⁠יַּחֲנוּ֙ בִּ⁠רְפִידִ֔ים וְ⁠אֵ֥ין מַ֖יִם לִ⁠שְׁתֹּ֥ת הָ⁠עָֽם׃","wa֠⁠yi̇sĕʻẇ ká̇l-ʻàda֨ţ bĕ̇néֽy-yişĕ̂ráʼé֧l mi⁠mi̇dĕbȧr-si֛yn lĕ⁠masĕʻéy⁠he֖m ʻal-pi֣̇y yĕhwá֑h waֽ⁠yȧẖànẇ֙ bi̇⁠rĕpiydi֔ym wĕ⁠ʼé֥yn ma֖yim li⁠şĕ̌ţò֥̇ţ há⁠ʻáֽm׃"],[17,2,"וַ⁠יָּ֤רֶב הָ⁠עָם֙ עִם־מֹשֶׁ֔ה וַ⁠יֹּ֣אמְר֔וּ תְּנוּ־לָ֥⁠נוּ מַ֖יִם וְ⁠נִשְׁתֶּ֑ה וַ⁠יֹּ֤אמֶר לָ⁠הֶם֙ מֹשֶׁ֔ה מַה־תְּרִיבוּ⁠ן֙ עִמָּדִ֔⁠י מַה־תְּנַסּ֖וּ⁠ן אֶת־יְהוָֽה׃","wa⁠yá֤̇reb há⁠ʻám֙ ʻim-mòşě֔h wa⁠yò֣̇ʼmĕr֔ẇ ţĕ̇nẇ-lá֥⁠nẇ ma֖yim wĕ⁠nişĕ̌ţė֑h wa⁠yò֤̇ʼmer lá⁠hem֙ mòşě֔h mah-ţĕ̇riybẇ⁠n֙ ʻimá̇di֔⁠y mah-ţĕ̇naṡ֖ẇ⁠n ʼeţ-yĕhwáֽh׃"],[17,3,"וַ⁠יִּצְמָ֨א שָׁ֤ם הָ⁠עָם֙ לַ⁠מַּ֔יִם וַ⁠יָּ֥לֶן הָ⁠עָ֖ם עַל־מֹשֶׁ֑ה וַ⁠יֹּ֗אמֶר לָ֤⁠מָּה זֶּה֙ הֶעֱלִיתָ֣⁠נוּ מִ⁠מִּצְרַ֔יִם לְ⁠הָמִ֥ית אֹתִ֛⁠י וְ⁠אֶת־בָּנַ֥⁠י וְ⁠אֶת־מִקְנַ֖⁠י בַּ⁠צָּמָֽא׃","wa⁠yi̇ẕĕmá֨ʼ şá֤̌m há⁠ʻám֙ la⁠mȧ֔yim wa⁠yá֥̇len há⁠ʻá֖m ʻal-mòşě֑h wa⁠yò̇֗ʼmer lá֤⁠má̇h zėh֙ heʻèliyţá֣⁠nẇ mi⁠mi̇ẕĕra֔yim lĕ⁠hámi֥yţ ʼòţi֛⁠y wĕ⁠ʼeţ-bá̇na֥⁠y wĕ⁠ʼeţ-miqĕna֖⁠y bȧ⁠ẕá̇máֽʼ׃"],[17,4,"וַ⁠יִּצְעַ֤ק מֹשֶׁה֙ אֶל־יְהוָ֣ה לֵ⁠אמֹ֔ר מָ֥ה אֶעֱשֶׂ֖ה לָ⁠עָ֣ם הַ⁠זֶּ֑ה ע֥וֹד מְעַ֖ט וּ⁠סְקָלֻֽ⁠נִי׃","wa⁠yi̇ẕĕʻa֤q mòşěh֙ ʼel-yĕhwá֣h lé⁠ʼmò֔r má֥h ʼeʻèşê֖h lá⁠ʻá֣m ha⁠zė֑h ʻ֥wòd mĕʻa֖t ẇ⁠sĕqáluֽ⁠niy׃"],[17,5,"וַ⁠יֹּ֨אמֶר יְהוָ֜ה אֶל־מֹשֶׁ֗ה עֲבֹר֙ לִ⁠פְנֵ֣י הָ⁠עָ֔ם וְ⁠קַ֥ח אִתְּ⁠ךָ֖ מִ⁠זִּקְנֵ֣י יִשְׂרָאֵ֑ל וּ⁠מַטְּ⁠ךָ֗ אֲשֶׁ֨ר הִכִּ֤יתָ בּ⁠וֹ֙ אֶת־הַ⁠יְאֹ֔ר קַ֥ח בְּ⁠יָדְ⁠ךָ֖ וְ⁠הָלָֽכְתָּ׃","wa⁠yò̇֨ʼmer yĕhwá֜h ʼel-mòşě֗h ʻàbòr֙ li⁠pĕné֣y há⁠ʻá֔m wĕ⁠qa֥ẖ ʼiţĕ̇⁠ká֖ mi⁠zi̇qĕné֣y yişĕ̂ráʼé֑l ẇ⁠matĕ̇⁠ká֗ ʼàşě֨r hiki֤̇yţá ḃ⁠wò֙ ʼeţ-ha⁠yĕʼò֔r qa֥ẖ bĕ̇⁠yádĕ⁠ká֖ wĕ⁠háláֽkĕţá̇׃"],[17,6,"הִנְ⁠נִ֣י עֹמֵד֩ לְ⁠פָנֶ֨י⁠ךָ שָּׁ֥ם ׀ עַֽל־הַ⁠צּוּר֮ בְּ⁠חֹרֵב֒ וְ⁠הִכִּ֣יתָ בַ⁠צּ֗וּר וְ⁠יָצְא֥וּ מִמֶּ֛⁠נּוּ מַ֖יִם וְ⁠שָׁתָ֣ה הָ⁠עָ֑ם וַ⁠יַּ֤עַשׂ כֵּן֙ מֹשֶׁ֔ה לְ⁠עֵינֵ֖י זִקְנֵ֥י יִשְׂרָאֵֽל׃","hinĕ⁠ni֣y ʻòméd֩ lĕ⁠páne֨y⁠ká şá֥̇̌m ׀ ʻaֽl-ha⁠ẕ̇ẇr֮ bĕ̇⁠ẖòréb֒ wĕ⁠hiki֣̇yţá ba⁠ẕ̇֗ẇr wĕ⁠yáẕĕʼ֥ẇ mimė֛⁠ṅẇ ma֖yim wĕ⁠şá̌ţá֣h há⁠ʻá֑m wa⁠yȧ֤ʻaş̂ ké̇n֙ mòşě֔h lĕ⁠ʻéyné֖y ziqĕné֥y yişĕ̂ráʼéֽl׃"],[17,7,"וַ⁠יִּקְרָא֙ שֵׁ֣ם הַ⁠מָּק֔וֹם מַסָּ֖ה וּ⁠מְרִיבָ֑ה עַל־רִ֣יב ׀ בְּנֵ֣י יִשְׂרָאֵ֗ל וְ⁠עַ֨ל נַסֹּתָ֤⁠ם אֶת־יְהוָה֙ לֵ⁠אמֹ֔ר הֲ⁠יֵ֧שׁ יְהוָ֛ה בְּ⁠קִרְבֵּ֖⁠נוּ אִם־אָֽיִן׃פ","wa⁠yi̇qĕráʼ֙ şé֣̌m ha⁠má̇q֔wòm masá֖̇h ẇ⁠mĕriybá֑h ʻal-ri֣yb ׀ bĕ̇né֣y yişĕ̂ráʼé֗l wĕ⁠ʻa֨l nasò̇ţá֤⁠m ʼeţ-yĕhwáh֙ lé⁠ʼmò֔r hà⁠yé֧ş̌ yĕhwá֛h bĕ̇⁠qirĕbé֖̇⁠nẇ ʼim-ʼáֽyin׃p"],[17,8,"וַ⁠יָּבֹ֖א עֲמָלֵ֑ק וַ⁠יִּלָּ֥חֶם עִם־יִשְׂרָאֵ֖ל בִּ⁠רְפִידִֽם׃","wa⁠yá̇bò֖ʼ ʻàmálé֑q wa⁠yi̇lá֥̇ẖem ʻim-yişĕ̂ráʼé֖l bi̇⁠rĕpiydiֽm׃"],[17,9,"וַ⁠יֹּ֨אמֶר מֹשֶׁ֤ה אֶל־יְהוֹשֻׁ֨עַ֙ בְּחַר־לָ֣⁠נוּ אֲנָשִׁ֔ים וְ⁠צֵ֖א הִלָּחֵ֣ם בַּ⁠עֲמָלֵ֑ק מָחָ֗ר אָנֹכִ֤י נִצָּב֙ עַל־רֹ֣אשׁ הַ⁠גִּבְעָ֔ה וּ⁠מַטֵּ֥ה הָ⁠אֱלֹהִ֖ים בְּ⁠יָדִֽ⁠י׃","wa⁠yò̇֨ʼmer mòşě֤h ʼel-yĕhwòşǔ֨ʻa֙ bĕ̇ẖar-lá֣⁠nẇ ʼànáşǐ֔ym wĕ⁠ẕé֖ʼ hilá̇ẖé֣m bȧ⁠ʻàmálé֑q máẖá֗r ʼánòki֤y niẕá̇b֙ ʻal-rò֣ʼş̌ ha⁠gi̇bĕʻá֔h ẇ⁠maté֥̇h há⁠ʼèlòhi֖ym bĕ̇⁠yádiֽ⁠y׃"],[17,10,"וַ⁠יַּ֣עַשׂ יְהוֹשֻׁ֗עַ כַּ⁠אֲשֶׁ֤ר אָֽמַר־ל⁠וֹ֙ מֹשֶׁ֔ה לְ⁠הִלָּחֵ֖ם בַּ⁠עֲמָלֵ֑ק וּ⁠מֹשֶׁה֙ אַהֲרֹ֣ן וְ⁠ח֔וּר עָל֖וּ רֹ֥אשׁ הַ⁠גִּבְעָֽה׃","wa⁠yȧ֣ʻaş̂ yĕhwòşǔ֗ʻa kȧ⁠ʼàşě֤r ʼáֽmar-l⁠wò֙ mòşě֔h lĕ⁠hilá̇ẖé֖m bȧ⁠ʻàmálé֑q ẇ⁠mòşěh֙ ʼahàrò֣n wĕ⁠ẖ֔ẇr ʻál֖ẇ rò֥ʼş̌ ha⁠gi̇bĕʻáֽh׃"],[17,11,"וְ⁠הָיָ֗ה כַּ⁠אֲשֶׁ֨ר יָרִ֥ים מֹשֶׁ֛ה יָד֖⁠וֹ וְ⁠גָבַ֣ר יִשְׂרָאֵ֑ל וְ⁠כַ⁠אֲשֶׁ֥ר יָנִ֛יחַ יָד֖⁠וֹ וְ⁠גָבַ֥ר עֲמָלֵֽק׃","wĕ⁠háyá֗h kȧ⁠ʼàşě֨r yári֥ym mòşě֛h yád֖⁠wò wĕ⁠gába֣r yişĕ̂ráʼé֑l wĕ⁠ka⁠ʼàşě֥r yáni֛yẖa yád֖⁠wò wĕ⁠gába֥r ʻàmáléֽq׃"],[17,12,"וִ⁠ידֵ֤י מֹשֶׁה֙ כְּבֵדִ֔ים וַ⁠יִּקְחוּ־אֶ֛בֶן וַ⁠יָּשִׂ֥ימוּ תַחְתָּ֖י⁠ו וַ⁠יֵּ֣שֶׁב עָלֶ֑י⁠הָ וְ⁠אַהֲרֹ֨ן וְ⁠ח֜וּר תָּֽמְכ֣וּ בְ⁠יָדָ֗י⁠ו מִ⁠זֶּ֤ה אֶחָד֙ וּ⁠מִ⁠זֶּ֣ה אֶחָ֔ד וַ⁠יְהִ֥י יָדָ֛י⁠ו אֱמוּנָ֖ה עַד־בֹּ֥א הַ⁠שָּֽׁמֶשׁ׃","wi⁠ydé֤y mòşěh֙ kĕ̇bédi֔ym wa⁠yi̇qĕẖẇ-ʼe֛ben wa⁠yá̇şî֥ymẇ ţaẖĕţá֖̇y⁠w wa⁠yé֣̇şěb ʻále֑y⁠há wĕ⁠ʼahàrò֨n wĕ⁠ẖ֜ẇr ţáֽ̇mĕk֣ẇ bĕ⁠yádá֗y⁠w mi⁠zė֤h ʼeẖád֙ ẇ⁠mi⁠zė֣h ʼeẖá֔d wa⁠yĕhi֥y yádá֛y⁠w ʼèmẇná֖h ʻad-bò֥̇ʼ ha⁠şáֽ̇̌meş̌׃"],[17,13,"וַ⁠יַּחֲלֹ֧שׁ יְהוֹשֻׁ֛עַ אֶת־עֲמָלֵ֥ק וְ⁠אֶת־עַמּ֖⁠וֹ לְ⁠פִי־חָֽרֶב׃פ","wa⁠yȧẖàlò֧ş̌ yĕhwòşǔ֛ʻa ʼeţ-ʻàmálé֥q wĕ⁠ʼeţ-ʻaṁ֖⁠wò lĕ⁠piy-ẖáֽreb׃p"],[17,14,"וַ⁠יֹּ֨אמֶר יְהוָ֜ה אֶל־מֹשֶׁ֗ה כְּתֹ֨ב זֹ֤את זִכָּרוֹן֙ בַּ⁠סֵּ֔פֶר וְ⁠שִׂ֖ים בְּ⁠אָזְנֵ֣י יְהוֹשֻׁ֑עַ כִּֽי־מָחֹ֤ה אֶמְחֶה֙ אֶת־זֵ֣כֶר עֲמָלֵ֔ק מִ⁠תַּ֖חַת הַ⁠שָּׁמָֽיִם׃","wa⁠yò̇֨ʼmer yĕhwá֜h ʼel-mòşě֗h kĕ̇ţò֨b zò֤ʼţ ziká̇rwòn֙ bȧ⁠sé̇֔per wĕ⁠şî֖ym bĕ̇⁠ʼázĕné֣y yĕhwòşǔ֑ʻa kiֽ̇y-máẖò֤h ʼemĕẖeh֙ ʼeţ-zé֣ker ʻàmálé֔q mi⁠ţȧ֖ẖaţ ha⁠şá̇̌máֽyim׃"],[17,15,"וַ⁠יִּ֥בֶן מֹשֶׁ֖ה מִזְבֵּ֑חַ וַ⁠יִּקְרָ֥א שְׁמ֖⁠וֹ יְהוָ֥ה ׀ נִסִּֽ⁠י׃","wa⁠yi֥̇ben mòşě֖h mizĕbé֑̇ẖa wa⁠yi̇qĕrá֥ʼ şĕ̌m֖⁠wò yĕhwá֥h ׀ nisiֽ̇⁠y׃"],[17,16,"וַ⁠יֹּ֗אמֶר כִּֽי־יָד֙ עַל־כֵּ֣ס יָ֔הּ מִלְחָמָ֥ה לַ⁠יהוָ֖ה בַּֽ⁠עֲמָלֵ֑ק מִ⁠דֹּ֖ר דֹּֽר׃פ","wa⁠yò̇֗ʼmer kiֽ̇y-yád֙ ʻal-ké֣̇s yá֔ḣ milĕẖámá֥h la⁠yhwá֖h bȧֽ⁠ʻàmálé֑q mi⁠dò֖̇r dòֽ̇r׃p"],[18,1,"וַ⁠יִּשְׁמַ֞ע יִתְר֨וֹ כֹהֵ֤ן מִדְיָן֙ חֹתֵ֣ן מֹשֶׁ֔ה אֵת֩ כָּל־אֲשֶׁ֨ר עָשָׂ֤ה אֱלֹהִים֙ לְ⁠מֹשֶׁ֔ה וּ⁠לְ⁠יִשְׂרָאֵ֖ל עַמּ֑⁠וֹ כִּֽי־הוֹצִ֧יא יְהוָ֛ה אֶת־יִשְׂרָאֵ֖ל מִ⁠מִּצְרָֽיִם׃","wa⁠yi̇şĕ̌ma֞ʻ yiţĕr֨wò kòhé֤n midĕyán֙ ẖòţé֣n mòşě֔h ʼéţ֩ ká̇l-ʼàşě֨r ʻáşá֤̂h ʼèlòhiym֙ lĕ⁠mòşě֔h ẇ⁠lĕ⁠yişĕ̂ráʼé֖l ʻaṁ֑⁠wò kiֽ̇y-hwòẕi֧yʼ yĕhwá֛h ʼeţ-yişĕ̂ráʼé֖l mi⁠mi̇ẕĕráֽyim׃"],[18,2,"וַ⁠יִּקַּ֗ח יִתְרוֹ֙ חֹתֵ֣ן מֹשֶׁ֔ה אֶת־צִפֹּרָ֖ה אֵ֣שֶׁת מֹשֶׁ֑ה אַחַ֖ר שִׁלּוּחֶֽי⁠הָ׃","wa⁠yi̇qȧ֗ẖ yiţĕrwò֙ ẖòţé֣n mòşě֔h ʼeţ-ẕipò̇rá֖h ʼé֣şěţ mòşě֑h ʼaẖa֖r şǐl̇ẇẖeֽy⁠há׃"],[18,3,"וְ⁠אֵ֖ת שְׁנֵ֣י בָנֶ֑י⁠הָ אֲשֶׁ֨ר שֵׁ֤ם הָֽ⁠אֶחָד֙ גֵּֽרְשֹׁ֔ם כִּ֣י אָמַ֔ר גֵּ֣ר הָיִ֔יתִי בְּ⁠אֶ֖רֶץ נָכְרִיָּֽה׃","wĕ⁠ʼé֖ţ şĕ̌né֣y báne֑y⁠há ʼàşě֨r şé֤̌m háֽ⁠ʼeẖád֙ géֽ̇rĕşò̌֔m ki֣̇y ʼáma֔r gé֣̇r háyi֔yţiy bĕ̇⁠ʼe֖reẕ nákĕriyáֽ̇h׃"],[18,4,"וְ⁠שֵׁ֥ם הָ⁠אֶחָ֖ד אֱלִיעֶ֑זֶר כִּֽי־אֱלֹהֵ֤י אָבִ⁠י֙ בְּ⁠עֶזְרִ֔⁠י וַ⁠יַּצִּלֵ֖⁠נִי מֵ⁠חֶ֥רֶב פַּרְעֹֽה׃","wĕ⁠şé֥̌m há⁠ʼeẖá֖d ʼèliyʻe֑zer kiֽ̇y-ʼèlòhé֤y ʼábi⁠y֙ bĕ̇⁠ʻezĕri֔⁠y wa⁠yȧẕi̇lé֖⁠niy mé⁠ẖe֥reb pȧrĕʻòֽh׃"],[18,5,"וַ⁠יָּבֹ֞א יִתְר֨וֹ חֹתֵ֥ן מֹשֶׁ֛ה וּ⁠בָנָ֥י⁠ו וְ⁠אִשְׁתּ֖⁠וֹ אֶל־מֹשֶׁ֑ה אֶל־הַ⁠מִּדְבָּ֗ר אֲשֶׁר־ה֛וּא חֹנֶ֥ה שָׁ֖ם הַ֥ר הָ⁠אֱלֹהִֽים׃","wa⁠yá̇bò֞ʼ yiţĕr֨wò ẖòţé֥n mòşě֛h ẇ⁠báná֥y⁠w wĕ⁠ʼişĕ̌ţ֖̇⁠wò ʼel-mòşě֑h ʼel-ha⁠mi̇dĕbá̇֗r ʼàşěr-h֛ẇʼ ẖòne֥h şá֖̌m ha֥r há⁠ʼèlòhiֽym׃"],[18,6,"וַ⁠יֹּ֨אמֶר֙ אֶל־מֹשֶׁ֔ה אֲנִ֛י חֹתֶנְ⁠ךָ֥ יִתְר֖וֹ בָּ֣א אֵלֶ֑י⁠ךָ וְ⁠אִ֨שְׁתְּ⁠ךָ֔ וּ⁠שְׁנֵ֥י בָנֶ֖י⁠הָ עִמָּֽ⁠הּ׃","wa⁠yò̇֨ʼmer֙ ʼel-mòşě֔h ʼàni֛y ẖòţenĕ⁠ká֥ yiţĕr֖wò bá֣̇ʼ ʼéle֑y⁠ká wĕ⁠ʼi֨şĕ̌ţĕ̇⁠ká֔ ẇ⁠şĕ̌né֥y báne֖y⁠há ʻimáֽ̇⁠ḣ׃"],[18,7,"וַ⁠יֵּצֵ֨א מֹשֶׁ֜ה לִ⁠קְרַ֣את חֹֽתְנ֗⁠וֹ וַ⁠יִּשְׁתַּ֨חוּ֙ וַ⁠יִּשַּׁק־ל֔⁠וֹ וַ⁠יִּשְׁאֲל֥וּ אִישׁ־לְ⁠רֵעֵ֖⁠הוּ לְ⁠שָׁל֑וֹם וַ⁠יָּבֹ֖אוּ הָ⁠אֹֽהֱלָ⁠ה׃","wa⁠yé̇ẕé֨ʼ mòşě֜h li⁠qĕra֣ʼţ ẖòֽţĕn֗⁠wò wa⁠yi̇şĕ̌ţȧ֨ẖẇ֙ wa⁠yi̇şȧ̌q-l֔⁠wò wa⁠yi̇şĕ̌ʼàl֥ẇ ʼiyş̌-lĕ⁠réʻé֖⁠hẇ lĕ⁠şá̌l֑wòm wa⁠yá̇bò֖ʼẇ há⁠ʼòֽhèlá⁠h׃"],[18,8,"וַ⁠יְסַפֵּ֤ר מֹשֶׁה֙ לְ⁠חֹ֣תְנ֔⁠וֹ אֵת֩ כָּל־אֲשֶׁ֨ר עָשָׂ֤ה יְהוָה֙ לְ⁠פַרְעֹ֣ה וּ⁠לְ⁠מִצְרַ֔יִם עַ֖ל אוֹדֹ֣ת יִשְׂרָאֵ֑ל אֵ֤ת כָּל־הַ⁠תְּלָאָה֙ אֲשֶׁ֣ר מְצָאָ֣תַ⁠ם בַּ⁠דֶּ֔רֶךְ וַ⁠יַּצִּלֵ֖⁠ם יְהוָֽה׃","wa⁠yĕsapé֤̇r mòşěh֙ lĕ⁠ẖò֣ţĕn֔⁠wò ʼéţ֩ ká̇l-ʼàşě֨r ʻáşá֤̂h yĕhwáh֙ lĕ⁠parĕʻò֣h ẇ⁠lĕ⁠miẕĕra֔yim ʻa֖l ʼwòdò֣ţ yişĕ̂ráʼé֑l ʼé֤ţ ká̇l-ha⁠ţĕ̇láʼáh֙ ʼàşě֣r mĕẕáʼá֣ţa⁠m bȧ⁠dė֔rekĕ wa⁠yȧẕi̇lé֖⁠m yĕhwáֽh׃"],[18,9,"וַ⁠יִּ֣חַדְּ יִתְר֔וֹ עַ֚ל כָּל־הַ⁠טּוֹבָ֔ה אֲשֶׁר־עָשָׂ֥ה יְהוָ֖ה לְ⁠יִשְׂרָאֵ֑ל אֲשֶׁ֥ר הִצִּיל֖⁠וֹ מִ⁠יַּ֥ד מִצְרָֽיִם׃","wa⁠yi֣̇ẖadĕ̇ yiţĕr֔wò ʻa֚l ká̇l-ha⁠ṫwòbá֔h ʼàşěr-ʻáşá֥̂h yĕhwá֖h lĕ⁠yişĕ̂ráʼé֑l ʼàşě֥r hiẕi̇yl֖⁠wò mi⁠yȧ֥d miẕĕráֽyim׃"],[18,10,"וַ⁠יֹּאמֶר֮ יִתְרוֹ֒ בָּר֣וּךְ יְהוָ֔ה אֲשֶׁ֨ר הִצִּ֥יל אֶתְ⁠כֶ֛ם מִ⁠יַּ֥ד מִצְרַ֖יִם וּ⁠מִ⁠יַּ֣ד פַּרְעֹ֑ה אֲשֶׁ֤ר הִצִּיל֙ אֶת־הָ⁠עָ֔ם מִ⁠תַּ֖חַת יַד־מִצְרָֽיִם׃","wa⁠yò̇ʼmer֮ yiţĕrwò֒ bá̇r֣ẇkĕ yĕhwá֔h ʼàşě֨r hiẕi֥̇yl ʼeţĕ⁠ke֛m mi⁠yȧ֥d miẕĕra֖yim ẇ⁠mi⁠yȧ֣d pȧrĕʻò֑h ʼàşě֤r hiẕi̇yl֙ ʼeţ-há⁠ʻá֔m mi⁠ţȧ֖ẖaţ yad-miẕĕráֽyim׃"],[18,11,"עַתָּ֣ה יָדַ֔עְתִּי כִּֽי־גָד֥וֹל יְהוָ֖ה מִ⁠כָּל־הָ⁠אֱלֹהִ֑ים כִּ֣י בַ⁠דָּבָ֔ר אֲשֶׁ֥ר זָד֖וּ עֲלֵי⁠הֶֽם׃","ʻaţá֣̇h yáda֔ʻĕţi̇y kiֽ̇y-gád֥wòl yĕhwá֖h mi⁠ká̇l-há⁠ʼèlòhi֑ym ki֣̇y ba⁠dá̇bá֔r ʼàşě֥r zád֖ẇ ʻàléy⁠heֽm׃"],[18,12,"וַ⁠יִּקַּ֞ח יִתְר֨וֹ חֹתֵ֥ן מֹשֶׁ֛ה עֹלָ֥ה וּ⁠זְבָחִ֖ים לֵֽ⁠אלֹהִ֑ים וַ⁠יָּבֹ֨א אַהֲרֹ֜ן וְ⁠כֹ֣ל ׀ זִקְנֵ֣י יִשְׂרָאֵ֗ל לֶ⁠אֱכָל־לֶ֛חֶם עִם־חֹתֵ֥ן מֹשֶׁ֖ה לִ⁠פְנֵ֥י הָ⁠אֱלֹהִֽים׃","wa⁠yi̇qȧ֞ẖ yiţĕr֨wò ẖòţé֥n mòşě֛h ʻòlá֥h ẇ⁠zĕbáẖi֖ym léֽ⁠ʼlòhi֑ym wa⁠yá̇bò֨ʼ ʼahàrò֜n wĕ⁠kò֣l ׀ ziqĕné֣y yişĕ̂ráʼé֗l le⁠ʼèkál-le֛ẖem ʻim-ẖòţé֥n mòşě֖h li⁠pĕné֥y há⁠ʼèlòhiֽym׃"],[18,13,"וַ⁠יְהִי֙ מִֽ⁠מָּחֳרָ֔ת וַ⁠יֵּ֥שֶׁב מֹשֶׁ֖ה לִ⁠שְׁפֹּ֣ט אֶת־הָ⁠עָ֑ם וַ⁠יַּעֲמֹ֤ד הָ⁠עָם֙ עַל־מֹשֶׁ֔ה מִן־הַ⁠בֹּ֖קֶר עַד־הָ⁠עָֽרֶב׃","wa⁠yĕhiy֙ miֽ⁠má̇ẖorá֔ţ wa⁠yé֥̇şěb mòşě֖h li⁠şĕ̌pò֣̇t ʼeţ-há⁠ʻá֑m wa⁠yȧʻàmò֤d há⁠ʻám֙ ʻal-mòşě֔h min-ha⁠bò֖̇qer ʻad-há⁠ʻáֽreb׃"],[18,14,"וַ⁠יַּרְא֙ חֹתֵ֣ן מֹשֶׁ֔ה אֵ֛ת כָּל־אֲשֶׁר־ה֥וּא עֹשֶׂ֖ה לָ⁠עָ֑ם וַ⁠יֹּ֗אמֶר מָֽה־הַ⁠דָּבָ֤ר הַ⁠זֶּה֙ אֲשֶׁ֨ר אַתָּ֤ה עֹשֶׂה֙ לָ⁠עָ֔ם מַדּ֗וּעַ אַתָּ֤ה יוֹשֵׁב֙ לְ⁠בַדֶּ֔⁠ךָ וְ⁠כָל־הָ⁠עָ֛ם נִצָּ֥ב עָלֶ֖י⁠ךָ מִן־בֹּ֥קֶר עַד־עָֽרֶב׃","wa⁠yȧrĕʼ֙ ẖòţé֣n mòşě֔h ʼé֛ţ ká̇l-ʼàşěr-h֥ẇʼ ʻòşê֖h lá⁠ʻá֑m wa⁠yò̇֗ʼmer máֽh-ha⁠dá̇bá֤r ha⁠zėh֙ ʼàşě֨r ʼaţá֤̇h ʻòşêh֙ lá⁠ʻá֔m maḋ֗ẇʻa ʼaţá֤̇h ywòşé̌b֙ lĕ⁠badė֔⁠ká wĕ⁠kál-há⁠ʻá֛m niẕá֥̇b ʻále֖y⁠ká min-bò֥̇qer ʻad-ʻáֽreb׃"],[18,15,"וַ⁠יֹּ֥אמֶר מֹשֶׁ֖ה לְ⁠חֹתְנ֑⁠וֹ כִּֽי־יָבֹ֥א אֵלַ֛⁠י הָ⁠עָ֖ם לִ⁠דְרֹ֥שׁ אֱלֹהִֽים׃","wa⁠yò֥̇ʼmer mòşě֖h lĕ⁠ẖòţĕn֑⁠wò kiֽ̇y-yábò֥ʼ ʼéla֛⁠y há⁠ʻá֖m li⁠dĕrò֥ş̌ ʼèlòhiֽym׃"],[18,16,"כִּֽי־יִהְיֶ֨ה לָ⁠הֶ֤ם דָּבָר֙ בָּ֣א אֵלַ֔⁠י וְ⁠שָׁ֣פַטְתִּ֔י בֵּ֥ין אִ֖ישׁ וּ⁠בֵ֣ין רֵעֵ֑⁠הוּ וְ⁠הוֹדַעְתִּ֛י אֶת־חֻקֵּ֥י הָ⁠אֱלֹהִ֖ים וְ⁠אֶת־תּוֹרֹתָֽי⁠ו׃","kiֽ̇y-yihĕye֨h lá⁠he֤m dá̇bár֙ bá֣̇ʼ ʼéla֔⁠y wĕ⁠şá֣̌patĕţi̇֔y bé֥̇yn ʼi֖yş̌ ẇ⁠bé֣yn réʻé֑⁠hẇ wĕ⁠hwòdaʻĕţi֛̇y ʼeţ-ẖuqé֥̇y há⁠ʼèlòhi֖ym wĕ⁠ʼeţ-ţ̇wòròţáֽy⁠w׃"],[18,17,"וַ⁠יֹּ֛אמֶר חֹתֵ֥ן מֹשֶׁ֖ה אֵלָ֑י⁠ו לֹא־טוֹב֙ הַ⁠דָּבָ֔ר אֲשֶׁ֥ר אַתָּ֖ה עֹשֶֽׂה׃","wa⁠yò֛̇ʼmer ẖòţé֥n mòşě֖h ʼélá֑y⁠w lòʼ-twòb֙ ha⁠dá̇bá֔r ʼàşě֥r ʼaţá֖̇h ʻòşêֽh׃"],[18,18,"נָבֹ֣ל תִּבֹּ֔ל גַּם־אַתָּ֕ה גַּם־הָ⁠עָ֥ם הַ⁠זֶּ֖ה אֲשֶׁ֣ר עִמָּ֑⁠ךְ כִּֽי־כָבֵ֤ד מִמְּ⁠ךָ֙ הַ⁠דָּבָ֔ר לֹא־תוּכַ֥ל עֲשֹׂ֖⁠הוּ לְ⁠בַדֶּֽ⁠ךָ׃","nábò֣l ţi̇bò̇֔l gȧm-ʼaţá̇֕h gȧm-há⁠ʻá֥m ha⁠zė֖h ʼàşě֣r ʻimá֑̇⁠kĕ kiֽ̇y-kábé֤d mimĕ̇⁠ká֙ ha⁠dá̇bá֔r lòʼ-ţẇka֥l ʻàşò֖̂⁠hẇ lĕ⁠badėֽ⁠ká׃"],[18,19,"עַתָּ֞ה שְׁמַ֤ע בְּ⁠קֹלִ⁠י֙ אִיעָ֣צְ⁠ךָ֔ וִ⁠יהִ֥י אֱלֹהִ֖ים עִמָּ֑⁠ךְ הֱיֵ֧ה אַתָּ֣ה לָ⁠עָ֗ם מ֚וּל הָֽ⁠אֱלֹהִ֔ים וְ⁠הֵבֵאתָ֥ אַתָּ֛ה אֶת־הַ⁠דְּבָרִ֖ים אֶל־הָ⁠אֱלֹהִֽים׃","ʻaţá̇֞h şĕ̌ma֤ʻ bĕ̇⁠qòli⁠y֙ ʼiyʻá֣ẕĕ⁠ká֔ wi⁠yhi֥y ʼèlòhi֖ym ʻimá֑̇⁠kĕ hèyé֧h ʼaţá֣̇h lá⁠ʻá֗m m֚ẇl háֽ⁠ʼèlòhi֔ym wĕ⁠hébéʼţá֥ ʼaţá֛̇h ʼeţ-ha⁠dĕ̇bári֖ym ʼel-há⁠ʼèlòhiֽym׃"],[18,20,"וְ⁠הִזְהַרְתָּ֣ה אֶתְ⁠הֶ֔ם אֶת־הַ⁠חֻקִּ֖ים וְ⁠אֶת־הַ⁠תּוֹרֹ֑ת וְ⁠הוֹדַעְתָּ֣ לָ⁠הֶ֗ם אֶת־הַ⁠דֶּ֨רֶךְ֙ יֵ֣לְכוּ בָ֔⁠הּ וְ⁠אֶת־הַֽ⁠מַּעֲשֶׂ֖ה אֲשֶׁ֥ר יַעֲשֽׂוּ⁠ן׃","wĕ⁠hizĕharĕţá֣̇h ʼeţĕ⁠he֔m ʼeţ-ha⁠ẖuqi֖̇ym wĕ⁠ʼeţ-ha⁠ţ̇wòrò֑ţ wĕ⁠hwòdaʻĕţá֣̇ lá⁠he֗m ʼeţ-ha⁠dė֨rekĕ֙ yé֣lĕkẇ bá֔⁠ḣ wĕ⁠ʼeţ-haֽ⁠mȧʻàşê֖h ʼàşě֥r yaʻàşֽ̂ẇ⁠n׃"],[18,21,"וְ⁠אַתָּ֣ה תֶחֱזֶ֣ה מִ⁠כָּל־הָ֠⁠עָם אַנְשֵׁי־חַ֜יִל יִרְאֵ֧י אֱלֹהִ֛ים אַנְשֵׁ֥י אֱמֶ֖ת שֹׂ֣נְאֵי בָ֑צַע וְ⁠שַׂמְתָּ֣ עֲלֵ⁠הֶ֗ם שָׂרֵ֤י אֲלָפִים֙ שָׂרֵ֣י מֵא֔וֹת שָׂרֵ֥י חֲמִשִּׁ֖ים וְ⁠שָׂרֵ֥י עֲשָׂרֹֽת׃","wĕ⁠ʼaţá֣̇h ţeẖèze֣h mi⁠ká̇l-há֠⁠ʻám ʼanĕşé̌y-ẖa֜yil yirĕʼé֧y ʼèlòhi֛ym ʼanĕşé֥̌y ʼème֖ţ şò֣̂nĕʼéy bá֑ẕaʻ wĕ⁠şâmĕţá֣̇ ʻàlé⁠he֗m şá̂ré֤y ʼàlápiym֙ şá̂ré֣y méʼ֔wòţ şá̂ré֥y ẖàmişi֖̇̌ym wĕ⁠şá̂ré֥y ʻàşá̂ròֽţ׃"],[18,22,"וְ⁠שָׁפְט֣וּ אֶת־הָ⁠עָם֮ בְּ⁠כָל־עֵת֒ וְ⁠הָיָ֞ה כָּל־הַ⁠דָּבָ֤ר הַ⁠גָּדֹל֙ יָבִ֣יאוּ אֵלֶ֔י⁠ךָ וְ⁠כָל־הַ⁠דָּבָ֥ר הַ⁠קָּטֹ֖ן יִשְׁפְּטוּ־הֵ֑ם וְ⁠הָקֵל֙ מֵֽ⁠עָלֶ֔י⁠ךָ וְ⁠נָשְׂא֖וּ אִתָּֽ⁠ךְ׃","wĕ⁠şá̌pĕt֣ẇ ʼeţ-há⁠ʻám֮ bĕ̇⁠kál-ʻéţ֒ wĕ⁠háyá֞h ká̇l-ha⁠dá̇bá֤r ha⁠gá̇dòl֙ yábi֣yʼẇ ʼéle֔y⁠ká wĕ⁠kál-ha⁠dá̇bá֥r ha⁠qá̇tò֖n yişĕ̌pĕ̇tẇ-hé֑m wĕ⁠háqél֙ méֽ⁠ʻále֔y⁠ká wĕ⁠náşĕ̂ʼ֖ẇ ʼiţáֽ̇⁠kĕ׃"],[18,23,"אִ֣ם אֶת־הַ⁠דָּבָ֤ר הַ⁠זֶּה֙ תַּעֲשֶׂ֔ה וְ⁠צִוְּ⁠ךָ֣ אֱלֹהִ֔ים וְ⁠יָֽכָלְתָּ֖ עֲמֹ֑ד וְ⁠גַם֙ כָּל־הָ⁠עָ֣ם הַ⁠זֶּ֔ה עַל־מְקֹמ֖⁠וֹ יָבֹ֥א בְ⁠שָׁלֽוֹם׃","ʼi֣m ʼeţ-ha⁠dá̇bá֤r ha⁠zėh֙ ţȧʻàşê֔h wĕ⁠ẕiwĕ̇⁠ká֣ ʼèlòhi֔ym wĕ⁠yáֽkálĕţá֖̇ ʻàmò֑d wĕ⁠gam֙ ká̇l-há⁠ʻá֣m ha⁠zė֔h ʻal-mĕqòm֖⁠wò yábò֥ʼ bĕ⁠şá̌lֽwòm׃"],[18,24,"וַ⁠יִּשְׁמַ֥ע מֹשֶׁ֖ה לְ⁠ק֣וֹל חֹתְנ֑⁠וֹ וַ⁠יַּ֕עַשׂ כֹּ֖ל אֲשֶׁ֥ר אָמָֽר׃","wa⁠yi̇şĕ̌ma֥ʻ mòşě֖h lĕ⁠q֣wòl ẖòţĕn֑⁠wò wa⁠yȧ֕ʻaş̂ kò֖̇l ʼàşě֥r ʼámáֽr׃"],[18,25,"וַ⁠יִּבְחַ֨ר מֹשֶׁ֤ה אַנְשֵׁי־חַ֨יִל֙ מִ⁠כָּל־יִשְׂרָאֵ֔ל וַ⁠יִּתֵּ֥ן אֹתָ֛⁠ם רָאשִׁ֖ים עַל־הָ⁠עָ֑ם שָׂרֵ֤י אֲלָפִים֙ שָׂרֵ֣י מֵא֔וֹת שָׂרֵ֥י חֲמִשִּׁ֖ים וְ⁠שָׂרֵ֥י עֲשָׂרֹֽת׃","wa⁠yi̇bĕẖa֨r mòşě֤h ʼanĕşé̌y-ẖa֨yil֙ mi⁠ká̇l-yişĕ̂ráʼé֔l wa⁠yi̇ţé֥̇n ʼòţá֛⁠m ráʼşǐ֖ym ʻal-há⁠ʻá֑m şá̂ré֤y ʼàlápiym֙ şá̂ré֣y méʼ֔wòţ şá̂ré֥y ẖàmişi֖̇̌ym wĕ⁠şá̂ré֥y ʻàşá̂ròֽţ׃"],[18,26,"וְ⁠שָׁפְט֥וּ אֶת־הָ⁠עָ֖ם בְּ⁠כָל־עֵ֑ת אֶת־הַ⁠דָּבָ֤ר הַ⁠קָּשֶׁה֙ יְבִיא֣וּ⁠ן אֶל־מֹשֶׁ֔ה וְ⁠כָל־הַ⁠דָּבָ֥ר הַ⁠קָּטֹ֖ן יִשְׁפּוּט֥וּ הֵֽם׃","wĕ⁠şá̌pĕt֥ẇ ʼeţ-há⁠ʻá֖m bĕ̇⁠kál-ʻé֑ţ ʼeţ-ha⁠dá̇bá֤r ha⁠qá̇şěh֙ yĕbiyʼ֣ẇ⁠n ʼel-mòşě֔h wĕ⁠kál-ha⁠dá̇bá֥r ha⁠qá̇tò֖n yişĕ̌ṗẇt֥ẇ héֽm׃"],[18,27,"וַ⁠יְשַׁלַּ֥ח מֹשֶׁ֖ה אֶת־חֹתְנ֑⁠וֹ וַ⁠יֵּ֥לֶךְ ל֖⁠וֹ אֶל־אַרְצֽ⁠וֹ׃פ","wa⁠yĕşǎlȧ֥ẖ mòşě֖h ʼeţ-ẖòţĕn֑⁠wò wa⁠yé֥̇lekĕ l֖⁠wò ʼel-ʼarĕẕֽ⁠wò׃p"],[19,1,"בַּ⁠חֹ֨דֶשׁ֙ הַ⁠שְּׁלִישִׁ֔י לְ⁠צֵ֥את בְּנֵי־יִשְׂרָאֵ֖ל מֵ⁠אֶ֣רֶץ מִצְרָ֑יִם בַּ⁠יּ֣וֹם הַ⁠זֶּ֔ה בָּ֖אוּ מִדְבַּ֥ר סִינָֽי׃","bȧ⁠ẖò֨deş̌֙ ha⁠şĕ̇̌liyşǐ֔y lĕ⁠ẕé֥ʼţ bĕ̇néy-yişĕ̂ráʼé֖l mé⁠ʼe֣reẕ miẕĕrá֑yim bȧ⁠ẏ֣wòm ha⁠zė֔h bá֖̇ʼẇ midĕbȧ֥r siynáֽy׃"],[19,2,"וַ⁠יִּסְע֣וּ מֵ⁠רְפִידִ֗ים וַ⁠יָּבֹ֨אוּ֙ מִדְבַּ֣ר סִינַ֔י וַֽ⁠יַּחֲנ֖וּ בַּ⁠מִּדְבָּ֑ר וַ⁠יִּֽחַן־שָׁ֥ם יִשְׂרָאֵ֖ל נֶ֥גֶד הָ⁠הָֽר׃","wa⁠yi̇sĕʻ֣ẇ mé⁠rĕpiydi֗ym wa⁠yá̇bò֨ʼẇ֙ midĕbȧ֣r siyna֔y waֽ⁠yȧẖàn֖ẇ bȧ⁠mi̇dĕbá֑̇r wa⁠yiֽ̇ẖan-şá֥̌m yişĕ̂ráʼé֖l ne֥ged há⁠háֽr׃"],[19,3,"וּ⁠מֹשֶׁ֥ה עָלָ֖ה אֶל־הָ⁠אֱלֹהִ֑ים וַ⁠יִּקְרָ֨א אֵלָ֤י⁠ו יְהוָה֙ מִן־הָ⁠הָ֣ר לֵ⁠אמֹ֔ר כֹּ֤ה תֹאמַר֙ לְ⁠בֵ֣ית יַעֲקֹ֔ב וְ⁠תַגֵּ֖יד לִ⁠בְנֵ֥י יִשְׂרָאֵֽל׃","ẇ⁠mòşě֥h ʻálá֖h ʼel-há⁠ʼèlòhi֑ym wa⁠yi̇qĕrá֨ʼ ʼélá֤y⁠w yĕhwáh֙ min-há⁠há֣r lé⁠ʼmò֔r kò֤̇h ţòʼmar֙ lĕ⁠bé֣yţ yaʻàqò֔b wĕ⁠ţagé֖̇yd li⁠bĕné֥y yişĕ̂ráʼéֽl׃"],[19,4,"אַתֶּ֣ם רְאִיתֶ֔ם אֲשֶׁ֥ר עָשִׂ֖יתִי לְ⁠מִצְרָ֑יִם וָ⁠אֶשָּׂ֤א אֶתְ⁠כֶם֙ עַל־כַּנְפֵ֣י נְשָׁרִ֔ים וָ⁠אָבִ֥א אֶתְ⁠כֶ֖ם אֵלָֽ⁠י׃","ʼaţė֣m rĕʼiyţe֔m ʼàşě֥r ʻáşî֖yţiy lĕ⁠miẕĕrá֑yim wá⁠ʼeşá֤̇̂ʼ ʼeţĕ⁠kem֙ ʻal-kȧnĕpé֣y nĕşá̌ri֔ym wá⁠ʼábi֥ʼ ʼeţĕ⁠ke֖m ʼéláֽ⁠y׃"],[19,5,"וְ⁠עַתָּ֗ה אִם־שָׁמ֤וֹעַ תִּשְׁמְעוּ֙ בְּ⁠קֹלִ֔⁠י וּ⁠שְׁמַרְתֶּ֖ם אֶת־בְּרִיתִ֑⁠י וִ⁠הְיִ֨יתֶם לִ֤⁠י סְגֻלָּה֙ מִ⁠כָּל־הָ֣⁠עַמִּ֔ים כִּי־לִ֖⁠י כָּל־הָ⁠אָֽרֶץ׃","wĕ⁠ʻaţá̇֗h ʼim-şá̌m֤wòʻa ţi̇şĕ̌mĕʻẇ֙ bĕ̇⁠qòli֔⁠y ẇ⁠şĕ̌marĕţė֖m ʼeţ-bĕ̇riyţi֑⁠y wi⁠hĕyi֨yţem li֤⁠y sĕgulá̇h֙ mi⁠ká̇l-há֣⁠ʻami̇֔ym ki̇y-li֖⁠y ká̇l-há⁠ʼáֽreẕ׃"],[19,6,"וְ⁠אַתֶּ֧ם תִּהְיוּ־לִ֛⁠י מַמְלֶ֥כֶת כֹּהֲנִ֖ים וְ⁠ג֣וֹי קָד֑וֹשׁ אֵ֚לֶּה הַ⁠דְּבָרִ֔ים אֲשֶׁ֥ר תְּדַבֵּ֖ר אֶל־בְּנֵ֥י יִשְׂרָאֵֽל׃","wĕ⁠ʼaţė֧m ţi̇hĕyẇ-li֛⁠y mamĕle֥keţ kò̇hàni֖ym wĕ⁠g֣wòy qád֑wòş̌ ʼé֚lėh ha⁠dĕ̇bári֔ym ʼàşě֥r ţĕ̇dabé֖̇r ʼel-bĕ̇né֥y yişĕ̂ráʼéֽl׃"],[19,7,"וַ⁠יָּבֹ֣א מֹשֶׁ֔ה וַ⁠יִּקְרָ֖א לְ⁠זִקְנֵ֣י הָ⁠עָ֑ם וַ⁠יָּ֣שֶׂם לִ⁠פְנֵי⁠הֶ֗ם אֵ֚ת כָּל־הַ⁠דְּבָרִ֣ים הָ⁠אֵ֔לֶּה אֲשֶׁ֥ר צִוָּ֖⁠הוּ יְהוָֽה׃","wa⁠yá̇bò֣ʼ mòşě֔h wa⁠yi̇qĕrá֖ʼ lĕ⁠ziqĕné֣y há⁠ʻá֑m wa⁠yá֣̇şêm li⁠pĕnéy⁠he֗m ʼé֚ţ ká̇l-ha⁠dĕ̇bári֣ym há⁠ʼé֔lėh ʼàşě֥r ẕiwá֖̇⁠hẇ yĕhwáֽh׃"],[19,8,"וַ⁠יַּעֲנ֨וּ כָל־הָ⁠עָ֤ם יַחְדָּו֙ וַ⁠יֹּ֣אמְר֔וּ כֹּ֛ל אֲשֶׁר־דִּבֶּ֥ר יְהוָ֖ה נַעֲשֶׂ֑ה וַ⁠יָּ֧שֶׁב מֹשֶׁ֛ה אֶת־דִּבְרֵ֥י הָ⁠עָ֖ם אֶל־יְהוָֽה׃","wa⁠yȧʻàn֨ẇ kál-há⁠ʻá֤m yaẖĕdá̇w֙ wa⁠yò֣̇ʼmĕr֔ẇ kò֛̇l ʼàşěr-di̇bė֥r yĕhwá֖h naʻàşê֑h wa⁠yá֧̇şěb mòşě֛h ʼeţ-di̇bĕré֥y há⁠ʻá֖m ʼel-yĕhwáֽh׃"],[19,9,"וַ⁠יֹּ֨אמֶר יְהוָ֜ה אֶל־מֹשֶׁ֗ה הִנֵּ֨ה אָנֹכִ֜י בָּ֣א אֵלֶי⁠ךָ֮ בְּ⁠עַ֣ב הֶֽ⁠עָנָן֒ בַּ⁠עֲב֞וּר יִשְׁמַ֤ע הָ⁠עָם֙ בְּ⁠דַבְּרִ֣⁠י עִמָּ֔⁠ךְ וְ⁠גַם־בְּ⁠ךָ֖ יַאֲמִ֣ינוּ לְ⁠עוֹלָ֑ם וַ⁠יַּגֵּ֥ד מֹשֶׁ֛ה אֶת־דִּבְרֵ֥י הָ⁠עָ֖ם אֶל־יְהוָֽה׃","wa⁠yò̇֨ʼmer yĕhwá֜h ʼel-mòşě֗h hiné̇֨h ʼánòki֜y bá֣̇ʼ ʼéley⁠ká֮ bĕ̇⁠ʻa֣b heֽ⁠ʻánán֒ bȧ⁠ʻàb֞ẇr yişĕ̌ma֤ʻ há⁠ʻám֙ bĕ̇⁠dabĕ̇ri֣⁠y ʻimá̇֔⁠kĕ wĕ⁠gam-bĕ̇⁠ká֖ yaʼàmi֣ynẇ lĕ⁠ʻwòlá֑m wa⁠yȧgé֥̇d mòşě֛h ʼeţ-di̇bĕré֥y há⁠ʻá֖m ʼel-yĕhwáֽh׃"],[19,10,"וַ⁠יֹּ֨אמֶר יְהוָ֤ה אֶל־מֹשֶׁה֙ לֵ֣ךְ אֶל־הָ⁠עָ֔ם וְ⁠קִדַּשְׁתָּ֥⁠ם הַ⁠יּ֖וֹם וּ⁠מָחָ֑ר וְ⁠כִבְּס֖וּ שִׂמְלֹתָֽ⁠ם׃","wa⁠yò̇֨ʼmer yĕhwá֤h ʼel-mòşěh֙ lé֣kĕ ʼel-há⁠ʻá֔m wĕ⁠qidȧşĕ̌ţá֥̇⁠m ha⁠ẏ֖wòm ẇ⁠máẖá֑r wĕ⁠kibĕ̇s֖ẇ şîmĕlòţáֽ⁠m׃"],[19,11,"וְ⁠הָי֥וּ נְכֹנִ֖ים לַ⁠יּ֣וֹם הַ⁠שְּׁלִישִׁ֑י כִּ֣י ׀ בַּ⁠יּ֣וֹם הַ⁠שְּׁלִישִׁ֗י יֵרֵ֧ד יְהוָ֛ה לְ⁠עֵינֵ֥י כָל־הָ⁠עָ֖ם עַל־הַ֥ר סִינָֽי׃","wĕ⁠háy֥ẇ nĕkòni֖ym la⁠ẏ֣wòm ha⁠şĕ̇̌liyşǐ֑y ki֣̇y ׀ bȧ⁠ẏ֣wòm ha⁠şĕ̇̌liyşǐ֗y yéré֧d yĕhwá֛h lĕ⁠ʻéyné֥y kál-há⁠ʻá֖m ʻal-ha֥r siynáֽy׃"],[19,12,"וְ⁠הִגְבַּלְתָּ֤ אֶת־הָ⁠עָם֙ סָבִ֣יב לֵ⁠אמֹ֔ר הִשָּׁמְר֥וּ לָ⁠כֶ֛ם עֲל֥וֹת בָּ⁠הָ֖ר וּ⁠נְגֹ֣עַ בְּ⁠קָצֵ֑⁠הוּ כָּל־הַ⁠נֹּגֵ֥עַ בָּ⁠הָ֖ר מ֥וֹת יוּמָֽת׃","wĕ⁠higĕbȧlĕţá֤̇ ʼeţ-há⁠ʻám֙ sábi֣yb lé⁠ʼmò֔r hişá̇̌mĕr֥ẇ lá⁠ke֛m ʻàl֥wòţ bá̇⁠há֖r ẇ⁠nĕgò֣ʻa bĕ̇⁠qáẕé֑⁠hẇ ká̇l-ha⁠nò̇gé֥ʻa bá̇⁠há֖r m֥wòţ yẇmáֽţ׃"],[19,13,"לֹא־תִגַּ֨ע בּ֜⁠וֹ יָ֗ד כִּֽי־סָק֤וֹל יִסָּקֵל֙ אוֹ־יָרֹ֣ה יִיָּרֶ֔ה אִם־בְּהֵמָ֥ה אִם־אִ֖ישׁ לֹ֣א יִחְיֶ֑ה בִּ⁠מְשֹׁךְ֙ הַ⁠יֹּבֵ֔ל הֵ֖מָּה יַעֲל֥וּ בָ⁠הָֽר׃","lòʼ-ţigȧ֨ʻ ḃ֜⁠wò yá֗d kiֽ̇y-sáq֤wòl yisá̇qél֙ ʼwò-yárò֣h yiyá̇re֔h ʼim-bĕ̇hémá֥h ʼim-ʼi֖yş̌ lò֣ʼ yiẖĕye֑h bi̇⁠mĕşò̌kĕ֙ ha⁠yò̇bé֔l hé֖má̇h yaʻàl֥ẇ bá⁠háֽr׃"],[19,14,"וַ⁠יֵּ֧רֶד מֹשֶׁ֛ה מִן־הָ⁠הָ֖ר אֶל־הָ⁠עָ֑ם וַ⁠יְקַדֵּשׁ֙ אֶת־הָ⁠עָ֔ם וַֽ⁠יְכַבְּס֖וּ שִׂמְלֹתָֽ⁠ם׃","wa⁠yé֧̇red mòşě֛h min-há⁠há֖r ʼel-há⁠ʻá֑m wa⁠yĕqadé̇ş̌֙ ʼeţ-há⁠ʻá֔m waֽ⁠yĕkabĕ̇s֖ẇ şîmĕlòţáֽ⁠m׃"],[19,15,"וַ⁠יֹּ֨אמֶר֙ אֶל־הָ⁠עָ֔ם הֱי֥וּ נְכֹנִ֖ים לִ⁠שְׁלֹ֣שֶׁת יָמִ֑ים אַֽל־תִּגְּשׁ֖וּ אֶל־אִשָּֽׁה׃","wa⁠yò̇֨ʼmer֙ ʼel-há⁠ʻá֔m hèy֥ẇ nĕkòni֖ym li⁠şĕ̌lò֣şěţ yámi֑ym ʼaֽl-ţi̇gĕ̇ş֖̌ẇ ʼel-ʼişáֽ̇̌h׃"],[19,16,"וַ⁠יְהִי֩ בַ⁠יּ֨וֹם הַ⁠שְּׁלִישִׁ֜י בִּֽ⁠הְיֹ֣ת הַ⁠בֹּ֗קֶר וַ⁠יְהִי֩ קֹלֹ֨ת וּ⁠בְרָקִ֜ים וְ⁠עָנָ֤ן כָּבֵד֙ עַל־הָ⁠הָ֔ר וְ⁠קֹ֥ל שֹׁפָ֖ר חָזָ֣ק מְאֹ֑ד וַ⁠יֶּחֱרַ֥ד כָּל־הָ⁠עָ֖ם אֲשֶׁ֥ר בַּֽ⁠מַּחֲנֶֽה׃","wa⁠yĕhiy֩ ba⁠ẏ֨wòm ha⁠şĕ̇̌liyşǐ֜y biֽ̇⁠hĕyò֣ţ ha⁠bò̇֗qer wa⁠yĕhiy֩ qòlò֨ţ ẇ⁠bĕráqi֜ym wĕ⁠ʻáná֤n ká̇béd֙ ʻal-há⁠há֔r wĕ⁠qò֥l şò̌pá֖r ẖázá֣q mĕʼò֑d wa⁠yėẖèra֥d ká̇l-há⁠ʻá֖m ʼàşě֥r bȧֽ⁠mȧẖàneֽh׃"],[19,17,"וַ⁠יּוֹצֵ֨א מֹשֶׁ֧ה אֶת־הָ⁠עָ֛ם לִ⁠קְרַ֥את הָֽ⁠אֱלֹהִ֖ים מִן־הַֽ⁠מַּחֲנֶ֑ה וַ⁠יִּֽתְיַצְּב֖וּ בְּ⁠תַחְתִּ֥ית הָ⁠הָֽר׃","wa⁠ẏwòẕé֨ʼ mòşě֧h ʼeţ-há⁠ʻá֛m li⁠qĕra֥ʼţ háֽ⁠ʼèlòhi֖ym min-haֽ⁠mȧẖàne֑h wa⁠yiֽ̇ţĕyaẕĕ̇b֖ẇ bĕ̇⁠ţaẖĕţi֥̇yţ há⁠háֽr׃"],[19,18,"וְ⁠הַ֤ר סִינַי֙ עָשַׁ֣ן כֻּלּ֔⁠וֹ מִ֠⁠פְּנֵי אֲשֶׁ֨ר יָרַ֥ד עָלָ֛י⁠ו יְהוָ֖ה בָּ⁠אֵ֑שׁ וַ⁠יַּ֤עַל עֲשָׁנ⁠וֹ֙ כְּ⁠עֶ֣שֶׁן הַ⁠כִּבְשָׁ֔ן וַ⁠יֶּחֱרַ֥ד כָּל־הָ⁠הָ֖ר מְאֹֽד׃","wĕ⁠ha֤r siynay֙ ʻáşǎ֣n ku̇l̇֔⁠wò mi֠⁠pĕ̇néy ʼàşě֨r yára֥d ʻálá֛y⁠w yĕhwá֖h bá̇⁠ʼé֑ş̌ wa⁠yȧ֤ʻal ʻàşá̌n⁠wò֙ kĕ̇⁠ʻe֣şěn ha⁠ki̇bĕşá̌֔n wa⁠yėẖèra֥d ká̇l-há⁠há֖r mĕʼòֽd׃"],[19,19,"וַ⁠יְהִי֙ ק֣וֹל הַ⁠שּׁוֹפָ֔ר הוֹלֵ֖ךְ וְ⁠חָזֵ֣ק מְאֹ֑ד מֹשֶׁ֣ה יְדַבֵּ֔ר וְ⁠הָ⁠אֱלֹהִ֖ים יַעֲנֶ֥⁠נּוּ בְ⁠קֽוֹל׃","wa⁠yĕhiy֙ q֣wòl ha⁠ş̇̌wòpá֔r hwòlé֖kĕ wĕ⁠ẖázé֣q mĕʼò֑d mòşě֣h yĕdabé̇֔r wĕ⁠há⁠ʼèlòhi֖ym yaʻàne֥⁠ṅẇ bĕ⁠qֽwòl׃"],[19,20,"וַ⁠יֵּ֧רֶד יְהוָ֛ה עַל־הַ֥ר סִינַ֖י אֶל־רֹ֣אשׁ הָ⁠הָ֑ר וַ⁠יִּקְרָ֨א יְהוָ֧ה לְ⁠מֹשֶׁ֛ה אֶל־רֹ֥אשׁ הָ⁠הָ֖ר וַ⁠יַּ֥עַל מֹשֶֽׁה׃","wa⁠yé֧̇red yĕhwá֛h ʻal-ha֥r siyna֖y ʼel-rò֣ʼş̌ há⁠há֑r wa⁠yi̇qĕrá֨ʼ yĕhwá֧h lĕ⁠mòşě֛h ʼel-rò֥ʼş̌ há⁠há֖r wa⁠yȧ֥ʻal mòşěֽh׃"],[19,21,"וַ⁠יֹּ֤אמֶר יְהוָה֙ אֶל־מֹשֶׁ֔ה רֵ֖ד הָעֵ֣ד בָּ⁠עָ֑ם פֶּן־יֶהֶרְס֤וּ אֶל־יְהוָה֙ לִ⁠רְא֔וֹת וְ⁠נָפַ֥ל מִמֶּ֖⁠נּוּ רָֽב׃","wa⁠yò֤̇ʼmer yĕhwáh֙ ʼel-mòşě֔h ré֖d háʻé֣d bá̇⁠ʻá֑m pėn-yeherĕs֤ẇ ʼel-yĕhwáh֙ li⁠rĕʼ֔wòţ wĕ⁠nápa֥l mimė֖⁠ṅẇ ráֽb׃"],[19,22,"וְ⁠גַ֧ם הַ⁠כֹּהֲנִ֛ים הַ⁠נִּגָּשִׁ֥ים אֶל־יְהוָ֖ה יִתְקַדָּ֑שׁוּ פֶּן־יִפְרֹ֥ץ בָּ⁠הֶ֖ם יְהוָֽה׃","wĕ⁠ga֧m ha⁠kò̇hàni֛ym ha⁠ni̇gá̇şǐ֥ym ʼel-yĕhwá֖h yiţĕqadá֑̇ş̌ẇ pėn-yipĕrò֥ẕ bá̇⁠he֖m yĕhwáֽh׃"],[19,23,"וַ⁠יֹּ֤אמֶר מֹשֶׁה֙ אֶל־יְהוָ֔ה לֹא־יוּכַ֣ל הָ⁠עָ֔ם לַ⁠עֲלֹ֖ת אֶל־הַ֣ר סִינָ֑י כִּֽי־אַתָּ֞ה הַעֵדֹ֤תָה בָּ֨⁠נוּ֙ לֵ⁠אמֹ֔ר הַגְבֵּ֥ל אֶת־הָ⁠הָ֖ר וְ⁠קִדַּשְׁתּֽ⁠וֹ׃","wa⁠yò֤̇ʼmer mòşěh֙ ʼel-yĕhwá֔h lòʼ-yẇka֣l há⁠ʻá֔m la⁠ʻàlò֖ţ ʼel-ha֣r siyná֑y kiֽ̇y-ʼaţá̇֞h haʻédò֤ţáh bá̇֨⁠nẇ֙ lé⁠ʼmò֔r hagĕbé֥̇l ʼeţ-há⁠há֖r wĕ⁠qidȧşĕ̌ţֽ̇⁠wò׃"],[19,24,"וַ⁠יֹּ֨אמֶר אֵלָ֤י⁠ו יְהוָה֙ לֶךְ־רֵ֔ד וְ⁠עָלִ֥יתָ אַתָּ֖ה וְ⁠אַהֲרֹ֣ן עִמָּ֑⁠ךְ וְ⁠הַ⁠כֹּהֲנִ֣ים וְ⁠הָ⁠עָ֗ם אַל־יֶֽהֶרְס֛וּ לַ⁠עֲלֹ֥ת אֶל־יְהוָ֖ה פֶּן־יִפְרָץ־בָּֽ⁠ם׃","wa⁠yò̇֨ʼmer ʼélá֤y⁠w yĕhwáh֙ lekĕ-ré֔d wĕ⁠ʻáli֥yţá ʼaţá֖̇h wĕ⁠ʼahàrò֣n ʻimá֑̇⁠kĕ wĕ⁠ha⁠kò̇hàni֣ym wĕ⁠há⁠ʻá֗m ʼal-yֽeherĕs֛ẇ la⁠ʻàlò֥ţ ʼel-yĕhwá֖h pėn-yipĕráẕ-báֽ̇⁠m׃"],[19,25,"וַ⁠יֵּ֥רֶד מֹשֶׁ֖ה אֶל־הָ⁠עָ֑ם וַ⁠יֹּ֖אמֶר אֲלֵ⁠הֶֽם׃ס","wa⁠yé֥̇red mòşě֖h ʼel-há⁠ʻá֑m wa⁠yò֖̇ʼmer ʼàlé⁠heֽm׃s"],[20,1,"וַ⁠יְדַבֵּ֣ר אֱלֹהִ֔ים אֵ֛ת כָּל־הַ⁠דְּבָרִ֥ים הָ⁠אֵ֖לֶּה לֵ⁠אמֹֽר׃ס","wa⁠yĕdabé֣̇r ʼèlòhi֔ym ʼé֛ţ ká̇l-ha⁠dĕ̇bári֥ym há⁠ʼé֖lėh lé⁠ʼmòֽr׃s"],[20,2,"אָֽנֹכִ֖י יְהוָ֣ה אֱלֹהֶ֑י⁠ךָ אֲשֶׁ֧ר הוֹצֵאתִ֛י⁠ךָ מֵ⁠אֶ֥רֶץ מִצְרַ֖יִם מִ⁠בֵּ֥ית עֲבָדִֽים׃","ʼáֽnòki֖y yĕhwá֣h ʼèlòhe֑y⁠ká ʼàşě֧r hwòẕéʼţi֛y⁠ká mé⁠ʼe֥reẕ miẕĕra֖yim mi⁠bé֥̇yţ ʻàbádiֽym׃"],[20,3,"לֹֽ֣א יִהְיֶֽה־לְ⁠ךָ֛ אֱלֹהִ֥ים אֲחֵרִ֖ים עַל־פָּנָֽ⁠יַ׃","lòֽ֣ʼ yihĕyeֽh-lĕ⁠ká֛ ʼèlòhi֥ym ʼàẖéri֖ym ʻal-pá̇náֽ⁠ya׃"],[20,4,"לֹֽ֣א תַֽעֲשֶׂ֨ה־לְ⁠ךָ֥ פֶ֨סֶל֙ וְ⁠כָל־תְּמוּנָ֔ה אֲשֶׁ֤ר בַּ⁠שָּׁמַ֨יִם֙ מִ⁠מַּ֔עַל וַ⁠אֲשֶׁ֥ר בָּ⁠אָ֖רֶץ מִ⁠תָּ֑חַת וַ⁠אֲשֶׁ֥ר בַּ⁠מַּ֖יִם מִ⁠תַּ֥חַת לָ⁠אָֽרֶץ׃","lòֽ֣ʼ ţֽaʻàşê֨h-lĕ⁠ká֥ pe֨sel֙ wĕ⁠kál-ţĕ̇mẇná֔h ʼàşě֤r bȧ⁠şá̇̌ma֨yim֙ mi⁠mȧ֔ʻal wa⁠ʼàşě֥r bá̇⁠ʼá֖reẕ mi⁠ţá֑̇ẖaţ wa⁠ʼàşě֥r bȧ⁠mȧ֖yim mi⁠ţȧ֥ẖaţ lá⁠ʼáֽreẕ׃"],[20,5,"לֹֽא־תִשְׁתַּחֲוֶ֥ה לָ⁠הֶ֖ם וְ⁠לֹ֣א תָעָבְדֵ֑⁠ם כִּ֣י אָֽנֹכִ֞י יְהוָ֤ה אֱלֹהֶ֨י⁠ךָ֙ אֵ֣ל קַנָּ֔א פֹּ֠קֵד עֲוֺ֨ן אָבֹ֧ת עַל־בָּנִ֛ים עַל־שִׁלֵּשִׁ֥ים וְ⁠עַל־רִבֵּעִ֖ים לְ⁠שֹׂנְאָֽ⁠י׃","lòֽʼ-ţişĕ̌ţȧẖàwe֥h lá⁠he֖m wĕ⁠lò֣ʼ ţáʻábĕdé֑⁠m ki֣̇y ʼֽánòki֞y yĕhwá֤h ʼèlòhe֨y⁠ká֙ ʼé֣l qaná̇֔ʼ pò̇֠qéd ʻàwֺ֨n ʼábò֧ţ ʻal-bá̇ni֛ym ʻal-şǐlé̇şǐ֥ym wĕ⁠ʻal-ribé̇ʻi֖ym lĕ⁠şò̂nĕʼáֽ⁠y׃"],[20,6,"וְ⁠עֹ֥שֶׂה חֶ֖סֶד לַ⁠אֲלָפִ֑ים לְ⁠אֹהֲבַ֖⁠י וּ⁠לְ⁠שֹׁמְרֵ֥י מִצְוֺתָֽ⁠י׃ס","wĕ⁠ʻò֥şêh ẖe֖sed la⁠ʼàlápi֑ym lĕ⁠ʼòhàba֖⁠y ẇ⁠lĕ⁠şò̌mĕré֥y miẕĕwֺţáֽ⁠y׃s"],[20,7,"לֹ֥א תִשָּׂ֛א אֶת־שֵֽׁם־יְהוָ֥ה אֱלֹהֶ֖י⁠ךָ לַ⁠שָּׁ֑וְא כִּ֣י לֹ֤א יְנַקֶּה֙ יְהוָ֔ה אֵ֛ת אֲשֶׁר־יִשָּׂ֥א אֶת־שְׁמ֖⁠וֹ לַ⁠שָּֽׁוְא׃פ","lò֥ʼ ţişá֛̇̂ʼ ʼeţ-şéֽ̌m-yĕhwá֥h ʼèlòhe֖y⁠ká la⁠şá֑̇̌wĕʼ ki֣̇y lò֤ʼ yĕnaqėh֙ yĕhwá֔h ʼé֛ţ ʼàşěr-yişá֥̇̂ʼ ʼeţ-şĕ̌m֖⁠wò la⁠şáֽ̇̌wĕʼ׃p"],[20,8,"זָכ֛וֹר אֶת־י֥וֹם הַ⁠שַּׁבָּ֖ת לְ⁠קַדְּשֽׁ⁠וֹ׃","zák֛wòr ʼeţ-y֥wòm ha⁠şȧ̌bá֖̇ţ lĕ⁠qadĕ̇şֽ̌⁠wò׃"],[20,9,"שֵׁ֤שֶׁת יָמִים֙ תַּֽעֲבֹ֔ד וְ⁠עָשִׂ֖יתָ כָּל־מְלַאכְתֶּֽ⁠ךָ׃","şé֤̌şěţ yámiym֙ ţֽ̇aʻàbò֔d wĕ⁠ʻáşî֖yţá ká̇l-mĕlaʼkĕţėֽ⁠ká׃"],[20,10,"וְ⁠י֨וֹם֙ הַ⁠שְּׁבִיעִ֔י שַׁבָּ֖ת לַ⁠יהוָ֣ה אֱלֹהֶ֑י⁠ךָ לֹֽ֣א־תַעֲשֶׂ֨ה כָל־מְלָאכָ֜ה אַתָּ֣ה ׀ וּ⁠בִנְ⁠ךָֽ֣־וּ⁠בִתֶּ֗⁠ךָ עַבְדְּ⁠ךָ֤ וַ⁠אֲמָֽתְ⁠ךָ֙ וּ⁠בְהֶמְתֶּ֔⁠ךָ וְ⁠גֵרְ⁠ךָ֖ אֲשֶׁ֥ר בִּ⁠שְׁעָרֶֽי⁠ךָ׃","wĕ⁠y֨wòm֙ ha⁠şĕ̇̌biyʻi֔y şǎbá֖̇ţ la⁠yhwá֣h ʼèlòhe֑y⁠ká lòֽ֣ʼ-ţaʻàşê֨h kál-mĕláʼká֜h ʼaţá֣̇h ׀ ẇ⁠binĕ⁠káֽ֣-ẇ⁠biţė֗⁠ká ʻabĕdĕ̇⁠ká֤ wa⁠ʼàmáֽţĕ⁠ká֙ ẇ⁠bĕhemĕţė֔⁠ká wĕ⁠gérĕ⁠ká֖ ʼàşě֥r bi̇⁠şĕ̌ʻáreֽy⁠ká׃"],[20,11,"כִּ֣י שֵֽׁשֶׁת־יָמִים֩ עָשָׂ֨ה יְהוָ֜ה אֶת־הַ⁠שָּׁמַ֣יִם וְ⁠אֶת־הָ⁠אָ֗רֶץ אֶת־הַ⁠יָּם֙ וְ⁠אֶת־כָּל־אֲשֶׁר־בָּ֔⁠ם וַ⁠יָּ֖נַח בַּ⁠יּ֣וֹם הַ⁠שְּׁבִיעִ֑י עַל־כֵּ֗ן בֵּרַ֧ךְ יְהוָ֛ה אֶת־י֥וֹם הַ⁠שַּׁבָּ֖ת וַֽ⁠יְקַדְּשֵֽׁ⁠הוּ׃ס","ki֣̇y şéֽ̌şěţ-yámiym֩ ʻáşá̂֨h yĕhwá֜h ʼeţ-ha⁠şá̇̌ma֣yim wĕ⁠ʼeţ-há⁠ʼá֗reẕ ʼeţ-ha⁠yá̇m֙ wĕ⁠ʼeţ-ká̇l-ʼàşěr-bá̇֔⁠m wa⁠yá֖̇naẖ bȧ⁠ẏ֣wòm ha⁠şĕ̇̌biyʻi֑y ʻal-ké̇֗n bé̇ra֧kĕ yĕhwá֛h ʼeţ-y֥wòm ha⁠şȧ̌bá֖̇ţ waֽ⁠yĕqadĕ̇şéֽ̌⁠hẇ׃s"],[20,12,"כַּבֵּ֥ד אֶת־אָבִ֖י⁠ךָ וְ⁠אֶת־אִמֶּ֑⁠ךָ לְמַ֨עַן֙ יַאֲרִכ֣וּ⁠ן יָמֶ֔י⁠ךָ עַ֚ל הָ⁠אֲדָמָ֔ה אֲשֶׁר־יְהוָ֥ה אֱלֹהֶ֖י⁠ךָ נֹתֵ֥ן לָֽ⁠ךְ׃ס","kȧbé֥̇d ʼeţ-ʼábi֖y⁠ká wĕ⁠ʼeţ-ʼimė֑⁠ká lĕma֨ʻan֙ yaʼàrik֣ẇ⁠n yáme֔y⁠ká ʻa֚l há⁠ʼàdámá֔h ʼàşěr-yĕhwá֥h ʼèlòhe֖y⁠ká nòţé֥n láֽ⁠kĕ׃s"],[20,13,"לֹ֖א תִּרְצָֽח׃ס","lò֖ʼ ţi̇rĕẕáֽẖ׃s"],[20,14,"לֹ֖א תִּנְאָֽף׃ס","lò֖ʼ ţi̇nĕʼáֽp׃s"],[20,15,"לֹ֖א תִּגְנֹֽב׃ס","lò֖ʼ ţi̇gĕnòֽb׃s"],[20,16,"לֹֽא־תַעֲנֶ֥ה בְ⁠רֵעֲ⁠ךָ֖ עֵ֥ד שָֽׁקֶר׃ס","lòֽʼ-ţaʻàne֥h bĕ⁠réʻà⁠ká֖ ʻé֥d şáֽ̌qer׃s"],[20,17,"לֹ֥א תַחְמֹ֖ד בֵּ֣ית רֵעֶ֑⁠ךָ לֹֽא־תַחְמֹ֞ד אֵ֣שֶׁת רֵעֶ֗⁠ךָ וְ⁠עַבְדּ֤⁠וֹ וַ⁠אֲמָת⁠וֹ֙ וְ⁠שׁוֹר֣⁠וֹ וַ⁠חֲמֹר֔⁠וֹ וְ⁠כֹ֖ל אֲשֶׁ֥ר לְ⁠רֵעֶֽ⁠ךָ׃פ","lò֥ʼ ţaẖĕmò֖d bé֣̇yţ réʻe֑⁠ká lòֽʼ-ţaẖĕmò֞d ʼé֣şěţ réʻe֗⁠ká wĕ⁠ʻabĕḋ֤⁠wò wa⁠ʼàmáţ⁠wò֙ wĕ⁠ş̌wòr֣⁠wò wa⁠ẖàmòr֔⁠wò wĕ⁠kò֖l ʼàşě֥r lĕ⁠réʻeֽ⁠ká׃p"],[20,18,"וְ⁠כָל־הָ⁠עָם֩ רֹאִ֨ים אֶת־הַ⁠קּוֹלֹ֜ת וְ⁠אֶת־הַ⁠לַּפִּידִ֗ם וְ⁠אֵת֙ ק֣וֹל הַ⁠שֹּׁפָ֔ר וְ⁠אֶת־הָ⁠הָ֖ר עָשֵׁ֑ן וַ⁠יַּ֤רְא הָ⁠עָם֙ וַ⁠יָּנֻ֔עוּ וַ⁠יַּֽעַמְד֖וּ מֵֽ⁠רָחֹֽק׃","wĕ⁠kál-há⁠ʻám֩ ròʼi֨ym ʼeţ-ha⁠q̇wòlò֜ţ wĕ⁠ʼeţ-ha⁠lȧpi̇ydi֗m wĕ⁠ʼéţ֙ q֣wòl ha⁠şò̇̌pá֔r wĕ⁠ʼeţ-há⁠há֖r ʻáşé֑̌n wa⁠yȧ֤rĕʼ há⁠ʻám֙ wa⁠yá̇nu֔ʻẇ wa⁠ẏֽaʻamĕd֖ẇ méֽ⁠ráẖòֽq׃"],[20,19,"וַ⁠יֹּֽאמְרוּ֙ אֶל־מֹשֶׁ֔ה דַּבֵּר־אַתָּ֥ה עִמָּ֖⁠נוּ וְ⁠נִשְׁמָ֑עָה וְ⁠אַל־יְדַבֵּ֥ר עִמָּ֛⁠נוּ אֱלֹהִ֖ים פֶּן־נָמֽוּת׃","wa⁠yòֽ̇ʼmĕrẇ֙ ʼel-mòşě֔h dȧbé̇r-ʼaţá֥̇h ʻimá֖̇⁠nẇ wĕ⁠nişĕ̌má֑ʻáh wĕ⁠ʼal-yĕdabé֥̇r ʻimá֛̇⁠nẇ ʼèlòhi֖ym pėn-námֽẇţ׃"],[20,20,"וַ⁠יֹּ֨אמֶר מֹשֶׁ֣ה אֶל־הָ⁠עָם֮ אַל־תִּירָאוּ֒ כִּ֗י לְ⁠בַֽ⁠עֲבוּר֙ נַסּ֣וֹת אֶתְ⁠כֶ֔ם בָּ֖א הָ⁠אֱלֹהִ֑ים וּ⁠בַ⁠עֲב֗וּר תִּהְיֶ֧ה יִרְאָת֛⁠וֹ עַל־פְּנֵי⁠כֶ֖ם לְ⁠בִלְתִּ֥י תֶחֱטָֽאוּ׃","wa⁠yò̇֨ʼmer mòşě֣h ʼel-há⁠ʻám֮ ʼal-ţi̇yráʼẇ֒ ki̇֗y lĕ⁠baֽ⁠ʻàbẇr֙ naṡ֣wòţ ʼeţĕ⁠ke֔m bá֖̇ʼ há⁠ʼèlòhi֑ym ẇ⁠ba⁠ʻàb֗ẇr ţi̇hĕye֧h yirĕʼáţ֛⁠wò ʻal-pĕ̇néy⁠ke֖m lĕ⁠bilĕţi֥̇y ţeẖètáֽʼẇ׃"],[20,21,"וַ⁠יַּעֲמֹ֥ד הָ⁠עָ֖ם מֵ⁠רָחֹ֑ק וּ⁠מֹשֶׁה֙ נִגַּ֣שׁ אֶל־הָֽ⁠עֲרָפֶ֔ל אֲשֶׁר־שָׁ֖ם הָ⁠אֱלֹהִֽים׃פ","wa⁠yȧʻàmò֥d há⁠ʻá֖m mé⁠ráẖò֑q ẇ⁠mòşěh֙ nigȧ֣ş̌ ʼel-háֽ⁠ʻàrápe֔l ʼàşěr-şá֖̌m há⁠ʼèlòhiֽym׃p"],[20,22,"וַ⁠יֹּ֤אמֶר יְהוָה֙ אֶל־מֹשֶׁ֔ה כֹּ֥ה תֹאמַ֖ר אֶל־בְּנֵ֣י יִשְׂרָאֵ֑ל אַתֶּ֣ם רְאִיתֶ֔ם כִּ֚י מִן־הַ⁠שָּׁמַ֔יִם דִּבַּ֖רְתִּי עִמָּ⁠כֶֽם׃","wa⁠yò֤̇ʼmer yĕhwáh֙ ʼel-mòşě֔h kò֥̇h ţòʼma֖r ʼel-bĕ̇né֣y yişĕ̂ráʼé֑l ʼaţė֣m rĕʼiyţe֔m ki֚̇y min-ha⁠şá̇̌ma֔yim di̇bȧ֖rĕţi̇y ʻimá̇⁠keֽm׃"],[20,23,"לֹ֥א תַעֲשׂ֖וּ⁠ן אִתִּ֑⁠י אֱלֹ֤הֵי כֶ֨סֶף֙ וֵ⁠אלֹהֵ֣י זָהָ֔ב לֹ֥א תַעֲשׂ֖וּ לָ⁠כֶֽם׃","lò֥ʼ ţaʻàş֖̂ẇ⁠n ʼiţi֑̇⁠y ʼèlò֤héy ke֨sep֙ wé⁠ʼlòhé֣y záhá֔b lò֥ʼ ţaʻàş֖̂ẇ lá⁠keֽm׃"],[20,24,"מִזְבַּ֣ח אֲדָמָה֮ תַּעֲשֶׂה־לִּ⁠י֒ וְ⁠זָבַחְתָּ֣ עָלָ֗י⁠ו אֶת־עֹלֹתֶ֨י⁠ךָ֙ וְ⁠אֶת־שְׁלָמֶ֔י⁠ךָ אֶת־צֹֽאנְ⁠ךָ֖ וְ⁠אֶת־בְּקָרֶ֑⁠ךָ בְּ⁠כָל־הַ⁠מָּקוֹם֙ אֲשֶׁ֣ר אַזְכִּ֣יר אֶת־שְׁמִ֔⁠י אָב֥וֹא אֵלֶ֖י⁠ךָ וּ⁠בֵרַכְתִּֽי⁠ךָ׃","mizĕbȧ֣ẖ ʼàdámáh֮ ţȧʻàşêh-li̇⁠y֒ wĕ⁠zábaẖĕţá֣̇ ʻálá֗y⁠w ʼeţ-ʻòlòţe֨y⁠ká֙ wĕ⁠ʼeţ-şĕ̌láme֔y⁠ká ʼeţ-ẕòֽʼnĕ⁠ká֖ wĕ⁠ʼeţ-bĕ̇qáre֑⁠ká bĕ̇⁠kál-ha⁠má̇qwòm֙ ʼàşě֣r ʼazĕki֣̇yr ʼeţ-şĕ̌mi֔⁠y ʼáb֥wòʼ ʼéle֖y⁠ká ẇ⁠bérakĕţiֽ̇y⁠ká׃"],[20,25,"וְ⁠אִם־מִזְבַּ֤ח אֲבָנִים֙ תַּֽעֲשֶׂה־לִּ֔⁠י לֹֽא־תִבְנֶ֥ה אֶתְ⁠הֶ֖ן גָּזִ֑ית כִּ֧י חַרְבְּ⁠ךָ֛ הֵנַ֥פְתָּ עָלֶ֖י⁠הָ וַ⁠תְּחַֽלְלֶֽ⁠הָ׃","wĕ⁠ʼim-mizĕbȧ֤ẖ ʼàbániym֙ ţȧֽʻàşêh-li̇֔⁠y lòֽʼ-ţibĕne֥h ʼeţĕ⁠he֖n gá̇zi֑yţ ki֧̇y ẖarĕbĕ̇⁠ká֛ héna֥pĕţá̇ ʻále֖y⁠há wa⁠ţĕ̇ẖaֽlĕleֽ⁠há׃"],[20,26,"וְ⁠לֹֽא־תַעֲלֶ֥ה בְ⁠מַעֲלֹ֖ת עַֽל־מִזְבְּחִ֑⁠י אֲשֶׁ֛ר לֹֽא־תִגָּלֶ֥ה עֶרְוָתְ⁠ךָ֖ עָלָֽי⁠ו׃פ","wĕ⁠lòֽʼ-ţaʻàle֥h bĕ⁠maʻàlò֖ţ ʻaֽl-mizĕbĕ̇ẖi֑⁠y ʼàşě֛r lòֽʼ-ţigá̇le֥h ʻerĕwáţĕ⁠ká֖ ʻáláֽy⁠w׃p"],[21,1,"וְ⁠אֵ֨לֶּה֙ הַ⁠מִּשְׁפָּטִ֔ים אֲשֶׁ֥ר תָּשִׂ֖ים לִ⁠פְנֵי⁠הֶֽם׃","wĕ⁠ʼé֨lėh֙ ha⁠mi̇şĕ̌pá̇ti֔ym ʼàşě֥r ţá̇şî֖ym li⁠pĕnéy⁠heֽm׃"],[21,2,"כִּ֤י תִקְנֶה֙ עֶ֣בֶד עִבְרִ֔י שֵׁ֥שׁ שָׁנִ֖ים יַעֲבֹ֑ד וּ⁠בַ֨⁠שְּׁבִעִ֔ת יֵצֵ֥א לַֽ⁠חָפְשִׁ֖י חִנָּֽם׃","ki֤̇y ţiqĕneh֙ ʻe֣bed ʻibĕri֔y şé֥̌ş̌ şá̌ni֖ym yaʻàbò֑d ẇ⁠ba֨⁠şĕ̇̌biʻi֔ţ yéẕé֥ʼ laֽ⁠ẖápĕşǐ֖y ẖináֽ̇m׃"],[21,3,"אִם־בְּ⁠גַפּ֥⁠וֹ יָבֹ֖א בְּ⁠גַפּ֣⁠וֹ יֵצֵ֑א אִם־בַּ֤עַל אִשָּׁה֙ ה֔וּא וְ⁠יָצְאָ֥ה אִשְׁתּ֖⁠וֹ עִמּֽ⁠וֹ׃","ʼim-bĕ̇⁠gaṗ֥⁠wò yábò֖ʼ bĕ̇⁠gaṗ֣⁠wò yéẕé֑ʼ ʼim-bȧ֤ʻal ʼişá̇̌h֙ h֔ẇʼ wĕ⁠yáẕĕʼá֥h ʼişĕ̌ţ֖̇⁠wò ʻiṁֽ⁠wò׃"],[21,4,"אִם־אֲדֹנָי⁠ו֙ יִתֶּן־ל֣⁠וֹ אִשָּׁ֔ה וְ⁠יָלְדָה־ל֥⁠וֹ בָנִ֖ים א֣וֹ בָנ֑וֹת הָ⁠אִשָּׁ֣ה וִ⁠ילָדֶ֗י⁠הָ תִּהְיֶה֙ לַֽ⁠אדֹנֶ֔י⁠הָ וְ⁠ה֖וּא יֵצֵ֥א בְ⁠גַפּֽ⁠וֹ׃","ʼim-ʼàdònáy⁠w֙ yiţėn-l֣⁠wò ʼişá̇̌֔h wĕ⁠yálĕdáh-l֥⁠wò báni֖ym ʼ֣wò bán֑wòţ há⁠ʼişá֣̇̌h wi⁠yláde֗y⁠há ţi̇hĕyeh֙ laֽ⁠ʼdòne֔y⁠há wĕ⁠h֖ẇʼ yéẕé֥ʼ bĕ⁠gaṗֽ⁠wò׃"],[21,5,"וְ⁠אִם־אָמֹ֤ר יֹאמַר֙ הָ⁠עֶ֔בֶד אָהַ֨בְתִּי֙ אֶת־אֲדֹנִ֔⁠י אֶת־אִשְׁתִּ֖⁠י וְ⁠אֶת־בָּנָ֑⁠י לֹ֥א אֵצֵ֖א חָפְשִֽׁי׃","wĕ⁠ʼim-ʼámò֤r yòʼmar֙ há⁠ʻe֔bed ʼáha֨bĕţi̇y֙ ʼeţ-ʼàdòni֔⁠y ʼeţ-ʼişĕ̌ţi֖̇⁠y wĕ⁠ʼeţ-bá̇ná֑⁠y lò֥ʼ ʼéẕé֖ʼ ẖápĕşǐֽy׃"],[21,6,"וְ⁠הִגִּישׁ֤⁠וֹ אֲדֹנָי⁠ו֙ אֶל־הָ֣⁠אֱלֹהִ֔ים וְ⁠הִגִּישׁ⁠וֹ֙ אֶל־הַ⁠דֶּ֔לֶת א֖וֹ אֶל־הַ⁠מְּזוּזָ֑ה וְ⁠רָצַ֨ע אֲדֹנָ֤י⁠ו אֶת־אָזְנ⁠וֹ֙ בַּ⁠מַּרְצֵ֔עַ וַ⁠עֲבָד֖⁠וֹ לְ⁠עֹלָֽם׃ס","wĕ⁠higi̇yş֤̌⁠wò ʼàdònáy⁠w֙ ʼel-há֣⁠ʼèlòhi֔ym wĕ⁠higi̇yş̌⁠wò֙ ʼel-ha⁠dė֔leţ ʼ֖wò ʼel-ha⁠mĕ̇zẇzá֑h wĕ⁠ráẕa֨ʻ ʼàdòná֤y⁠w ʼeţ-ʼázĕn⁠wò֙ bȧ⁠mȧrĕẕé֔ʻa wa⁠ʻàbád֖⁠wò lĕ⁠ʻòláֽm׃s"],[21,7,"וְ⁠כִֽי־יִמְכֹּ֥ר אִ֛ישׁ אֶת־בִּתּ֖⁠וֹ לְ⁠אָמָ֑ה לֹ֥א תֵצֵ֖א כְּ⁠צֵ֥את הָ⁠עֲבָדִֽים׃","wĕ⁠kiֽy-yimĕkò֥̇r ʼi֛yş̌ ʼeţ-bi̇ţ֖̇⁠wò lĕ⁠ʼámá֑h lò֥ʼ ţéẕé֖ʼ kĕ̇⁠ẕé֥ʼţ há⁠ʻàbádiֽym׃"],[21,8,"אִם־רָעָ֞ה בְּ⁠עֵינֵ֧י אֲדֹנֶ֛י⁠הָ אֲשֶׁר־לא יְעָדָ֖⁠הּ וְ⁠הֶפְדָּ֑⁠הּ לְ⁠עַ֥ם נָכְרִ֛י לֹא־יִמְשֹׁ֥ל לְ⁠מָכְרָ֖⁠הּ בְּ⁠בִגְד⁠וֹ־בָֽ⁠הּ׃","ʼim-ráʻá֞h bĕ̇⁠ʻéyné֧y ʼàdòne֛y⁠há ʼàşěr-lʼ yĕʻádá֖⁠ḣ wĕ⁠hepĕdá֑̇⁠ḣ lĕ⁠ʻa֥m nákĕri֛y lòʼ-yimĕşò֥̌l lĕ⁠mákĕrá֖⁠ḣ bĕ̇⁠bigĕd⁠wò-báֽ⁠ḣ׃"],[21,9,"וְ⁠אִם־לִ⁠בְנ֖⁠וֹ יִֽיעָדֶ֑⁠נָּה כְּ⁠מִשְׁפַּ֥ט הַ⁠בָּנ֖וֹת יַעֲשֶׂה־לָּֽ⁠הּ׃","wĕ⁠ʼim-li⁠bĕn֖⁠wò yiֽyʻáde֑⁠ná̇h kĕ̇⁠mişĕ̌pȧ֥t ha⁠bá̇n֖wòţ yaʻàşêh-láֽ̇⁠ḣ׃"],[21,10,"אִם־אַחֶ֖רֶת יִֽקַּֽח־ל֑⁠וֹ שְׁאֵרָ֛⁠הּ כְּסוּתָ֥⁠הּ וְ⁠עֹנָתָ֖⁠הּ לֹ֥א יִגְרָֽע׃","ʼim-ʼaẖe֖reţ yiֽqȧֽẖ-l֑⁠wò şĕ̌ʼérá֛⁠ḣ kĕ̇sẇţá֥⁠ḣ wĕ⁠ʻònáţá֖⁠ḣ lò֥ʼ yigĕráֽʻ׃"],[21,11,"וְ⁠אִם־שְׁלָ֨שׁ־אֵ֔לֶּה לֹ֥א יַעֲשֶׂ֖ה לָ֑⁠הּ וְ⁠יָצְאָ֥ה חִנָּ֖ם אֵ֥ין כָּֽסֶף׃ס","wĕ⁠ʼim-şĕ̌lá֨ş̌-ʼé֔lėh lò֥ʼ yaʻàşê֖h lá֑⁠ḣ wĕ⁠yáẕĕʼá֥h ẖiná֖̇m ʼé֥yn káֽ̇sep׃s"],[21,12,"מַכֵּ֥ה אִ֛ישׁ וָ⁠מֵ֖ת מ֥וֹת יוּמָֽת׃","maké֥̇h ʼi֛yş̌ wá⁠mé֖ţ m֥wòţ yẇmáֽţ׃"],[21,13,"וַ⁠אֲשֶׁר֙ לֹ֣א צָדָ֔ה וְ⁠הָ⁠אֱלֹהִ֖ים אִנָּ֣ה לְ⁠יָד֑⁠וֹ וְ⁠שַׂמְתִּ֤י לְ⁠ךָ֙ מָק֔וֹם אֲשֶׁ֥ר יָנ֖וּס שָֽׁמָּ⁠ה׃ס","wa⁠ʼàşěr֙ lò֣ʼ ẕádá֔h wĕ⁠há⁠ʼèlòhi֖ym ʼiná֣̇h lĕ⁠yád֑⁠wò wĕ⁠şâmĕţi֤̇y lĕ⁠ká֙ máq֔wòm ʼàşě֥r yán֖ẇs şáֽ̌má̇⁠h׃s"],[21,14,"וְ⁠כִֽי־יָזִ֥ד אִ֛ישׁ עַל־רֵעֵ֖⁠הוּ לְ⁠הָרְג֣⁠וֹ בְ⁠עָרְמָ֑ה מֵ⁠עִ֣ם מִזְבְּחִ֔⁠י תִּקָּחֶ֖⁠נּוּ לָ⁠מֽוּת׃ס","wĕ⁠kiֽy-yázi֥d ʼi֛yş̌ ʻal-réʻé֖⁠hẇ lĕ⁠hárĕg֣⁠wò bĕ⁠ʻárĕmá֑h mé⁠ʻi֣m mizĕbĕ̇ẖi֔⁠y ţi̇qá̇ẖe֖⁠ṅẇ lá⁠mֽẇţ׃s"],[21,15,"וּ⁠מַכֵּ֥ה אָבִ֛י⁠ו וְ⁠אִמּ֖⁠וֹ מ֥וֹת יוּמָֽת׃","ẇ⁠maké֥̇h ʼábi֛y⁠w wĕ⁠ʼiṁ֖⁠wò m֥wòţ yẇmáֽţ׃"],[21,16,"וְ⁠גֹנֵ֨ב אִ֧ישׁ וּ⁠מְכָר֛⁠וֹ וְ⁠נִמְצָ֥א בְ⁠יָד֖⁠וֹ מ֥וֹת יוּמָֽת׃ס","wĕ⁠gòné֨b ʼi֧yş̌ ẇ⁠mĕkár֛⁠wò wĕ⁠nimĕẕá֥ʼ bĕ⁠yád֖⁠wò m֥wòţ yẇmáֽţ׃s"],[21,17,"וּ⁠מְקַלֵּ֥ל אָבִ֛י⁠ו וְ⁠אִמּ֖⁠וֹ מ֥וֹת יוּמָֽת׃ס","ẇ⁠mĕqalé֥̇l ʼábi֛y⁠w wĕ⁠ʼiṁ֖⁠wò m֥wòţ yẇmáֽţ׃s"],[21,18,"וְ⁠כִֽי־יְרִיבֻ֣⁠ן אֲנָשִׁ֔ים וְ⁠הִכָּה־אִישׁ֙ אֶת־רֵעֵ֔⁠הוּ בְּ⁠אֶ֖בֶן א֣וֹ בְ⁠אֶגְרֹ֑ף וְ⁠לֹ֥א יָמ֖וּת וְ⁠נָפַ֥ל לְ⁠מִשְׁכָּֽב׃","wĕ⁠kiֽy-yĕriybu֣⁠n ʼànáşǐ֔ym wĕ⁠hiká̇h-ʼiyş̌֙ ʼeţ-réʻé֔⁠hẇ bĕ̇⁠ʼe֖ben ʼ֣wò bĕ⁠ʼegĕrò֑p wĕ⁠lò֥ʼ yám֖ẇţ wĕ⁠nápa֥l lĕ⁠mişĕ̌káֽ̇b׃"],[21,19,"אִם־יָק֞וּם וְ⁠הִתְהַלֵּ֥ךְ בַּ⁠ח֛וּץ עַל־מִשְׁעַנְתּ֖⁠וֹ וְ⁠נִקָּ֣ה הַ⁠מַּכֶּ֑ה רַ֥ק שִׁבְתּ֛⁠וֹ יִתֵּ֖ן וְ⁠רַפֹּ֥א יְרַפֵּֽא׃ס","ʼim-yáq֞ẇm wĕ⁠hiţĕhalé֥̇kĕ bȧ⁠ẖ֛ẇẕ ʻal-mişĕ̌ʻanĕţ֖̇⁠wò wĕ⁠niqá֣̇h ha⁠mȧkė֑h ra֥q şǐbĕţ֛̇⁠wò yiţé֖̇n wĕ⁠rapò֥̇ʼ yĕrapéֽ̇ʼ׃s"],[21,20,"וְ⁠כִֽי־יַכֶּה֩ אִ֨ישׁ אֶת־עַבְדּ֜⁠וֹ א֤וֹ אֶת־אֲמָת⁠וֹ֙ בַּ⁠שֵּׁ֔בֶט וּ⁠מֵ֖ת תַּ֣חַת יָד֑⁠וֹ נָקֹ֖ם יִנָּקֵֽם׃","wĕ⁠kiֽy-yakėh֩ ʼi֨yş̌ ʼeţ-ʻabĕḋ֜⁠wò ʼ֤wò ʼeţ-ʼàmáţ⁠wò֙ bȧ⁠şé̇̌֔bet ẇ⁠mé֖ţ ţȧ֣ẖaţ yád֑⁠wò náqò֖m yiná̇qéֽm׃"],[21,21,"אַ֥ךְ אִם־י֛וֹם א֥וֹ יוֹמַ֖יִם יַעֲמֹ֑ד לֹ֣א יֻקַּ֔ם כִּ֥י כַסְפּ֖⁠וֹ הֽוּא׃ס","ʼa֥kĕ ʼim-y֛wòm ʼ֥wò ywòma֖yim yaʻàmò֑d lò֣ʼ yuqȧ֔m ki֥̇y kasĕṗ֖⁠wò hֽẇʼ׃s"],[21,22,"וְ⁠כִֽי־יִנָּצ֣וּ אֲנָשִׁ֗ים וְ⁠נָ֨גְפ֜וּ אִשָּׁ֤ה הָרָה֙ וְ⁠יָצְא֣וּ יְלָדֶ֔י⁠הָ וְ⁠לֹ֥א יִהְיֶ֖ה אָס֑וֹן עָנ֣וֹשׁ יֵעָנֵ֗שׁ כַּֽ⁠אֲשֶׁ֨ר יָשִׁ֤ית עָלָי⁠ו֙ בַּ֣עַל הָֽ⁠אִשָּׁ֔ה וְ⁠נָתַ֖ן בִּ⁠פְלִלִֽים׃","wĕ⁠kiֽy-yiná̇ẕ֣ẇ ʼànáşǐ֗ym wĕ⁠ná֨gĕp֜ẇ ʼişá֤̇̌h háráh֙ wĕ⁠yáẕĕʼ֣ẇ yĕláde֔y⁠há wĕ⁠lò֥ʼ yihĕye֖h ʼás֑wòn ʻán֣wòş̌ yéʻáné֗ş̌ kֽ̇a⁠ʼàşě֨r yáşǐ֤yţ ʻáláy⁠w֙ bȧ֣ʻal háֽ⁠ʼişá̇̌֔h wĕ⁠náţa֖n bi̇⁠pĕliliֽym׃"],[21,23,"וְ⁠אִם־אָס֖וֹן יִהְיֶ֑ה וְ⁠נָתַתָּ֥ה נֶ֖פֶשׁ תַּ֥חַת נָֽפֶשׁ׃","wĕ⁠ʼim-ʼás֖wòn yihĕye֑h wĕ⁠náţaţá֥̇h ne֖peş̌ ţȧ֥ẖaţ náֽpeş̌׃"],[21,24,"עַ֚יִן תַּ֣חַת עַ֔יִן שֵׁ֖ן תַּ֣חַת שֵׁ֑ן יָ֚ד תַּ֣חַת יָ֔ד רֶ֖גֶל תַּ֥חַת רָֽגֶל׃","ʻa֚yin ţȧ֣ẖaţ ʻa֔yin şé֖̌n ţȧ֣ẖaţ şé֑̌n yá֚d ţȧ֣ẖaţ yá֔d re֖gel ţȧ֥ẖaţ ráֽgel׃"],[21,25,"כְּוִיָּה֙ תַּ֣חַת כְּוִיָּ֔ה פֶּ֖צַע תַּ֣חַת פָּ֑צַע חַבּוּרָ֕ה תַּ֖חַת חַבּוּרָֽה׃ס","kĕ̇wiyá̇h֙ ţȧ֣ẖaţ kĕ̇wiyá̇֔h pė֖ẕaʻ ţȧ֣ẖaţ pá֑̇ẕaʻ ẖaḃẇrá֕h ţȧ֖ẖaţ ẖaḃẇráֽh׃s"],[21,26,"וְ⁠כִֽי־יַכֶּ֨ה אִ֜ישׁ אֶת־עֵ֥ין עַבְדּ֛⁠וֹ אֽוֹ־אֶת־עֵ֥ין אֲמָת֖⁠וֹ וְ⁠שִֽׁחֲתָ֑⁠הּ לַֽ⁠חָפְשִׁ֥י יְשַׁלְּחֶ֖⁠נּוּ תַּ֥חַת עֵינֽ⁠וֹ׃ס","wĕ⁠kiֽy-yakė֨h ʼi֜yş̌ ʼeţ-ʻé֥yn ʻabĕḋ֛⁠wò ʼֽwò-ʼeţ-ʻé֥yn ʼàmáţ֖⁠wò wĕ⁠şǐֽẖàţá֑⁠ḣ lֽa⁠ẖápĕşǐ֥y yĕşǎlĕ̇ẖe֖⁠ṅẇ ţȧ֥ẖaţ ʻéynֽ⁠wò׃s"],[21,27,"וְ⁠אִם־שֵׁ֥ן עַבְדּ֛⁠וֹ אֽוֹ־שֵׁ֥ן אֲמָת֖⁠וֹ יַפִּ֑יל לַֽ⁠חָפְשִׁ֥י יְשַׁלְּחֶ֖⁠נּוּ תַּ֥חַת שִׁנּֽ⁠וֹ׃פ","wĕ⁠ʼim-şé֥̌n ʻabĕḋ֛⁠wò ʼֽwò-şé֥̌n ʼàmáţ֖⁠wò yapi֑̇yl lֽa⁠ẖápĕşǐ֥y yĕşǎlĕ̇ẖe֖⁠ṅẇ ţȧ֥ẖaţ şǐṅֽ⁠wò׃p"],[21,28,"וְ⁠כִֽי־יִגַּ֨ח שׁ֥וֹר אֶת־אִ֛ישׁ א֥וֹ אֶת־אִשָּׁ֖ה וָ⁠מֵ֑ת סָק֨וֹל יִסָּקֵ֜ל הַ⁠שּׁ֗וֹר וְ⁠לֹ֤א יֵאָכֵל֙ אֶת־בְּשָׂר֔⁠וֹ וּ⁠בַ֥עַל הַ⁠שּׁ֖וֹר נָקִֽי׃","wĕ⁠kiֽy-yigȧ֨ẖ ş֥̌wòr ʼeţ-ʼi֛yş̌ ʼ֥wò ʼeţ-ʼişá֖̇̌h wá⁠mé֑ţ sáq֨wòl yisá̇qé֜l ha⁠ş̇̌֗wòr wĕ⁠lò֤ʼ yéʼákél֙ ʼeţ-bĕ̇şá̂r֔⁠wò ẇ⁠ba֥ʻal ha⁠ş֖̇̌wòr náqiֽy׃"],[21,29,"וְ⁠אִ֡ם שׁוֹר֩ נַגָּ֨ח ה֜וּא מִ⁠תְּמֹ֣ל שִׁלְשֹׁ֗ם וְ⁠הוּעַ֤ד בִּ⁠בְעָלָי⁠ו֙ וְ⁠לֹ֣א יִשְׁמְרֶ֔⁠נּוּ וְ⁠הֵמִ֥ית אִ֖ישׁ א֣וֹ אִשָּׁ֑ה הַ⁠שּׁוֹר֙ יִסָּקֵ֔ל וְ⁠גַם־בְּעָלָ֖י⁠ו יוּמָֽת׃","wĕ⁠ʼi֡m ş̌wòr֩ nagá̇֨ẖ h֜ẇʼ mi⁠ţĕ̇mò֣l şǐlĕşò̌֗m wĕ⁠hẇʻa֤d bi̇⁠bĕʻáláy⁠w֙ wĕ⁠lò֣ʼ yişĕ̌mĕre֔⁠ṅẇ wĕ⁠hémi֥yţ ʼi֖yş̌ ʼ֣wò ʼişá֑̇̌h ha⁠ş̇̌wòr֙ yisá̇qé֔l wĕ⁠gam-bĕ̇ʻálá֖y⁠w yẇmáֽţ׃"],[21,30,"אִם־כֹּ֖פֶר יוּשַׁ֣ת עָלָ֑י⁠ו וְ⁠נָתַן֙ פִּדְיֹ֣ן נַפְשׁ֔⁠וֹ כְּ⁠כֹ֥ל אֲשֶׁר־יוּשַׁ֖ת עָלָֽי⁠ו׃","ʼim-kò֖̇per yẇşǎ֣ţ ʻálá֑y⁠w wĕ⁠náţan֙ pi̇dĕyò֣n napĕş̌֔⁠wò kĕ̇⁠kò֥l ʼàşěr-yẇşǎ֖ţ ʻáláֽy⁠w׃"],[21,31,"אוֹ־בֵ֥ן יִגָּ֖ח אוֹ־בַ֣ת יִגָּ֑ח כַּ⁠מִּשְׁפָּ֥ט הַ⁠זֶּ֖ה יֵעָ֥שֶׂה לּֽ⁠וֹ׃","ʼwò-bé֥n yigá֖̇ẖ ʼwò-ba֣ţ yigá֑̇ẖ kȧ⁠mi̇şĕ̌pá֥̇t ha⁠zė֖h yéʻá֥şêh lֽ̇⁠wò׃"],[21,32,"אִם־עֶ֛בֶד יִגַּ֥ח הַ⁠שּׁ֖וֹר א֣וֹ אָמָ֑ה כֶּ֣סֶף ׀ שְׁלֹשִׁ֣ים שְׁקָלִ֗ים יִתֵּן֙ לַֽ⁠אדֹנָ֔י⁠ו וְ⁠הַ⁠שּׁ֖וֹר יִסָּקֵֽל׃ס","ʼim-ʻe֛bed yigȧ֥ẖ ha⁠ş֖̇̌wòr ʼ֣wò ʼámá֑h kė֣sep ׀ şĕ̌lòşǐ֣ym şĕ̌qáli֗ym yiţé̇n֙ laֽ⁠ʼdòná֔y⁠w wĕ⁠ha⁠ş֖̇̌wòr yisá̇qéֽl׃s"],[21,33,"וְ⁠כִֽי־יִפְתַּ֨ח אִ֜ישׁ בּ֗וֹר א֠וֹ כִּֽי־יִכְרֶ֥ה אִ֛ישׁ בֹּ֖ר וְ⁠לֹ֣א יְכַסֶּ֑⁠נּוּ וְ⁠נָֽפַל־שָׁ֥מָּ⁠ה שּׁ֖וֹר א֥וֹ חֲמֽוֹר׃","wĕ⁠kiֽy-yipĕţȧ֨ẖ ʼi֜yş̌ ḃ֗wòr ʼ֠wò kiֽ̇y-yikĕre֥h ʼi֛yş̌ bò֖̇r wĕ⁠lò֣ʼ yĕkasė֑⁠ṅẇ wĕ⁠náֽpal-şá֥̌má̇⁠h ş֖̇̌wòr ʼ֥wò ẖàmֽwòr׃"],[21,34,"בַּ֤עַל הַ⁠בּוֹר֙ יְשַׁלֵּ֔ם כֶּ֖סֶף יָשִׁ֣יב לִ⁠בְעָלָ֑י⁠ו וְ⁠הַ⁠מֵּ֖ת יִֽהְיֶה־לּֽ⁠וֹ׃ס","bȧ֤ʻal ha⁠ḃwòr֙ yĕşǎlé̇֔m kė֖sep yáşǐ֣yb li⁠bĕʻálá֑y⁠w wĕ⁠ha⁠mé֖̇ţ yiֽhĕyeh-lֽ̇⁠wò׃s"],[21,35,"וְ⁠כִֽי־יִגֹּ֧ף שֽׁוֹר־אִ֛ישׁ אֶת־שׁ֥וֹר רֵעֵ֖⁠הוּ וָ⁠מֵ֑ת וּ⁠מָ֨כְר֜וּ אֶת־הַ⁠שּׁ֤וֹר הַ⁠חַי֙ וְ⁠חָצ֣וּ אֶת־כַּסְפּ֔⁠וֹ וְ⁠גַ֥ם אֶת־הַ⁠מֵּ֖ת יֶֽחֱצֽוּ⁠ן׃","wĕ⁠kiֽy-yigò֧̇p şֽ̌wòr-ʼi֛yş̌ ʼeţ-ş֥̌wòr réʻé֖⁠hẇ wá⁠mé֑ţ ẇ⁠má֨kĕr֜ẇ ʼeţ-ha⁠ş֤̇̌wòr ha⁠ẖay֙ wĕ⁠ẖáẕ֣ẇ ʼeţ-kȧsĕṗ֔⁠wò wĕ⁠ga֥m ʼeţ-ha⁠mé֖̇ţ yֽeẖèẕֽẇ⁠n׃"],[21,36,"א֣וֹ נוֹדַ֗ע כִּ֠י שׁ֣וֹר נַגָּ֥ח הוּא֙ מִ⁠תְּמ֣וֹל שִׁלְשֹׁ֔ם וְ⁠לֹ֥א יִשְׁמְרֶ֖⁠נּוּ בְּעָלָ֑י⁠ו שַׁלֵּ֨ם יְשַׁלֵּ֥ם שׁוֹר֙ תַּ֣חַת הַ⁠שּׁ֔וֹר וְ⁠הַ⁠מֵּ֖ת יִֽהְיֶה־לּֽ⁠וֹ׃ס","ʼ֣wò nwòda֗ʻ ki̇֠y ş֣̌wòr nagá֥̇ẖ hẇʼ֙ mi⁠ţĕ̇m֣wòl şǐlĕşò̌֔m wĕ⁠lò֥ʼ yişĕ̌mĕre֖⁠ṅẇ bĕ̇ʻálá֑y⁠w şǎlé̇֨m yĕşǎlé֥̇m ş̌wòr֙ ţȧ֣ẖaţ ha⁠ş̇̌֔wòr wĕ⁠ha⁠mé֖̇ţ yiֽhĕyeh-lֽ̇⁠wò׃s"],[22,1,"כִּ֤י יִגְנֹֽב־אִישׁ֙ שׁ֣וֹר אוֹ־שֶׂ֔ה וּ⁠טְבָח֖⁠וֹ א֣וֹ מְכָר֑⁠וֹ חֲמִשָּׁ֣ה בָקָ֗ר יְשַׁלֵּם֙ תַּ֣חַת הַ⁠שּׁ֔וֹר וְ⁠אַרְבַּע־צֹ֖אן תַּ֥חַת הַ⁠שֶּֽׂה׃","ki֤̇y yigĕnòֽb-ʼiyş̌֙ ş֣̌wòr ʼwò-şê֔h ẇ⁠tĕbáẖ֖⁠wò ʼ֣wò mĕkár֑⁠wò ẖàmişá֣̇̌h báqá֗r yĕşǎlé̇m֙ ţȧ֣ẖaţ ha⁠ş̇̌֔wòr wĕ⁠ʼarĕbȧʻ-ẕò֖ʼn ţȧ֥ẖaţ ha⁠şėֽ̂h׃"],[22,2,"אִם־בַּ⁠מַּחְתֶּ֛רֶת יִמָּצֵ֥א הַ⁠גַּנָּ֖ב וְ⁠הֻכָּ֣ה וָ⁠מֵ֑ת אֵ֥ין ל֖⁠וֹ דָּמִֽים׃","ʼim-bȧ⁠mȧẖĕţė֛reţ yimá̇ẕé֥ʼ ha⁠gȧná֖̇b wĕ⁠huká֣̇h wá⁠mé֑ţ ʼé֥yn l֖⁠wò dá̇miֽym׃"],[22,3,"אִם־זָרְחָ֥ה הַ⁠שֶּׁ֛מֶשׁ עָלָ֖י⁠ו דָּמִ֣ים ל֑⁠וֹ שַׁלֵּ֣ם יְשַׁלֵּ֔ם אִם־אֵ֣ין ל֔⁠וֹ וְ⁠נִמְכַּ֖ר בִּ⁠גְנֵבָתֽ⁠וֹ׃","ʼim-zárĕẖá֥h ha⁠şė֛̌meş̌ ʻálá֖y⁠w dá̇mi֣ym l֑⁠wò şǎlé֣̇m yĕşǎlé̇֔m ʼim-ʼé֣yn l֔⁠wò wĕ⁠nimĕkȧ֖r bi̇⁠gĕnébáţֽ⁠wò׃"],[22,4,"אִֽם־הִמָּצֵא֩ תִמָּצֵ֨א בְ⁠יָד֜⁠וֹ הַ⁠גְּנֵבָ֗ה מִ⁠שּׁ֧וֹר עַד־חֲמ֛וֹר עַד־שֶׂ֖ה חַיִּ֑ים שְׁנַ֖יִם יְשַׁלֵּֽם׃ס","ʼiֽm-himá̇ẕéʼ֩ ţimá̇ẕé֨ʼ bĕ⁠yád֜⁠wò ha⁠gĕ̇nébá֗h mi⁠ş֧̇̌wòr ʻad-ẖàm֛wòr ʻad-şê֖h ẖayi֑̇ym şĕ̌na֖yim yĕşǎléֽ̇m׃s"],[22,5,"כִּ֤י יַבְעֶר־אִישׁ֙ שָׂדֶ֣ה אוֹ־כֶ֔רֶם וְ⁠שִׁלַּח֙ אֶת־בעיר⁠ה וּ⁠בִעֵ֖ר בִּ⁠שְׂדֵ֣ה אַחֵ֑ר מֵיטַ֥ב שָׂדֵ֛⁠הוּ וּ⁠מֵיטַ֥ב כַּרְמ֖⁠וֹ יְשַׁלֵּֽם׃ס","ki֤̇y yabĕʻer-ʼiyş̌֙ şá̂de֣h ʼwò-ke֔rem wĕ⁠şǐlȧẖ֙ ʼeţ-bʻyr⁠h ẇ⁠biʻé֖r bi̇⁠şĕ̂dé֣h ʼaẖé֑r méyta֥b şá̂dé֛⁠hẇ ẇ⁠méyta֥b kȧrĕm֖⁠wò yĕşǎléֽ̇m׃s"],[22,6,"כִּֽי־תֵצֵ֨א אֵ֜שׁ וּ⁠מָצְאָ֤ה קֹצִים֙ וְ⁠נֶאֱכַ֣ל גָּדִ֔ישׁ א֥וֹ הַ⁠קָּמָ֖ה א֣וֹ הַ⁠שָּׂדֶ֑ה שַׁלֵּ֣ם יְשַׁלֵּ֔ם הַ⁠מַּבְעִ֖ר אֶת־הַ⁠בְּעֵרָֽה׃ס","kiֽ̇y-ţéẕé֨ʼ ʼé֜ş̌ ẇ⁠máẕĕʼá֤h qòẕiym֙ wĕ⁠neʼèka֣l gá̇di֔yş̌ ʼ֥wò ha⁠qá̇má֖h ʼ֣wò ha⁠şá̇̂de֑h şǎlé֣̇m yĕşǎlé̇֔m ha⁠mȧbĕʻi֖r ʼeţ-ha⁠bĕ̇ʻéráֽh׃s"],[22,7,"כִּֽי־יִתֵּן֩ אִ֨ישׁ אֶל־רֵעֵ֜⁠הוּ כֶּ֤סֶף אֽוֹ־כֵלִים֙ לִ⁠שְׁמֹ֔ר וְ⁠גֻנַּ֖ב מִ⁠בֵּ֣ית הָ⁠אִ֑ישׁ אִם־יִמָּצֵ֥א הַ⁠גַּנָּ֖ב יְשַׁלֵּ֥ם שְׁנָֽיִם׃","kiֽ̇y-yiţé̇n֩ ʼi֨yş̌ ʼel-réʻé֜⁠hẇ kė֤sep ʼֽwò-kéliym֙ li⁠şĕ̌mò֔r wĕ⁠gunȧ֖b mi⁠bé֣̇yţ há⁠ʼi֑yş̌ ʼim-yimá̇ẕé֥ʼ ha⁠gȧná֖̇b yĕşǎlé֥̇m şĕ̌náֽyim׃"],[22,8,"אִם־לֹ֤א יִמָּצֵא֙ הַ⁠גַּנָּ֔ב וְ⁠נִקְרַ֥ב בַּֽעַל־הַ⁠בַּ֖יִת אֶל־הָֽ⁠אֱלֹהִ֑ים אִם־לֹ֥א שָׁלַ֛ח יָד֖⁠וֹ בִּ⁠מְלֶ֥אכֶת רֵעֵֽ⁠הוּ׃","ʼim-lò֤ʼ yimá̇ẕéʼ֙ ha⁠gȧná̇֔b wĕ⁠niqĕra֥b bȧֽʻal-ha⁠bȧ֖yiţ ʼel-háֽ⁠ʼèlòhi֑ym ʼim-lò֥ʼ şá̌la֛ẖ yád֖⁠wò bi̇⁠mĕle֥ʼkeţ réʻéֽ⁠hẇ׃"],[22,9,"עַֽל־כָּל־דְּבַר־פֶּ֡שַׁע עַל־שׁ֡וֹר עַל־חֲ֠מוֹר עַל־שֶׂ֨ה עַל־שַׂלְמָ֜ה עַל־כָּל־אֲבֵדָ֗ה אֲשֶׁ֤ר יֹאמַר֙ כִּי־ה֣וּא זֶ֔ה עַ֚ד הָֽ⁠אֱלֹהִ֔ים יָבֹ֖א דְּבַר־שְׁנֵי⁠הֶ֑ם אֲשֶׁ֤ר יַרְשִׁיעֻ⁠ן֙ אֱלֹהִ֔ים יְשַׁלֵּ֥ם שְׁנַ֖יִם לְ⁠רֵעֵֽ⁠הוּ׃ס","ʻaֽl-ká̇l-dĕ̇bar-pė֡şǎʻ ʻal-ş̌֡wòr ʻal-ẖà֠mwòr ʻal-şê֨h ʻal-şâlĕmá֜h ʻal-ká̇l-ʼàbédá֗h ʼàşě֤r yòʼmar֙ ki̇y-h֣ẇʼ ze֔h ʻa֚d háֽ⁠ʼèlòhi֔ym yábò֖ʼ dĕ̇bar-şĕ̌néy⁠he֑m ʼàşě֤r yarĕşǐyʻu⁠n֙ ʼèlòhi֔ym yĕşǎlé֥̇m şĕ̌na֖yim lĕ⁠réʻéֽ⁠hẇ׃s"],[22,10,"כִּֽי־יִתֵּן֩ אִ֨ישׁ אֶל־רֵעֵ֜⁠הוּ חֲמ֨וֹר אוֹ־שׁ֥וֹר אוֹ־שֶׂ֛ה וְ⁠כָל־בְּהֵמָ֖ה לִ⁠שְׁמֹ֑ר וּ⁠מֵ֛ת אוֹ־נִשְׁבַּ֥ר אוֹ־נִשְׁבָּ֖ה אֵ֥ין רֹאֶֽה׃","kiֽ̇y-yiţé̇n֩ ʼi֨yş̌ ʼel-réʻé֜⁠hẇ ẖàm֨wòr ʼwò-ş֥̌wòr ʼwò-şê֛h wĕ⁠kál-bĕ̇hémá֖h li⁠şĕ̌mò֑r ẇ⁠mé֛ţ ʼwò-nişĕ̌bȧ֥r ʼwò-nişĕ̌bá֖̇h ʼé֥yn ròʼeֽh׃"],[22,11,"שְׁבֻעַ֣ת יְהוָ֗ה תִּהְיֶה֙ בֵּ֣ין שְׁנֵי⁠הֶ֔ם אִם־לֹ֥א שָׁלַ֛ח יָד֖⁠וֹ בִּ⁠מְלֶ֣אכֶת רֵעֵ֑⁠הוּ וְ⁠לָקַ֥ח בְּעָלָ֖י⁠ו וְ⁠לֹ֥א יְשַׁלֵּֽם׃","şĕ̌buʻa֣ţ yĕhwá֗h ţi̇hĕyeh֙ bé֣̇yn şĕ̌néy⁠he֔m ʼim-lò֥ʼ şá̌la֛ẖ yád֖⁠wò bi̇⁠mĕle֣ʼkeţ réʻé֑⁠hẇ wĕ⁠láqa֥ẖ bĕ̇ʻálá֖y⁠w wĕ⁠lò֥ʼ yĕşǎléֽ̇m׃"],[22,12,"וְ⁠אִם־גָּנֹ֥ב יִגָּנֵ֖ב מֵ⁠עִמּ֑⁠וֹ יְשַׁלֵּ֖ם לִ⁠בְעָלָֽי⁠ו׃","wĕ⁠ʼim-gá̇nò֥b yigá̇né֖b mé⁠ʻiṁ֑⁠wò yĕşǎlé֖̇m li⁠bĕʻáláֽy⁠w׃"],[22,13,"אִם־טָרֹ֥ף יִטָּרֵ֖ף יְבִאֵ֣⁠הוּ עֵ֑ד הַ⁠טְּרֵפָ֖ה לֹ֥א יְשַׁלֵּֽם׃פ","ʼim-tárò֥p yitá̇ré֖p yĕbiʼé֣⁠hẇ ʻé֑d ha⁠tĕ̇répá֖h lò֥ʼ yĕşǎléֽ̇m׃p"],[22,14,"וְ⁠כִֽי־יִשְׁאַ֥ל אִ֛ישׁ מֵ⁠עִ֥ם רֵעֵ֖⁠הוּ וְ⁠נִשְׁבַּ֣ר אוֹ־מֵ֑ת בְּעָלָ֥י⁠ו אֵין־עִמּ֖⁠וֹ שַׁלֵּ֥ם יְשַׁלֵּֽם׃","wĕ⁠kiֽy-yişĕ̌ʼa֥l ʼi֛yş̌ mé⁠ʻi֥m réʻé֖⁠hẇ wĕ⁠nişĕ̌bȧ֣r ʼwò-mé֑ţ bĕ̇ʻálá֥y⁠w ʼéyn-ʻiṁ֖⁠wò şǎlé֥̇m yĕşǎléֽ̇m׃"],[22,15,"אִם־בְּעָלָ֥י⁠ו עִמּ֖⁠וֹ לֹ֣א יְשַׁלֵּ֑ם אִם־שָׂכִ֣יר ה֔וּא בָּ֖א בִּ⁠שְׂכָרֽ⁠וֹ׃ס","ʼim-bĕ̇ʻálá֥y⁠w ʻiṁ֖⁠wò lò֣ʼ yĕşǎlé֑̇m ʼim-şá̂ki֣yr h֔ẇʼ bá֖̇ʼ bi̇⁠şĕ̂kárֽ⁠wò׃s"],[22,16,"וְ⁠כִֽי־יְפַתֶּ֣ה אִ֗ישׁ בְּתוּלָ֛ה אֲשֶׁ֥ר לֹא־אֹרָ֖שָׂה וְ⁠שָׁכַ֣ב עִמָּ֑⁠הּ מָהֹ֛ר יִמְהָרֶ֥⁠נָּה לּ֖⁠וֹ לְ⁠אִשָּֽׁה׃","wĕ⁠kiֽy-yĕpaţė֣h ʼi֗yş̌ bĕ̇ţẇlá֛h ʼàşě֥r lòʼ-ʼòrá֖şá̂h wĕ⁠şá̌ka֣b ʻimá֑̇⁠ḣ máhò֛r yimĕháre֥⁠ná̇h l֖̇⁠wò lĕ⁠ʼişáֽ̇̌h׃"],[22,17,"אִם־מָאֵ֧ן יְמָאֵ֛ן אָבִ֖י⁠הָ לְ⁠תִתָּ֣⁠הּ ל֑⁠וֹ כֶּ֣סֶף יִשְׁקֹ֔ל כְּ⁠מֹ֖הַר הַ⁠בְּתוּלֹֽת׃ס","ʼim-máʼé֧n yĕmáʼé֛n ʼábi֖y⁠há lĕ⁠ţiţá֣̇⁠ḣ l֑⁠wò kė֣sep yişĕ̌qò֔l kĕ̇⁠mò֖har ha⁠bĕ̇ţẇlòֽţ׃s"],[22,18,"מְכַשֵּׁפָ֖ה לֹ֥א תְחַיֶּֽה׃ס","mĕkaşé̇̌pá֖h lò֥ʼ ţĕẖayėֽh׃s"],[22,19,"כָּל־שֹׁכֵ֥ב עִם־בְּהֵמָ֖ה מ֥וֹת יוּמָֽת׃ס","ká̇l-şò̌ké֥b ʻim-bĕ̇hémá֖h m֥wòţ yẇmáֽţ׃s"],[22,20,"זֹבֵ֥חַ לָ⁠אֱלֹהִ֖ים יָֽחֳרָ֑ם בִּלְתִּ֥י לַ⁠יהוָ֖ה לְ⁠בַדּֽ⁠וֹ׃","zòbé֥ẖa lá⁠ʼèlòhi֖ym yáֽẖorá֑m bi̇lĕţi֥̇y la⁠yhwá֖h lĕ⁠baḋֽ⁠wò׃"],[22,21,"וְ⁠גֵ֥ר לֹא־תוֹנֶ֖ה וְ⁠לֹ֣א תִלְחָצֶ֑⁠נּוּ כִּֽי־גֵרִ֥ים הֱיִיתֶ֖ם בְּ⁠אֶ֥רֶץ מִצְרָֽיִם׃","wĕ⁠gé֥r lòʼ-ţwòne֖h wĕ⁠lò֣ʼ ţilĕẖáẕe֑⁠ṅẇ kiֽ̇y-géri֥ym hèyiyţe֖m bĕ̇⁠ʼe֥reẕ miẕĕráֽyim׃"],[22,22,"כָּל־אַלְמָנָ֥ה וְ⁠יָת֖וֹם לֹ֥א תְעַנּֽוּ⁠ן׃","ká̇l-ʼalĕmáná֥h wĕ⁠yáţ֖wòm lò֥ʼ ţĕʻaṅֽẇ⁠n׃"],[22,23,"אִם־עַנֵּ֥ה תְעַנֶּ֖ה אֹת֑⁠וֹ כִּ֣י אִם־צָעֹ֤ק יִצְעַק֙ אֵלַ֔⁠י שָׁמֹ֥עַ אֶשְׁמַ֖ע צַעֲקָתֽ⁠וֹ׃","ʼim-ʻané֥̇h ţĕʻanė֖h ʼòţ֑⁠wò ki֣̇y ʼim-ẕáʻò֤q yiẕĕʻaq֙ ʼéla֔⁠y şá̌mò֥ʻa ʼeşĕ̌ma֖ʻ ẕaʻàqáţֽ⁠wò׃"],[22,24,"וְ⁠חָרָ֣ה אַפִּ֔⁠י וְ⁠הָרַגְתִּ֥י אֶתְ⁠כֶ֖ם בֶּ⁠חָ֑רֶב וְ⁠הָי֤וּ נְשֵׁי⁠כֶם֙ אַלְמָנ֔וֹת וּ⁠בְנֵי⁠כֶ֖ם יְתֹמִֽים׃פ","wĕ⁠ẖárá֣h ʼapi̇֔⁠y wĕ⁠háragĕţi֥̇y ʼeţĕ⁠ke֖m bė⁠ẖá֑reb wĕ⁠háy֤ẇ nĕşé̌y⁠kem֙ ʼalĕmán֔wòţ ẇ⁠bĕnéy⁠ke֖m yĕţòmiֽym׃p"],[22,25,"אִם־כֶּ֣סֶף ׀ תַּלְוֶ֣ה אֶת־עַמִּ֗⁠י אֶת־הֶֽ⁠עָנִי֙ עִמָּ֔⁠ךְ לֹא־תִהְיֶ֥ה ל֖⁠וֹ כְּ⁠נֹשֶׁ֑ה לֹֽא־תְשִׂימ֥וּ⁠ן עָלָ֖י⁠ו נֶֽשֶׁךְ׃","ʼim-kė֣sep ׀ ţȧlĕwe֣h ʼeţ-ʻami̇֗⁠y ʼeţ-heֽ⁠ʻániy֙ ʻimá̇֔⁠kĕ lòʼ-ţihĕye֥h l֖⁠wò kĕ̇⁠nòşě֑h lòֽʼ-ţĕşîym֥ẇ⁠n ʻálá֖y⁠w neֽşěkĕ׃"],[22,26,"אִם־חָבֹ֥ל תַּחְבֹּ֖ל שַׂלְמַ֣ת רֵעֶ֑⁠ךָ עַד־בֹּ֥א הַ⁠שֶּׁ֖מֶשׁ תְּשִׁיבֶ֥⁠נּוּ לֽ⁠וֹ׃","ʼim-ẖábò֥l ţȧẖĕbò֖̇l şâlĕma֣ţ réʻe֑⁠ká ʻad-bò֥̇ʼ ha⁠şė֖̌meş̌ ţĕ̇şǐybe֥⁠ṅẇ lֽ⁠wò׃"],[22,27,"כִּ֣י הִ֤וא כסות⁠ה לְ⁠בַדָּ֔⁠הּ הִ֥וא שִׂמְלָת֖⁠וֹ לְ⁠עֹר֑⁠וֹ בַּ⁠מֶּ֣ה יִשְׁכָּ֔ב וְ⁠הָיָה֙ כִּֽי־יִצְעַ֣ק אֵלַ֔⁠י וְ⁠שָׁמַעְתִּ֖י כִּֽי־חַנּ֥וּן אָֽנִי׃ס","ki֣̇y hi֤wʼ kswţ⁠h lĕ⁠badá̇֔⁠ḣ hi֥wʼ şîmĕláţ֖⁠wò lĕ⁠ʻòr֑⁠wò bȧ⁠mė֣h yişĕ̌ká̇֔b wĕ⁠háyáh֙ kiֽ̇y-yiẕĕʻa֣q ʼéla֔⁠y wĕ⁠şá̌maʻĕţi֖̇y kiֽ̇y-ẖaṅ֥ẇn ʼáֽniy׃s"],[22,28,"אֱלֹהִ֖ים לֹ֣א תְקַלֵּ֑ל וְ⁠נָשִׂ֥יא בְ⁠עַמְּ⁠ךָ֖ לֹ֥א תָאֹֽר׃","ʼèlòhi֖ym lò֣ʼ ţĕqalé֑̇l wĕ⁠náşî֥yʼ bĕ⁠ʻamĕ̇⁠ká֖ lò֥ʼ ţáʼòֽr׃"],[22,29,"מְלֵאָתְ⁠ךָ֥ וְ⁠דִמְעֲ⁠ךָ֖ לֹ֣א תְאַחֵ֑ר בְּכ֥וֹר בָּנֶ֖י⁠ךָ תִּתֶּן־לִּֽ⁠י׃","mĕléʼáţĕ⁠ká֥ wĕ⁠dimĕʻà⁠ká֖ lò֣ʼ ţĕʼaẖé֑r bĕ̇k֥wòr bá̇ne֖y⁠ká ţi̇ţėn-liֽ̇⁠y׃"],[22,30,"כֵּֽן־תַּעֲשֶׂ֥ה לְ⁠שֹׁרְ⁠ךָ֖ לְ⁠צֹאנֶ֑⁠ךָ שִׁבְעַ֤ת יָמִים֙ יִהְיֶ֣ה עִם־אִמּ֔⁠וֹ בַּ⁠יּ֥וֹם הַ⁠שְּׁמִינִ֖י תִּתְּנ⁠וֹ־לִֽ⁠י׃","kéֽ̇n-ţȧʻàşê֥h lĕ⁠şò̌rĕ⁠ká֖ lĕ⁠ẕòʼne֑⁠ká şǐbĕʻa֤ţ yámiym֙ yihĕye֣h ʻim-ʼiṁ֔⁠wò bȧ⁠ẏ֥wòm ha⁠şĕ̇̌miyni֖y ţi̇ţĕ̇n⁠wò-liֽ⁠y׃"],[22,31,"וְ⁠אַנְשֵׁי־קֹ֖דֶשׁ תִּהְי֣וּ⁠ן לִ֑⁠י וּ⁠בָשָׂ֨ר בַּ⁠שָּׂדֶ֤ה טְרֵפָה֙ לֹ֣א תֹאכֵ֔לוּ לַ⁠כֶּ֖לֶב תַּשְׁלִכ֥וּ⁠ן אֹתֽ⁠וֹ׃ס","wĕ⁠ʼanĕşé̌y-qò֖deş̌ ţi̇hĕy֣ẇ⁠n li֑⁠y ẇ⁠báşá̂֨r bȧ⁠şá̇̂de֤h tĕrépáh֙ lò֣ʼ ţòʼké֔lẇ la⁠kė֖leb ţȧşĕ̌lik֥ẇ⁠n ʼòţֽ⁠wò׃s"],[23,1,"לֹ֥א תִשָּׂ֖א שֵׁ֣מַע שָׁ֑וְא אַל־תָּ֤שֶׁת יָֽדְ⁠ךָ֙ עִם־רָשָׁ֔ע לִ⁠הְיֹ֖ת עֵ֥ד חָמָֽס׃ס","lò֥ʼ ţişá֖̇̂ʼ şé֣̌maʻ şá֑̌wĕʼ ʼal-ţá֤̇şěţ yáֽdĕ⁠ká֙ ʻim-ráşá̌֔ʻ li⁠hĕyò֖ţ ʻé֥d ẖámáֽs׃s"],[23,2,"לֹֽא־תִהְיֶ֥ה אַחֲרֵֽי־רַבִּ֖ים לְ⁠רָעֹ֑ת וְ⁠לֹא־תַעֲנֶ֣ה עַל־רִ֗ב לִ⁠נְטֹ֛ת אַחֲרֵ֥י רַבִּ֖ים לְ⁠הַטֹּֽת׃","lòֽʼ-ţihĕye֥h ʼaẖàréֽy-rabi֖̇ym lĕ⁠ráʻò֑ţ wĕ⁠lòʼ-ţaʻàne֣h ʻal-ri֗b li⁠nĕtò֛ţ ʼaẖàré֥y rabi֖̇ym lĕ⁠hatòֽ̇ţ׃"],[23,3,"וְ⁠דָ֕ל לֹ֥א תֶהְדַּ֖ר בְּ⁠רִיבֽ⁠וֹ׃ס","wĕ⁠dá֕l lò֥ʼ ţehĕdȧ֖r bĕ̇⁠riybֽ⁠wò׃s"],[23,4,"כִּ֣י תִפְגַּ֞ע שׁ֧וֹר אֹֽיִבְ⁠ךָ֛ א֥וֹ חֲמֹר֖⁠וֹ תֹּעֶ֑ה הָשֵׁ֥ב תְּשִׁיבֶ֖⁠נּוּ לֽ⁠וֹ׃ס","ki֣̇y ţipĕgȧ֞ʻ ş֧̌wòr ʼòֽyibĕ⁠ká֛ ʼ֥wò ẖàmòr֖⁠wò ţò̇ʻe֑h háşé֥̌b ţĕ̇şǐybe֖⁠ṅẇ lֽ⁠wò׃s"],[23,5,"כִּֽי־תִרְאֶ֞ה חֲמ֣וֹר שֹׂנַאֲ⁠ךָ֗ רֹבֵץ֙ תַּ֣חַת מַשָּׂא֔⁠וֹ וְ⁠חָדַלְתָּ֖ מֵ⁠עֲזֹ֣ב ל֑⁠וֹ עָזֹ֥ב תַּעֲזֹ֖ב עִמּֽ⁠וֹ׃ס","kiֽ̇y-ţirĕʼe֞h ẖàm֣wòr şò̂naʼà⁠ká֗ ròbéẕ֙ ţȧ֣ẖaţ maşá̇̂ʼ֔⁠wò wĕ⁠ẖádalĕţá֖̇ mé⁠ʻàzò֣b l֑⁠wò ʻázò֥b ţȧʻàzò֖b ʻiṁֽ⁠wò׃s"],[23,6,"לֹ֥א תַטֶּ֛ה מִשְׁפַּ֥ט אֶבְיֹנְ⁠ךָ֖ בְּ⁠רִיבֽ⁠וֹ׃","lò֥ʼ ţatė֛h mişĕ̌pȧ֥t ʼebĕyònĕ⁠ká֖ bĕ̇⁠riybֽ⁠wò׃"],[23,7,"מִ⁠דְּבַר־שֶׁ֖קֶר תִּרְחָ֑ק וְ⁠נָקִ֤י וְ⁠צַדִּיק֙ אַֽל־תַּהֲרֹ֔ג כִּ֥י לֹא־אַצְדִּ֖יק רָשָֽׁע׃","mi⁠dĕ̇bar-şě֖qer ţi̇rĕẖá֑q wĕ⁠náqi֤y wĕ⁠ẕadi̇yq֙ ʼaֽl-ţȧhàrò֔g ki֥̇y lòʼ-ʼaẕĕdi֖̇yq ráşáֽ̌ʻ׃"],[23,8,"וְ⁠שֹׁ֖חַד לֹ֣א תִקָּ֑ח כִּ֤י הַ⁠שֹּׁ֨חַד֙ יְעַוֵּ֣ר פִּקְחִ֔ים וִֽ⁠יסַלֵּ֖ף דִּבְרֵ֥י צַדִּיקִֽים׃","wĕ⁠şò֖̌ẖad lò֣ʼ ţiqá֑̇ẖ ki֤̇y ha⁠şò̇̌֨ẖad֙ yĕʻawé֣̇r pi̇qĕẖi֔ym wiֽ⁠ysalé֖̇p di̇bĕré֥y ẕadi̇yqiֽym׃"],[23,9,"וְ⁠גֵ֖ר לֹ֣א תִלְחָ֑ץ וְ⁠אַתֶּ֗ם יְדַעְתֶּם֙ אֶת־נֶ֣פֶשׁ הַ⁠גֵּ֔ר כִּֽי־גֵרִ֥ים הֱיִיתֶ֖ם בְּ⁠אֶ֥רֶץ מִצְרָֽיִם׃","wĕ⁠gé֖r lò֣ʼ ţilĕẖá֑ẕ wĕ⁠ʼaţė֗m yĕdaʻĕţėm֙ ʼeţ-ne֣peş̌ ha⁠gé̇֔r kiֽ̇y-géri֥ym hèyiyţe֖m bĕ̇⁠ʼe֥reẕ miẕĕráֽyim׃"],[23,10,"וְ⁠שֵׁ֥שׁ שָׁנִ֖ים תִּזְרַ֣ע אֶת־אַרְצֶ֑⁠ךָ וְ⁠אָסַפְתָּ֖ אֶת־תְּבוּאָתָֽ⁠הּ׃","wĕ⁠şé֥̌ş̌ şá̌ni֖ym ţi̇zĕra֣ʻ ʼeţ-ʼarĕẕe֑⁠ká wĕ⁠ʼásapĕţá֖̇ ʼeţ-ţĕ̇bẇʼáţáֽ⁠ḣ׃"],[23,11,"וְ⁠הַ⁠שְּׁבִיעִ֞ת תִּשְׁמְטֶ֣⁠נָּה וּ⁠נְטַשְׁתָּ֗⁠הּ וְ⁠אָֽכְלוּ֙ אֶבְיֹנֵ֣י עַמֶּ֔⁠ךָ וְ⁠יִתְרָ֕⁠ם תֹּאכַ֖ל חַיַּ֣ת הַ⁠שָּׂדֶ֑ה כֵּֽן־תַּעֲשֶׂ֥ה לְ⁠כַרְמְ⁠ךָ֖ לְ⁠זֵיתֶֽ⁠ךָ׃","wĕ⁠ha⁠şĕ̇̌biyʻi֞ţ ţi̇şĕ̌mĕte֣⁠ná̇h ẇ⁠nĕtaşĕ̌ţá̇֗⁠ḣ wĕ⁠ʼáֽkĕlẇ֙ ʼebĕyòné֣y ʻamė֔⁠ká wĕ⁠yiţĕrá֕⁠m ţò̇ʼka֖l ẖayȧ֣ţ ha⁠şá̇̂de֑h kéֽ̇n-ţȧʻàşê֥h lĕ⁠karĕmĕ⁠ká֖ lĕ⁠zéyţeֽ⁠ká׃"],[23,12,"שֵׁ֤שֶׁת יָמִים֙ תַּעֲשֶׂ֣ה מַעֲשֶׂ֔י⁠ךָ וּ⁠בַ⁠יּ֥וֹם הַ⁠שְּׁבִיעִ֖י תִּשְׁבֹּ֑ת לְמַ֣עַן יָנ֗וּחַ שֽׁוֹרְ⁠ךָ֙ וַ⁠חֲמֹרֶ֔⁠ךָ וְ⁠יִנָּפֵ֥שׁ בֶּן־אֲמָתְ⁠ךָ֖ וְ⁠הַ⁠גֵּֽר׃","şé֤̌şěţ yámiym֙ ţȧʻàşê֣h maʻàşê֔y⁠ká ẇ⁠ba⁠ẏ֥wòm ha⁠şĕ̇̌biyʻi֖y ţi̇şĕ̌bò֑̇ţ lĕma֣ʻan yán֗ẇẖa şֽ̌wòrĕ⁠ká֙ wa⁠ẖàmòre֔⁠ká wĕ⁠yiná̇pé֥ş̌ bėn-ʼàmáţĕ⁠ká֖ wĕ⁠ha⁠géֽ̇r׃"],[23,13,"וּ⁠בְ⁠כֹ֛ל אֲשֶׁר־אָמַ֥רְתִּי אֲלֵי⁠כֶ֖ם תִּשָּׁמֵ֑רוּ וְ⁠שֵׁ֨ם אֱלֹהִ֤ים אֲחֵרִים֙ לֹ֣א תַזְכִּ֔ירוּ לֹ֥א יִשָּׁמַ֖ע עַל־פִּֽי⁠ךָ׃","ẇ⁠bĕ⁠kò֛l ʼàşěr-ʼáma֥rĕţi̇y ʼàléy⁠ke֖m ţi̇şá̇̌mé֑rẇ wĕ⁠şé̌֨m ʼèlòhi֤ym ʼàẖériym֙ lò֣ʼ ţazĕki̇֔yrẇ lò֥ʼ yişá̇̌ma֖ʻ ʻal-piֽ̇y⁠ká׃"],[23,14,"שָׁלֹ֣שׁ רְגָלִ֔ים תָּחֹ֥ג לִ֖⁠י בַּ⁠שָּׁנָֽה׃","şá̌lò֣ş̌ rĕgáli֔ym ţá̇ẖò֥g li֖⁠y bȧ⁠şá̇̌náֽh׃"],[23,15,"אֶת־חַ֣ג הַ⁠מַּצּוֹת֮ תִּשְׁמֹר֒ שִׁבְעַ֣ת יָמִים֩ תֹּאכַ֨ל מַצּ֜וֹת כַּֽ⁠אֲשֶׁ֣ר צִוִּיתִ֗⁠ךָ לְ⁠מוֹעֵד֙ חֹ֣דֶשׁ הָֽ⁠אָבִ֔יב כִּי־ב֖⁠וֹ יָצָ֣אתָ מִ⁠מִּצְרָ֑יִם וְ⁠לֹא־יֵרָא֥וּ פָנַ֖⁠י רֵיקָֽם׃","ʼeţ-ẖa֣g ha⁠mȧẕ̇wòţ֮ ţi̇şĕ̌mòr֒ şǐbĕʻa֣ţ yámiym֩ ţò̇ʼka֨l maẕ̇֜wòţ kֽ̇a⁠ʼàşě֣r ẕiwi̇yţi֗⁠ká lĕ⁠mwòʻéd֙ ẖò֣deş̌ háֽ⁠ʼábi֔yb ki̇y-b֖⁠wò yáẕá֣ʼţá mi⁠mi̇ẕĕrá֑yim wĕ⁠lòʼ-yéráʼ֥ẇ pána֖⁠y réyqáֽm׃"],[23,16,"וְ⁠חַ֤ג הַ⁠קָּצִיר֙ בִּכּוּרֵ֣י מַעֲשֶׂ֔י⁠ךָ אֲשֶׁ֥ר תִּזְרַ֖ע בַּ⁠שָּׂדֶ֑ה וְ⁠חַ֤ג הָֽ⁠אָסִף֙ בְּ⁠צֵ֣את הַ⁠שָּׁנָ֔ה בְּ⁠אָסְפְּ⁠ךָ֥ אֶֽת־מַעֲשֶׂ֖י⁠ךָ מִן־הַ⁠שָּׂדֶֽה׃","wĕ⁠ẖa֤g ha⁠qá̇ẕiyr֙ bi̇k̇ẇré֣y maʻàşê֔y⁠ká ʼàşě֥r ţi̇zĕra֖ʻ bȧ⁠şá̇̂de֑h wĕ⁠ẖa֤g háֽ⁠ʼásip֙ bĕ̇⁠ẕé֣ʼţ ha⁠şá̇̌ná֔h bĕ̇⁠ʼásĕpĕ̇⁠ká֥ ʼeֽţ-maʻàşê֖y⁠ká min-ha⁠şá̇̂deֽh׃"],[23,17,"שָׁלֹ֥שׁ פְּעָמִ֖ים בַּ⁠שָּׁנָ֑ה יֵרָאֶה֙ כָּל־זְכ֣וּרְ⁠ךָ֔ אֶל־פְּנֵ֖י הָ⁠אָדֹ֥ן ׀ יְהוָֽה׃","şá̌lò֥ş̌ pĕ̇ʻámi֖ym bȧ⁠şá̇̌ná֑h yéráʼeh֙ ká̇l-zĕk֣ẇrĕ⁠ká֔ ʼel-pĕ̇né֖y há⁠ʼádò֥n ׀ yĕhwáֽh׃"],[23,18,"לֹֽא־תִזְבַּ֥ח עַל־חָמֵ֖ץ דַּם־זִבְחִ֑⁠י וְ⁠לֹֽא־יָלִ֥ין חֵֽלֶב־חַגִּ֖⁠י עַד־בֹּֽקֶר׃","lòֽʼ-ţizĕbȧ֥ẖ ʻal-ẖámé֖ẕ dȧm-zibĕẖi֑⁠y wĕ⁠lòֽʼ-yáli֥yn ẖéֽleb-ẖagi֖̇⁠y ʻad-bòֽ̇qer׃"],[23,19,"רֵאשִׁ֗ית בִּכּוּרֵי֙ אַדְמָ֣תְ⁠ךָ֔ תָּבִ֕יא בֵּ֖ית יְהוָ֣ה אֱלֹהֶ֑י⁠ךָ לֹֽא־תְבַשֵּׁ֥ל גְּדִ֖י בַּ⁠חֲלֵ֥ב אִמּֽ⁠וֹ׃ס","réʼşǐ֗yţ bi̇k̇ẇréy֙ ʼadĕmá֣ţĕ⁠ká֔ ţá̇bi֕yʼ bé֖̇yţ yĕhwá֣h ʼèlòhe֑y⁠ká lòֽʼ-ţĕbaşé֥̇̌l gĕ̇di֖y bȧ⁠ẖàlé֥b ʼiṁֽ⁠wò׃s"],[23,20,"הִנֵּ֨ה אָנֹכִ֜י שֹׁלֵ֤חַ מַלְאָךְ֙ לְ⁠פָנֶ֔י⁠ךָ לִ⁠שְׁמָרְ⁠ךָ֖ בַּ⁠דָּ֑רֶךְ וְ⁠לַ⁠הֲבִ֣יאֲ⁠ךָ֔ אֶל־הַ⁠מָּק֖וֹם אֲשֶׁ֥ר הֲכִנֹֽתִי׃","hiné̇֨h ʼánòki֜y şò̌lé֤ẖa malĕʼákĕ֙ lĕ⁠páne֔y⁠ká li⁠şĕ̌márĕ⁠ká֖ bȧ⁠dá֑̇rekĕ wĕ⁠la⁠hàbi֣yʼà⁠ká֔ ʼel-ha⁠má̇q֖wòm ʼàşě֥r hàkinòֽţiy׃"],[23,21,"הִשָּׁ֧מֶר מִ⁠פָּנָ֛י⁠ו וּ⁠שְׁמַ֥ע בְּ⁠קֹל֖⁠וֹ אַל־תַּמֵּ֣ר בּ֑⁠וֹ כִּ֣י לֹ֤א יִשָּׂא֙ לְ⁠פִשְׁעֲ⁠כֶ֔ם כִּ֥י שְׁמִ֖⁠י בְּ⁠קִרְבּֽ⁠וֹ׃","hişá֧̇̌mer mi⁠pá̇ná֛y⁠w ẇ⁠şĕ̌ma֥ʻ bĕ̇⁠qòl֖⁠wò ʼal-ţȧmé֣̇r ḃ֑⁠wò ki֣̇y lò֤ʼ yişá̇̂ʼ֙ lĕ⁠pişĕ̌ʻà⁠ke֔m ki֥̇y şĕ̌mi֖⁠y bĕ̇⁠qirĕḃֽ⁠wò׃"],[23,22,"כִּ֣י אִם־שָׁמֹ֤עַ תִּשְׁמַע֙ בְּ⁠קֹל֔⁠וֹ וְ⁠עָשִׂ֕יתָ כֹּ֖ל אֲשֶׁ֣ר אֲדַבֵּ֑ר וְ⁠אָֽיַבְתִּי֙ אֶת־אֹ֣יְבֶ֔י⁠ךָ וְ⁠צַרְתִּ֖י אֶת־צֹרְרֶֽי⁠ךָ׃","ki֣̇y ʼim-şá̌mò֤ʻa ţi̇şĕ̌maʻ֙ bĕ̇⁠qòl֔⁠wò wĕ⁠ʻáşî֕yţá kò֖̇l ʼàşě֣r ʼàdabé֑̇r wĕ⁠ʼáֽyabĕţi̇y֙ ʼeţ-ʼò֣yĕbe֔y⁠ká wĕ⁠ẕarĕţi֖̇y ʼeţ-ẕòrĕreֽy⁠ká׃"],[23,23,"כִּֽי־יֵלֵ֣ךְ מַלְאָכִ⁠י֮ לְ⁠פָנֶי⁠ךָ֒ וֶ⁠הֱבִֽיאֲ⁠ךָ֗ אֶל־הָֽ⁠אֱמֹרִי֙ וְ⁠הַ֣⁠חִתִּ֔י וְ⁠הַ⁠פְּרִזִּי֙ וְ⁠הַֽ⁠כְּנַעֲנִ֔י הַ⁠חִוִּ֖י וְ⁠הַ⁠יְבוּסִ֑י וְ⁠הִכְחַדְתִּֽי⁠ו׃","kiֽ̇y-yélé֣kĕ malĕʼáki⁠y֮ lĕ⁠páney⁠ká֒ we⁠hèbiֽyʼà⁠ká֗ ʼel-háֽ⁠ʼèmòriy֙ wĕ⁠ha֣⁠ẖiţi̇֔y wĕ⁠ha⁠pĕ̇rizi̇y֙ wĕ⁠haֽ⁠kĕ̇naʻàni֔y ha⁠ẖiwi֖̇y wĕ⁠ha⁠yĕbẇsi֑y wĕ⁠hikĕẖadĕţiֽ̇y⁠w׃"],[23,24,"לֹֽא־תִשְׁתַּחֲוֶ֤ה לֵ⁠אלֹֽהֵי⁠הֶם֙ וְ⁠לֹ֣א תָֽעָבְדֵ֔⁠ם וְ⁠לֹ֥א תַעֲשֶׂ֖ה כְּ⁠מַֽעֲשֵׂי⁠הֶ֑ם כִּ֤י הָרֵס֙ תְּהָ֣רְסֵ֔⁠ם וְ⁠שַׁבֵּ֥ר תְּשַׁבֵּ֖ר מַצֵּבֹתֵי⁠הֶֽם׃","lòֽʼ-ţişĕ̌ţȧẖàwe֤h lé⁠ʼlòֽhéy⁠hem֙ wĕ⁠lò֣ʼ ţáֽʻábĕdé֔⁠m wĕ⁠lò֥ʼ ţaʻàşê֖h kĕ̇⁠maֽʻàşé̂y⁠he֑m ki֤̇y hárés֙ ţĕ̇há֣rĕsé֔⁠m wĕ⁠şǎbé֥̇r ţĕ̇şǎbé֖̇r maẕé̇bòţéy⁠heֽm׃"],[23,25,"וַ⁠עֲבַדְתֶּ֗ם אֵ֚ת יְהוָ֣ה אֱלֹֽהֵי⁠כֶ֔ם וּ⁠בֵרַ֥ךְ אֶֽת־לַחְמְ⁠ךָ֖ וְ⁠אֶת־מֵימֶ֑י⁠ךָ וַ⁠הֲסִרֹתִ֥י מַחֲלָ֖ה מִ⁠קִּרְבֶּֽ⁠ךָ׃","wa⁠ʻàbadĕţė֗m ʼé֚ţ yĕhwá֣h ʼèlòֽhéy⁠ke֔m ẇ⁠béra֥kĕ ʼeֽţ-laẖĕmĕ⁠ká֖ wĕ⁠ʼeţ-méyme֑y⁠ká wa⁠hàsiròţi֥y maẖàlá֖h mi⁠qi̇rĕbėֽ⁠ká׃"],[23,26,"לֹ֥א תִהְיֶ֛ה מְשַׁכֵּלָ֥ה וַ⁠עֲקָרָ֖ה בְּ⁠אַרְצֶ֑⁠ךָ אֶת־מִסְפַּ֥ר יָמֶ֖י⁠ךָ אֲמַלֵּֽא׃","lò֥ʼ ţihĕye֛h mĕşǎké̇lá֥h wa⁠ʻàqárá֖h bĕ̇⁠ʼarĕẕe֑⁠ká ʼeţ-misĕpȧ֥r yáme֖y⁠ká ʼàmaléֽ̇ʼ׃"],[23,27,"אֶת־אֵֽימָתִ⁠י֙ אֲשַׁלַּ֣ח לְ⁠פָנֶ֔י⁠ךָ וְ⁠הַמֹּתִי֙ אֶת־כָּל־הָ⁠עָ֔ם אֲשֶׁ֥ר תָּבֹ֖א בָּ⁠הֶ֑ם וְ⁠נָתַתִּ֧י אֶת־כָּל־אֹיְבֶ֛י⁠ךָ אֵלֶ֖י⁠ךָ עֹֽרֶף׃","ʼeţ-ʼéֽymáţi⁠y֙ ʼàşǎlȧ֣ẖ lĕ⁠páne֔y⁠ká wĕ⁠hamò̇ţiy֙ ʼeţ-ká̇l-há⁠ʻá֔m ʼàşě֥r ţá̇bò֖ʼ bá̇⁠he֑m wĕ⁠náţaţi֧̇y ʼeţ-ká̇l-ʼòyĕbe֛y⁠ká ʼéle֖y⁠ká ʻòֽrep׃"],[23,28,"וְ⁠שָׁלַחְתִּ֥י אֶת־הַ⁠צִּרְעָ֖ה לְ⁠פָנֶ֑י⁠ךָ וְ⁠גֵרְשָׁ֗ה אֶת־הַ⁠חִוִּ֧י אֶת־הַֽ⁠כְּנַעֲנִ֛י וְ⁠אֶת־הַ⁠חִתִּ֖י מִ⁠לְּ⁠פָנֶֽי⁠ךָ׃","wĕ⁠şá̌laẖĕţi֥̇y ʼeţ-ha⁠ẕi̇rĕʻá֖h lĕ⁠páne֑y⁠ká wĕ⁠gérĕşá̌֗h ʼeţ-ha⁠ẖiwi֧̇y ʼeţ-haֽ⁠kĕ̇naʻàni֛y wĕ⁠ʼeţ-ha⁠ẖiţi֖̇y mi⁠lĕ̇⁠páneֽy⁠ká׃"],[23,29,"לֹ֧א אֲגָרְשֶׁ֛⁠נּוּ מִ⁠פָּנֶ֖י⁠ךָ בְּ⁠שָׁנָ֣ה אֶחָ֑ת פֶּן־תִּהְיֶ֤ה הָ⁠אָ֨רֶץ֙ שְׁמָמָ֔ה וְ⁠רַבָּ֥ה עָלֶ֖י⁠ךָ חַיַּ֥ת הַ⁠שָּׂדֶֽה׃","lò֧ʼ ʼàgárĕşě֛⁠ṅẇ mi⁠pá̇ne֖y⁠ká bĕ̇⁠şá̌ná֣h ʼeẖá֑ţ pėn-ţi̇hĕye֤h há⁠ʼá֨reẕ֙ şĕ̌mámá֔h wĕ⁠rabá֥̇h ʻále֖y⁠ká ẖayȧ֥ţ ha⁠şá̇̂deֽh׃"],[23,30,"מְעַ֥ט מְעַ֛ט אֲגָרְשֶׁ֖⁠נּוּ מִ⁠פָּנֶ֑י⁠ךָ עַ֚ד אֲשֶׁ֣ר תִּפְרֶ֔ה וְ⁠נָחַלְתָּ֖ אֶת־הָ⁠אָֽרֶץ׃","mĕʻa֥t mĕʻa֛t ʼàgárĕşě֖⁠ṅẇ mi⁠pá̇ne֑y⁠ká ʻa֚d ʼàşě֣r ţi̇pĕre֔h wĕ⁠náẖalĕţá֖̇ ʼeţ-há⁠ʼáֽreẕ׃"],[23,31,"וְ⁠שַׁתִּ֣י אֶת־גְּבֻלְ⁠ךָ֗ מִ⁠יַּם־סוּף֙ וְ⁠עַד־יָ֣ם פְּלִשְׁתִּ֔ים וּ⁠מִ⁠מִּדְבָּ֖ר עַד־הַ⁠נָּהָ֑ר כִּ֣י ׀ אֶתֵּ֣ן בְּ⁠יֶדְ⁠כֶ֗ם אֵ֚ת יֹשְׁבֵ֣י הָ⁠אָ֔רֶץ וְ⁠גֵרַשְׁתָּ֖⁠מוֹ מִ⁠פָּנֶֽי⁠ךָ׃","wĕ⁠şǎţi֣̇y ʼeţ-gĕ̇bulĕ⁠ká֗ mi⁠yȧm-sẇp֙ wĕ⁠ʻad-yá֣m pĕ̇lişĕ̌ţi̇֔ym ẇ⁠mi⁠mi̇dĕbá֖̇r ʻad-ha⁠ná̇há֑r ki֣̇y ׀ ʼeţé֣̇n bĕ̇⁠yedĕ⁠ke֗m ʼé֚ţ yòşĕ̌bé֣y há⁠ʼá֔reẕ wĕ⁠géraşĕ̌ţá֖̇⁠mwò mi⁠pá̇neֽy⁠ká׃"],[23,32,"לֹֽא־תִכְרֹ֥ת לָ⁠הֶ֛ם וְ⁠לֵ⁠אלֹֽהֵי⁠הֶ֖ם בְּרִֽית׃","lòֽʼ-ţikĕrò֥ţ lá⁠he֛m wĕ⁠lé⁠ʼlòֽhéy⁠he֖m bĕ̇riֽyţ׃"],[23,33,"לֹ֤א יֵשְׁבוּ֙ בְּ⁠אַרְצְ⁠ךָ֔ פֶּן־יַחֲטִ֥יאוּ אֹתְ⁠ךָ֖ לִ֑⁠י כִּ֤י תַעֲבֹד֙ אֶת־אֱלֹ֣הֵי⁠הֶ֔ם כִּֽי־יִהְיֶ֥ה לְ⁠ךָ֖ לְ⁠מוֹקֵֽשׁ׃פ","lò֤ʼ yéşĕ̌bẇ֙ bĕ̇⁠ʼarĕẕĕ⁠ká֔ pėn-yaẖàti֥yʼẇ ʼòţĕ⁠ká֖ li֑⁠y ki֤̇y ţaʻàbòd֙ ʼeţ-ʼèlò֣héy⁠he֔m kiֽ̇y-yihĕye֥h lĕ⁠ká֖ lĕ⁠mwòqéֽş̌׃p"],[24,1,"וְ⁠אֶל־מֹשֶׁ֨ה אָמַ֜ר עֲלֵ֣ה אֶל־יְהוָ֗ה אַתָּה֙ וְ⁠אַהֲרֹן֙ נָדָ֣ב וַ⁠אֲבִיה֔וּא וְ⁠שִׁבְעִ֖ים מִ⁠זִּקְנֵ֣י יִשְׂרָאֵ֑ל וְ⁠הִשְׁתַּחֲוִיתֶ֖ם מֵ⁠רָחֹֽק׃","wĕ⁠ʼel-mòşě֨h ʼáma֜r ʻàlé֣h ʼel-yĕhwá֗h ʼaţá̇h֙ wĕ⁠ʼahàròn֙ nádá֣b wa⁠ʼàbiyh֔ẇʼ wĕ⁠şǐbĕʻi֖ym mi⁠zi̇qĕné֣y yişĕ̂ráʼé֑l wĕ⁠hişĕ̌ţȧẖàwiyţe֖m mé⁠ráẖòֽq׃"],[24,2,"וְ⁠נִגַּ֨שׁ מֹשֶׁ֤ה לְ⁠בַדּ⁠וֹ֙ אֶל־יְהוָ֔ה וְ⁠הֵ֖ם לֹ֣א יִגָּ֑שׁוּ וְ⁠הָ⁠עָ֕ם לֹ֥א יַעֲל֖וּ עִמּֽ⁠וֹ׃","wĕ⁠nigȧ֨ş̌ mòşě֤h lĕ⁠baḋ⁠wò֙ ʼel-yĕhwá֔h wĕ⁠hé֖m lò֣ʼ yigá֑̇ş̌ẇ wĕ⁠há⁠ʻá֕m lò֥ʼ yaʻàl֖ẇ ʻiṁֽ⁠wò׃"],[24,3,"וַ⁠יָּבֹ֣א מֹשֶׁ֗ה וַ⁠יְסַפֵּ֤ר לָ⁠עָם֙ אֵ֚ת כָּל־דִּבְרֵ֣י יְהוָ֔ה וְ⁠אֵ֖ת כָּל־הַ⁠מִּשְׁפָּטִ֑ים וַ⁠יַּ֨עַן כָּל־הָ⁠עָ֜ם ק֤וֹל אֶחָד֙ וַ⁠יֹּ֣אמְר֔וּ כָּל־הַ⁠דְּבָרִ֛ים אֲשֶׁר־דִּבֶּ֥ר יְהוָ֖ה נַעֲשֶֽׂה׃","wa⁠yá̇bò֣ʼ mòşě֗h wa⁠yĕsapé֤̇r lá⁠ʻám֙ ʼé֚ţ ká̇l-di̇bĕré֣y yĕhwá֔h wĕ⁠ʼé֖ţ ká̇l-ha⁠mi̇şĕ̌pá̇ti֑ym wa⁠yȧ֨ʻan ká̇l-há⁠ʻá֜m q֤wòl ʼeẖád֙ wa⁠yò֣̇ʼmĕr֔ẇ ká̇l-ha⁠dĕ̇bári֛ym ʼàşěr-di̇bė֥r yĕhwá֖h naʻàşêֽh׃"],[24,4,"וַ⁠יִּכְתֹּ֣ב מֹשֶׁ֗ה אֵ֚ת כָּל־דִּבְרֵ֣י יְהוָ֔ה וַ⁠יַּשְׁכֵּ֣ם בַּ⁠בֹּ֔קֶר וַ⁠יִּ֥בֶן מִזְבֵּ֖חַ תַּ֣חַת הָ⁠הָ֑ר וּ⁠שְׁתֵּ֤ים עֶשְׂרֵה֙ מַצֵּבָ֔ה לִ⁠שְׁנֵ֥ים עָשָׂ֖ר שִׁבְטֵ֥י יִשְׂרָאֵֽל׃","wa⁠yi̇kĕţò֣̇b mòşě֗h ʼé֚ţ ká̇l-di̇bĕré֣y yĕhwá֔h wa⁠yȧşĕ̌ké֣̇m bȧ⁠bò̇֔qer wa⁠yi֥̇ben mizĕbé֖̇ẖa ţȧ֣ẖaţ há⁠há֑r ẇ⁠şĕ̌ţé֤̇ym ʻeşĕ̂réh֙ maẕé̇bá֔h li⁠şĕ̌né֥ym ʻáşá֖̂r şǐbĕté֥y yişĕ̂ráʼéֽl׃"],[24,5,"וַ⁠יִּשְׁלַ֗ח אֶֽת־נַעֲרֵי֙ בְּנֵ֣י יִשְׂרָאֵ֔ל וַ⁠יַּֽעֲל֖וּ עֹלֹ֑ת וַֽ⁠יִּזְבְּח֞וּ זְבָחִ֧ים שְׁלָמִ֛ים לַ⁠יהוָ֖ה פָּרִֽים׃","wa⁠yi̇şĕ̌la֗ẖ ʼeֽţ-naʻàréy֙ bĕ̇né֣y yişĕ̂ráʼé֔l wa⁠ẏֽaʻàl֖ẇ ʻòlò֑ţ waֽ⁠yi̇zĕbĕ̇ẖ֞ẇ zĕbáẖi֧ym şĕ̌lámi֛ym la⁠yhwá֖h pá̇riֽym׃"],[24,6,"וַ⁠יִּקַּ֤ח מֹשֶׁה֙ חֲצִ֣י הַ⁠דָּ֔ם וַ⁠יָּ֖שֶׂם בָּ⁠אַגָּנֹ֑ת וַ⁠חֲצִ֣י הַ⁠דָּ֔ם זָרַ֖ק עַל־הַ⁠מִּזְבֵּֽחַ׃","wa⁠yi̇qȧ֤ẖ mòşěh֙ ẖàẕi֣y ha⁠dá̇֔m wa⁠yá֖̇şêm bá̇⁠ʼagá̇nò֑ţ wa⁠ẖàẕi֣y ha⁠dá̇֔m zára֖q ʻal-ha⁠mi̇zĕbéֽ̇ẖa׃"],[24,7,"וַ⁠יִּקַּח֙ סֵ֣פֶר הַ⁠בְּרִ֔ית וַ⁠יִּקְרָ֖א בְּ⁠אָזְנֵ֣י הָ⁠עָ֑ם וַ⁠יֹּ֣אמְר֔וּ כֹּ֛ל אֲשֶׁר־דִּבֶּ֥ר יְהוָ֖ה נַעֲשֶׂ֥ה וְ⁠נִשְׁמָֽע׃","wa⁠yi̇qȧẖ֙ sé֣per ha⁠bĕ̇ri֔yţ wa⁠yi̇qĕrá֖ʼ bĕ̇⁠ʼázĕné֣y há⁠ʻá֑m wa⁠yò֣̇ʼmĕr֔ẇ kò֛̇l ʼàşěr-di̇bė֥r yĕhwá֖h naʻàşê֥h wĕ⁠nişĕ̌máֽʻ׃"],[24,8,"וַ⁠יִּקַּ֤ח מֹשֶׁה֙ אֶת־הַ⁠דָּ֔ם וַ⁠יִּזְרֹ֖ק עַל־הָ⁠עָ֑ם וַ⁠יֹּ֗אמֶר הִנֵּ֤ה דַֽם־הַ⁠בְּרִית֙ אֲשֶׁ֨ר כָּרַ֤ת יְהוָה֙ עִמָּ⁠כֶ֔ם עַ֥ל כָּל־הַ⁠דְּבָרִ֖ים הָ⁠אֵֽלֶּה׃","wa⁠yi̇qȧ֤ẖ mòşěh֙ ʼeţ-ha⁠dá̇֔m wa⁠yi̇zĕrò֖q ʻal-há⁠ʻá֑m wa⁠yò̇֗ʼmer hiné֤̇h daֽm-ha⁠bĕ̇riyţ֙ ʼàşě֨r ká̇ra֤ţ yĕhwáh֙ ʻimá̇⁠ke֔m ʻa֥l ká̇l-ha⁠dĕ̇bári֖ym há⁠ʼéֽlėh׃"],[24,9,"וַ⁠יַּ֥עַל מֹשֶׁ֖ה וְ⁠אַהֲרֹ֑ן נָדָב֙ וַ⁠אֲבִיה֔וּא וְ⁠שִׁבְעִ֖ים מִ⁠זִּקְנֵ֥י יִשְׂרָאֵֽל׃","wa⁠yȧ֥ʻal mòşě֖h wĕ⁠ʼahàrò֑n nádáb֙ wa⁠ʼàbiyh֔ẇʼ wĕ⁠şǐbĕʻi֖ym mi⁠zi̇qĕné֥y yişĕ̂ráʼéֽl׃"],[24,10,"וַ⁠יִּרְא֕וּ אֵ֖ת אֱלֹהֵ֣י יִשְׂרָאֵ֑ל וְ⁠תַ֣חַת רַגְלָ֗י⁠ו כְּ⁠מַעֲשֵׂה֙ לִבְנַ֣ת הַ⁠סַּפִּ֔יר וּ⁠כְ⁠עֶ֥צֶם הַ⁠שָּׁמַ֖יִם לָ⁠טֹֽהַר׃","wa⁠yi̇rĕʼ֕ẇ ʼé֖ţ ʼèlòhé֣y yişĕ̂ráʼé֑l wĕ⁠ţa֣ẖaţ ragĕlá֗y⁠w kĕ̇⁠maʻàşé̂h֙ libĕna֣ţ ha⁠sȧpi̇֔yr ẇ⁠kĕ⁠ʻe֥ẕem ha⁠şá̇̌ma֖yim lá⁠tòֽhar׃"],[24,11,"וְ⁠אֶל־אֲצִילֵי֙ בְּנֵ֣י יִשְׂרָאֵ֔ל לֹ֥א שָׁלַ֖ח יָד֑⁠וֹ וַֽ⁠יֶּחֱזוּ֙ אֶת־הָ֣⁠אֱלֹהִ֔ים וַ⁠יֹּאכְל֖וּ וַ⁠יִּשְׁתּֽוּ׃ס","wĕ⁠ʼel-ʼàẕiyléy֙ bĕ̇né֣y yişĕ̂ráʼé֔l lò֥ʼ şá̌la֖ẖ yád֑⁠wò waֽ⁠yėẖèzẇ֙ ʼeţ-há֣⁠ʼèlòhi֔ym wa⁠yò̇ʼkĕl֖ẇ wa⁠yi̇şĕ̌ţֽ̇ẇ׃s"],[24,12,"וַ⁠יֹּ֨אמֶר יְהוָ֜ה אֶל־מֹשֶׁ֗ה עֲלֵ֥ה אֵלַ֛⁠י הָ⁠הָ֖רָ⁠ה וֶ⁠הְיֵה־שָׁ֑ם וְ⁠אֶתְּנָ֨ה לְ⁠ךָ֜ אֶת־לֻחֹ֣ת הָ⁠אֶ֗בֶן וְ⁠הַ⁠תּוֹרָה֙ וְ⁠הַ⁠מִּצְוָ֔ה אֲשֶׁ֥ר כָּתַ֖בְתִּי לְ⁠הוֹרֹתָֽ⁠ם׃","wa⁠yò̇֨ʼmer yĕhwá֜h ʼel-mòşě֗h ʻàlé֥h ʼéla֛⁠y há⁠há֖rá⁠h we⁠hĕyéh-şá֑̌m wĕ⁠ʼeţĕ̇ná֨h lĕ⁠ká֜ ʼeţ-luẖò֣ţ há⁠ʼe֗ben wĕ⁠ha⁠ţ̇wòráh֙ wĕ⁠ha⁠mi̇ẕĕwá֔h ʼàşě֥r ká̇ţa֖bĕţi̇y lĕ⁠hwòròţáֽ⁠m׃"],[24,13,"וַ⁠יָּ֣קָם מֹשֶׁ֔ה וִ⁠יהוֹשֻׁ֖עַ מְשָׁרְת֑⁠וֹ וַ⁠יַּ֥עַל מֹשֶׁ֖ה אֶל־הַ֥ר הָ⁠אֱלֹהִֽים׃","wa⁠yá֣̇qám mòşě֔h wi⁠yhwòşǔ֖ʻa mĕşá̌rĕţ֑⁠wò wa⁠yȧ֥ʻal mòşě֖h ʼel-ha֥r há⁠ʼèlòhiֽym׃"],[24,14,"וְ⁠אֶל־הַ⁠זְּקֵנִ֤ים אָמַר֙ שְׁבוּ־לָ֣⁠נוּ בָ⁠זֶ֔ה עַ֥ד אֲשֶׁר־נָשׁ֖וּב אֲלֵי⁠כֶ֑ם וְ⁠הִנֵּ֨ה אַהֲרֹ֤ן וְ⁠חוּר֙ עִמָּ⁠כֶ֔ם מִי־בַ֥עַל דְּבָרִ֖ים יִגַּ֥שׁ אֲלֵ⁠הֶֽם׃","wĕ⁠ʼel-ha⁠zĕ̇qéni֤ym ʼámar֙ şĕ̌bẇ-lá֣⁠nẇ bá⁠ze֔h ʻa֥d ʼàşěr-náş֖̌ẇb ʼàléy⁠ke֑m wĕ⁠hiné̇֨h ʼahàrò֤n wĕ⁠ẖẇr֙ ʻimá̇⁠ke֔m miy-ba֥ʻal dĕ̇bári֖ym yigȧ֥ş̌ ʼàlé⁠heֽm׃"],[24,15,"וַ⁠יַּ֥עַל מֹשֶׁ֖ה אֶל־הָ⁠הָ֑ר וַ⁠יְכַ֥ס הֶ⁠עָנָ֖ן אֶת־הָ⁠הָֽר׃","wa⁠yȧ֥ʻal mòşě֖h ʼel-há⁠há֑r wa⁠yĕka֥s he⁠ʻáná֖n ʼeţ-há⁠háֽr׃"],[24,16,"וַ⁠יִּשְׁכֹּ֤ן כְּבוֹד־יְהוָה֙ עַל־הַ֣ר סִינַ֔י וַ⁠יְכַסֵּ֥⁠הוּ הֶ⁠עָנָ֖ן שֵׁ֣שֶׁת יָמִ֑ים וַ⁠יִּקְרָ֧א אֶל־מֹשֶׁ֛ה בַּ⁠יּ֥וֹם הַ⁠שְּׁבִיעִ֖י מִ⁠תּ֥וֹךְ הֶ⁠עָנָֽן׃","wa⁠yi̇şĕ̌kò֤̇n kĕ̇bwòd-yĕhwáh֙ ʻal-ha֣r siyna֔y wa⁠yĕkasé֥̇⁠hẇ he⁠ʻáná֖n şé֣̌şěţ yámi֑ym wa⁠yi̇qĕrá֧ʼ ʼel-mòşě֛h bȧ⁠ẏ֥wòm ha⁠şĕ̇̌biyʻi֖y mi⁠ţ֥̇wòkĕ he⁠ʻánáֽn׃"],[24,17,"וּ⁠מַרְאֵה֙ כְּב֣וֹד יְהוָ֔ה כְּ⁠אֵ֥שׁ אֹכֶ֖לֶת בְּ⁠רֹ֣אשׁ הָ⁠הָ֑ר לְ⁠עֵינֵ֖י בְּנֵ֥י יִשְׂרָאֵֽל׃","ẇ⁠marĕʼéh֙ kĕ̇b֣wòd yĕhwá֔h kĕ̇⁠ʼé֥ş̌ ʼòke֖leţ bĕ̇⁠rò֣ʼş̌ há⁠há֑r lĕ⁠ʻéyné֖y bĕ̇né֥y yişĕ̂ráʼéֽl׃"],[24,18,"וַ⁠יָּבֹ֥א מֹשֶׁ֛ה בְּ⁠ת֥וֹךְ הֶ⁠עָנָ֖ן וַ⁠יַּ֣עַל אֶל־הָ⁠הָ֑ר וַ⁠יְהִ֤י מֹשֶׁה֙ בָּ⁠הָ֔ר אַרְבָּעִ֣ים י֔וֹם וְ⁠אַרְבָּעִ֖ים לָֽיְלָה׃פ","wa⁠yá̇bò֥ʼ mòşě֛h bĕ̇⁠ţ֥wòkĕ he⁠ʻáná֖n wa⁠yȧ֣ʻal ʼel-há⁠há֑r wa⁠yĕhi֤y mòşěh֙ bá̇⁠há֔r ʼarĕbá̇ʻi֣ym y֔wòm wĕ⁠ʼarĕbá̇ʻi֖ym láֽyĕláh׃p"],[25,1,"וַ⁠יְדַבֵּ֥ר יְהוָ֖ה אֶל־מֹשֶׁ֥ה לֵּ⁠אמֹֽר׃","wa⁠yĕdabé֥̇r yĕhwá֖h ʼel-mòşě֥h lé̇⁠ʼmòֽr׃"],[25,2,"דַּבֵּר֙ אֶל־בְּנֵ֣י יִשְׂרָאֵ֔ל וְ⁠יִקְחוּ־לִ֖⁠י תְּרוּמָ֑ה מֵ⁠אֵ֤ת כָּל־אִישׁ֙ אֲשֶׁ֣ר יִדְּבֶ֣⁠נּוּ לִבּ֔⁠וֹ תִּקְח֖וּ אֶת־תְּרוּמָתִֽ⁠י׃","dȧbé̇r֙ ʼel-bĕ̇né֣y yişĕ̂ráʼé֔l wĕ⁠yiqĕẖẇ-li֖⁠y ţĕ̇rẇmá֑h mé⁠ʼé֤ţ ká̇l-ʼiyş̌֙ ʼàşě֣r yidĕ̇be֣⁠ṅẇ liḃ֔⁠wò ţi̇qĕẖ֖ẇ ʼeţ-ţĕ̇rẇmáţiֽ⁠y׃"],[25,3,"וְ⁠זֹאת֙ הַ⁠תְּרוּמָ֔ה אֲשֶׁ֥ר תִּקְח֖וּ מֵ⁠אִתָּ֑⁠ם זָהָ֥ב וָ⁠כֶ֖סֶף וּ⁠נְחֹֽשֶׁת׃","wĕ⁠zòʼţ֙ ha⁠ţĕ̇rẇmá֔h ʼàşě֥r ţi̇qĕẖ֖ẇ mé⁠ʼiţá֑̇⁠m záhá֥b wá⁠ke֖sep ẇ⁠nĕẖòֽşěţ׃"],[25,4,"וּ⁠תְכֵ֧לֶת וְ⁠אַרְגָּמָ֛ן וְ⁠תוֹלַ֥עַת שָׁנִ֖י וְ⁠שֵׁ֥שׁ וְ⁠עִזִּֽים׃","ẇ⁠ţĕké֧leţ wĕ⁠ʼarĕgá̇má֛n wĕ⁠ţwòla֥ʻaţ şá̌ni֖y wĕ⁠şé֥̌ş̌ wĕ⁠ʻiziֽ̇ym׃"],[25,5,"וְ⁠עֹרֹ֨ת אֵילִ֧ם מְאָדָּמִ֛ים וְ⁠עֹרֹ֥ת תְּחָשִׁ֖ים וַ⁠עֲצֵ֥י שִׁטִּֽים׃","wĕ⁠ʻòrò֨ţ ʼéyli֧m mĕʼádá̇mi֛ym wĕ⁠ʻòrò֥ţ ţĕ̇ẖáşǐ֖ym wa⁠ʻàẕé֥y şǐtiֽ̇ym׃"],[25,6,"שֶׁ֖מֶן לַ⁠מָּאֹ֑ר בְּשָׂמִים֙ לְ⁠שֶׁ֣מֶן הַ⁠מִּשְׁחָ֔ה וְ⁠לִ⁠קְטֹ֖רֶת הַ⁠סַּמִּֽים׃","şě֖men la⁠má̇ʼò֑r bĕ̇şá̂miym֙ lĕ⁠şě֣men ha⁠mi̇şĕ̌ẖá֔h wĕ⁠li⁠qĕtò֖reţ ha⁠sȧmiֽ̇ym׃"],[25,7,"אַבְנֵי־שֹׁ֕הַם וְ⁠אַבְנֵ֖י מִלֻּאִ֑ים לָ⁠אֵפֹ֖ד וְ⁠לַ⁠חֹֽשֶׁן׃","ʼabĕnéy-şò̌֕ham wĕ⁠ʼabĕné֖y milu̇ʼi֑ym lá⁠ʼépò֖d wĕ⁠la⁠ẖòֽşěn׃"],[25,8,"וְ⁠עָ֥שׂוּ לִ֖⁠י מִקְדָּ֑שׁ וְ⁠שָׁכַנְתִּ֖י בְּ⁠תוֹכָֽ⁠ם׃","wĕ⁠ʻá֥ş̂ẇ li֖⁠y miqĕdá֑̇ş̌ wĕ⁠şá̌kanĕţi֖̇y bĕ̇⁠ţwòkáֽ⁠m׃"],[25,9,"כְּ⁠כֹ֗ל אֲשֶׁ֤ר אֲנִי֙ מַרְאֶ֣ה אוֹתְ⁠ךָ֔ אֵ֚ת תַּבְנִ֣ית הַ⁠מִּשְׁכָּ֔ן וְ⁠אֵ֖ת תַּבְנִ֣ית כָּל־כֵּלָ֑י⁠ו וְ⁠כֵ֖ן תַּעֲשֽׂוּ׃ס","kĕ̇⁠kò֗l ʼàşě֤r ʼàniy֙ marĕʼe֣h ʼwòţĕ⁠ká֔ ʼé֚ţ ţȧbĕni֣yţ ha⁠mi̇şĕ̌ká̇֔n wĕ⁠ʼé֖ţ ţȧbĕni֣yţ ká̇l-ké̇lá֑y⁠w wĕ⁠ké֖n ţȧʻàşֽ̂ẇ׃s"],[25,10,"וְ⁠עָשׂ֥וּ אֲר֖וֹן עֲצֵ֣י שִׁטִּ֑ים אַמָּתַ֨יִם וָ⁠חֵ֜צִי אָרְכּ֗⁠וֹ וְ⁠אַמָּ֤ה וָ⁠חֵ֨צִי֙ רָחְבּ֔⁠וֹ וְ⁠אַמָּ֥ה וָ⁠חֵ֖צִי קֹמָתֽ⁠וֹ׃","wĕ⁠ʻáş֥̂ẇ ʼàr֖wòn ʻàẕé֣y şǐti֑̇ym ʼamá̇ţa֨yim wá⁠ẖé֜ẕiy ʼárĕk̇֗⁠wò wĕ⁠ʼamá֤̇h wá⁠ẖé֨ẕiy֙ ráẖĕḃ֔⁠wò wĕ⁠ʼamá֥̇h wá⁠ẖé֖ẕiy qòmáţֽ⁠wò׃"],[25,11,"וְ⁠צִפִּיתָ֤ אֹת⁠וֹ֙ זָהָ֣ב טָה֔וֹר מִ⁠בַּ֥יִת וּ⁠מִ⁠ח֖וּץ תְּצַפֶּ֑⁠נּוּ וְ⁠עָשִׂ֧יתָ עָלָ֛י⁠ו זֵ֥ר זָהָ֖ב סָבִֽיב׃","wĕ⁠ẕipi̇yţá֤ ʼòţ⁠wò֙ záhá֣b táh֔wòr mi⁠bȧ֥yiţ ẇ⁠mi⁠ẖ֖ẇẕ ţĕ̇ẕapė֑⁠ṅẇ wĕ⁠ʻáşî֧yţá ʻálá֛y⁠w zé֥r záhá֖b sábiֽyb׃"],[25,12,"וְ⁠יָצַ֣קְתָּ לּ֗⁠וֹ אַרְבַּע֙ טַבְּעֹ֣ת זָהָ֔ב וְ⁠נָ֣תַתָּ֔ה עַ֖ל אַרְבַּ֣ע פַּעֲמֹתָ֑י⁠ו וּ⁠שְׁתֵּ֣י טַבָּעֹ֗ת עַל־צַלְע⁠וֹ֙ הָֽ⁠אֶחָ֔ת וּ⁠שְׁתֵּי֙ טַבָּעֹ֔ת עַל־צַלְע֖⁠וֹ הַ⁠שֵּׁנִֽית׃","wĕ⁠yáẕa֣qĕţá̇ l̇֗⁠wò ʼarĕbȧʻ֙ tabĕ̇ʻò֣ţ záhá֔b wĕ⁠ná֣ţaţá̇֔h ʻa֖l ʼarĕbȧ֣ʻ pȧʻàmòţá֑y⁠w ẇ⁠şĕ̌ţé֣̇y tabá̇ʻò֗ţ ʻal-ẕalĕʻ⁠wò֙ háֽ⁠ʼeẖá֔ţ ẇ⁠şĕ̌ţé̇y֙ tabá̇ʻò֔ţ ʻal-ẕalĕʻ֖⁠wò ha⁠şé̇̌niֽyţ׃"],[25,13,"וְ⁠עָשִׂ֥יתָ בַדֵּ֖י עֲצֵ֣י שִׁטִּ֑ים וְ⁠צִפִּיתָ֥ אֹתָ֖⁠ם זָהָֽב׃","wĕ⁠ʻáşî֥yţá badé֖̇y ʻàẕé֣y şǐti֑̇ym wĕ⁠ẕipi̇yţá֥ ʼòţá֖⁠m záháֽb׃"],[25,14,"וְ⁠הֵֽבֵאתָ֤ אֶת־הַ⁠בַּדִּים֙ בַּ⁠טַּבָּעֹ֔ת עַ֖ל צַלְעֹ֣ת הָ⁠אָרֹ֑ן לָ⁠שֵׂ֥את אֶת־הָ⁠אָרֹ֖ן בָּ⁠הֶֽם׃","wĕ⁠héֽbéʼţá֤ ʼeţ-ha⁠bȧdi̇ym֙ bȧ⁠tȧbá̇ʻò֔ţ ʻa֖l ẕalĕʻò֣ţ há⁠ʼárò֑n lá⁠şé֥̂ʼţ ʼeţ-há⁠ʼárò֖n bá̇⁠heֽm׃"],[25,15,"בְּ⁠טַבְּעֹת֙ הָ⁠אָרֹ֔ן יִהְי֖וּ הַ⁠בַּדִּ֑ים לֹ֥א יָסֻ֖רוּ מִמֶּֽ⁠נּוּ׃","bĕ̇⁠tabĕ̇ʻòţ֙ há⁠ʼárò֔n yihĕy֖ẇ ha⁠bȧdi֑̇ym lò֥ʼ yásu֖rẇ mimėֽ⁠ṅẇ׃"],[25,16,"וְ⁠נָתַתָּ֖ אֶל־הָ⁠אָרֹ֑ן אֵ֚ת הָ⁠עֵדֻ֔ת אֲשֶׁ֥ר אֶתֵּ֖ן אֵלֶֽי⁠ךָ׃","wĕ⁠náţaţá֖̇ ʼel-há⁠ʼárò֑n ʼé֚ţ há⁠ʻédu֔ţ ʼàşě֥r ʼeţé֖̇n ʼéleֽy⁠ká׃"],[25,17,"וְ⁠עָשִׂ֥יתָ כַפֹּ֖רֶת זָהָ֣ב טָה֑וֹר אַמָּתַ֤יִם וָ⁠חֵ֨צִי֙ אָרְכָּ֔⁠הּ וְ⁠אַמָּ֥ה וָ⁠חֵ֖צִי רָחְבָּֽ⁠הּ׃","wĕ⁠ʻáşî֥yţá kapò֖̇reţ záhá֣b táh֑wòr ʼamá̇ţa֤yim wá⁠ẖé֨ẕiy֙ ʼárĕká̇֔⁠ḣ wĕ⁠ʼamá֥̇h wá⁠ẖé֖ẕiy ráẖĕbáֽ̇⁠ḣ׃"],[25,18,"וְ⁠עָשִׂ֛יתָ שְׁנַ֥יִם כְּרֻבִ֖ים זָהָ֑ב מִקְשָׁה֙ תַּעֲשֶׂ֣ה אֹתָ֔⁠ם מִ⁠שְּׁנֵ֖י קְצ֥וֹת הַ⁠כַּפֹּֽרֶת׃","wĕ⁠ʻáşî֛yţá şĕ̌na֥yim kĕ̇rubi֖ym záhá֑b miqĕşá̌h֙ ţȧʻàşê֣h ʼòţá֔⁠m mi⁠şĕ̇̌né֖y qĕẕ֥wòţ ha⁠kȧpòֽ̇reţ׃"],[25,19,"וַ֠⁠עֲשֵׂה כְּר֨וּב אֶחָ֤ד מִ⁠קָּצָה֙ מִ⁠זֶּ֔ה וּ⁠כְרוּב־אֶחָ֥ד מִ⁠קָּצָ֖ה מִ⁠זֶּ֑ה מִן־הַ⁠כַּפֹּ֛רֶת תַּעֲשׂ֥וּ אֶת־הַ⁠כְּרֻבִ֖ים עַל־שְׁנֵ֥י קְצוֹתָֽי⁠ו׃","wa֠⁠ʻàşé̂h kĕ̇r֨ẇb ʼeẖá֤d mi⁠qá̇ẕáh֙ mi⁠zė֔h ẇ⁠kĕrẇb-ʼeẖá֥d mi⁠qá̇ẕá֖h mi⁠zė֑h min-ha⁠kȧpò֛̇reţ ţȧʻàş֥̂ẇ ʼeţ-ha⁠kĕ̇rubi֖ym ʻal-şĕ̌né֥y qĕẕwòţáֽy⁠w׃"],[25,20,"וְ⁠הָי֣וּ הַ⁠כְּרֻבִים֩ פֹּרְשֵׂ֨י כְנָפַ֜יִם לְ⁠מַ֗עְלָ⁠ה סֹכְכִ֤ים בְּ⁠כַנְפֵי⁠הֶם֙ עַל־הַ⁠כַּפֹּ֔רֶת וּ⁠פְנֵי⁠הֶ֖ם אִ֣ישׁ אֶל־אָחִ֑י⁠ו אֶל־הַ⁠כַּפֹּ֔רֶת יִהְי֖וּ פְּנֵ֥י הַ⁠כְּרֻבִֽים׃","wĕ⁠háy֣ẇ ha⁠kĕ̇rubiym֩ pò̇rĕşé̂֨y kĕnápa֜yim lĕ⁠ma֗ʻĕlá⁠h sòkĕki֤ym bĕ̇⁠kanĕpéy⁠hem֙ ʻal-ha⁠kȧpò̇֔reţ ẇ⁠pĕnéy⁠he֖m ʼi֣yş̌ ʼel-ʼáẖi֑y⁠w ʼel-ha⁠kȧpò̇֔reţ yihĕy֖ẇ pĕ̇né֥y ha⁠kĕ̇rubiֽym׃"],[25,21,"וְ⁠נָתַתָּ֧ אֶת־הַ⁠כַּפֹּ֛רֶת עַל־הָ⁠אָרֹ֖ן מִ⁠לְ⁠מָ֑עְלָ⁠ה וְ⁠אֶל־הָ֣⁠אָרֹ֔ן תִּתֵּן֙ אֶת־הָ֣⁠עֵדֻ֔ת אֲשֶׁ֥ר אֶתֵּ֖ן אֵלֶֽי⁠ךָ׃","wĕ⁠náţaţá֧̇ ʼeţ-ha⁠kȧpò֛̇reţ ʻal-há⁠ʼárò֖n mi⁠lĕ⁠má֑ʻĕlá⁠h wĕ⁠ʼel-há֣⁠ʼárò֔n ţi̇ţé̇n֙ ʼeţ-há֣⁠ʻédu֔ţ ʼàşě֥r ʼeţé֖̇n ʼéleֽy⁠ká׃"],[25,22,"וְ⁠נוֹעַדְתִּ֣י לְ⁠ךָ֮ שָׁם֒ וְ⁠דִבַּרְתִּ֨י אִתְּ⁠ךָ֜ מֵ⁠עַ֣ל הַ⁠כַּפֹּ֗רֶת מִ⁠בֵּין֙ שְׁנֵ֣י הַ⁠כְּרֻבִ֔ים אֲשֶׁ֖ר עַל־אֲרֹ֣ן הָ⁠עֵדֻ֑ת אֵ֣ת כָּל־אֲשֶׁ֧ר אֲצַוֶּ֛ה אוֹתְ⁠ךָ֖ אֶל־בְּנֵ֥י יִשְׂרָאֵֽל׃פ","wĕ⁠nwòʻadĕţi֣̇y lĕ⁠ká֮ şá̌m֒ wĕ⁠dibȧrĕţi̇֨y ʼiţĕ̇⁠ká֜ mé⁠ʻa֣l ha⁠kȧpò̇֗reţ mi⁠bé̇yn֙ şĕ̌né֣y ha⁠kĕ̇rubi֔ym ʼàşě֖r ʻal-ʼàrò֣n há⁠ʻédu֑ţ ʼé֣ţ ká̇l-ʼàşě֧r ʼàẕawė֛h ʼwòţĕ⁠ká֖ ʼel-bĕ̇né֥y yişĕ̂ráʼéֽl׃p"],[25,23,"וְ⁠עָשִׂ֥יתָ שֻׁלְחָ֖ן עֲצֵ֣י שִׁטִּ֑ים אַמָּתַ֤יִם אָרְכּ⁠וֹ֙ וְ⁠אַמָּ֣ה רָחְבּ֔⁠וֹ וְ⁠אַמָּ֥ה וָ⁠חֵ֖צִי קֹמָתֽ⁠וֹ׃","wĕ⁠ʻáşî֥yţá şǔlĕẖá֖n ʻàẕé֣y şǐti֑̇ym ʼamá̇ţa֤yim ʼárĕk̇⁠wò֙ wĕ⁠ʼamá֣̇h ráẖĕḃ֔⁠wò wĕ⁠ʼamá֥̇h wá⁠ẖé֖ẕiy qòmáţֽ⁠wò׃"],[25,24,"וְ⁠צִפִּיתָ֥ אֹת֖⁠וֹ זָהָ֣ב טָה֑וֹר וְ⁠עָשִׂ֥יתָ לּ֛⁠וֹ זֵ֥ר זָהָ֖ב סָבִֽיב׃","wĕ⁠ẕipi̇yţá֥ ʼòţ֖⁠wò záhá֣b táh֑wòr wĕ⁠ʻáşî֥yţá l֛̇⁠wò zé֥r záhá֖b sábiֽyb׃"],[25,25,"וְ⁠עָשִׂ֨יתָ לּ֥⁠וֹ מִסְגֶּ֛רֶת טֹ֖פַח סָבִ֑יב וְ⁠עָשִׂ֧יתָ זֵר־זָהָ֛ב לְ⁠מִסְגַּרְתּ֖⁠וֹ סָבִֽיב׃","wĕ⁠ʻáşî֨yţá l֥̇⁠wò misĕgė֛reţ tò֖paẖ sábi֑yb wĕ⁠ʻáşî֧yţá zér-záhá֛b lĕ⁠misĕgȧrĕţ֖̇⁠wò sábiֽyb׃"],[25,26,"וְ⁠עָשִׂ֣יתָ לּ֔⁠וֹ אַרְבַּ֖ע טַבְּעֹ֣ת זָהָ֑ב וְ⁠נָתַתָּ֙ אֶת־הַ⁠טַּבָּעֹ֔ת עַ֚ל אַרְבַּ֣ע הַ⁠פֵּאֹ֔ת אֲשֶׁ֖ר לְ⁠אַרְבַּ֥ע רַגְלָֽי⁠ו׃","wĕ⁠ʻáşî֣yţá l̇֔⁠wò ʼarĕbȧ֖ʻ tabĕ̇ʻò֣ţ záhá֑b wĕ⁠náţaţá̇֙ ʼeţ-ha⁠tȧbá̇ʻò֔ţ ʻa֚l ʼarĕbȧ֣ʻ ha⁠pé̇ʼò֔ţ ʼàşě֖r lĕ⁠ʼarĕbȧ֥ʻ ragĕláֽy⁠w׃"],[25,27,"לְ⁠עֻמַּת֙ הַ⁠מִּסְגֶּ֔רֶת תִּהְיֶ֖יןָ הַ⁠טַּבָּעֹ֑ת לְ⁠בָתִּ֣ים לְ⁠בַדִּ֔ים לָ⁠שֵׂ֖את אֶת־הַ⁠שֻּׁלְחָֽן׃","lĕ⁠ʻumȧţ֙ ha⁠mi̇sĕgė֔reţ ţi̇hĕye֖yná ha⁠tȧbá̇ʻò֑ţ lĕ⁠báţi֣̇ym lĕ⁠badi̇֔ym lá⁠şé֖̂ʼţ ʼeţ-ha⁠şu̇̌lĕẖáֽn׃"],[25,28,"וְ⁠עָשִׂ֤יתָ אֶת־הַ⁠בַּדִּים֙ עֲצֵ֣י שִׁטִּ֔ים וְ⁠צִפִּיתָ֥ אֹתָ֖⁠ם זָהָ֑ב וְ⁠נִשָּׂא־בָ֖⁠ם אֶת־הַ⁠שֻּׁלְחָֽן׃","wĕ⁠ʻáşî֤yţá ʼeţ-ha⁠bȧdi̇ym֙ ʻàẕé֣y şǐti̇֔ym wĕ⁠ẕipi̇yţá֥ ʼòţá֖⁠m záhá֑b wĕ⁠nişá̇̂ʼ-bá֖⁠m ʼeţ-ha⁠şu̇̌lĕẖáֽn׃"],[25,29,"וְ⁠עָשִׂ֨יתָ קְּעָרֹתָ֜י⁠ו וְ⁠כַפֹּתָ֗י⁠ו וּ⁠קְשׂוֹתָי⁠ו֙ וּ⁠מְנַקִּיֹּתָ֔י⁠ו אֲשֶׁ֥ר יֻסַּ֖ךְ בָּ⁠הֵ֑ן זָהָ֥ב טָה֖וֹר תַּעֲשֶׂ֥ה אֹתָֽ⁠ם׃","wĕ⁠ʻáşî֨yţá qĕ̇ʻáròţá֜y⁠w wĕ⁠kapò̇ţá֗y⁠w ẇ⁠qĕş̂wòţáy⁠w֙ ẇ⁠mĕnaqi̇yò̇ţá֔y⁠w ʼàşě֥r yusȧ֖kĕ bá̇⁠hé֑n záhá֥b táh֖wòr ţȧʻàşê֥h ʼòţáֽ⁠m׃"],[25,30,"וְ⁠נָתַתָּ֧ עַֽל־הַ⁠שֻּׁלְחָ֛ן לֶ֥חֶם פָּנִ֖ים לְ⁠פָנַ֥⁠י תָּמִֽיד׃פ","wĕ⁠náţaţá֧̇ ʻaֽl-ha⁠şu̇̌lĕẖá֛n le֥ẖem pá̇ni֖ym lĕ⁠pána֥⁠y ţá̇miֽyd׃p"],[25,31,"וְ⁠עָשִׂ֥יתָ מְנֹרַ֖ת זָהָ֣ב טָה֑וֹר מִקְשָׁ֞ה תֵּעָשֶׂ֤ה הַ⁠מְּנוֹרָה֙ יְרֵכָ֣⁠הּ וְ⁠קָנָ֔⁠הּ גְּבִיעֶ֛י⁠הָ כַּפְתֹּרֶ֥י⁠הָ וּ⁠פְרָחֶ֖י⁠הָ מִמֶּ֥⁠נָּה יִהְיֽוּ׃","wĕ⁠ʻáşî֥yţá mĕnòra֖ţ záhá֣b táh֑wòr miqĕşá̌֞h ţé̇ʻáşê֤h ha⁠mĕ̇nwòráh֙ yĕréká֣⁠ḣ wĕ⁠qáná֔⁠ḣ gĕ̇biyʻe֛y⁠há kȧpĕţò̇re֥y⁠há ẇ⁠pĕráẖe֖y⁠há mimė֥⁠ná̇h yihĕyֽẇ׃"],[25,32,"וְ⁠שִׁשָּׁ֣ה קָנִ֔ים יֹצְאִ֖ים מִ⁠צִּדֶּ֑י⁠הָ שְׁלֹשָׁ֣ה ׀ קְנֵ֣י מְנֹרָ֗ה מִ⁠צִּדָּ⁠הּ֙ הָ⁠אֶחָ֔ד וּ⁠שְׁלֹשָׁה֙ קְנֵ֣י מְנֹרָ֔ה מִ⁠צִּדָּ֖⁠הּ הַ⁠שֵּׁנִֽי׃","wĕ⁠şǐşá֣̇̌h qáni֔ym yòẕĕʼi֖ym mi⁠ẕi̇dė֑y⁠há şĕ̌lòşá֣̌h ׀ qĕné֣y mĕnòrá֗h mi⁠ẕi̇dá̇⁠ḣ֙ há⁠ʼeẖá֔d ẇ⁠şĕ̌lòşá̌h֙ qĕné֣y mĕnòrá֔h mi⁠ẕi̇dá֖̇⁠ḣ ha⁠şé̇̌niֽy׃"],[25,33,"שְׁלֹשָׁ֣ה גְ֠בִעִים מְֽשֻׁקָּדִ֞ים בַּ⁠קָּנֶ֣ה הָ⁠אֶחָד֮ כַּפְתֹּ֣ר וָ⁠פֶרַח֒ וּ⁠שְׁלֹשָׁ֣ה גְבִעִ֗ים מְשֻׁקָּדִ֛ים בַּ⁠קָּנֶ֥ה הָ⁠אֶחָ֖ד כַּפְתֹּ֣ר וָ⁠פָ֑רַח כֵּ֚ן לְ⁠שֵׁ֣שֶׁת הַ⁠קָּנִ֔ים הַ⁠יֹּצְאִ֖ים מִן־הַ⁠מְּנֹרָֽה׃","şĕ̌lòşá֣̌h gĕ֠biʻiym mĕֽşǔqá̇di֞ym bȧ⁠qá̇ne֣h há⁠ʼeẖád֮ kȧpĕţò֣̇r wá⁠peraẖ֒ ẇ⁠şĕ̌lòşá֣̌h gĕbiʻi֗ym mĕşǔqá̇di֛ym bȧ⁠qá̇ne֥h há⁠ʼeẖá֖d kȧpĕţò֣̇r wá⁠pá֑raẖ ké֚̇n lĕ⁠şé֣̌şěţ ha⁠qá̇ni֔ym ha⁠yò̇ẕĕʼi֖ym min-ha⁠mĕ̇nòráֽh׃"],[25,34,"וּ⁠בַ⁠מְּנֹרָ֖ה אַרְבָּעָ֣ה גְבִעִ֑ים מְשֻׁקָּדִ֔ים כַּפְתֹּרֶ֖י⁠הָ וּ⁠פְרָחֶֽי⁠הָ׃","ẇ⁠ba⁠mĕ̇nòrá֖h ʼarĕbá̇ʻá֣h gĕbiʻi֑ym mĕşǔqá̇di֔ym kȧpĕţò̇re֖y⁠há ẇ⁠pĕráẖeֽy⁠há׃"],[25,35,"וְ⁠כַפְתֹּ֡ר תַּחַת֩ שְׁנֵ֨י הַ⁠קָּנִ֜ים מִמֶּ֗⁠נָּה וְ⁠כַפְתֹּר֙ תַּ֣חַת שְׁנֵ֤י הַ⁠קָּנִים֙ מִמֶּ֔⁠נָּה וְ⁠כַפְתֹּ֕ר תַּחַת־שְׁנֵ֥י הַ⁠קָּנִ֖ים מִמֶּ֑⁠נָּה לְ⁠שֵׁ֨שֶׁת֙ הַ⁠קָּנִ֔ים הַ⁠יֹּצְאִ֖ים מִן־הַ⁠מְּנֹרָֽה׃","wĕ⁠kapĕţò̇֡r ţȧẖaţ֩ şĕ̌né֨y ha⁠qá̇ni֜ym mimė֗⁠ná̇h wĕ⁠kapĕţò̇r֙ ţȧ֣ẖaţ şĕ̌né֤y ha⁠qá̇niym֙ mimė֔⁠ná̇h wĕ⁠kapĕţò̇֕r ţȧẖaţ-şĕ̌né֥y ha⁠qá̇ni֖ym mimė֑⁠ná̇h lĕ⁠şé̌֨şěţ֙ ha⁠qá̇ni֔ym ha⁠yò̇ẕĕʼi֖ym min-ha⁠mĕ̇nòráֽh׃"],[25,36,"כַּפְתֹּרֵי⁠הֶ֥ם וּ⁠קְנֹתָ֖⁠ם מִמֶּ֣⁠נָּה יִהְי֑וּ כֻּלָּ֛⁠הּ מִקְשָׁ֥ה אַחַ֖ת זָהָ֥ב טָהֽוֹר׃","kȧpĕţò̇réy⁠he֥m ẇ⁠qĕnòţá֖⁠m mimė֣⁠ná̇h yihĕy֑ẇ ku̇lá֛̇⁠ḣ miqĕşá֥̌h ʼaẖa֖ţ záhá֥b táhֽwòr׃"],[25,37,"וְ⁠עָשִׂ֥יתָ אֶת־נֵרֹתֶ֖י⁠הָ שִׁבְעָ֑ה וְ⁠הֶֽעֱלָה֙ אֶת־נֵ֣רֹתֶ֔י⁠הָ וְ⁠הֵאִ֖יר עַל־עֵ֥בֶר פָּנֶֽי⁠הָ׃","wĕ⁠ʻáşî֥yţá ʼeţ-néròţe֖y⁠há şǐbĕʻá֑h wĕ⁠heֽʻèláh֙ ʼeţ-né֣ròţe֔y⁠há wĕ⁠héʼi֖yr ʻal-ʻé֥ber pá̇neֽy⁠há׃"],[25,38,"וּ⁠מַלְקָחֶ֥י⁠הָ וּ⁠מַחְתֹּתֶ֖י⁠הָ זָהָ֥ב טָהֽוֹר׃","ẇ⁠malĕqáẖe֥y⁠há ẇ⁠maẖĕţò̇ţe֖y⁠há záhá֥b táhֽwòr׃"],[25,39,"כִּכָּ֛ר זָהָ֥ב טָה֖וֹר יַעֲשֶׂ֣ה אֹתָ֑⁠הּ אֵ֥ת כָּל־הַ⁠כֵּלִ֖ים הָ⁠אֵֽלֶּה׃","ki̇ká֛̇r záhá֥b táh֖wòr yaʻàşê֣h ʼòţá֑⁠ḣ ʼé֥ţ ká̇l-ha⁠ké̇li֖ym há⁠ʼéֽlėh׃"],[25,40,"וּ⁠רְאֵ֖ה וַ⁠עֲשֵׂ֑ה בְּ⁠תַ֨בְנִיתָ֔⁠ם אֲשֶׁר־אַתָּ֥ה מָרְאֶ֖ה בָּ⁠הָֽר׃ס","ẇ⁠rĕʼé֖h wa⁠ʻàşé֑̂h bĕ̇⁠ţa֨bĕniyţá֔⁠m ʼàşěr-ʼaţá֥̇h márĕʼe֖h bá̇⁠háֽr׃s"],[26,1,"וְ⁠אֶת־הַ⁠מִּשְׁכָּ֥ן תַּעֲשֶׂ֖ה עֶ֣שֶׂר יְרִיעֹ֑ת שֵׁ֣שׁ מָשְׁזָ֗ר וּ⁠תְכֵ֤לֶת וְ⁠אַרְגָּמָן֙ וְ⁠תֹלַ֣עַת שָׁנִ֔י כְּרֻבִ֛ים מַעֲשֵׂ֥ה חֹשֵׁ֖ב תַּעֲשֶׂ֥ה אֹתָֽ⁠ם׃","wĕ⁠ʼeţ-ha⁠mi̇şĕ̌ká֥̇n ţȧʻàşê֖h ʻe֣şêr yĕriyʻò֑ţ şé֣̌ş̌ máşĕ̌zá֗r ẇ⁠ţĕké֤leţ wĕ⁠ʼarĕgá̇mán֙ wĕ⁠ţòla֣ʻaţ şá̌ni֔y kĕ̇rubi֛ym maʻàşé֥̂h ẖòşé֖̌b ţȧʻàşê֥h ʼòţáֽ⁠m׃"],[26,2,"אֹ֣רֶךְ ׀ הַ⁠יְרִיעָ֣ה הָֽ⁠אַחַ֗ת שְׁמֹנֶ֤ה וְ⁠עֶשְׂרִים֙ בָּֽ⁠אַמָּ֔ה וְ⁠רֹ֨חַב֙ אַרְבַּ֣ע בָּ⁠אַמָּ֔ה הַ⁠יְרִיעָ֖ה הָ⁠אֶחָ֑ת מִדָּ֥ה אַחַ֖ת לְ⁠כָל־הַ⁠יְרִיעֹֽת׃","ʼò֣rekĕ ׀ ha⁠yĕriyʻá֣h háֽ⁠ʼaẖa֗ţ şĕ̌mòne֤h wĕ⁠ʻeşĕ̂riym֙ báֽ̇⁠ʼamá̇֔h wĕ⁠rò֨ẖab֙ ʼarĕbȧ֣ʻ bá̇⁠ʼamá̇֔h ha⁠yĕriyʻá֖h há⁠ʼeẖá֑ţ midá֥̇h ʼaẖa֖ţ lĕ⁠kál-ha⁠yĕriyʻòֽţ׃"],[26,3,"חֲמֵ֣שׁ הַ⁠יְרִיעֹ֗ת תִּֽהְיֶ֨יןָ֙ חֹֽבְרֹ֔ת אִשָּׁ֖ה אֶל־אֲחֹתָ֑⁠הּ וְ⁠חָמֵ֤שׁ יְרִיעֹת֙ חֹֽבְרֹ֔ת אִשָּׁ֖ה אֶל־אֲחֹתָֽ⁠הּ׃","ẖàmé֣ş̌ ha⁠yĕriyʻò֗ţ ţiֽ̇hĕye֨yná֙ ẖòֽbĕrò֔ţ ʼişá֖̇̌h ʼel-ʼàẖòţá֑⁠ḣ wĕ⁠ẖámé֤ş̌ yĕriyʻòţ֙ ẖòֽbĕrò֔ţ ʼişá֖̇̌h ʼel-ʼàẖòţáֽ⁠ḣ׃"],[26,4,"וְ⁠עָשִׂ֜יתָ לֻֽלְאֹ֣ת תְּכֵ֗לֶת עַ֣ל שְׂפַ֤ת הַ⁠יְרִיעָה֙ הָ⁠אֶחָ֔ת מִ⁠קָּצָ֖ה בַּ⁠חֹבָ֑רֶת וְ⁠כֵ֤ן תַּעֲשֶׂה֙ בִּ⁠שְׂפַ֣ת הַ⁠יְרִיעָ֔ה הַ⁠קִּ֣יצוֹנָ֔ה בַּ⁠מַּחְבֶּ֖רֶת הַ⁠שֵּׁנִֽית׃","wĕ⁠ʻáşî֜yţá luֽlĕʼò֣ţ ţĕ̇ké֗leţ ʻa֣l şĕ̂pa֤ţ ha⁠yĕriyʻáh֙ há⁠ʼeẖá֔ţ mi⁠qá̇ẕá֖h bȧ⁠ẖòbá֑reţ wĕ⁠ké֤n ţȧʻàşêh֙ bi̇⁠şĕ̂pa֣ţ ha⁠yĕriyʻá֔h ha⁠qi֣̇yẕwòná֔h bȧ⁠mȧẖĕbė֖reţ ha⁠şé̇̌niֽyţ׃"],[26,5,"חֲמִשִּׁ֣ים לֻֽלָאֹ֗ת תַּעֲשֶׂה֮ בַּ⁠יְרִיעָ֣ה הָ⁠אֶחָת֒ וַ⁠חֲמִשִּׁ֣ים לֻֽלָאֹ֗ת תַּעֲשֶׂה֙ בִּ⁠קְצֵ֣ה הַ⁠יְרִיעָ֔ה אֲשֶׁ֖ר בַּ⁠מַּחְבֶּ֣רֶת הַ⁠שֵּׁנִ֑ית מַקְבִּילֹת֙ הַ⁠לֻּ֣לָאֹ֔ת אִשָּׁ֖ה אֶל־אֲחֹתָֽ⁠הּ׃","ẖàmişi֣̇̌ym luֽláʼò֗ţ ţȧʻàşêh֮ bȧ⁠yĕriyʻá֣h há⁠ʼeẖáţ֒ wa⁠ẖàmişi֣̇̌ym luֽláʼò֗ţ ţȧʻàşêh֙ bi̇⁠qĕẕé֣h ha⁠yĕriyʻá֔h ʼàşě֖r bȧ⁠mȧẖĕbė֣reţ ha⁠şé̇̌ni֑yţ maqĕbi̇ylòţ֙ ha⁠lu֣̇láʼò֔ţ ʼişá֖̇̌h ʼel-ʼàẖòţáֽ⁠ḣ׃"],[26,6,"וְ⁠עָשִׂ֕יתָ חֲמִשִּׁ֖ים קַרְסֵ֣י זָהָ֑ב וְ⁠חִבַּרְתָּ֨ אֶת־הַ⁠יְרִיעֹ֜ת אִשָּׁ֤ה אֶל־אֲחֹתָ⁠הּ֙ בַּ⁠קְּרָסִ֔ים וְ⁠הָיָ֥ה הַ⁠מִּשְׁכָּ֖ן אֶחָֽד׃פ","wĕ⁠ʻáşî֕yţá ẖàmişi֖̇̌ym qarĕsé֣y záhá֑b wĕ⁠ẖibȧrĕţá̇֨ ʼeţ-ha⁠yĕriyʻò֜ţ ʼişá֤̇̌h ʼel-ʼàẖòţá⁠ḣ֙ bȧ⁠qĕ̇rási֔ym wĕ⁠háyá֥h ha⁠mi̇şĕ̌ká֖̇n ʼeẖáֽd׃p"],[26,7,"וְ⁠עָשִׂ֨יתָ֙ יְרִיעֹ֣ת עִזִּ֔ים לְ⁠אֹ֖הֶל עַל־הַ⁠מִּשְׁכָּ֑ן עַשְׁתֵּי־עֶשְׂרֵ֥ה יְרִיעֹ֖ת תַּעֲשֶׂ֥ה אֹתָֽ⁠ם׃","wĕ⁠ʻáşî֨yţá֙ yĕriyʻò֣ţ ʻizi̇֔ym lĕ⁠ʼò֖hel ʻal-ha⁠mi̇şĕ̌ká֑̇n ʻaşĕ̌ţé̇y-ʻeşĕ̂ré֥h yĕriyʻò֖ţ ţȧʻàşê֥h ʼòţáֽ⁠m׃"],[26,8,"אֹ֣רֶךְ ׀ הַ⁠יְרִיעָ֣ה הָֽ⁠אַחַ֗ת שְׁלֹשִׁים֙ בָּֽ⁠אַמָּ֔ה וְ⁠רֹ֨חַב֙ אַרְבַּ֣ע בָּ⁠אַמָּ֔ה הַ⁠יְרִיעָ֖ה הָ⁠אֶחָ֑ת מִדָּ֣ה אַחַ֔ת לְ⁠עַשְׁתֵּ֥י עֶשְׂרֵ֖ה יְרִיעֹֽת׃","ʼò֣rekĕ ׀ ha⁠yĕriyʻá֣h háֽ⁠ʼaẖa֗ţ şĕ̌lòşǐym֙ báֽ̇⁠ʼamá̇֔h wĕ⁠rò֨ẖab֙ ʼarĕbȧ֣ʻ bá̇⁠ʼamá̇֔h ha⁠yĕriyʻá֖h há⁠ʼeẖá֑ţ midá֣̇h ʼaẖa֔ţ lĕ⁠ʻaşĕ̌ţé֥̇y ʻeşĕ̂ré֖h yĕriyʻòֽţ׃"],[26,9,"וְ⁠חִבַּרְתָּ֞ אֶת־חֲמֵ֤שׁ הַ⁠יְרִיעֹת֙ לְ⁠בָ֔ד וְ⁠אֶת־שֵׁ֥שׁ הַ⁠יְרִיעֹ֖ת לְ⁠בָ֑ד וְ⁠כָפַלְתָּ֙ אֶת־הַ⁠יְרִיעָ֣ה הַ⁠שִּׁשִּׁ֔ית אֶל־מ֖וּל פְּנֵ֥י הָ⁠אֹֽהֶל׃","wĕ⁠ẖibȧrĕţá̇֞ ʼeţ-ẖàmé֤ş̌ ha⁠yĕriyʻòţ֙ lĕ⁠bá֔d wĕ⁠ʼeţ-şé֥̌ş̌ ha⁠yĕriyʻò֖ţ lĕ⁠bá֑d wĕ⁠kápalĕţá̇֙ ʼeţ-ha⁠yĕriyʻá֣h ha⁠şi̇̌şi̇̌֔yţ ʼel-m֖ẇl pĕ̇né֥y há⁠ʼòֽhel׃"],[26,10,"וְ⁠עָשִׂ֜יתָ חֲמִשִּׁ֣ים לֻֽלָאֹ֗ת עַ֣ל שְׂפַ֤ת הַ⁠יְרִיעָה֙ הָֽ⁠אֶחָ֔ת הַ⁠קִּיצֹנָ֖ה בַּ⁠חֹבָ֑רֶת וַ⁠חֲמִשִּׁ֣ים לֻֽלָאֹ֗ת עַ֚ל שְׂפַ֣ת הַ⁠יְרִיעָ֔ה הַ⁠חֹבֶ֖רֶת הַ⁠שֵּׁנִֽית׃","wĕ⁠ʻáşî֜yţá ẖàmişi֣̇̌ym luֽláʼò֗ţ ʻa֣l şĕ̂pa֤ţ ha⁠yĕriyʻáh֙ háֽ⁠ʼeẖá֔ţ ha⁠qi̇yẕòná֖h bȧ⁠ẖòbá֑reţ wa⁠ẖàmişi֣̇̌ym luֽláʼò֗ţ ʻa֚l şĕ̂pa֣ţ ha⁠yĕriyʻá֔h ha⁠ẖòbe֖reţ ha⁠şé̇̌niֽyţ׃"],[26,11,"וְ⁠עָשִׂ֛יתָ קַרְסֵ֥י נְחֹ֖שֶׁת חֲמִשִּׁ֑ים וְ⁠הֵבֵאתָ֤ אֶת־הַ⁠קְּרָסִים֙ בַּ⁠לֻּ֣לָאֹ֔ת וְ⁠חִבַּרְתָּ֥ אֶת־הָ⁠אֹ֖הֶל וְ⁠הָיָ֥ה אֶחָֽד׃","wĕ⁠ʻáşî֛yţá qarĕsé֥y nĕẖò֖şěţ ẖàmişi֑̇̌ym wĕ⁠hébéʼţá֤ ʼeţ-ha⁠qĕ̇rásiym֙ bȧ⁠lu֣̇láʼò֔ţ wĕ⁠ẖibȧrĕţá֥̇ ʼeţ-há⁠ʼò֖hel wĕ⁠háyá֥h ʼeẖáֽd׃"],[26,12,"וְ⁠סֶ֨רַח֙ הָ⁠עֹדֵ֔ף בִּ⁠ירִיעֹ֖ת הָ⁠אֹ֑הֶל חֲצִ֤י הַ⁠יְרִיעָה֙ הָ⁠עֹדֶ֔פֶת תִּסְרַ֕ח עַ֖ל אֲחֹרֵ֥י הַ⁠מִּשְׁכָּֽן׃","wĕ⁠se֨raẖ֙ há⁠ʻòdé֔p bi̇⁠yriyʻò֖ţ há⁠ʼò֑hel ẖàẕi֤y ha⁠yĕriyʻáh֙ há⁠ʻòde֔peţ ţi̇sĕra֕ẖ ʻa֖l ʼàẖòré֥y ha⁠mi̇şĕ̌káֽ̇n׃"],[26,13,"וְ⁠הָ⁠אַמָּ֨ה מִ⁠זֶּ֜ה וְ⁠הָ⁠אַמָּ֤ה מִ⁠זֶּה֙ בָּ⁠עֹדֵ֔ף בְּ⁠אֹ֖רֶךְ יְרִיעֹ֣ת הָ⁠אֹ֑הֶל יִהְיֶ֨ה סָר֜וּחַ עַל־צִדֵּ֧י הַ⁠מִּשְׁכָּ֛ן מִ⁠זֶּ֥ה וּ⁠מִ⁠זֶּ֖ה לְ⁠כַסֹּתֽ⁠וֹ׃","wĕ⁠há⁠ʼamá̇֨h mi⁠zė֜h wĕ⁠há⁠ʼamá֤̇h mi⁠zėh֙ bá̇⁠ʻòdé֔p bĕ̇⁠ʼò֖rekĕ yĕriyʻò֣ţ há⁠ʼò֑hel yihĕye֨h sár֜ẇẖa ʻal-ẕidé֧̇y ha⁠mi̇şĕ̌ká֛̇n mi⁠zė֥h ẇ⁠mi⁠zė֖h lĕ⁠kasò̇ţֽ⁠wò׃"],[26,14,"וְ⁠עָשִׂ֤יתָ מִכְסֶה֙ לָ⁠אֹ֔הֶל עֹרֹ֥ת אֵילִ֖ם מְאָדָּמִ֑ים וּ⁠מִכְסֵ֛ה עֹרֹ֥ת תְּחָשִׁ֖ים מִ⁠לְ⁠מָֽעְלָ⁠ה׃פ","wĕ⁠ʻáşî֤yţá mikĕseh֙ lá⁠ʼò֔hel ʻòrò֥ţ ʼéyli֖m mĕʼádá̇mi֑ym ẇ⁠mikĕsé֛h ʻòrò֥ţ ţĕ̇ẖáşǐ֖ym mi⁠lĕ⁠máֽʻĕlá⁠h׃p"],[26,15,"וְ⁠עָשִׂ֥יתָ אֶת־הַ⁠קְּרָשִׁ֖ים לַ⁠מִּשְׁכָּ֑ן עֲצֵ֥י שִׁטִּ֖ים עֹמְדִֽים׃","wĕ⁠ʻáşî֥yţá ʼeţ-ha⁠qĕ̇ráşǐ֖ym la⁠mi̇şĕ̌ká֑̇n ʻàẕé֥y şǐti֖̇ym ʻòmĕdiֽym׃"],[26,16,"עֶ֥שֶׂר אַמּ֖וֹת אֹ֣רֶךְ הַ⁠קָּ֑רֶשׁ וְ⁠אַמָּה֙ וַ⁠חֲצִ֣י הָֽ⁠אַמָּ֔ה רֹ֖חַב הַ⁠קֶּ֥רֶשׁ הָ⁠אֶחָֽד׃","ʻe֥şêr ʼaṁ֖wòţ ʼò֣rekĕ ha⁠qá֑̇reş̌ wĕ⁠ʼamá̇h֙ wa⁠ẖàẕi֣y háֽ⁠ʼamá̇֔h rò֖ẖab ha⁠qė֥reş̌ há⁠ʼeẖáֽd׃"],[26,17,"שְׁתֵּ֣י יָד֗וֹת לַ⁠קֶּ֨רֶשׁ֙ הָ⁠אֶחָ֔ד מְשֻׁלָּבֹ֔ת אִשָּׁ֖ה אֶל־אֲחֹתָ֑⁠הּ כֵּ֣ן תַּעֲשֶׂ֔ה לְ⁠כֹ֖ל קַרְשֵׁ֥י הַ⁠מִּשְׁכָּֽן׃","şĕ̌ţé֣̇y yád֗wòţ la⁠qė֨reş̌֙ há⁠ʼeẖá֔d mĕşǔlá̇bò֔ţ ʼişá֖̇̌h ʼel-ʼàẖòţá֑⁠ḣ ké֣̇n ţȧʻàşê֔h lĕ⁠kò֖l qarĕşé֥̌y ha⁠mi̇şĕ̌káֽ̇n׃"],[26,18,"וְ⁠עָשִׂ֥יתָ אֶת־הַ⁠קְּרָשִׁ֖ים לַ⁠מִּשְׁכָּ֑ן עֶשְׂרִ֣ים קֶ֔רֶשׁ לִ⁠פְאַ֖ת נֶ֥גְבָּ⁠ה תֵימָֽנָ⁠ה׃","wĕ⁠ʻáşî֥yţá ʼeţ-ha⁠qĕ̇ráşǐ֖ym la⁠mi̇şĕ̌ká֑̇n ʻeşĕ̂ri֣ym qe֔reş̌ li⁠pĕʼa֖ţ ne֥gĕbá̇⁠h ţéymáֽná⁠h׃"],[26,19,"וְ⁠אַרְבָּעִים֙ אַדְנֵי־כֶ֔סֶף תַּעֲשֶׂ֕ה תַּ֖חַת עֶשְׂרִ֣ים הַ⁠קָּ֑רֶשׁ שְׁנֵ֨י אֲדָנִ֜ים תַּֽחַת־הַ⁠קֶּ֤רֶשׁ הָ⁠אֶחָד֙ לִ⁠שְׁתֵּ֣י יְדֹתָ֔י⁠ו וּ⁠שְׁנֵ֧י אֲדָנִ֛ים תַּֽחַת־הַ⁠קֶּ֥רֶשׁ הָ⁠אֶחָ֖ד לִ⁠שְׁתֵּ֥י יְדֹתָֽי⁠ו׃","wĕ⁠ʼarĕbá̇ʻiym֙ ʼadĕnéy-ke֔sep ţȧʻàşê֕h ţȧ֖ẖaţ ʻeşĕ̂ri֣ym ha⁠qá֑̇reş̌ şĕ̌né֨y ʼàdáni֜ym ţȧֽẖaţ-ha⁠qė֤reş̌ há⁠ʼeẖád֙ li⁠şĕ̌ţé֣̇y yĕdòţá֔y⁠w ẇ⁠şĕ̌né֧y ʼàdáni֛ym ţȧֽẖaţ-ha⁠qė֥reş̌ há⁠ʼeẖá֖d li⁠şĕ̌ţé֥̇y yĕdòţáֽy⁠w׃"],[26,20,"וּ⁠לְ⁠צֶ֧לַע הַ⁠מִּשְׁכָּ֛ן הַ⁠שֵּׁנִ֖ית לִ⁠פְאַ֣ת צָפ֑וֹן עֶשְׂרִ֖ים קָֽרֶשׁ׃","ẇ⁠lĕ⁠ẕe֧laʻ ha⁠mi̇şĕ̌ká֛̇n ha⁠şé̇̌ni֖yţ li⁠pĕʼa֣ţ ẕáp֑wòn ʻeşĕ̂ri֖ym qáֽreş̌׃"],[26,21,"וְ⁠אַרְבָּעִ֥ים אַדְנֵי⁠הֶ֖ם כָּ֑סֶף שְׁנֵ֣י אֲדָנִ֗ים תַּ֚חַת הַ⁠קֶּ֣רֶשׁ הָֽ⁠אֶחָ֔ד וּ⁠שְׁנֵ֣י אֲדָנִ֔ים תַּ֖חַת הַ⁠קֶּ֥רֶשׁ הָ⁠אֶחָֽד׃","wĕ⁠ʼarĕbá̇ʻi֥ym ʼadĕnéy⁠he֖m ká֑̇sep şĕ̌né֣y ʼàdáni֗ym ţȧ֚ẖaţ ha⁠qė֣reş̌ háֽ⁠ʼeẖá֔d ẇ⁠şĕ̌né֣y ʼàdáni֔ym ţȧ֖ẖaţ ha⁠qė֥reş̌ há⁠ʼeẖáֽd׃"],[26,22,"וּֽ⁠לְ⁠יַרְכְּתֵ֥י הַ⁠מִּשְׁכָּ֖ן יָ֑מָּ⁠ה תַּעֲשֶׂ֖ה שִׁשָּׁ֥ה קְרָשִֽׁים׃","ẇֽ⁠lĕ⁠yarĕkĕ̇ţé֥y ha⁠mi̇şĕ̌ká֖̇n yá֑má̇⁠h ţȧʻàşê֖h şǐşá֥̇̌h qĕráşǐֽym׃"],[26,23,"וּ⁠שְׁנֵ֤י קְרָשִׁים֙ תַּעֲשֶׂ֔ה לִ⁠מְקֻצְעֹ֖ת הַ⁠מִּשְׁכָּ֑ן בַּ⁠יַּרְכָתָֽיִם׃","ẇ⁠şĕ̌né֤y qĕráşǐym֙ ţȧʻàşê֔h li⁠mĕquẕĕʻò֖ţ ha⁠mi̇şĕ̌ká֑̇n bȧ⁠yȧrĕkáţáֽyim׃"],[26,24,"וְ⁠יִֽהְי֣וּ תֹֽאֲמִים֮ מִ⁠לְּ⁠מַטָּה֒ וְ⁠יַחְדָּ֗ו יִהְי֤וּ תַמִּים֙ עַל־רֹאשׁ֔⁠וֹ אֶל־הַ⁠טַּבַּ֖עַת הָ⁠אֶחָ֑ת כֵּ֚ן יִהְיֶ֣ה לִ⁠שְׁנֵי⁠הֶ֔ם לִ⁠שְׁנֵ֥י הַ⁠מִּקְצֹעֹ֖ת יִהְיֽוּ׃","wĕ⁠yiֽhĕy֣ẇ ţòֽʼàmiym֮ mi⁠lĕ̇⁠matá̇h֒ wĕ⁠yaẖĕdá̇֗w yihĕy֤ẇ ţami̇ym֙ ʻal-ròʼş̌֔⁠wò ʼel-ha⁠tȧbȧ֖ʻaţ há⁠ʼeẖá֑ţ ké֚̇n yihĕye֣h li⁠şĕ̌néy⁠he֔m li⁠şĕ̌né֥y ha⁠mi̇qĕẕòʻò֖ţ yihĕyֽẇ׃"],[26,25,"וְ⁠הָיוּ֙ שְׁמֹנָ֣ה קְרָשִׁ֔ים וְ⁠אַדְנֵי⁠הֶ֣ם כֶּ֔סֶף שִׁשָּׁ֥ה עָשָׂ֖ר אֲדָנִ֑ים שְׁנֵ֣י אֲדָנִ֗ים תַּ֚חַת הַ⁠קֶּ֣רֶשׁ הָ⁠אֶחָ֔ד וּ⁠שְׁנֵ֣י אֲדָנִ֔ים תַּ֖חַת הַ⁠קֶּ֥רֶשׁ הָ⁠אֶחָֽד׃","wĕ⁠háyẇ֙ şĕ̌mòná֣h qĕráşǐ֔ym wĕ⁠ʼadĕnéy⁠he֣m kė֔sep şǐşá֥̇̌h ʻáşá֖̂r ʼàdáni֑ym şĕ̌né֣y ʼàdáni֗ym ţȧ֚ẖaţ ha⁠qė֣reş̌ há⁠ʼeẖá֔d ẇ⁠şĕ̌né֣y ʼàdáni֔ym ţȧ֖ẖaţ ha⁠qė֥reş̌ há⁠ʼeẖáֽd׃"],[26,26,"וְ⁠עָשִׂ֥יתָ בְרִיחִ֖ם עֲצֵ֣י שִׁטִּ֑ים חֲמִשָּׁ֕ה לְ⁠קַרְשֵׁ֥י צֶֽלַע־הַ⁠מִּשְׁכָּ֖ן הָ⁠אֶחָֽד׃","wĕ⁠ʻáşî֥yţá bĕriyẖi֖m ʻàẕé֣y şǐti֑̇ym ẖàmişá̇̌֕h lĕ⁠qarĕşé֥̌y ẕeֽlaʻ-ha⁠mi̇şĕ̌ká֖̇n há⁠ʼeẖáֽd׃"],[26,27,"וַ⁠חֲמִשָּׁ֣ה בְרִיחִ֔ם לְ⁠קַרְשֵׁ֥י צֶֽלַע־הַ⁠מִּשְׁכָּ֖ן הַ⁠שֵּׁנִ֑ית וַ⁠חֲמִשָּׁ֣ה בְרִיחִ֗ם לְ⁠קַרְשֵׁי֙ צֶ֣לַע הַ⁠מִּשְׁכָּ֔ן לַ⁠יַּרְכָתַ֖יִם יָֽמָּ⁠ה׃","wa⁠ẖàmişá֣̇̌h bĕriyẖi֔m lĕ⁠qarĕşé֥̌y ẕeֽlaʻ-ha⁠mi̇şĕ̌ká֖̇n ha⁠şé̇̌ni֑yţ wa⁠ẖàmişá֣̇̌h bĕriyẖi֗m lĕ⁠qarĕşé̌y֙ ẕe֣laʻ ha⁠mi̇şĕ̌ká̇֔n la⁠yȧrĕkáţa֖yim yáֽmá̇⁠h׃"],[26,28,"וְ⁠הַ⁠בְּרִ֥יחַ הַ⁠תִּיכֹ֖ן בְּ⁠ת֣וֹךְ הַ⁠קְּרָשִׁ֑ים מַבְרִ֕חַ מִן־הַ⁠קָּצֶ֖ה אֶל־הַ⁠קָּצֶֽה׃","wĕ⁠ha⁠bĕ̇ri֥yẖa ha⁠ţi̇ykò֖n bĕ̇⁠ţ֣wòkĕ ha⁠qĕ̇ráşǐ֑ym mabĕri֕ẖa min-ha⁠qá̇ẕe֖h ʼel-ha⁠qá̇ẕeֽh׃"],[26,29,"וְֽ⁠אֶת־הַ⁠קְּרָשִׁ֞ים תְּצַפֶּ֣ה זָהָ֗ב וְ⁠אֶת־טַבְּעֹֽתֵי⁠הֶם֙ תַּעֲשֶׂ֣ה זָהָ֔ב בָּתִּ֖ים לַ⁠בְּרִיחִ֑ם וְ⁠צִפִּיתָ֥ אֶת־הַ⁠בְּרִיחִ֖ם זָהָֽב׃","wĕֽ⁠ʼeţ-ha⁠qĕ̇ráşǐ֞ym ţĕ̇ẕapė֣h záhá֗b wĕ⁠ʼeţ-tabĕ̇ʻòֽţéy⁠hem֙ ţȧʻàşê֣h záhá֔b bá̇ţi֖̇ym la⁠bĕ̇riyẖi֑m wĕ⁠ẕipi̇yţá֥ ʼeţ-ha⁠bĕ̇riyẖi֖m záháֽb׃"],[26,30,"וַ⁠הֲקֵמֹתָ֖ אֶת־הַ⁠מִּשְׁכָּ֑ן כְּ⁠מִ֨שְׁפָּט֔⁠וֹ אֲשֶׁ֥ר הָרְאֵ֖יתָ בָּ⁠הָֽר׃ס","wa⁠hàqémòţá֖ ʼeţ-ha⁠mi̇şĕ̌ká֑̇n kĕ̇⁠mi֨şĕ̌pá̇t֔⁠wò ʼàşě֥r hárĕʼé֖yţá bá̇⁠háֽr׃s"],[26,31,"וְ⁠עָשִׂ֣יתָ פָרֹ֗כֶת תְּכֵ֧לֶת וְ⁠אַרְגָּמָ֛ן וְ⁠תוֹלַ֥עַת שָׁנִ֖י וְ⁠שֵׁ֣שׁ מָשְׁזָ֑ר מַעֲשֵׂ֥ה חֹשֵׁ֛ב יַעֲשֶׂ֥ה אֹתָ֖⁠הּ כְּרֻבִֽים׃","wĕ⁠ʻáşî֣yţá párò֗keţ ţĕ̇ké֧leţ wĕ⁠ʼarĕgá̇má֛n wĕ⁠ţwòla֥ʻaţ şá̌ni֖y wĕ⁠şé֣̌ş̌ máşĕ̌zá֑r maʻàşé֥̂h ẖòşé֛̌b yaʻàşê֥h ʼòţá֖⁠ḣ kĕ̇rubiֽym׃"],[26,32,"וְ⁠נָתַתָּ֣ה אֹתָ֗⁠הּ עַל־אַרְבָּעָה֙ עַמּוּדֵ֣י שִׁטִּ֔ים מְצֻפִּ֣ים זָהָ֔ב וָוֵי⁠הֶ֖ם זָהָ֑ב עַל־אַרְבָּעָ֖ה אַדְנֵי־כָֽסֶף׃","wĕ⁠náţaţá֣̇h ʼòţá֗⁠ḣ ʻal-ʼarĕbá̇ʻáh֙ ʻaṁẇdé֣y şǐti̇֔ym mĕẕupi֣̇ym záhá֔b wáwéy⁠he֖m záhá֑b ʻal-ʼarĕbá̇ʻá֖h ʼadĕnéy-káֽsep׃"],[26,33,"וְ⁠נָתַתָּ֣ה אֶת־הַ⁠פָּרֹכֶת֮ תַּ֣חַת הַ⁠קְּרָסִים֒ וְ⁠הֵבֵאתָ֥ שָׁ֨מָּ⁠ה֙ מִ⁠בֵּ֣ית לַ⁠פָּרֹ֔כֶת אֵ֖ת אֲר֣וֹן הָ⁠עֵד֑וּת וְ⁠הִבְדִּילָ֤ה הַ⁠פָּרֹ֨כֶת֙ לָ⁠כֶ֔ם בֵּ֣ין הַ⁠קֹּ֔דֶשׁ וּ⁠בֵ֖ין קֹ֥דֶשׁ הַ⁠קֳּדָשִֽׁים׃","wĕ⁠náţaţá֣̇h ʼeţ-ha⁠pá̇ròkeţ֮ ţȧ֣ẖaţ ha⁠qĕ̇rásiym֒ wĕ⁠hébéʼţá֥ şá̌֨má̇⁠h֙ mi⁠bé֣̇yţ la⁠pá̇rò֔keţ ʼé֖ţ ʼàr֣wòn há⁠ʻéd֑ẇţ wĕ⁠hibĕdi̇ylá֤h ha⁠pá̇rò֨keţ֙ lá⁠ke֔m bé֣̇yn ha⁠qò̇֔deş̌ ẇ⁠bé֖yn qò֥deş̌ ha⁠qȯdáşǐֽym׃"],[26,34,"וְ⁠נָתַתָּ֙ אֶת־הַ⁠כַּפֹּ֔רֶת עַ֖ל אֲר֣וֹן הָ⁠עֵדֻ֑ת בְּ⁠קֹ֖דֶשׁ הַ⁠קֳּדָשִֽׁים׃","wĕ⁠náţaţá̇֙ ʼeţ-ha⁠kȧpò̇֔reţ ʻa֖l ʼàr֣wòn há⁠ʻédu֑ţ bĕ̇⁠qò֖deş̌ ha⁠qȯdáşǐֽym׃"],[26,35,"וְ⁠שַׂמְתָּ֤ אֶת־הַ⁠שֻּׁלְחָן֙ מִ⁠ח֣וּץ לַ⁠פָּרֹ֔כֶת וְ⁠אֶת־הַ⁠מְּנֹרָה֙ נֹ֣כַח הַ⁠שֻּׁלְחָ֔ן עַ֛ל צֶ֥לַע הַ⁠מִּשְׁכָּ֖ן תֵּימָ֑נָ⁠ה וְ⁠הַ֨⁠שֻּׁלְחָ֔ן תִּתֵּ֖ן עַל־צֶ֥לַע צָפֽוֹן׃","wĕ⁠şâmĕţá֤̇ ʼeţ-ha⁠şu̇̌lĕẖán֙ mi⁠ẖ֣ẇẕ la⁠pá̇rò֔keţ wĕ⁠ʼeţ-ha⁠mĕ̇nòráh֙ nò֣kaẖ ha⁠şu̇̌lĕẖá֔n ʻa֛l ẕe֥laʻ ha⁠mi̇şĕ̌ká֖̇n ţé̇ymá֑ná⁠h wĕ⁠ha֨⁠şu̇̌lĕẖá֔n ţi̇ţé֖̇n ʻal-ẕe֥laʻ ẕápֽwòn׃"],[26,36,"וְ⁠עָשִׂ֤יתָ מָסָךְ֙ לְ⁠פֶ֣תַח הָ⁠אֹ֔הֶל תְּכֵ֧לֶת וְ⁠אַרְגָּמָ֛ן וְ⁠תוֹלַ֥עַת שָׁנִ֖י וְ⁠שֵׁ֣שׁ מָשְׁזָ֑ר מַעֲשֵׂ֖ה רֹקֵֽם׃","wĕ⁠ʻáşî֤yţá másákĕ֙ lĕ⁠pe֣ţaẖ há⁠ʼò֔hel ţĕ̇ké֧leţ wĕ⁠ʼarĕgá̇má֛n wĕ⁠ţwòla֥ʻaţ şá̌ni֖y wĕ⁠şé֣̌ş̌ máşĕ̌zá֑r maʻàşé֖̂h ròqéֽm׃"],[26,37,"וְ⁠עָשִׂ֣יתָ לַ⁠מָּסָ֗ךְ חֲמִשָּׁה֙ עַמּוּדֵ֣י שִׁטִּ֔ים וְ⁠צִפִּיתָ֤ אֹתָ⁠ם֙ זָהָ֔ב וָוֵי⁠הֶ֖ם זָהָ֑ב וְ⁠יָצַקְתָּ֣ לָ⁠הֶ֔ם חֲמִשָּׁ֖ה אַדְנֵ֥י נְחֹֽשֶׁת׃ס","wĕ⁠ʻáşî֣yţá la⁠má̇sá֗kĕ ẖàmişá̇̌h֙ ʻaṁẇdé֣y şǐti̇֔ym wĕ⁠ẕipi̇yţá֤ ʼòţá⁠m֙ záhá֔b wáwéy⁠he֖m záhá֑b wĕ⁠yáẕaqĕţá֣̇ lá⁠he֔m ẖàmişá֖̇̌h ʼadĕné֥y nĕẖòֽşěţ׃s"],[27,1,"וְ⁠עָשִׂ֥יתָ אֶת־הַ⁠מִּזְבֵּ֖חַ עֲצֵ֣י שִׁטִּ֑ים חָמֵשׁ֩ אַמּ֨וֹת אֹ֜רֶךְ וְ⁠חָמֵ֧שׁ אַמּ֣וֹת רֹ֗חַב רָב֤וּעַ יִהְיֶה֙ הַ⁠מִּזְבֵּ֔חַ וְ⁠שָׁלֹ֥שׁ אַמּ֖וֹת קֹמָתֽ⁠וֹ׃","wĕ⁠ʻáşî֥yţá ʼeţ-ha⁠mi̇zĕbé֖̇ẖa ʻàẕé֣y şǐti֑̇ym ẖáméş̌֩ ʼaṁ֨wòţ ʼò֜rekĕ wĕ⁠ẖámé֧ş̌ ʼaṁ֣wòţ rò֗ẖab ráb֤ẇʻa yihĕyeh֙ ha⁠mi̇zĕbé̇֔ẖa wĕ⁠şá̌lò֥ş̌ ʼaṁ֖wòţ qòmáţֽ⁠wò׃"],[27,2,"וְ⁠עָשִׂ֣יתָ קַרְנֹתָ֗י⁠ו עַ֚ל אַרְבַּ֣ע פִּנֹּתָ֔י⁠ו מִמֶּ֖⁠נּוּ תִּהְיֶ֣יןָ קַרְנֹתָ֑י⁠ו וְ⁠צִפִּיתָ֥ אֹת֖⁠וֹ נְחֹֽשֶׁת׃","wĕ⁠ʻáşî֣yţá qarĕnòţá֗y⁠w ʻa֚l ʼarĕbȧ֣ʻ pi̇nò̇ţá֔y⁠w mimė֖⁠ṅẇ ţi̇hĕye֣yná qarĕnòţá֑y⁠w wĕ⁠ẕipi̇yţá֥ ʼòţ֖⁠wò nĕẖòֽşěţ׃"],[27,3,"וְ⁠עָשִׂ֤יתָ סִּֽירֹתָי⁠ו֙ לְ⁠דַשְּׁנ֔⁠וֹ וְ⁠יָעָי⁠ו֙ וּ⁠מִזְרְקֹתָ֔י⁠ו וּ⁠מִזְלְגֹתָ֖י⁠ו וּ⁠מַחְתֹּתָ֑י⁠ו לְ⁠כָל־כֵּלָ֖י⁠ו תַּעֲשֶׂ֥ה נְחֹֽשֶׁת׃","wĕ⁠ʻáşî֤yţá siֽ̇yròţáy⁠w֙ lĕ⁠daşĕ̇̌n֔⁠wò wĕ⁠yáʻáy⁠w֙ ẇ⁠mizĕrĕqòţá֔y⁠w ẇ⁠mizĕlĕgòţá֖y⁠w ẇ⁠maẖĕţò̇ţá֑y⁠w lĕ⁠kál-ké̇lá֖y⁠w ţȧʻàşê֥h nĕẖòֽşěţ׃"],[27,4,"וְ⁠עָשִׂ֤יתָ לּ⁠וֹ֙ מִכְבָּ֔ר מַעֲשֵׂ֖ה רֶ֣שֶׁת נְחֹ֑שֶׁת וְ⁠עָשִׂ֣יתָ עַל־הָ⁠רֶ֗שֶׁת אַרְבַּע֙ טַבְּעֹ֣ת נְחֹ֔שֶׁת עַ֖ל אַרְבַּ֥ע קְצוֹתָֽי⁠ו׃","wĕ⁠ʻáşî֤yţá l̇⁠wò֙ mikĕbá̇֔r maʻàşé֖̂h re֣şěţ nĕẖò֑şěţ wĕ⁠ʻáşî֣yţá ʻal-há⁠re֗şěţ ʼarĕbȧʻ֙ tabĕ̇ʻò֣ţ nĕẖò֔şěţ ʻa֖l ʼarĕbȧ֥ʻ qĕẕwòţáֽy⁠w׃"],[27,5,"וְ⁠נָתַתָּ֣ה אֹתָ֗⁠הּ תַּ֛חַת כַּרְכֹּ֥ב הַ⁠מִּזְבֵּ֖חַ מִ⁠לְּ⁠מָ֑טָּה וְ⁠הָיְתָ֣ה הָ⁠רֶ֔שֶׁת עַ֖ד חֲצִ֥י הַ⁠מִּזְבֵּֽחַ׃","wĕ⁠náţaţá֣̇h ʼòţá֗⁠ḣ ţȧ֛ẖaţ kȧrĕkò֥̇b ha⁠mi̇zĕbé֖̇ẖa mi⁠lĕ̇⁠má֑tá̇h wĕ⁠háyĕţá֣h há⁠re֔şěţ ʻa֖d ẖàẕi֥y ha⁠mi̇zĕbéֽ̇ẖa׃"],[27,6,"וְ⁠עָשִׂ֤יתָ בַדִּים֙ לַ⁠מִּזְבֵּ֔חַ בַּדֵּ֖י עֲצֵ֣י שִׁטִּ֑ים וְ⁠צִפִּיתָ֥ אֹתָ֖⁠ם נְחֹֽשֶׁת׃","wĕ⁠ʻáşî֤yţá badi̇ym֙ la⁠mi̇zĕbé̇֔ẖa bȧdé֖̇y ʻàẕé֣y şǐti֑̇ym wĕ⁠ẕipi̇yţá֥ ʼòţá֖⁠m nĕẖòֽşěţ׃"],[27,7,"וְ⁠הוּבָ֥א אֶת־בַּדָּ֖י⁠ו בַּ⁠טַּבָּעֹ֑ת וְ⁠הָי֣וּ הַ⁠בַּדִּ֗ים עַל־שְׁתֵּ֛י צַלְעֹ֥ת הַ⁠מִּזְבֵּ֖חַ בִּ⁠שְׂאֵ֥ת אֹתֽ⁠וֹ׃","wĕ⁠hẇbá֥ʼ ʼeţ-bȧdá֖̇y⁠w bȧ⁠tȧbá̇ʻò֑ţ wĕ⁠háy֣ẇ ha⁠bȧdi̇֗ym ʻal-şĕ̌ţé֛̇y ẕalĕʻò֥ţ ha⁠mi̇zĕbé֖̇ẖa bi̇⁠şĕ̂ʼé֥ţ ʼòţֽ⁠wò׃"],[27,8,"נְב֥וּב לֻחֹ֖ת תַּעֲשֶׂ֣ה אֹת֑⁠וֹ כַּ⁠אֲשֶׁ֨ר הֶרְאָ֥ה אֹתְ⁠ךָ֛ בָּ⁠הָ֖ר כֵּ֥ן יַעֲשֽׂוּ׃ס","nĕb֥ẇb luẖò֖ţ ţȧʻàşê֣h ʼòţ֑⁠wò kȧ⁠ʼàşě֨r herĕʼá֥h ʼòţĕ⁠ká֛ bá̇⁠há֖r ké֥̇n yaʻàşֽ̂ẇ׃s"],[27,9,"וְ⁠עָשִׂ֕יתָ אֵ֖ת חֲצַ֣ר הַ⁠מִּשְׁכָּ֑ן לִ⁠פְאַ֣ת נֶֽגֶב־תֵּ֠ימָנָ⁠ה קְלָעִ֨ים לֶ⁠חָצֵ֜ר שֵׁ֣שׁ מָשְׁזָ֗ר מֵאָ֤ה בָֽ⁠אַמָּה֙ אֹ֔רֶךְ לַ⁠פֵּאָ֖ה הָ⁠אֶחָֽת׃","wĕ⁠ʻáşî֕yţá ʼé֖ţ ẖàẕa֣r ha⁠mi̇şĕ̌ká֑̇n li⁠pĕʼa֣ţ neֽgeb-ţé̇֠ymáná⁠h qĕláʻi֨ym le⁠ẖáẕé֜r şé֣̌ş̌ máşĕ̌zá֗r méʼá֤h báֽ⁠ʼamá̇h֙ ʼò֔rekĕ la⁠pé̇ʼá֖h há⁠ʼeẖáֽţ׃"],[27,10,"וְ⁠עַמֻּדָ֣י⁠ו עֶשְׂרִ֔ים וְ⁠אַדְנֵי⁠הֶ֥ם עֶשְׂרִ֖ים נְחֹ֑שֶׁת וָוֵ֧י הָ⁠עַמֻּדִ֛ים וַ⁠חֲשֻׁקֵי⁠הֶ֖ם כָּֽסֶף׃","wĕ⁠ʻamu̇dá֣y⁠w ʻeşĕ̂ri֔ym wĕ⁠ʼadĕnéy⁠he֥m ʻeşĕ̂ri֖ym nĕẖò֑şěţ wáwé֧y há⁠ʻamu̇di֛ym wa⁠ẖàşǔqéy⁠he֖m káֽ̇sep׃"],[27,11,"וְ⁠כֵ֨ן לִ⁠פְאַ֤ת צָפוֹן֙ בָּ⁠אֹ֔רֶךְ קְלָעִ֖ים מֵ֣אָה אֹ֑רֶךְ ו⁠עמד⁠ו עֶשְׂרִ֗ים וְ⁠אַדְנֵי⁠הֶ֤ם עֶשְׂרִים֙ נְחֹ֔שֶׁת וָוֵ֧י הָֽ⁠עַמֻּדִ֛ים וַ⁠חֲשֻׁקֵי⁠הֶ֖ם כָּֽסֶף׃","wĕ⁠ké֨n li⁠pĕʼa֤ţ ẕápwòn֙ bá̇⁠ʼò֔rekĕ qĕláʻi֖ym mé֣ʼáh ʼò֑rekĕ w⁠ʻmd⁠w ʻeşĕ̂ri֗ym wĕ⁠ʼadĕnéy⁠he֤m ʻeşĕ̂riym֙ nĕẖò֔şěţ wáwé֧y háֽ⁠ʻamu̇di֛ym wa⁠ẖàşǔqéy⁠he֖m káֽ̇sep׃"],[27,12,"וְ⁠רֹ֤חַב הֶֽ⁠חָצֵר֙ לִ⁠פְאַת־יָ֔ם קְלָעִ֖ים חֲמִשִּׁ֣ים אַמָּ֑ה עַמֻּדֵי⁠הֶ֣ם עֲשָׂרָ֔ה וְ⁠אַדְנֵי⁠הֶ֖ם עֲשָׂרָֽה׃","wĕ⁠rò֤ẖab heֽ⁠ẖáẕér֙ li⁠pĕʼaţ-yá֔m qĕláʻi֖ym ẖàmişi֣̇̌ym ʼamá֑̇h ʻamu̇déy⁠he֣m ʻàşá̂rá֔h wĕ⁠ʼadĕnéy⁠he֖m ʻàşá̂ráֽh׃"],[27,13,"וְ⁠רֹ֣חַב הֶֽ⁠חָצֵ֗ר לִ⁠פְאַ֛ת קֵ֥דְמָ⁠ה מִזְרָ֖חָ⁠ה חֲמִשִּׁ֥ים אַמָּֽה׃","wĕ⁠rò֣ẖab heֽ⁠ẖáẕé֗r li⁠pĕʼa֛ţ qé֥dĕmá⁠h mizĕrá֖ẖá⁠h ẖàmişi֥̇̌ym ʼamáֽ̇h׃"],[27,14,"וַ⁠חֲמֵ֨שׁ עֶשְׂרֵ֥ה אַמָּ֛ה קְלָעִ֖ים לַ⁠כָּתֵ֑ף עַמֻּדֵי⁠הֶ֣ם שְׁלֹשָׁ֔ה וְ⁠אַדְנֵי⁠הֶ֖ם שְׁלֹשָֽׁה׃","wa⁠ẖàmé֨ş̌ ʻeşĕ̂ré֥h ʼamá֛̇h qĕláʻi֖ym la⁠ká̇ţé֑p ʻamu̇déy⁠he֣m şĕ̌lòşá̌֔h wĕ⁠ʼadĕnéy⁠he֖m şĕ̌lòşáֽ̌h׃"],[27,15,"וְ⁠לַ⁠כָּתֵף֙ הַ⁠שֵּׁנִ֔ית חְמֵ֥שׁ עֶשְׂרֵ֖ה קְלָעִ֑ים עַמֻּדֵי⁠הֶ֣ם שְׁלֹשָׁ֔ה וְ⁠אַדְנֵי⁠הֶ֖ם שְׁלֹשָֽׁה׃","wĕ⁠la⁠ká̇ţép֙ ha⁠şé̇̌ni֔yţ ẖĕmé֥ş̌ ʻeşĕ̂ré֖h qĕláʻi֑ym ʻamu̇déy⁠he֣m şĕ̌lòşá̌֔h wĕ⁠ʼadĕnéy⁠he֖m şĕ̌lòşáֽ̌h׃"],[27,16,"וּ⁠לְ⁠שַׁ֨עַר הֶֽ⁠חָצֵ֜ר מָסָ֣ךְ ׀ עֶשְׂרִ֣ים אַמָּ֗ה תְּכֵ֨לֶת וְ⁠אַרְגָּמָ֜ן וְ⁠תוֹלַ֧עַת שָׁנִ֛י וְ⁠שֵׁ֥שׁ מָשְׁזָ֖ר מַעֲשֵׂ֣ה רֹקֵ֑ם עַמֻּֽדֵי⁠הֶם֙ אַרְבָּעָ֔ה וְ⁠אַדְנֵי⁠הֶ֖ם אַרְבָּעָֽה׃","ẇ⁠lĕ⁠şǎ֨ʻar heֽ⁠ẖáẕé֜r másá֣kĕ ׀ ʻeşĕ̂ri֣ym ʼamá̇֗h ţĕ̇ké֨leţ wĕ⁠ʼarĕgá̇má֜n wĕ⁠ţwòla֧ʻaţ şá̌ni֛y wĕ⁠şé֥̌ş̌ máşĕ̌zá֖r maʻàşé֣̂h ròqé֑m ʻamuֽ̇déy⁠hem֙ ʼarĕbá̇ʻá֔h wĕ⁠ʼadĕnéy⁠he֖m ʼarĕbá̇ʻáֽh׃"],[27,17,"כָּל־עַמּוּדֵ֨י הֶֽ⁠חָצֵ֤ר סָבִיב֙ מְחֻשָּׁקִ֣ים כֶּ֔סֶף וָוֵי⁠הֶ֖ם כָּ֑סֶף וְ⁠אַדְנֵי⁠הֶ֖ם נְחֹֽשֶׁת׃","ká̇l-ʻaṁẇdé֨y heֽ⁠ẖáẕé֤r sábiyb֙ mĕẖuşá̇̌qi֣ym kė֔sep wáwéy⁠he֖m ká֑̇sep wĕ⁠ʼadĕnéy⁠he֖m nĕẖòֽşěţ׃"],[27,18,"אֹ֣רֶךְ הֶֽ⁠חָצֵר֩ מֵאָ֨ה בָֽ⁠אַמָּ֜ה וְ⁠רֹ֣חַב ׀ חֲמִשִּׁ֣ים בַּ⁠חֲמִשִּׁ֗ים וְ⁠קֹמָ֛ה חָמֵ֥שׁ אַמּ֖וֹת שֵׁ֣שׁ מָשְׁזָ֑ר וְ⁠אַדְנֵי⁠הֶ֖ם נְחֹֽשֶׁת׃","ʼò֣rekĕ heֽ⁠ẖáẕér֩ méʼá֨h báֽ⁠ʼamá̇֜h wĕ⁠rò֣ẖab ׀ ẖàmişi֣̇̌ym bȧ⁠ẖàmişi̇̌֗ym wĕ⁠qòmá֛h ẖámé֥ş̌ ʼaṁ֖wòţ şé֣̌ş̌ máşĕ̌zá֑r wĕ⁠ʼadĕnéy⁠he֖m nĕẖòֽşěţ׃"],[27,19,"לְ⁠כֹל֙ כְּלֵ֣י הַ⁠מִּשְׁכָּ֔ן בְּ⁠כֹ֖ל עֲבֹדָת֑⁠וֹ וְ⁠כָל־יְתֵדֹתָ֛י⁠ו וְ⁠כָל־יִתְדֹ֥ת הֶ⁠חָצֵ֖ר נְחֹֽשֶׁת׃ס","lĕ⁠kòl֙ kĕ̇lé֣y ha⁠mi̇şĕ̌ká̇֔n bĕ̇⁠kò֖l ʻàbòdáţ֑⁠wò wĕ⁠kál-yĕţédòţá֛y⁠w wĕ⁠kál-yiţĕdò֥ţ he⁠ẖáẕé֖r nĕẖòֽşěţ׃s"],[27,20,"וְ⁠אַתָּ֞ה תְּצַוֶּ֣ה ׀ אֶת־בְּנֵ֣י יִשְׂרָאֵ֗ל וְ⁠יִקְח֨וּ אֵלֶ֜י⁠ךָ שֶׁ֣מֶן זַ֥יִת זָ֛ךְ כָּתִ֖ית לַ⁠מָּא֑וֹר לְ⁠הַעֲלֹ֥ת נֵ֖ר תָּמִֽיד׃","wĕ⁠ʼaţá̇֞h ţĕ̇ẕawė֣h ׀ ʼeţ-bĕ̇né֣y yişĕ̂ráʼé֗l wĕ⁠yiqĕẖ֨ẇ ʼéle֜y⁠ká şě֣men za֥yiţ zá֛kĕ ká̇ţi֖yţ la⁠má̇ʼ֑wòr lĕ⁠haʻàlò֥ţ né֖r ţá̇miֽyd׃"],[27,21,"בְּ⁠אֹ֣הֶל מוֹעֵד֩ מִ⁠ח֨וּץ לַ⁠פָּרֹ֜כֶת אֲשֶׁ֣ר עַל־הָ⁠עֵדֻ֗ת יַעֲרֹךְ֩ אֹת֨⁠וֹ אַהֲרֹ֧ן וּ⁠בָנָ֛י⁠ו מֵ⁠עֶ֥רֶב עַד־בֹּ֖קֶר לִ⁠פְנֵ֣י יְהוָ֑ה חֻקַּ֤ת עוֹלָם֙ לְ⁠דֹ֣רֹתָ֔⁠ם מֵ⁠אֵ֖ת בְּנֵ֥י יִשְׂרָאֵֽל׃ס","bĕ̇⁠ʼò֣hel mwòʻéd֩ mi⁠ẖ֨ẇẕ la⁠pá̇rò֜keţ ʼàşě֣r ʻal-há⁠ʻédu֗ţ yaʻàròkĕ֩ ʼòţ֨⁠wò ʼahàrò֧n ẇ⁠báná֛y⁠w mé⁠ʻe֥reb ʻad-bò֖̇qer li⁠pĕné֣y yĕhwá֑h ẖuqȧ֤ţ ʻwòlám֙ lĕ⁠dò֣ròţá֔⁠m mé⁠ʼé֖ţ bĕ̇né֥y yişĕ̂ráʼéֽl׃s"],[28,1,"וְ⁠אַתָּ֡ה הַקְרֵ֣ב אֵלֶי⁠ךָ֩ אֶת־אַהֲרֹ֨ן אָחִ֜י⁠ךָ וְ⁠אֶת־בָּנָ֣י⁠ו אִתּ֔⁠וֹ מִ⁠תּ֛וֹךְ בְּנֵ֥י יִשְׂרָאֵ֖ל לְ⁠כַהֲנ⁠וֹ־לִ֑⁠י אַהֲרֹ֕ן נָדָ֧ב וַ⁠אֲבִיה֛וּא אֶלְעָזָ֥ר וְ⁠אִיתָמָ֖ר בְּנֵ֥י אַהֲרֹֽן׃","wĕ⁠ʼaţá̇֡h haqĕré֣b ʼéley⁠ká֩ ʼeţ-ʼahàrò֨n ʼáẖi֜y⁠ká wĕ⁠ʼeţ-bá̇ná֣y⁠w ʼiţ̇֔⁠wò mi⁠ţ֛̇wòkĕ bĕ̇né֥y yişĕ̂ráʼé֖l lĕ⁠kahàn⁠wò-li֑⁠y ʼahàrò֕n nádá֧b wa⁠ʼàbiyh֛ẇʼ ʼelĕʻázá֥r wĕ⁠ʼiyţámá֖r bĕ̇né֥y ʼahàròֽn׃"],[28,2,"וְ⁠עָשִׂ֥יתָ בִגְדֵי־קֹ֖דֶשׁ לְ⁠אַהֲרֹ֣ן אָחִ֑י⁠ךָ לְ⁠כָב֖וֹד וּ⁠לְ⁠תִפְאָֽרֶת׃","wĕ⁠ʻáşî֥yţá bigĕdéy-qò֖deş̌ lĕ⁠ʼahàrò֣n ʼáẖi֑y⁠ká lĕ⁠káb֖wòd ẇ⁠lĕ⁠ţipĕʼáֽreţ׃"],[28,3,"וְ⁠אַתָּ֗ה תְּדַבֵּר֙ אֶל־כָּל־חַכְמֵי־לֵ֔ב אֲשֶׁ֥ר מִלֵּאתִ֖י⁠ו ר֣וּחַ חָכְמָ֑ה וְ⁠עָשׂ֞וּ אֶת־בִּגְדֵ֧י אַהֲרֹ֛ן לְ⁠קַדְּשׁ֖⁠וֹ לְ⁠כַהֲנ⁠וֹ־לִֽ⁠י׃","wĕ⁠ʼaţá̇֗h ţĕ̇dabé̇r֙ ʼel-ká̇l-ẖakĕméy-lé֔b ʼàşě֥r milé̇ʼţi֖y⁠w r֣ẇẖa ẖákĕmá֑h wĕ⁠ʻáş̂֞ẇ ʼeţ-bi̇gĕdé֧y ʼahàrò֛n lĕ⁠qadĕ̇ş֖̌⁠wò lĕ⁠kahàn⁠wò-liֽ⁠y׃"],[28,4,"וְ⁠אֵ֨לֶּה הַ⁠בְּגָדִ֜ים אֲשֶׁ֣ר יַעֲשׂ֗וּ חֹ֤שֶׁן וְ⁠אֵפוֹד֙ וּ⁠מְעִ֔יל וּ⁠כְתֹ֥נֶת תַּשְׁבֵּ֖ץ מִצְנֶ֣פֶת וְ⁠אַבְנֵ֑ט וְ⁠עָשׂ֨וּ בִגְדֵי־קֹ֜דֶשׁ לְ⁠אַהֲרֹ֥ן אָחִ֛י⁠ךָ וּ⁠לְ⁠בָנָ֖י⁠ו לְ⁠כַהֲנ⁠וֹ־לִֽ⁠י׃","wĕ⁠ʼé֨lėh ha⁠bĕ̇gádi֜ym ʼàşě֣r yaʻàş̂֗ẇ ẖò֤şěn wĕ⁠ʼépwòd֙ ẇ⁠mĕʻi֔yl ẇ⁠kĕţò֥neţ ţȧşĕ̌bé֖̇ẕ miẕĕne֣peţ wĕ⁠ʼabĕné֑t wĕ⁠ʻáş̂֨ẇ bigĕdéy-qò֜deş̌ lĕ⁠ʼahàrò֥n ʼáẖi֛y⁠ká ẇ⁠lĕ⁠báná֖y⁠w lĕ⁠kahàn⁠wò-liֽ⁠y׃"],[28,5,"וְ⁠הֵם֙ יִקְח֣וּ אֶת־הַ⁠זָּהָ֔ב וְ⁠אֶת־הַ⁠תְּכֵ֖לֶת וְ⁠אֶת־הָֽ⁠אַרְגָּמָ֑ן וְ⁠אֶת־תּוֹלַ֥עַת הַ⁠שָּׁנִ֖י וְ⁠אֶת־הַ⁠שֵּֽׁשׁ׃פ","wĕ⁠hém֙ yiqĕẖ֣ẇ ʼeţ-ha⁠zá̇há֔b wĕ⁠ʼeţ-ha⁠ţĕ̇ké֖leţ wĕ⁠ʼeţ-háֽ⁠ʼarĕgá̇má֑n wĕ⁠ʼeţ-ţ̇wòla֥ʻaţ ha⁠şá̇̌ni֖y wĕ⁠ʼeţ-ha⁠şéֽ̇̌ş̌׃p"],[28,6,"וְ⁠עָשׂ֖וּ אֶת־הָ⁠אֵפֹ֑ד זָ֠הָב תְּכֵ֨לֶת וְ⁠אַרְגָּמָ֜ן תּוֹלַ֧עַת שָׁנִ֛י וְ⁠שֵׁ֥שׁ מָשְׁזָ֖ר מַעֲשֵׂ֥ה חֹשֵֽׁב׃","wĕ⁠ʻáş֖̂ẇ ʼeţ-há⁠ʼépò֑d zá֠háb ţĕ̇ké֨leţ wĕ⁠ʼarĕgá̇má֜n ţ̇wòla֧ʻaţ şá̌ni֛y wĕ⁠şé֥̌ş̌ máşĕ̌zá֖r maʻàşé֥̂h ẖòşéֽ̌b׃"],[28,7,"שְׁתֵּ֧י כְתֵפֹ֣ת חֹֽבְרֹ֗ת יִֽהְיֶה־לּ֛⁠וֹ אֶל־שְׁנֵ֥י קְצוֹתָ֖י⁠ו וְ⁠חֻבָּֽר׃","şĕ̌ţé֧̇y kĕţépò֣ţ ẖòֽbĕrò֗ţ yiֽhĕyeh-l֛̇⁠wò ʼel-şĕ̌né֥y qĕẕwòţá֖y⁠w wĕ⁠ẖubáֽ̇r׃"],[28,8,"וְ⁠חֵ֤שֶׁב אֲפֻדָּת⁠וֹ֙ אֲשֶׁ֣ר עָלָ֔י⁠ו כְּ⁠מַעֲשֵׂ֖⁠הוּ מִמֶּ֣⁠נּוּ יִהְיֶ֑ה זָהָ֗ב תְּכֵ֧לֶת וְ⁠אַרְגָּמָ֛ן וְ⁠תוֹלַ֥עַת שָׁנִ֖י וְ⁠שֵׁ֥שׁ מָשְׁזָֽר׃","wĕ⁠ẖé֤şěb ʼàpudá̇ţ⁠wò֙ ʼàşě֣r ʻálá֔y⁠w kĕ̇⁠maʻàşé֖̂⁠hẇ mimė֣⁠ṅẇ yihĕye֑h záhá֗b ţĕ̇ké֧leţ wĕ⁠ʼarĕgá̇má֛n wĕ⁠ţwòla֥ʻaţ şá̌ni֖y wĕ⁠şé֥̌ş̌ máşĕ̌záֽr׃"],[28,9,"וְ⁠לָ֣קַחְתָּ֔ אֶת־שְׁתֵּ֖י אַבְנֵי־שֹׁ֑הַם וּ⁠פִתַּחְתָּ֣ עֲלֵי⁠הֶ֔ם שְׁמ֖וֹת בְּנֵ֥י יִשְׂרָאֵֽל׃","wĕ⁠lá֣qaẖĕţá̇֔ ʼeţ-şĕ̌ţé֖̇y ʼabĕnéy-şò֑̌ham ẇ⁠piţȧẖĕţá֣̇ ʻàléy⁠he֔m şĕ̌m֖wòţ bĕ̇né֥y yişĕ̂ráʼéֽl׃"],[28,10,"שִׁשָּׁה֙ מִ⁠שְּׁמֹתָ֔⁠ם עַ֖ל הָ⁠אֶ֣בֶן הָ⁠אֶחָ֑ת וְ⁠אֶת־שְׁמ֞וֹת הַ⁠שִּׁשָּׁ֧ה הַ⁠נּוֹתָרִ֛ים עַל־הָ⁠אֶ֥בֶן הַ⁠שֵּׁנִ֖ית כְּ⁠תוֹלְדֹתָֽ⁠ם׃","şǐşá̇̌h֙ mi⁠şĕ̇̌mòţá֔⁠m ʻa֖l há⁠ʼe֣ben há⁠ʼeẖá֑ţ wĕ⁠ʼeţ-şĕ̌m֞wòţ ha⁠şi̇̌şá֧̇̌h ha⁠ṅwòţári֛ym ʻal-há⁠ʼe֥ben ha⁠şé̇̌ni֖yţ kĕ̇⁠ţwòlĕdòţáֽ⁠m׃"],[28,11,"מַעֲשֵׂ֣ה חָרַשׁ֮ אֶבֶן֒ פִּתּוּחֵ֣י חֹתָ֗ם תְּפַתַּח֙ אֶת־שְׁתֵּ֣י הָ⁠אֲבָנִ֔ים עַל־שְׁמֹ֖ת בְּנֵ֣י יִשְׂרָאֵ֑ל מֻסַבֹּ֛ת מִשְׁבְּצ֥וֹת זָהָ֖ב תַּעֲשֶׂ֥ה אֹתָֽ⁠ם׃","maʻàşé֣̂h ẖáraş֮̌ ʼeben֒ pi̇ţ̇ẇẖé֣y ẖòţá֗m ţĕ̇paţȧẖ֙ ʼeţ-şĕ̌ţé֣̇y há⁠ʼàbáni֔ym ʻal-şĕ̌mò֖ţ bĕ̇né֣y yişĕ̂ráʼé֑l musabò֛̇ţ mişĕ̌bĕ̇ẕ֥wòţ záhá֖b ţȧʻàşê֥h ʼòţáֽ⁠m׃"],[28,12,"וְ⁠שַׂמְתָּ֞ אֶת־שְׁתֵּ֣י הָ⁠אֲבָנִ֗ים עַ֚ל כִּתְפֹ֣ת הָֽ⁠אֵפֹ֔ד אַבְנֵ֥י זִכָּרֹ֖ן לִ⁠בְנֵ֣י יִשְׂרָאֵ֑ל וְ⁠נָשָׂא֩ אַהֲרֹ֨ן אֶת־שְׁמוֹתָ֜⁠ם לִ⁠פְנֵ֧י יְהוָ֛ה עַל־שְׁתֵּ֥י כְתֵפָ֖י⁠ו לְ⁠זִכָּרֹֽן׃ס","wĕ⁠şâmĕţá̇֞ ʼeţ-şĕ̌ţé֣̇y há⁠ʼàbáni֗ym ʻa֚l ki̇ţĕpò֣ţ háֽ⁠ʼépò֔d ʼabĕné֥y ziká̇rò֖n li⁠bĕné֣y yişĕ̂ráʼé֑l wĕ⁠náşá̂ʼ֩ ʼahàrò֨n ʼeţ-şĕ̌mwòţá֜⁠m li⁠pĕné֧y yĕhwá֛h ʻal-şĕ̌ţé֥̇y kĕţépá֖y⁠w lĕ⁠ziká̇ròֽn׃s"],[28,13,"וְ⁠עָשִׂ֥יתָ מִשְׁבְּצֹ֖ת זָהָֽב׃","wĕ⁠ʻáşî֥yţá mişĕ̌bĕ̇ẕò֖ţ záháֽb׃"],[28,14,"וּ⁠שְׁתֵּ֤י שַׁרְשְׁרֹת֙ זָהָ֣ב טָה֔וֹר מִגְבָּלֹ֛ת תַּעֲשֶׂ֥ה אֹתָ֖⁠ם מַעֲשֵׂ֣ה עֲבֹ֑ת וְ⁠נָתַתָּ֛ה אֶת־שַׁרְשְׁרֹ֥ת הָ⁠עֲבֹתֹ֖ת עַל־הַֽ⁠מִּשְׁבְּצֹֽת׃ס","ẇ⁠şĕ̌ţé֤̇y şǎrĕşĕ̌ròţ֙ záhá֣b táh֔wòr migĕbá̇lò֛ţ ţȧʻàşê֥h ʼòţá֖⁠m maʻàşé֣̂h ʻàbò֑ţ wĕ⁠náţaţá֛̇h ʼeţ-şǎrĕşĕ̌rò֥ţ há⁠ʻàbòţò֖ţ ʻal-haֽ⁠mi̇şĕ̌bĕ̇ẕòֽţ׃s"],[28,15,"וְ⁠עָשִׂ֜יתָ חֹ֤שֶׁן מִשְׁפָּט֙ מַעֲשֵׂ֣ה חֹשֵׁ֔ב כְּ⁠מַעֲשֵׂ֥ה אֵפֹ֖ד תַּעֲשֶׂ֑⁠נּוּ זָ֠הָב תְּכֵ֨לֶת וְ⁠אַרְגָּמָ֜ן וְ⁠תוֹלַ֧עַת שָׁנִ֛י וְ⁠שֵׁ֥שׁ מָשְׁזָ֖ר תַּעֲשֶׂ֥ה אֹתֽ⁠וֹ׃","wĕ⁠ʻáşî֜yţá ẖò֤şěn mişĕ̌pá̇t֙ maʻàşé֣̂h ẖòşé̌֔b kĕ̇⁠maʻàşé֥̂h ʼépò֖d ţȧʻàşê֑⁠ṅẇ zá֠háb ţĕ̇ké֨leţ wĕ⁠ʼarĕgá̇má֜n wĕ⁠ţwòla֧ʻaţ şá̌ni֛y wĕ⁠şé֥̌ş̌ máşĕ̌zá֖r ţȧʻàşê֥h ʼòţֽ⁠wò׃"],[28,16,"רָב֥וּעַ יִֽהְיֶ֖ה כָּפ֑וּל זֶ֥רֶת אָרְכּ֖⁠וֹ וְ⁠זֶ֥רֶת רָחְבּֽ⁠וֹ׃","ráb֥ẇʻa yiֽhĕye֖h ká̇p֑ẇl ze֥reţ ʼárĕk֖̇⁠wò wĕ⁠ze֥reţ ráẖĕḃֽ⁠wò׃"],[28,17,"וּ⁠מִלֵּאתָ֥ ב⁠וֹ֙ מִלֻּ֣אַת אֶ֔בֶן אַרְבָּעָ֖ה טוּרִ֣ים אָ֑בֶן ט֗וּר אֹ֤דֶם פִּטְדָה֙ וּ⁠בָרֶ֔קֶת הַ⁠טּ֖וּר הָ⁠אֶחָֽד׃","ẇ⁠milé̇ʼţá֥ b⁠wò֙ milu֣̇ʼaţ ʼe֔ben ʼarĕbá̇ʻá֖h tẇri֣ym ʼá֑ben t֗ẇr ʼò֤dem pi̇tĕdáh֙ ẇ⁠báre֔qeţ ha⁠ṫ֖ẇr há⁠ʼeẖáֽd׃"],[28,18,"וְ⁠הַ⁠טּ֖וּר הַ⁠שֵּׁנִ֑י נֹ֥פֶךְ סַפִּ֖יר וְ⁠יָהֲלֹֽם׃","wĕ⁠ha⁠ṫ֖ẇr ha⁠şé̇̌ni֑y nò֥pekĕ sapi֖̇yr wĕ⁠yáhàlòֽm׃"],[28,19,"וְ⁠הַ⁠טּ֖וּר הַ⁠שְּׁלִישִׁ֑י לֶ֥שֶׁם שְׁב֖וֹ וְ⁠אַחְלָֽמָה׃","wĕ⁠ha⁠ṫ֖ẇr ha⁠şĕ̇̌liyşǐ֑y le֥şěm şĕ̌b֖wò wĕ⁠ʼaẖĕláֽmáh׃"],[28,20,"וְ⁠הַ⁠טּוּר֙ הָ⁠רְבִיעִ֔י תַּרְשִׁ֥ישׁ וְ⁠שֹׁ֖הַם וְ⁠יָשְׁפֵ֑ה מְשֻׁבָּצִ֥ים זָהָ֛ב יִהְי֖וּ בְּ⁠מִלּוּאֹתָֽ⁠ם׃","wĕ⁠ha⁠ṫẇr֙ há⁠rĕbiyʻi֔y ţȧrĕşǐ֥yş̌ wĕ⁠şò֖̌ham wĕ⁠yáşĕ̌pé֑h mĕşǔbá̇ẕi֥ym záhá֛b yihĕy֖ẇ bĕ̇⁠mil̇ẇʼòţáֽ⁠m׃"],[28,21,"וְ֠⁠הָ⁠אֲבָנִים תִּֽהְיֶ֜יןָ עַל־שְׁמֹ֧ת בְּנֵֽי־יִשְׂרָאֵ֛ל שְׁתֵּ֥ים עֶשְׂרֵ֖ה עַל־שְׁמֹתָ֑⁠ם פִּתּוּחֵ֤י חוֹתָם֙ אִ֣ישׁ עַל־שְׁמ֔⁠וֹ תִּֽהְיֶ֕יןָ לִ⁠שְׁנֵ֥י עָשָׂ֖ר שָֽׁבֶט׃","wĕ֠⁠há⁠ʼàbániym ţiֽ̇hĕye֜yná ʻal-şĕ̌mò֧ţ bĕ̇néֽy-yişĕ̂ráʼé֛l şĕ̌ţé֥̇ym ʻeşĕ̂ré֖h ʻal-şĕ̌mòţá֑⁠m pi̇ţ̇ẇẖé֤y ẖwòţám֙ ʼi֣yş̌ ʻal-şĕ̌m֔⁠wò ţiֽ̇hĕye֕yná li⁠şĕ̌né֥y ʻáşá֖̂r şáֽ̌bet׃"],[28,22,"וְ⁠עָשִׂ֧יתָ עַל־הַ⁠חֹ֛שֶׁן שַֽׁרְשֹׁ֥ת גַּבְלֻ֖ת מַעֲשֵׂ֣ה עֲבֹ֑ת זָהָ֖ב טָהֽוֹר׃","wĕ⁠ʻáşî֧yţá ʻal-ha⁠ẖò֛şěn şǎֽrĕşò֥̌ţ gȧbĕlu֖ţ maʻàşé֣̂h ʻàbò֑ţ záhá֖b táhֽwòr׃"],[28,23,"וְ⁠עָשִׂ֨יתָ֙ עַל־הַ⁠חֹ֔שֶׁן שְׁתֵּ֖י טַבְּע֣וֹת זָהָ֑ב וְ⁠נָתַתָּ֗ אֶת־שְׁתֵּי֙ הַ⁠טַּבָּע֔וֹת עַל־שְׁנֵ֖י קְצ֥וֹת הַ⁠חֹֽשֶׁן׃","wĕ⁠ʻáşî֨yţá֙ ʻal-ha⁠ẖò֔şěn şĕ̌ţé֖̇y tabĕ̇ʻ֣wòţ záhá֑b wĕ⁠náţaţá̇֗ ʼeţ-şĕ̌ţé̇y֙ ha⁠tȧbá̇ʻ֔wòţ ʻal-şĕ̌né֖y qĕẕ֥wòţ ha⁠ẖòֽşěn׃"],[28,24,"וְ⁠נָתַתָּ֗ה אֶת־שְׁתֵּי֙ עֲבֹתֹ֣ת הַ⁠זָּהָ֔ב עַל־שְׁתֵּ֖י הַ⁠טַּבָּעֹ֑ת אֶל־קְצ֖וֹת הַ⁠חֹֽשֶׁן׃","wĕ⁠náţaţá̇֗h ʼeţ-şĕ̌ţé̇y֙ ʻàbòţò֣ţ ha⁠zá̇há֔b ʻal-şĕ̌ţé֖̇y ha⁠tȧbá̇ʻò֑ţ ʼel-qĕẕ֖wòţ ha⁠ẖòֽşěn׃"],[28,25,"וְ⁠אֵ֨ת שְׁתֵּ֤י קְצוֹת֙ שְׁתֵּ֣י הָ⁠עֲבֹתֹ֔ת תִּתֵּ֖ן עַל־שְׁתֵּ֣י הַֽ⁠מִּשְׁבְּצ֑וֹת וְ⁠נָתַתָּ֛ה עַל־כִּתְפ֥וֹת הָ⁠אֵפֹ֖ד אֶל־מ֥וּל פָּנָֽי⁠ו׃","wĕ⁠ʼé֨ţ şĕ̌ţé֤̇y qĕẕwòţ֙ şĕ̌ţé֣̇y há⁠ʻàbòţò֔ţ ţi̇ţé֖̇n ʻal-şĕ̌ţé֣̇y haֽ⁠mi̇şĕ̌bĕ̇ẕ֑wòţ wĕ⁠náţaţá֛̇h ʻal-ki̇ţĕp֥wòţ há⁠ʼépò֖d ʼel-m֥ẇl pá̇náֽy⁠w׃"],[28,26,"וְ⁠עָשִׂ֗יתָ שְׁתֵּי֙ טַבְּע֣וֹת זָהָ֔ב וְ⁠שַׂמְתָּ֣ אֹתָ֔⁠ם עַל־שְׁנֵ֖י קְצ֣וֹת הַ⁠חֹ֑שֶׁן עַל־שְׂפָת֕⁠וֹ אֲשֶׁ֛ר אֶל־עֵ֥בֶר הָ⁠אֵפֹ֖ד בָּֽיְתָ⁠ה׃","wĕ⁠ʻáşî֗yţá şĕ̌ţé̇y֙ tabĕ̇ʻ֣wòţ záhá֔b wĕ⁠şâmĕţá֣̇ ʼòţá֔⁠m ʻal-şĕ̌né֖y qĕẕ֣wòţ ha⁠ẖò֑şěn ʻal-şĕ̂páţ֕⁠wò ʼàşě֛r ʼel-ʻé֥ber há⁠ʼépò֖d báֽ̇yĕţá⁠h׃"],[28,27,"וְ⁠עָשִׂיתָ֮ שְׁתֵּ֣י טַבְּע֣וֹת זָהָב֒ וְ⁠נָתַתָּ֣ה אֹתָ֡⁠ם עַל־שְׁתֵּי֩ כִתְפ֨וֹת הָ⁠אֵפ֤וֹד מִ⁠לְּ⁠מַ֨טָּה֙ מִ⁠מּ֣וּל פָּנָ֔י⁠ו לְ⁠עֻמַּ֖ת מֶחְבַּרְתּ֑⁠וֹ מִ⁠מַּ֕עַל לְ⁠חֵ֖שֶׁב הָ⁠אֵפֽוֹד׃","wĕ⁠ʻáşîyţá֮ şĕ̌ţé֣̇y tabĕ̇ʻ֣wòţ záháb֒ wĕ⁠náţaţá֣̇h ʼòţá֡⁠m ʻal-şĕ̌ţé̇y֩ kiţĕp֨wòţ há⁠ʼép֤wòd mi⁠lĕ̇⁠ma֨tá̇h֙ mi⁠ṁ֣ẇl pá̇ná֔y⁠w lĕ⁠ʻumȧ֖ţ meẖĕbȧrĕţ֑̇⁠wò mi⁠mȧ֕ʻal lĕ⁠ẖé֖şěb há⁠ʼépֽwòd׃"],[28,28,"וְ⁠יִרְכְּס֣וּ אֶת־הַ֠⁠חֹשֶׁן מ⁠טבעת⁠ו אֶל־טַבְּעֹ֤ת הָ⁠אֵפֹד֙ בִּ⁠פְתִ֣יל תְּכֵ֔לֶת לִֽ⁠הְי֖וֹת עַל־חֵ֣שֶׁב הָ⁠אֵפ֑וֹד וְ⁠לֹֽא־יִזַּ֣ח הַ⁠חֹ֔שֶׁן מֵ⁠עַ֖ל הָ⁠אֵפֽוֹד׃","wĕ⁠yirĕkĕ̇s֣ẇ ʼeţ-ha֠⁠ẖòşěn m⁠tbʻţ⁠w ʼel-tabĕ̇ʻò֤ţ há⁠ʼépòd֙ bi̇⁠pĕţi֣yl ţĕ̇ké֔leţ liֽ⁠hĕy֖wòţ ʻal-ẖé֣şěb há⁠ʼép֑wòd wĕ⁠lòֽʼ-yizȧ֣ẖ ha⁠ẖò֔şěn mé⁠ʻa֖l há⁠ʼépֽwòd׃"],[28,29,"וְ⁠נָשָׂ֣א אַ֠הֲרֹן אֶת־שְׁמ֨וֹת בְּנֵֽי־יִשְׂרָאֵ֜ל בְּ⁠חֹ֧שֶׁן הַ⁠מִּשְׁפָּ֛ט עַל־לִבּ֖⁠וֹ בְּ⁠בֹא֣⁠וֹ אֶל־הַ⁠קֹּ֑דֶשׁ לְ⁠זִכָּרֹ֥ן לִ⁠פְנֵֽי־יְהוָ֖ה תָּמִֽיד׃","wĕ⁠náşá֣̂ʼ ʼa֠hàròn ʼeţ-şĕ̌m֨wòţ bĕ̇néֽy-yişĕ̂ráʼé֜l bĕ̇⁠ẖò֧şěn ha⁠mi̇şĕ̌pá֛̇t ʻal-liḃ֖⁠wò bĕ̇⁠bòʼ֣⁠wò ʼel-ha⁠qò֑̇deş̌ lĕ⁠ziká̇rò֥n li⁠pĕnéֽy-yĕhwá֖h ţá̇miֽyd׃"],[28,30,"וְ⁠נָתַתָּ֞ אֶל־חֹ֣שֶׁן הַ⁠מִּשְׁפָּ֗ט אֶת־הָ⁠אוּרִים֙ וְ⁠אֶת־הַ⁠תֻּמִּ֔ים וְ⁠הָיוּ֙ עַל־לֵ֣ב אַהֲרֹ֔ן בְּ⁠בֹא֖⁠וֹ לִ⁠פְנֵ֣י יְהוָ֑ה וְ⁠נָשָׂ֣א אַ֠הֲרֹן אֶת־מִשְׁפַּ֨ט בְּנֵי־יִשְׂרָאֵ֧ל עַל־לִבּ֛⁠וֹ לִ⁠פְנֵ֥י יְהוָ֖ה תָּמִֽיד׃ס","wĕ⁠náţaţá̇֞ ʼel-ẖò֣şěn ha⁠mi̇şĕ̌pá̇֗t ʼeţ-há⁠ʼẇriym֙ wĕ⁠ʼeţ-ha⁠ţu̇mi̇֔ym wĕ⁠háyẇ֙ ʻal-lé֣b ʼahàrò֔n bĕ̇⁠bòʼ֖⁠wò li⁠pĕné֣y yĕhwá֑h wĕ⁠náşá֣̂ʼ ʼa֠hàròn ʼeţ-mişĕ̌pȧ֨t bĕ̇néy-yişĕ̂ráʼé֧l ʻal-liḃ֛⁠wò li⁠pĕné֥y yĕhwá֖h ţá̇miֽyd׃s"],[28,31,"וְ⁠עָשִׂ֛יתָ אֶת־מְעִ֥יל הָ⁠אֵפ֖וֹד כְּלִ֥יל תְּכֵֽלֶת׃","wĕ⁠ʻáşî֛yţá ʼeţ-mĕʻi֥yl há⁠ʼép֖wòd kĕ̇li֥yl ţĕ̇kéֽleţ׃"],[28,32,"וְ⁠הָיָ֥ה פִֽי־רֹאשׁ֖⁠וֹ בְּ⁠תוֹכ֑⁠וֹ שָׂפָ֡ה יִֽהְיֶה֩ לְ⁠פִ֨י⁠ו סָבִ֜יב מַעֲשֵׂ֣ה אֹרֵ֗ג כְּ⁠פִ֥י תַחְרָ֛א יִֽהְיֶה־לּ֖⁠וֹ לֹ֥א יִקָּרֵֽעַ׃","wĕ⁠háyá֥h piֽy-ròʼş֖̌⁠wò bĕ̇⁠ţwòk֑⁠wò şá̂pá֡h yiֽhĕyeh֩ lĕ⁠pi֨y⁠w sábi֜yb maʻàşé֣̂h ʼòré֗g kĕ̇⁠pi֥y ţaẖĕrá֛ʼ yiֽhĕyeh-l֖̇⁠wò lò֥ʼ yiqá̇réֽʻa׃"],[28,33,"וְ⁠עָשִׂ֣יתָ עַל־שׁוּלָ֗י⁠ו רִמֹּנֵי֙ תְּכֵ֤לֶת וְ⁠אַרְגָּמָן֙ וְ⁠תוֹלַ֣עַת שָׁנִ֔י עַל־שׁוּלָ֖י⁠ו סָבִ֑יב וּ⁠פַעֲמֹנֵ֥י זָהָ֛ב בְּ⁠תוֹכָ֖⁠ם סָבִֽיב׃","wĕ⁠ʻáşî֣yţá ʻal-ş̌ẇlá֗y⁠w rimò̇néy֙ ţĕ̇ké֤leţ wĕ⁠ʼarĕgá̇mán֙ wĕ⁠ţwòla֣ʻaţ şá̌ni֔y ʻal-ş̌ẇlá֖y⁠w sábi֑yb ẇ⁠paʻàmòné֥y záhá֛b bĕ̇⁠ţwòká֖⁠m sábiֽyb׃"],[28,34,"פַּעֲמֹ֤ן זָהָב֙ וְ⁠רִמּ֔וֹן פַּֽעֲמֹ֥ן זָהָ֖ב וְ⁠רִמּ֑וֹן עַל־שׁוּלֵ֥י הַ⁠מְּעִ֖יל סָבִֽיב׃","pȧʻàmò֤n záháb֙ wĕ⁠riṁ֔wòn ṗֽaʻàmò֥n záhá֖b wĕ⁠riṁ֑wòn ʻal-ş̌ẇlé֥y ha⁠mĕ̇ʻi֖yl sábiֽyb׃"],[28,35,"וְ⁠הָיָ֥ה עַֽל־אַהֲרֹ֖ן לְ⁠שָׁרֵ֑ת וְ⁠נִשְׁמַ֣ע ק֠וֹל⁠וֹ בְּ⁠בֹא֨⁠וֹ אֶל־הַ⁠קֹּ֜דֶשׁ לִ⁠פְנֵ֧י יְהוָ֛ה וּ⁠בְ⁠צֵאת֖⁠וֹ וְ⁠לֹ֥א יָמֽוּת׃ס","wĕ⁠háyá֥h ʻaֽl-ʼahàrò֖n lĕ⁠şá̌ré֑ţ wĕ⁠nişĕ̌ma֣ʻ q֠wòl⁠wò bĕ̇⁠bòʼ֨⁠wò ʼel-ha⁠qò̇֜deş̌ li⁠pĕné֧y yĕhwá֛h ẇ⁠bĕ⁠ẕéʼţ֖⁠wò wĕ⁠lò֥ʼ yámֽẇţ׃s"],[28,36,"וְ⁠עָשִׂ֥יתָ צִּ֖יץ זָהָ֣ב טָה֑וֹר וּ⁠פִתַּחְתָּ֤ עָלָי⁠ו֙ פִּתּוּחֵ֣י חֹתָ֔ם קֹ֖דֶשׁ לַֽ⁠יהוָֽה׃","wĕ⁠ʻáşî֥yţá ẕi֖̇yẕ záhá֣b táh֑wòr ẇ⁠piţȧẖĕţá֤̇ ʻáláy⁠w֙ pi̇ţ̇ẇẖé֣y ẖòţá֔m qò֖deş̌ laֽ⁠yhwáֽh׃"],[28,37,"וְ⁠שַׂמְתָּ֤ אֹת⁠וֹ֙ עַל־פְּתִ֣יל תְּכֵ֔לֶת וְ⁠הָיָ֖ה עַל־הַ⁠מִּצְנָ֑פֶת אֶל־מ֥וּל פְּנֵֽי־הַ⁠מִּצְנֶ֖פֶת יִהְיֶֽה׃","wĕ⁠şâmĕţá֤̇ ʼòţ⁠wò֙ ʻal-pĕ̇ţi֣yl ţĕ̇ké֔leţ wĕ⁠háyá֖h ʻal-ha⁠mi̇ẕĕná֑peţ ʼel-m֥ẇl pĕ̇néֽy-ha⁠mi̇ẕĕne֖peţ yihĕyeֽh׃"],[28,38,"וְ⁠הָיָה֮ עַל־מֵ֣צַח אַהֲרֹן֒ וְ⁠נָשָׂ֨א אַהֲרֹ֜ן אֶת־עֲוֺ֣ן הַ⁠קֳּדָשִׁ֗ים אֲשֶׁ֤ר יַקְדִּ֨ישׁוּ֙ בְּנֵ֣י יִשְׂרָאֵ֔ל לְ⁠כָֽל־מַתְּנֹ֖ת קָדְשֵׁי⁠הֶ֑ם וְ⁠הָיָ֤ה עַל־מִצְח⁠וֹ֙ תָּמִ֔יד לְ⁠רָצ֥וֹן לָ⁠הֶ֖ם לִ⁠פְנֵ֥י יְהוָֽה׃","wĕ⁠háyáh֮ ʻal-mé֣ẕaẖ ʼahàròn֒ wĕ⁠náşá̂֨ʼ ʼahàrò֜n ʼeţ-ʻàwֺ֣n ha⁠qȯdáşǐ֗ym ʼàşě֤r yaqĕdi̇֨yş̌ẇ֙ bĕ̇né֣y yişĕ̂ráʼé֔l lĕ⁠káֽl-maţĕ̇nò֖ţ qádĕşé̌y⁠he֑m wĕ⁠háyá֤h ʻal-miẕĕẖ⁠wò֙ ţá̇mi֔yd lĕ⁠ráẕ֥wòn lá⁠he֖m li⁠pĕné֥y yĕhwáֽh׃"],[28,39,"וְ⁠שִׁבַּצְתָּ֙ הַ⁠כְּתֹ֣נֶת שֵׁ֔שׁ וְ⁠עָשִׂ֖יתָ מִצְנֶ֣פֶת שֵׁ֑שׁ וְ⁠אַבְנֵ֥ט תַּעֲשֶׂ֖ה מַעֲשֵׂ֥ה רֹקֵֽם׃","wĕ⁠şǐbȧẕĕţá̇֙ ha⁠kĕ̇ţò֣neţ şé̌֔ş̌ wĕ⁠ʻáşî֖yţá miẕĕne֣peţ şé֑̌ş̌ wĕ⁠ʼabĕné֥t ţȧʻàşê֖h maʻàşé֥̂h ròqéֽm׃"],[28,40,"וְ⁠לִ⁠בְנֵ֤י אַהֲרֹן֙ תַּעֲשֶׂ֣ה כֻתֳּנֹ֔ת וְ⁠עָשִׂ֥יתָ לָ⁠הֶ֖ם אַבְנֵטִ֑ים וּ⁠מִגְבָּעוֹת֙ תַּעֲשֶׂ֣ה לָ⁠הֶ֔ם לְ⁠כָב֖וֹד וּ⁠לְ⁠תִפְאָֽרֶת׃","wĕ⁠li⁠bĕné֤y ʼahàròn֙ ţȧʻàşê֣h kuţȯnò֔ţ wĕ⁠ʻáşî֥yţá lá⁠he֖m ʼabĕnéti֑ym ẇ⁠migĕbá̇ʻwòţ֙ ţȧʻàşê֣h lá⁠he֔m lĕ⁠káb֖wòd ẇ⁠lĕ⁠ţipĕʼáֽreţ׃"],[28,41,"וְ⁠הִלְבַּשְׁתָּ֤ אֹתָ⁠ם֙ אֶת־אַהֲרֹ֣ן אָחִ֔י⁠ךָ וְ⁠אֶת־בָּנָ֖י⁠ו אִתּ֑⁠וֹ וּ⁠מָשַׁחְתָּ֨ אֹתָ֜⁠ם וּ⁠מִלֵּאתָ֧ אֶת־יָדָ֛⁠ם וְ⁠קִדַּשְׁתָּ֥ אֹתָ֖⁠ם וְ⁠כִהֲנ֥וּ לִֽ⁠י׃","wĕ⁠hilĕbȧşĕ̌ţá֤̇ ʼòţá⁠m֙ ʼeţ-ʼahàrò֣n ʼáẖi֔y⁠ká wĕ⁠ʼeţ-bá̇ná֖y⁠w ʼiţ֑̇⁠wò ẇ⁠máşǎẖĕţá̇֨ ʼòţá֜⁠m ẇ⁠milé̇ʼţá֧ ʼeţ-yádá֛⁠m wĕ⁠qidȧşĕ̌ţá֥̇ ʼòţá֖⁠m wĕ⁠kihàn֥ẇ liֽ⁠y׃"],[28,42,"וַ⁠עֲשֵׂ֤ה לָ⁠הֶם֙ מִכְנְסֵי־בָ֔ד לְ⁠כַסּ֖וֹת בְּשַׂ֣ר עֶרְוָ֑ה מִ⁠מָּתְנַ֥יִם וְ⁠עַד־יְרֵכַ֖יִם יִהְיֽוּ׃","wa⁠ʻàşé֤̂h lá⁠hem֙ mikĕnĕséy-bá֔d lĕ⁠kaṡ֖wòţ bĕ̇şâ֣r ʻerĕwá֑h mi⁠má̇ţĕna֥yim wĕ⁠ʻad-yĕréka֖yim yihĕyֽẇ׃"],[28,43,"וְ⁠הָיוּ֩ עַל־אַהֲרֹ֨ן וְ⁠עַל־בָּנָ֜י⁠ו בְּ⁠בֹאָ֣⁠ם ׀ אֶל־אֹ֣הֶל מוֹעֵ֗ד א֣וֹ בְ⁠גִשְׁתָּ֤⁠ם אֶל־הַ⁠מִּזְבֵּ֨חַ֙ לְ⁠שָׁרֵ֣ת בַּ⁠קֹּ֔דֶשׁ וְ⁠לֹא־יִשְׂא֥וּ עָוֺ֖ן וָ⁠מֵ֑תוּ חֻקַּ֥ת עוֹלָ֛ם ל֖⁠וֹ וּ⁠לְ⁠זַרְע֥⁠וֹ אַחֲרָֽי⁠ו׃ס","wĕ⁠háyẇ֩ ʻal-ʼahàrò֨n wĕ⁠ʻal-bá̇ná֜y⁠w bĕ̇⁠bòʼá֣⁠m ׀ ʼel-ʼò֣hel mwòʻé֗d ʼ֣wò bĕ⁠gişĕ̌ţá֤̇⁠m ʼel-ha⁠mi̇zĕbé̇֨ẖa֙ lĕ⁠şá̌ré֣ţ bȧ⁠qò̇֔deş̌ wĕ⁠lòʼ-yişĕ̂ʼ֥ẇ ʻáwֺ֖n wá⁠mé֑ţẇ ẖuqȧ֥ţ ʻwòlá֛m l֖⁠wò ẇ⁠lĕ⁠zarĕʻ֥⁠wò ʼaẖàráֽy⁠w׃s"],[29,1,"וְ⁠זֶ֨ה הַ⁠דָּבָ֜ר אֲשֶֽׁר־תַּעֲשֶׂ֥ה לָ⁠הֶ֛ם לְ⁠קַדֵּ֥שׁ אֹתָ֖⁠ם לְ⁠כַהֵ֣ן לִ֑⁠י לְ֠קַח פַּ֣ר אֶחָ֧ד בֶּן־בָּקָ֛ר וְ⁠אֵילִ֥ם שְׁנַ֖יִם תְּמִימִֽם׃","wĕ⁠ze֨h ha⁠dá̇bá֜r ʼàşěֽr-ţȧʻàşê֥h lá⁠he֛m lĕ⁠qadé֥̇ş̌ ʼòţá֖⁠m lĕ⁠kahé֣n li֑⁠y lĕ֠qaẖ pȧ֣r ʼeẖá֧d bėn-bá̇qá֛r wĕ⁠ʼéyli֥m şĕ̌na֖yim ţĕ̇miymiֽm׃"],[29,2,"וְ⁠לֶ֣חֶם מַצּ֗וֹת וְ⁠חַלֹּ֤ת מַצֹּת֙ בְּלוּלֹ֣ת בַּ⁠שֶּׁ֔מֶן וּ⁠רְקִיקֵ֥י מַצּ֖וֹת מְשֻׁחִ֣ים בַּ⁠שָּׁ֑מֶן סֹ֥לֶת חִטִּ֖ים תַּעֲשֶׂ֥ה אֹתָֽ⁠ם׃","wĕ⁠le֣ẖem maẕ̇֗wòţ wĕ⁠ẖalò֤̇ţ maẕò̇ţ֙ bĕ̇lẇlò֣ţ bȧ⁠şė̌֔men ẇ⁠rĕqiyqé֥y maẕ֖̇wòţ mĕşǔẖi֣ym bȧ⁠şá֑̇̌men sò֥leţ ẖiti֖̇ym ţȧʻàşê֥h ʼòţáֽ⁠m׃"],[29,3,"וְ⁠נָתַתָּ֤ אוֹתָ⁠ם֙ עַל־סַ֣ל אֶחָ֔ד וְ⁠הִקְרַבְתָּ֥ אֹתָ֖⁠ם בַּ⁠סָּ֑ל וְ⁠אֶ֨ת־הַ⁠פָּ֔ר וְ⁠אֵ֖ת שְׁנֵ֥י הָ⁠אֵילִֽם׃","wĕ⁠náţaţá֤̇ ʼwòţá⁠m֙ ʻal-sa֣l ʼeẖá֔d wĕ⁠hiqĕrabĕţá֥̇ ʼòţá֖⁠m bȧ⁠sá֑̇l wĕ⁠ʼe֨ţ-ha⁠pá̇֔r wĕ⁠ʼé֖ţ şĕ̌né֥y há⁠ʼéyliֽm׃"],[29,4,"וְ⁠אֶת־אַהֲרֹ֤ן וְ⁠אֶת־בָּנָי⁠ו֙ תַּקְרִ֔יב אֶל־פֶּ֖תַח אֹ֣הֶל מוֹעֵ֑ד וְ⁠רָחַצְתָּ֥ אֹתָ֖⁠ם בַּ⁠מָּֽיִם׃","wĕ⁠ʼeţ-ʼahàrò֤n wĕ⁠ʼeţ-bá̇náy⁠w֙ ţȧqĕri֔yb ʼel-pė֖ţaẖ ʼò֣hel mwòʻé֑d wĕ⁠ráẖaẕĕţá֥̇ ʼòţá֖⁠m bȧ⁠máֽ̇yim׃"],[29,5,"וְ⁠לָקַחְתָּ֣ אֶת־הַ⁠בְּגָדִ֗ים וְ⁠הִלְבַּשְׁתָּ֤ אֶֽת־אַהֲרֹן֙ אֶת־הַ⁠כֻּתֹּ֔נֶת וְ⁠אֵת֙ מְעִ֣יל הָ⁠אֵפֹ֔ד וְ⁠אֶת־הָ⁠אֵפֹ֖ד וְ⁠אֶת־הַ⁠חֹ֑שֶׁן וְ⁠אָפַדְתָּ֣ ל֔⁠וֹ בְּ⁠חֵ֖שֶׁב הָ⁠אֵפֹֽד׃","wĕ⁠láqaẖĕţá֣̇ ʼeţ-ha⁠bĕ̇gádi֗ym wĕ⁠hilĕbȧşĕ̌ţá֤̇ ʼeֽţ-ʼahàròn֙ ʼeţ-ha⁠ku̇ţò̇֔neţ wĕ⁠ʼéţ֙ mĕʻi֣yl há⁠ʼépò֔d wĕ⁠ʼeţ-há⁠ʼépò֖d wĕ⁠ʼeţ-ha⁠ẖò֑şěn wĕ⁠ʼápadĕţá֣̇ l֔⁠wò bĕ̇⁠ẖé֖şěb há⁠ʼépòֽd׃"],[29,6,"וְ⁠שַׂמְתָּ֥ הַ⁠מִּצְנֶ֖פֶת עַל־רֹאשׁ֑⁠וֹ וְ⁠נָתַתָּ֛ אֶת־נֵ֥זֶר הַ⁠קֹּ֖דֶשׁ עַל־הַ⁠מִּצְנָֽפֶת׃","wĕ⁠şâmĕţá֥̇ ha⁠mi̇ẕĕne֖peţ ʻal-ròʼş֑̌⁠wò wĕ⁠náţaţá֛̇ ʼeţ-né֥zer ha⁠qò֖̇deş̌ ʻal-ha⁠mi̇ẕĕnáֽpeţ׃"],[29,7,"וְ⁠לָֽקַחְתָּ֙ אֶת־שֶׁ֣מֶן הַ⁠מִּשְׁחָ֔ה וְ⁠יָצַקְתָּ֖ עַל־רֹאשׁ֑⁠וֹ וּ⁠מָשַׁחְתָּ֖ אֹתֽ⁠וֹ׃","wĕ⁠láֽqaẖĕţá̇֙ ʼeţ-şě֣men ha⁠mi̇şĕ̌ẖá֔h wĕ⁠yáẕaqĕţá֖̇ ʻal-ròʼş֑̌⁠wò ẇ⁠máşǎẖĕţá֖̇ ʼòţֽ⁠wò׃"],[29,8,"וְ⁠אֶת־בָּנָ֖י⁠ו תַּקְרִ֑יב וְ⁠הִלְבַּשְׁתָּ֖⁠ם כֻּתֳּנֹֽת׃","wĕ⁠ʼeţ-bá̇ná֖y⁠w ţȧqĕri֑yb wĕ⁠hilĕbȧşĕ̌ţá֖̇⁠m ku̇ţȯnòֽţ׃"],[29,9,"וְ⁠חָגַרְתָּ֩ אֹתָ֨⁠ם אַבְנֵ֜ט אַהֲרֹ֣ן וּ⁠בָנָ֗י⁠ו וְ⁠חָבַשְׁתָּ֤ לָ⁠הֶם֙ מִגְבָּעֹ֔ת וְ⁠הָיְתָ֥ה לָ⁠הֶ֛ם כְּהֻנָּ֖ה לְ⁠חֻקַּ֣ת עוֹלָ֑ם וּ⁠מִלֵּאתָ֥ יַֽד־אַהֲרֹ֖ן וְ⁠יַד־בָּנָֽי⁠ו׃","wĕ⁠ẖágarĕţá̇֩ ʼòţá֨⁠m ʼabĕné֜t ʼahàrò֣n ẇ⁠báná֗y⁠w wĕ⁠ẖábaşĕ̌ţá֤̇ lá⁠hem֙ migĕbá̇ʻò֔ţ wĕ⁠háyĕţá֥h lá⁠he֛m kĕ̇huná֖̇h lĕ⁠ẖuqȧ֣ţ ʻwòlá֑m ẇ⁠milé̇ʼţá֥ yֽad-ʼahàrò֖n wĕ⁠yad-bá̇náֽy⁠w׃"],[29,10,"וְ⁠הִקְרַבְתָּ֙ אֶת־הַ⁠פָּ֔ר לִ⁠פְנֵ֖י אֹ֣הֶל מוֹעֵ֑ד וְ⁠סָמַ֨ךְ אַהֲרֹ֧ן וּ⁠בָנָ֛י⁠ו אֶת־יְדֵי⁠הֶ֖ם עַל־רֹ֥אשׁ הַ⁠פָּֽר׃","wĕ⁠hiqĕrabĕţá̇֙ ʼeţ-ha⁠pá̇֔r li⁠pĕné֖y ʼò֣hel mwòʻé֑d wĕ⁠sáma֨kĕ ʼahàrò֧n ẇ⁠báná֛y⁠w ʼeţ-yĕdéy⁠he֖m ʻal-rò֥ʼş̌ ha⁠páֽ̇r׃"],[29,11,"וְ⁠שָׁחַטְתָּ֥ אֶת־הַ⁠פָּ֖ר לִ⁠פְנֵ֣י יְהוָ֑ה פֶּ֖תַח אֹ֥הֶל מוֹעֵֽד׃","wĕ⁠şá̌ẖatĕţá֥̇ ʼeţ-ha⁠pá֖̇r li⁠pĕné֣y yĕhwá֑h pė֖ţaẖ ʼò֥hel mwòʻéֽd׃"],[29,12,"וְ⁠לָֽקַחְתָּ֙ מִ⁠דַּ֣ם הַ⁠פָּ֔ר וְ⁠נָתַתָּ֛ה עַל־קַרְנֹ֥ת הַ⁠מִּזְבֵּ֖חַ בְּ⁠אֶצְבָּעֶ֑⁠ךָ וְ⁠אֶת־כָּל־הַ⁠דָּ֣ם תִּשְׁפֹּ֔ךְ אֶל־יְס֖וֹד הַ⁠מִּזְבֵּֽחַ׃","wĕ⁠láֽqaẖĕţá̇֙ mi⁠dȧ֣m ha⁠pá̇֔r wĕ⁠náţaţá֛̇h ʻal-qarĕnò֥ţ ha⁠mi̇zĕbé֖̇ẖa bĕ̇⁠ʼeẕĕbá̇ʻe֑⁠ká wĕ⁠ʼeţ-ká̇l-ha⁠dá֣̇m ţi̇şĕ̌pò̇֔kĕ ʼel-yĕs֖wòd ha⁠mi̇zĕbéֽ̇ẖa׃"],[29,13,"וְ⁠לָֽקַחְתָּ֗ אֶֽת־כָּל־הַ⁠חֵלֶב֮ הַֽ⁠מְכַסֶּ֣ה אֶת־הַ⁠קֶּרֶב֒ וְ⁠אֵ֗ת הַ⁠יֹּתֶ֨רֶת֙ עַל־הַ⁠כָּבֵ֔ד וְ⁠אֵת֙ שְׁתֵּ֣י הַ⁠כְּלָיֹ֔ת וְ⁠אֶת־הַ⁠חֵ֖לֶב אֲשֶׁ֣ר עֲלֵי⁠הֶ֑ן וְ⁠הִקְטַרְתָּ֖ הַ⁠מִּזְבֵּֽחָ⁠ה׃","wĕ⁠láֽqaẖĕţá̇֗ ʼeֽţ-ká̇l-ha⁠ẖéleb֮ haֽ⁠mĕkasė֣h ʼeţ-ha⁠qėreb֒ wĕ⁠ʼé֗ţ ha⁠yò̇ţe֨reţ֙ ʻal-ha⁠ká̇bé֔d wĕ⁠ʼéţ֙ şĕ̌ţé֣̇y ha⁠kĕ̇láyò֔ţ wĕ⁠ʼeţ-ha⁠ẖé֖leb ʼàşě֣r ʻàléy⁠he֑n wĕ⁠hiqĕtarĕţá֖̇ ha⁠mi̇zĕbéֽ̇ẖá⁠h׃"],[29,14,"וְ⁠אֶת־בְּשַׂ֤ר הַ⁠פָּר֙ וְ⁠אֶת־עֹר֣⁠וֹ וְ⁠אֶת־פִּרְשׁ֔⁠וֹ תִּשְׂרֹ֣ף בָּ⁠אֵ֔שׁ מִ⁠ח֖וּץ לַֽ⁠מַּחֲנֶ֑ה חַטָּ֖את הֽוּא׃","wĕ⁠ʼeţ-bĕ̇şâ֤r ha⁠pá̇r֙ wĕ⁠ʼeţ-ʻòr֣⁠wò wĕ⁠ʼeţ-pi̇rĕş̌֔⁠wò ţi̇şĕ̂rò֣p bá̇⁠ʼé֔ş̌ mi⁠ẖ֖ẇẕ laֽ⁠mȧẖàne֑h ẖatá֖̇ʼţ hֽẇʼ׃"],[29,15,"וְ⁠אֶת־הָ⁠אַ֥יִל הָ⁠אֶחָ֖ד תִּקָּ֑ח וְ⁠סָ֨מְכ֜וּ אַהֲרֹ֧ן וּ⁠בָנָ֛י⁠ו אֶת־יְדֵי⁠הֶ֖ם עַל־רֹ֥אשׁ הָ⁠אָֽיִל׃","wĕ⁠ʼeţ-há⁠ʼa֥yil há⁠ʼeẖá֖d ţi̇qá֑̇ẖ wĕ⁠sá֨mĕk֜ẇ ʼahàrò֧n ẇ⁠báná֛y⁠w ʼeţ-yĕdéy⁠he֖m ʻal-rò֥ʼş̌ há⁠ʼáֽyil׃"],[29,16,"וְ⁠שָׁחַטְתָּ֖ אֶת־הָ⁠אָ֑יִל וְ⁠לָֽקַחְתָּ֙ אֶת־דָּמ֔⁠וֹ וְ⁠זָרַקְתָּ֥ עַל־הַ⁠מִּזְבֵּ֖חַ סָבִֽיב׃","wĕ⁠şá̌ẖatĕţá֖̇ ʼeţ-há⁠ʼá֑yil wĕ⁠láֽqaẖĕţá̇֙ ʼeţ-dá̇m֔⁠wò wĕ⁠záraqĕţá֥̇ ʻal-ha⁠mi̇zĕbé֖̇ẖa sábiֽyb׃"],[29,17,"וְ⁠אֶ֨ת־הָ⁠אַ֔יִל תְּנַתֵּ֖חַ לִ⁠נְתָחָ֑י⁠ו וְ⁠רָחַצְתָּ֤ קִרְבּ⁠וֹ֙ וּ⁠כְרָעָ֔י⁠ו וְ⁠נָתַתָּ֥ עַל־נְתָחָ֖י⁠ו וְ⁠עַל־רֹאשֽׁ⁠וֹ׃","wĕ⁠ʼe֨ţ-há⁠ʼa֔yil ţĕ̇naţé֖̇ẖa li⁠nĕţáẖá֑y⁠w wĕ⁠ráẖaẕĕţá֤̇ qirĕḃ⁠wò֙ ẇ⁠kĕráʻá֔y⁠w wĕ⁠náţaţá֥̇ ʻal-nĕţáẖá֖y⁠w wĕ⁠ʻal-ròʼşֽ̌⁠wò׃"],[29,18,"וְ⁠הִקְטַרְתָּ֤ אֶת־כָּל־הָ⁠אַ֨יִל֙ הַ⁠מִּזְבֵּ֔חָ⁠ה עֹלָ֥ה ה֖וּא לַֽ⁠יהוָ֑ה רֵ֣יחַ נִיח֔וֹחַ אִשֶּׁ֥ה לַ⁠יהוָ֖ה הֽוּא׃","wĕ⁠hiqĕtarĕţá֤̇ ʼeţ-ká̇l-há⁠ʼa֨yil֙ ha⁠mi̇zĕbé̇֔ẖá⁠h ʻòlá֥h h֖ẇʼ laֽ⁠yhwá֑h ré֣yẖa niyẖ֔wòẖa ʼişė֥̌h la⁠yhwá֖h hֽẇʼ׃"],[29,19,"וְ⁠לָ֣קַחְתָּ֔ אֵ֖ת הָ⁠אַ֣יִל הַ⁠שֵּׁנִ֑י וְ⁠סָמַ֨ךְ אַהֲרֹ֧ן וּ⁠בָנָ֛י⁠ו אֶת־יְדֵי⁠הֶ֖ם עַל־רֹ֥אשׁ הָ⁠אָֽיִל׃","wĕ⁠lá֣qaẖĕţá̇֔ ʼé֖ţ há⁠ʼa֣yil ha⁠şé̇̌ni֑y wĕ⁠sáma֨kĕ ʼahàrò֧n ẇ⁠báná֛y⁠w ʼeţ-yĕdéy⁠he֖m ʻal-rò֥ʼş̌ há⁠ʼáֽyil׃"],[29,20,"וְ⁠שָׁחַטְתָּ֣ אֶת־הָ⁠אַ֗יִל וְ⁠לָקַחְתָּ֤ מִ⁠דָּמ⁠וֹ֙ וְ⁠נָֽתַתָּ֡ה עַל־תְּנוּךְ֩ אֹ֨זֶן אַהֲרֹ֜ן וְ⁠עַל־תְּנ֨וּךְ אֹ֤זֶן בָּנָי⁠ו֙ הַ⁠יְמָנִ֔ית וְ⁠עַל־בֹּ֤הֶן יָדָ⁠ם֙ הַ⁠יְמָנִ֔ית וְ⁠עַל־בֹּ֥הֶן רַגְלָ֖⁠ם הַ⁠יְמָנִ֑ית וְ⁠זָרַקְתָּ֧ אֶת־הַ⁠דָּ֛ם עַל־הַ⁠מִּזְבֵּ֖חַ סָבִֽיב׃","wĕ⁠şá̌ẖatĕţá֣̇ ʼeţ-há⁠ʼa֗yil wĕ⁠láqaẖĕţá֤̇ mi⁠dá̇m⁠wò֙ wĕ⁠náֽţaţá̇֡h ʻal-ţĕ̇nẇkĕ֩ ʼò֨zen ʼahàrò֜n wĕ⁠ʻal-ţĕ̇n֨ẇkĕ ʼò֤zen bá̇náy⁠w֙ ha⁠yĕmáni֔yţ wĕ⁠ʻal-bò֤̇hen yádá⁠m֙ ha⁠yĕmáni֔yţ wĕ⁠ʻal-bò֥̇hen ragĕlá֖⁠m ha⁠yĕmáni֑yţ wĕ⁠záraqĕţá֧̇ ʼeţ-ha⁠dá֛̇m ʻal-ha⁠mi̇zĕbé֖̇ẖa sábiֽyb׃"],[29,21,"וְ⁠לָקַחְתָּ֞ מִן־הַ⁠דָּ֨ם אֲשֶׁ֥ר עַֽל־הַ⁠מִּזְבֵּחַ֮ וּ⁠מִ⁠שֶּׁ֣מֶן הַ⁠מִּשְׁחָה֒ וְ⁠הִזֵּיתָ֤ עַֽל־אַהֲרֹן֙ וְ⁠עַל־בְּגָדָ֔י⁠ו וְ⁠עַל־בָּנָ֛י⁠ו וְ⁠עַל־בִּגְדֵ֥י בָנָ֖י⁠ו אִתּ֑⁠וֹ וְ⁠קָדַ֥שׁ הוּא֙ וּ⁠בְגָדָ֔י⁠ו וּ⁠בָנָ֛י⁠ו וּ⁠בִגְדֵ֥י בָנָ֖י⁠ו אִתּֽ⁠וֹ׃","wĕ⁠láqaẖĕţá̇֞ min-ha⁠dá̇֨m ʼàşě֥r ʻaֽl-ha⁠mi̇zĕbé̇ẖa֮ ẇ⁠mi⁠şė֣̌men ha⁠mi̇şĕ̌ẖáh֒ wĕ⁠hizé̇yţá֤ ʻaֽl-ʼahàròn֙ wĕ⁠ʻal-bĕ̇gádá֔y⁠w wĕ⁠ʻal-bá̇ná֛y⁠w wĕ⁠ʻal-bi̇gĕdé֥y báná֖y⁠w ʼiţ֑̇⁠wò wĕ⁠qáda֥ş̌ hẇʼ֙ ẇ⁠bĕgádá֔y⁠w ẇ⁠báná֛y⁠w ẇ⁠bigĕdé֥y báná֖y⁠w ʼiţֽ̇⁠wò׃"],[29,22,"וְ⁠לָקַחְתָּ֣ מִן־הָ֠⁠אַיִל הַ⁠חֵ֨לֶב וְ⁠הָֽ⁠אַלְיָ֜ה וְ⁠אֶת־הַ⁠חֵ֣לֶב ׀ הַֽ⁠מְכַסֶּ֣ה אֶת־הַ⁠קֶּ֗רֶב וְ⁠אֵ֨ת יֹתֶ֤רֶת הַ⁠כָּבֵד֙ וְ⁠אֵ֣ת ׀ שְׁתֵּ֣י הַ⁠כְּלָיֹ֗ת וְ⁠אֶת־הַ⁠חֵ֨לֶב֙ אֲשֶׁ֣ר עֲלֵ⁠הֶ֔ן וְ⁠אֵ֖ת שׁ֣וֹק הַ⁠יָּמִ֑ין כִּ֛י אֵ֥יל מִלֻּאִ֖ים הֽוּא׃","wĕ⁠láqaẖĕţá֣̇ min-há֠⁠ʼayil ha⁠ẖé֨leb wĕ⁠háֽ⁠ʼalĕyá֜h wĕ⁠ʼeţ-ha⁠ẖé֣leb ׀ haֽ⁠mĕkasė֣h ʼeţ-ha⁠qė֗reb wĕ⁠ʼé֨ţ yòţe֤reţ ha⁠ká̇béd֙ wĕ⁠ʼé֣ţ ׀ şĕ̌ţé֣̇y ha⁠kĕ̇láyò֗ţ wĕ⁠ʼeţ-ha⁠ẖé֨leb֙ ʼàşě֣r ʻàlé⁠he֔n wĕ⁠ʼé֖ţ ş֣̌wòq ha⁠yá̇mi֑yn ki֛̇y ʼé֥yl milu̇ʼi֖ym hֽẇʼ׃"],[29,23,"וְ⁠כִכַּ֨ר לֶ֜חֶם אַחַ֗ת וַֽ⁠חַלַּ֨ת לֶ֥חֶם שֶׁ֛מֶן אַחַ֖ת וְ⁠רָקִ֣יק אֶחָ֑ד מִ⁠סַּל֙ הַ⁠מַּצּ֔וֹת אֲשֶׁ֖ר לִ⁠פְנֵ֥י יְהוָֽה׃","wĕ⁠kikȧ֨r le֜ẖem ʼaẖa֗ţ waֽ⁠ẖalȧ֨ţ le֥ẖem şě֛men ʼaẖa֖ţ wĕ⁠ráqi֣yq ʼeẖá֑d mi⁠sȧl֙ ha⁠mȧẕ̇֔wòţ ʼàşě֖r li⁠pĕné֥y yĕhwáֽh׃"],[29,24,"וְ⁠שַׂמְתָּ֣ הַ⁠כֹּ֔ל עַ֚ל כַּפֵּ֣י אַהֲרֹ֔ן וְ⁠עַ֖ל כַּפֵּ֣י בָנָ֑י⁠ו וְ⁠הֵנַפְתָּ֥ אֹתָ֛⁠ם תְּנוּפָ֖ה לִ⁠פְנֵ֥י יְהוָֽה׃","wĕ⁠şâmĕţá֣̇ ha⁠kò̇֔l ʻa֚l kȧpé֣̇y ʼahàrò֔n wĕ⁠ʻa֖l kȧpé֣̇y báná֑y⁠w wĕ⁠hénapĕţá֥̇ ʼòţá֛⁠m ţĕ̇nẇpá֖h li⁠pĕné֥y yĕhwáֽh׃"],[29,25,"וְ⁠לָקַחְתָּ֤ אֹתָ⁠ם֙ מִ⁠יָּדָ֔⁠ם וְ⁠הִקְטַרְתָּ֥ הַ⁠מִּזְבֵּ֖חָ⁠ה עַל־הָ⁠עֹלָ֑ה לְ⁠רֵ֤יחַ נִיח֨וֹחַ֙ לִ⁠פְנֵ֣י יְהוָ֔ה אִשֶּׁ֥ה ה֖וּא לַ⁠יהוָֽה׃","wĕ⁠láqaẖĕţá֤̇ ʼòţá⁠m֙ mi⁠yá̇dá֔⁠m wĕ⁠hiqĕtarĕţá֥̇ ha⁠mi̇zĕbé֖̇ẖá⁠h ʻal-há⁠ʻòlá֑h lĕ⁠ré֤yẖa niyẖ֨wòẖa֙ li⁠pĕné֣y yĕhwá֔h ʼişė֥̌h h֖ẇʼ la⁠yhwáֽh׃"],[29,26,"וְ⁠לָקַחְתָּ֣ אֶת־הֶֽ⁠חָזֶ֗ה מֵ⁠אֵ֤יל הַ⁠מִּלֻּאִים֙ אֲשֶׁ֣ר לְ⁠אַהֲרֹ֔ן וְ⁠הֵנַפְתָּ֥ אֹת֛⁠וֹ תְּנוּפָ֖ה לִ⁠פְנֵ֣י יְהוָ֑ה וְ⁠הָיָ֥ה לְ⁠ךָ֖ לְ⁠מָנָֽה׃","wĕ⁠láqaẖĕţá֣̇ ʼeţ-heֽ⁠ẖáze֗h mé⁠ʼé֤yl ha⁠mi̇lu̇ʼiym֙ ʼàşě֣r lĕ⁠ʼahàrò֔n wĕ⁠hénapĕţá֥̇ ʼòţ֛⁠wò ţĕ̇nẇpá֖h li⁠pĕné֣y yĕhwá֑h wĕ⁠háyá֥h lĕ⁠ká֖ lĕ⁠mánáֽh׃"],[29,27,"וְ⁠קִדַּשְׁתָּ֞ אֵ֣ת ׀ חֲזֵ֣ה הַ⁠תְּנוּפָ֗ה וְ⁠אֵת֙ שׁ֣וֹק הַ⁠תְּרוּמָ֔ה אֲשֶׁ֥ר הוּנַ֖ף וַ⁠אֲשֶׁ֣ר הוּרָ֑ם מֵ⁠אֵיל֙ הַ⁠מִּלֻּאִ֔ים מֵ⁠אֲשֶׁ֥ר לְ⁠אַהֲרֹ֖ן וּ⁠מֵ⁠אֲשֶׁ֥ר לְ⁠בָנָֽי⁠ו׃","wĕ⁠qidȧşĕ̌ţá̇֞ ʼé֣ţ ׀ ẖàzé֣h ha⁠ţĕ̇nẇpá֗h wĕ⁠ʼéţ֙ ş֣̌wòq ha⁠ţĕ̇rẇmá֔h ʼàşě֥r hẇna֖p wa⁠ʼàşě֣r hẇrá֑m mé⁠ʼéyl֙ ha⁠mi̇lu̇ʼi֔ym mé⁠ʼàşě֥r lĕ⁠ʼahàrò֖n ẇ⁠mé⁠ʼàşě֥r lĕ⁠bánáֽy⁠w׃"],[29,28,"וְ⁠הָיָה֩ לְ⁠אַהֲרֹ֨ן וּ⁠לְ⁠בָנָ֜י⁠ו לְ⁠חָק־עוֹלָ֗ם מֵ⁠אֵת֙ בְּנֵ֣י יִשְׂרָאֵ֔ל כִּ֥י תְרוּמָ֖ה ה֑וּא וּ⁠תְרוּמָ֞ה יִהְיֶ֨ה מֵ⁠אֵ֤ת בְּנֵֽי־יִשְׂרָאֵל֙ מִ⁠זִּבְחֵ֣י שַׁלְמֵי⁠הֶ֔ם תְּרוּמָתָ֖⁠ם לַ⁠יהוָֽה׃","wĕ⁠háyáh֩ lĕ⁠ʼahàrò֨n ẇ⁠lĕ⁠báná֜y⁠w lĕ⁠ẖáq-ʻwòlá֗m mé⁠ʼéţ֙ bĕ̇né֣y yişĕ̂ráʼé֔l ki֥̇y ţĕrẇmá֖h h֑ẇʼ ẇ⁠ţĕrẇmá֞h yihĕye֨h mé⁠ʼé֤ţ bĕ̇néֽy-yişĕ̂ráʼél֙ mi⁠zi̇bĕẖé֣y şǎlĕméy⁠he֔m ţĕ̇rẇmáţá֖⁠m la⁠yhwáֽh׃"],[29,29,"וּ⁠בִגְדֵ֤י הַ⁠קֹּ֨דֶשׁ֙ אֲשֶׁ֣ר לְ⁠אַהֲרֹ֔ן יִהְי֥וּ לְ⁠בָנָ֖י⁠ו אַחֲרָ֑י⁠ו לְ⁠מָשְׁחָ֣ה בָ⁠הֶ֔ם וּ⁠לְ⁠מַלֵּא־בָ֖⁠ם אֶת־יָדָֽ⁠ם׃","ẇ⁠bigĕdé֤y ha⁠qò̇֨deş̌֙ ʼàşě֣r lĕ⁠ʼahàrò֔n yihĕy֥ẇ lĕ⁠báná֖y⁠w ʼaẖàrá֑y⁠w lĕ⁠máşĕ̌ẖá֣h bá⁠he֔m ẇ⁠lĕ⁠malé̇ʼ-bá֖⁠m ʼeţ-yádáֽ⁠m׃"],[29,30,"שִׁבְעַ֣ת יָמִ֗ים יִלְבָּשָׁ֧⁠ם הַ⁠כֹּהֵ֛ן תַּחְתָּ֖י⁠ו מִ⁠בָּנָ֑י⁠ו אֲשֶׁ֥ר יָבֹ֛א אֶל־אֹ֥הֶל מוֹעֵ֖ד לְ⁠שָׁרֵ֥ת בַּ⁠קֹּֽדֶשׁ׃","şǐbĕʻa֣ţ yámi֗ym yilĕbá̇şá֧̌⁠m ha⁠kò̇hé֛n ţȧẖĕţá֖̇y⁠w mi⁠bá̇ná֑y⁠w ʼàşě֥r yábò֛ʼ ʼel-ʼò֥hel mwòʻé֖d lĕ⁠şá̌ré֥ţ bȧ⁠qòֽ̇deş̌׃"],[29,31,"וְ⁠אֵ֛ת אֵ֥יל הַ⁠מִּלֻּאִ֖ים תִּקָּ֑ח וּ⁠בִשַּׁלְתָּ֥ אֶת־בְּשָׂר֖⁠וֹ בְּ⁠מָקֹ֥ם קָדֹֽשׁ׃","wĕ⁠ʼé֛ţ ʼé֥yl ha⁠mi̇lu̇ʼi֖ym ţi̇qá֑̇ẖ ẇ⁠bişȧ̌lĕţá֥̇ ʼeţ-bĕ̇şá̂r֖⁠wò bĕ̇⁠máqò֥m qádòֽş̌׃"],[29,32,"וְ⁠אָכַ֨ל אַהֲרֹ֤ן וּ⁠בָנָי⁠ו֙ אֶת־בְּשַׂ֣ר הָ⁠אַ֔יִל וְ⁠אֶת־הַ⁠לֶּ֖חֶם אֲשֶׁ֣ר בַּ⁠סָּ֑ל פֶּ֖תַח אֹ֥הֶל מוֹעֵֽד׃","wĕ⁠ʼáka֨l ʼahàrò֤n ẇ⁠bánáy⁠w֙ ʼeţ-bĕ̇şâ֣r há⁠ʼa֔yil wĕ⁠ʼeţ-ha⁠lė֖ẖem ʼàşě֣r bȧ⁠sá֑̇l pė֖ţaẖ ʼò֥hel mwòʻéֽd׃"],[29,33,"וְ⁠אָכְל֤וּ אֹתָ⁠ם֙ אֲשֶׁ֣ר כֻּפַּ֣ר בָּ⁠הֶ֔ם לְ⁠מַלֵּ֥א אֶת־יָדָ֖⁠ם לְ⁠קַדֵּ֣שׁ אֹתָ֑⁠ם וְ⁠זָ֥ר לֹא־יֹאכַ֖ל כִּי־קֹ֥דֶשׁ הֵֽם׃","wĕ⁠ʼákĕl֤ẇ ʼòţá⁠m֙ ʼàşě֣r ku̇pȧ֣r bá̇⁠he֔m lĕ⁠malé֥̇ʼ ʼeţ-yádá֖⁠m lĕ⁠qadé֣̇ş̌ ʼòţá֑⁠m wĕ⁠zá֥r lòʼ-yòʼka֖l ki̇y-qò֥deş̌ héֽm׃"],[29,34,"וְֽ⁠אִם־יִוָּתֵ֞ר מִ⁠בְּשַׂ֧ר הַ⁠מִּלֻּאִ֛ים וּ⁠מִן־הַ⁠לֶּ֖חֶם עַד־הַ⁠בֹּ֑קֶר וְ⁠שָׂרַפְתָּ֤ אֶת־הַ⁠נּוֹתָר֙ בָּ⁠אֵ֔שׁ לֹ֥א יֵאָכֵ֖ל כִּי־קֹ֥דֶשׁ הֽוּא׃","wĕֽ⁠ʼim-yiwá̇ţé֞r mi⁠bĕ̇şâ֧r ha⁠mi̇lu̇ʼi֛ym ẇ⁠min-ha⁠lė֖ẖem ʻad-ha⁠bò֑̇qer wĕ⁠şá̂rapĕţá֤̇ ʼeţ-ha⁠ṅwòţár֙ bá̇⁠ʼé֔ş̌ lò֥ʼ yéʼáké֖l ki̇y-qò֥deş̌ hֽẇʼ׃"],[29,35,"וְ⁠עָשִׂ֜יתָ לְ⁠אַהֲרֹ֤ן וּ⁠לְ⁠בָנָי⁠ו֙ כָּ֔כָה כְּ⁠כֹ֥ל אֲשֶׁר־צִוִּ֖יתִי אֹתָ֑⁠כָה שִׁבְעַ֥ת יָמִ֖ים תְּמַלֵּ֥א יָדָֽ⁠ם׃","wĕ⁠ʻáşî֜yţá lĕ⁠ʼahàrò֤n ẇ⁠lĕ⁠bánáy⁠w֙ ká̇֔káh kĕ̇⁠kò֥l ʼàşěr-ẕiwi֖̇yţiy ʼòţá֑⁠káh şǐbĕʻa֥ţ yámi֖ym ţĕ̇malé֥̇ʼ yádáֽ⁠m׃"],[29,36,"וּ⁠פַ֨ר חַטָּ֜את תַּעֲשֶׂ֤ה לַ⁠יּוֹם֙ עַל־הַ⁠כִּפֻּרִ֔ים וְ⁠חִטֵּאתָ֙ עַל־הַ⁠מִּזְבֵּ֔חַ בְּ⁠כַפֶּרְ⁠ךָ֖ עָלָ֑י⁠ו וּ⁠מָֽשַׁחְתָּ֥ אֹת֖⁠וֹ לְ⁠קַדְּשֽׁ⁠וֹ׃","ẇ⁠pa֨r ẖatá̇֜ʼţ ţȧʻàşê֤h la⁠ẏwòm֙ ʻal-ha⁠ki̇pu̇ri֔ym wĕ⁠ẖité̇ʼţá֙ ʻal-ha⁠mi̇zĕbé̇֔ẖa bĕ̇⁠kapėrĕ⁠ká֖ ʻálá֑y⁠w ẇ⁠máֽşǎẖĕţá֥̇ ʼòţ֖⁠wò lĕ⁠qadĕ̇şֽ̌⁠wò׃"],[29,37,"שִׁבְעַ֣ת יָמִ֗ים תְּכַפֵּר֙ עַל־הַ⁠מִּזְבֵּ֔חַ וְ⁠קִדַּשְׁתָּ֖ אֹת֑⁠וֹ וְ⁠הָיָ֤ה הַ⁠מִּזְבֵּ֨חַ֙ קֹ֣דֶשׁ קָֽדָשִׁ֔ים כָּל־הַ⁠נֹּגֵ֥עַ בַּ⁠מִּזְבֵּ֖חַ יִקְדָּֽשׁ׃ס","şǐbĕʻa֣ţ yámi֗ym ţĕ̇kapé̇r֙ ʻal-ha⁠mi̇zĕbé̇֔ẖa wĕ⁠qidȧşĕ̌ţá֖̇ ʼòţ֑⁠wò wĕ⁠háyá֤h ha⁠mi̇zĕbé̇֨ẖa֙ qò֣deş̌ qáֽdáşǐ֔ym ká̇l-ha⁠nò̇gé֥ʻa bȧ⁠mi̇zĕbé֖̇ẖa yiqĕdáֽ̇ş̌׃s"],[29,38,"וְ⁠זֶ֕ה אֲשֶׁ֥ר תַּעֲשֶׂ֖ה עַל־הַ⁠מִּזְבֵּ֑חַ כְּבָשִׂ֧ים בְּנֵֽי־שָׁנָ֛ה שְׁנַ֥יִם לַ⁠יּ֖וֹם תָּמִֽיד׃","wĕ⁠ze֕h ʼàşě֥r ţȧʻàşê֖h ʻal-ha⁠mi̇zĕbé֑̇ẖa kĕ̇báşî֧ym bĕ̇néֽy-şá̌ná֛h şĕ̌na֥yim la⁠ẏ֖wòm ţá̇miֽyd׃"],[29,39,"אֶת־הַ⁠כֶּ֥בֶשׂ הָ⁠אֶחָ֖ד תַּעֲשֶׂ֣ה בַ⁠בֹּ֑קֶר וְ⁠אֵת֙ הַ⁠כֶּ֣בֶשׂ הַ⁠שֵּׁנִ֔י תַּעֲשֶׂ֖ה בֵּ֥ין הָ⁠עַרְבָּֽיִם׃","ʼeţ-ha⁠kė֥beş̂ há⁠ʼeẖá֖d ţȧʻàşê֣h ba⁠bò֑̇qer wĕ⁠ʼéţ֙ ha⁠kė֣beş̂ ha⁠şé̇̌ni֔y ţȧʻàşê֖h bé֥̇yn há⁠ʻarĕbáֽ̇yim׃"],[29,40,"וְ⁠עִשָּׂרֹ֨ן סֹ֜לֶת בָּל֨וּל בְּ⁠שֶׁ֤מֶן כָּתִית֙ רֶ֣בַע הַ⁠הִ֔ין וְ⁠נֵ֕סֶךְ רְבִעִ֥ית הַ⁠הִ֖ין יָ֑יִן לַ⁠כֶּ֖בֶשׂ הָ⁠אֶחָֽד׃","wĕ⁠ʻişá̇̂rò֨n sò֜leţ bá̇l֨ẇl bĕ̇⁠şě֤men ká̇ţiyţ֙ re֣baʻ ha⁠hi֔yn wĕ⁠né֕sekĕ rĕbiʻi֥yţ ha⁠hi֖yn yá֑yin la⁠kė֖beş̂ há⁠ʼeẖáֽd׃"],[29,41,"וְ⁠אֵת֙ הַ⁠כֶּ֣בֶשׂ הַ⁠שֵּׁנִ֔י תַּעֲשֶׂ֖ה בֵּ֣ין הָ⁠עַרְבָּ֑יִם כְּ⁠מִנְחַ֨ת הַ⁠בֹּ֤קֶר וּ⁠כְ⁠נִסְכָּ⁠הּ֙ תַּֽעֲשֶׂה־לָּ֔⁠הּ לְ⁠רֵ֣יחַ נִיחֹ֔חַ אִשֶּׁ֖ה לַ⁠יהוָֽה׃","wĕ⁠ʼéţ֙ ha⁠kė֣beş̂ ha⁠şé̇̌ni֔y ţȧʻàşê֖h bé֣̇yn há⁠ʻarĕbá֑̇yim kĕ̇⁠minĕẖa֨ţ ha⁠bò֤̇qer ẇ⁠kĕ⁠nisĕká̇⁠ḣ֙ ţֽ̇aʻàşêh-lá̇֔⁠ḣ lĕ⁠ré֣yẖa niyẖò֔ẖa ʼişė֖̌h la⁠yhwáֽh׃"],[29,42,"עֹלַ֤ת תָּמִיד֙ לְ⁠דֹרֹ֣תֵי⁠כֶ֔ם פֶּ֥תַח אֹֽהֶל־מוֹעֵ֖ד לִ⁠פְנֵ֣י יְהוָ֑ה אֲשֶׁ֨ר אִוָּעֵ֤ד לָ⁠כֶם֙ שָׁ֔מָּ⁠ה לְ⁠דַבֵּ֥ר אֵלֶ֖י⁠ךָ שָֽׁם׃","ʻòla֤ţ ţá̇miyd֙ lĕ⁠dòrò֣ţéy⁠ke֔m pė֥ţaẖ ʼòֽhel-mwòʻé֖d li⁠pĕné֣y yĕhwá֑h ʼàşě֨r ʼiwá̇ʻé֤d lá⁠kem֙ şá̌֔má̇⁠h lĕ⁠dabé֥̇r ʼéle֖y⁠ká şáֽ̌m׃"],[29,43,"וְ⁠נֹעַדְתִּ֥י שָׁ֖מָּ⁠ה לִ⁠בְנֵ֣י יִשְׂרָאֵ֑ל וְ⁠נִקְדַּ֖שׁ בִּ⁠כְבֹדִֽ⁠י׃","wĕ⁠nòʻadĕţi֥̇y şá֖̌má̇⁠h li⁠bĕné֣y yişĕ̂ráʼé֑l wĕ⁠niqĕdȧ֖ş̌ bi̇⁠kĕbòdiֽ⁠y׃"],[29,44,"וְ⁠קִדַּשְׁתִּ֛י אֶת־אֹ֥הֶל מוֹעֵ֖ד וְ⁠אֶת־הַ⁠מִּזְבֵּ֑חַ וְ⁠אֶת־אַהֲרֹ֧ן וְ⁠אֶת־בָּנָ֛י⁠ו אֲקַדֵּ֖שׁ לְ⁠כַהֵ֥ן לִֽ⁠י׃","wĕ⁠qidȧşĕ̌ţi֛̇y ʼeţ-ʼò֥hel mwòʻé֖d wĕ⁠ʼeţ-ha⁠mi̇zĕbé֑̇ẖa wĕ⁠ʼeţ-ʼahàrò֧n wĕ⁠ʼeţ-bá̇ná֛y⁠w ʼàqadé֖̇ş̌ lĕ⁠kahé֥n liֽ⁠y׃"],[29,45,"וְ⁠שָׁ֣כַנְתִּ֔י בְּ⁠ת֖וֹךְ בְּנֵ֣י יִשְׂרָאֵ֑ל וְ⁠הָיִ֥יתִי לָ⁠הֶ֖ם לֵ⁠אלֹהִֽים׃","wĕ⁠şá֣̌kanĕţi̇֔y bĕ̇⁠ţ֖wòkĕ bĕ̇né֣y yişĕ̂ráʼé֑l wĕ⁠háyi֥yţiy lá⁠he֖m lé⁠ʼlòhiֽym׃"],[29,46,"וְ⁠יָדְע֗וּ כִּ֣י אֲנִ֤י יְהוָה֙ אֱלֹ֣הֵי⁠הֶ֔ם אֲשֶׁ֨ר הוֹצֵ֧אתִי אֹתָ֛⁠ם מֵ⁠אֶ֥רֶץ מִצְרַ֖יִם לְ⁠שָׁכְנִ֣⁠י בְ⁠תוֹכָ֑⁠ם אֲנִ֖י יְהוָ֥ה אֱלֹהֵי⁠הֶֽם׃פ","wĕ⁠yádĕʻ֗ẇ ki֣̇y ʼàni֤y yĕhwáh֙ ʼèlò֣héy⁠he֔m ʼàşě֨r hwòẕé֧ʼţiy ʼòţá֛⁠m mé⁠ʼe֥reẕ miẕĕra֖yim lĕ⁠şá̌kĕni֣⁠y bĕ⁠ţwòká֑⁠m ʼàni֖y yĕhwá֥h ʼèlòhéy⁠heֽm׃p"],[30,1,"וְ⁠עָשִׂ֥יתָ מִזְבֵּ֖חַ מִקְטַ֣ר קְטֹ֑רֶת עֲצֵ֥י שִׁטִּ֖ים תַּעֲשֶׂ֥ה אֹתֽ⁠וֹ׃","wĕ⁠ʻáşî֥yţá mizĕbé֖̇ẖa miqĕta֣r qĕtò֑reţ ʻàẕé֥y şǐti֖̇ym ţȧʻàşê֥h ʼòţֽ⁠wò׃"],[30,2,"אַמָּ֨ה אָרְכּ֜⁠וֹ וְ⁠אַמָּ֤ה רָחְבּ⁠וֹ֙ רָב֣וּעַ יִהְיֶ֔ה וְ⁠אַמָּתַ֖יִם קֹמָת֑⁠וֹ מִמֶּ֖⁠נּוּ קַרְנֹתָֽי⁠ו׃","ʼamá̇֨h ʼárĕk̇֜⁠wò wĕ⁠ʼamá֤̇h ráẖĕḃ⁠wò֙ ráb֣ẇʻa yihĕye֔h wĕ⁠ʼamá̇ţa֖yim qòmáţ֑⁠wò mimė֖⁠ṅẇ qarĕnòţáֽy⁠w׃"],[30,3,"וְ⁠צִפִּיתָ֨ אֹת֜⁠וֹ זָהָ֣ב טָה֗וֹר אֶת־גַּגּ֧⁠וֹ וְ⁠אֶת־קִירֹתָ֛י⁠ו סָבִ֖יב וְ⁠אֶת־קַרְנֹתָ֑י⁠ו וְ⁠עָשִׂ֥יתָ לּ֛⁠וֹ זֵ֥ר זָהָ֖ב סָבִֽיב׃","wĕ⁠ẕipi̇yţá֨ ʼòţ֜⁠wò záhá֣b táh֗wòr ʼeţ-gȧġ֧⁠wò wĕ⁠ʼeţ-qiyròţá֛y⁠w sábi֖yb wĕ⁠ʼeţ-qarĕnòţá֑y⁠w wĕ⁠ʻáşî֥yţá l֛̇⁠wò zé֥r záhá֖b sábiֽyb׃"],[30,4,"וּ⁠שְׁתֵּי֩ טַבְּעֹ֨ת זָהָ֜ב תַּֽעֲשֶׂה־לּ֣⁠וֹ ׀ מִ⁠תַּ֣חַת לְ⁠זֵר֗⁠וֹ עַ֚ל שְׁתֵּ֣י צַלְעֹתָ֔י⁠ו תַּעֲשֶׂ֖ה עַל־שְׁנֵ֣י צִדָּ֑י⁠ו וְ⁠הָיָה֙ לְ⁠בָתִּ֣ים לְ⁠בַדִּ֔ים לָ⁠שֵׂ֥את אֹת֖⁠וֹ בָּ⁠הֵֽמָּה׃","ẇ⁠şĕ̌ţé̇y֩ tabĕ̇ʻò֨ţ záhá֜b ţȧֽʻàşêh-l֣̇⁠wò ׀ mi⁠ţȧ֣ẖaţ lĕ⁠zér֗⁠wò ʻa֚l şĕ̌ţé֣̇y ẕalĕʻòţá֔y⁠w ţȧʻàşê֖h ʻal-şĕ̌né֣y ẕidá֑̇y⁠w wĕ⁠háyáh֙ lĕ⁠báţi֣̇ym lĕ⁠badi̇֔ym lá⁠şé֥̂ʼţ ʼòţ֖⁠wò bá̇⁠héֽmá̇h׃"],[30,5,"וְ⁠עָשִׂ֥יתָ אֶת־הַ⁠בַּדִּ֖ים עֲצֵ֣י שִׁטִּ֑ים וְ⁠צִפִּיתָ֥ אֹתָ֖⁠ם זָהָֽב׃","wĕ⁠ʻáşî֥yţá ʼeţ-ha⁠bȧdi֖̇ym ʻàẕé֣y şǐti֑̇ym wĕ⁠ẕipi̇yţá֥ ʼòţá֖⁠m záháֽb׃"],[30,6,"וְ⁠נָתַתָּ֤ה אֹת⁠וֹ֙ לִ⁠פְנֵ֣י הַ⁠פָּרֹ֔כֶת אֲשֶׁ֖ר עַל־אֲרֹ֣ן הָ⁠עֵדֻ֑ת לִ⁠פְנֵ֣י הַ⁠כַּפֹּ֗רֶת אֲשֶׁר֙ עַל־הָ֣⁠עֵדֻ֔ת אֲשֶׁ֛ר אִוָּעֵ֥ד לְ⁠ךָ֖ שָֽׁמָּ⁠ה׃","wĕ⁠náţaţá֤̇h ʼòţ⁠wò֙ li⁠pĕné֣y ha⁠pá̇rò֔keţ ʼàşě֖r ʻal-ʼàrò֣n há⁠ʻédu֑ţ li⁠pĕné֣y ha⁠kȧpò̇֗reţ ʼàşěr֙ ʻal-há֣⁠ʻédu֔ţ ʼàşě֛r ʼiwá̇ʻé֥d lĕ⁠ká֖ şáֽ̌má̇⁠h׃"],[30,7,"וְ⁠הִקְטִ֥יר עָלָ֛י⁠ו אַהֲרֹ֖ן קְטֹ֣רֶת סַמִּ֑ים בַּ⁠בֹּ֣קֶר בַּ⁠בֹּ֗קֶר בְּ⁠הֵיטִיב֛⁠וֹ אֶת־הַ⁠נֵּרֹ֖ת יַקְטִירֶֽ⁠נָּה׃","wĕ⁠hiqĕti֥yr ʻálá֛y⁠w ʼahàrò֖n qĕtò֣reţ sami֑̇ym bȧ⁠bò֣̇qer bȧ⁠bò̇֗qer bĕ̇⁠héytiyb֛⁠wò ʼeţ-ha⁠né̇rò֖ţ yaqĕtiyreֽ⁠ná̇h׃"],[30,8,"וּ⁠בְ⁠הַעֲלֹ֨ת אַהֲרֹ֧ן אֶת־הַ⁠נֵּרֹ֛ת בֵּ֥ין הָ⁠עֲרְבַּ֖יִם יַקְטִירֶ֑⁠נָּה קְטֹ֧רֶת תָּמִ֛יד לִ⁠פְנֵ֥י יְהוָ֖ה לְ⁠דֹרֹתֵי⁠כֶֽם׃","ẇ⁠bĕ⁠haʻàlò֨ţ ʼahàrò֧n ʼeţ-ha⁠né̇rò֛ţ bé֥̇yn há⁠ʻàrĕbȧ֖yim yaqĕtiyre֑⁠ná̇h qĕtò֧reţ ţá̇mi֛yd li⁠pĕné֥y yĕhwá֖h lĕ⁠dòròţéy⁠keֽm׃"],[30,9,"לֹא־תַעֲל֥וּ עָלָ֛י⁠ו קְטֹ֥רֶת זָרָ֖ה וְ⁠עֹלָ֣ה וּ⁠מִנְחָ֑ה וְ⁠נֵ֕סֶךְ לֹ֥א תִסְּכ֖וּ עָלָֽי⁠ו׃","lòʼ-ţaʻàl֥ẇ ʻálá֛y⁠w qĕtò֥reţ zárá֖h wĕ⁠ʻòlá֣h ẇ⁠minĕẖá֑h wĕ⁠né֕sekĕ lò֥ʼ ţisĕ̇k֖ẇ ʻáláֽy⁠w׃"],[30,10,"וְ⁠כִפֶּ֤ר אַהֲרֹן֙ עַל־קַרְנֹתָ֔י⁠ו אַחַ֖ת בַּ⁠שָּׁנָ֑ה מִ⁠דַּ֞ם חַטַּ֣את הַ⁠כִּפֻּרִ֗ים אַחַ֤ת בַּ⁠שָּׁנָה֙ יְכַפֵּ֤ר עָלָי⁠ו֙ לְ⁠דֹרֹ֣תֵי⁠כֶ֔ם קֹֽדֶשׁ־קָֽדָשִׁ֥ים ה֖וּא לַ⁠יהוָֽה׃פ","wĕ⁠kipė֤r ʼahàròn֙ ʻal-qarĕnòţá֔y⁠w ʼaẖa֖ţ bȧ⁠şá̇̌ná֑h mi⁠dȧ֞m ẖatȧ֣ʼţ ha⁠ki̇pu̇ri֗ym ʼaẖa֤ţ bȧ⁠şá̇̌náh֙ yĕkapé֤̇r ʻáláy⁠w֙ lĕ⁠dòrò֣ţéy⁠ke֔m qòֽdeş̌-qֽádáşǐ֥ym h֖ẇʼ la⁠yhwáֽh׃p"],[30,11,"וַ⁠יְדַבֵּ֥ר יְהוָ֖ה אֶל־מֹשֶׁ֥ה לֵּ⁠אמֹֽר׃","wa⁠yĕdabé֥̇r yĕhwá֖h ʼel-mòşě֥h lé̇⁠ʼmòֽr׃"],[30,12,"כִּ֣י תִשָּׂ֞א אֶת־רֹ֥אשׁ בְּנֵֽי־יִשְׂרָאֵ֘ל לִ⁠פְקֻדֵי⁠הֶם֒ וְ⁠נָ֨תְנ֜וּ אִ֣ישׁ כֹּ֧פֶר נַפְשׁ֛⁠וֹ לַ⁠יהוָ֖ה בִּ⁠פְקֹ֣ד אֹתָ֑⁠ם וְ⁠לֹא־יִהְיֶ֥ה בָ⁠הֶ֛ם נֶ֖גֶף בִּ⁠פְקֹ֥ד אֹתָֽ⁠ם׃","ki֣̇y ţişá̇̂֞ʼ ʼeţ-rò֥ʼş̌ bĕ̇nֽéy-yişĕ̂ráʼé֘l li⁠pĕqudéy⁠hem֒ wĕ⁠ná֨ţĕn֜ẇ ʼi֣yş̌ kò֧̇per napĕş֛̌⁠wò la⁠yhwá֖h bi̇⁠pĕqò֣d ʼòţá֑⁠m wĕ⁠lòʼ-yihĕye֥h bá⁠he֛m ne֖gep bi̇⁠pĕqò֥d ʼòţáֽ⁠m׃"],[30,13,"זֶ֣ה ׀ יִתְּנ֗וּ כָּל־הָ⁠עֹבֵר֙ עַל־הַ⁠פְּקֻדִ֔ים מַחֲצִ֥ית הַ⁠שֶּׁ֖קֶל בְּ⁠שֶׁ֣קֶל הַ⁠קֹּ֑דֶשׁ עֶשְׂרִ֤ים גֵּרָה֙ הַ⁠שֶּׁ֔קֶל מַחֲצִ֣ית הַ⁠שֶּׁ֔קֶל תְּרוּמָ֖ה לַֽ⁠יהוָֽה׃","ze֣h ׀ yiţĕ̇n֗ẇ ká̇l-há⁠ʻòbér֙ ʻal-ha⁠pĕ̇qudi֔ym maẖàẕi֥yţ ha⁠şė֖̌qel bĕ̇⁠şě֣qel ha⁠qò֑̇deş̌ ʻeşĕ̂ri֤ym gé̇ráh֙ ha⁠şė̌֔qel maẖàẕi֣yţ ha⁠şė̌֔qel ţĕ̇rẇmá֖h lֽa⁠yhwáֽh׃"],[30,14,"כֹּ֗ל הָ⁠עֹבֵר֙ עַל־הַ⁠פְּקֻדִ֔ים מִ⁠בֶּ֛ן עֶשְׂרִ֥ים שָׁנָ֖ה וָ⁠מָ֑עְלָ⁠ה יִתֵּ֖ן תְּרוּמַ֥ת יְהוָֽה׃","kò̇֗l há⁠ʻòbér֙ ʻal-ha⁠pĕ̇qudi֔ym mi⁠bė֛n ʻeşĕ̂ri֥ym şá̌ná֖h wá⁠má֑ʻĕlá⁠h yiţé֖̇n ţĕ̇rẇma֥ţ yĕhwáֽh׃"],[30,15,"הֶֽ⁠עָשִׁ֣יר לֹֽא־יַרְבֶּ֗ה וְ⁠הַ⁠דַּל֙ לֹ֣א יַמְעִ֔יט מִֽ⁠מַּחֲצִ֖ית הַ⁠שָּׁ֑קֶל לָ⁠תֵת֙ אֶת־תְּרוּמַ֣ת יְהוָ֔ה לְ⁠כַפֵּ֖ר עַל־נַפְשֹׁתֵי⁠כֶֽם׃","heֽ⁠ʻáşǐ֣yr lòֽʼ-yarĕbė֗h wĕ⁠ha⁠dȧl֙ lò֣ʼ yamĕʻi֔yt miֽ⁠mȧẖàẕi֖yţ ha⁠şá֑̇̌qel lá⁠ţéţ֙ ʼeţ-ţĕ̇rẇma֣ţ yĕhwá֔h lĕ⁠kapé֖̇r ʻal-napĕşò̌ţéy⁠keֽm׃"],[30,16,"וְ⁠לָקַחְתָּ֞ אֶת־כֶּ֣סֶף הַ⁠כִּפֻּרִ֗ים מֵ⁠אֵת֙ בְּנֵ֣י יִשְׂרָאֵ֔ל וְ⁠נָתַתָּ֣ אֹת֔⁠וֹ עַל־עֲבֹדַ֖ת אֹ֣הֶל מוֹעֵ֑ד וְ⁠הָיָה֩ לִ⁠בְנֵ֨י יִשְׂרָאֵ֤ל לְ⁠זִכָּרוֹן֙ לִ⁠פְנֵ֣י יְהוָ֔ה לְ⁠כַפֵּ֖ר עַל־נַפְשֹׁתֵי⁠כֶֽם׃פ","wĕ⁠láqaẖĕţá̇֞ ʼeţ-kė֣sep ha⁠ki̇pu̇ri֗ym mé⁠ʼéţ֙ bĕ̇né֣y yişĕ̂ráʼé֔l wĕ⁠náţaţá֣̇ ʼòţ֔⁠wò ʻal-ʻàbòda֖ţ ʼò֣hel mwòʻé֑d wĕ⁠háyáh֩ li⁠bĕné֨y yişĕ̂ráʼé֤l lĕ⁠ziká̇rwòn֙ li⁠pĕné֣y yĕhwá֔h lĕ⁠kapé֖̇r ʻal-napĕşò̌ţéy⁠keֽm׃p"],[30,17,"וַ⁠יְדַבֵּ֥ר יְהוָ֖ה אֶל־מֹשֶׁ֥ה לֵּ⁠אמֹֽר׃","wa⁠yĕdabé֥̇r yĕhwá֖h ʼel-mòşě֥h lé̇⁠ʼmòֽr׃"],[30,18,"וְ⁠עָשִׂ֜יתָ כִּיּ֥וֹר נְחֹ֛שֶׁת וְ⁠כַנּ֥⁠וֹ נְחֹ֖שֶׁת לְ⁠רָחְצָ֑ה וְ⁠נָתַתָּ֣ אֹת֗⁠וֹ בֵּֽין־אֹ֤הֶל מוֹעֵד֙ וּ⁠בֵ֣ין הַ⁠מִּזְבֵּ֔חַ וְ⁠נָתַתָּ֥ שָׁ֖מָּ⁠ה מָֽיִם׃","wĕ⁠ʻáşî֜yţá ki̇ẏ֥wòr nĕẖò֛şěţ wĕ⁠kaṅ֥⁠wò nĕẖò֖şěţ lĕ⁠ráẖĕẕá֑h wĕ⁠náţaţá֣̇ ʼòţ֗⁠wò béֽ̇yn-ʼò֤hel mwòʻéd֙ ẇ⁠bé֣yn ha⁠mi̇zĕbé̇֔ẖa wĕ⁠náţaţá֥̇ şá֖̌má̇⁠h máֽyim׃"],[30,19,"וְ⁠רָחֲצ֛וּ אַהֲרֹ֥ן וּ⁠בָנָ֖י⁠ו מִמֶּ֑⁠נּוּ אֶת־יְדֵי⁠הֶ֖ם וְ⁠אֶת־רַגְלֵי⁠הֶֽם׃","wĕ⁠ráẖàẕ֛ẇ ʼahàrò֥n ẇ⁠báná֖y⁠w mimė֑⁠ṅẇ ʼeţ-yĕdéy⁠he֖m wĕ⁠ʼeţ-ragĕléy⁠heֽm׃"],[30,20,"בְּ⁠בֹאָ֞⁠ם אֶל־אֹ֧הֶל מוֹעֵ֛ד יִרְחֲצוּ־מַ֖יִם וְ⁠לֹ֣א יָמֻ֑תוּ א֣וֹ בְ⁠גִשְׁתָּ֤⁠ם אֶל־הַ⁠מִּזְבֵּ֨חַ֙ לְ⁠שָׁרֵ֔ת לְ⁠הַקְטִ֥יר אִשֶּׁ֖ה לַֽ⁠יהוָֽה׃","bĕ̇⁠bòʼá֞⁠m ʼel-ʼò֧hel mwòʻé֛d yirĕẖàẕẇ-ma֖yim wĕ⁠lò֣ʼ yámu֑ţẇ ʼ֣wò bĕ⁠gişĕ̌ţá֤̇⁠m ʼel-ha⁠mi̇zĕbé̇֨ẖa֙ lĕ⁠şá̌ré֔ţ lĕ⁠haqĕti֥yr ʼişė֖̌h laֽ⁠yhwáֽh׃"],[30,21,"וְ⁠רָחֲצ֛וּ יְדֵי⁠הֶ֥ם וְ⁠רַגְלֵי⁠הֶ֖ם וְ⁠לֹ֣א יָמֻ֑תוּ וְ⁠הָיְתָ֨ה לָ⁠הֶ֧ם חָק־עוֹלָ֛ם ל֥⁠וֹ וּ⁠לְ⁠זַרְע֖⁠וֹ לְ⁠דֹרֹתָֽ⁠ם׃פ","wĕ⁠ráẖàẕ֛ẇ yĕdéy⁠he֥m wĕ⁠ragĕléy⁠he֖m wĕ⁠lò֣ʼ yámu֑ţẇ wĕ⁠háyĕţá֨h lá⁠he֧m ẖáq-ʻwòlá֛m l֥⁠wò ẇ⁠lĕ⁠zarĕʻ֖⁠wò lĕ⁠dòròţáֽ⁠m׃p"],[30,22,"וַ⁠יְדַבֵּ֥ר יְהוָ֖ה אֶל־מֹשֶׁ֥ה לֵּ⁠אמֹֽר׃","wa⁠yĕdabé֥̇r yĕhwá֖h ʼel-mòşě֥h lé̇⁠ʼmòֽr׃"],[30,23,"וְ⁠אַתָּ֣ה קַח־לְ⁠ךָ֮ בְּשָׂמִ֣ים רֹאשׁ֒ מָר־דְּרוֹר֙ חֲמֵ֣שׁ מֵא֔וֹת וְ⁠קִנְּמָן־בֶּ֥שֶׂם מַחֲצִית֖⁠וֹ חֲמִשִּׁ֣ים וּ⁠מָאתָ֑יִם וּ⁠קְנֵה־בֹ֖שֶׂם חֲמִשִּׁ֥ים וּ⁠מָאתָֽיִם׃","wĕ⁠ʼaţá֣̇h qaẖ-lĕ⁠ká֮ bĕ̇şá̂mi֣ym ròʼş̌֒ már-dĕ̇rwòr֙ ẖàmé֣ş̌ méʼ֔wòţ wĕ⁠qinĕ̇mán-bė֥şêm maẖàẕiyţ֖⁠wò ẖàmişi֣̇̌ym ẇ⁠máʼţá֑yim ẇ⁠qĕnéh-bò֖şêm ẖàmişi֥̇̌ym ẇ⁠máʼţáֽyim׃"],[30,24,"וְ⁠קִדָּ֕ה חֲמֵ֥שׁ מֵא֖וֹת בְּ⁠שֶׁ֣קֶל הַ⁠קֹּ֑דֶשׁ וְ⁠שֶׁ֥מֶן זַ֖יִת הִֽין׃","wĕ⁠qidá̇֕h ẖàmé֥ş̌ méʼ֖wòţ bĕ̇⁠şě֣qel ha⁠qò֑̇deş̌ wĕ⁠şě֥men za֖yiţ hiֽyn׃"],[30,25,"וְ⁠עָשִׂ֣יתָ אֹת֗⁠וֹ שֶׁ֚מֶן מִשְׁחַת־קֹ֔דֶשׁ רֹ֥קַח מִרְקַ֖חַת מַעֲשֵׂ֣ה רֹקֵ֑חַ שֶׁ֥מֶן מִשְׁחַת־קֹ֖דֶשׁ יִהְיֶֽה׃","wĕ⁠ʻáşî֣yţá ʼòţ֗⁠wò şě֚men mişĕ̌ẖaţ-qò֔deş̌ rò֥qaẖ mirĕqa֖ẖaţ maʻàşé֣̂h ròqé֑ẖa şě֥men mişĕ̌ẖaţ-qò֖deş̌ yihĕyeֽh׃"],[30,26,"וּ⁠מָשַׁחְתָּ֥ ב֖⁠וֹ אֶת־אֹ֣הֶל מוֹעֵ֑ד וְ⁠אֵ֖ת אֲר֥וֹן הָ⁠עֵדֻֽת׃","ẇ⁠máşǎẖĕţá֥̇ b֖⁠wò ʼeţ-ʼò֣hel mwòʻé֑d wĕ⁠ʼé֖ţ ʼàr֥wòn há⁠ʻéduֽţ׃"],[30,27,"וְ⁠אֶת־הַ⁠שֻּׁלְחָן֙ וְ⁠אֶת־כָּל־כֵּלָ֔י⁠ו וְ⁠אֶת־הַ⁠מְּנֹרָ֖ה וְ⁠אֶת־כֵּלֶ֑י⁠הָ וְ⁠אֵ֖ת מִזְבַּ֥ח הַ⁠קְּטֹֽרֶת׃","wĕ⁠ʼeţ-ha⁠şu̇̌lĕẖán֙ wĕ⁠ʼeţ-ká̇l-ké̇lá֔y⁠w wĕ⁠ʼeţ-ha⁠mĕ̇nòrá֖h wĕ⁠ʼeţ-ké̇le֑y⁠há wĕ⁠ʼé֖ţ mizĕbȧ֥ẖ ha⁠qĕ̇tòֽreţ׃"],[30,28,"וְ⁠אֶת־מִזְבַּ֥ח הָ⁠עֹלָ֖ה וְ⁠אֶת־כָּל־כֵּלָ֑י⁠ו וְ⁠אֶת־הַ⁠כִּיֹּ֖ר וְ⁠אֶת־כַּנּֽ⁠וֹ׃","wĕ⁠ʼeţ-mizĕbȧ֥ẖ há⁠ʻòlá֖h wĕ⁠ʼeţ-ká̇l-ké̇lá֑y⁠w wĕ⁠ʼeţ-ha⁠ki̇yò֖̇r wĕ⁠ʼeţ-kȧṅֽ⁠wò׃"],[30,29,"וְ⁠קִדַּשְׁתָּ֣ אֹתָ֔⁠ם וְ⁠הָי֖וּ קֹ֣דֶשׁ קָֽדָשִׁ֑ים כָּל־הַ⁠נֹּגֵ֥עַ בָּ⁠הֶ֖ם יִקְדָּֽשׁ׃","wĕ⁠qidȧşĕ̌ţá֣̇ ʼòţá֔⁠m wĕ⁠háy֖ẇ qò֣deş̌ qֽádáşǐ֑ym ká̇l-ha⁠nò̇gé֥ʻa bá̇⁠he֖m yiqĕdáֽ̇ş̌׃"],[30,30,"וְ⁠אֶת־אַהֲרֹ֥ן וְ⁠אֶת־בָּנָ֖י⁠ו תִּמְשָׁ֑ח וְ⁠קִדַּשְׁתָּ֥ אֹתָ֖⁠ם לְ⁠כַהֵ֥ן לִֽ⁠י׃","wĕ⁠ʼeţ-ʼahàrò֥n wĕ⁠ʼeţ-bá̇ná֖y⁠w ţi̇mĕşá֑̌ẖ wĕ⁠qidȧşĕ̌ţá֥̇ ʼòţá֖⁠m lĕ⁠kahé֥n liֽ⁠y׃"],[30,31,"וְ⁠אֶל־בְּנֵ֥י יִשְׂרָאֵ֖ל תְּדַבֵּ֣ר לֵ⁠אמֹ֑ר שֶׁ֠מֶן מִשְׁחַת־קֹ֨דֶשׁ יִהְיֶ֥ה זֶ֛ה לִ֖⁠י לְ⁠דֹרֹתֵי⁠כֶֽם׃","wĕ⁠ʼel-bĕ̇né֥y yişĕ̂ráʼé֖l ţĕ̇dabé֣̇r lé⁠ʼmò֑r şě֠men mişĕ̌ẖaţ-qò֨deş̌ yihĕye֥h ze֛h li֖⁠y lĕ⁠dòròţéy⁠keֽm׃"],[30,32,"עַל־בְּשַׂ֤ר אָדָם֙ לֹ֣א יִיסָ֔ךְ וּ⁠בְ⁠מַ֨תְכֻּנְתּ֔⁠וֹ לֹ֥א תַעֲשׂ֖וּ כָּמֹ֑⁠הוּ קֹ֣דֶשׁ ה֔וּא קֹ֖דֶשׁ יִהְיֶ֥ה לָ⁠כֶֽם׃","ʻal-bĕ̇şâ֤r ʼádám֙ lò֣ʼ yiysá֔kĕ ẇ⁠bĕ⁠ma֨ţĕku̇nĕţ̇֔⁠wò lò֥ʼ ţaʻàş֖̂ẇ ká̇mò֑⁠hẇ qò֣deş̌ h֔ẇʼ qò֖deş̌ yihĕye֥h lá⁠keֽm׃"],[30,33,"אִ֚ישׁ אֲשֶׁ֣ר יִרְקַ֣ח כָּמֹ֔⁠הוּ וַ⁠אֲשֶׁ֥ר יִתֵּ֛ן מִמֶּ֖⁠נּוּ עַל־זָ֑ר וְ⁠נִכְרַ֖ת מֵ⁠עַמָּֽי⁠ו׃ס","ʼi֚yş̌ ʼàşě֣r yirĕqa֣ẖ ká̇mò֔⁠hẇ wa⁠ʼàşě֥r yiţé֛̇n mimė֖⁠ṅẇ ʻal-zá֑r wĕ⁠nikĕra֖ţ mé⁠ʻamáֽ̇y⁠w׃s"],[30,34,"וַ⁠יֹּאמֶר֩ יְהוָ֨ה אֶל־מֹשֶׁ֜ה קַח־לְ⁠ךָ֣ סַמִּ֗ים נָטָ֤ף ׀ וּ⁠שְׁחֵ֨לֶת֙ וְ⁠חֶלְבְּנָ֔ה סַמִּ֖ים וּ⁠לְבֹנָ֣ה זַכָּ֑ה בַּ֥ד בְּ⁠בַ֖ד יִהְיֶֽה׃","wa⁠yò̇ʼmer֩ yĕhwá֨h ʼel-mòşě֜h qaẖ-lĕ⁠ká֣ sami̇֗ym nátá֤p ׀ ẇ⁠şĕ̌ẖé֨leţ֙ wĕ⁠ẖelĕbĕ̇ná֔h sami֖̇ym ẇ⁠lĕbòná֣h zaká֑̇h bȧ֥d bĕ̇⁠ba֖d yihĕyeֽh׃"],[30,35,"וְ⁠עָשִׂ֤יתָ אֹתָ⁠הּ֙ קְטֹ֔רֶת רֹ֖קַח מַעֲשֵׂ֣ה רוֹקֵ֑חַ מְמֻלָּ֖ח טָה֥וֹר קֹֽדֶשׁ׃","wĕ⁠ʻáşî֤yţá ʼòţá⁠ḣ֙ qĕtò֔reţ rò֖qaẖ maʻàşé֣̂h rwòqé֑ẖa mĕmulá֖̇ẖ táh֥wòr qòֽdeş̌׃"],[30,36,"וְ⁠שָֽׁחַקְתָּ֣ מִמֶּ⁠נָּה֮ הָדֵק֒ וְ⁠נָתַתָּ֨ה מִמֶּ֜⁠נָּה לִ⁠פְנֵ֤י הָ⁠עֵדֻת֙ בְּ⁠אֹ֣הֶל מוֹעֵ֔ד אֲשֶׁ֛ר אִוָּעֵ֥ד לְ⁠ךָ֖ שָׁ֑מָּ⁠ה קֹ֥דֶשׁ קָֽדָשִׁ֖ים תִּהְיֶ֥ה לָ⁠כֶֽם׃","wĕ⁠şáֽ̌ẖaqĕţá֣̇ mimė⁠ná̇h֮ hádéq֒ wĕ⁠náţaţá̇֨h mimė֜⁠ná̇h li⁠pĕné֤y há⁠ʻéduţ֙ bĕ̇⁠ʼò֣hel mwòʻé֔d ʼàşě֛r ʼiwá̇ʻé֥d lĕ⁠ká֖ şá֑̌má̇⁠h qò֥deş̌ qֽádáşǐ֖ym ţi̇hĕye֥h lá⁠keֽm׃"],[30,37,"וְ⁠הַ⁠קְּטֹ֨רֶת֙ אֲשֶׁ֣ר תַּעֲשֶׂ֔ה בְּ⁠מַ֨תְכֻּנְתָּ֔⁠הּ לֹ֥א תַעֲשׂ֖וּ לָ⁠כֶ֑ם קֹ֛דֶשׁ תִּהְיֶ֥ה לְ⁠ךָ֖ לַ⁠יהוָֽה׃","wĕ⁠ha⁠qĕ̇tò֨reţ֙ ʼàşě֣r ţȧʻàşê֔h bĕ̇⁠ma֨ţĕku̇nĕţá̇֔⁠ḣ lò֥ʼ ţaʻàş֖̂ẇ lá⁠ke֑m qò֛deş̌ ţi̇hĕye֥h lĕ⁠ká֖ la⁠yhwáֽh׃"],[30,38,"אִ֛ישׁ אֲשֶׁר־יַעֲשֶׂ֥ה כָמ֖וֹ⁠הָ לְ⁠הָרִ֣יחַ בָּ֑⁠הּ וְ⁠נִכְרַ֖ת מֵ⁠עַמָּֽי⁠ו׃ס","ʼi֛yş̌ ʼàşěr-yaʻàşê֥h kám֖wò⁠há lĕ⁠hári֣yẖa bá֑̇⁠ḣ wĕ⁠nikĕra֖ţ mé⁠ʻamáֽ̇y⁠w׃s"],[31,1,"וַ⁠יְדַבֵּ֥ר יְהוָ֖ה אֶל־מֹשֶׁ֥ה לֵּ⁠אמֹֽר׃","wa⁠yĕdabé֥̇r yĕhwá֖h ʼel-mòşě֥h lé̇⁠ʼmòֽr׃"],[31,2,"רְאֵ֖ה קָרָ֣אתִֽי בְ⁠שֵׁ֑ם בְּצַלְאֵ֛ל בֶּן־אוּרִ֥י בֶן־ח֖וּר לְ⁠מַטֵּ֥ה יְהוּדָֽה׃","rĕʼé֖h qárá֣ʼţiֽy bĕ⁠şé֑̌m bĕ̇ẕalĕʼé֛l bėn-ʼẇri֥y ben-ẖ֖ẇr lĕ⁠maté֥̇h yĕhẇdáֽh׃"],[31,3,"וָ⁠אֲמַלֵּ֥א אֹת֖⁠וֹ ר֣וּחַ אֱלֹהִ֑ים בְּ⁠חָכְמָ֛ה וּ⁠בִ⁠תְבוּנָ֥ה וּ⁠בְ⁠דַ֖עַת וּ⁠בְ⁠כָל־מְלָאכָֽה׃","wá⁠ʼàmalé֥̇ʼ ʼòţ֖⁠wò r֣ẇẖa ʼèlòhi֑ym bĕ̇⁠ẖákĕmá֛h ẇ⁠bi⁠ţĕbẇná֥h ẇ⁠bĕ⁠da֖ʻaţ ẇ⁠bĕ⁠kál-mĕláʼkáֽh׃"],[31,4,"לַ⁠חְשֹׁ֖ב מַחֲשָׁבֹ֑ת לַ⁠עֲשׂ֛וֹת בַּ⁠זָּהָ֥ב וּ⁠בַ⁠כֶּ֖סֶף וּ⁠בַ⁠נְּחֹֽשֶׁת׃","la⁠ẖĕşò֖̌b maẖàşá̌bò֑ţ la⁠ʻàş֛̂wòţ bȧ⁠zá̇há֥b ẇ⁠ba⁠kė֖sep ẇ⁠ba⁠nĕ̇ẖòֽşěţ׃"],[31,5,"וּ⁠בַ⁠חֲרֹ֥שֶׁת אֶ֛בֶן לְ⁠מַלֹּ֖את וּ⁠בַ⁠חֲרֹ֣שֶׁת עֵ֑ץ לַ⁠עֲשׂ֖וֹת בְּ⁠כָל־מְלָאכָֽה׃","ẇ⁠ba⁠ẖàrò֥şěţ ʼe֛ben lĕ⁠malò֖̇ʼţ ẇ⁠ba⁠ẖàrò֣şěţ ʻé֑ẕ la⁠ʻàş֖̂wòţ bĕ̇⁠kál-mĕláʼkáֽh׃"],[31,6,"וַ⁠אֲנִ֞י הִנֵּ֧ה נָתַ֣תִּי אִתּ֗⁠וֹ אֵ֣ת אָהֳלִיאָ֞ב בֶּן־אֲחִֽיסָמָךְ֙ לְ⁠מַטֵּה־דָ֔ן וּ⁠בְ⁠לֵ֥ב כָּל־חֲכַם־לֵ֖ב נָתַ֣תִּי חָכְמָ֑ה וְ⁠עָשׂ֕וּ אֵ֖ת כָּל־אֲשֶׁ֥ר צִוִּיתִֽ⁠ךָ׃","wa⁠ʼàni֞y hiné֧̇h náţa֣ţi̇y ʼiţ̇֗⁠wò ʼé֣ţ ʼáholiyʼá֞b bėn-ʼàẖiֽysámákĕ֙ lĕ⁠maté̇h-dá֔n ẇ⁠bĕ⁠lé֥b ká̇l-ẖàkam-lé֖b náţa֣ţi̇y ẖákĕmá֑h wĕ⁠ʻáş̂֕ẇ ʼé֖ţ ká̇l-ʼàşě֥r ẕiwi̇yţiֽ⁠ká׃"],[31,7,"אֵ֣ת ׀ אֹ֣הֶל מוֹעֵ֗ד וְ⁠אֶת־הָֽ⁠אָרֹן֙ לָֽ⁠עֵדֻ֔ת וְ⁠אֶת־הַ⁠כַּפֹּ֖רֶת אֲשֶׁ֣ר עָלָ֑י⁠ו וְ⁠אֵ֖ת כָּל־כְּלֵ֥י הָ⁠אֹֽהֶל׃","ʼé֣ţ ׀ ʼò֣hel mwòʻé֗d wĕ⁠ʼeţ-háֽ⁠ʼáròn֙ láֽ⁠ʻédu֔ţ wĕ⁠ʼeţ-ha⁠kȧpò֖̇reţ ʼàşě֣r ʻálá֑y⁠w wĕ⁠ʼé֖ţ ká̇l-kĕ̇lé֥y há⁠ʼòֽhel׃"],[31,8,"וְ⁠אֶת־הַ⁠שֻּׁלְחָן֙ וְ⁠אֶת־כֵּלָ֔י⁠ו וְ⁠אֶת־הַ⁠מְּנֹרָ֥ה הַ⁠טְּהֹרָ֖ה וְ⁠אֶת־כָּל־כֵּלֶ֑י⁠הָ וְ⁠אֵ֖ת מִזְבַּ֥ח הַ⁠קְּטֹֽרֶת׃","wĕ⁠ʼeţ-ha⁠şu̇̌lĕẖán֙ wĕ⁠ʼeţ-ké̇lá֔y⁠w wĕ⁠ʼeţ-ha⁠mĕ̇nòrá֥h ha⁠tĕ̇hòrá֖h wĕ⁠ʼeţ-ká̇l-ké̇le֑y⁠há wĕ⁠ʼé֖ţ mizĕbȧ֥ẖ ha⁠qĕ̇tòֽreţ׃"],[31,9,"וְ⁠אֶת־מִזְבַּ֥ח הָ⁠עֹלָ֖ה וְ⁠אֶת־כָּל־כֵּלָ֑י⁠ו וְ⁠אֶת־הַ⁠כִּיּ֖וֹר וְ⁠אֶת־כַּנּֽ⁠וֹ׃","wĕ⁠ʼeţ-mizĕbȧ֥ẖ há⁠ʻòlá֖h wĕ⁠ʼeţ-ká̇l-ké̇lá֑y⁠w wĕ⁠ʼeţ-ha⁠ki̇ẏ֖wòr wĕ⁠ʼeţ-kȧṅֽ⁠wò׃"],[31,10,"וְ⁠אֵ֖ת בִּגְדֵ֣י הַ⁠שְּׂרָ֑ד וְ⁠אֶת־בִּגְדֵ֤י הַ⁠קֹּ֨דֶשׁ֙ לְ⁠אַהֲרֹ֣ן הַ⁠כֹּהֵ֔ן וְ⁠אֶת־בִּגְדֵ֥י בָנָ֖י⁠ו לְ⁠כַהֵֽן׃","wĕ⁠ʼé֖ţ bi̇gĕdé֣y ha⁠şĕ̇̂rá֑d wĕ⁠ʼeţ-bi̇gĕdé֤y ha⁠qò̇֨deş̌֙ lĕ⁠ʼahàrò֣n ha⁠kò̇hé֔n wĕ⁠ʼeţ-bi̇gĕdé֥y báná֖y⁠w lĕ⁠kahéֽn׃"],[31,11,"וְ⁠אֵ֨ת שֶׁ֧מֶן הַ⁠מִּשְׁחָ֛ה וְ⁠אֶת־קְטֹ֥רֶת הַ⁠סַּמִּ֖ים לַ⁠קֹּ֑דֶשׁ כְּ⁠כֹ֥ל אֲשֶׁר־צִוִּיתִ֖⁠ךָ יַעֲשֽׂוּ׃פ","wĕ⁠ʼé֨ţ şě֧men ha⁠mi̇şĕ̌ẖá֛h wĕ⁠ʼeţ-qĕtò֥reţ ha⁠sȧmi֖̇ym la⁠qò֑̇deş̌ kĕ̇⁠kò֥l ʼàşěr-ẕiwi̇yţi֖⁠ká yaʻàşֽ̂ẇ׃p"],[31,12,"וַ⁠יֹּ֥אמֶר יְהוָ֖ה אֶל־מֹשֶׁ֥ה לֵּ⁠אמֹֽר׃","wa⁠yò֥̇ʼmer yĕhwá֖h ʼel-mòşě֥h lé̇⁠ʼmòֽr׃"],[31,13,"וְ⁠אַתָּ֞ה דַּבֵּ֨ר אֶל־בְּנֵ֤י יִשְׂרָאֵל֙ לֵ⁠אמֹ֔ר אַ֥ךְ אֶת־שַׁבְּתֹתַ֖⁠י תִּשְׁמֹ֑רוּ כִּי֩ א֨וֹת הִ֜וא בֵּינִ֤⁠י וּ⁠בֵֽינֵי⁠כֶם֙ לְ⁠דֹרֹ֣תֵי⁠כֶ֔ם לָ⁠דַ֕עַת כִּ֛י אֲנִ֥י יְהוָ֖ה מְקַדִּשְׁ⁠כֶֽם׃","wĕ⁠ʼaţá̇֞h dȧbé̇֨r ʼel-bĕ̇né֤y yişĕ̂ráʼél֙ lé⁠ʼmò֔r ʼa֥kĕ ʼeţ-şǎbĕ̇ţòţa֖⁠y ţi̇şĕ̌mò֑rẇ ki̇y֩ ʼ֨wòţ hi֜wʼ bé̇yni֤⁠y ẇ⁠béֽynéy⁠kem֙ lĕ⁠dòrò֣ţéy⁠ke֔m lá⁠da֕ʻaţ ki֛̇y ʼàni֥y yĕhwá֖h mĕqadi̇şĕ̌⁠keֽm׃"],[31,14,"וּ⁠שְׁמַרְתֶּם֙ אֶת־הַ⁠שַּׁבָּ֔ת כִּ֛י קֹ֥דֶשׁ הִ֖וא לָ⁠כֶ֑ם מְחַֽלְלֶ֨י⁠הָ֙ מ֣וֹת יוּמָ֔ת כִּ֗י כָּל־הָ⁠עֹשֶׂ֥ה בָ⁠הּ֙ מְלָאכָ֔ה וְ⁠נִכְרְתָ֛ה הַ⁠נֶּ֥פֶשׁ הַ⁠הִ֖וא מִ⁠קֶּ֥רֶב עַמֶּֽי⁠הָ׃","ẇ⁠şĕ̌marĕţėm֙ ʼeţ-ha⁠şȧ̌bá̇֔ţ ki֛̇y qò֥deş̌ hi֖wʼ lá⁠ke֑m mĕẖaֽlĕle֨y⁠há֙ m֣wòţ yẇmá֔ţ ki̇֗y ká̇l-há⁠ʻòşê֥h bá⁠ḣ֙ mĕláʼká֔h wĕ⁠nikĕrĕţá֛h ha⁠nė֥peş̌ ha⁠hi֖wʼ mi⁠qė֥reb ʻamėֽy⁠há׃"],[31,15,"שֵׁ֣שֶׁת יָמִים֮ יֵעָשֶׂ֣ה מְלָאכָה֒ וּ⁠בַ⁠יּ֣וֹם הַ⁠שְּׁבִיעִ֗י שַׁבַּ֧ת שַׁבָּת֛וֹן קֹ֖דֶשׁ לַ⁠יהוָ֑ה כָּל־הָ⁠עֹשֶׂ֧ה מְלָאכָ֛ה בְּ⁠י֥וֹם הַ⁠שַּׁבָּ֖ת מ֥וֹת יוּמָֽת׃","şé֣̌şěţ yámiym֮ yéʻáşê֣h mĕláʼkáh֒ ẇ⁠ba⁠ẏ֣wòm ha⁠şĕ̇̌biyʻi֗y şǎbȧ֧ţ şǎbá̇ţ֛wòn qò֖deş̌ la⁠yhwá֑h ká̇l-há⁠ʻòşê֧h mĕláʼká֛h bĕ̇⁠y֥wòm ha⁠şȧ̌bá֖̇ţ m֥wòţ yẇmáֽţ׃"],[31,16,"וְ⁠שָׁמְר֥וּ בְנֵֽי־יִשְׂרָאֵ֖ל אֶת־הַ⁠שַּׁבָּ֑ת לַ⁠עֲשׂ֧וֹת אֶת־הַ⁠שַּׁבָּ֛ת לְ⁠דֹרֹתָ֖⁠ם בְּרִ֥ית עוֹלָֽם׃","wĕ⁠şá̌mĕr֥ẇ bĕnéֽy-yişĕ̂ráʼé֖l ʼeţ-ha⁠şȧ̌bá֑̇ţ la⁠ʻàş֧̂wòţ ʼeţ-ha⁠şȧ̌bá֛̇ţ lĕ⁠dòròţá֖⁠m bĕ̇ri֥yţ ʻwòláֽm׃"],[31,17,"בֵּינִ֗⁠י וּ⁠בֵין֙ בְּנֵ֣י יִשְׂרָאֵ֔ל א֥וֹת הִ֖וא לְ⁠עֹלָ֑ם כִּי־שֵׁ֣שֶׁת יָמִ֗ים עָשָׂ֤ה יְהוָה֙ אֶת־הַ⁠שָּׁמַ֣יִם וְ⁠אֶת־הָ⁠אָ֔רֶץ וּ⁠בַ⁠יּוֹם֙ הַ⁠שְּׁבִיעִ֔י שָׁבַ֖ת וַ⁠יִּנָּפַֽשׁ׃ס","bé̇yni֗⁠y ẇ⁠béyn֙ bĕ̇né֣y yişĕ̂ráʼé֔l ʼ֥wòţ hi֖wʼ lĕ⁠ʻòlá֑m ki̇y-şé֣̌şěţ yámi֗ym ʻáşá֤̂h yĕhwáh֙ ʼeţ-ha⁠şá̇̌ma֣yim wĕ⁠ʼeţ-há⁠ʼá֔reẕ ẇ⁠ba⁠ẏwòm֙ ha⁠şĕ̇̌biyʻi֔y şá̌ba֖ţ wa⁠yi̇ná̇paֽş̌׃s"],[31,18,"וַ⁠יִּתֵּ֣ן אֶל־מֹשֶׁ֗ה כְּ⁠כַלֹּת⁠וֹ֙ לְ⁠דַבֵּ֤ר אִתּ⁠וֹ֙ בְּ⁠הַ֣ר סִינַ֔י שְׁנֵ֖י לֻחֹ֣ת הָ⁠עֵדֻ֑ת לֻחֹ֣ת אֶ֔בֶן כְּתֻבִ֖ים בְּ⁠אֶצְבַּ֥ע אֱלֹהִֽים׃","wa⁠yi̇ţé֣̇n ʼel-mòşě֗h kĕ̇⁠kalò̇ţ⁠wò֙ lĕ⁠dabé֤̇r ʼiţ̇⁠wò֙ bĕ̇⁠ha֣r siyna֔y şĕ̌né֖y luẖò֣ţ há⁠ʻédu֑ţ luẖò֣ţ ʼe֔ben kĕ̇ţubi֖ym bĕ̇⁠ʼeẕĕbȧ֥ʻ ʼèlòhiֽym׃"],[32,1,"וַ⁠יַּ֣רְא הָ⁠עָ֔ם כִּֽי־בֹשֵׁ֥שׁ מֹשֶׁ֖ה לָ⁠רֶ֣דֶת מִן־הָ⁠הָ֑ר וַ⁠יִּקָּהֵ֨ל הָ⁠עָ֜ם עַֽל־אַהֲרֹ֗ן וַ⁠יֹּאמְר֤וּ אֵלָי⁠ו֙ ק֣וּם ׀ עֲשֵׂה־לָ֣⁠נוּ אֱלֹהִ֗ים אֲשֶׁ֤ר יֵֽלְכוּ֙ לְ⁠פָנֵ֔י⁠נוּ כִּי־זֶ֣ה ׀ מֹשֶׁ֣ה הָ⁠אִ֗ישׁ אֲשֶׁ֤ר הֶֽעֱלָ֨⁠נוּ֙ מֵ⁠אֶ֣רֶץ מִצְרַ֔יִם לֹ֥א יָדַ֖עְנוּ מֶה־הָ֥יָה לֽ⁠וֹ׃","wa⁠yȧ֣rĕʼ há⁠ʻá֔m kiֽ̇y-bòşé֥̌ş̌ mòşě֖h lá⁠re֣deţ min-há⁠há֑r wa⁠yi̇qá̇hé֨l há⁠ʻá֜m ʻaֽl-ʼahàrò֗n wa⁠yò̇ʼmĕr֤ẇ ʼéláy⁠w֙ q֣ẇm ׀ ʻàşé̂h-lá֣⁠nẇ ʼèlòhi֗ym ʼàşě֤r yéֽlĕkẇ֙ lĕ⁠páné֔y⁠nẇ ki̇y-ze֣h ׀ mòşě֣h há⁠ʼi֗yş̌ ʼàşě֤r heֽʻèlá֨⁠nẇ֙ mé⁠ʼe֣reẕ miẕĕra֔yim lò֥ʼ yáda֖ʻĕnẇ meh-há֥yáh lֽ⁠wò׃"],[32,2,"וַ⁠יֹּ֤אמֶר אֲלֵ⁠הֶם֙ אַהֲרֹ֔ן פָּֽרְקוּ֙ נִזְמֵ֣י הַ⁠זָּהָ֔ב אֲשֶׁר֙ בְּ⁠אָזְנֵ֣י נְשֵׁי⁠כֶ֔ם בְּנֵי⁠כֶ֖ם וּ⁠בְנֹתֵי⁠כֶ֑ם וְ⁠הָבִ֖יאוּ אֵלָֽ⁠י׃","wa⁠yò֤̇ʼmer ʼàlé⁠hem֙ ʼahàrò֔n páֽ̇rĕqẇ֙ nizĕmé֣y ha⁠zá̇há֔b ʼàşěr֙ bĕ̇⁠ʼázĕné֣y nĕşé̌y⁠ke֔m bĕ̇néy⁠ke֖m ẇ⁠bĕnòţéy⁠ke֑m wĕ⁠hábi֖yʼẇ ʼéláֽ⁠y׃"],[32,3,"וַ⁠יִּתְפָּֽרְקוּ֙ כָּל־הָ⁠עָ֔ם אֶת־נִזְמֵ֥י הַ⁠זָּהָ֖ב אֲשֶׁ֣ר בְּ⁠אָזְנֵי⁠הֶ֑ם וַ⁠יָּבִ֖יאוּ אֶֽל־אַהֲרֹֽן׃","wa⁠yi̇ţĕpáֽ̇rĕqẇ֙ ká̇l-há⁠ʻá֔m ʼeţ-nizĕmé֥y ha⁠zá̇há֖b ʼàşě֣r bĕ̇⁠ʼázĕnéy⁠he֑m wa⁠yá̇bi֖yʼẇ ʼeֽl-ʼahàròֽn׃"],[32,4,"וַ⁠יִּקַּ֣ח מִ⁠יָּדָ֗⁠ם וַ⁠יָּ֤צַר אֹת⁠וֹ֙ בַּ⁠חֶ֔רֶט וַֽ⁠יַּעֲשֵׂ֖⁠הוּ עֵ֣גֶל מַסֵּכָ֑ה וַ⁠יֹּ֣אמְר֔וּ אֵ֤לֶּה אֱלֹהֶ֨י⁠ךָ֙ יִשְׂרָאֵ֔ל אֲשֶׁ֥ר הֶעֱל֖וּ⁠ךָ מֵ⁠אֶ֥רֶץ מִצְרָֽיִם׃","wa⁠yi̇qȧ֣ẖ mi⁠yá̇dá֗⁠m wa⁠yá֤̇ẕar ʼòţ⁠wò֙ bȧ⁠ẖe֔ret waֽ⁠yȧʻàşé֖̂⁠hẇ ʻé֣gel masé̇ká֑h wa⁠yò֣̇ʼmĕr֔ẇ ʼé֤lėh ʼèlòhe֨y⁠ká֙ yişĕ̂ráʼé֔l ʼàşě֥r heʻèl֖ẇ⁠ká mé⁠ʼe֥reẕ miẕĕráֽyim׃"],[32,5,"וַ⁠יַּ֣רְא אַהֲרֹ֔ן וַ⁠יִּ֥בֶן מִזְבֵּ֖חַ לְ⁠פָנָ֑י⁠ו וַ⁠יִּקְרָ֤א אַֽהֲרֹן֙ וַ⁠יֹּאמַ֔ר חַ֥ג לַ⁠יהוָ֖ה מָחָֽר׃","wa⁠yȧ֣rĕʼ ʼahàrò֔n wa⁠yi֥̇ben mizĕbé֖̇ẖa lĕ⁠páná֑y⁠w wa⁠yi̇qĕrá֤ʼ ʼaֽhàròn֙ wa⁠yò̇ʼma֔r ẖa֥g la⁠yhwá֖h máẖáֽr׃"],[32,6,"וַ⁠יַּשְׁכִּ֨ימוּ֙ מִֽ⁠מָּחֳרָ֔ת וַ⁠יַּעֲל֣וּ עֹלֹ֔ת וַ⁠יַּגִּ֖שׁוּ שְׁלָמִ֑ים וַ⁠יֵּ֤שֶׁב הָ⁠עָם֙ לֶֽ⁠אֱכֹ֣ל וְ⁠שָׁת֔וֹ וַ⁠יָּקֻ֖מוּ לְ⁠צַחֵֽק׃פ","wa⁠yȧşĕ̌ki̇֨ymẇ֙ miֽ⁠má̇ẖorá֔ţ wa⁠yȧʻàl֣ẇ ʻòlò֔ţ wa⁠yȧgi֖̇ş̌ẇ şĕ̌lámi֑ym wa⁠yé֤̇şěb há⁠ʻám֙ lֽe⁠ʼèkò֣l wĕ⁠şá̌ţ֔wò wa⁠yá̇qu֖mẇ lĕ⁠ẕaẖéֽq׃p"],[32,7,"וַ⁠יְדַבֵּ֥ר יְהוָ֖ה אֶל־מֹשֶׁ֑ה לֶךְ־רֵ֕ד כִּ֚י שִׁחֵ֣ת עַמְּ⁠ךָ֔ אֲשֶׁ֥ר הֶעֱלֵ֖יתָ מֵ⁠אֶ֥רֶץ מִצְרָֽיִם׃","wa⁠yĕdabé֥̇r yĕhwá֖h ʼel-mòşě֑h lekĕ-ré֕d ki֚̇y şǐẖé֣ţ ʻamĕ̇⁠ká֔ ʼàşě֥r heʻèlé֖yţá mé⁠ʼe֥reẕ miẕĕráֽyim׃"],[32,8,"סָ֣רוּ מַהֵ֗ר מִן־הַ⁠דֶּ֨רֶךְ֙ אֲשֶׁ֣ר צִוִּיתִ֔⁠ם עָשׂ֣וּ לָ⁠הֶ֔ם עֵ֖גֶל מַסֵּכָ֑ה וַ⁠יִּשְׁתַּֽחֲווּ־ל⁠וֹ֙ וַ⁠יִּזְבְּחוּ־ל֔⁠וֹ וַ⁠יֹּ֣אמְר֔וּ אֵ֤לֶּה אֱלֹהֶ֨י⁠ךָ֙ יִשְׂרָאֵ֔ל אֲשֶׁ֥ר הֶֽעֱל֖וּ⁠ךָ מֵ⁠אֶ֥רֶץ מִצְרָֽיִם׃","sá֣rẇ mahé֗r min-ha⁠dė֨rekĕ֙ ʼàşě֣r ẕiwi̇yţi֔⁠m ʻáş֣̂ẇ lá⁠he֔m ʻé֖gel masé̇ká֑h wa⁠yi̇şĕ̌ţȧֽẖàwẇ-l⁠wò֙ wa⁠yi̇zĕbĕ̇ẖẇ-l֔⁠wò wa⁠yò֣̇ʼmĕr֔ẇ ʼé֤lėh ʼèlòhe֨y⁠ká֙ yişĕ̂ráʼé֔l ʼàşě֥r hֽeʻèl֖ẇ⁠ká mé⁠ʼe֥reẕ miẕĕráֽyim׃"],[32,9,"וַ⁠יֹּ֥אמֶר יְהוָ֖ה אֶל־מֹשֶׁ֑ה רָאִ֨יתִי֙ אֶת־הָ⁠עָ֣ם הַ⁠זֶּ֔ה וְ⁠הִנֵּ֥ה עַם־קְשֵׁה־עֹ֖רֶף הֽוּא׃","wa⁠yò֥̇ʼmer yĕhwá֖h ʼel-mòşě֑h ráʼi֨yţiy֙ ʼeţ-há⁠ʻá֣m ha⁠zė֔h wĕ⁠hiné֥̇h ʻam-qĕşé̌h-ʻò֖rep hֽẇʼ׃"],[32,10,"וְ⁠עַתָּה֙ הַנִּ֣יחָ⁠ה לִּ֔⁠י וְ⁠יִֽחַר־אַפִּ֥⁠י בָ⁠הֶ֖ם וַ⁠אֲכַלֵּ֑⁠ם וְ⁠אֶֽעֱשֶׂ֥ה אוֹתְ⁠ךָ֖ לְ⁠ג֥וֹי גָּדֽוֹל׃","wĕ⁠ʻaţá̇h֙ hani֣̇yẖá⁠h li̇֔⁠y wĕ⁠yiֽẖar-ʼapi֥̇⁠y bá⁠he֖m wa⁠ʼàkalé֑̇⁠m wĕ⁠ʼeֽʻèşê֥h ʼwòţĕ⁠ká֖ lĕ⁠g֥wòy gá̇dֽwòl׃"],[32,11,"וַ⁠יְחַ֣ל מֹשֶׁ֔ה אֶת־פְּנֵ֖י יְהוָ֣ה אֱלֹהָ֑י⁠ו וַ⁠יֹּ֗אמֶר לָ⁠מָ֤ה יְהוָה֙ יֶחֱרֶ֤ה אַפְּ⁠ךָ֙ בְּ⁠עַמֶּ֔⁠ךָ אֲשֶׁ֤ר הוֹצֵ֨אתָ֙ מֵ⁠אֶ֣רֶץ מִצְרַ֔יִם בְּ⁠כֹ֥חַ גָּד֖וֹל וּ⁠בְ⁠יָ֥ד חֲזָקָֽה׃","wa⁠yĕẖa֣l mòşě֔h ʼeţ-pĕ̇né֖y yĕhwá֣h ʼèlòhá֑y⁠w wa⁠yò̇֗ʼmer lá⁠má֤h yĕhwáh֙ yeẖère֤h ʼapĕ̇⁠ká֙ bĕ̇⁠ʻamė֔⁠ká ʼàşě֤r hwòẕé֨ʼţá֙ mé⁠ʼe֣reẕ miẕĕra֔yim bĕ̇⁠kò֥ẖa gá̇d֖wòl ẇ⁠bĕ⁠yá֥d ẖàzáqáֽh׃"],[32,12,"לָ⁠מָּה֩ יֹאמְר֨וּ מִצְרַ֜יִם לֵ⁠אמֹ֗ר בְּ⁠רָעָ֤ה הֽוֹצִיאָ⁠ם֙ לַ⁠הֲרֹ֤ג אֹתָ⁠ם֙ בֶּֽ⁠הָרִ֔ים וּ֨⁠לְ⁠כַלֹּתָ֔⁠ם מֵ⁠עַ֖ל פְּנֵ֣י הָֽ⁠אֲדָמָ֑ה שׁ֚וּב מֵ⁠חֲר֣וֹן אַפֶּ֔⁠ךָ וְ⁠הִנָּחֵ֥ם עַל־הָ⁠רָעָ֖ה לְ⁠עַמֶּֽ⁠ךָ׃","lá⁠má̇h֩ yòʼmĕr֨ẇ miẕĕra֜yim lé⁠ʼmò֗r bĕ̇⁠ráʻá֤h hֽwòẕiyʼá⁠m֙ la⁠hàrò֤g ʼòţá⁠m֙ bėֽ⁠hári֔ym ẇ֨⁠lĕ⁠kalò̇ţá֔⁠m mé⁠ʻa֖l pĕ̇né֣y háֽ⁠ʼàdámá֑h ş֚̌ẇb mé⁠ẖàr֣wòn ʼapė֔⁠ká wĕ⁠hiná̇ẖé֥m ʻal-há⁠ráʻá֖h lĕ⁠ʻamėֽ⁠ká׃"],[32,13,"זְכֹ֡ר לְ⁠אַבְרָהָם֩ לְ⁠יִצְחָ֨ק וּ⁠לְ⁠יִשְׂרָאֵ֜ל עֲבָדֶ֗י⁠ךָ אֲשֶׁ֨ר נִשְׁבַּ֣עְתָּ לָ⁠הֶם֮ בָּ⁠ךְ֒ וַ⁠תְּדַבֵּ֣ר אֲלֵ⁠הֶ֔ם אַרְבֶּה֙ אֶֽת־זַרְעֲ⁠כֶ֔ם כְּ⁠כוֹכְבֵ֖י הַ⁠שָּׁמָ֑יִם וְ⁠כָל־הָ⁠אָ֨רֶץ הַ⁠זֹּ֜את אֲשֶׁ֣ר אָמַ֗רְתִּי אֶתֵּן֙ לְ⁠זַרְעֲ⁠כֶ֔ם וְ⁠נָחֲל֖וּ לְ⁠עֹלָֽם׃","zĕkò֡r lĕ⁠ʼabĕráhám֩ lĕ⁠yiẕĕẖá֨q ẇ⁠lĕ⁠yişĕ̂ráʼé֜l ʻàbáde֗y⁠ká ʼàşě֨r nişĕ̌bȧ֣ʻĕţá̇ lá⁠hem֮ bá̇⁠kĕ֒ wa⁠ţĕ̇dabé֣̇r ʼàlé⁠he֔m ʼarĕbėh֙ ʼeֽţ-zarĕʻà⁠ke֔m kĕ̇⁠kwòkĕbé֖y ha⁠şá̇̌má֑yim wĕ⁠kál-há⁠ʼá֨reẕ ha⁠zò̇֜ʼţ ʼàşě֣r ʼáma֗rĕţi̇y ʼeţé̇n֙ lĕ⁠zarĕʻà⁠ke֔m wĕ⁠náẖàl֖ẇ lĕ⁠ʻòláֽm׃"],[32,14,"וַ⁠יִּנָּ֖חֶם יְהוָ֑ה עַל־הָ֣⁠רָעָ֔ה אֲשֶׁ֥ר דִּבֶּ֖ר לַ⁠עֲשׂ֥וֹת לְ⁠עַמּֽ⁠וֹ׃פ","wa⁠yi̇ná֖̇ẖem yĕhwá֑h ʻal-há֣⁠ráʻá֔h ʼàşě֥r di̇bė֖r la⁠ʻàş֥̂wòţ lĕ⁠ʻaṁֽ⁠wò׃p"],[32,15,"וַ⁠יִּ֜פֶן וַ⁠יֵּ֤רֶד מֹשֶׁה֙ מִן־הָ⁠הָ֔ר וּ⁠שְׁנֵ֛י לֻחֹ֥ת הָ⁠עֵדֻ֖ת בְּ⁠יָד֑⁠וֹ לֻחֹ֗ת כְּתֻבִים֙ מִ⁠שְּׁנֵ֣י עֶבְרֵי⁠הֶ֔ם מִ⁠זֶּ֥ה וּ⁠מִ⁠זֶּ֖ה הֵ֥ם כְּתֻבִֽים׃","wa⁠yi̇֜pen wa⁠yé֤̇red mòşěh֙ min-há⁠há֔r ẇ⁠şĕ̌né֛y luẖò֥ţ há⁠ʻédu֖ţ bĕ̇⁠yád֑⁠wò luẖò֗ţ kĕ̇ţubiym֙ mi⁠şĕ̇̌né֣y ʻebĕréy⁠he֔m mi⁠zė֥h ẇ⁠mi⁠zė֖h hé֥m kĕ̇ţubiֽym׃"],[32,16,"וְ⁠הַ֨⁠לֻּחֹ֔ת מַעֲשֵׂ֥ה אֱלֹהִ֖ים הֵ֑מָּה וְ⁠הַ⁠מִּכְתָּ֗ב מִכְתַּ֤ב אֱלֹהִים֙ ה֔וּא חָר֖וּת עַל־הַ⁠לֻּחֹֽת׃","wĕ⁠ha֨⁠lu̇ẖò֔ţ maʻàşé֥̂h ʼèlòhi֖ym hé֑má̇h wĕ⁠ha⁠mi̇kĕţá̇֗b mikĕţȧ֤b ʼèlòhiym֙ h֔ẇʼ ẖár֖ẇţ ʻal-ha⁠lu̇ẖòֽţ׃"],[32,17,"וַ⁠יִּשְׁמַ֧ע יְהוֹשֻׁ֛עַ אֶת־ק֥וֹל הָ⁠עָ֖ם בְּ⁠רֵעֹ֑⁠ה וַ⁠יֹּ֨אמֶר֙ אֶל־מֹשֶׁ֔ה ק֥וֹל מִלְחָמָ֖ה בַּֽ⁠מַּחֲנֶה׃","wa⁠yi̇şĕ̌ma֧ʻ yĕhwòşǔ֛ʻa ʼeţ-q֥wòl há⁠ʻá֖m bĕ̇⁠réʻò֑⁠h wa⁠yò̇֨ʼmer֙ ʼel-mòşě֔h q֥wòl milĕẖámá֖h bȧֽ⁠mȧẖàneh׃"],[32,18,"וַ⁠יֹּ֗אמֶר אֵ֥ין קוֹל֙ עֲנ֣וֹת גְּבוּרָ֔ה וְ⁠אֵ֥ין ק֖וֹל עֲנ֣וֹת חֲלוּשָׁ֑ה ק֣וֹל עַנּ֔וֹת אָנֹכִ֖י שֹׁמֵֽעַ׃","wa⁠yò̇֗ʼmer ʼé֥yn qwòl֙ ʻàn֣wòţ gĕ̇bẇrá֔h wĕ⁠ʼé֥yn q֖wòl ʻàn֣wòţ ẖàlẇşá֑̌h q֣wòl ʻaṅ֔wòţ ʼánòki֖y şò̌méֽʻa׃"],[32,19,"וַֽ⁠יְהִ֗י כַּ⁠אֲשֶׁ֤ר קָרַב֙ אֶל־הַֽ⁠מַּחֲנֶ֔ה וַ⁠יַּ֥רְא אֶת־הָ⁠עֵ֖גֶל וּ⁠מְחֹלֹ֑ת וַ⁠יִּֽחַר־אַ֣ף מֹשֶׁ֗ה וַ⁠יַּשְׁלֵ֤ךְ מ⁠יד⁠ו אֶת־הַ⁠לֻּחֹ֔ת וַ⁠יְשַׁבֵּ֥ר אֹתָ֖⁠ם תַּ֥חַת הָ⁠הָֽר׃","wֽa⁠yĕhi֗y kȧ⁠ʼàşě֤r qárab֙ ʼel-haֽ⁠mȧẖàne֔h wa⁠yȧ֥rĕʼ ʼeţ-há⁠ʻé֖gel ẇ⁠mĕẖòlò֑ţ wa⁠yiֽ̇ẖar-ʼa֣p mòşě֗h wa⁠yȧşĕ̌lé֤kĕ m⁠yd⁠w ʼeţ-ha⁠lu̇ẖò֔ţ wa⁠yĕşǎbé֥̇r ʼòţá֖⁠m ţȧ֥ẖaţ há⁠háֽr׃"],[32,20,"וַ⁠יִּקַּ֞ח אֶת־הָ⁠עֵ֨גֶל אֲשֶׁ֤ר עָשׂוּ֙ וַ⁠יִּשְׂרֹ֣ף בָּ⁠אֵ֔שׁ וַ⁠יִּטְחַ֖ן עַ֣ד אֲשֶׁר־דָּ֑ק וַ⁠יִּ֨זֶר֙ עַל־פְּנֵ֣י הַ⁠מַּ֔יִם וַ⁠יַּ֖שְׁקְ אֶת־בְּנֵ֥י יִשְׂרָאֵֽל׃","wa⁠yi̇qȧ֞ẖ ʼeţ-há⁠ʻé֨gel ʼàşě֤r ʻáş̂ẇ֙ wa⁠yi̇şĕ̂rò֣p bá̇⁠ʼé֔ş̌ wa⁠yi̇tĕẖa֖n ʻa֣d ʼàşěr-dá֑̇q wa⁠yi̇֨zer֙ ʻal-pĕ̇né֣y ha⁠mȧ֔yim wa⁠yȧ֖şĕ̌qĕ ʼeţ-bĕ̇né֥y yişĕ̂ráʼéֽl׃"],[32,21,"וַ⁠יֹּ֤אמֶר מֹשֶׁה֙ אֶֽל־אַהֲרֹ֔ן מֶֽה־עָשָׂ֥ה לְ⁠ךָ֖ הָ⁠עָ֣ם הַ⁠זֶּ֑ה כִּֽי־הֵבֵ֥אתָ עָלָ֖י⁠ו חֲטָאָ֥ה גְדֹלָֽה׃","wa⁠yò֤̇ʼmer mòşěh֙ ʼeֽl-ʼahàrò֔n meֽh-ʻáşá֥̂h lĕ⁠ká֖ há⁠ʻá֣m ha⁠zė֑h kiֽ̇y-hébé֥ʼţá ʻálá֖y⁠w ẖàtáʼá֥h gĕdòláֽh׃"],[32,22,"וַ⁠יֹּ֣אמֶר אַהֲרֹ֔ן אַל־יִ֥חַר אַ֖ף אֲדֹנִ֑⁠י אַתָּה֙ יָדַ֣עְתָּ אֶת־הָ⁠עָ֔ם כִּ֥י בְ⁠רָ֖ע הֽוּא׃","wa⁠yò֣̇ʼmer ʼahàrò֔n ʼal-yi֥ẖar ʼa֖p ʼàdòni֑⁠y ʼaţá̇h֙ yáda֣ʻĕţá̇ ʼeţ-há⁠ʻá֔m ki֥̇y bĕ⁠rá֖ʻ hֽẇʼ׃"],[32,23,"וַ⁠יֹּ֣אמְרוּ לִ֔⁠י עֲשֵׂה־לָ֣⁠נוּ אֱלֹהִ֔ים אֲשֶׁ֥ר יֵלְכ֖וּ לְ⁠פָנֵ֑י⁠נוּ כִּי־זֶ֣ה ׀ מֹשֶׁ֣ה הָ⁠אִ֗ישׁ אֲשֶׁ֤ר הֶֽעֱלָ֨⁠נוּ֙ מֵ⁠אֶ֣רֶץ מִצְרַ֔יִם לֹ֥א יָדַ֖עְנוּ מֶה־הָ֥יָה לֽ⁠וֹ׃","wa⁠yò֣̇ʼmĕrẇ li֔⁠y ʻàşé̂h-lá֣⁠nẇ ʼèlòhi֔ym ʼàşě֥r yélĕk֖ẇ lĕ⁠páné֑y⁠nẇ ki̇y-ze֣h ׀ mòşě֣h há⁠ʼi֗yş̌ ʼàşě֤r hֽeʻèlá֨⁠nẇ֙ mé⁠ʼe֣reẕ miẕĕra֔yim lò֥ʼ yáda֖ʻĕnẇ meh-há֥yáh lֽ⁠wò׃"],[32,24,"וָ⁠אֹמַ֤ר לָ⁠הֶם֙ לְ⁠מִ֣י זָהָ֔ב הִתְפָּרָ֖קוּ וַ⁠יִּתְּנוּ־לִ֑⁠י וָ⁠אַשְׁלִכֵ֣⁠הוּ בָ⁠אֵ֔שׁ וַ⁠יֵּצֵ֖א הָ⁠עֵ֥גֶל הַ⁠זֶּֽה׃","wá⁠ʼòma֤r lá⁠hem֙ lĕ⁠mi֣y záhá֔b hiţĕpá̇rá֖qẇ wa⁠yi̇ţĕ̇nẇ-li֑⁠y wá⁠ʼaşĕ̌liké֣⁠hẇ bá⁠ʼé֔ş̌ wa⁠yé̇ẕé֖ʼ há⁠ʻé֥gel ha⁠zėֽh׃"],[32,25,"וַ⁠יַּ֤רְא מֹשֶׁה֙ אֶת־הָ⁠עָ֔ם כִּ֥י פָרֻ֖עַ ה֑וּא כִּֽי־פְרָעֹ֣⁠ה אַהֲרֹ֔ן לְ⁠שִׁמְצָ֖ה בְּ⁠קָמֵי⁠הֶֽם׃","wa⁠yȧ֤rĕʼ mòşěh֙ ʼeţ-há⁠ʻá֔m ki֥̇y páru֖ʻa h֑ẇʼ kiֽ̇y-pĕráʻò֣⁠h ʼahàrò֔n lĕ⁠şǐmĕẕá֖h bĕ̇⁠qáméy⁠heֽm׃"],[32,26,"וַ⁠יַּעֲמֹ֤ד מֹשֶׁה֙ בְּ⁠שַׁ֣עַר הַֽ⁠מַּחֲנֶ֔ה וַ⁠יֹּ֕אמֶר מִ֥י לַ⁠יהוָ֖ה אֵלָ֑⁠י וַ⁠יֵּאָסְפ֥וּ אֵלָ֖י⁠ו כָּל־בְּנֵ֥י לֵוִֽי׃","wa⁠yȧʻàmò֤d mòşěh֙ bĕ̇⁠şǎ֣ʻar haֽ⁠mȧẖàne֔h wa⁠yò̇֕ʼmer mi֥y la⁠yhwá֖h ʼélá֑⁠y wa⁠yé̇ʼásĕp֥ẇ ʼélá֖y⁠w ká̇l-bĕ̇né֥y léwiֽy׃"],[32,27,"וַ⁠יֹּ֣אמֶר לָ⁠הֶ֗ם כֹּֽה־אָמַ֤ר יְהוָה֙ אֱלֹהֵ֣י יִשְׂרָאֵ֔ל שִׂ֥ימוּ אִישׁ־חַרְבּ֖⁠וֹ עַל־יְרֵכ֑⁠וֹ עִבְר֨וּ וָ⁠שׁ֜וּבוּ מִ⁠שַּׁ֤עַר לָ⁠שַׁ֨עַר֙ בַּֽ⁠מַּחֲנֶ֔ה וְ⁠הִרְג֧וּ אִֽישׁ־אֶת־אָחִ֛י⁠ו וְ⁠אִ֥ישׁ אֶת־רֵעֵ֖⁠הוּ וְ⁠אִ֥ישׁ אֶת־קְרֹבֽ⁠וֹ׃","wa⁠yò֣̇ʼmer lá⁠he֗m kòֽ̇h-ʼáma֤r yĕhwáh֙ ʼèlòhé֣y yişĕ̂ráʼé֔l şî֥ymẇ ʼiyş̌-ẖarĕḃ֖⁠wò ʻal-yĕrék֑⁠wò ʻibĕr֨ẇ wá⁠ş̌֜ẇbẇ mi⁠şȧ֤̌ʻar lá⁠şǎ֨ʻar֙ bȧֽ⁠mȧẖàne֔h wĕ⁠hirĕg֧ẇ ʼiֽyş̌-ʼeţ-ʼáẖi֛y⁠w wĕ⁠ʼi֥yş̌ ʼeţ-réʻé֖⁠hẇ wĕ⁠ʼi֥yş̌ ʼeţ-qĕròbֽ⁠wò׃"],[32,28,"וַ⁠יַּֽעֲשׂ֥וּ בְנֵֽי־לֵוִ֖י כִּ⁠דְבַ֣ר מֹשֶׁ֑ה וַ⁠יִּפֹּ֤ל מִן־הָ⁠עָם֙ בַּ⁠יּ֣וֹם הַ⁠ה֔וּא כִּ⁠שְׁלֹ֥שֶׁת אַלְפֵ֖י אִֽישׁ׃","wa⁠yȧֽʻàş֥̂ẇ bĕnéֽy-léwi֖y ki̇⁠dĕba֣r mòşě֑h wa⁠yi̇pò֤̇l min-há⁠ʻám֙ bȧ⁠ẏ֣wòm ha⁠h֔ẇʼ ki̇⁠şĕ̌lò֥şěţ ʼalĕpé֖y ʼiֽyş̌׃"],[32,29,"וַ⁠יֹּ֣אמֶר מֹשֶׁ֗ה מִלְא֨וּ יֶדְ⁠כֶ֤ם הַ⁠יּוֹם֙ לַֽ⁠יהוָ֔ה כִּ֛י אִ֥ישׁ בִּ⁠בְנ֖⁠וֹ וּ⁠בְ⁠אָחִ֑י⁠ו וְ⁠לָ⁠תֵ֧ת עֲלֵי⁠כֶ֛ם הַ⁠יּ֖וֹם בְּרָכָֽה׃","wa⁠yò֣̇ʼmer mòşě֗h milĕʼ֨ẇ yedĕ⁠ke֤m ha⁠ẏwòm֙ laֽ⁠yhwá֔h ki֛̇y ʼi֥yş̌ bi̇⁠bĕn֖⁠wò ẇ⁠bĕ⁠ʼáẖi֑y⁠w wĕ⁠lá⁠ţé֧ţ ʻàléy⁠ke֛m ha⁠ẏ֖wòm bĕ̇rákáֽh׃"],[32,30,"וַ⁠יְהִי֙ מִֽ⁠מָּחֳרָ֔ת וַ⁠יֹּ֤אמֶר מֹשֶׁה֙ אֶל־הָ⁠עָ֔ם אַתֶּ֥ם חֲטָאתֶ֖ם חֲטָאָ֣ה גְדֹלָ֑ה וְ⁠עַתָּה֙ אֶֽעֱלֶ֣ה אֶל־יְהוָ֔ה אוּלַ֥י אֲכַפְּרָ֖ה בְּעַ֥ד חַטַּאתְ⁠כֶֽם׃","wa⁠yĕhiy֙ miֽ⁠má̇ẖorá֔ţ wa⁠yò֤̇ʼmer mòşěh֙ ʼel-há⁠ʻá֔m ʼaţė֥m ẖàtáʼţe֖m ẖàtáʼá֣h gĕdòlá֑h wĕ⁠ʻaţá̇h֙ ʼֽeʻèle֣h ʼel-yĕhwá֔h ʼẇla֥y ʼàkapĕ̇rá֖h bĕ̇ʻa֥d ẖatȧʼţĕ⁠keֽm׃"],[32,31,"וַ⁠יָּ֧שָׁב מֹשֶׁ֛ה אֶל־יְהוָ֖ה וַ⁠יֹּאמַ֑ר אָ֣נָּ֗א חָטָ֞א הָ⁠עָ֤ם הַ⁠זֶּה֙ חֲטָאָ֣ה גְדֹלָ֔ה וַ⁠יַּֽעֲשׂ֥וּ לָ⁠הֶ֖ם אֱלֹהֵ֥י זָהָֽב׃","wa⁠yá֧̇şá̌b mòşě֛h ʼel-yĕhwá֖h wa⁠yò̇ʼma֑r ʼá֣ná̇֗ʼ ẖátá֞ʼ há⁠ʻá֤m ha⁠zėh֙ ẖàtáʼá֣h gĕdòlá֔h wa⁠yȧֽʻàş֥̂ẇ lá⁠he֖m ʼèlòhé֥y záháֽb׃"],[32,32,"וְ⁠עַתָּ֖ה אִם־תִּשָּׂ֣א חַטָּאתָ֑⁠ם וְ⁠אִם־אַ֕יִן מְחֵ֣⁠נִי נָ֔א מִֽ⁠סִּפְרְ⁠ךָ֖ אֲשֶׁ֥ר כָּתָֽבְתָּ׃","wĕ⁠ʻaţá֖̇h ʼim-ţi̇şá֣̇̂ʼ ẖatá̇ʼţá֑⁠m wĕ⁠ʼim-ʼa֕yin mĕẖé֣⁠niy ná֔ʼ miֽ⁠si̇pĕrĕ⁠ká֖ ʼàşě֥r ká̇ţáֽbĕţá̇׃"],[32,33,"וַ⁠יֹּ֥אמֶר יְהוָ֖ה אֶל־מֹשֶׁ֑ה מִ֚י אֲשֶׁ֣ר חָֽטָא־לִ֔⁠י אֶמְחֶ֖⁠נּוּ מִ⁠סִּפְרִֽ⁠י׃","wa⁠yò֥̇ʼmer yĕhwá֖h ʼel-mòşě֑h mi֚y ʼàşě֣r ẖáֽtáʼ-li֔⁠y ʼemĕẖe֖⁠ṅẇ mi⁠si̇pĕriֽ⁠y׃"],[32,34,"וְ⁠עַתָּ֞ה לֵ֣ךְ ׀ נְחֵ֣ה אֶת־הָ⁠עָ֗ם אֶ֤ל אֲשֶׁר־דִּבַּ֨רְתִּי֙ לָ֔⁠ךְ הִנֵּ֥ה מַלְאָכִ֖⁠י יֵלֵ֣ךְ לְ⁠פָנֶ֑י⁠ךָ וּ⁠בְ⁠י֣וֹם פָּקְדִ֔⁠י וּ⁠פָקַדְתִּ֥י עֲלֵי⁠הֶ֖ם חַטָּאתָֽ⁠ם׃","wĕ⁠ʻaţá̇֞h lé֣kĕ ׀ nĕẖé֣h ʼeţ-há⁠ʻá֗m ʼe֤l ʼàşěr-di̇bȧ֨rĕţi̇y֙ lá֔⁠kĕ hiné֥̇h malĕʼáki֖⁠y yélé֣kĕ lĕ⁠páne֑y⁠ká ẇ⁠bĕ⁠y֣wòm pá̇qĕdi֔⁠y ẇ⁠páqadĕţi֥̇y ʻàléy⁠he֖m ẖatá̇ʼţáֽ⁠m׃"],[32,35,"וַ⁠יִּגֹּ֥ף יְהוָ֖ה אֶת־הָ⁠עָ֑ם עַ֚ל אֲשֶׁ֣ר עָשׂ֣וּ אֶת־הָ⁠עֵ֔גֶל אֲשֶׁ֥ר עָשָׂ֖ה אַהֲרֹֽן׃ס","wa⁠yi̇gò֥̇p yĕhwá֖h ʼeţ-há⁠ʻá֑m ʻa֚l ʼàşě֣r ʻáş֣̂ẇ ʼeţ-há⁠ʻé֔gel ʼàşě֥r ʻáşá֖̂h ʼahàròֽn׃s"],[33,1,"וַ⁠יְדַבֵּ֨ר יְהוָ֤ה אֶל־מֹשֶׁה֙ לֵ֣ךְ עֲלֵ֣ה מִ⁠זֶּ֔ה אַתָּ֣ה וְ⁠הָ⁠עָ֔ם אֲשֶׁ֥ר הֶֽעֱלִ֖יתָ מֵ⁠אֶ֣רֶץ מִצְרָ֑יִם אֶל־הָ⁠אָ֗רֶץ אֲשֶׁ֣ר נִ֠שְׁבַּעְתִּי לְ⁠אַבְרָהָ֨ם לְ⁠יִצְחָ֤ק וּֽ⁠לְ⁠יַעֲקֹב֙ לֵ⁠אמֹ֔ר לְ⁠זַרְעֲ⁠ךָ֖ אֶתְּנֶֽ⁠נָּה׃","wa⁠yĕdabé̇֨r yĕhwá֤h ʼel-mòşěh֙ lé֣kĕ ʻàlé֣h mi⁠zė֔h ʼaţá֣̇h wĕ⁠há⁠ʻá֔m ʼàşě֥r hֽeʻèli֖yţá mé⁠ʼe֣reẕ miẕĕrá֑yim ʼel-há⁠ʼá֗reẕ ʼàşě֣r ni֠şĕ̌bȧʻĕţi̇y lĕ⁠ʼabĕráhá֨m lĕ⁠yiẕĕẖá֤q ẇֽ⁠lĕ⁠yaʻàqòb֙ lé⁠ʼmò֔r lĕ⁠zarĕʻà⁠ká֖ ʼeţĕ̇neֽ⁠ná̇h׃"],[33,2,"וְ⁠שָׁלַחְתִּ֥י לְ⁠פָנֶ֖י⁠ךָ מַלְאָ֑ךְ וְ⁠גֵֽרַשְׁתִּ֗י אֶת־הַֽ⁠כְּנַעֲנִי֙ הָֽ⁠אֱמֹרִ֔י וְ⁠הַֽ⁠חִתִּי֙ וְ⁠הַ⁠פְּרִזִּ֔י הַ⁠חִוִּ֖י וְ⁠הַ⁠יְבוּסִֽי׃","wĕ⁠şá̌laẖĕţi֥̇y lĕ⁠páne֖y⁠ká malĕʼá֑kĕ wĕ⁠géֽraşĕ̌ţi̇֗y ʼeţ-haֽ⁠kĕ̇naʻàniy֙ háֽ⁠ʼèmòri֔y wĕ⁠haֽ⁠ẖiţi̇y֙ wĕ⁠ha⁠pĕ̇rizi̇֔y ha⁠ẖiwi֖̇y wĕ⁠ha⁠yĕbẇsiֽy׃"],[33,3,"אֶל־אֶ֛רֶץ זָבַ֥ת חָלָ֖ב וּ⁠דְבָ֑שׁ כִּי֩ לֹ֨א אֶֽעֱלֶ֜ה בְּ⁠קִרְבְּ⁠ךָ֗ כִּ֤י עַם־קְשֵׁה־עֹ֨רֶף֙ אַ֔תָּה פֶּן־אֲכֶלְ⁠ךָ֖ בַּ⁠דָּֽרֶךְ׃","ʼel-ʼe֛reẕ zába֥ţ ẖálá֖b ẇ⁠dĕbá֑ş̌ ki̇y֩ lò֨ʼ ʼeֽʻèle֜h bĕ̇⁠qirĕbĕ̇⁠ká֗ ki֤̇y ʻam-qĕşé̌h-ʻò֨rep֙ ʼa֔ţá̇h pėn-ʼàkelĕ⁠ká֖ bȧ⁠dáֽ̇rekĕ׃"],[33,4,"וַ⁠יִּשְׁמַ֣ע הָ⁠עָ֗ם אֶת־הַ⁠דָּבָ֥ר הָ⁠רָ֛ע הַ⁠זֶּ֖ה וַ⁠יִּתְאַבָּ֑לוּ וְ⁠לֹא־שָׁ֛תוּ אִ֥ישׁ עֶדְי֖⁠וֹ עָלָֽי⁠ו׃","wa⁠yi̇şĕ̌ma֣ʻ há⁠ʻá֗m ʼeţ-ha⁠dá̇bá֥r há⁠rá֛ʻ ha⁠zė֖h wa⁠yi̇ţĕʼabá֑̇lẇ wĕ⁠lòʼ-şá֛̌ţẇ ʼi֥yş̌ ʻedĕy֖⁠wò ʻáláֽy⁠w׃"],[33,5,"וַ⁠יֹּ֨אמֶר יְהוָ֜ה אֶל־מֹשֶׁ֗ה אֱמֹ֤ר אֶל־בְּנֵֽי־יִשְׂרָאֵל֙ אַתֶּ֣ם עַם־קְשֵׁה־עֹ֔רֶף רֶ֧גַע אֶחָ֛ד אֶֽעֱלֶ֥ה בְ⁠קִרְבְּ⁠ךָ֖ וְ⁠כִלִּיתִ֑י⁠ךָ וְ⁠עַתָּ֗ה הוֹרֵ֤ד עֶדְיְ⁠ךָ֙ מֵֽ⁠עָלֶ֔י⁠ךָ וְ⁠אֵדְעָ֖ה מָ֥ה אֶֽעֱשֶׂה־לָּֽ⁠ךְ׃","wa⁠yò̇֨ʼmer yĕhwá֜h ʼel-mòşě֗h ʼèmò֤r ʼel-bĕ̇néֽy-yişĕ̂ráʼél֙ ʼaţė֣m ʻam-qĕşé̌h-ʻò֔rep re֧gaʻ ʼeẖá֛d ʼֽeʻèle֥h bĕ⁠qirĕbĕ̇⁠ká֖ wĕ⁠kili̇yţi֑y⁠ká wĕ⁠ʻaţá̇֗h hwòré֤d ʻedĕyĕ⁠ká֙ méֽ⁠ʻále֔y⁠ká wĕ⁠ʼédĕʻá֖h má֥h ʼeֽʻèşêh-láֽ̇⁠kĕ׃"],[33,6,"וַ⁠יִּֽתְנַצְּל֧וּ בְנֵֽי־יִשְׂרָאֵ֛ל אֶת־עֶדְיָ֖⁠ם מֵ⁠הַ֥ר חוֹרֵֽב׃","wa⁠yiֽ̇ţĕnaẕĕ̇l֧ẇ bĕnéֽy-yişĕ̂ráʼé֛l ʼeţ-ʻedĕyá֖⁠m mé⁠ha֥r ẖwòréֽb׃"],[33,7,"וּ⁠מֹשֶׁה֩ יִקַּ֨ח אֶת־הָ⁠אֹ֜הֶל וְ⁠נָֽטָה־ל֣⁠וֹ ׀ מִ⁠ח֣וּץ לַֽ⁠מַּחֲנֶ֗ה הַרְחֵק֙ מִן־הַֽ⁠מַּחֲנֶ֔ה וְ⁠קָ֥רָא ל֖⁠וֹ אֹ֣הֶל מוֹעֵ֑ד וְ⁠הָיָה֙ כָּל־מְבַקֵּ֣שׁ יְהוָ֔ה יֵצֵא֙ אֶל־אֹ֣הֶל מוֹעֵ֔ד אֲשֶׁ֖ר מִ⁠ח֥וּץ לַֽ⁠מַּחֲנֶֽה׃","ẇ⁠mòşěh֩ yiqȧ֨ẖ ʼeţ-há⁠ʼò֜hel wĕ⁠náֽtáh-l֣⁠wò ׀ mi⁠ẖ֣ẇẕ laֽ⁠mȧẖàne֗h harĕẖéq֙ min-haֽ⁠mȧẖàne֔h wĕ⁠qá֥ráʼ l֖⁠wò ʼò֣hel mwòʻé֑d wĕ⁠háyáh֙ ká̇l-mĕbaqé֣̇ş̌ yĕhwá֔h yéẕéʼ֙ ʼel-ʼò֣hel mwòʻé֔d ʼàşě֖r mi⁠ẖ֥ẇẕ laֽ⁠mȧẖàneֽh׃"],[33,8,"וְ⁠הָיָ֗ה כְּ⁠צֵ֤את מֹשֶׁה֙ אֶל־הָ⁠אֹ֔הֶל יָק֨וּמוּ֙ כָּל־הָ⁠עָ֔ם וְ⁠נִ֨צְּב֔וּ אִ֖ישׁ פֶּ֣תַח אָהֳל֑⁠וֹ וְ⁠הִבִּ֨יטוּ֙ אַחֲרֵ֣י מֹשֶׁ֔ה עַד־בֹּא֖⁠וֹ הָ⁠אֹֽהֱלָ⁠ה׃","wĕ⁠háyá֗h kĕ̇⁠ẕé֤ʼţ mòşěh֙ ʼel-há⁠ʼò֔hel yáq֨ẇmẇ֙ ká̇l-há⁠ʻá֔m wĕ⁠ni֨ẕĕ̇b֔ẇ ʼi֖yş̌ pė֣ţaẖ ʼáhol֑⁠wò wĕ⁠hibi̇֨ytẇ֙ ʼaẖàré֣y mòşě֔h ʻad-bò̇ʼ֖⁠wò há⁠ʼòֽhèlá⁠h׃"],[33,9,"וְ⁠הָיָ֗ה כְּ⁠בֹ֤א מֹשֶׁה֙ הָ⁠אֹ֔הֱלָ⁠ה יֵרֵד֙ עַמּ֣וּד הֶֽ⁠עָנָ֔ן וְ⁠עָמַ֖ד פֶּ֣תַח הָ⁠אֹ֑הֶל וְ⁠דִבֶּ֖ר עִם־מֹשֶֽׁה׃","wĕ⁠háyá֗h kĕ̇⁠bò֤ʼ mòşěh֙ há⁠ʼò֔hèlá⁠h yéréd֙ ʻaṁ֣ẇd heֽ⁠ʻáná֔n wĕ⁠ʻáma֖d pė֣ţaẖ há⁠ʼò֑hel wĕ⁠dibė֖r ʻim-mòşěֽh׃"],[33,10,"וְ⁠רָאָ֤ה כָל־הָ⁠עָם֙ אֶת־עַמּ֣וּד הֶֽ⁠עָנָ֔ן עֹמֵ֖ד פֶּ֣תַח הָ⁠אֹ֑הֶל וְ⁠קָ֤ם כָּל־הָ⁠עָם֙ וְ⁠הִֽשְׁתַּחֲוּ֔וּ אִ֖ישׁ פֶּ֥תַח אָהֳלֽ⁠וֹ׃","wĕ⁠ráʼá֤h kál-há⁠ʻám֙ ʼeţ-ʻaṁ֣ẇd heֽ⁠ʻáná֔n ʻòmé֖d pė֣ţaẖ há⁠ʼò֑hel wĕ⁠qá֤m ká̇l-há⁠ʻám֙ wĕ⁠hiֽşĕ̌ţȧẖàẇ֔ẇ ʼi֖yş̌ pė֥ţaẖ ʼáholֽ⁠wò׃"],[33,11,"וְ⁠דִבֶּ֨ר יְהוָ֤ה אֶל־מֹשֶׁה֙ פָּנִ֣ים אֶל־פָּנִ֔ים כַּ⁠אֲשֶׁ֛ר יְדַבֵּ֥ר אִ֖ישׁ אֶל־רֵעֵ֑⁠הוּ וְ⁠שָׁב֙ אֶל־הַֽ⁠מַּחֲנֶ֔ה וּ⁠מְשָׁ֨רְת֜⁠וֹ יְהוֹשֻׁ֤עַ בִּן־נוּן֙ נַ֔עַר לֹ֥א יָמִ֖ישׁ מִ⁠תּ֥וֹךְ הָ⁠אֹֽהֶל׃ס","wĕ⁠dibė֨r yĕhwá֤h ʼel-mòşěh֙ pá̇ni֣ym ʼel-pá̇ni֔ym kȧ⁠ʼàşě֛r yĕdabé֥̇r ʼi֖yş̌ ʼel-réʻé֑⁠hẇ wĕ⁠şá̌b֙ ʼel-haֽ⁠mȧẖàne֔h ẇ⁠mĕşá̌֨rĕţ֜⁠wò yĕhwòşǔ֤ʻa bi̇n-nẇn֙ na֔ʻar lò֥ʼ yámi֖yş̌ mi⁠ţ֥̇wòkĕ há⁠ʼòֽhel׃s"],[33,12,"וַ⁠יֹּ֨אמֶר מֹשֶׁ֜ה אֶל־יְהוָ֗ה רְ֠אֵה אַתָּ֞ה אֹמֵ֤ר אֵלַ⁠י֙ הַ֚עַל אֶת־הָ⁠עָ֣ם הַ⁠זֶּ֔ה וְ⁠אַתָּה֙ לֹ֣א הֽוֹדַעְתַּ֔⁠נִי אֵ֥ת אֲשֶׁר־תִּשְׁלַ֖ח עִמִּ֑⁠י וְ⁠אַתָּ֤ה אָמַ֨רְתָּ֙ יְדַעְתִּ֣י⁠ךָֽ בְ⁠שֵׁ֔ם וְ⁠גַם־מָצָ֥אתָ חֵ֖ן בְּ⁠עֵינָֽ⁠י׃","wa⁠yò̇֨ʼmer mòşě֜h ʼel-yĕhwá֗h rĕ֠ʼéh ʼaţá̇֞h ʼòmé֤r ʼéla⁠y֙ ha֚ʻal ʼeţ-há⁠ʻá֣m ha⁠zė֔h wĕ⁠ʼaţá̇h֙ lò֣ʼ hֽwòdaʻĕţȧ֔⁠niy ʼé֥ţ ʼàşěr-ţi̇şĕ̌la֖ẖ ʻimi֑̇⁠y wĕ⁠ʼaţá֤̇h ʼáma֨rĕţá̇֙ yĕdaʻĕţi֣̇y⁠káֽ bĕ⁠şé̌֔m wĕ⁠gam-máẕá֥ʼţá ẖé֖n bĕ̇⁠ʻéynáֽ⁠y׃"],[33,13,"וְ⁠עַתָּ֡ה אִם־נָא֩ מָצָ֨אתִי חֵ֜ן בְּ⁠עֵינֶ֗י⁠ךָ הוֹדִעֵ֤⁠נִי נָא֙ אֶת־דְּרָכֶ֔⁠ךָ וְ⁠אֵדָ֣עֲ⁠ךָ֔ לְמַ֥עַן אֶמְצָא־חֵ֖ן בְּ⁠עֵינֶ֑י⁠ךָ וּ⁠רְאֵ֕ה כִּ֥י עַמְּ⁠ךָ֖ הַ⁠גּ֥וֹי הַ⁠זֶּֽה׃","wĕ⁠ʻaţá̇֡h ʼim-náʼ֩ máẕá֨ʼţiy ẖé֜n bĕ̇⁠ʻéyne֗y⁠ká hwòdiʻé֤⁠niy náʼ֙ ʼeţ-dĕ̇ráke֔⁠ká wĕ⁠ʼédá֣ʻà⁠ká֔ lĕma֥ʻan ʼemĕẕáʼ-ẖé֖n bĕ̇⁠ʻéyne֑y⁠ká ẇ⁠rĕʼé֕h ki֥̇y ʻamĕ̇⁠ká֖ ha⁠ġ֥wòy ha⁠zėֽh׃"],[33,14,"וַ⁠יֹּאמַ֑ר פָּנַ֥⁠י יֵלֵ֖כוּ וַ⁠הֲנִחֹ֥תִי לָֽ⁠ךְ׃","wa⁠yò̇ʼma֑r pá̇na֥⁠y yélé֖kẇ wa⁠hàniẖò֥ţiy láֽ⁠kĕ׃"],[33,15,"וַ⁠יֹּ֖אמֶר אֵלָ֑י⁠ו אִם־אֵ֤ין פָּנֶ֨י⁠ךָ֙ הֹלְכִ֔ים אַֽל־תַּעֲלֵ֖⁠נוּ מִ⁠זֶּֽה׃","wa⁠yò֖̇ʼmer ʼélá֑y⁠w ʼim-ʼé֤yn pá̇ne֨y⁠ká֙ hòlĕki֔ym ʼaֽl-ţȧʻàlé֖⁠nẇ mi⁠zėֽh׃"],[33,16,"וּ⁠בַ⁠מֶּ֣ה ׀ יִוָּדַ֣ע אֵפ֗וֹא כִּֽי־מָצָ֨אתִי חֵ֤ן בְּ⁠עֵינֶ֨י⁠ךָ֙ אֲנִ֣י וְ⁠עַמֶּ֔⁠ךָ הֲ⁠ל֖וֹא בְּ⁠לֶכְתְּ⁠ךָ֣ עִמָּ֑⁠נוּ וְ⁠נִפְלֵ֨ינוּ֙ אֲנִ֣י וְ⁠עַמְּ⁠ךָ֔ מִ⁠כָּ֨ל־הָ⁠עָ֔ם אֲשֶׁ֖ר עַל־פְּנֵ֥י הָ⁠אֲדָמָֽה׃פ","ẇ⁠ba⁠mė֣h ׀ yiwá̇da֣ʻ ʼép֗wòʼ kiֽ̇y-máẕá֨ʼţiy ẖé֤n bĕ̇⁠ʻéyne֨y⁠ká֙ ʼàni֣y wĕ⁠ʻamė֔⁠ká hà⁠l֖wòʼ bĕ̇⁠lekĕţĕ̇⁠ká֣ ʻimá֑̇⁠nẇ wĕ⁠nipĕlé֨ynẇ֙ ʼàni֣y wĕ⁠ʻamĕ̇⁠ká֔ mi⁠ká̇֨l-há⁠ʻá֔m ʼàşě֖r ʻal-pĕ̇né֥y há⁠ʼàdámáֽh׃p"],[33,17,"וַ⁠יֹּ֤אמֶר יְהוָה֙ אֶל־מֹשֶׁ֔ה גַּ֣ם אֶת־הַ⁠דָּבָ֥ר הַ⁠זֶּ֛ה אֲשֶׁ֥ר דִּבַּ֖רְתָּ אֶֽעֱשֶׂ֑ה כִּֽי־מָצָ֤אתָ חֵן֙ בְּ⁠עֵינַ֔⁠י וָ⁠אֵדָעֲ⁠ךָ֖ בְּ⁠שֵֽׁם׃","wa⁠yò֤̇ʼmer yĕhwáh֙ ʼel-mòşě֔h gȧ֣m ʼeţ-ha⁠dá̇bá֥r ha⁠zė֛h ʼàşě֥r di̇bȧ֖rĕţá̇ ʼeֽʻèşê֑h kiֽ̇y-máẕá֤ʼţá ẖén֙ bĕ̇⁠ʻéyna֔⁠y wá⁠ʼédáʻà⁠ká֖ bĕ̇⁠şéֽ̌m׃"],[33,18,"וַ⁠יֹּאמַ֑ר הַרְאֵ֥⁠נִי נָ֖א אֶת־כְּבֹדֶֽ⁠ךָ׃","wa⁠yò̇ʼma֑r harĕʼé֥⁠niy ná֖ʼ ʼeţ-kĕ̇bòdeֽ⁠ká׃"],[33,19,"וַ⁠יֹּ֗אמֶר אֲנִ֨י אַעֲבִ֤יר כָּל־טוּבִ⁠י֙ עַל־פָּנֶ֔י⁠ךָ וְ⁠קָרָ֧אתִֽי בְ⁠שֵׁ֛ם יְהוָ֖ה לְ⁠פָנֶ֑י⁠ךָ וְ⁠חַנֹּתִי֙ אֶת־אֲשֶׁ֣ר אָחֹ֔ן וְ⁠רִחַמְתִּ֖י אֶת־אֲשֶׁ֥ר אֲרַחֵֽם׃","wa⁠yò̇֗ʼmer ʼàni֨y ʼaʻàbi֤yr ká̇l-tẇbi⁠y֙ ʻal-pá̇ne֔y⁠ká wĕ⁠qárá֧ʼţiֽy bĕ⁠şé֛̌m yĕhwá֖h lĕ⁠páne֑y⁠ká wĕ⁠ẖanò̇ţiy֙ ʼeţ-ʼàşě֣r ʼáẖò֔n wĕ⁠riẖamĕţi֖̇y ʼeţ-ʼàşě֥r ʼàraẖéֽm׃"],[33,20,"וַ⁠יֹּ֕אמֶר לֹ֥א תוּכַ֖ל לִ⁠רְאֹ֣ת אֶת־פָּנָ֑⁠י כִּ֛י לֹֽא־יִרְאַ֥⁠נִי הָ⁠אָדָ֖ם וָ⁠חָֽי׃","wa⁠yò̇֕ʼmer lò֥ʼ ţẇka֖l li⁠rĕʼò֣ţ ʼeţ-pá̇ná֑⁠y ki֛̇y lòֽʼ-yirĕʼa֥⁠niy há⁠ʼádá֖m wá⁠ẖáֽy׃"],[33,21,"וַ⁠יֹּ֣אמֶר יְהוָ֔ה הִנֵּ֥ה מָק֖וֹם אִתִּ֑⁠י וְ⁠נִצַּבְתָּ֖ עַל־הַ⁠צּֽוּר׃","wa⁠yò֣̇ʼmer yĕhwá֔h hiné֥̇h máq֖wòm ʼiţi֑̇⁠y wĕ⁠niẕȧbĕţá֖̇ ʻal-ha⁠ẕֽ̇ẇr׃"],[33,22,"וְ⁠הָיָה֙ בַּ⁠עֲבֹ֣ר כְּבֹדִ֔⁠י וְ⁠שַׂמְתִּ֖י⁠ךָ בְּ⁠נִקְרַ֣ת הַ⁠צּ֑וּר וְ⁠שַׂכֹּתִ֥י כַפִּ֛⁠י עָלֶ֖י⁠ךָ עַד־עָבְרִֽ⁠י׃","wĕ⁠háyáh֙ bȧ⁠ʻàbò֣r kĕ̇bòdi֔⁠y wĕ⁠şâmĕţi֖̇y⁠ká bĕ̇⁠niqĕra֣ţ ha⁠ẕ֑̇ẇr wĕ⁠şâkò̇ţi֥y kapi֛̇⁠y ʻále֖y⁠ká ʻad-ʻábĕriֽ⁠y׃"],[33,23,"וַ⁠הֲסִרֹתִי֙ אֶת־כַּפִּ֔⁠י וְ⁠רָאִ֖יתָ אֶת־אֲחֹרָ֑⁠י וּ⁠פָנַ֖⁠י לֹ֥א יֵרָאֽוּ׃ס","wa⁠hàsiròţiy֙ ʼeţ-kȧpi̇֔⁠y wĕ⁠ráʼi֖yţá ʼeţ-ʼàẖòrá֑⁠y ẇ⁠pána֖⁠y lò֥ʼ yéráʼֽẇ׃s"],[34,1,"וַ⁠יֹּ֤אמֶר יְהוָה֙ אֶל־מֹשֶׁ֔ה פְּסָל־לְ⁠ךָ֛ שְׁנֵֽי־לֻחֹ֥ת אֲבָנִ֖ים כָּ⁠רִאשֹׁנִ֑ים וְ⁠כָתַבְתִּי֙ עַל־הַ⁠לֻּחֹ֔ת אֶת־הַ⁠דְּבָרִ֔ים אֲשֶׁ֥ר הָי֛וּ עַל־הַ⁠לֻּחֹ֥ת הָ⁠רִאשֹׁנִ֖ים אֲשֶׁ֥ר שִׁבַּֽרְתָּ׃","wa⁠yò֤̇ʼmer yĕhwáh֙ ʼel-mòşě֔h pĕ̇sál-lĕ⁠ká֛ şĕ̌néֽy-luẖò֥ţ ʼàbáni֖ym ká̇⁠riʼşò̌ni֑ym wĕ⁠káţabĕţi̇y֙ ʻal-ha⁠lu̇ẖò֔ţ ʼeţ-ha⁠dĕ̇bári֔ym ʼàşě֥r háy֛ẇ ʻal-ha⁠lu̇ẖò֥ţ há⁠riʼşò̌ni֖ym ʼàşě֥r şǐbȧֽrĕţá̇׃"],[34,2,"וֶ⁠הְיֵ֥ה נָכ֖וֹן לַ⁠בֹּ֑קֶר וְ⁠עָלִ֤יתָ בַ⁠בֹּ֨קֶר֙ אֶל־הַ֣ר סִינַ֔י וְ⁠נִצַּבְתָּ֥ לִ֛⁠י שָׁ֖ם עַל־רֹ֥אשׁ הָ⁠הָֽר׃","we⁠hĕyé֥h nák֖wòn la⁠bò֑̇qer wĕ⁠ʻáli֤yţá ba⁠bò̇֨qer֙ ʼel-ha֣r siyna֔y wĕ⁠niẕȧbĕţá֥̇ li֛⁠y şá֖̌m ʻal-rò֥ʼş̌ há⁠háֽr׃"],[34,3,"וְ⁠אִישׁ֙ לֹֽא־יַעֲלֶ֣ה עִמָּ֔⁠ךְ וְ⁠גַם־אִ֥ישׁ אַל־יֵרָ֖א בְּ⁠כָל־הָ⁠הָ֑ר גַּם־הַ⁠צֹּ֤אן וְ⁠הַ⁠בָּקָר֙ אַל־יִרְע֔וּ אֶל־מ֖וּל הָ⁠הָ֥ר הַ⁠הֽוּא׃","wĕ⁠ʼiyş̌֙ lòֽʼ-yaʻàle֣h ʻimá̇֔⁠kĕ wĕ⁠gam-ʼi֥yş̌ ʼal-yérá֖ʼ bĕ̇⁠kál-há⁠há֑r gȧm-ha⁠ẕò֤̇ʼn wĕ⁠ha⁠bá̇qár֙ ʼal-yirĕʻ֔ẇ ʼel-m֖ẇl há⁠há֥r ha⁠hֽẇʼ׃"],[34,4,"וַ⁠יִּפְסֹ֡ל שְׁנֵֽי־לֻחֹ֨ת אֲבָנִ֜ים כָּ⁠רִאשֹׁנִ֗ים וַ⁠יַּשְׁכֵּ֨ם מֹשֶׁ֤ה בַ⁠בֹּ֨קֶר֙ וַ⁠יַּ֨עַל֙ אֶל־הַ֣ר סִינַ֔י כַּ⁠אֲשֶׁ֛ר צִוָּ֥ה יְהוָ֖ה אֹת֑⁠וֹ וַ⁠יִּקַּ֣ח בְּ⁠יָד֔⁠וֹ שְׁנֵ֖י לֻחֹ֥ת אֲבָנִֽים׃","wa⁠yi̇pĕsò֡l şĕ̌néֽy-luẖò֨ţ ʼàbáni֜ym ká̇⁠riʼşò̌ni֗ym wa⁠yȧşĕ̌ké̇֨m mòşě֤h ba⁠bò̇֨qer֙ wa⁠yȧ֨ʻal֙ ʼel-ha֣r siyna֔y kȧ⁠ʼàşě֛r ẕiwá֥̇h yĕhwá֖h ʼòţ֑⁠wò wa⁠yi̇qȧ֣ẖ bĕ̇⁠yád֔⁠wò şĕ̌né֖y luẖò֥ţ ʼàbániֽym׃"],[34,5,"וַ⁠יֵּ֤רֶד יְהוָה֙ בֶּֽ⁠עָנָ֔ן וַ⁠יִּתְיַצֵּ֥ב עִמּ֖⁠וֹ שָׁ֑ם וַ⁠יִּקְרָ֥א בְ⁠שֵׁ֖ם יְהוָֽה׃","wa⁠yé֤̇red yĕhwáh֙ bėֽ⁠ʻáná֔n wa⁠yi̇ţĕyaẕé֥̇b ʻiṁ֖⁠wò şá֑̌m wa⁠yi̇qĕrá֥ʼ bĕ⁠şé֖̌m yĕhwáֽh׃"],[34,6,"וַ⁠יַּעֲבֹ֨ר יְהוָ֥ה ׀ עַל־פָּנָי⁠ו֮ וַ⁠יִּקְרָא֒ יְהוָ֣ה ׀ יְהוָ֔ה אֵ֥ל רַח֖וּם וְ⁠חַנּ֑וּן אֶ֥רֶךְ אַפַּ֖יִם וְ⁠רַב־חֶ֥סֶד וֶ⁠אֱמֶֽת ׀","wa⁠yȧʻàbò֨r yĕhwá֥h ׀ ʻal-pá̇náy⁠w֮ wa⁠yi̇qĕráʼ֒ yĕhwá֣h ׀ yĕhwá֔h ʼé֥l raẖ֖ẇm wĕ⁠ẖaṅ֑ẇn ʼe֥rekĕ ʼapȧ֖yim wĕ⁠rab-ẖe֥sed we⁠ʼèmeֽţ ׀"],[34,7,"נֹצֵ֥ר חֶ֨סֶד֙ לָ⁠אֲלָפִ֔ים נֹשֵׂ֥א עָוֺ֛ן וָ⁠פֶ֖שַׁע וְ⁠חַטָּאָ֑ה וְ⁠נַקֵּה֙ לֹ֣א יְנַקֶּ֔ה פֹּקֵ֣ד ׀ עֲוֺ֣ן אָב֗וֹת עַל־בָּנִים֙ וְ⁠עַל־בְּנֵ֣י בָנִ֔ים עַל־שִׁלֵּשִׁ֖ים וְ⁠עַל־רִבֵּעִֽים׃","nòẕé֥r ẖe֨sed֙ lá⁠ʼàlápi֔ym nòşé֥̂ʼ ʻáwֺ֛n wá⁠pe֖şǎʻ wĕ⁠ẖatá̇ʼá֑h wĕ⁠naqé̇h֙ lò֣ʼ yĕnaqė֔h pò̇qé֣d ׀ ʻàwֺ֣n ʼáb֗wòţ ʻal-bá̇niym֙ wĕ⁠ʻal-bĕ̇né֣y báni֔ym ʻal-şǐlé̇şǐ֖ym wĕ⁠ʻal-ribé̇ʻiֽym׃"],[34,8,"וַ⁠יְמַהֵ֖ר מֹשֶׁ֑ה וַ⁠יִּקֹּ֥ד אַ֖רְצָ⁠ה וַ⁠יִּשְׁתָּֽחוּ׃","wa⁠yĕmahé֖r mòşě֑h wa⁠yi̇qò֥̇d ʼa֖rĕẕá⁠h wa⁠yi̇şĕ̌ţáֽ̇ẖẇ׃"],[34,9,"וַ⁠יֹּ֡אמֶר אִם־נָא֩ מָצָ֨אתִי חֵ֤ן בְּ⁠עֵינֶ֨י⁠ךָ֙ אֲדֹנָ֔⁠י יֵֽלֶךְ־נָ֥א אֲדֹנָ֖⁠י בְּ⁠קִרְבֵּ֑⁠נוּ כִּ֤י עַם־קְשֵׁה־עֹ֨רֶף֙ ה֔וּא וְ⁠סָלַחְתָּ֛ לַ⁠עֲוֺנֵ֥⁠נוּ וּ⁠לְ⁠חַטָּאתֵ֖⁠נוּ וּ⁠נְחַלְתָּֽ⁠נוּ׃","wa⁠yò̇֡ʼmer ʼim-náʼ֩ máẕá֨ʼţiy ẖé֤n bĕ̇⁠ʻéyne֨y⁠ká֙ ʼàdòná֔⁠y yéֽlekĕ-ná֥ʼ ʼàdòná֖⁠y bĕ̇⁠qirĕbé֑̇⁠nẇ ki֤̇y ʻam-qĕşé̌h-ʻò֨rep֙ h֔ẇʼ wĕ⁠sálaẖĕţá֛̇ la⁠ʻàwֺné֥⁠nẇ ẇ⁠lĕ⁠ẖatá̇ʼţé֖⁠nẇ ẇ⁠nĕẖalĕţáֽ̇⁠nẇ׃"],[34,10,"וַ⁠יֹּ֗אמֶר הִנֵּ֣ה אָנֹכִי֮ כֹּרֵ֣ת בְּרִית֒ נֶ֤גֶד כָּֽל־עַמְּ⁠ךָ֙ אֶעֱשֶׂ֣ה נִפְלָאֹ֔ת אֲשֶׁ֛ר לֹֽא־נִבְרְא֥וּ בְ⁠כָל־הָ⁠אָ֖רֶץ וּ⁠בְ⁠כָל־הַ⁠גּוֹיִ֑ם וְ⁠רָאָ֣ה כָל־הָ֠⁠עָם אֲשֶׁר־אַתָּ֨ה בְ⁠קִרְבּ֜⁠וֹ אֶת־מַעֲשֵׂ֤ה יְהוָה֙ כִּֽי־נוֹרָ֣א ה֔וּא אֲשֶׁ֥ר אֲנִ֖י עֹשֶׂ֥ה עִמָּֽ⁠ךְ׃","wa⁠yò̇֗ʼmer hiné֣̇h ʼánòkiy֮ kò̇ré֣ţ bĕ̇riyţ֒ ne֤ged káֽ̇l-ʻamĕ̇⁠ká֙ ʼeʻèşê֣h nipĕláʼò֔ţ ʼàşě֛r lòֽʼ-nibĕrĕʼ֥ẇ bĕ⁠kál-há⁠ʼá֖reẕ ẇ⁠bĕ⁠kál-ha⁠ġwòyi֑m wĕ⁠ráʼá֣h kál-há֠⁠ʻám ʼàşěr-ʼaţá̇֨h bĕ⁠qirĕḃ֜⁠wò ʼeţ-maʻàşé֤̂h yĕhwáh֙ kiֽ̇y-nwòrá֣ʼ h֔ẇʼ ʼàşě֥r ʼàni֖y ʻòşê֥h ʻimáֽ̇⁠kĕ׃"],[34,11,"שְׁמָ֨ר־לְ⁠ךָ֔ אֵ֛ת אֲשֶׁ֥ר אָנֹכִ֖י מְצַוְּ⁠ךָ֣ הַ⁠יּ֑וֹם הִנְ⁠נִ֧י גֹרֵ֣שׁ מִ⁠פָּנֶ֗י⁠ךָ אֶת־הָ⁠אֱמֹרִי֙ וְ⁠הַֽ⁠כְּנַעֲנִ֔י וְ⁠הַ⁠חִתִּי֙ וְ⁠הַ⁠פְּרִזִּ֔י וְ⁠הַ⁠חִוִּ֖י וְ⁠הַ⁠יְבוּסִֽי׃","şĕ̌má֨r-lĕ⁠ká֔ ʼé֛ţ ʼàşě֥r ʼánòki֖y mĕẕawĕ̇⁠ká֣ ha⁠ẏ֑wòm hinĕ⁠ni֧y gòré֣ş̌ mi⁠pá̇ne֗y⁠ká ʼeţ-há⁠ʼèmòriy֙ wĕ⁠haֽ⁠kĕ̇naʻàni֔y wĕ⁠ha⁠ẖiţi̇y֙ wĕ⁠ha⁠pĕ̇rizi̇֔y wĕ⁠ha⁠ẖiwi֖̇y wĕ⁠ha⁠yĕbẇsiֽy׃"],[34,12,"הִשָּׁ֣מֶר לְ⁠ךָ֗ פֶּן־תִּכְרֹ֤ת בְּרִית֙ לְ⁠יוֹשֵׁ֣ב הָ⁠אָ֔רֶץ אֲשֶׁ֥ר אַתָּ֖ה בָּ֣א עָלֶ֑י⁠הָ פֶּן־יִהְיֶ֥ה לְ⁠מוֹקֵ֖שׁ בְּ⁠קִרְבֶּֽ⁠ךָ׃","hişá֣̇̌mer lĕ⁠ká֗ pėn-ţi̇kĕrò֤ţ bĕ̇riyţ֙ lĕ⁠ywòşé֣̌b há⁠ʼá֔reẕ ʼàşě֥r ʼaţá֖̇h bá֣̇ʼ ʻále֑y⁠há pėn-yihĕye֥h lĕ⁠mwòqé֖ş̌ bĕ̇⁠qirĕbėֽ⁠ká׃"],[34,13,"כִּ֤י אֶת־מִזְבְּחֹתָ⁠ם֙ תִּתֹּצ֔וּ⁠ן וְ⁠אֶת־מַצֵּבֹתָ֖⁠ם תְּשַׁבֵּר֑וּ⁠ן וְ⁠אֶת־אֲשֵׁרָ֖י⁠ו תִּכְרֹתֽוּ⁠ן׃","ki֤̇y ʼeţ-mizĕbĕ̇ẖòţá⁠m֙ ţi̇ţò̇ẕ֔ẇ⁠n wĕ⁠ʼeţ-maẕé̇bòţá֖⁠m ţĕ̇şǎbé̇r֑ẇ⁠n wĕ⁠ʼeţ-ʼàşé̌rá֖y⁠w ţi̇kĕròţֽẇ⁠n׃"],[34,14,"כִּ֛י לֹ֥א תִֽשְׁתַּחֲוֶ֖ה לְ⁠אֵ֣ל אַחֵ֑ר כִּ֤י יְהוָה֙ קַנָּ֣א שְׁמ֔⁠וֹ אֵ֥ל קַנָּ֖א הֽוּא׃","ki֛̇y lò֥ʼ ţiֽşĕ̌ţȧẖàwe֖h lĕ⁠ʼé֣l ʼaẖé֑r ki֤̇y yĕhwáh֙ qaná֣̇ʼ şĕ̌m֔⁠wò ʼé֥l qaná֖̇ʼ hֽẇʼ׃"],[34,15,"פֶּן־תִּכְרֹ֥ת בְּרִ֖ית לְ⁠יוֹשֵׁ֣ב הָ⁠אָ֑רֶץ וְ⁠זָנ֣וּ ׀ אַחֲרֵ֣י אֱלֹֽהֵי⁠הֶ֗ם וְ⁠זָבְחוּ֙ לֵ⁠אלֹ֣הֵי⁠הֶ֔ם וְ⁠קָרָ֣א לְ⁠ךָ֔ וְ⁠אָכַלְתָּ֖ מִ⁠זִּבְחֽ⁠וֹ׃","pėn-ţi̇kĕrò֥ţ bĕ̇ri֖yţ lĕ⁠ywòşé֣̌b há⁠ʼá֑reẕ wĕ⁠zán֣ẇ ׀ ʼaẖàré֣y ʼèlòֽhéy⁠he֗m wĕ⁠zábĕẖẇ֙ lé⁠ʼlò֣héy⁠he֔m wĕ⁠qárá֣ʼ lĕ⁠ká֔ wĕ⁠ʼákalĕţá֖̇ mi⁠zi̇bĕẖֽ⁠wò׃"],[34,16,"וְ⁠לָקַחְתָּ֥ מִ⁠בְּנֹתָ֖י⁠ו לְ⁠בָנֶ֑י⁠ךָ וְ⁠זָנ֣וּ בְנֹתָ֗י⁠ו אַחֲרֵי֙ אֱלֹ֣הֵי⁠הֶ֔ן וְ⁠הִזְנוּ֙ אֶת־בָּנֶ֔י⁠ךָ אַחֲרֵ֖י אֱלֹהֵי⁠הֶֽן׃","wĕ⁠láqaẖĕţá֥̇ mi⁠bĕ̇nòţá֖y⁠w lĕ⁠báne֑y⁠ká wĕ⁠zán֣ẇ bĕnòţá֗y⁠w ʼaẖàréy֙ ʼèlò֣héy⁠he֔n wĕ⁠hizĕnẇ֙ ʼeţ-bá̇ne֔y⁠ká ʼaẖàré֖y ʼèlòhéy⁠heֽn׃"],[34,17,"אֱלֹהֵ֥י מַסֵּכָ֖ה לֹ֥א תַעֲשֶׂה־לָּֽ⁠ךְ׃","ʼèlòhé֥y masé̇ká֖h lò֥ʼ ţaʻàşêh-láֽ̇⁠kĕ׃"],[34,18,"אֶת־חַ֣ג הַ⁠מַּצּוֹת֮ תִּשְׁמֹר֒ שִׁבְעַ֨ת יָמִ֜ים תֹּאכַ֤ל מַצּוֹת֙ אֲשֶׁ֣ר צִוִּיתִ֔⁠ךָ לְ⁠מוֹעֵ֖ד חֹ֣דֶשׁ הָ⁠אָבִ֑יב כִּ֚י בְּ⁠חֹ֣דֶשׁ הָֽ⁠אָבִ֔יב יָצָ֖אתָ מִ⁠מִּצְרָֽיִם׃","ʼeţ-ẖa֣g ha⁠mȧẕ̇wòţ֮ ţi̇şĕ̌mòr֒ şǐbĕʻa֨ţ yámi֜ym ţò̇ʼka֤l maẕ̇wòţ֙ ʼàşě֣r ẕiwi̇yţi֔⁠ká lĕ⁠mwòʻé֖d ẖò֣deş̌ há⁠ʼábi֑yb ki֚̇y bĕ̇⁠ẖò֣deş̌ háֽ⁠ʼábi֔yb yáẕá֖ʼţá mi⁠mi̇ẕĕráֽyim׃"],[34,19,"כָּל־פֶּ֥טֶר רֶ֖חֶם לִ֑⁠י וְ⁠כָֽל־מִקְנְ⁠ךָ֙ תִּזָּכָ֔ר פֶּ֖טֶר שׁ֥וֹר וָ⁠שֶֽׂה׃","ká̇l-pė֥ter re֖ẖem li֑⁠y wĕ⁠káֽl-miqĕnĕ⁠ká֙ ţi̇zá̇ká֔r pė֖ter ş֥̌wòr wá⁠şêֽh׃"],[34,20,"וּ⁠פֶ֤טֶר חֲמוֹר֙ תִּפְדֶּ֣ה בְ⁠שֶׂ֔ה וְ⁠אִם־לֹ֥א תִפְדֶּ֖ה וַ⁠עֲרַפְתּ֑⁠וֹ כֹּ֣ל בְּכ֤וֹר בָּנֶ֨י⁠ךָ֙ תִּפְדֶּ֔ה וְ⁠לֹֽא־יֵרָא֥וּ פָנַ֖⁠י רֵיקָֽם׃","ẇ⁠pe֤ter ẖàmwòr֙ ţi̇pĕdė֣h bĕ⁠şê֔h wĕ⁠ʼim-lò֥ʼ ţipĕdė֖h wa⁠ʻàrapĕţ֑̇⁠wò kò֣̇l bĕ̇k֤wòr bá̇ne֨y⁠ká֙ ţi̇pĕdė֔h wĕ⁠lòֽʼ-yéráʼ֥ẇ pána֖⁠y réyqáֽm׃"],[34,21,"שֵׁ֤שֶׁת יָמִים֙ תַּעֲבֹ֔ד וּ⁠בַ⁠יּ֥וֹם הַ⁠שְּׁבִיעִ֖י תִּשְׁבֹּ֑ת בֶּ⁠חָרִ֥ישׁ וּ⁠בַ⁠קָּצִ֖יר תִּשְׁבֹּֽת׃","şé֤̌şěţ yámiym֙ ţȧʻàbò֔d ẇ⁠ba⁠ẏ֥wòm ha⁠şĕ̇̌biyʻi֖y ţi̇şĕ̌bò֑̇ţ bė⁠ẖári֥yş̌ ẇ⁠ba⁠qá̇ẕi֖yr ţi̇şĕ̌bòֽ̇ţ׃"],[34,22,"וְ⁠חַ֤ג שָׁבֻעֹת֙ תַּעֲשֶׂ֣ה לְ⁠ךָ֔ בִּכּוּרֵ֖י קְצִ֣יר חִטִּ֑ים וְ⁠חַג֙ הָֽ⁠אָסִ֔יף תְּקוּפַ֖ת הַ⁠שָּׁנָֽה׃","wĕ⁠ẖa֤g şá̌buʻòţ֙ ţȧʻàşê֣h lĕ⁠ká֔ bi̇k̇ẇré֖y qĕẕi֣yr ẖiti֑̇ym wĕ⁠ẖag֙ háֽ⁠ʼási֔yp ţĕ̇qẇpa֖ţ ha⁠şá̇̌náֽh׃"],[34,23,"שָׁלֹ֥שׁ פְּעָמִ֖ים בַּ⁠שָּׁנָ֑ה יֵרָאֶה֙ כָּל־זְכ֣וּרְ⁠ךָ֔ אֶת־פְּנֵ֛י הָֽ⁠אָדֹ֥ן ׀ יְהוָ֖ה אֱלֹהֵ֥י יִשְׂרָאֵֽל׃","şá̌lò֥ş̌ pĕ̇ʻámi֖ym bȧ⁠şá̇̌ná֑h yéráʼeh֙ ká̇l-zĕk֣ẇrĕ⁠ká֔ ʼeţ-pĕ̇né֛y háֽ⁠ʼádò֥n ׀ yĕhwá֖h ʼèlòhé֥y yişĕ̂ráʼéֽl׃"],[34,24,"כִּֽי־אוֹרִ֤ישׁ גּוֹיִם֙ מִ⁠פָּנֶ֔י⁠ךָ וְ⁠הִרְחַבְתִּ֖י אֶת־גְּבוּלֶ֑⁠ךָ וְ⁠לֹא־יַחְמֹ֥ד אִישׁ֙ אֶֽת־אַרְצְ⁠ךָ֔ בַּ⁠עֲלֹֽתְ⁠ךָ֗ לֵ⁠רָאוֹת֙ אֶת־פְּנֵי֙ יְהוָ֣ה אֱלֹהֶ֔י⁠ךָ שָׁלֹ֥שׁ פְּעָמִ֖ים בַּ⁠שָּׁנָֽה׃","kiֽ̇y-ʼwòri֤yş̌ ġwòyim֙ mi⁠pá̇ne֔y⁠ká wĕ⁠hirĕẖabĕţi֖̇y ʼeţ-gĕ̇bẇle֑⁠ká wĕ⁠lòʼ-yaẖĕmò֥d ʼiyş̌֙ ʼeֽţ-ʼarĕẕĕ⁠ká֔ bȧ⁠ʻàlòֽţĕ⁠ká֗ lé⁠ráʼwòţ֙ ʼeţ-pĕ̇néy֙ yĕhwá֣h ʼèlòhe֔y⁠ká şá̌lò֥ş̌ pĕ̇ʻámi֖ym bȧ⁠şá̇̌náֽh׃"],[34,25,"לֹֽא־תִשְׁחַ֥ט עַל־חָמֵ֖ץ דַּם־זִבְחִ֑⁠י וְ⁠לֹא־יָלִ֣ין לַ⁠בֹּ֔קֶר זֶ֖בַח חַ֥ג הַ⁠פָּֽסַח׃","lòֽʼ-ţişĕ̌ẖa֥t ʻal-ẖámé֖ẕ dȧm-zibĕẖi֑⁠y wĕ⁠lòʼ-yáli֣yn la⁠bò̇֔qer ze֖baẖ ẖa֥g ha⁠páֽ̇saẖ׃"],[34,26,"רֵאשִׁ֗ית בִּכּוּרֵי֙ אַדְמָ֣תְ⁠ךָ֔ תָּבִ֕יא בֵּ֖ית יְהוָ֣ה אֱלֹהֶ֑י⁠ךָ לֹא־תְבַשֵּׁ֥ל גְּדִ֖י בַּ⁠חֲלֵ֥ב אִמּֽ⁠וֹ׃פ","réʼşǐ֗yţ bi̇k̇ẇréy֙ ʼadĕmá֣ţĕ⁠ká֔ ţá̇bi֕yʼ bé֖̇yţ yĕhwá֣h ʼèlòhe֑y⁠ká lòʼ-ţĕbaşé֥̇̌l gĕ̇di֖y bȧ⁠ẖàlé֥b ʼiṁֽ⁠wò׃p"],[34,27,"וַ⁠יֹּ֤אמֶר יְהוָה֙ אֶל־מֹשֶׁ֔ה כְּתָב־לְ⁠ךָ֖ אֶת־הַ⁠דְּבָרִ֣ים הָ⁠אֵ֑לֶּה כִּ֞י עַל־פִּ֣י ׀ הַ⁠דְּבָרִ֣ים הָ⁠אֵ֗לֶּה כָּרַ֧תִּי אִתְּ⁠ךָ֛ בְּרִ֖ית וְ⁠אֶת־יִשְׂרָאֵֽל׃","wa⁠yò֤̇ʼmer yĕhwáh֙ ʼel-mòşě֔h kĕ̇ţáb-lĕ⁠ká֖ ʼeţ-ha⁠dĕ̇bári֣ym há⁠ʼé֑lėh ki̇֞y ʻal-pi֣̇y ׀ ha⁠dĕ̇bári֣ym há⁠ʼé֗lėh ká̇ra֧ţi̇y ʼiţĕ̇⁠ká֛ bĕ̇ri֖yţ wĕ⁠ʼeţ-yişĕ̂ráʼéֽl׃"],[34,28,"וַֽ⁠יְהִי־שָׁ֣ם עִם־יְהוָ֗ה אַרְבָּעִ֥ים יוֹם֙ וְ⁠אַרְבָּעִ֣ים לַ֔יְלָה לֶ֚חֶם לֹ֣א אָכַ֔ל וּ⁠מַ֖יִם לֹ֣א שָׁתָ֑ה וַ⁠יִּכְתֹּ֣ב עַל־הַ⁠לֻּחֹ֗ת אֵ֚ת דִּבְרֵ֣י הַ⁠בְּרִ֔ית עֲשֶׂ֖רֶת הַ⁠דְּבָרִֽים׃","wֽa⁠yĕhiy-şá֣̌m ʻim-yĕhwá֗h ʼarĕbá̇ʻi֥ym ywòm֙ wĕ⁠ʼarĕbá̇ʻi֣ym la֔yĕláh le֚ẖem lò֣ʼ ʼáka֔l ẇ⁠ma֖yim lò֣ʼ şá̌ţá֑h wa⁠yi̇kĕţò֣̇b ʻal-ha⁠lu̇ẖò֗ţ ʼé֚ţ di̇bĕré֣y ha⁠bĕ̇ri֔yţ ʻàşê֖reţ ha⁠dĕ̇báriֽym׃"],[34,29,"וַ⁠יְהִ֗י בְּ⁠רֶ֤דֶת מֹשֶׁה֙ מֵ⁠הַ֣ר סִינַ֔י וּ⁠שְׁנֵ֨י לֻחֹ֤ת הָֽ⁠עֵדֻת֙ בְּ⁠יַד־מֹשֶׁ֔ה בְּ⁠רִדְתּ֖⁠וֹ מִן־הָ⁠הָ֑ר וּ⁠מֹשֶׁ֣ה לֹֽא־יָדַ֗ע כִּ֥י קָרַ֛ן ע֥וֹר פָּנָ֖י⁠ו בְּ⁠דַבְּר֥⁠וֹ אִתּֽ⁠וֹ׃","wa⁠yĕhi֗y bĕ̇⁠re֤deţ mòşěh֙ mé⁠ha֣r siyna֔y ẇ⁠şĕ̌né֨y luẖò֤ţ háֽ⁠ʻéduţ֙ bĕ̇⁠yad-mòşě֔h bĕ̇⁠ridĕţ֖̇⁠wò min-há⁠há֑r ẇ⁠mòşě֣h lòֽʼ-yáda֗ʻ ki֥̇y qára֛n ʻ֥wòr pá̇ná֖y⁠w bĕ̇⁠dabĕ̇r֥⁠wò ʼiţֽ̇⁠wò׃"],[34,30,"וַ⁠יַּ֨רְא אַהֲרֹ֜ן וְ⁠כָל־בְּנֵ֤י יִשְׂרָאֵל֙ אֶת־מֹשֶׁ֔ה וְ⁠הִנֵּ֥ה קָרַ֖ן ע֣וֹר פָּנָ֑י⁠ו וַ⁠יִּֽירְא֖וּ מִ⁠גֶּ֥שֶׁת אֵלָֽי⁠ו׃","wa⁠yȧ֨rĕʼ ʼahàrò֜n wĕ⁠kál-bĕ̇né֤y yişĕ̂ráʼél֙ ʼeţ-mòşě֔h wĕ⁠hiné֥̇h qára֖n ʻ֣wòr pá̇ná֑y⁠w wa⁠yiֽ̇yrĕʼ֖ẇ mi⁠gė֥şěţ ʼéláֽy⁠w׃"],[34,31,"וַ⁠יִּקְרָ֤א אֲלֵ⁠הֶם֙ מֹשֶׁ֔ה וַ⁠יָּשֻׁ֧בוּ אֵלָ֛י⁠ו אַהֲרֹ֥ן וְ⁠כָל־הַ⁠נְּשִׂאִ֖ים בָּ⁠עֵדָ֑ה וַ⁠יְדַבֵּ֥ר מֹשֶׁ֖ה אֲלֵ⁠הֶֽם׃","wa⁠yi̇qĕrá֤ʼ ʼàlé⁠hem֙ mòşě֔h wa⁠yá̇şǔ֧bẇ ʼélá֛y⁠w ʼahàrò֥n wĕ⁠kál-ha⁠nĕ̇şîʼi֖ym bá̇⁠ʻédá֑h wa⁠yĕdabé֥̇r mòşě֖h ʼàlé⁠heֽm׃"],[34,32,"וְ⁠אַחֲרֵי־כֵ֥ן נִגְּשׁ֖וּ כָּל־בְּנֵ֣י יִשְׂרָאֵ֑ל וַ⁠יְצַוֵּ֕⁠ם אֵת֩ כָּל־אֲשֶׁ֨ר דִּבֶּ֧ר יְהוָ֛ה אִתּ֖⁠וֹ בְּ⁠הַ֥ר סִינָֽי׃","wĕ⁠ʼaẖàréy-ké֥n nigĕ̇ş֖̌ẇ ká̇l-bĕ̇né֣y yişĕ̂ráʼé֑l wa⁠yĕẕawé̇֕⁠m ʼéţ֩ ká̇l-ʼàşě֨r di̇bė֧r yĕhwá֛h ʼiţ֖̇⁠wò bĕ̇⁠ha֥r siynáֽy׃"],[34,33,"וַ⁠יְכַ֣ל מֹשֶׁ֔ה מִ⁠דַּבֵּ֖ר אִתָּ֑⁠ם וַ⁠יִּתֵּ֥ן עַל־פָּנָ֖י⁠ו מַסְוֶֽה׃","wa⁠yĕka֣l mòşě֔h mi⁠dȧbé֖̇r ʼiţá֑̇⁠m wa⁠yi̇ţé֥̇n ʻal-pá̇ná֖y⁠w masĕweֽh׃"],[34,34,"וּ⁠בְ⁠בֹ֨א מֹשֶׁ֜ה לִ⁠פְנֵ֤י יְהוָה֙ לְ⁠דַבֵּ֣ר אִתּ֔⁠וֹ יָסִ֥יר אֶת־הַ⁠מַּסְוֶ֖ה עַד־צֵאת֑⁠וֹ וְ⁠יָצָ֗א וְ⁠דִבֶּר֙ אֶל־בְּנֵ֣י יִשְׂרָאֵ֔ל אֵ֖ת אֲשֶׁ֥ר יְצֻוֶּֽה׃","ẇ⁠bĕ⁠bò֨ʼ mòşě֜h li⁠pĕné֤y yĕhwáh֙ lĕ⁠dabé֣̇r ʼiţ̇֔⁠wò yási֥yr ʼeţ-ha⁠mȧsĕwe֖h ʻad-ẕéʼţ֑⁠wò wĕ⁠yáẕá֗ʼ wĕ⁠dibėr֙ ʼel-bĕ̇né֣y yişĕ̂ráʼé֔l ʼé֖ţ ʼàşě֥r yĕẕuwėֽh׃"],[34,35,"וְ⁠רָא֤וּ בְנֵֽי־יִשְׂרָאֵל֙ אֶת־פְּנֵ֣י מֹשֶׁ֔ה כִּ֣י קָרַ֔ן ע֖וֹר פְּנֵ֣י מֹשֶׁ֑ה וְ⁠הֵשִׁ֨יב מֹשֶׁ֤ה אֶת־הַ⁠מַּסְוֶה֙ עַל־פָּנָ֔י⁠ו עַד־בֹּא֖⁠וֹ לְ⁠דַבֵּ֥ר אִתּֽ⁠וֹ׃ס","wĕ⁠ráʼ֤ẇ bĕnéֽy-yişĕ̂ráʼél֙ ʼeţ-pĕ̇né֣y mòşě֔h ki֣̇y qára֔n ʻ֖wòr pĕ̇né֣y mòşě֑h wĕ⁠héşǐ֨yb mòşě֤h ʼeţ-ha⁠mȧsĕweh֙ ʻal-pá̇ná֔y⁠w ʻad-bò̇ʼ֖⁠wò lĕ⁠dabé֥̇r ʼiţֽ̇⁠wò׃s"],[35,1,"וַ⁠יַּקְהֵ֣ל מֹשֶׁ֗ה אֶֽת־כָּל־עֲדַ֛ת בְּנֵ֥י יִשְׂרָאֵ֖ל וַ⁠יֹּ֣אמֶר אֲלֵ⁠הֶ֑ם אֵ֚לֶּה הַ⁠דְּבָרִ֔ים אֲשֶׁר־צִוָּ֥ה יְהוָ֖ה לַ⁠עֲשֹׂ֥ת אֹתָֽ⁠ם׃","wa⁠yȧqĕhé֣l mòşě֗h ʼeֽţ-ká̇l-ʻàda֛ţ bĕ̇né֥y yişĕ̂ráʼé֖l wa⁠yò֣̇ʼmer ʼàlé⁠he֑m ʼé֚lėh ha⁠dĕ̇bári֔ym ʼàşěr-ẕiwá֥̇h yĕhwá֖h la⁠ʻàşò֥̂ţ ʼòţáֽ⁠m׃"],[35,2,"שֵׁ֣שֶׁת יָמִים֮ תֵּעָשֶׂ֣ה מְלָאכָה֒ וּ⁠בַ⁠יּ֣וֹם הַ⁠שְּׁבִיעִ֗י יִהְיֶ֨ה לָ⁠כֶ֥ם קֹ֛דֶשׁ שַׁבַּ֥ת שַׁבָּת֖וֹן לַ⁠יהוָ֑ה כָּל־הָ⁠עֹשֶׂ֥ה ב֛⁠וֹ מְלָאכָ֖ה יוּמָֽת׃","şé֣̌şěţ yámiym֮ ţé̇ʻáşê֣h mĕláʼkáh֒ ẇ⁠ba⁠ẏ֣wòm ha⁠şĕ̇̌biyʻi֗y yihĕye֨h lá⁠ke֥m qò֛deş̌ şǎbȧ֥ţ şǎbá̇ţ֖wòn la⁠yhwá֑h ká̇l-há⁠ʻòşê֥h b֛⁠wò mĕláʼká֖h yẇmáֽţ׃"],[35,3,"לֹא־תְבַעֲר֣וּ אֵ֔שׁ בְּ⁠כֹ֖ל מֹשְׁבֹֽתֵי⁠כֶ֑ם בְּ⁠י֖וֹם הַ⁠שַּׁבָּֽת׃פ","lòʼ-ţĕbaʻàr֣ẇ ʼé֔ş̌ bĕ̇⁠kò֖l mòşĕ̌bòֽţéy⁠ke֑m bĕ̇⁠y֖wòm ha⁠şȧ̌báֽ̇ţ׃p"],[35,4,"וַ⁠יֹּ֣אמֶר מֹשֶׁ֔ה אֶל־כָּל־עֲדַ֥ת בְּנֵֽי־יִשְׂרָאֵ֖ל לֵ⁠אמֹ֑ר זֶ֣ה הַ⁠דָּבָ֔ר אֲשֶׁר־צִוָּ֥ה יְהוָ֖ה לֵ⁠אמֹֽר׃","wa⁠yò֣̇ʼmer mòşě֔h ʼel-ká̇l-ʻàda֥ţ bĕ̇néֽy-yişĕ̂ráʼé֖l lé⁠ʼmò֑r ze֣h ha⁠dá̇bá֔r ʼàşěr-ẕiwá֥̇h yĕhwá֖h lé⁠ʼmòֽr׃"],[35,5,"קְח֨וּ מֵֽ⁠אִתְּ⁠כֶ֤ם תְּרוּמָה֙ לַֽ⁠יהוָ֔ה כֹּ֚ל נְדִ֣יב לִבּ֔⁠וֹ יְבִיאֶ֕⁠הָ אֵ֖ת תְּרוּמַ֣ת יְהוָ֑ה זָהָ֥ב וָ⁠כֶ֖סֶף וּ⁠נְחֹֽשֶׁת׃","qĕẖ֨ẇ méֽ⁠ʼiţĕ̇⁠ke֤m ţĕ̇rẇmáh֙ laֽ⁠yhwá֔h kò֚̇l nĕdi֣yb liḃ֔⁠wò yĕbiyʼe֕⁠há ʼé֖ţ ţĕ̇rẇma֣ţ yĕhwá֑h záhá֥b wá⁠ke֖sep ẇ⁠nĕẖòֽşěţ׃"],[35,6,"וּ⁠תְכֵ֧לֶת וְ⁠אַרְגָּמָ֛ן וְ⁠תוֹלַ֥עַת שָׁנִ֖י וְ⁠שֵׁ֥שׁ וְ⁠עִזִּֽים׃","ẇ⁠ţĕké֧leţ wĕ⁠ʼarĕgá̇má֛n wĕ⁠ţwòla֥ʻaţ şá̌ni֖y wĕ⁠şé֥̌ş̌ wĕ⁠ʻiziֽ̇ym׃"],[35,7,"וְ⁠עֹרֹ֨ת אֵילִ֧ם מְאָדָּמִ֛ים וְ⁠עֹרֹ֥ת תְּחָשִׁ֖ים וַ⁠עֲצֵ֥י שִׂטִּֽים׃","wĕ⁠ʻòrò֨ţ ʼéyli֧m mĕʼádá̇mi֛ym wĕ⁠ʻòrò֥ţ ţĕ̇ẖáşǐ֖ym wa⁠ʻàẕé֥y şîtiֽ̇ym׃"],[35,8,"וְ⁠שֶׁ֖מֶן לַ⁠מָּא֑וֹר וּ⁠בְשָׂמִים֙ לְ⁠שֶׁ֣מֶן הַ⁠מִּשְׁחָ֔ה וְ⁠לִ⁠קְטֹ֖רֶת הַ⁠סַּמִּֽים׃","wĕ⁠şě֖men la⁠má̇ʼ֑wòr ẇ⁠bĕşá̂miym֙ lĕ⁠şě֣men ha⁠mi̇şĕ̌ẖá֔h wĕ⁠li⁠qĕtò֖reţ ha⁠sȧmiֽ̇ym׃"],[35,9,"וְ⁠אַ֨בְנֵי־שֹׁ֔הַם וְ⁠אַבְנֵ֖י מִלֻּאִ֑ים לָ⁠אֵפ֖וֹד וְ⁠לַ⁠חֹֽשֶׁן׃","wĕ⁠ʼa֨bĕnéy-şò̌֔ham wĕ⁠ʼabĕné֖y milu̇ʼi֑ym lá⁠ʼép֖wòd wĕ⁠la⁠ẖòֽşěn׃"],[35,10,"וְ⁠כָל־חֲכַם־לֵ֖ב בָּ⁠כֶ֑ם יָבֹ֣אוּ וְ⁠יַעֲשׂ֔וּ אֵ֛ת כָּל־אֲשֶׁ֥ר צִוָּ֖ה יְהוָֽה׃","wĕ⁠kál-ẖàkam-lé֖b bá̇⁠ke֑m yábò֣ʼẇ wĕ⁠yaʻàş̂֔ẇ ʼé֛ţ ká̇l-ʼàşě֥r ẕiwá֖̇h yĕhwáֽh׃"],[35,11,"אֶת־הַ֨⁠מִּשְׁכָּ֔ן אֶֽת־אָהֳל֖⁠וֹ וְ⁠אֶת־מִכְסֵ֑⁠הוּ אֶת־קְרָסָי⁠ו֙ וְ⁠אֶת־קְרָשָׁ֔י⁠ו אֶת־בריחו אֶת־עַמֻּדָ֖י⁠ו וְ⁠אֶת־אֲדָנָֽי⁠ו׃","ʼeţ-ha֨⁠mi̇şĕ̌ká̇֔n ʼeֽţ-ʼáhol֖⁠wò wĕ⁠ʼeţ-mikĕsé֑⁠hẇ ʼeţ-qĕrásáy⁠w֙ wĕ⁠ʼeţ-qĕráşá̌֔y⁠w ʼeţ-bryẖw ʼeţ-ʻamu̇dá֖y⁠w wĕ⁠ʼeţ-ʼàdánáֽy⁠w׃"],[35,12,"אֶת־הָ⁠אָרֹ֥ן וְ⁠אֶת־בַּדָּ֖י⁠ו אֶת־הַ⁠כַּפֹּ֑רֶת וְ⁠אֵ֖ת פָּרֹ֥כֶת הַ⁠מָּסָֽךְ׃","ʼeţ-há⁠ʼárò֥n wĕ⁠ʼeţ-bȧdá֖̇y⁠w ʼeţ-ha⁠kȧpò֑̇reţ wĕ⁠ʼé֖ţ pá̇rò֥keţ ha⁠má̇sáֽkĕ׃"],[35,13,"אֶת־הַ⁠שֻּׁלְחָ֥ן וְ⁠אֶת־בַּדָּ֖י⁠ו וְ⁠אֶת־כָּל־כֵּלָ֑י⁠ו וְ⁠אֵ֖ת לֶ֥חֶם הַ⁠פָּנִֽים׃","ʼeţ-ha⁠şu̇̌lĕẖá֥n wĕ⁠ʼeţ-bȧdá֖̇y⁠w wĕ⁠ʼeţ-ká̇l-ké̇lá֑y⁠w wĕ⁠ʼé֖ţ le֥ẖem ha⁠pá̇niֽym׃"],[35,14,"וְ⁠אֶת־מְנֹרַ֧ת הַ⁠מָּא֛וֹר וְ⁠אֶת־כֵּלֶ֖י⁠הָ וְ⁠אֶת־נֵרֹתֶ֑י⁠הָ וְ⁠אֵ֖ת שֶׁ֥מֶן הַ⁠מָּאֽוֹר׃","wĕ⁠ʼeţ-mĕnòra֧ţ ha⁠má̇ʼ֛wòr wĕ⁠ʼeţ-ké̇le֖y⁠há wĕ⁠ʼeţ-néròţe֑y⁠há wĕ⁠ʼé֖ţ şě֥men ha⁠má̇ʼֽwòr׃"],[35,15,"וְ⁠אֶת־מִזְבַּ֤ח הַ⁠קְּטֹ֨רֶת֙ וְ⁠אֶת־בַּדָּ֔י⁠ו וְ⁠אֵת֙ שֶׁ֣מֶן הַ⁠מִּשְׁחָ֔ה וְ⁠אֵ֖ת קְטֹ֣רֶת הַ⁠סַּמִּ֑ים וְ⁠אֶת־מָסַ֥ךְ הַ⁠פֶּ֖תַח לְ⁠פֶ֥תַח הַ⁠מִּשְׁכָּֽן׃","wĕ⁠ʼeţ-mizĕbȧ֤ẖ ha⁠qĕ̇tò֨reţ֙ wĕ⁠ʼeţ-bȧdá̇֔y⁠w wĕ⁠ʼéţ֙ şě֣men ha⁠mi̇şĕ̌ẖá֔h wĕ⁠ʼé֖ţ qĕtò֣reţ ha⁠sȧmi֑̇ym wĕ⁠ʼeţ-mása֥kĕ ha⁠pė֖ţaẖ lĕ⁠pe֥ţaẖ ha⁠mi̇şĕ̌káֽ̇n׃"],[35,16,"אֵ֣ת ׀ מִזְבַּ֣ח הָ⁠עֹלָ֗ה וְ⁠אֶת־מִכְבַּ֤ר הַ⁠נְּחֹ֨שֶׁת֙ אֲשֶׁר־ל֔⁠וֹ אֶת־בַּדָּ֖י⁠ו וְ⁠אֶת־כָּל־כֵּלָ֑י⁠ו אֶת־הַ⁠כִּיֹּ֖ר וְ⁠אֶת־כַּנּֽ⁠וֹ׃","ʼé֣ţ ׀ mizĕbȧ֣ẖ há⁠ʻòlá֗h wĕ⁠ʼeţ-mikĕbȧ֤r ha⁠nĕ̇ẖò֨şěţ֙ ʼàşěr-l֔⁠wò ʼeţ-bȧdá֖̇y⁠w wĕ⁠ʼeţ-ká̇l-ké̇lá֑y⁠w ʼeţ-ha⁠ki̇yò֖̇r wĕ⁠ʼeţ-kȧṅֽ⁠wò׃"],[35,17,"אֵ֚ת קַלְעֵ֣י הֶ⁠חָצֵ֔ר אֶת־עַמֻּדָ֖י⁠ו וְ⁠אֶת־אֲדָנֶ֑י⁠הָ וְ⁠אֵ֕ת מָסַ֖ךְ שַׁ֥עַר הֶ⁠חָצֵֽר׃","ʼé֚ţ qalĕʻé֣y he⁠ẖáẕé֔r ʼeţ-ʻamu̇dá֖y⁠w wĕ⁠ʼeţ-ʼàdáne֑y⁠há wĕ⁠ʼé֕ţ mása֖kĕ şǎ֥ʻar he⁠ẖáẕéֽr׃"],[35,18,"אֶת־יִתְדֹ֧ת הַ⁠מִּשְׁכָּ֛ן וְ⁠אֶת־יִתְדֹ֥ת הֶ⁠חָצֵ֖ר וְ⁠אֶת־מֵיתְרֵי⁠הֶֽם׃","ʼeţ-yiţĕdò֧ţ ha⁠mi̇şĕ̌ká֛̇n wĕ⁠ʼeţ-yiţĕdò֥ţ he⁠ẖáẕé֖r wĕ⁠ʼeţ-méyţĕréy⁠heֽm׃"],[35,19,"אֶת־בִּגְדֵ֥י הַ⁠שְּׂרָ֖ד לְ⁠שָׁרֵ֣ת בַּ⁠קֹּ֑דֶשׁ אֶת־בִּגְדֵ֤י הַ⁠קֹּ֨דֶשׁ֙ לְ⁠אַהֲרֹ֣ן הַ⁠כֹּהֵ֔ן וְ⁠אֶת־בִּגְדֵ֥י בָנָ֖י⁠ו לְ⁠כַהֵֽן׃","ʼeţ-bi̇gĕdé֥y ha⁠şĕ̇̂rá֖d lĕ⁠şá̌ré֣ţ bȧ⁠qò֑̇deş̌ ʼeţ-bi̇gĕdé֤y ha⁠qò̇֨deş̌֙ lĕ⁠ʼahàrò֣n ha⁠kò̇hé֔n wĕ⁠ʼeţ-bi̇gĕdé֥y báná֖y⁠w lĕ⁠kahéֽn׃"],[35,20,"וַ⁠יֵּֽצְא֛וּ כָּל־עֲדַ֥ת בְּנֵֽי־יִשְׂרָאֵ֖ל מִ⁠לִּ⁠פְנֵ֥י מֹשֶֽׁה׃","wa⁠yéֽ̇ẕĕʼ֛ẇ ká̇l-ʻàda֥ţ bĕ̇nֽéy-yişĕ̂ráʼé֖l mi⁠li̇⁠pĕné֥y mòşěֽh׃"],[35,21,"וַ⁠יָּבֹ֕אוּ כָּל־אִ֖ישׁ אֲשֶׁר־נְשָׂא֣⁠וֹ לִבּ֑⁠וֹ וְ⁠כֹ֡ל אֲשֶׁר֩ נָדְבָ֨ה רוּח֜⁠וֹ אֹת֗⁠וֹ הֵ֠בִיאוּ אֶת־תְּרוּמַ֨ת יְהוָ֜ה לִ⁠מְלֶ֨אכֶת אֹ֤הֶל מוֹעֵד֙ וּ⁠לְ⁠כָל־עֲבֹ֣דָת֔⁠וֹ וּ⁠לְ⁠בִגְדֵ֖י הַ⁠קֹּֽדֶשׁ׃","wa⁠yá̇bò֕ʼẇ ká̇l-ʼi֖yş̌ ʼàşěr-nĕşá̂ʼ֣⁠wò liḃ֑⁠wò wĕ⁠kò֡l ʼàşěr֩ nádĕbá֨h rẇẖ֜⁠wò ʼòţ֗⁠wò hé֠biyʼẇ ʼeţ-ţĕ̇rẇma֨ţ yĕhwá֜h li⁠mĕle֨ʼkeţ ʼò֤hel mwòʻéd֙ ẇ⁠lĕ⁠kál-ʻàbò֣dáţ֔⁠wò ẇ⁠lĕ⁠bigĕdé֖y ha⁠qòֽ̇deş̌׃"],[35,22,"וַ⁠יָּבֹ֥אוּ הָ⁠אֲנָשִׁ֖ים עַל־הַ⁠נָּשִׁ֑ים כֹּ֣ל ׀ נְדִ֣יב לֵ֗ב הֵ֠בִיאוּ חָ֣ח וָ⁠נֶ֜זֶם וְ⁠טַבַּ֤עַת וְ⁠כוּמָז֙ כָּל־כְּלִ֣י זָהָ֔ב וְ⁠כָל־אִ֕ישׁ אֲשֶׁ֥ר הֵנִ֛יף תְּנוּפַ֥ת זָהָ֖ב לַ⁠יהוָֽה׃","wa⁠yá̇bò֥ʼẇ há⁠ʼànáşǐ֖ym ʻal-ha⁠ná̇şǐ֑ym kò֣̇l ׀ nĕdi֣yb lé֗b hé֠biyʼẇ ẖá֣ẖ wá⁠ne֜zem wĕ⁠tabȧ֤ʻaţ wĕ⁠kẇmáz֙ ká̇l-kĕ̇li֣y záhá֔b wĕ⁠kál-ʼi֕yş̌ ʼàşě֥r héni֛yp ţĕ̇nẇpa֥ţ záhá֖b la⁠yhwáֽh׃"],[35,23,"וְ⁠כָל־אִ֞ישׁ אֲשֶׁר־נִמְצָ֣א אִתּ֗⁠וֹ תְּכֵ֧לֶת וְ⁠אַרְגָּמָ֛ן וְ⁠תוֹלַ֥עַת שָׁנִ֖י וְ⁠שֵׁ֣שׁ וְ⁠עִזִּ֑ים וְ⁠עֹרֹ֨ת אֵילִ֧ם מְאָדָּמִ֛ים וְ⁠עֹרֹ֥ת תְּחָשִׁ֖ים הֵבִֽיאוּ׃","wĕ⁠kál-ʼi֞yş̌ ʼàşěr-nimĕẕá֣ʼ ʼiţ̇֗⁠wò ţĕ̇ké֧leţ wĕ⁠ʼarĕgá̇má֛n wĕ⁠ţwòla֥ʻaţ şá̌ni֖y wĕ⁠şé֣̌ş̌ wĕ⁠ʻizi֑̇ym wĕ⁠ʻòrò֨ţ ʼéyli֧m mĕʼádá̇mi֛ym wĕ⁠ʻòrò֥ţ ţĕ̇ẖáşǐ֖ym hébiֽyʼẇ׃"],[35,24,"כָּל־מֵרִ֗ים תְּר֤וּמַת כֶּ֨סֶף֙ וּ⁠נְחֹ֔שֶׁת הֵבִ֕יאוּ אֵ֖ת תְּרוּמַ֣ת יְהוָ֑ה וְ⁠כֹ֡ל אֲשֶׁר֩ נִמְצָ֨א אִתּ֜⁠וֹ עֲצֵ֥י שִׁטִּ֛ים לְ⁠כָל־מְלֶ֥אכֶת הָ⁠עֲבֹדָ֖ה הֵבִֽיאוּ׃","ká̇l-méri֗ym ţĕ̇r֤ẇmaţ kė֨sep֙ ẇ⁠nĕẖò֔şěţ hébi֕yʼẇ ʼé֖ţ ţĕ̇rẇma֣ţ yĕhwá֑h wĕ⁠kò֡l ʼàşěr֩ nimĕẕá֨ʼ ʼiţ̇֜⁠wò ʻàẕé֥y şǐti֛̇ym lĕ⁠kál-mĕle֥ʼkeţ há⁠ʻàbòdá֖h hébiֽyʼẇ׃"],[35,25,"וְ⁠כָל־אִשָּׁ֥ה חַכְמַת־לֵ֖ב בְּ⁠יָדֶ֣י⁠הָ טָו֑וּ וַ⁠יָּבִ֣יאוּ מַטְוֶ֗ה אֶֽת־הַ⁠תְּכֵ֨לֶת֙ וְ⁠אֶת־הָֽ⁠אַרְגָּמָ֔ן אֶת־תּוֹלַ֥עַת הַ⁠שָּׁנִ֖י וְ⁠אֶת־הַ⁠שֵּֽׁשׁ׃","wĕ⁠kál-ʼişá֥̇̌h ẖakĕmaţ-lé֖b bĕ̇⁠yáde֣y⁠há táw֑ẇ wa⁠yá̇bi֣yʼẇ matĕwe֗h ʼeֽţ-ha⁠ţĕ̇ké֨leţ֙ wĕ⁠ʼeţ-háֽ⁠ʼarĕgá̇má֔n ʼeţ-ţ̇wòla֥ʻaţ ha⁠şá̇̌ni֖y wĕ⁠ʼeţ-ha⁠şéֽ̇̌ş̌׃"],[35,26,"וְ⁠כָל־הַ֨⁠נָּשִׁ֔ים אֲשֶׁ֨ר נָשָׂ֥א לִבָּ֛⁠ן אֹתָ֖⁠נָה בְּ⁠חָכְמָ֑ה טָו֖וּ אֶת־הָ⁠עִזִּֽים׃","wĕ⁠kál-ha֨⁠ná̇şǐ֔ym ʼàşě֨r náşá֥̂ʼ libá֛̇⁠n ʼòţá֖⁠náh bĕ̇⁠ẖákĕmá֑h táw֖ẇ ʼeţ-há⁠ʻiziֽ̇ym׃"],[35,27,"וְ⁠הַ⁠נְּשִׂאִ֣ם הֵבִ֔יאוּ אֵ֚ת אַבְנֵ֣י הַ⁠שֹּׁ֔הַם וְ⁠אֵ֖ת אַבְנֵ֣י הַ⁠מִּלֻּאִ֑ים לָ⁠אֵפ֖וֹד וְ⁠לַ⁠חֹֽשֶׁן׃","wĕ⁠ha⁠nĕ̇şîʼi֣m hébi֔yʼẇ ʼé֚ţ ʼabĕné֣y ha⁠şò̇̌֔ham wĕ⁠ʼé֖ţ ʼabĕné֣y ha⁠mi̇lu̇ʼi֑ym lá⁠ʼép֖wòd wĕ⁠la⁠ẖòֽşěn׃"],[35,28,"וְ⁠אֶת־הַ⁠בֹּ֖שֶׂם וְ⁠אֶת־הַ⁠שָּׁ֑מֶן לְ⁠מָא֕וֹר וּ⁠לְ⁠שֶׁ֨מֶן֙ הַ⁠מִּשְׁחָ֔ה וְ⁠לִ⁠קְטֹ֖רֶת הַ⁠סַּמִּֽים׃","wĕ⁠ʼeţ-ha⁠bò֖̇şêm wĕ⁠ʼeţ-ha⁠şá֑̇̌men lĕ⁠máʼ֕wòr ẇ⁠lĕ⁠şě֨men֙ ha⁠mi̇şĕ̌ẖá֔h wĕ⁠li⁠qĕtò֖reţ ha⁠sȧmiֽ̇ym׃"],[35,29,"כָּל־אִ֣ישׁ וְ⁠אִשָּׁ֗ה אֲשֶׁ֨ר נָדַ֣ב לִבָּ⁠ם֮ אֹתָ⁠ם֒ לְ⁠הָבִיא֙ לְ⁠כָל־הַ⁠מְּלָאכָ֔ה אֲשֶׁ֨ר צִוָּ֧ה יְהוָ֛ה לַ⁠עֲשׂ֖וֹת בְּ⁠יַד־מֹשֶׁ֑ה הֵבִ֧יאוּ בְנֵי־יִשְׂרָאֵ֛ל נְדָבָ֖ה לַ⁠יהוָֽה׃פ","ká̇l-ʼi֣yş̌ wĕ⁠ʼişá̇̌֗h ʼàşě֨r náda֣b libá̇⁠m֮ ʼòţá⁠m֒ lĕ⁠hábiyʼ֙ lĕ⁠kál-ha⁠mĕ̇láʼká֔h ʼàşě֨r ẕiwá֧̇h yĕhwá֛h la⁠ʻàş֖̂wòţ bĕ̇⁠yad-mòşě֑h hébi֧yʼẇ bĕnéy-yişĕ̂ráʼé֛l nĕdábá֖h la⁠yhwáֽh׃p"],[35,30,"וַ⁠יֹּ֤אמֶר מֹשֶׁה֙ אֶל־בְּנֵ֣י יִשְׂרָאֵ֔ל רְא֛וּ קָרָ֥א יְהוָ֖ה בְּ⁠שֵׁ֑ם בְּצַלְאֵ֛ל בֶּן־אוּרִ֥י בֶן־ח֖וּר לְ⁠מַטֵּ֥ה יְהוּדָֽה׃","wa⁠yò֤̇ʼmer mòşěh֙ ʼel-bĕ̇né֣y yişĕ̂ráʼé֔l rĕʼ֛ẇ qárá֥ʼ yĕhwá֖h bĕ̇⁠şé֑̌m bĕ̇ẕalĕʼé֛l bėn-ʼẇri֥y ben-ẖ֖ẇr lĕ⁠maté֥̇h yĕhẇdáֽh׃"],[35,31,"וַ⁠יְמַלֵּ֥א אֹת֖⁠וֹ ר֣וּחַ אֱלֹהִ֑ים בְּ⁠חָכְמָ֛ה בִּ⁠תְבוּנָ֥ה וּ⁠בְ⁠דַ֖עַת וּ⁠בְ⁠כָל־מְלָאכָֽה׃","wa⁠yĕmalé֥̇ʼ ʼòţ֖⁠wò r֣ẇẖa ʼèlòhi֑ym bĕ̇⁠ẖákĕmá֛h bi̇⁠ţĕbẇná֥h ẇ⁠bĕ⁠da֖ʻaţ ẇ⁠bĕ⁠kál-mĕláʼkáֽh׃"],[35,32,"וְ⁠לַ⁠חְשֹׁ֖ב מַֽחַשָׁבֹ֑ת לַ⁠עֲשֹׂ֛ת בַּ⁠זָּהָ֥ב וּ⁠בַ⁠כֶּ֖סֶף וּ⁠בַ⁠נְּחֹֽשֶׁת׃","wĕ⁠la⁠ẖĕşò֖̌b maֽẖaşá̌bò֑ţ la⁠ʻàşò֛̂ţ bȧ⁠zá̇há֥b ẇ⁠ba⁠kė֖sep ẇ⁠ba⁠nĕ̇ẖòֽşěţ׃"],[35,33,"וּ⁠בַ⁠חֲרֹ֥שֶׁת אֶ֛בֶן לְ⁠מַלֹּ֖את וּ⁠בַ⁠חֲרֹ֣שֶׁת עֵ֑ץ לַ⁠עֲשׂ֖וֹת בְּ⁠כָל־מְלֶ֥אכֶת מַחֲשָֽׁבֶת׃","ẇ⁠ba⁠ẖàrò֥şěţ ʼe֛ben lĕ⁠malò֖̇ʼţ ẇ⁠ba⁠ẖàrò֣şěţ ʻé֑ẕ la⁠ʻàş֖̂wòţ bĕ̇⁠kál-mĕle֥ʼkeţ maẖàşáֽ̌beţ׃"],[35,34,"וּ⁠לְ⁠הוֹרֹ֖ת נָתַ֣ן בְּ⁠לִבּ֑⁠וֹ ה֕וּא וְ⁠אָֽהֳלִיאָ֥ב בֶּן־אֲחִיסָמָ֖ךְ לְ⁠מַטֵּה־דָֽן׃","ẇ⁠lĕ⁠hwòrò֖ţ náţa֣n bĕ̇⁠liḃ֑⁠wò h֕ẇʼ wĕ⁠ʼáֽholiyʼá֥b bėn-ʼàẖiysámá֖kĕ lĕ⁠maté̇h-dáֽn׃"],[35,35,"מִלֵּ֨א אֹתָ֜⁠ם חָכְמַת־לֵ֗ב לַ⁠עֲשׂוֹת֮ כָּל־מְלֶ֣אכֶת חָרָ֣שׁ ׀ וְ⁠חֹשֵׁב֒ וְ⁠רֹקֵ֞ם בַּ⁠תְּכֵ֣לֶת וּ⁠בָֽ⁠אַרְגָּמָ֗ן בְּ⁠תוֹלַ֧עַת הַ⁠שָּׁנִ֛י וּ⁠בַ⁠שֵּׁ֖שׁ וְ⁠אֹרֵ֑ג עֹשֵׂי֙ כָּל־מְלָאכָ֔ה וְ⁠חֹשְׁבֵ֖י מַחֲשָׁבֹֽת׃","milé̇֨ʼ ʼòţá֜⁠m ẖákĕmaţ-lé֗b la⁠ʻàş̂wòţ֮ ká̇l-mĕle֣ʼkeţ ẖárá֣ş̌ ׀ wĕ⁠ẖòşé̌b֒ wĕ⁠ròqé֞m bȧ⁠ţĕ̇ké֣leţ ẇ⁠báֽ⁠ʼarĕgá̇má֗n bĕ̇⁠ţwòla֧ʻaţ ha⁠şá̇̌ni֛y ẇ⁠ba⁠şé֖̇̌ş̌ wĕ⁠ʼòré֑g ʻòşé̂y֙ ká̇l-mĕláʼká֔h wĕ⁠ẖòşĕ̌bé֖y maẖàşá̌bòֽţ׃"],[36,1,"וְ⁠עָשָׂה֩ בְצַלְאֵ֨ל וְ⁠אָהֳלִיאָ֜ב וְ⁠כֹ֣ל ׀ אִ֣ישׁ חֲכַם־לֵ֗ב אֲשֶׁר֩ נָתַ֨ן יְהוָ֜ה חָכְמָ֤ה וּ⁠תְבוּנָה֙ בָּ⁠הֵ֔מָּה לָ⁠דַ֣עַת לַ⁠עֲשֹׂ֔ת אֶֽת־כָּל־מְלֶ֖אכֶת עֲבֹדַ֣ת הַ⁠קֹּ֑דֶשׁ לְ⁠כֹ֥ל אֲשֶׁר־צִוָּ֖ה יְהוָֽה׃","wĕ⁠ʻáşá̂h֩ bĕẕalĕʼé֨l wĕ⁠ʼáholiyʼá֜b wĕ⁠kò֣l ׀ ʼi֣yş̌ ẖàkam-lé֗b ʼàşěr֩ náţa֨n yĕhwá֜h ẖákĕmá֤h ẇ⁠ţĕbẇnáh֙ bá̇⁠hé֔má̇h lá⁠da֣ʻaţ la⁠ʻàşò̂֔ţ ʼeֽţ-ká̇l-mĕle֖ʼkeţ ʻàbòda֣ţ ha⁠qò֑̇deş̌ lĕ⁠kò֥l ʼàşěr-ẕiwá֖̇h yĕhwáֽh׃"],[36,2,"וַ⁠יִּקְרָ֣א מֹשֶׁ֗ה אֶל־בְּצַלְאֵ֘ל וְ⁠אֶל־אָֽהֳלִיאָב֒ וְ⁠אֶל֙ כָּל־אִ֣ישׁ חֲכַם־לֵ֔ב אֲשֶׁ֨ר נָתַ֧ן יְהוָ֛ה חָכְמָ֖ה בְּ⁠לִבּ֑⁠וֹ כֹּ֚ל אֲשֶׁ֣ר נְשָׂא֣⁠וֹ לִבּ֔⁠וֹ לְ⁠קָרְבָ֥ה אֶל־הַ⁠מְּלָאכָ֖ה לַ⁠עֲשֹׂ֥ת אֹתָֽ⁠הּ׃","wa⁠yi̇qĕrá֣ʼ mòşě֗h ʼel-bĕ̇ẕalĕʼé֘l wĕ⁠ʼel-ʼáֽholiyʼáb֒ wĕ⁠ʼel֙ ká̇l-ʼi֣yş̌ ẖàkam-lé֔b ʼàşě֨r náţa֧n yĕhwá֛h ẖákĕmá֖h bĕ̇⁠liḃ֑⁠wò kò֚̇l ʼàşě֣r nĕşá̂ʼ֣⁠wò liḃ֔⁠wò lĕ⁠qárĕbá֥h ʼel-ha⁠mĕ̇láʼká֖h la⁠ʻàşò֥̂ţ ʼòţáֽ⁠ḣ׃"],[36,3,"וַ⁠יִּקְח֞וּ מִ⁠לִּ⁠פְנֵ֣י מֹשֶׁ֗ה אֵ֤ת כָּל־הַ⁠תְּרוּמָה֙ אֲשֶׁ֨ר הֵבִ֜יאוּ בְּנֵ֣י יִשְׂרָאֵ֗ל לִ⁠מְלֶ֛אכֶת עֲבֹדַ֥ת הַ⁠קֹּ֖דֶשׁ לַ⁠עֲשֹׂ֣ת אֹתָ֑⁠הּ וְ֠⁠הֵם הֵבִ֨יאוּ אֵלָ֥י⁠ו ע֛וֹד נְדָבָ֖ה בַּ⁠בֹּ֥קֶר בַּ⁠בֹּֽקֶר׃","wa⁠yi̇qĕẖ֞ẇ mi⁠li̇⁠pĕné֣y mòşě֗h ʼé֤ţ ká̇l-ha⁠ţĕ̇rẇmáh֙ ʼàşě֨r hébi֜yʼẇ bĕ̇né֣y yişĕ̂ráʼé֗l li⁠mĕle֛ʼkeţ ʻàbòda֥ţ ha⁠qò֖̇deş̌ la⁠ʻàşò֣̂ţ ʼòţá֑⁠ḣ wĕ֠⁠hém hébi֨yʼẇ ʼélá֥y⁠w ʻ֛wòd nĕdábá֖h bȧ⁠bò֥̇qer bȧ⁠bòֽ̇qer׃"],[36,4,"וַ⁠יָּבֹ֨אוּ֙ כָּל־הַ֣⁠חֲכָמִ֔ים הָ⁠עֹשִׂ֕ים אֵ֖ת כָּל־מְלֶ֣אכֶת הַ⁠קֹּ֑דֶשׁ אִֽישׁ־אִ֥ישׁ מִ⁠מְּלַאכְתּ֖⁠וֹ אֲשֶׁר־הֵ֥מָּה עֹשִֽׂים׃","wa⁠yá̇bò֨ʼẇ֙ ká̇l-ha֣⁠ẖàkámi֔ym há⁠ʻòşî֕ym ʼé֖ţ ká̇l-mĕle֣ʼkeţ ha⁠qò֑̇deş̌ ʼiֽyş̌-ʼi֥yş̌ mi⁠mĕ̇laʼkĕţ֖̇⁠wò ʼàşěr-hé֥má̇h ʻòşîֽym׃"],[36,5,"וַ⁠יֹּאמְרוּ֙ אֶל־מֹשֶׁ֣ה לֵּ⁠אמֹ֔ר מַרְבִּ֥ים הָ⁠עָ֖ם לְ⁠הָבִ֑יא מִ⁠דֵּ֤י הָֽ⁠עֲבֹדָה֙ לַ⁠מְּלָאכָ֔ה אֲשֶׁר־צִוָּ֥ה יְהוָ֖ה לַ⁠עֲשֹׂ֥ת אֹתָֽ⁠הּ׃","wa⁠yò̇ʼmĕrẇ֙ ʼel-mòşě֣h lé̇⁠ʼmò֔r marĕbi֥̇ym há⁠ʻá֖m lĕ⁠hábi֑yʼ mi⁠dé֤̇y háֽ⁠ʻàbòdáh֙ la⁠mĕ̇láʼká֔h ʼàşěr-ẕiwá֥̇h yĕhwá֖h la⁠ʻàşò֥̂ţ ʼòţáֽ⁠ḣ׃"],[36,6,"וַ⁠יְצַ֣ו מֹשֶׁ֗ה וַ⁠יַּעֲבִ֨ירוּ ק֥וֹל בַּֽ⁠מַּחֲנֶה֮ לֵ⁠אמֹר֒ אִ֣ישׁ וְ⁠אִשָּׁ֗ה אַל־יַעֲשׂוּ־ע֛וֹד מְלָאכָ֖ה לִ⁠תְרוּמַ֣ת הַ⁠קֹּ֑דֶשׁ וַ⁠יִּכָּלֵ֥א הָ⁠עָ֖ם מֵ⁠הָבִֽיא׃","wa⁠yĕẕa֣w mòşě֗h wa⁠yȧʻàbi֨yrẇ q֥wòl bȧֽ⁠mȧẖàneh֮ lé⁠ʼmòr֒ ʼi֣yş̌ wĕ⁠ʼişá̇̌֗h ʼal-yaʻàş̂ẇ-ʻ֛wòd mĕláʼká֖h li⁠ţĕrẇma֣ţ ha⁠qò֑̇deş̌ wa⁠yi̇ká̇lé֥ʼ há⁠ʻá֖m mé⁠hábiֽyʼ׃"],[36,7,"וְ⁠הַ⁠מְּלָאכָ֗ה הָיְתָ֥ה דַיָּ֛⁠ם לְ⁠כָל־הַ⁠מְּלָאכָ֖ה לַ⁠עֲשׂ֣וֹת אֹתָ֑⁠הּ וְ⁠הוֹתֵֽר׃ס","wĕ⁠ha⁠mĕ̇láʼká֗h háyĕţá֥h dayá֛̇⁠m lĕ⁠kál-ha⁠mĕ̇láʼká֖h la⁠ʻàş֣̂wòţ ʼòţá֑⁠ḣ wĕ⁠hwòţéֽr׃s"],[36,8,"וַ⁠יַּעֲשׂ֨וּ כָל־חֲכַם־לֵ֜ב בְּ⁠עֹשֵׂ֧י הַ⁠מְּלָאכָ֛ה אֶת־הַ⁠מִּשְׁכָּ֖ן עֶ֣שֶׂר יְרִיעֹ֑ת שֵׁ֣שׁ מָשְׁזָ֗ר וּ⁠תְכֵ֤לֶת וְ⁠אַרְגָּמָן֙ וְ⁠תוֹלַ֣עַת שָׁנִ֔י כְּרֻבִ֛ים מַעֲשֵׂ֥ה חֹשֵׁ֖ב עָשָׂ֥ה אֹתָֽ⁠ם׃","wa⁠yȧʻàş̂֨ẇ kál-ẖàkam-lé֜b bĕ̇⁠ʻòşé֧̂y ha⁠mĕ̇láʼká֛h ʼeţ-ha⁠mi̇şĕ̌ká֖̇n ʻe֣şêr yĕriyʻò֑ţ şé֣̌ş̌ máşĕ̌zá֗r ẇ⁠ţĕké֤leţ wĕ⁠ʼarĕgá̇mán֙ wĕ⁠ţwòla֣ʻaţ şá̌ni֔y kĕ̇rubi֛ym maʻàşé֥̂h ẖòşé֖̌b ʻáşá֥̂h ʼòţáֽ⁠m׃"],[36,9,"אֹ֜רֶךְ הַ⁠יְרִיעָ֣ה הָֽ⁠אַחַ֗ת שְׁמֹנֶ֤ה וְ⁠עֶשְׂרִים֙ בָּֽ⁠אַמָּ֔ה וְ⁠רֹ֨חַב֙ אַרְבַּ֣ע בָּֽ⁠אַמָּ֔ה הַ⁠יְרִיעָ֖ה הָ⁠אֶחָ֑ת מִדָּ֥ה אַחַ֖ת לְ⁠כָל־הַ⁠יְרִיעֹֽת׃","ʼò֜rekĕ ha⁠yĕriyʻá֣h háֽ⁠ʼaẖa֗ţ şĕ̌mòne֤h wĕ⁠ʻeşĕ̂riym֙ báֽ̇⁠ʼamá̇֔h wĕ⁠rò֨ẖab֙ ʼarĕbȧ֣ʻ báֽ̇⁠ʼamá̇֔h ha⁠yĕriyʻá֖h há⁠ʼeẖá֑ţ midá֥̇h ʼaẖa֖ţ lĕ⁠kál-ha⁠yĕriyʻòֽţ׃"],[36,10,"וַ⁠יְחַבֵּר֙ אֶת־חֲמֵ֣שׁ הַ⁠יְרִיעֹ֔ת אַחַ֖ת אֶל־אֶחָ֑ת וְ⁠חָמֵ֤שׁ יְרִיעֹת֙ חִבַּ֔ר אַחַ֖ת אֶל־אֶחָֽת׃","wa⁠yĕẖabé̇r֙ ʼeţ-ẖàmé֣ş̌ ha⁠yĕriyʻò֔ţ ʼaẖa֖ţ ʼel-ʼeẖá֑ţ wĕ⁠ẖámé֤ş̌ yĕriyʻòţ֙ ẖibȧ֔r ʼaẖa֖ţ ʼel-ʼeẖáֽţ׃"],[36,11,"וַ⁠יַּ֜עַשׂ לֻֽלְאֹ֣ת תְּכֵ֗לֶת עַ֣ל שְׂפַ֤ת הַ⁠יְרִיעָה֙ הָֽ⁠אֶחָ֔ת מִ⁠קָּצָ֖ה בַּ⁠מַּחְבָּ֑רֶת כֵּ֤ן עָשָׂה֙ בִּ⁠שְׂפַ֣ת הַ⁠יְרִיעָ֔ה הַ⁠קִּ֣יצוֹנָ֔ה בַּ⁠מַּחְבֶּ֖רֶת הַ⁠שֵּׁנִֽית׃","wa⁠yȧ֜ʻaş̂ luֽlĕʼò֣ţ ţĕ̇ké֗leţ ʻa֣l şĕ̂pa֤ţ ha⁠yĕriyʻáh֙ háֽ⁠ʼeẖá֔ţ mi⁠qá̇ẕá֖h bȧ⁠mȧẖĕbá֑̇reţ ké֤̇n ʻáşá̂h֙ bi̇⁠şĕ̂pa֣ţ ha⁠yĕriyʻá֔h ha⁠qi֣̇yẕwòná֔h bȧ⁠mȧẖĕbė֖reţ ha⁠şé̇̌niֽyţ׃"],[36,12,"חֲמִשִּׁ֣ים לֻלָאֹ֗ת עָשָׂה֮ בַּ⁠יְרִיעָ֣ה הָ⁠אֶחָת֒ וַ⁠חֲמִשִּׁ֣ים לֻלָאֹ֗ת עָשָׂה֙ בִּ⁠קְצֵ֣ה הַ⁠יְרִיעָ֔ה אֲשֶׁ֖ר בַּ⁠מַּחְבֶּ֣רֶת הַ⁠שֵּׁנִ֑ית מַקְבִּילֹת֙ הַ⁠לֻּ֣לָאֹ֔ת אַחַ֖ת אֶל־אֶחָֽת׃","ẖàmişi֣̇̌ym luláʼò֗ţ ʻáşá̂h֮ bȧ⁠yĕriyʻá֣h há⁠ʼeẖáţ֒ wa⁠ẖàmişi֣̇̌ym luláʼò֗ţ ʻáşá̂h֙ bi̇⁠qĕẕé֣h ha⁠yĕriyʻá֔h ʼàşě֖r bȧ⁠mȧẖĕbė֣reţ ha⁠şé̇̌ni֑yţ maqĕbi̇ylòţ֙ ha⁠lu֣̇láʼò֔ţ ʼaẖa֖ţ ʼel-ʼeẖáֽţ׃"],[36,13,"וַ⁠יַּ֕עַשׂ חֲמִשִּׁ֖ים קַרְסֵ֣י זָהָ֑ב וַ⁠יְחַבֵּ֨ר אֶת־הַ⁠יְרִעֹ֜ת אַחַ֤ת אֶל־אַחַת֙ בַּ⁠קְּרָסִ֔ים וַֽ⁠יְהִ֥י הַ⁠מִּשְׁכָּ֖ן אֶחָֽד׃ס","wa⁠yȧ֕ʻaş̂ ẖàmişi֖̇̌ym qarĕsé֣y záhá֑b wa⁠yĕẖabé̇֨r ʼeţ-ha⁠yĕriʻò֜ţ ʼaẖa֤ţ ʼel-ʼaẖaţ֙ bȧ⁠qĕ̇rási֔ym waֽ⁠yĕhi֥y ha⁠mi̇şĕ̌ká֖̇n ʼeẖáֽd׃s"],[36,14,"וַ⁠יַּ֨עַשׂ֙ יְרִיעֹ֣ת עִזִּ֔ים לְ⁠אֹ֖הֶל עַל־הַ⁠מִּשְׁכָּ֑ן עַשְׁתֵּֽי־עֶשְׂרֵ֥ה יְרִיעֹ֖ת עָשָׂ֥ה אֹתָֽ⁠ם׃","wa⁠yȧ֨ʻaş̂֙ yĕriyʻò֣ţ ʻizi̇֔ym lĕ⁠ʼò֖hel ʻal-ha⁠mi̇şĕ̌ká֑̇n ʻaşĕ̌ţéֽ̇y-ʻeşĕ̂ré֥h yĕriyʻò֖ţ ʻáşá֥̂h ʼòţáֽ⁠m׃"],[36,15,"אֹ֜רֶךְ הַ⁠יְרִיעָ֣ה הָ⁠אַחַ֗ת שְׁלֹשִׁים֙ בָּֽ⁠אַמָּ֔ה וְ⁠אַרְבַּ֣ע אַמּ֔וֹת רֹ֖חַב הַ⁠יְרִיעָ֣ה הָ⁠אֶחָ֑ת מִדָּ֣ה אַחַ֔ת לְ⁠עַשְׁתֵּ֥י עֶשְׂרֵ֖ה יְרִיעֹֽת׃","ʼò֜rekĕ ha⁠yĕriyʻá֣h há⁠ʼaẖa֗ţ şĕ̌lòşǐym֙ báֽ̇⁠ʼamá̇֔h wĕ⁠ʼarĕbȧ֣ʻ ʼaṁ֔wòţ rò֖ẖab ha⁠yĕriyʻá֣h há⁠ʼeẖá֑ţ midá֣̇h ʼaẖa֔ţ lĕ⁠ʻaşĕ̌ţé֥̇y ʻeşĕ̂ré֖h yĕriyʻòֽţ׃"],[36,16,"וַ⁠יְחַבֵּ֛ר אֶת־חֲמֵ֥שׁ הַ⁠יְרִיעֹ֖ת לְ⁠בָ֑ד וְ⁠אֶת־שֵׁ֥שׁ הַ⁠יְרִיעֹ֖ת לְ⁠בָֽד׃","wa⁠yĕẖabé֛̇r ʼeţ-ẖàmé֥ş̌ ha⁠yĕriyʻò֖ţ lĕ⁠bá֑d wĕ⁠ʼeţ-şé֥̌ş̌ ha⁠yĕriyʻò֖ţ lĕ⁠báֽd׃"],[36,17,"וַ⁠יַּ֜עַשׂ לֻֽלָאֹ֣ת חֲמִשִּׁ֗ים עַ֚ל שְׂפַ֣ת הַ⁠יְרִיעָ֔ה הַ⁠קִּיצֹנָ֖ה בַּ⁠מַּחְבָּ֑רֶת וַ⁠חֲמִשִּׁ֣ים לֻלָאֹ֗ת עָשָׂה֙ עַל־שְׂפַ֣ת הַ⁠יְרִיעָ֔ה הַ⁠חֹבֶ֖רֶת הַ⁠שֵּׁנִֽית׃","wa⁠yȧ֜ʻaş̂ luֽláʼò֣ţ ẖàmişi̇̌֗ym ʻa֚l şĕ̂pa֣ţ ha⁠yĕriyʻá֔h ha⁠qi̇yẕòná֖h bȧ⁠mȧẖĕbá֑̇reţ wa⁠ẖàmişi֣̇̌ym luláʼò֗ţ ʻáşá̂h֙ ʻal-şĕ̂pa֣ţ ha⁠yĕriyʻá֔h ha⁠ẖòbe֖reţ ha⁠şé̇̌niֽyţ׃"],[36,18,"וַ⁠יַּ֛עַשׂ קַרְסֵ֥י נְחֹ֖שֶׁת חֲמִשִּׁ֑ים לְ⁠חַבֵּ֥ר אֶת־הָ⁠אֹ֖הֶל לִֽ⁠הְיֹ֥ת אֶחָֽד׃","wa⁠yȧ֛ʻaş̂ qarĕsé֥y nĕẖò֖şěţ ẖàmişi֑̇̌ym lĕ⁠ẖabé֥̇r ʼeţ-há⁠ʼò֖hel liֽ⁠hĕyò֥ţ ʼeẖáֽd׃"],[36,19,"וַ⁠יַּ֤עַשׂ מִכְסֶה֙ לָ⁠אֹ֔הֶל עֹרֹ֥ת אֵלִ֖ים מְאָדָּמִ֑ים וּ⁠מִכְסֵ֛ה עֹרֹ֥ת תְּחָשִׁ֖ים מִ⁠לְ⁠מָֽעְלָ⁠ה׃ס","wa⁠yȧ֤ʻaş̂ mikĕseh֙ lá⁠ʼò֔hel ʻòrò֥ţ ʼéli֖ym mĕʼádá̇mi֑ym ẇ⁠mikĕsé֛h ʻòrò֥ţ ţĕ̇ẖáşǐ֖ym mi⁠lĕ⁠máֽʻĕlá⁠h׃s"],[36,20,"וַ⁠יַּ֥עַשׂ אֶת־הַ⁠קְּרָשִׁ֖ים לַ⁠מִּשְׁכָּ֑ן עֲצֵ֥י שִׁטִּ֖ים עֹמְדִֽים׃","wa⁠yȧ֥ʻaş̂ ʼeţ-ha⁠qĕ̇ráşǐ֖ym la⁠mi̇şĕ̌ká֑̇n ʻàẕé֥y şǐti֖̇ym ʻòmĕdiֽym׃"],[36,21,"עֶ֥שֶׂר אַמֹּ֖ת אֹ֣רֶךְ הַ⁠קָּ֑רֶשׁ וְ⁠אַמָּה֙ וַ⁠חֲצִ֣י הָֽ⁠אַמָּ֔ה רֹ֖חַב הַ⁠קֶּ֥רֶשׁ הָ⁠אֶחָֽד׃","ʻe֥şêr ʼamò֖̇ţ ʼò֣rekĕ ha⁠qá֑̇reş̌ wĕ⁠ʼamá̇h֙ wa⁠ẖàẕi֣y háֽ⁠ʼamá̇֔h rò֖ẖab ha⁠qė֥reş̌ há⁠ʼeẖáֽd׃"],[36,22,"שְׁתֵּ֣י יָדֹ֗ת לַ⁠קֶּ֨רֶשׁ֙ הָֽ⁠אֶחָ֔ד מְשֻׁלָּבֹ֔ת אַחַ֖ת אֶל־אֶחָ֑ת כֵּ֣ן עָשָׂ֔ה לְ⁠כֹ֖ל קַרְשֵׁ֥י הַ⁠מִּשְׁכָּֽן׃","şĕ̌ţé֣̇y yádò֗ţ la⁠qė֨reş̌֙ háֽ⁠ʼeẖá֔d mĕşǔlá̇bò֔ţ ʼaẖa֖ţ ʼel-ʼeẖá֑ţ ké֣̇n ʻáşá̂֔h lĕ⁠kò֖l qarĕşé֥̌y ha⁠mi̇şĕ̌káֽ̇n׃"],[36,23,"וַ⁠יַּ֥עַשׂ אֶת־הַ⁠קְּרָשִׁ֖ים לַ⁠מִּשְׁכָּ֑ן עֶשְׂרִ֣ים קְרָשִׁ֔ים לִ⁠פְאַ֖ת נֶ֥גֶב תֵּימָֽנָ⁠ה׃","wa⁠yȧ֥ʻaş̂ ʼeţ-ha⁠qĕ̇ráşǐ֖ym la⁠mi̇şĕ̌ká֑̇n ʻeşĕ̂ri֣ym qĕráşǐ֔ym li⁠pĕʼa֖ţ ne֥geb ţé̇ymáֽná⁠h׃"],[36,24,"וְ⁠אַרְבָּעִים֙ אַדְנֵי־כֶ֔סֶף עָשָׂ֕ה תַּ֖חַת עֶשְׂרִ֣ים הַ⁠קְּרָשִׁ֑ים שְׁנֵ֨י אֲדָנִ֜ים תַּֽחַת־הַ⁠קֶּ֤רֶשׁ הָ⁠אֶחָד֙ לִ⁠שְׁתֵּ֣י יְדֹתָ֔י⁠ו וּ⁠שְׁנֵ֧י אֲדָנִ֛ים תַּֽחַת־הַ⁠קֶּ֥רֶשׁ הָ⁠אֶחָ֖ד לִ⁠שְׁתֵּ֥י יְדֹתָֽי⁠ו׃","wĕ⁠ʼarĕbá̇ʻiym֙ ʼadĕnéy-ke֔sep ʻáşá̂֕h ţȧ֖ẖaţ ʻeşĕ̂ri֣ym ha⁠qĕ̇ráşǐ֑ym şĕ̌né֨y ʼàdáni֜ym ţȧֽẖaţ-ha⁠qė֤reş̌ há⁠ʼeẖád֙ li⁠şĕ̌ţé֣̇y yĕdòţá֔y⁠w ẇ⁠şĕ̌né֧y ʼàdáni֛ym ţȧֽẖaţ-ha⁠qė֥reş̌ há⁠ʼeẖá֖d li⁠şĕ̌ţé֥̇y yĕdòţáֽy⁠w׃"],[36,25,"וּ⁠לְ⁠צֶ֧לַע הַ⁠מִּשְׁכָּ֛ן הַ⁠שֵּׁנִ֖ית לִ⁠פְאַ֣ת צָפ֑וֹן עָשָׂ֖ה עֶשְׂרִ֥ים קְרָשִֽׁים׃","ẇ⁠lĕ⁠ẕe֧laʻ ha⁠mi̇şĕ̌ká֛̇n ha⁠şé̇̌ni֖yţ li⁠pĕʼa֣ţ ẕáp֑wòn ʻáşá֖̂h ʻeşĕ̂ri֥ym qĕráşǐֽym׃"],[36,26,"וְ⁠אַרְבָּעִ֥ים אַדְנֵי⁠הֶ֖ם כָּ֑סֶף שְׁנֵ֣י אֲדָנִ֗ים תַּ֚חַת הַ⁠קֶּ֣רֶשׁ הָ⁠אֶחָ֔ד וּ⁠שְׁנֵ֣י אֲדָנִ֔ים תַּ֖חַת הַ⁠קֶּ֥רֶשׁ הָ⁠אֶחָֽד׃","wĕ⁠ʼarĕbá̇ʻi֥ym ʼadĕnéy⁠he֖m ká֑̇sep şĕ̌né֣y ʼàdáni֗ym ţȧ֚ẖaţ ha⁠qė֣reş̌ há⁠ʼeẖá֔d ẇ⁠şĕ̌né֣y ʼàdáni֔ym ţȧ֖ẖaţ ha⁠qė֥reş̌ há⁠ʼeẖáֽd׃"],[36,27,"וּֽ⁠לְ⁠יַרְכְּתֵ֥י הַ⁠מִּשְׁכָּ֖ן יָ֑מָּ⁠ה עָשָׂ֖ה שִׁשָּׁ֥ה קְרָשִֽׁים׃","ẇֽ⁠lĕ⁠yarĕkĕ̇ţé֥y ha⁠mi̇şĕ̌ká֖̇n yá֑má̇⁠h ʻáşá֖̂h şǐşá֥̇̌h qĕráşǐֽym׃"],[36,28,"וּ⁠שְׁנֵ֤י קְרָשִׁים֙ עָשָׂ֔ה לִ⁠מְקֻצְעֹ֖ת הַ⁠מִּשְׁכָּ֑ן בַּ⁠יַּרְכָתָֽיִם׃","ẇ⁠şĕ̌né֤y qĕráşǐym֙ ʻáşá̂֔h li⁠mĕquẕĕʻò֖ţ ha⁠mi̇şĕ̌ká֑̇n bȧ⁠yȧrĕkáţáֽyim׃"],[36,29,"וְ⁠הָי֣וּ תוֹאֲמִם֮ מִ⁠לְּ⁠מַטָּה֒ וְ⁠יַחְדָּ֗ו יִהְי֤וּ תַמִּים֙ אֶל־רֹאשׁ֔⁠וֹ אֶל־הַ⁠טַּבַּ֖עַת הָ⁠אֶחָ֑ת כֵּ֚ן עָשָׂ֣ה לִ⁠שְׁנֵי⁠הֶ֔ם לִ⁠שְׁנֵ֖י הַ⁠מִּקְצֹעֹֽת׃","wĕ⁠háy֣ẇ ţwòʼàmim֮ mi⁠lĕ̇⁠matá̇h֒ wĕ⁠yaẖĕdá̇֗w yihĕy֤ẇ ţami̇ym֙ ʼel-ròʼş̌֔⁠wò ʼel-ha⁠tȧbȧ֖ʻaţ há⁠ʼeẖá֑ţ ké֚̇n ʻáşá֣̂h li⁠şĕ̌néy⁠he֔m li⁠şĕ̌né֖y ha⁠mi̇qĕẕòʻòֽţ׃"],[36,30,"וְ⁠הָיוּ֙ שְׁמֹנָ֣ה קְרָשִׁ֔ים וְ⁠אַדְנֵי⁠הֶ֣ם כֶּ֔סֶף שִׁשָּׁ֥ה עָשָׂ֖ר אֲדָנִ֑ים שְׁנֵ֤י אֲדָנִים֙ שְׁנֵ֣י אֲדָנִ֔ים תַּ֖חַת הַ⁠קֶּ֥רֶשׁ הָ⁠אֶחָֽד׃","wĕ⁠háyẇ֙ şĕ̌mòná֣h qĕráşǐ֔ym wĕ⁠ʼadĕnéy⁠he֣m kė֔sep şǐşá֥̇̌h ʻáşá֖̂r ʼàdáni֑ym şĕ̌né֤y ʼàdániym֙ şĕ̌né֣y ʼàdáni֔ym ţȧ֖ẖaţ ha⁠qė֥reş̌ há⁠ʼeẖáֽd׃"],[36,31,"וַ⁠יַּ֥עַשׂ בְּרִיחֵ֖י עֲצֵ֣י שִׁטִּ֑ים חֲמִשָּׁ֕ה לְ⁠קַרְשֵׁ֥י צֶֽלַע־הַ⁠מִּשְׁכָּ֖ן הָ⁠אֶחָֽת׃","wa⁠yȧ֥ʻaş̂ bĕ̇riyẖé֖y ʻàẕé֣y şǐti֑̇ym ẖàmişá̇̌֕h lĕ⁠qarĕşé֥̌y ẕeֽlaʻ-ha⁠mi̇şĕ̌ká֖̇n há⁠ʼeẖáֽţ׃"],[36,32,"וַ⁠חֲמִשָּׁ֣ה בְרִיחִ֔ם לְ⁠קַרְשֵׁ֥י צֶֽלַע־הַ⁠מִּשְׁכָּ֖ן הַ⁠שֵּׁנִ֑ית וַ⁠חֲמִשָּׁ֤ה בְרִיחִם֙ לְ⁠קַרְשֵׁ֣י הַ⁠מִּשְׁכָּ֔ן לַ⁠יַּרְכָתַ֖יִם יָֽמָּ⁠ה׃","wa⁠ẖàmişá֣̇̌h bĕriyẖi֔m lĕ⁠qarĕşé֥̌y ẕeֽlaʻ-ha⁠mi̇şĕ̌ká֖̇n ha⁠şé̇̌ni֑yţ wa⁠ẖàmişá֤̇̌h bĕriyẖim֙ lĕ⁠qarĕşé֣̌y ha⁠mi̇şĕ̌ká̇֔n la⁠yȧrĕkáţa֖yim yáֽmá̇⁠h׃"],[36,33,"וַ⁠יַּ֖עַשׂ אֶת־הַ⁠בְּרִ֣יחַ הַ⁠תִּיכֹ֑ן לִ⁠בְרֹ֨חַ֙ בְּ⁠ת֣וֹךְ הַ⁠קְּרָשִׁ֔ים מִן־הַ⁠קָּצֶ֖ה אֶל־הַ⁠קָּצֶֽה׃","wa⁠yȧ֖ʻaş̂ ʼeţ-ha⁠bĕ̇ri֣yẖa ha⁠ţi̇ykò֑n li⁠bĕrò֨ẖa֙ bĕ̇⁠ţ֣wòkĕ ha⁠qĕ̇ráşǐ֔ym min-ha⁠qá̇ẕe֖h ʼel-ha⁠qá̇ẕeֽh׃"],[36,34,"וְֽ⁠אֶת־הַ⁠קְּרָשִׁ֞ים צִפָּ֣ה זָהָ֗ב וְ⁠אֶת־טַבְּעֹתָ⁠ם֙ עָשָׂ֣ה זָהָ֔ב בָּתִּ֖ים לַ⁠בְּרִיחִ֑ם וַ⁠יְצַ֥ף אֶת־הַ⁠בְּרִיחִ֖ם זָהָֽב׃","wĕֽ⁠ʼeţ-ha⁠qĕ̇ráşǐ֞ym ẕipá֣̇h záhá֗b wĕ⁠ʼeţ-tabĕ̇ʻòţá⁠m֙ ʻáşá֣̂h záhá֔b bá̇ţi֖̇ym la⁠bĕ̇riyẖi֑m wa⁠yĕẕa֥p ʼeţ-ha⁠bĕ̇riyẖi֖m záháֽb׃"],[36,35,"וַ⁠יַּ֨עַשׂ֙ אֶת־הַ⁠פָּרֹ֔כֶת תְּכֵ֧לֶת וְ⁠אַרְגָּמָ֛ן וְ⁠תוֹלַ֥עַת שָׁנִ֖י וְ⁠שֵׁ֣שׁ מָשְׁזָ֑ר מַעֲשֵׂ֥ה חֹשֵׁ֛ב עָשָׂ֥ה אֹתָ֖⁠הּ כְּרֻבִֽים׃","wa⁠yȧ֨ʻaş̂֙ ʼeţ-ha⁠pá̇rò֔keţ ţĕ̇ké֧leţ wĕ⁠ʼarĕgá̇má֛n wĕ⁠ţwòla֥ʻaţ şá̌ni֖y wĕ⁠şé֣̌ş̌ máşĕ̌zá֑r maʻàşé֥̂h ẖòşé֛̌b ʻáşá֥̂h ʼòţá֖⁠ḣ kĕ̇rubiֽym׃"],[36,36,"וַ⁠יַּ֣עַשׂ לָ֗⁠הּ אַרְבָּעָה֙ עַמּוּדֵ֣י שִׁטִּ֔ים וַ⁠יְצַפֵּ֣⁠ם זָהָ֔ב וָוֵי⁠הֶ֖ם זָהָ֑ב וַ⁠יִּצֹ֣ק לָ⁠הֶ֔ם אַרְבָּעָ֖ה אַדְנֵי־כָֽסֶף׃","wa⁠yȧ֣ʻaş̂ lá֗⁠ḣ ʼarĕbá̇ʻáh֙ ʻaṁẇdé֣y şǐti̇֔ym wa⁠yĕẕapé֣̇⁠m záhá֔b wáwéy⁠he֖m záhá֑b wa⁠yi̇ẕò֣q lá⁠he֔m ʼarĕbá̇ʻá֖h ʼadĕnéy-káֽsep׃"],[36,37,"וַ⁠יַּ֤עַשׂ מָסָךְ֙ לְ⁠פֶ֣תַח הָ⁠אֹ֔הֶל תְּכֵ֧לֶת וְ⁠אַרְגָּמָ֛ן וְ⁠תוֹלַ֥עַת שָׁנִ֖י וְ⁠שֵׁ֣שׁ מָשְׁזָ֑ר מַעֲשֵׂ֖ה רֹקֵֽם׃","wa⁠yȧ֤ʻaş̂ másákĕ֙ lĕ⁠pe֣ţaẖ há⁠ʼò֔hel ţĕ̇ké֧leţ wĕ⁠ʼarĕgá̇má֛n wĕ⁠ţwòla֥ʻaţ şá̌ni֖y wĕ⁠şé֣̌ş̌ máşĕ̌zá֑r maʻàşé֖̂h ròqéֽm׃"],[36,38,"וְ⁠אֶת־עַמּוּדָ֤י⁠ו חֲמִשָּׁה֙ וְ⁠אֶת־וָ֣וֵי⁠הֶ֔ם וְ⁠צִפָּ֧ה רָאשֵׁי⁠הֶ֛ם וַ⁠חֲשֻׁקֵי⁠הֶ֖ם זָהָ֑ב וְ⁠אַדְנֵי⁠הֶ֥ם חֲמִשָּׁ֖ה נְחֹֽשֶׁת׃פ","wĕ⁠ʼeţ-ʻaṁẇdá֤y⁠w ẖàmişá̇̌h֙ wĕ⁠ʼeţ-wá֣wéy⁠he֔m wĕ⁠ẕipá֧̇h ráʼşé̌y⁠he֛m wa⁠ẖàşǔqéy⁠he֖m záhá֑b wĕ⁠ʼadĕnéy⁠he֥m ẖàmişá֖̇̌h nĕẖòֽşěţ׃p"],[37,1,"וַ⁠יַּ֧עַשׂ בְּצַלְאֵ֛ל אֶת־הָ⁠אָרֹ֖ן עֲצֵ֣י שִׁטִּ֑ים אַמָּתַ֨יִם וָ⁠חֵ֜צִי אָרְכּ֗⁠וֹ וְ⁠אַמָּ֤ה וָ⁠חֵ֨צִי֙ רָחְבּ֔⁠וֹ וְ⁠אַמָּ֥ה וָ⁠חֵ֖צִי קֹמָתֽ⁠וֹ׃","wa⁠yȧ֧ʻaş̂ bĕ̇ẕalĕʼé֛l ʼeţ-há⁠ʼárò֖n ʻàẕé֣y şǐti֑̇ym ʼamá̇ţa֨yim wá⁠ẖé֜ẕiy ʼárĕk̇֗⁠wò wĕ⁠ʼamá֤̇h wá⁠ẖé֨ẕiy֙ ráẖĕḃ֔⁠wò wĕ⁠ʼamá֥̇h wá⁠ẖé֖ẕiy qòmáţֽ⁠wò׃"],[37,2,"וַ⁠יְצַפֵּ֛⁠הוּ זָהָ֥ב טָה֖וֹר מִ⁠בַּ֣יִת וּ⁠מִ⁠ח֑וּץ וַ⁠יַּ֥עַשׂ ל֛⁠וֹ זֵ֥ר זָהָ֖ב סָבִֽיב׃","wa⁠yĕẕapé֛̇⁠hẇ záhá֥b táh֖wòr mi⁠bȧ֣yiţ ẇ⁠mi⁠ẖ֑ẇẕ wa⁠yȧ֥ʻaş̂ l֛⁠wò zé֥r záhá֖b sábiֽyb׃"],[37,3,"וַ⁠יִּצֹ֣ק ל֗⁠וֹ אַרְבַּע֙ טַבְּעֹ֣ת זָהָ֔ב עַ֖ל אַרְבַּ֣ע פַּעֲמֹתָ֑י⁠ו וּ⁠שְׁתֵּ֣י טַבָּעֹ֗ת עַל־צַלְע⁠וֹ֙ הָֽ⁠אֶחָ֔ת וּ⁠שְׁתֵּי֙ טַבָּע֔וֹת עַל־צַלְע֖⁠וֹ הַ⁠שֵּׁנִֽית׃","wa⁠yi̇ẕò֣q l֗⁠wò ʼarĕbȧʻ֙ tabĕ̇ʻò֣ţ záhá֔b ʻa֖l ʼarĕbȧ֣ʻ pȧʻàmòţá֑y⁠w ẇ⁠şĕ̌ţé֣̇y tabá̇ʻò֗ţ ʻal-ẕalĕʻ⁠wò֙ háֽ⁠ʼeẖá֔ţ ẇ⁠şĕ̌ţé̇y֙ tabá̇ʻ֔wòţ ʻal-ẕalĕʻ֖⁠wò ha⁠şé̇̌niֽyţ׃"],[37,4,"וַ⁠יַּ֥עַשׂ בַּדֵּ֖י עֲצֵ֣י שִׁטִּ֑ים וַ⁠יְצַ֥ף אֹתָ֖⁠ם זָהָֽב׃","wa⁠yȧ֥ʻaş̂ bȧdé֖̇y ʻàẕé֣y şǐti֑̇ym wa⁠yĕẕa֥p ʼòţá֖⁠m záháֽb׃"],[37,5,"וַ⁠יָּבֵ֤א אֶת־הַ⁠בַּדִּים֙ בַּ⁠טַּבָּעֹ֔ת עַ֖ל צַלְעֹ֣ת הָ⁠אָרֹ֑ן לָ⁠שֵׂ֖את אֶת־הָ⁠אָרֹֽן׃","wa⁠yá̇bé֤ʼ ʼeţ-ha⁠bȧdi̇ym֙ bȧ⁠tȧbá̇ʻò֔ţ ʻa֖l ẕalĕʻò֣ţ há⁠ʼárò֑n lá⁠şé֖̂ʼţ ʼeţ-há⁠ʼáròֽn׃"],[37,6,"וַ⁠יַּ֥עַשׂ כַּפֹּ֖רֶת זָהָ֣ב טָה֑וֹר אַמָּתַ֤יִם וָ⁠חֵ֨צִי֙ אָרְכָּ֔⁠הּ וְ⁠אַמָּ֥ה וָ⁠חֵ֖צִי רָחְבָּֽ⁠הּ׃","wa⁠yȧ֥ʻaş̂ kȧpò֖̇reţ záhá֣b táh֑wòr ʼamá̇ţa֤yim wá⁠ẖé֨ẕiy֙ ʼárĕká̇֔⁠ḣ wĕ⁠ʼamá֥̇h wá⁠ẖé֖ẕiy ráẖĕbáֽ̇⁠ḣ׃"],[37,7,"וַ⁠יַּ֛עַשׂ שְׁנֵ֥י כְרֻבִ֖ים זָהָ֑ב מִקְשָׁה֙ עָשָׂ֣ה אֹתָ֔⁠ם מִ⁠שְּׁנֵ֖י קְצ֥וֹת הַ⁠כַּפֹּֽרֶת׃","wa⁠yȧ֛ʻaş̂ şĕ̌né֥y kĕrubi֖ym záhá֑b miqĕşá̌h֙ ʻáşá֣̂h ʼòţá֔⁠m mi⁠şĕ̇̌né֖y qĕẕ֥wòţ ha⁠kȧpòֽ̇reţ׃"],[37,8,"כְּרוּב־אֶחָ֤ד מִ⁠קָּצָה֙ מִ⁠זֶּ֔ה וּ⁠כְרוּב־אֶחָ֥ד מִ⁠קָּצָ֖ה מִ⁠זֶּ֑ה מִן־הַ⁠כַּפֹּ֛רֶת עָשָׂ֥ה אֶת־הַ⁠כְּרֻבִ֖ים מִ⁠שְּׁנֵ֥י קצוות⁠ו׃","kĕ̇rẇb-ʼeẖá֤d mi⁠qá̇ẕáh֙ mi⁠zė֔h ẇ⁠kĕrẇb-ʼeẖá֥d mi⁠qá̇ẕá֖h mi⁠zė֑h min-ha⁠kȧpò֛̇reţ ʻáşá֥̂h ʼeţ-ha⁠kĕ̇rubi֖ym mi⁠şĕ̇̌né֥y qẕwwţ⁠w׃"],[37,9,"וַ⁠יִּהְי֣וּ הַ⁠כְּרֻבִים֩ פֹּרְשֵׂ֨י כְנָפַ֜יִם לְ⁠מַ֗עְלָ⁠ה סֹֽכְכִ֤ים בְּ⁠כַנְפֵי⁠הֶם֙ עַל־הַ⁠כַּפֹּ֔רֶת וּ⁠פְנֵי⁠הֶ֖ם אִ֣ישׁ אֶל־אָחִ֑י⁠ו אֶל־הַ⁠כַּפֹּ֔רֶת הָי֖וּ פְּנֵ֥י הַ⁠כְּרֻבִֽים׃פ","wa⁠yi̇hĕy֣ẇ ha⁠kĕ̇rubiym֩ pò̇rĕşé̂֨y kĕnápa֜yim lĕ⁠ma֗ʻĕlá⁠h sòֽkĕki֤ym bĕ̇⁠kanĕpéy⁠hem֙ ʻal-ha⁠kȧpò̇֔reţ ẇ⁠pĕnéy⁠he֖m ʼi֣yş̌ ʼel-ʼáẖi֑y⁠w ʼel-ha⁠kȧpò̇֔reţ háy֖ẇ pĕ̇né֥y ha⁠kĕ̇rubiֽym׃p"],[37,10,"וַ⁠יַּ֥עַשׂ אֶת־הַ⁠שֻּׁלְחָ֖ן עֲצֵ֣י שִׁטִּ֑ים אַמָּתַ֤יִם אָרְכּ⁠וֹ֙ וְ⁠אַמָּ֣ה רָחְבּ֔⁠וֹ וְ⁠אַמָּ֥ה וָ⁠חֵ֖צִי קֹמָתֽ⁠וֹ׃","wa⁠yȧ֥ʻaş̂ ʼeţ-ha⁠şu̇̌lĕẖá֖n ʻàẕé֣y şǐti֑̇ym ʼamá̇ţa֤yim ʼárĕk̇⁠wò֙ wĕ⁠ʼamá֣̇h ráẖĕḃ֔⁠wò wĕ⁠ʼamá֥̇h wá⁠ẖé֖ẕiy qòmáţֽ⁠wò׃"],[37,11,"וַ⁠יְצַ֥ף אֹת֖⁠וֹ זָהָ֣ב טָה֑וֹר וַ⁠יַּ֥עַשׂ ל֛⁠וֹ זֵ֥ר זָהָ֖ב סָבִֽיב׃","wa⁠yĕẕa֥p ʼòţ֖⁠wò záhá֣b táh֑wòr wa⁠yȧ֥ʻaş̂ l֛⁠wò zé֥r záhá֖b sábiֽyb׃"],[37,12,"וַ⁠יַּ֨עַשׂ ל֥⁠וֹ מִסְגֶּ֛רֶת טֹ֖פַח סָבִ֑יב וַ⁠יַּ֧עַשׂ זֵר־זָהָ֛ב לְ⁠מִסְגַּרְתּ֖⁠וֹ סָבִֽיב׃","wa⁠yȧ֨ʻaş̂ l֥⁠wò misĕgė֛reţ tò֖paẖ sábi֑yb wa⁠yȧ֧ʻaş̂ zér-záhá֛b lĕ⁠misĕgȧrĕţ֖̇⁠wò sábiֽyb׃"],[37,13,"וַ⁠יִּצֹ֣ק ל֔⁠וֹ אַרְבַּ֖ע טַבְּעֹ֣ת זָהָ֑ב וַ⁠יִּתֵּן֙ אֶת־הַ⁠טַּבָּעֹ֔ת עַ֚ל אַרְבַּ֣ע הַ⁠פֵּאֹ֔ת אֲשֶׁ֖ר לְ⁠אַרְבַּ֥ע רַגְלָֽי⁠ו׃","wa⁠yi̇ẕò֣q l֔⁠wò ʼarĕbȧ֖ʻ tabĕ̇ʻò֣ţ záhá֑b wa⁠yi̇ţé̇n֙ ʼeţ-ha⁠tȧbá̇ʻò֔ţ ʻa֚l ʼarĕbȧ֣ʻ ha⁠pé̇ʼò֔ţ ʼàşě֖r lĕ⁠ʼarĕbȧ֥ʻ ragĕláֽy⁠w׃"],[37,14,"לְ⁠עֻמַּת֙ הַ⁠מִּסְגֶּ֔רֶת הָי֖וּ הַ⁠טַּבָּעֹ֑ת בָּתִּים֙ לַ⁠בַּדִּ֔ים לָ⁠שֵׂ֖את אֶת־הַ⁠שֻּׁלְחָֽן׃","lĕ⁠ʻumȧţ֙ ha⁠mi̇sĕgė֔reţ háy֖ẇ ha⁠tȧbá̇ʻò֑ţ bá̇ţi̇ym֙ la⁠bȧdi̇֔ym lá⁠şé֖̂ʼţ ʼeţ-ha⁠şu̇̌lĕẖáֽn׃"],[37,15,"וַ⁠יַּ֤עַשׂ אֶת־הַ⁠בַּדִּים֙ עֲצֵ֣י שִׁטִּ֔ים וַ⁠יְצַ֥ף אֹתָ֖⁠ם זָהָ֑ב לָ⁠שֵׂ֖את אֶת־הַ⁠שֻּׁלְחָֽן׃","wa⁠yȧ֤ʻaş̂ ʼeţ-ha⁠bȧdi̇ym֙ ʻàẕé֣y şǐti̇֔ym wa⁠yĕẕa֥p ʼòţá֖⁠m záhá֑b lá⁠şé֖̂ʼţ ʼeţ-ha⁠şu̇̌lĕẖáֽn׃"],[37,16,"וַ⁠יַּ֜עַשׂ אֶֽת־הַ⁠כֵּלִ֣ים ׀ אֲשֶׁ֣ר עַל־הַ⁠שֻּׁלְחָ֗ן אֶת־קְעָרֹתָ֤י⁠ו וְ⁠אֶת־כַּפֹּתָי⁠ו֙ וְ⁠אֵת֙ מְנַקִּיֹּתָ֔י⁠ו וְ⁠אֶת־הַ⁠קְּשָׂוֺ֔ת אֲשֶׁ֥ר יֻסַּ֖ךְ בָּ⁠הֵ֑ן זָהָ֖ב טָהֽוֹר׃פ","wa⁠yȧ֜ʻaş̂ ʼeֽţ-ha⁠ké̇li֣ym ׀ ʼàşě֣r ʻal-ha⁠şu̇̌lĕẖá֗n ʼeţ-qĕʻáròţá֤y⁠w wĕ⁠ʼeţ-kȧpò̇ţáy⁠w֙ wĕ⁠ʼéţ֙ mĕnaqi̇yò̇ţá֔y⁠w wĕ⁠ʼeţ-ha⁠qĕ̇şá̂wֺ֔ţ ʼàşě֥r yusȧ֖kĕ bá̇⁠hé֑n záhá֖b táhֽwòr׃p"],[37,17,"וַ⁠יַּ֥עַשׂ אֶת־הַ⁠מְּנֹרָ֖ה זָהָ֣ב טָה֑וֹר מִקְשָׁ֞ה עָשָׂ֤ה אֶת־הַ⁠מְּנֹרָה֙ יְרֵכָ֣⁠הּ וְ⁠קָנָ֔⁠הּ גְּבִיעֶ֛י⁠הָ כַּפְתֹּרֶ֥י⁠הָ וּ⁠פְרָחֶ֖י⁠הָ מִמֶּ֥⁠נָּה הָיֽוּ׃","wa⁠yȧ֥ʻaş̂ ʼeţ-ha⁠mĕ̇nòrá֖h záhá֣b táh֑wòr miqĕşá̌֞h ʻáşá֤̂h ʼeţ-ha⁠mĕ̇nòráh֙ yĕréká֣⁠ḣ wĕ⁠qáná֔⁠ḣ gĕ̇biyʻe֛y⁠há kȧpĕţò̇re֥y⁠há ẇ⁠pĕráẖe֖y⁠há mimė֥⁠ná̇h háyֽẇ׃"],[37,18,"וְ⁠שִׁשָּׁ֣ה קָנִ֔ים יֹצְאִ֖ים מִ⁠צִּדֶּ֑י⁠הָ שְׁלֹשָׁ֣ה ׀ קְנֵ֣י מְנֹרָ֗ה מִ⁠צִּדָּ⁠הּ֙ הָֽ⁠אֶחָ֔ד וּ⁠שְׁלֹשָׁה֙ קְנֵ֣י מְנֹרָ֔ה מִ⁠צִּדָּ֖⁠הּ הַ⁠שֵּׁנִֽי׃","wĕ⁠şǐşá֣̇̌h qáni֔ym yòẕĕʼi֖ym mi⁠ẕi̇dė֑y⁠há şĕ̌lòşá֣̌h ׀ qĕné֣y mĕnòrá֗h mi⁠ẕi̇dá̇⁠ḣ֙ háֽ⁠ʼeẖá֔d ẇ⁠şĕ̌lòşá̌h֙ qĕné֣y mĕnòrá֔h mi⁠ẕi̇dá֖̇⁠ḣ ha⁠şé̇̌niֽy׃"],[37,19,"שְׁלֹשָׁ֣ה גְ֠בִעִים מְֽשֻׁקָּדִ֞ים בַּ⁠קָּנֶ֣ה הָ⁠אֶחָד֮ כַּפְתֹּ֣ר וָ⁠פֶרַח֒ וּ⁠שְׁלֹשָׁ֣ה גְבִעִ֗ים מְשֻׁקָּדִ֛ים בְּ⁠קָנֶ֥ה אֶחָ֖ד כַּפְתֹּ֣ר וָ⁠פָ֑רַח כֵּ֚ן לְ⁠שֵׁ֣שֶׁת הַ⁠קָּנִ֔ים הַ⁠יֹּצְאִ֖ים מִן־הַ⁠מְּנֹרָֽה׃","şĕ̌lòşá֣̌h gĕ֠biʻiym mĕֽşǔqá̇di֞ym bȧ⁠qá̇ne֣h há⁠ʼeẖád֮ kȧpĕţò֣̇r wá⁠peraẖ֒ ẇ⁠şĕ̌lòşá֣̌h gĕbiʻi֗ym mĕşǔqá̇di֛ym bĕ̇⁠qáne֥h ʼeẖá֖d kȧpĕţò֣̇r wá⁠pá֑raẖ ké֚̇n lĕ⁠şé֣̌şěţ ha⁠qá̇ni֔ym ha⁠yò̇ẕĕʼi֖ym min-ha⁠mĕ̇nòráֽh׃"],[37,20,"וּ⁠בַ⁠מְּנֹרָ֖ה אַרְבָּעָ֣ה גְבִעִ֑ים מְשֻׁ֨קָּדִ֔ים כַּפְתֹּרֶ֖י⁠הָ וּ⁠פְרָחֶֽי⁠הָ׃","ẇ⁠ba⁠mĕ̇nòrá֖h ʼarĕbá̇ʻá֣h gĕbiʻi֑ym mĕşǔ֨qá̇di֔ym kȧpĕţò̇re֖y⁠há ẇ⁠pĕráẖeֽy⁠há׃"],[37,21,"וְ⁠כַפְתֹּ֡ר תַּחַת֩ שְׁנֵ֨י הַ⁠קָּנִ֜ים מִמֶּ֗⁠נָּה וְ⁠כַפְתֹּר֙ תַּ֣חַת שְׁנֵ֤י הַ⁠קָּנִים֙ מִמֶּ֔⁠נָּה וְ⁠כַפְתֹּ֕ר תַּֽחַת־שְׁנֵ֥י הַ⁠קָּנִ֖ים מִמֶּ֑⁠נָּה לְ⁠שֵׁ֨שֶׁת֙ הַ⁠קָּנִ֔ים הַ⁠יֹּצְאִ֖ים מִמֶּֽ⁠נָּה׃","wĕ⁠kapĕţò̇֡r ţȧẖaţ֩ şĕ̌né֨y ha⁠qá̇ni֜ym mimė֗⁠ná̇h wĕ⁠kapĕţò̇r֙ ţȧ֣ẖaţ şĕ̌né֤y ha⁠qá̇niym֙ mimė֔⁠ná̇h wĕ⁠kapĕţò̇֕r ţȧֽẖaţ-şĕ̌né֥y ha⁠qá̇ni֖ym mimė֑⁠ná̇h lĕ⁠şé̌֨şěţ֙ ha⁠qá̇ni֔ym ha⁠yò̇ẕĕʼi֖ym mimėֽ⁠ná̇h׃"],[37,22,"כַּפְתֹּרֵי⁠הֶ֥ם וּ⁠קְנֹתָ֖⁠ם מִמֶּ֣⁠נָּה הָי֑וּ כֻּלָּ֛⁠הּ מִקְשָׁ֥ה אַחַ֖ת זָהָ֥ב טָהֽוֹר׃","kȧpĕţò̇réy⁠he֥m ẇ⁠qĕnòţá֖⁠m mimė֣⁠ná̇h háy֑ẇ ku̇lá֛̇⁠ḣ miqĕşá֥̌h ʼaẖa֖ţ záhá֥b táhֽwòr׃"],[37,23,"וַ⁠יַּ֥עַשׂ אֶת־נֵרֹתֶ֖י⁠הָ שִׁבְעָ֑ה וּ⁠מַלְקָחֶ֥י⁠הָ וּ⁠מַחְתֹּתֶ֖י⁠הָ זָהָ֥ב טָהֽוֹר׃","wa⁠yȧ֥ʻaş̂ ʼeţ-néròţe֖y⁠há şǐbĕʻá֑h ẇ⁠malĕqáẖe֥y⁠há ẇ⁠maẖĕţò̇ţe֖y⁠há záhá֥b táhֽwòr׃"],[37,24,"כִּכָּ֛ר זָהָ֥ב טָה֖וֹר עָשָׂ֣ה אֹתָ֑⁠הּ וְ⁠אֵ֖ת כָּל־כֵּלֶֽי⁠הָ׃פ","ki̇ká֛̇r záhá֥b táh֖wòr ʻáşá֣̂h ʼòţá֑⁠ḣ wĕ⁠ʼé֖ţ ká̇l-ké̇leֽy⁠há׃p"],[37,25,"וַ⁠יַּ֛עַשׂ אֶת־מִזְבַּ֥ח הַ⁠קְּטֹ֖רֶת עֲצֵ֣י שִׁטִּ֑ים אַמָּ֣ה אָרְכּ⁠וֹ֩ וְ⁠אַמָּ֨ה רָחְבּ֜⁠וֹ רָב֗וּעַ וְ⁠אַמָּתַ֨יִם֙ קֹֽמָת֔⁠וֹ מִמֶּ֖⁠נּוּ הָי֥וּ קַרְנֹתָֽי⁠ו׃","wa⁠yȧ֛ʻaş̂ ʼeţ-mizĕbȧ֥ẖ ha⁠qĕ̇tò֖reţ ʻàẕé֣y şǐti֑̇ym ʼamá֣̇h ʼárĕk̇⁠wò֩ wĕ⁠ʼamá̇֨h ráẖĕḃ֜⁠wò ráb֗ẇʻa wĕ⁠ʼamá̇ţa֨yim֙ qòֽmáţ֔⁠wò mimė֖⁠ṅẇ háy֥ẇ qarĕnòţáֽy⁠w׃"],[37,26,"וַ⁠יְצַ֨ף אֹת֜⁠וֹ זָהָ֣ב טָה֗וֹר אֶת־גַּגּ֧⁠וֹ וְ⁠אֶת־קִירֹתָ֛י⁠ו סָבִ֖יב וְ⁠אֶת־קַרְנֹתָ֑י⁠ו וַ⁠יַּ֥עַשׂ ל֛⁠וֹ זֵ֥ר זָהָ֖ב סָבִֽיב׃","wa⁠yĕẕa֨p ʼòţ֜⁠wò záhá֣b táh֗wòr ʼeţ-gȧġ֧⁠wò wĕ⁠ʼeţ-qiyròţá֛y⁠w sábi֖yb wĕ⁠ʼeţ-qarĕnòţá֑y⁠w wa⁠yȧ֥ʻaş̂ l֛⁠wò zé֥r záhá֖b sábiֽyb׃"],[37,27,"וּ⁠שְׁתֵּי֩ טַבְּעֹ֨ת זָהָ֜ב עָֽשָׂה־ל֣⁠וֹ ׀ מִ⁠תַּ֣חַת לְ⁠זֵר֗⁠וֹ עַ֚ל שְׁתֵּ֣י צַלְעֹתָ֔י⁠ו עַ֖ל שְׁנֵ֣י צִדָּ֑י⁠ו לְ⁠בָתִּ֣ים לְ⁠בַדִּ֔ים לָ⁠שֵׂ֥את אֹת֖⁠וֹ בָּ⁠הֶֽם׃","ẇ⁠şĕ̌ţé̇y֩ tabĕ̇ʻò֨ţ záhá֜b ʻáֽşá̂h-l֣⁠wò ׀ mi⁠ţȧ֣ẖaţ lĕ⁠zér֗⁠wò ʻa֚l şĕ̌ţé֣̇y ẕalĕʻòţá֔y⁠w ʻa֖l şĕ̌né֣y ẕidá֑̇y⁠w lĕ⁠báţi֣̇ym lĕ⁠badi̇֔ym lá⁠şé֥̂ʼţ ʼòţ֖⁠wò bá̇⁠heֽm׃"],[37,28,"וַ⁠יַּ֥עַשׂ אֶת־הַ⁠בַּדִּ֖ים עֲצֵ֣י שִׁטִּ֑ים וַ⁠יְצַ֥ף אֹתָ֖⁠ם זָהָֽב׃","wa⁠yȧ֥ʻaş̂ ʼeţ-ha⁠bȧdi֖̇ym ʻàẕé֣y şǐti֑̇ym wa⁠yĕẕa֥p ʼòţá֖⁠m záháֽb׃"],[37,29,"וַ⁠יַּ֜עַשׂ אֶת־שֶׁ֤מֶן הַ⁠מִּשְׁחָה֙ קֹ֔דֶשׁ וְ⁠אֶת־קְטֹ֥רֶת הַ⁠סַּמִּ֖ים טָה֑וֹר מַעֲשֵׂ֖ה רֹקֵֽחַ׃פ","wa⁠yȧ֜ʻaş̂ ʼeţ-şě֤men ha⁠mi̇şĕ̌ẖáh֙ qò֔deş̌ wĕ⁠ʼeţ-qĕtò֥reţ ha⁠sȧmi֖̇ym táh֑wòr maʻàşé֖̂h ròqéֽẖa׃p"],[38,1,"וַ⁠יַּ֛עַשׂ אֶת־מִזְבַּ֥ח הָ⁠עֹלָ֖ה עֲצֵ֣י שִׁטִּ֑ים חָמֵשׁ֩ אַמּ֨וֹת אָרְכּ֜⁠וֹ וְ⁠חָֽמֵשׁ־אַמּ֤וֹת רָחְבּ⁠וֹ֙ רָב֔וּעַ וְ⁠שָׁלֹ֥שׁ אַמּ֖וֹת קֹמָתֽ⁠וֹ׃","wa⁠yȧ֛ʻaş̂ ʼeţ-mizĕbȧ֥ẖ há⁠ʻòlá֖h ʻàẕé֣y şǐti֑̇ym ẖáméş̌֩ ʼaṁ֨wòţ ʼárĕk̇֜⁠wò wĕ⁠ẖáֽméş̌-ʼaṁ֤wòţ ráẖĕḃ⁠wò֙ ráb֔ẇʻa wĕ⁠şá̌lò֥ş̌ ʼaṁ֖wòţ qòmáţֽ⁠wò׃"],[38,2,"וַ⁠יַּ֣עַשׂ קַרְנֹתָ֗י⁠ו עַ֚ל אַרְבַּ֣ע פִּנֹּתָ֔י⁠ו מִמֶּ֖⁠נּוּ הָי֣וּ קַרְנֹתָ֑י⁠ו וַ⁠יְצַ֥ף אֹת֖⁠וֹ נְחֹֽשֶׁת׃","wa⁠yȧ֣ʻaş̂ qarĕnòţá֗y⁠w ʻa֚l ʼarĕbȧ֣ʻ pi̇nò̇ţá֔y⁠w mimė֖⁠ṅẇ háy֣ẇ qarĕnòţá֑y⁠w wa⁠yĕẕa֥p ʼòţ֖⁠wò nĕẖòֽşěţ׃"],[38,3,"וַ⁠יַּ֜עַשׂ אֶֽת־כָּל־כְּלֵ֣י הַ⁠מִּזְבֵּ֗חַ אֶת־הַ⁠סִּירֹ֤ת וְ⁠אֶת־הַ⁠יָּעִים֙ וְ⁠אֶת־הַ⁠מִּזְרָקֹ֔ת אֶת־הַ⁠מִּזְלָגֹ֖ת וְ⁠אֶת־הַ⁠מַּחְתֹּ֑ת כָּל־כֵּלָ֖י⁠ו עָשָׂ֥ה נְחֹֽשֶׁת׃","wa⁠yȧ֜ʻaş̂ ʼeֽţ-ká̇l-kĕ̇lé֣y ha⁠mi̇zĕbé̇֗ẖa ʼeţ-ha⁠si̇yrò֤ţ wĕ⁠ʼeţ-ha⁠yá̇ʻiym֙ wĕ⁠ʼeţ-ha⁠mi̇zĕráqò֔ţ ʼeţ-ha⁠mi̇zĕlágò֖ţ wĕ⁠ʼeţ-ha⁠mȧẖĕţò֑̇ţ ká̇l-ké̇lá֖y⁠w ʻáşá֥̂h nĕẖòֽşěţ׃"],[38,4,"וַ⁠יַּ֤עַשׂ לַ⁠מִּזְבֵּ֨חַ֙ מִכְבָּ֔ר מַעֲשֵׂ֖ה רֶ֣שֶׁת נְחֹ֑שֶׁת תַּ֧חַת כַּרְכֻּבּ֛⁠וֹ מִ⁠לְּ⁠מַ֖טָּה עַד־חֶצְיֽ⁠וֹ׃","wa⁠yȧ֤ʻaş̂ la⁠mi̇zĕbé̇֨ẖa֙ mikĕbá̇֔r maʻàşé֖̂h re֣şěţ nĕẖò֑şěţ ţȧ֧ẖaţ kȧrĕku̇ḃ֛⁠wò mi⁠lĕ̇⁠ma֖tá̇h ʻad-ẖeẕĕyֽ⁠wò׃"],[38,5,"וַ⁠יִּצֹ֞ק אַרְבַּ֧ע טַבָּעֹ֛ת בְּ⁠אַרְבַּ֥ע הַ⁠קְּצָוֺ֖ת לְ⁠מִכְבַּ֣ר הַ⁠נְּחֹ֑שֶׁת בָּתִּ֖ים לַ⁠בַּדִּֽים׃","wa⁠yi̇ẕò֞q ʼarĕbȧ֧ʻ tabá̇ʻò֛ţ bĕ̇⁠ʼarĕbȧ֥ʻ ha⁠qĕ̇ẕáwֺ֖ţ lĕ⁠mikĕbȧ֣r ha⁠nĕ̇ẖò֑şěţ bá̇ţi֖̇ym la⁠bȧdiֽ̇ym׃"],[38,6,"וַ⁠יַּ֥עַשׂ אֶת־הַ⁠בַּדִּ֖ים עֲצֵ֣י שִׁטִּ֑ים וַ⁠יְצַ֥ף אֹתָ֖⁠ם נְחֹֽשֶׁת׃","wa⁠yȧ֥ʻaş̂ ʼeţ-ha⁠bȧdi֖̇ym ʻàẕé֣y şǐti֑̇ym wa⁠yĕẕa֥p ʼòţá֖⁠m nĕẖòֽşěţ׃"],[38,7,"וַ⁠יָּבֵ֨א אֶת־הַ⁠בַּדִּ֜ים בַּ⁠טַּבָּעֹ֗ת עַ֚ל צַלְעֹ֣ת הַ⁠מִּזְבֵּ֔חַ לָ⁠שֵׂ֥את אֹת֖⁠וֹ בָּ⁠הֶ֑ם נְב֥וּב לֻחֹ֖ת עָשָׂ֥ה אֹתֽ⁠וֹ׃ס","wa⁠yá̇bé֨ʼ ʼeţ-ha⁠bȧdi̇֜ym bȧ⁠tȧbá̇ʻò֗ţ ʻa֚l ẕalĕʻò֣ţ ha⁠mi̇zĕbé̇֔ẖa lá⁠şé֥̂ʼţ ʼòţ֖⁠wò bá̇⁠he֑m nĕb֥ẇb luẖò֖ţ ʻáşá֥̂h ʼòţֽ⁠wò׃s"],[38,8,"וַ⁠יַּ֗עַשׂ אֵ֚ת הַ⁠כִּיּ֣וֹר נְחֹ֔שֶׁת וְ⁠אֵ֖ת כַּנּ֣⁠וֹ נְחֹ֑שֶׁת בְּ⁠מַרְאֹת֙ הַ⁠צֹּ֣בְאֹ֔ת אֲשֶׁ֣ר צָֽבְא֔וּ פֶּ֖תַח אֹ֥הֶל מוֹעֵֽד׃ס","wa⁠yȧ֗ʻaş̂ ʼé֚ţ ha⁠ki̇ẏ֣wòr nĕẖò֔şěţ wĕ⁠ʼé֖ţ kȧṅ֣⁠wò nĕẖò֑şěţ bĕ̇⁠marĕʼòţ֙ ha⁠ẕò֣̇bĕʼò֔ţ ʼàşě֣r ẕáֽbĕʼ֔ẇ pė֖ţaẖ ʼò֥hel mwòʻéֽd׃s"],[38,9,"וַ⁠יַּ֖עַשׂ אֶת־הֶ⁠חָצֵ֑ר לִ⁠פְאַ֣ת ׀ נֶ֣גֶב תֵּימָ֗נָ⁠ה קַלְעֵ֤י הֶֽ⁠חָצֵר֙ שֵׁ֣שׁ מָשְׁזָ֔ר מֵאָ֖ה בָּ⁠אַמָּֽה׃","wa⁠yȧ֖ʻaş̂ ʼeţ-he⁠ẖáẕé֑r li⁠pĕʼa֣ţ ׀ ne֣geb ţé̇ymá֗ná⁠h qalĕʻé֤y heֽ⁠ẖáẕér֙ şé֣̌ş̌ máşĕ̌zá֔r méʼá֖h bá̇⁠ʼamáֽ̇h׃"],[38,10,"עַמּוּדֵי⁠הֶ֣ם עֶשְׂרִ֔ים וְ⁠אַדְנֵי⁠הֶ֥ם עֶשְׂרִ֖ים נְחֹ֑שֶׁת וָוֵ֧י הָ⁠עַמֻּדִ֛ים וַ⁠חֲשֻׁקֵי⁠הֶ֖ם כָּֽסֶף׃","ʻaṁẇdéy⁠he֣m ʻeşĕ̂ri֔ym wĕ⁠ʼadĕnéy⁠he֥m ʻeşĕ̂ri֖ym nĕẖò֑şěţ wáwé֧y há⁠ʻamu̇di֛ym wa⁠ẖàşǔqéy⁠he֖m káֽ̇sep׃"],[38,11,"וְ⁠לִ⁠פְאַ֤ת צָפוֹן֙ מֵאָ֣ה בָֽ⁠אַמָּ֔ה עַמּוּדֵי⁠הֶ֣ם עֶשְׂרִ֔ים וְ⁠אַדְנֵי⁠הֶ֥ם עֶשְׂרִ֖ים נְחֹ֑שֶׁת וָוֵ֧י הָֽ⁠עַמּוּדִ֛ים וַ⁠חֲשֻׁקֵי⁠הֶ֖ם כָּֽסֶף׃","wĕ⁠li⁠pĕʼa֤ţ ẕápwòn֙ méʼá֣h báֽ⁠ʼamá̇֔h ʻaṁẇdéy⁠he֣m ʻeşĕ̂ri֔ym wĕ⁠ʼadĕnéy⁠he֥m ʻeşĕ̂ri֖ym nĕẖò֑şěţ wáwé֧y háֽ⁠ʻaṁẇdi֛ym wa⁠ẖàşǔqéy⁠he֖m káֽ̇sep׃"],[38,12,"וְ⁠לִ⁠פְאַת־יָ֗ם קְלָעִים֙ חֲמִשִּׁ֣ים בָּֽ⁠אַמָּ֔ה עַמּוּדֵי⁠הֶ֥ם עֲשָׂרָ֔ה וְ⁠אַדְנֵי⁠הֶ֖ם עֲשָׂרָ֑ה וָוֵ֧י הָ⁠עַמֻּדִ֛ים וַ⁠חֲשׁוּקֵי⁠הֶ֖ם כָּֽסֶף׃","wĕ⁠li⁠pĕʼaţ-yá֗m qĕláʻiym֙ ẖàmişi֣̇̌ym báֽ̇⁠ʼamá̇֔h ʻaṁẇdéy⁠he֥m ʻàşá̂rá֔h wĕ⁠ʼadĕnéy⁠he֖m ʻàşá̂rá֑h wáwé֧y há⁠ʻamu̇di֛ym wa⁠ẖàş̌ẇqéy⁠he֖m káֽ̇sep׃"],[38,13,"וְ⁠לִ⁠פְאַ֛ת קֵ֥דְמָ⁠ה מִזְרָ֖חָ⁠ה חֲמִשִּׁ֥ים אַמָּֽה׃","wĕ⁠li⁠pĕʼa֛ţ qé֥dĕmá⁠h mizĕrá֖ẖá⁠h ẖàmişi֥̇̌ym ʼamáֽ̇h׃"],[38,14,"קְלָעִ֛ים חֲמֵשׁ־עֶשְׂרֵ֥ה אַמָּ֖ה אֶל־הַ⁠כָּתֵ֑ף עַמּוּדֵי⁠הֶ֣ם שְׁלֹשָׁ֔ה וְ⁠אַדְנֵי⁠הֶ֖ם שְׁלֹשָֽׁה׃","qĕláʻi֛ym ẖàméş̌-ʻeşĕ̂ré֥h ʼamá֖̇h ʼel-ha⁠ká̇ţé֑p ʻaṁẇdéy⁠he֣m şĕ̌lòşá̌֔h wĕ⁠ʼadĕnéy⁠he֖m şĕ̌lòşáֽ̌h׃"],[38,15,"וְ⁠לַ⁠כָּתֵ֣ף הַ⁠שֵּׁנִ֗ית מִ⁠זֶּ֤ה וּ⁠מִ⁠זֶּה֙ לְ⁠שַׁ֣עַר הֶֽ⁠חָצֵ֔ר קְלָעִ֕ים חֲמֵ֥שׁ עֶשְׂרֵ֖ה אַמָּ֑ה עַמֻּדֵי⁠הֶ֣ם שְׁלֹשָׁ֔ה וְ⁠אַדְנֵי⁠הֶ֖ם שְׁלֹשָֽׁה׃","wĕ⁠la⁠ká̇ţé֣p ha⁠şé̇̌ni֗yţ mi⁠zė֤h ẇ⁠mi⁠zėh֙ lĕ⁠şǎ֣ʻar heֽ⁠ẖáẕé֔r qĕláʻi֕ym ẖàmé֥ş̌ ʻeşĕ̂ré֖h ʼamá֑̇h ʻamu̇déy⁠he֣m şĕ̌lòşá̌֔h wĕ⁠ʼadĕnéy⁠he֖m şĕ̌lòşáֽ̌h׃"],[38,16,"כָּל־קַלְעֵ֧י הֶ⁠חָצֵ֛ר סָבִ֖יב שֵׁ֥שׁ מָשְׁזָֽר׃","ká̇l-qalĕʻé֧y he⁠ẖáẕé֛r sábi֖yb şé֥̌ş̌ máşĕ̌záֽr׃"],[38,17,"וְ⁠הָ⁠אֲדָנִ֣ים לָֽ⁠עַמֻּדִים֮ נְחֹשֶׁת֒ וָוֵ֨י הָֽ⁠עַמּוּדִ֜ים וַ⁠חֲשׁוּקֵי⁠הֶם֙ כֶּ֔סֶף וְ⁠צִפּ֥וּי רָאשֵׁי⁠הֶ֖ם כָּ֑סֶף וְ⁠הֵם֙ מְחֻשָּׁקִ֣ים כֶּ֔סֶף כֹּ֖ל עַמֻּדֵ֥י הֶ⁠חָצֵֽר׃","wĕ⁠há⁠ʼàdáni֣ym láֽ⁠ʻamu̇diym֮ nĕẖòşěţ֒ wáwé֨y háֽ⁠ʻaṁẇdi֜ym wa⁠ẖàş̌ẇqéy⁠hem֙ kė֔sep wĕ⁠ẕiṗ֥ẇy ráʼşé̌y⁠he֖m ká֑̇sep wĕ⁠hém֙ mĕẖuşá̇̌qi֣ym kė֔sep kò֖̇l ʻamu̇dé֥y he⁠ẖáẕéֽr׃"],[38,18,"וּ⁠מָסַ֞ךְ שַׁ֤עַר הֶ⁠חָצֵר֙ מַעֲשֵׂ֣ה רֹקֵ֔ם תְּכֵ֧לֶת וְ⁠אַרְגָּמָ֛ן וְ⁠תוֹלַ֥עַת שָׁנִ֖י וְ⁠שֵׁ֣שׁ מָשְׁזָ֑ר וְ⁠עֶשְׂרִ֤ים אַמָּה֙ אֹ֔רֶךְ וְ⁠קוֹמָ֤ה בְ⁠רֹ֨חַב֙ חָמֵ֣שׁ אַמּ֔וֹת לְ⁠עֻמַּ֖ת קַלְעֵ֥י הֶ⁠חָצֵֽר׃","ẇ⁠mása֞kĕ şǎ֤ʻar he⁠ẖáẕér֙ maʻàşé֣̂h ròqé֔m ţĕ̇ké֧leţ wĕ⁠ʼarĕgá̇má֛n wĕ⁠ţwòla֥ʻaţ şá̌ni֖y wĕ⁠şé֣̌ş̌ máşĕ̌zá֑r wĕ⁠ʻeşĕ̂ri֤ym ʼamá̇h֙ ʼò֔rekĕ wĕ⁠qwòmá֤h bĕ⁠rò֨ẖab֙ ẖámé֣ş̌ ʼaṁ֔wòţ lĕ⁠ʻumȧ֖ţ qalĕʻé֥y he⁠ẖáẕéֽr׃"],[38,19,"וְ⁠עַמֻּֽדֵי⁠הֶם֙ אַרְבָּעָ֔ה וְ⁠אַדְנֵי⁠הֶ֥ם אַרְבָּעָ֖ה נְחֹ֑שֶׁת וָוֵי⁠הֶ֣ם כֶּ֔סֶף וְ⁠צִפּ֧וּי רָאשֵׁי⁠הֶ֛ם וַ⁠חֲשֻׁקֵי⁠הֶ֖ם כָּֽסֶף׃","wĕ⁠ʻamuֽ̇déy⁠hem֙ ʼarĕbá̇ʻá֔h wĕ⁠ʼadĕnéy⁠he֥m ʼarĕbá̇ʻá֖h nĕẖò֑şěţ wáwéy⁠he֣m kė֔sep wĕ⁠ẕiṗ֧ẇy ráʼşé̌y⁠he֛m wa⁠ẖàşǔqéy⁠he֖m káֽ̇sep׃"],[38,20,"וְֽ⁠כָל־הַ⁠יְתֵדֹ֞ת לַ⁠מִּשְׁכָּ֧ן וְ⁠לֶ⁠חָצֵ֛ר סָבִ֖יב נְחֹֽשֶׁת׃ס","wĕֽ⁠kál-ha⁠yĕţédò֞ţ la⁠mi̇şĕ̌ká֧̇n wĕ⁠le⁠ẖáẕé֛r sábi֖yb nĕẖòֽşěţ׃s"],[38,21,"אֵ֣לֶּה פְקוּדֵ֤י הַ⁠מִּשְׁכָּן֙ מִשְׁכַּ֣ן הָ⁠עֵדֻ֔ת אֲשֶׁ֥ר פֻּקַּ֖ד עַל־פִּ֣י מֹשֶׁ֑ה עֲבֹדַת֙ הַ⁠לְוִיִּ֔ם בְּ⁠יַד֙ אִֽיתָמָ֔ר בֶּֽן־אַהֲרֹ֖ן הַ⁠כֹּהֵֽן׃","ʼé֣lėh pĕqẇdé֤y ha⁠mi̇şĕ̌ká̇n֙ mişĕ̌kȧ֣n há⁠ʻédu֔ţ ʼàşě֥r pu̇qȧ֖d ʻal-pi֣̇y mòşě֑h ʻàbòdaţ֙ ha⁠lĕwiyi̇֔m bĕ̇⁠yad֙ ʼiֽyţámá֔r bėֽn-ʼahàrò֖n ha⁠kò̇héֽn׃"],[38,22,"וּ⁠בְצַלְאֵ֛ל בֶּן־אוּרִ֥י בֶן־ח֖וּר לְ⁠מַטֵּ֣ה יְהוּדָ֑ה עָשָׂ֕ה אֵ֛ת כָּל־אֲשֶׁר־צִוָּ֥ה יְהוָ֖ה אֶת־מֹשֶֽׁה׃","ẇ⁠bĕẕalĕʼé֛l bėn-ʼẇri֥y ben-ẖ֖ẇr lĕ⁠maté֣̇h yĕhẇdá֑h ʻáşá̂֕h ʼé֛ţ ká̇l-ʼàşěr-ẕiwá֥̇h yĕhwá֖h ʼeţ-mòşěֽh׃"],[38,23,"וְ⁠אִתּ֗⁠וֹ אָהֳלִיאָ֞ב בֶּן־אֲחִיסָמָ֛ךְ לְ⁠מַטֵּה־דָ֖ן חָרָ֣שׁ וְ⁠חֹשֵׁ֑ב וְ⁠רֹקֵ֗ם בַּ⁠תְּכֵ֨לֶת֙ וּ⁠בָֽ⁠אַרְגָּמָ֔ן וּ⁠בְ⁠תוֹלַ֥עַת הַ⁠שָּׁנִ֖י וּ⁠בַ⁠שֵּֽׁשׁ׃ס","wĕ⁠ʼiţ̇֗⁠wò ʼáholiyʼá֞b bėn-ʼàẖiysámá֛kĕ lĕ⁠maté̇h-dá֖n ẖárá֣ş̌ wĕ⁠ẖòşé֑̌b wĕ⁠ròqé֗m bȧ⁠ţĕ̇ké֨leţ֙ ẇ⁠báֽ⁠ʼarĕgá̇má֔n ẇ⁠bĕ⁠ţwòla֥ʻaţ ha⁠şá̇̌ni֖y ẇ⁠ba⁠şéֽ̇̌ş̌׃s"],[38,24,"כָּל־הַ⁠זָּהָ֗ב הֶֽ⁠עָשׂוּי֙ לַ⁠מְּלָאכָ֔ה בְּ⁠כֹ֖ל מְלֶ֣אכֶת הַ⁠קֹּ֑דֶשׁ וַ⁠יְהִ֣י ׀ זְהַ֣ב הַ⁠תְּנוּפָ֗ה תֵּ֤שַׁע וְ⁠עֶשְׂרִים֙ כִּכָּ֔ר וּ⁠שְׁבַ֨ע מֵא֧וֹת וּ⁠שְׁלֹשִׁ֛ים שֶׁ֖קֶל בְּ⁠שֶׁ֥קֶל הַ⁠קֹּֽדֶשׁ׃","ká̇l-ha⁠zá̇há֗b heֽ⁠ʻáş̂ẇy֙ la⁠mĕ̇láʼká֔h bĕ̇⁠kò֖l mĕle֣ʼkeţ ha⁠qò֑̇deş̌ wa⁠yĕhi֣y ׀ zĕha֣b ha⁠ţĕ̇nẇpá֗h ţé֤̇şǎʻ wĕ⁠ʻeşĕ̂riym֙ ki̇ká̇֔r ẇ⁠şĕ̌ba֨ʻ méʼ֧wòţ ẇ⁠şĕ̌lòşǐ֛ym şě֖qel bĕ̇⁠şě֥qel ha⁠qòֽ̇deş̌׃"],[38,25,"וְ⁠כֶ֛סֶף פְּקוּדֵ֥י הָ⁠עֵדָ֖ה מְאַ֣ת כִּכָּ֑ר וְ⁠אֶלֶף֩ וּ⁠שְׁבַ֨ע מֵא֜וֹת וַ⁠חֲמִשָּׁ֧ה וְ⁠שִׁבְעִ֛ים שֶׁ֖קֶל בְּ⁠שֶׁ֥קֶל הַ⁠קֹּֽדֶשׁ׃","wĕ⁠ke֛sep pĕ̇qẇdé֥y há⁠ʻédá֖h mĕʼa֣ţ ki̇ká֑̇r wĕ⁠ʼelep֩ ẇ⁠şĕ̌ba֨ʻ méʼ֜wòţ wa⁠ẖàmişá֧̇̌h wĕ⁠şǐbĕʻi֛ym şě֖qel bĕ̇⁠şě֥qel ha⁠qòֽ̇deş̌׃"],[38,26,"בֶּ֚קַע לַ⁠גֻּלְגֹּ֔לֶת מַחֲצִ֥ית הַ⁠שֶּׁ֖קֶל בְּ⁠שֶׁ֣קֶל הַ⁠קֹּ֑דֶשׁ לְ⁠כֹ֨ל הָ⁠עֹבֵ֜ר עַל־הַ⁠פְּקֻדִ֗ים מִ⁠בֶּ֨ן עֶשְׂרִ֤ים שָׁנָה֙ וָ⁠מַ֔עְלָ⁠ה לְ⁠שֵׁשׁ־מֵא֥וֹת אֶ֨לֶף֙ וּ⁠שְׁלֹ֣שֶׁת אֲלָפִ֔ים וַ⁠חֲמֵ֥שׁ מֵא֖וֹת וַ⁠חֲמִשִּֽׁים׃","bė֚qaʻ la⁠gu̇lĕgò̇֔leţ maẖàẕi֥yţ ha⁠şė֖̌qel bĕ̇⁠şě֣qel ha⁠qò֑̇deş̌ lĕ⁠kò֨l há⁠ʻòbé֜r ʻal-ha⁠pĕ̇qudi֗ym mi⁠bė֨n ʻeşĕ̂ri֤ym şá̌náh֙ wá⁠ma֔ʻĕlá⁠h lĕ⁠şé̌ş̌-méʼ֥wòţ ʼe֨lep֙ ẇ⁠şĕ̌lò֣şěţ ʼàlápi֔ym wa⁠ẖàmé֥ş̌ méʼ֖wòţ wa⁠ẖàmişiֽ̇̌ym׃"],[38,27,"וַ⁠יְהִ֗י מְאַת֙ כִּכַּ֣ר הַ⁠כֶּ֔סֶף לָ⁠צֶ֗קֶת אֵ֚ת אַדְנֵ֣י הַ⁠קֹּ֔דֶשׁ וְ⁠אֵ֖ת אַדְנֵ֣י הַ⁠פָּרֹ֑כֶת מְאַ֧ת אֲדָנִ֛ים לִ⁠מְאַ֥ת הַ⁠כִּכָּ֖ר כִּכָּ֥ר לָ⁠אָֽדֶן׃","wa⁠yĕhi֗y mĕʼaţ֙ ki̇kȧ֣r ha⁠kė֔sep lá⁠ẕe֗qeţ ʼé֚ţ ʼadĕné֣y ha⁠qò̇֔deş̌ wĕ⁠ʼé֖ţ ʼadĕné֣y ha⁠pá̇rò֑keţ mĕʼa֧ţ ʼàdáni֛ym li⁠mĕʼa֥ţ ha⁠ki̇ká֖̇r ki̇ká֥̇r lá⁠ʼáֽden׃"],[38,28,"וְ⁠אֶת־הָ⁠אֶ֜לֶף וּ⁠שְׁבַ֤ע הַ⁠מֵּאוֹת֙ וַ⁠חֲמִשָּׁ֣ה וְ⁠שִׁבְעִ֔ים עָשָׂ֥ה וָוִ֖ים לָ⁠עַמּוּדִ֑ים וְ⁠צִפָּ֥ה רָאשֵׁי⁠הֶ֖ם וְ⁠חִשַּׁ֥ק אֹתָֽ⁠ם׃","wĕ⁠ʼeţ-há⁠ʼe֜lep ẇ⁠şĕ̌ba֤ʻ ha⁠mé̇ʼwòţ֙ wa⁠ẖàmişá֣̇̌h wĕ⁠şǐbĕʻi֔ym ʻáşá֥̂h wáwi֖ym lá⁠ʻaṁẇdi֑ym wĕ⁠ẕipá֥̇h ráʼşé̌y⁠he֖m wĕ⁠ẖişȧ֥̌q ʼòţáֽ⁠m׃"],[38,29,"וּ⁠נְחֹ֥שֶׁת הַ⁠תְּנוּפָ֖ה שִׁבְעִ֣ים כִּכָּ֑ר וְ⁠אַלְפַּ֥יִם וְ⁠אַרְבַּע־מֵא֖וֹת שָֽׁקֶל׃","ẇ⁠nĕẖò֥şěţ ha⁠ţĕ̇nẇpá֖h şǐbĕʻi֣ym ki̇ká֑̇r wĕ⁠ʼalĕpȧ֥yim wĕ⁠ʼarĕbȧʻ-méʼ֖wòţ şáֽ̌qel׃"],[38,30,"וַ⁠יַּ֣עַשׂ בָּ֗⁠הּ אֶת־אַדְנֵי֙ פֶּ֚תַח אֹ֣הֶל מוֹעֵ֔ד וְ⁠אֵת֙ מִזְבַּ֣ח הַ⁠נְּחֹ֔שֶׁת וְ⁠אֶת־מִכְבַּ֥ר הַ⁠נְּחֹ֖שֶׁת אֲשֶׁר־ל֑⁠וֹ וְ⁠אֵ֖ת כָּל־כְּלֵ֥י הַ⁠מִּזְבֵּֽחַ׃","wa⁠yȧ֣ʻaş̂ bá̇֗⁠ḣ ʼeţ-ʼadĕnéy֙ pė֚ţaẖ ʼò֣hel mwòʻé֔d wĕ⁠ʼéţ֙ mizĕbȧ֣ẖ ha⁠nĕ̇ẖò֔şěţ wĕ⁠ʼeţ-mikĕbȧ֥r ha⁠nĕ̇ẖò֖şěţ ʼàşěr-l֑⁠wò wĕ⁠ʼé֖ţ ká̇l-kĕ̇lé֥y ha⁠mi̇zĕbéֽ̇ẖa׃"],[38,31,"וְ⁠אֶת־אַדְנֵ֤י הֶֽ⁠חָצֵר֙ סָבִ֔יב וְ⁠אֶת־אַדְנֵ֖י שַׁ֣עַר הֶ⁠חָצֵ֑ר וְ⁠אֵ֨ת כָּל־יִתְדֹ֧ת הַ⁠מִּשְׁכָּ֛ן וְ⁠אֶת־כָּל־יִתְדֹ֥ת הֶ⁠חָצֵ֖ר סָבִֽיב׃","wĕ⁠ʼeţ-ʼadĕné֤y heֽ⁠ẖáẕér֙ sábi֔yb wĕ⁠ʼeţ-ʼadĕné֖y şǎ֣ʻar he⁠ẖáẕé֑r wĕ⁠ʼé֨ţ ká̇l-yiţĕdò֧ţ ha⁠mi̇şĕ̌ká֛̇n wĕ⁠ʼeţ-ká̇l-yiţĕdò֥ţ he⁠ẖáẕé֖r sábiֽyb׃"],[39,1,"וּ⁠מִן־הַ⁠תְּכֵ֤לֶת וְ⁠הָֽ⁠אַרְגָּמָן֙ וְ⁠תוֹלַ֣עַת הַ⁠שָּׁנִ֔י עָשׂ֥וּ בִגְדֵי־שְׂרָ֖ד לְ⁠שָׁרֵ֣ת בַּ⁠קֹּ֑דֶשׁ וַֽ⁠יַּעֲשׂ֞וּ אֶת־בִּגְדֵ֤י הַ⁠קֹּ֨דֶשׁ֙ אֲשֶׁ֣ר לְ⁠אַהֲרֹ֔ן כַּ⁠אֲשֶׁ֛ר צִוָּ֥ה יְהוָ֖ה אֶת־מֹשֶֽׁה׃פ","ẇ⁠min-ha⁠ţĕ̇ké֤leţ wĕ⁠háֽ⁠ʼarĕgá̇mán֙ wĕ⁠ţwòla֣ʻaţ ha⁠şá̇̌ni֔y ʻáş֥̂ẇ bigĕdéy-şĕ̂rá֖d lĕ⁠şá̌ré֣ţ bȧ⁠qò֑̇deş̌ waֽ⁠yȧʻàş̂֞ẇ ʼeţ-bi̇gĕdé֤y ha⁠qò̇֨deş̌֙ ʼàşě֣r lĕ⁠ʼahàrò֔n kȧ⁠ʼàşě֛r ẕiwá֥̇h yĕhwá֖h ʼeţ-mòşěֽh׃p"],[39,2,"וַ⁠יַּ֖עַשׂ אֶת־הָ⁠אֵפֹ֑ד זָהָ֗ב תְּכֵ֧לֶת וְ⁠אַרְגָּמָ֛ן וְ⁠תוֹלַ֥עַת שָׁנִ֖י וְ⁠שֵׁ֥שׁ מָשְׁזָֽר׃","wa⁠yȧ֖ʻaş̂ ʼeţ-há⁠ʼépò֑d záhá֗b ţĕ̇ké֧leţ wĕ⁠ʼarĕgá̇má֛n wĕ⁠ţwòla֥ʻaţ şá̌ni֖y wĕ⁠şé֥̌ş̌ máşĕ̌záֽr׃"],[39,3,"וַֽ⁠יְרַקְּע֞וּ אֶת־פַּחֵ֣י הַ⁠זָּהָב֮ וְ⁠קִצֵּ֣ץ פְּתִילִם֒ לַ⁠עֲשׂ֗וֹת בְּ⁠ת֤וֹךְ הַ⁠תְּכֵ֨לֶת֙ וּ⁠בְ⁠ת֣וֹךְ הָֽ⁠אַרְגָּמָ֔ן וּ⁠בְ⁠ת֛וֹךְ תּוֹלַ֥עַת הַ⁠שָּׁנִ֖י וּ⁠בְ⁠ת֣וֹךְ הַ⁠שֵּׁ֑שׁ מַעֲשֵׂ֖ה חֹשֵֽׁב׃","waֽ⁠yĕraqĕ̇ʻ֞ẇ ʼeţ-pȧẖé֣y ha⁠zá̇háb֮ wĕ⁠qiẕé֣̇ẕ pĕ̇ţiylim֒ la⁠ʻàş̂֗wòţ bĕ̇⁠ţ֤wòkĕ ha⁠ţĕ̇ké֨leţ֙ ẇ⁠bĕ⁠ţ֣wòkĕ háֽ⁠ʼarĕgá̇má֔n ẇ⁠bĕ⁠ţ֛wòkĕ ţ̇wòla֥ʻaţ ha⁠şá̇̌ni֖y ẇ⁠bĕ⁠ţ֣wòkĕ ha⁠şé֑̇̌ş̌ maʻàşé֖̂h ẖòşéֽ̌b׃"],[39,4,"כְּתֵפֹ֥ת עָֽשׂוּ־ל֖⁠וֹ חֹבְרֹ֑ת עַל־שְׁנֵ֥י קצוות⁠ו חֻבָּֽר׃","kĕ̇ţépò֥ţ ʻáֽş̂ẇ-l֖⁠wò ẖòbĕrò֑ţ ʻal-şĕ̌né֥y qẕwwţ⁠w ẖubáֽ̇r׃"],[39,5,"וְ⁠חֵ֨שֶׁב אֲפֻדָּת֜⁠וֹ אֲשֶׁ֣ר עָלָ֗י⁠ו מִמֶּ֣⁠נּוּ הוּא֮ כְּ⁠מַעֲשֵׂ⁠הוּ֒ זָהָ֗ב תְּכֵ֧לֶת וְ⁠אַרְגָּמָ֛ן וְ⁠תוֹלַ֥עַת שָׁנִ֖י וְ⁠שֵׁ֣שׁ מָשְׁזָ֑ר כַּ⁠אֲשֶׁ֛ר צִוָּ֥ה יְהוָ֖ה אֶת־מֹשֶֽׁה׃","wĕ⁠ẖé֨şěb ʼàpudá̇ţ֜⁠wò ʼàşě֣r ʻálá֗y⁠w mimė֣⁠ṅẇ hẇʼ֮ kĕ̇⁠maʻàşé̂⁠hẇ֒ záhá֗b ţĕ̇ké֧leţ wĕ⁠ʼarĕgá̇má֛n wĕ⁠ţwòla֥ʻaţ şá̌ni֖y wĕ⁠şé֣̌ş̌ máşĕ̌zá֑r kȧ⁠ʼàşě֛r ẕiwá֥̇h yĕhwá֖h ʼeţ-mòşěֽh׃"],[39,6,"וַֽ⁠יַּעֲשׂוּ֙ אֶת־אַבְנֵ֣י הַ⁠שֹּׁ֔הַם מֻֽסַבֹּ֖ת מִשְׁבְּצֹ֣ת זָהָ֑ב מְפֻתָּחֹת֙ פִּתּוּחֵ֣י חוֹתָ֔ם עַל־שְׁמ֖וֹת בְּנֵ֥י יִשְׂרָאֵֽל׃","waֽ⁠yȧʻàş̂ẇ֙ ʼeţ-ʼabĕné֣y ha⁠şò̇̌֔ham muֽsabò֖̇ţ mişĕ̌bĕ̇ẕò֣ţ záhá֑b mĕpuţá̇ẖòţ֙ pi̇ţ̇ẇẖé֣y ẖwòţá֔m ʻal-şĕ̌m֖wòţ bĕ̇né֥y yişĕ̂ráʼéֽl׃"],[39,7,"וַ⁠יָּ֣שֶׂם אֹתָ֗⁠ם עַ֚ל כִּתְפֹ֣ת הָ⁠אֵפֹ֔ד אַבְנֵ֥י זִכָּר֖וֹן לִ⁠בְנֵ֣י יִשְׂרָאֵ֑ל כַּ⁠אֲשֶׁ֛ר צִוָּ֥ה יְהוָ֖ה אֶת־מֹשֶֽׁה׃פ","wa⁠yá֣̇şêm ʼòţá֗⁠m ʻa֚l ki̇ţĕpò֣ţ há⁠ʼépò֔d ʼabĕné֥y ziká̇r֖wòn li⁠bĕné֣y yişĕ̂ráʼé֑l kȧ⁠ʼàşě֛r ẕiwá֥̇h yĕhwá֖h ʼeţ-mòşěֽh׃p"],[39,8,"וַ⁠יַּ֧עַשׂ אֶת־הַ⁠חֹ֛שֶׁן מַעֲשֵׂ֥ה חֹשֵׁ֖ב כְּ⁠מַעֲשֵׂ֣ה אֵפֹ֑ד זָהָ֗ב תְּכֵ֧לֶת וְ⁠אַרְגָּמָ֛ן וְ⁠תוֹלַ֥עַת שָׁנִ֖י וְ⁠שֵׁ֥שׁ מָשְׁזָֽר׃","wa⁠yȧ֧ʻaş̂ ʼeţ-ha⁠ẖò֛şěn maʻàşé֥̂h ẖòşé֖̌b kĕ̇⁠maʻàşé֣̂h ʼépò֑d záhá֗b ţĕ̇ké֧leţ wĕ⁠ʼarĕgá̇má֛n wĕ⁠ţwòla֥ʻaţ şá̌ni֖y wĕ⁠şé֥̌ş̌ máşĕ̌záֽr׃"],[39,9,"רָב֧וּעַ הָיָ֛ה כָּפ֖וּל עָשׂ֣וּ אֶת־הַ⁠חֹ֑שֶׁן זֶ֧רֶת אָרְכּ֛⁠וֹ וְ⁠זֶ֥רֶת רָחְבּ֖⁠וֹ כָּפֽוּל׃","ráb֧ẇʻa háyá֛h ká̇p֖ẇl ʻáş֣̂ẇ ʼeţ-ha⁠ẖò֑şěn ze֧reţ ʼárĕk֛̇⁠wò wĕ⁠ze֥reţ ráẖĕḃ֖⁠wò ká̇pֽẇl׃"],[39,10,"וַ⁠יְמַלְאוּ־ב֔⁠וֹ אַרְבָּעָ֖ה ט֣וּרֵי אָ֑בֶן ט֗וּר אֹ֤דֶם פִּטְדָה֙ וּ⁠בָרֶ֔קֶת הַ⁠טּ֖וּר הָ⁠אֶחָֽד׃","wa⁠yĕmalĕʼẇ-b֔⁠wò ʼarĕbá̇ʻá֖h t֣ẇréy ʼá֑ben t֗ẇr ʼò֤dem pi̇tĕdáh֙ ẇ⁠báre֔qeţ ha⁠ṫ֖ẇr há⁠ʼeẖáֽd׃"],[39,11,"וְ⁠הַ⁠טּ֖וּר הַ⁠שֵּׁנִ֑י נֹ֥פֶךְ סַפִּ֖יר וְ⁠יָהֲלֹֽם׃","wĕ⁠ha⁠ṫ֖ẇr ha⁠şé̇̌ni֑y nò֥pekĕ sapi֖̇yr wĕ⁠yáhàlòֽm׃"],[39,12,"וְ⁠הַ⁠טּ֖וּר הַ⁠שְּׁלִישִׁ֑י לֶ֥שֶׁם שְׁב֖וֹ וְ⁠אַחְלָֽמָה׃","wĕ⁠ha⁠ṫ֖ẇr ha⁠şĕ̇̌liyşǐ֑y le֥şěm şĕ̌b֖wò wĕ⁠ʼaẖĕláֽmáh׃"],[39,13,"וְ⁠הַ⁠טּוּר֙ הָֽ⁠רְבִיעִ֔י תַּרְשִׁ֥ישׁ שֹׁ֖הַם וְ⁠יָשְׁפֵ֑ה מֽוּסַבֹּ֛ת מִשְׁבְּצ֥וֹת זָהָ֖ב בְּ⁠מִלֻּאֹתָֽ⁠ם׃","wĕ⁠ha⁠ṫẇr֙ háֽ⁠rĕbiyʻi֔y ţȧrĕşǐ֥yş̌ şò֖̌ham wĕ⁠yáşĕ̌pé֑h mֽẇsabò֛̇ţ mişĕ̌bĕ̇ẕ֥wòţ záhá֖b bĕ̇⁠milu̇ʼòţáֽ⁠m׃"],[39,14,"וְ֠⁠הָ⁠אֲבָנִים עַל־שְׁמֹ֨ת בְּנֵי־יִשְׂרָאֵ֥ל הֵ֛נָּה שְׁתֵּ֥ים עֶשְׂרֵ֖ה עַל־שְׁמֹתָ֑⁠ם פִּתּוּחֵ֤י חֹתָם֙ אִ֣ישׁ עַל־שְׁמ֔⁠וֹ לִ⁠שְׁנֵ֥ים עָשָׂ֖ר שָֽׁבֶט׃","wĕ֠⁠há⁠ʼàbániym ʻal-şĕ̌mò֨ţ bĕ̇néy-yişĕ̂ráʼé֥l hé֛ná̇h şĕ̌ţé֥̇ym ʻeşĕ̂ré֖h ʻal-şĕ̌mòţá֑⁠m pi̇ţ̇ẇẖé֤y ẖòţám֙ ʼi֣yş̌ ʻal-şĕ̌m֔⁠wò li⁠şĕ̌né֥ym ʻáşá֖̂r şáֽ̌bet׃"],[39,15,"וַ⁠יַּעֲשׂ֧וּ עַל־הַ⁠חֹ֛שֶׁן שַׁרְשְׁרֹ֥ת גַּבְלֻ֖ת מַעֲשֵׂ֣ה עֲבֹ֑ת זָהָ֖ב טָהֽוֹר׃","wa⁠yȧʻàş֧̂ẇ ʻal-ha⁠ẖò֛şěn şǎrĕşĕ̌rò֥ţ gȧbĕlu֖ţ maʻàşé֣̂h ʻàbò֑ţ záhá֖b táhֽwòr׃"],[39,16,"וַֽ⁠יַּעֲשׂ֗וּ שְׁתֵּי֙ מִשְׁבְּצֹ֣ת זָהָ֔ב וּ⁠שְׁתֵּ֖י טַבְּעֹ֣ת זָהָ֑ב וַֽ⁠יִּתְּנ֗וּ אֶת־שְׁתֵּי֙ הַ⁠טַּבָּעֹ֔ת עַל־שְׁנֵ֖י קְצ֥וֹת הַ⁠חֹֽשֶׁן׃","waֽ⁠yȧʻàş̂֗ẇ şĕ̌ţé̇y֙ mişĕ̌bĕ̇ẕò֣ţ záhá֔b ẇ⁠şĕ̌ţé֖̇y tabĕ̇ʻò֣ţ záhá֑b wֽa⁠yi̇ţĕ̇n֗ẇ ʼeţ-şĕ̌ţé̇y֙ ha⁠tȧbá̇ʻò֔ţ ʻal-şĕ̌né֖y qĕẕ֥wòţ ha⁠ẖòֽşěn׃"],[39,17,"וַֽ⁠יִּתְּנ֗וּ שְׁתֵּי֙ הָ⁠עֲבֹתֹ֣ת הַ⁠זָּהָ֔ב עַל־שְׁתֵּ֖י הַ⁠טַּבָּעֹ֑ת עַל־קְצ֖וֹת הַ⁠חֹֽשֶׁן׃","waֽ⁠yi̇ţĕ̇n֗ẇ şĕ̌ţé̇y֙ há⁠ʻàbòţò֣ţ ha⁠zá̇há֔b ʻal-şĕ̌ţé֖̇y ha⁠tȧbá̇ʻò֑ţ ʻal-qĕẕ֖wòţ ha⁠ẖòֽşěn׃"],[39,18,"וְ⁠אֵ֨ת שְׁתֵּ֤י קְצוֹת֙ שְׁתֵּ֣י הָֽ⁠עֲבֹתֹ֔ת נָתְנ֖וּ עַל־שְׁתֵּ֣י הַֽ⁠מִּשְׁבְּצֹ֑ת וַֽ⁠יִּתְּנֻ֛⁠ם עַל־כִּתְפֹ֥ת הָ⁠אֵפֹ֖ד אֶל־מ֥וּל פָּנָֽי⁠ו׃","wĕ⁠ʼé֨ţ şĕ̌ţé֤̇y qĕẕwòţ֙ şĕ̌ţé֣̇y háֽ⁠ʻàbòţò֔ţ náţĕn֖ẇ ʻal-şĕ̌ţé֣̇y haֽ⁠mi̇şĕ̌bĕ̇ẕò֑ţ waֽ⁠yi̇ţĕ̇nu֛⁠m ʻal-ki̇ţĕpò֥ţ há⁠ʼépò֖d ʼel-m֥ẇl pá̇náֽy⁠w׃"],[39,19,"וַֽ⁠יַּעֲשׂ֗וּ שְׁתֵּי֙ טַבְּעֹ֣ת זָהָ֔ב וַ⁠יָּשִׂ֕ימוּ עַל־שְׁנֵ֖י קְצ֣וֹת הַ⁠חֹ֑שֶׁן עַל־שְׂפָת֕⁠וֹ אֲשֶׁ֛ר אֶל־עֵ֥בֶר הָ⁠אֵפֹ֖ד בָּֽיְתָ⁠ה׃","waֽ⁠yȧʻàş̂֗ẇ şĕ̌ţé̇y֙ tabĕ̇ʻò֣ţ záhá֔b wa⁠yá̇şî֕ymẇ ʻal-şĕ̌né֖y qĕẕ֣wòţ ha⁠ẖò֑şěn ʻal-şĕ̂páţ֕⁠wò ʼàşě֛r ʼel-ʻé֥ber há⁠ʼépò֖d báֽ̇yĕţá⁠h׃"],[39,20,"וַֽ⁠יַּעֲשׂוּ֮ שְׁתֵּ֣י טַבְּעֹ֣ת זָהָב֒ וַֽ⁠יִּתְּנֻ֡⁠ם עַל־שְׁתֵּי֩ כִתְפֹ֨ת הָ⁠אֵפֹ֤ד מִ⁠לְ⁠מַ֨טָּה֙ מִ⁠מּ֣וּל פָּנָ֔י⁠ו לְ⁠עֻמַּ֖ת מֶחְבַּרְתּ֑⁠וֹ מִ⁠מַּ֕עַל לְ⁠חֵ֖שֶׁב הָ⁠אֵפֹֽד׃","waֽ⁠yȧʻàş̂ẇ֮ şĕ̌ţé֣̇y tabĕ̇ʻò֣ţ záháb֒ waֽ⁠yi̇ţĕ̇nu֡⁠m ʻal-şĕ̌ţé̇y֩ kiţĕpò֨ţ há⁠ʼépò֤d mi⁠lĕ⁠ma֨tá̇h֙ mi⁠ṁ֣ẇl pá̇ná֔y⁠w lĕ⁠ʻumȧ֖ţ meẖĕbȧrĕţ֑̇⁠wò mi⁠mȧ֕ʻal lĕ⁠ẖé֖şěb há⁠ʼépòֽd׃"],[39,21,"וַ⁠יִּרְכְּס֣וּ אֶת־הַ⁠חֹ֡שֶׁן מִ⁠טַּבְּעֹתָי⁠ו֩ אֶל־טַבְּעֹ֨ת הָ⁠אֵפֹ֜ד בִּ⁠פְתִ֣יל תְּכֵ֗לֶת לִֽ⁠הְיֹת֙ עַל־חֵ֣שֶׁב הָ⁠אֵפֹ֔ד וְ⁠לֹֽא־יִזַּ֣ח הַ⁠חֹ֔שֶׁן מֵ⁠עַ֖ל הָ⁠אֵפֹ֑ד כַּ⁠אֲשֶׁ֛ר צִוָּ֥ה יְהוָ֖ה אֶת־מֹשֶֽׁה׃","wa⁠yi̇rĕkĕ̇s֣ẇ ʼeţ-ha⁠ẖò֡şěn mi⁠tȧbĕ̇ʻòţáy⁠w֩ ʼel-tabĕ̇ʻò֨ţ há⁠ʼépò֜d bi̇⁠pĕţi֣yl ţĕ̇ké֗leţ liֽ⁠hĕyòţ֙ ʻal-ẖé֣şěb há⁠ʼépò֔d wĕ⁠lòֽʼ-yizȧ֣ẖ ha⁠ẖò֔şěn mé⁠ʻa֖l há⁠ʼépò֑d kȧ⁠ʼàşě֛r ẕiwá֥̇h yĕhwá֖h ʼeţ-mòşěֽh׃"],[39,22,"וַ⁠יַּ֛עַשׂ אֶת־מְעִ֥יל הָ⁠אֵפֹ֖ד מַעֲשֵׂ֣ה אֹרֵ֑ג כְּלִ֖יל תְּכֵֽלֶת׃","wa⁠yȧ֛ʻaş̂ ʼeţ-mĕʻi֥yl há⁠ʼépò֖d maʻàşé֣̂h ʼòré֑g kĕ̇li֖yl ţĕ̇kéֽleţ׃"],[39,23,"וּ⁠פִֽי־הַ⁠מְּעִ֥יל בְּ⁠תוֹכ֖⁠וֹ כְּ⁠פִ֣י תַחְרָ֑א שָׂפָ֥ה לְ⁠פִ֛י⁠ו סָבִ֖יב לֹ֥א יִקָּרֵֽעַ׃","ẇ⁠piֽy-ha⁠mĕ̇ʻi֥yl bĕ̇⁠ţwòk֖⁠wò kĕ̇⁠pi֣y ţaẖĕrá֑ʼ şá̂pá֥h lĕ⁠pi֛y⁠w sábi֖yb lò֥ʼ yiqá̇réֽʻa׃"],[39,24,"וַֽ⁠יַּעֲשׂוּ֙ עַל־שׁוּלֵ֣י הַ⁠מְּעִ֔יל רִמּוֹנֵ֕י תְּכֵ֥לֶת וְ⁠אַרְגָּמָ֖ן וְ⁠תוֹלַ֣עַת שָׁנִ֑י מָשְׁזָֽר׃","waֽ⁠yȧʻàş̂ẇ֙ ʻal-ş̌ẇlé֣y ha⁠mĕ̇ʻi֔yl riṁwòné֕y ţĕ̇ké֥leţ wĕ⁠ʼarĕgá̇má֖n wĕ⁠ţwòla֣ʻaţ şá̌ni֑y máşĕ̌záֽr׃"],[39,25,"וַ⁠יַּעֲשׂ֥וּ פַעֲמֹנֵ֖י זָהָ֣ב טָה֑וֹר וַ⁠יִּתְּנ֨וּ אֶת־הַ⁠פַּֽעֲמֹנִ֜ים בְּ⁠ת֣וֹךְ הָ⁠רִמֹּנִ֗ים עַל־שׁוּלֵ֤י הַ⁠מְּעִיל֙ סָבִ֔יב בְּ⁠ת֖וֹךְ הָ⁠רִמֹּנִֽים׃","wa⁠yȧʻàş֥̂ẇ paʻàmòné֖y záhá֣b táh֑wòr wa⁠yi̇ţĕ̇n֨ẇ ʼeţ-ha⁠pȧֽʻàmòni֜ym bĕ̇⁠ţ֣wòkĕ há⁠rimò̇ni֗ym ʻal-ş̌ẇlé֤y ha⁠mĕ̇ʻiyl֙ sábi֔yb bĕ̇⁠ţ֖wòkĕ há⁠rimò̇niֽym׃"],[39,26,"פַּעֲמֹ֤ן וְ⁠רִמֹּן֙ פַּעֲמֹ֣ן וְ⁠רִמֹּ֔ן עַל־שׁוּלֵ֥י הַ⁠מְּעִ֖יל סָבִ֑יב לְ⁠שָׁרֵ֕ת כַּ⁠אֲשֶׁ֛ר צִוָּ֥ה יְהוָ֖ה אֶת־מֹשֶֽׁה׃ס","pȧʻàmò֤n wĕ⁠rimò̇n֙ pȧʻàmò֣n wĕ⁠rimò̇֔n ʻal-ş̌ẇlé֥y ha⁠mĕ̇ʻi֖yl sábi֑yb lĕ⁠şá̌ré֕ţ kȧ⁠ʼàşě֛r ẕiwá֥̇h yĕhwá֖h ʼeţ-mòşěֽh׃s"],[39,27,"וַֽ⁠יַּעֲשׂ֛וּ אֶת־הַ⁠כָּתְנֹ֥ת שֵׁ֖שׁ מַעֲשֵׂ֣ה אֹרֵ֑ג לְ⁠אַהֲרֹ֖ן וּ⁠לְ⁠בָנָֽי⁠ו׃","wֽa⁠yȧʻàş֛̂ẇ ʼeţ-ha⁠ká̇ţĕnò֥ţ şé֖̌ş̌ maʻàşé֣̂h ʼòré֑g lĕ⁠ʼahàrò֖n ẇ⁠lĕ⁠bánáֽy⁠w׃"],[39,28,"וְ⁠אֵת֙ הַ⁠מִּצְנֶ֣פֶת שֵׁ֔שׁ וְ⁠אֶת־פַּאֲרֵ֥י הַ⁠מִּגְבָּעֹ֖ת שֵׁ֑שׁ וְ⁠אֶת־מִכְנְסֵ֥י הַ⁠בָּ֖ד שֵׁ֥שׁ מָשְׁזָֽר׃","wĕ⁠ʼéţ֙ ha⁠mi̇ẕĕne֣peţ şé̌֔ş̌ wĕ⁠ʼeţ-pȧʼàré֥y ha⁠mi̇gĕbá̇ʻò֖ţ şé֑̌ş̌ wĕ⁠ʼeţ-mikĕnĕsé֥y ha⁠bá֖̇d şé֥̌ş̌ máşĕ̌záֽr׃"],[39,29,"וְֽ⁠אֶת־הָ⁠אַבְנֵ֞ט שֵׁ֣שׁ מָשְׁזָ֗ר וּ⁠תְכֵ֧לֶת וְ⁠אַרְגָּמָ֛ן וְ⁠תוֹלַ֥עַת שָׁנִ֖י מַעֲשֵׂ֣ה רֹקֵ֑ם כַּ⁠אֲשֶׁ֛ר צִוָּ֥ה יְהוָ֖ה אֶת־מֹשֶֽׁה׃ס","wĕֽ⁠ʼeţ-há⁠ʼabĕné֞t şé֣̌ş̌ máşĕ̌zá֗r ẇ⁠ţĕké֧leţ wĕ⁠ʼarĕgá̇má֛n wĕ⁠ţwòla֥ʻaţ şá̌ni֖y maʻàşé֣̂h ròqé֑m kȧ⁠ʼàşě֛r ẕiwá֥̇h yĕhwá֖h ʼeţ-mòşěֽh׃s"],[39,30,"וַֽ⁠יַּעֲשׂ֛וּ אֶת־צִ֥יץ נֵֽזֶר־הַ⁠קֹּ֖דֶשׁ זָהָ֣ב טָה֑וֹר וַ⁠יִּכְתְּב֣וּ עָלָ֗י⁠ו מִכְתַּב֙ פִּתּוּחֵ֣י חוֹתָ֔ם קֹ֖דֶשׁ לַ⁠יהוָֽה׃","wֽa⁠yȧʻàş֛̂ẇ ʼeţ-ẕi֥yẕ néֽzer-ha⁠qò֖̇deş̌ záhá֣b táh֑wòr wa⁠yi̇kĕţĕ̇b֣ẇ ʻálá֗y⁠w mikĕţȧb֙ pi̇ţ̇ẇẖé֣y ẖwòţá֔m qò֖deş̌ la⁠yhwáֽh׃"],[39,31,"וַ⁠יִּתְּנ֤וּ עָלָי⁠ו֙ פְּתִ֣יל תְּכֵ֔לֶת לָ⁠תֵ֥ת עַל־הַ⁠מִּצְנֶ֖פֶת מִ⁠לְ⁠מָ֑עְלָ⁠ה כַּ⁠אֲשֶׁ֛ר צִוָּ֥ה יְהוָ֖ה אֶת־מֹשֶֽׁה׃ס","wa⁠yi̇ţĕ̇n֤ẇ ʻáláy⁠w֙ pĕ̇ţi֣yl ţĕ̇ké֔leţ lá⁠ţé֥ţ ʻal-ha⁠mi̇ẕĕne֖peţ mi⁠lĕ⁠má֑ʻĕlá⁠h kȧ⁠ʼàşě֛r ẕiwá֥̇h yĕhwá֖h ʼeţ-mòşěֽh׃s"],[39,32,"וַ⁠תֵּ֕כֶל כָּל־עֲבֹדַ֕ת מִשְׁכַּ֖ן אֹ֣הֶל מוֹעֵ֑ד וַֽ⁠יַּעֲשׂוּ֙ בְּנֵ֣י יִשְׂרָאֵ֔ל כְּ֠⁠כֹל אֲשֶׁ֨ר צִוָּ֧ה יְהוָ֛ה אֶת־מֹשֶׁ֖ה כֵּ֥ן עָשֽׂוּ׃פ","wa⁠ţé̇֕kel ká̇l-ʻàbòda֕ţ mişĕ̌kȧ֖n ʼò֣hel mwòʻé֑d waֽ⁠yȧʻàş̂ẇ֙ bĕ̇né֣y yişĕ̂ráʼé֔l kĕ̇֠⁠kòl ʼàşě֨r ẕiwá֧̇h yĕhwá֛h ʼeţ-mòşě֖h ké֥̇n ʻáşֽ̂ẇ׃p"],[39,33,"וַ⁠יָּבִ֤יאוּ אֶת־הַ⁠מִּשְׁכָּן֙ אֶל־מֹשֶׁ֔ה אֶת־הָ⁠אֹ֖הֶל וְ⁠אֶת־כָּל־כֵּלָ֑י⁠ו קְרָסָ֣י⁠ו קְרָשָׁ֔י⁠ו בריחו וְ⁠עַמֻּדָ֥י⁠ו וַ⁠אֲדָנָֽי⁠ו׃","wa⁠yá̇bi֤yʼẇ ʼeţ-ha⁠mi̇şĕ̌ká̇n֙ ʼel-mòşě֔h ʼeţ-há⁠ʼò֖hel wĕ⁠ʼeţ-ká̇l-ké̇lá֑y⁠w qĕrásá֣y⁠w qĕráşá̌֔y⁠w bryẖw wĕ⁠ʻamu̇dá֥y⁠w wa⁠ʼàdánáֽy⁠w׃"],[39,34,"וְ⁠אֶת־מִכְסֵ֞ה עוֹרֹ֤ת הָֽ⁠אֵילִם֙ הַ⁠מְאָדָּמִ֔ים וְ⁠אֶת־מִכְסֵ֖ה עֹרֹ֣ת הַ⁠תְּחָשִׁ֑ים וְ⁠אֵ֖ת פָּרֹ֥כֶת הַ⁠מָּסָֽךְ׃","wĕ⁠ʼeţ-mikĕsé֞h ʻwòrò֤ţ háֽ⁠ʼéylim֙ ha⁠mĕʼádá̇mi֔ym wĕ⁠ʼeţ-mikĕsé֖h ʻòrò֣ţ ha⁠ţĕ̇ẖáşǐ֑ym wĕ⁠ʼé֖ţ pá̇rò֥keţ ha⁠má̇sáֽkĕ׃"],[39,35,"אֶת־אֲרֹ֥ן הָ⁠עֵדֻ֖ת וְ⁠אֶת־בַּדָּ֑י⁠ו וְ⁠אֵ֖ת הַ⁠כַּפֹּֽרֶת׃","ʼeţ-ʼàrò֥n há⁠ʻédu֖ţ wĕ⁠ʼeţ-bȧdá֑̇y⁠w wĕ⁠ʼé֖ţ ha⁠kȧpòֽ̇reţ׃"],[39,36,"אֶת־הַ⁠שֻּׁלְחָן֙ אֶת־כָּל־כֵּלָ֔י⁠ו וְ⁠אֵ֖ת לֶ֥חֶם הַ⁠פָּנִֽים׃","ʼeţ-ha⁠şu̇̌lĕẖán֙ ʼeţ-ká̇l-ké̇lá֔y⁠w wĕ⁠ʼé֖ţ le֥ẖem ha⁠pá̇niֽym׃"],[39,37,"אֶת־הַ⁠מְּנֹרָ֨ה הַ⁠טְּהֹרָ֜ה אֶת־נֵרֹתֶ֗י⁠הָ נֵרֹ֛ת הַ⁠מַּֽעֲרָכָ֖ה וְ⁠אֶת־כָּל־כֵּלֶ֑י⁠הָ וְ⁠אֵ֖ת שֶׁ֥מֶן הַ⁠מָּאֽוֹר׃","ʼeţ-ha⁠mĕ̇nòrá֨h ha⁠tĕ̇hòrá֜h ʼeţ-néròţe֗y⁠há nérò֛ţ ha⁠mȧֽʻàráká֖h wĕ⁠ʼeţ-ká̇l-ké̇le֑y⁠há wĕ⁠ʼé֖ţ şě֥men ha⁠má̇ʼֽwòr׃"],[39,38,"וְ⁠אֵת֙ מִזְבַּ֣ח הַ⁠זָּהָ֔ב וְ⁠אֵת֙ שֶׁ֣מֶן הַ⁠מִּשְׁחָ֔ה וְ⁠אֵ֖ת קְטֹ֣רֶת הַ⁠סַּמִּ֑ים וְ⁠אֵ֕ת מָסַ֖ךְ פֶּ֥תַח הָ⁠אֹֽהֶל׃","wĕ⁠ʼéţ֙ mizĕbȧ֣ẖ ha⁠zá̇há֔b wĕ⁠ʼéţ֙ şě֣men ha⁠mi̇şĕ̌ẖá֔h wĕ⁠ʼé֖ţ qĕtò֣reţ ha⁠sȧmi֑̇ym wĕ⁠ʼé֕ţ mása֖kĕ pė֥ţaẖ há⁠ʼòֽhel׃"],[39,39,"אֵ֣ת ׀ מִזְבַּ֣ח הַ⁠נְּחֹ֗שֶׁת וְ⁠אֶת־מִכְבַּ֤ר הַ⁠נְּחֹ֨שֶׁת֙ אֲשֶׁר־ל֔⁠וֹ אֶת־בַּדָּ֖י⁠ו וְ⁠אֶת־כָּל־כֵּלָ֑י⁠ו אֶת־הַ⁠כִּיֹּ֖ר וְ⁠אֶת־כַּנּֽ⁠וֹ׃","ʼé֣ţ ׀ mizĕbȧ֣ẖ ha⁠nĕ̇ẖò֗şěţ wĕ⁠ʼeţ-mikĕbȧ֤r ha⁠nĕ̇ẖò֨şěţ֙ ʼàşěr-l֔⁠wò ʼeţ-bȧdá֖̇y⁠w wĕ⁠ʼeţ-ká̇l-ké̇lá֑y⁠w ʼeţ-ha⁠ki̇yò֖̇r wĕ⁠ʼeţ-kȧṅֽ⁠wò׃"],[39,40,"אֵת֩ קַלְעֵ֨י הֶ⁠חָצֵ֜ר אֶת־עַמֻּדֶ֣י⁠הָ וְ⁠אֶת־אֲדָנֶ֗י⁠הָ וְ⁠אֶת־הַ⁠מָּסָךְ֙ לְ⁠שַׁ֣עַר הֶֽ⁠חָצֵ֔ר אֶת־מֵיתָרָ֖י⁠ו וִ⁠יתֵדֹתֶ֑י⁠הָ וְ⁠אֵ֗ת כָּל־כְּלֵ֛י עֲבֹדַ֥ת הַ⁠מִּשְׁכָּ֖ן לְ⁠אֹ֥הֶל מוֹעֵֽד׃","ʼéţ֩ qalĕʻé֨y he⁠ẖáẕé֜r ʼeţ-ʻamu̇de֣y⁠há wĕ⁠ʼeţ-ʼàdáne֗y⁠há wĕ⁠ʼeţ-ha⁠má̇sákĕ֙ lĕ⁠şǎ֣ʻar heֽ⁠ẖáẕé֔r ʼeţ-méyţárá֖y⁠w wi⁠yţédòţe֑y⁠há wĕ⁠ʼé֗ţ ká̇l-kĕ̇lé֛y ʻàbòda֥ţ ha⁠mi̇şĕ̌ká֖̇n lĕ⁠ʼò֥hel mwòʻéֽd׃"],[39,41,"אֶת־בִּגְדֵ֥י הַ⁠שְּׂרָ֖ד לְ⁠שָׁרֵ֣ת בַּ⁠קֹּ֑דֶשׁ אֶת־בִּגְדֵ֤י הַ⁠קֹּ֨דֶשׁ֙ לְ⁠אַהֲרֹ֣ן הַ⁠כֹּהֵ֔ן וְ⁠אֶת־בִּגְדֵ֥י בָנָ֖י⁠ו לְ⁠כַהֵֽן׃","ʼeţ-bi̇gĕdé֥y ha⁠şĕ̇̂rá֖d lĕ⁠şá̌ré֣ţ bȧ⁠qò֑̇deş̌ ʼeţ-bi̇gĕdé֤y ha⁠qò̇֨deş̌֙ lĕ⁠ʼahàrò֣n ha⁠kò̇hé֔n wĕ⁠ʼeţ-bi̇gĕdé֥y báná֖y⁠w lĕ⁠kahéֽn׃"],[39,42,"כְּ⁠כֹ֛ל אֲשֶׁר־צִוָּ֥ה יְהוָ֖ה אֶת־מֹשֶׁ֑ה כֵּ֤ן עָשׂוּ֙ בְּנֵ֣י יִשְׂרָאֵ֔ל אֵ֖ת כָּל־הָ⁠עֲבֹדָֽה׃","kĕ̇⁠kò֛l ʼàşěr-ẕiwá֥̇h yĕhwá֖h ʼeţ-mòşě֑h ké֤̇n ʻáş̂ẇ֙ bĕ̇né֣y yişĕ̂ráʼé֔l ʼé֖ţ ká̇l-há⁠ʻàbòdáֽh׃"],[39,43,"וַ⁠יַּ֨רְא מֹשֶׁ֜ה אֶת־כָּל־הַ⁠מְּלָאכָ֗ה וְ⁠הִנֵּה֙ עָשׂ֣וּ אֹתָ֔⁠הּ כַּ⁠אֲשֶׁ֛ר צִוָּ֥ה יְהוָ֖ה כֵּ֣ן עָשׂ֑וּ וַ⁠יְבָ֥רֶךְ אֹתָ֖⁠ם מֹשֶֽׁה׃פ","wa⁠yȧ֨rĕʼ mòşě֜h ʼeţ-ká̇l-ha⁠mĕ̇láʼká֗h wĕ⁠hiné̇h֙ ʻáş֣̂ẇ ʼòţá֔⁠ḣ kȧ⁠ʼàşě֛r ẕiwá֥̇h yĕhwá֖h ké֣̇n ʻáş֑̂ẇ wa⁠yĕbá֥rekĕ ʼòţá֖⁠m mòşěֽh׃p"],[40,1,"וַ⁠יְדַבֵּ֥ר יְהוָ֖ה אֶל־מֹשֶׁ֥ה לֵּ⁠אמֹֽר׃","wa⁠yĕdabé֥̇r yĕhwá֖h ʼel-mòşě֥h lé̇⁠ʼmòֽr׃"],[40,2,"בְּ⁠יוֹם־הַ⁠חֹ֥דֶשׁ הָ⁠רִאשׁ֖וֹן בְּ⁠אֶחָ֣ד לַ⁠חֹ֑דֶשׁ תָּקִ֕ים אֶת־מִשְׁכַּ֖ן אֹ֥הֶל מוֹעֵֽד׃","bĕ̇⁠ywòm-ha⁠ẖò֥deş̌ há⁠riʼş֖̌wòn bĕ̇⁠ʼeẖá֣d la⁠ẖò֑deş̌ ţá̇qi֕ym ʼeţ-mişĕ̌kȧ֖n ʼò֥hel mwòʻéֽd׃"],[40,3,"וְ⁠שַׂמְתָּ֣ שָׁ֔ם אֵ֖ת אֲר֣וֹן הָ⁠עֵד֑וּת וְ⁠סַכֹּתָ֥ עַל־הָ⁠אָרֹ֖ן אֶת־הַ⁠פָּרֹֽכֶת׃","wĕ⁠şâmĕţá֣̇ şá̌֔m ʼé֖ţ ʼàr֣wòn há⁠ʻéd֑ẇţ wĕ⁠sakò̇ţá֥ ʻal-há⁠ʼárò֖n ʼeţ-ha⁠pá̇ròֽkeţ׃"],[40,4,"וְ⁠הֵבֵאתָ֙ אֶת־הַ⁠שֻּׁלְחָ֔ן וְ⁠עָרַכְתָּ֖ אֶת־עֶרְכּ֑⁠וֹ וְ⁠הֵבֵאתָ֙ אֶת־הַ⁠מְּנֹרָ֔ה וְ⁠הַעֲלֵיתָ֖ אֶת־נֵרֹתֶֽי⁠הָ׃","wĕ⁠hébéʼţá֙ ʼeţ-ha⁠şu̇̌lĕẖá֔n wĕ⁠ʻárakĕţá֖̇ ʼeţ-ʻerĕk֑̇⁠wò wĕ⁠hébéʼţá֙ ʼeţ-ha⁠mĕ̇nòrá֔h wĕ⁠haʻàléyţá֖ ʼeţ-néròţeֽy⁠há׃"],[40,5,"וְ⁠נָתַתָּ֞ה אֶת־מִזְבַּ֤ח הַ⁠זָּהָב֙ לִ⁠קְטֹ֔רֶת לִ⁠פְנֵ֖י אֲר֣וֹן הָ⁠עֵדֻ֑ת וְ⁠שַׂמְתָּ֛ אֶת־מָסַ֥ךְ הַ⁠פֶּ֖תַח לַ⁠מִּשְׁכָּֽן׃","wĕ⁠náţaţá̇֞h ʼeţ-mizĕbȧ֤ẖ ha⁠zá̇háb֙ li⁠qĕtò֔reţ li⁠pĕné֖y ʼàr֣wòn há⁠ʻédu֑ţ wĕ⁠şâmĕţá֛̇ ʼeţ-mása֥kĕ ha⁠pė֖ţaẖ la⁠mi̇şĕ̌káֽ̇n׃"],[40,6,"וְ⁠נָ֣תַתָּ֔ה אֵ֖ת מִזְבַּ֣ח הָ⁠עֹלָ֑ה לִ⁠פְנֵ֕י פֶּ֖תַח מִשְׁכַּ֥ן אֹֽהֶל־מוֹעֵֽד׃","wĕ⁠ná֣ţaţá̇֔h ʼé֖ţ mizĕbȧ֣ẖ há⁠ʻòlá֑h li⁠pĕné֕y pė֖ţaẖ mişĕ̌kȧ֥n ʼòֽhel-mwòʻéֽd׃"],[40,7,"וְ⁠נָֽתַתָּ֙ אֶת־הַ⁠כִּיֹּ֔ר בֵּֽין־אֹ֥הֶל מוֹעֵ֖ד וּ⁠בֵ֣ין הַ⁠מִּזְבֵּ֑חַ וְ⁠נָתַתָּ֥ שָׁ֖ם מָֽיִם׃","wĕ⁠náֽţaţá̇֙ ʼeţ-ha⁠ki̇yò̇֔r béֽ̇yn-ʼò֥hel mwòʻé֖d ẇ⁠bé֣yn ha⁠mi̇zĕbé֑̇ẖa wĕ⁠náţaţá֥̇ şá֖̌m máֽyim׃"],[40,8,"וְ⁠שַׂמְתָּ֥ אֶת־הֶ⁠חָצֵ֖ר סָבִ֑יב וְ⁠נָ֣תַתָּ֔ אֶת־מָסַ֖ךְ שַׁ֥עַר הֶ⁠חָצֵֽר׃","wĕ⁠şâmĕţá֥̇ ʼeţ-he⁠ẖáẕé֖r sábi֑yb wĕ⁠ná֣ţaţá̇֔ ʼeţ-mása֖kĕ şǎ֥ʻar he⁠ẖáẕéֽr׃"],[40,9,"וְ⁠לָקַחְתָּ֙ אֶת־שֶׁ֣מֶן הַ⁠מִּשְׁחָ֔ה וּ⁠מָשַׁחְתָּ֥ אֶת־הַ⁠מִּשְׁכָּ֖ן וְ⁠אֶת־כָּל־אֲשֶׁר־בּ֑⁠וֹ וְ⁠קִדַּשְׁתָּ֥ אֹת֛⁠וֹ וְ⁠אֶת־כָּל־כֵּלָ֖י⁠ו וְ⁠הָ֥יָה קֹֽדֶשׁ׃","wĕ⁠láqaẖĕţá̇֙ ʼeţ-şě֣men ha⁠mi̇şĕ̌ẖá֔h ẇ⁠máşǎẖĕţá֥̇ ʼeţ-ha⁠mi̇şĕ̌ká֖̇n wĕ⁠ʼeţ-ká̇l-ʼàşěr-ḃ֑⁠wò wĕ⁠qidȧşĕ̌ţá֥̇ ʼòţ֛⁠wò wĕ⁠ʼeţ-ká̇l-ké̇lá֖y⁠w wĕ⁠há֥yáh qòֽdeş̌׃"],[40,10,"וּ⁠מָשַׁחְתָּ֛ אֶת־מִזְבַּ֥ח הָ⁠עֹלָ֖ה וְ⁠אֶת־כָּל־כֵּלָ֑י⁠ו וְ⁠קִדַּשְׁתָּ֙ אֶת־הַ⁠מִּזְבֵּ֔חַ וְ⁠הָיָ֥ה הַ⁠מִּזְבֵּ֖חַ קֹ֥דֶשׁ קָֽדָשִֽׁים׃","ẇ⁠máşǎẖĕţá֛̇ ʼeţ-mizĕbȧ֥ẖ há⁠ʻòlá֖h wĕ⁠ʼeţ-ká̇l-ké̇lá֑y⁠w wĕ⁠qidȧşĕ̌ţá̇֙ ʼeţ-ha⁠mi̇zĕbé̇֔ẖa wĕ⁠háyá֥h ha⁠mi̇zĕbé֖̇ẖa qò֥deş̌ qֽádáşǐֽym׃"],[40,11,"וּ⁠מָשַׁחְתָּ֥ אֶת־הַ⁠כִּיֹּ֖ר וְ⁠אֶת־כַּנּ֑⁠וֹ וְ⁠קִדַּשְׁתָּ֖ אֹתֽ⁠וֹ׃","ẇ⁠máşǎẖĕţá֥̇ ʼeţ-ha⁠ki̇yò֖̇r wĕ⁠ʼeţ-kȧṅ֑⁠wò wĕ⁠qidȧşĕ̌ţá֖̇ ʼòţֽ⁠wò׃"],[40,12,"וְ⁠הִקְרַבְתָּ֤ אֶֽת־אַהֲרֹן֙ וְ⁠אֶת־בָּנָ֔י⁠ו אֶל־פֶּ֖תַח אֹ֣הֶל מוֹעֵ֑ד וְ⁠רָחַצְתָּ֥ אֹתָ֖⁠ם בַּ⁠מָּֽיִם׃","wĕ⁠hiqĕrabĕţá֤̇ ʼeֽţ-ʼahàròn֙ wĕ⁠ʼeţ-bá̇ná֔y⁠w ʼel-pė֖ţaẖ ʼò֣hel mwòʻé֑d wĕ⁠ráẖaẕĕţá֥̇ ʼòţá֖⁠m bȧ⁠máֽ̇yim׃"],[40,13,"וְ⁠הִלְבַּשְׁתָּ֙ אֶֽת־אַהֲרֹ֔ן אֵ֖ת בִּגְדֵ֣י הַ⁠קֹּ֑דֶשׁ וּ⁠מָשַׁחְתָּ֥ אֹת֛⁠וֹ וְ⁠קִדַּשְׁתָּ֥ אֹת֖⁠וֹ וְ⁠כִהֵ֥ן לִֽ⁠י׃","wĕ⁠hilĕbȧşĕ̌ţá̇֙ ʼeֽţ-ʼahàrò֔n ʼé֖ţ bi̇gĕdé֣y ha⁠qò֑̇deş̌ ẇ⁠máşǎẖĕţá֥̇ ʼòţ֛⁠wò wĕ⁠qidȧşĕ̌ţá֥̇ ʼòţ֖⁠wò wĕ⁠kihé֥n liֽ⁠y׃"],[40,14,"וְ⁠אֶת־בָּנָ֖י⁠ו תַּקְרִ֑יב וְ⁠הִלְבַּשְׁתָּ֥ אֹתָ֖⁠ם כֻּתֳּנֹֽת׃","wĕ⁠ʼeţ-bá̇ná֖y⁠w ţȧqĕri֑yb wĕ⁠hilĕbȧşĕ̌ţá֥̇ ʼòţá֖⁠m ku̇ţȯnòֽţ׃"],[40,15,"וּ⁠מָשַׁחְתָּ֣ אֹתָ֗⁠ם כַּ⁠אֲשֶׁ֤ר מָשַׁ֨חְתָּ֙ אֶת־אֲבִי⁠הֶ֔ם וְ⁠כִהֲנ֖וּ לִ֑⁠י וְ֠⁠הָיְתָה לִ⁠הְיֹ֨ת לָ⁠הֶ֧ם מָשְׁחָתָ֛⁠ם לִ⁠כְהֻנַּ֥ת עוֹלָ֖ם לְ⁠דֹרֹתָֽ⁠ם׃","ẇ⁠máşǎẖĕţá֣̇ ʼòţá֗⁠m kȧ⁠ʼàşě֤r máşǎ֨ẖĕţá̇֙ ʼeţ-ʼàbiy⁠he֔m wĕ⁠kihàn֖ẇ li֑⁠y wĕ֠⁠háyĕţáh li⁠hĕyò֨ţ lá⁠he֧m máşĕ̌ẖáţá֛⁠m li⁠kĕhunȧ֥ţ ʻwòlá֖m lĕ⁠dòròţáֽ⁠m׃"],[40,16,"וַ⁠יַּ֖עַשׂ מֹשֶׁ֑ה כְּ֠⁠כֹל אֲשֶׁ֨ר צִוָּ֧ה יְהוָ֛ה אֹת֖⁠וֹ כֵּ֥ן עָשָֽׂה׃ס","wa⁠yȧ֖ʻaş̂ mòşě֑h kĕ̇֠⁠kòl ʼàşě֨r ẕiwá֧̇h yĕhwá֛h ʼòţ֖⁠wò ké֥̇n ʻáşáֽ̂h׃s"],[40,17,"וַ⁠יְהִ֞י בַּ⁠חֹ֧דֶשׁ הָ⁠רִאשׁ֛וֹן בַּ⁠שָּׁנָ֥ה הַ⁠שֵּׁנִ֖ית בְּ⁠אֶחָ֣ד לַ⁠חֹ֑דֶשׁ הוּקַ֖ם הַ⁠מִּשְׁכָּֽן׃","wa⁠yĕhi֞y bȧ⁠ẖò֧deş̌ há⁠riʼş֛̌wòn bȧ⁠şá̇̌ná֥h ha⁠şé̇̌ni֖yţ bĕ̇⁠ʼeẖá֣d la⁠ẖò֑deş̌ hẇqa֖m ha⁠mi̇şĕ̌káֽ̇n׃"],[40,18,"וַ⁠יָּ֨קֶם מֹשֶׁ֜ה אֶת־הַ⁠מִּשְׁכָּ֗ן וַ⁠יִּתֵּן֙ אֶת־אֲדָנָ֔י⁠ו וַ⁠יָּ֨שֶׂם֙ אֶת־קְרָשָׁ֔י⁠ו וַ⁠יִּתֵּ֖ן אֶת־בְּרִיחָ֑י⁠ו וַ⁠יָּ֖קֶם אֶת־עַמּוּדָֽי⁠ו׃","wa⁠yá̇֨qem mòşě֜h ʼeţ-ha⁠mi̇şĕ̌ká̇֗n wa⁠yi̇ţé̇n֙ ʼeţ-ʼàdáná֔y⁠w wa⁠yá̇֨şêm֙ ʼeţ-qĕráşá̌֔y⁠w wa⁠yi̇ţé֖̇n ʼeţ-bĕ̇riyẖá֑y⁠w wa⁠yá֖̇qem ʼeţ-ʻaṁẇdáֽy⁠w׃"],[40,19,"וַ⁠יִּפְרֹ֤שׂ אֶת־הָ⁠אֹ֨הֶל֙ עַל־הַ⁠מִּשְׁכָּ֔ן וַ⁠יָּ֜שֶׂם אֶת־מִכְסֵ֥ה הָ⁠אֹ֛הֶל עָלָ֖י⁠ו מִ⁠לְ⁠מָ֑עְלָ⁠ה כַּ⁠אֲשֶׁ֛ר צִוָּ֥ה יְהוָ֖ה אֶת־מֹשֶֽׁה׃ס","wa⁠yi̇pĕrò֤ş̂ ʼeţ-há⁠ʼò֨hel֙ ʻal-ha⁠mi̇şĕ̌ká̇֔n wa⁠yá̇֜şêm ʼeţ-mikĕsé֥h há⁠ʼò֛hel ʻálá֖y⁠w mi⁠lĕ⁠má֑ʻĕlá⁠h kȧ⁠ʼàşě֛r ẕiwá֥̇h yĕhwá֖h ʼeţ-mòşěֽh׃s"],[40,20,"וַ⁠יִּקַּ֞ח וַ⁠יִּתֵּ֤ן אֶת־הָ⁠עֵדֻת֙ אֶל־הָ֣⁠אָרֹ֔ן וַ⁠יָּ֥שֶׂם אֶת־הַ⁠בַּדִּ֖ים עַל־הָ⁠אָרֹ֑ן וַ⁠יִּתֵּ֧ן אֶת־הַ⁠כַּפֹּ֛רֶת עַל־הָ⁠אָרֹ֖ן מִ⁠לְ⁠מָֽעְלָ⁠ה׃","wa⁠yi̇qȧ֞ẖ wa⁠yi̇ţé֤̇n ʼeţ-há⁠ʻéduţ֙ ʼel-há֣⁠ʼárò֔n wa⁠yá֥̇şêm ʼeţ-ha⁠bȧdi֖̇ym ʻal-há⁠ʼárò֑n wa⁠yi̇ţé֧̇n ʼeţ-ha⁠kȧpò֛̇reţ ʻal-há⁠ʼárò֖n mi⁠lĕ⁠máֽʻĕlá⁠h׃"],[40,21,"וַ⁠יָּבֵ֣א אֶת־הָ⁠אָרֹן֮ אֶל־הַ⁠מִּשְׁכָּן֒ וַ⁠יָּ֗שֶׂם אֵ֚ת פָּרֹ֣כֶת הַ⁠מָּסָ֔ךְ וַ⁠יָּ֕סֶךְ עַ֖ל אֲר֣וֹן הָ⁠עֵד֑וּת כַּ⁠אֲשֶׁ֛ר צִוָּ֥ה יְהוָ֖ה אֶת־מֹשֶֽׁה׃ס","wa⁠yá̇bé֣ʼ ʼeţ-há⁠ʼáròn֮ ʼel-ha⁠mi̇şĕ̌ká̇n֒ wa⁠yá̇֗şêm ʼé֚ţ pá̇rò֣keţ ha⁠má̇sá֔kĕ wa⁠yá̇֕sekĕ ʻa֖l ʼàr֣wòn há⁠ʻéd֑ẇţ kȧ⁠ʼàşě֛r ẕiwá֥̇h yĕhwá֖h ʼeţ-mòşěֽh׃s"],[40,22,"וַ⁠יִּתֵּ֤ן אֶת־הַ⁠שֻּׁלְחָן֙ בְּ⁠אֹ֣הֶל מוֹעֵ֔ד עַ֛ל יֶ֥רֶךְ הַ⁠מִּשְׁכָּ֖ן צָפֹ֑נָ⁠ה מִ⁠ח֖וּץ לַ⁠פָּרֹֽכֶת׃","wa⁠yi̇ţé֤̇n ʼeţ-ha⁠şu̇̌lĕẖán֙ bĕ̇⁠ʼò֣hel mwòʻé֔d ʻa֛l ye֥rekĕ ha⁠mi̇şĕ̌ká֖̇n ẕápò֑ná⁠h mi⁠ẖ֖ẇẕ la⁠pá̇ròֽkeţ׃"],[40,23,"וַ⁠יַּעֲרֹ֥ךְ עָלָ֛י⁠ו עֵ֥רֶךְ לֶ֖חֶם לִ⁠פְנֵ֣י יְהוָ֑ה כַּ⁠אֲשֶׁ֛ר צִוָּ֥ה יְהוָ֖ה אֶת־מֹשֶֽׁה׃ס","wa⁠yȧʻàrò֥kĕ ʻálá֛y⁠w ʻé֥rekĕ le֖ẖem li⁠pĕné֣y yĕhwá֑h kȧ⁠ʼàşě֛r ẕiwá֥̇h yĕhwá֖h ʼeţ-mòşěֽh׃s"],[40,24,"וַ⁠יָּ֤שֶׂם אֶת־הַ⁠מְּנֹרָה֙ בְּ⁠אֹ֣הֶל מוֹעֵ֔ד נֹ֖כַח הַ⁠שֻּׁלְחָ֑ן עַ֛ל יֶ֥רֶךְ הַ⁠מִּשְׁכָּ֖ן נֶֽגְבָּ⁠ה׃","wa⁠yá֤̇şêm ʼeţ-ha⁠mĕ̇nòráh֙ bĕ̇⁠ʼò֣hel mwòʻé֔d nò֖kaẖ ha⁠şu̇̌lĕẖá֑n ʻa֛l ye֥rekĕ ha⁠mi̇şĕ̌ká֖̇n neֽgĕbá̇⁠h׃"],[40,25,"וַ⁠יַּ֥עַל הַ⁠נֵּרֹ֖ת לִ⁠פְנֵ֣י יְהוָ֑ה כַּ⁠אֲשֶׁ֛ר צִוָּ֥ה יְהוָ֖ה אֶת־מֹשֶֽׁה׃ס","wa⁠yȧ֥ʻal ha⁠né̇rò֖ţ li⁠pĕné֣y yĕhwá֑h kȧ⁠ʼàşě֛r ẕiwá֥̇h yĕhwá֖h ʼeţ-mòşěֽh׃s"],[40,26,"וַ⁠יָּ֛שֶׂם אֶת־מִזְבַּ֥ח הַ⁠זָּהָ֖ב בְּ⁠אֹ֣הֶל מוֹעֵ֑ד לִ⁠פְנֵ֖י הַ⁠פָּרֹֽכֶת׃","wa⁠yá֛̇şêm ʼeţ-mizĕbȧ֥ẖ ha⁠zá̇há֖b bĕ̇⁠ʼò֣hel mwòʻé֑d li⁠pĕné֖y ha⁠pá̇ròֽkeţ׃"],[40,27,"וַ⁠יַּקְטֵ֥ר עָלָ֖י⁠ו קְטֹ֣רֶת סַמִּ֑ים כַּ⁠אֲשֶׁ֛ר צִוָּ֥ה יְהוָ֖ה אֶת־מֹשֶֽׁה׃פ","wa⁠yȧqĕté֥r ʻálá֖y⁠w qĕtò֣reţ sami֑̇ym kȧ⁠ʼàşě֛r ẕiwá֥̇h yĕhwá֖h ʼeţ-mòşěֽh׃p"],[40,28,"וַ⁠יָּ֛שֶׂם אֶת־מָסַ֥ךְ הַ⁠פֶּ֖תַח לַ⁠מִּשְׁכָּֽן׃","wa⁠yá֛̇şêm ʼeţ-mása֥kĕ ha⁠pė֖ţaẖ la⁠mi̇şĕ̌káֽ̇n׃"],[40,29,"וְ⁠אֵת֙ מִזְבַּ֣ח הָ⁠עֹלָ֔ה שָׂ֕ם פֶּ֖תַח מִשְׁכַּ֣ן אֹֽהֶל־מוֹעֵ֑ד וַ⁠יַּ֣עַל עָלָ֗י⁠ו אֶת־הָ⁠עֹלָה֙ וְ⁠אֶת־הַ⁠מִּנְחָ֔ה כַּ⁠אֲשֶׁ֛ר צִוָּ֥ה יְהוָ֖ה אֶת־מֹשֶֽׁה׃ס","wĕ⁠ʼéţ֙ mizĕbȧ֣ẖ há⁠ʻòlá֔h şá̂֕m pė֖ţaẖ mişĕ̌kȧ֣n ʼòֽhel-mwòʻé֑d wa⁠yȧ֣ʻal ʻálá֗y⁠w ʼeţ-há⁠ʻòláh֙ wĕ⁠ʼeţ-ha⁠mi̇nĕẖá֔h kȧ⁠ʼàşě֛r ẕiwá֥̇h yĕhwá֖h ʼeţ-mòşěֽh׃s"],[40,30,"וַ⁠יָּ֨שֶׂם֙ אֶת־הַ⁠כִּיֹּ֔ר בֵּֽין־אֹ֥הֶל מוֹעֵ֖ד וּ⁠בֵ֣ין הַ⁠מִּזְבֵּ֑חַ וַ⁠יִּתֵּ֥ן שָׁ֛מָּ⁠ה מַ֖יִם לְ⁠רָחְצָֽה׃","wa⁠yá̇֨şêm֙ ʼeţ-ha⁠ki̇yò̇֔r béֽ̇yn-ʼò֥hel mwòʻé֖d ẇ⁠bé֣yn ha⁠mi̇zĕbé֑̇ẖa wa⁠yi̇ţé֥̇n şá֛̌má̇⁠h ma֖yim lĕ⁠ráẖĕẕáֽh׃"],[40,31,"וְ⁠רָחֲצ֣וּ מִמֶּ֔⁠נּוּ מֹשֶׁ֖ה וְ⁠אַהֲרֹ֣ן וּ⁠בָנָ֑י⁠ו אֶת־יְדֵי⁠הֶ֖ם וְ⁠אֶת־רַגְלֵי⁠הֶֽם׃","wĕ⁠ráẖàẕ֣ẇ mimė֔⁠ṅẇ mòşě֖h wĕ⁠ʼahàrò֣n ẇ⁠báná֑y⁠w ʼeţ-yĕdéy⁠he֖m wĕ⁠ʼeţ-ragĕléy⁠heֽm׃"],[40,32,"בְּ⁠בֹאָ֞⁠ם אֶל־אֹ֣הֶל מוֹעֵ֗ד וּ⁠בְ⁠קָרְבָתָ֛⁠ם אֶל־הַ⁠מִּזְבֵּ֖חַ יִרְחָ֑צוּ כַּ⁠אֲשֶׁ֛ר צִוָּ֥ה יְהוָ֖ה אֶת־מֹשֶֽׁה׃ס","bĕ̇⁠bòʼá֞⁠m ʼel-ʼò֣hel mwòʻé֗d ẇ⁠bĕ⁠qárĕbáţá֛⁠m ʼel-ha⁠mi̇zĕbé֖̇ẖa yirĕẖá֑ẕẇ kȧ⁠ʼàşě֛r ẕiwá֥̇h yĕhwá֖h ʼeţ-mòşěֽh׃s"],[40,33,"וַ⁠יָּ֣קֶם אֶת־הֶ⁠חָצֵ֗ר סָבִיב֙ לַ⁠מִּשְׁכָּ֣ן וְ⁠לַ⁠מִּזְבֵּ֔חַ וַ⁠יִּתֵּ֕ן אֶת־מָסַ֖ךְ שַׁ֣עַר הֶ⁠חָצֵ֑ר וַ⁠יְכַ֥ל מֹשֶׁ֖ה אֶת־הַ⁠מְּלָאכָֽה׃פ","wa⁠yá֣̇qem ʼeţ-he⁠ẖáẕé֗r sábiyb֙ la⁠mi̇şĕ̌ká֣̇n wĕ⁠la⁠mi̇zĕbé̇֔ẖa wa⁠yi̇ţé̇֕n ʼeţ-mása֖kĕ şǎ֣ʻar he⁠ẖáẕé֑r wa⁠yĕka֥l mòşě֖h ʼeţ-ha⁠mĕ̇láʼkáֽh׃p"],[40,34,"וַ⁠יְכַ֥ס הֶ⁠עָנָ֖ן אֶת־אֹ֣הֶל מוֹעֵ֑ד וּ⁠כְב֣וֹד יְהוָ֔ה מָלֵ֖א אֶת־הַ⁠מִּשְׁכָּֽן׃","wa⁠yĕka֥s he⁠ʻáná֖n ʼeţ-ʼò֣hel mwòʻé֑d ẇ⁠kĕb֣wòd yĕhwá֔h málé֖ʼ ʼeţ-ha⁠mi̇şĕ̌káֽ̇n׃"],[40,35,"וְ⁠לֹא־יָכֹ֣ל מֹשֶׁ֗ה לָ⁠בוֹא֙ אֶל־אֹ֣הֶל מוֹעֵ֔ד כִּֽי־שָׁכַ֥ן עָלָ֖י⁠ו הֶ⁠עָנָ֑ן וּ⁠כְב֣וֹד יְהוָ֔ה מָלֵ֖א אֶת־הַ⁠מִּשְׁכָּֽן׃","wĕ⁠lòʼ-yákò֣l mòşě֗h lá⁠bwòʼ֙ ʼel-ʼò֣hel mwòʻé֔d kiֽ̇y-şá̌ka֥n ʻálá֖y⁠w he⁠ʻáná֑n ẇ⁠kĕb֣wòd yĕhwá֔h málé֖ʼ ʼeţ-ha⁠mi̇şĕ̌káֽ̇n׃"],[40,36,"וּ⁠בְ⁠הֵעָל֤וֹת הֶֽ⁠עָנָן֙ מֵ⁠עַ֣ל הַ⁠מִּשְׁכָּ֔ן יִסְע֖וּ בְּנֵ֣י יִשְׂרָאֵ֑ל בְּ⁠כֹ֖ל מַסְעֵי⁠הֶֽם׃","ẇ⁠bĕ⁠héʻál֤wòţ heֽ⁠ʻánán֙ mé⁠ʻa֣l ha⁠mi̇şĕ̌ká̇֔n yisĕʻ֖ẇ bĕ̇né֣y yişĕ̂ráʼé֑l bĕ̇⁠kò֖l masĕʻéy⁠heֽm׃"],[40,37,"וְ⁠אִם־לֹ֥א יֵעָלֶ֖ה הֶ⁠עָנָ֑ן וְ⁠לֹ֣א יִסְע֔וּ עַד־י֖וֹם הֵעָלֹתֽ⁠וֹ׃","wĕ⁠ʼim-lò֥ʼ yéʻále֖h he⁠ʻáná֑n wĕ⁠lò֣ʼ yisĕʻ֔ẇ ʻad-y֖wòm héʻálòţֽ⁠wò׃"],[40,38,"כִּי֩ עֲנַ֨ן יְהוָ֤ה עַֽל־הַ⁠מִּשְׁכָּן֙ יוֹמָ֔ם וְ⁠אֵ֕שׁ תִּהְיֶ֥ה לַ֖יְלָה בּ֑⁠וֹ לְ⁠עֵינֵ֥י כָל־בֵּֽית־יִשְׂרָאֵ֖ל בְּ⁠כָל־מַסְעֵי⁠הֶֽם׃","ki̇y֩ ʻàna֨n yĕhwá֤h ʻaֽl-ha⁠mi̇şĕ̌ká̇n֙ ywòmá֔m wĕ⁠ʼé֕ş̌ ţi̇hĕye֥h la֖yĕláh ḃ֑⁠wò lĕ⁠ʻéyné֥y kál-béֽ̇yţ-yişĕ̂ráʼé֖l bĕ̇⁠kál-masĕʻéy⁠heֽm׃"]]}};